local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:96393"] = {n="Old Ironforge Incursion",s="在铁炉堡地下，Earthseer Farsen 派你前往领主大厅，完成调查的最后一环。在那里，你将直面黑铁的威胁，并向国王麦格尼·铜须复命。",h="在铁炉堡地下，Earthseer Farsen 派你前往领主大厅，完成调查的最后一环。在那里，你将直面黑铁的威胁，并向国王麦格尼·铜须复命。",kw={"黑铁","挽歌之锤","法尔森","入侵","铁炉堡","卡拉诺斯","麦格尼","领主"},ang={["faction:Alliance"]="身为联盟的一员，你协助阻止了一场入侵，否则你的阵营在东部王国的主要据点就可能遭受毁灭性的突袭。",["race:Dwarf"]="身为矮人，你知道黑铁渗透者已侵入王座厅下方被遗忘的地窟，侵犯了你祖先的堡垒。"},sec={{t="突入地窟",b="地下地图揭示了黑铁的动向，Earthseer Farsen 也查明了这次入侵的幕后主使。领主大厅的入口位于 Old Ironforge 古老石厅的深处。上层城市忙于处理地表事务之时，黑铁部队悄然潜入了王国地下沉寂已久的洞穴。"},{t="Durgen Dirgehammer",b="Earthseer Farsen 译出了缴获的黑铁文件，并指出了指挥官的名字：Durgen Dirgehammer。在下层地窟深处，Durgen 威胁着铜须山中之国的腹地。找到他，将他击杀，再把他的首级带给上方的国王麦格尼·铜须。"},{t="觐见国王",b="Durgen Dirgehammer 的首级向国王麦格尼·铜须证实了潜藏在这座古城根基之下的黑铁威胁。你带来了胜利的凭证，也捎来了麦格尼的老友 Farsen 的亲切问候。调查就此结束，麦格尼也已知晓地下潜伏的威胁。"}},faq={{q="旧铁炉堡入侵 是什么？",a="大地先知法尔森 派你进入 旧铁炉堡 下方的领主大厅，迎战黑铁指挥官 杜尔根·挽歌之锤。这是调查丹莫罗地下黑铁活动的最后阶段。",al={"旧铁炉堡入侵 任务","杜尔根·挽歌之锤 任务"}},{q="这个任务发生在哪里？",a="你将进入领主大厅，那是位于 旧铁炉堡 和这座山中都城下方基岩深处的一座古老厅室。",al={"领主大厅在哪里","领主大厅位置"}},{q="杜尔根·挽歌之锤 是谁？",a="达根·挽歌之锤 指挥黑铁入侵了 旧铁炉堡 下方的领主大厅。大地先知法尔森 从找回的黑铁文件中得知了他的名字。",al={"挽歌之锤 是谁","杜尔根·挽歌之锤"}},{q="任务由谁发布，又向谁交付？",a="你找回 地下地图 后，大地先知法尔森 会派你前往铁炉堡，向国王麦格尼·铜须复命。",al={"旧铁炉堡入侵 任务发布者","旧铁炉堡入侵 向谁交付"}},{q="如何开启通往这个任务的任务链？",a="从 丹莫罗的访客 开始，在丹莫罗卡拉诺斯外的贝尔丁·钢架处接取。",al={"如何开启领主大厅任务","丹莫罗的访客 起始"}},{q="大地先知法尔森 与 麦格尼国王 有什么关系？",a="大地先知法尔森 自认是国王麦格尼·铜须的老朋友。他请你在王座厅献上 达根·挽歌之锤 的首级时，代他致以亲切的问候。",al={"法尔森 与 麦格尼","大地先知法森 背景故事"}}},fx={bdae81a8={q="大地先知法尔森为什么要杀死杜尔根·挽歌之锤？",a="法尔森发现了山腹中的敌军动向，并破译了命令，得知杜尔根·挽歌之锤正是率军入侵旧铁炉堡的指挥官。黑铁盘踞在古老的领主大厅，直接从地下威胁着矮人的都城。法尔森派你斩杀他们的首领，是为了在黑铁站稳脚跟之前粉碎这次进攻，同时将确凿的威胁证据直接送到国王麦格尼·铜须面前。",al={"法尔森的动机","为什么杀杜尔根·挽歌之锤","法尔森为什么派人"}},["664606f0"]={q="杜尔根·挽歌之锤的头颅有什么用？",a="你需要用杜尔根·挽歌之锤的头颅向国王麦格尼·铜须提供确凿的证据，证明这场地下进攻的指挥官已被除掉。将这件骇人的战利品直接送到王座厅，既能证实领主大厅内的黑铁突击部队已经失去首领，也能将大地先知法尔森的亲笔警告带给国王。",al={"杜尔根·挽歌之锤的头颅用途","为什么取杜尔根的头颅","杜尔根·挽歌之锤的头颅"}}},fp="23,182,20.333.0,18.279.1,22.260.1,32.210.0,33.116.0,26.168.0,41.105.0,50.96.0,63.179.0"}
P.entries["quest:96394"] = {n="不得安息的亡者",s="“不得安息的亡者”讲述了领主大厅地下墓穴中一起令人不安的骚乱，古老的矮人灵魂从沉睡中被惊醒。由于看守者们不敢进入地下室，一位冒险者必须深入墓穴，让愤怒的幻影和安威玛尔之灵重归安宁。",h="“不得安息的亡者”讲述了领主大厅地下墓穴中一起令人不安的骚乱，古老的矮人灵魂从沉睡中被惊醒。由于看守者们不敢进入地下室，一位冒险者必须深入墓穴，让愤怒的幻影和安威玛尔之灵重归安宁。",kw={"安威玛尔","矮人墓穴","矮人灵魂","狂怒的幻影","鬼魂","领主大厅","安威玛尔之灵","不安的亡灵","受折磨的灵魂"},ang={["class:Priest"]="那些徘徊在痛苦或愤怒中的灵魂，对于那些能够与灵魂沟通并指引困顿的亡者走向宁静安息的人来说，是直接的职责召唤。",["faction:Alliance"]="确保铁炉堡下方祖先墓穴的安全，能保证看守者们在履行神圣职责时，无需担心被复仇的幻影所淹没。",["race:Dwarf"]="领主大厅安葬着受人尊敬的亡者和矮人先祖，他们突如其来的剧烈躁动，构成了矮人文明核心地带的一场令人不安的骚乱。"},sec={{t="深处地下室的骚乱",b="在领主大厅地表深处，祖先的墓穴里安葬着数代受人尊敬的亡者。这些通常在宁静沉睡中的灵魂，因地下室里一场看不见的骚乱而变得狂暴不安。从下方传来的阵阵怪声吓坏了此处的看守者，在恢复秩序之前，他们拒绝进入下层房间履行职责。冒险者们被召集起来，深入那阴森的石厅，平息这些躁动的灵魂。"},{t="平息先祖",b="在领主大厅安息的灵魂以浅眠著称。无论是什么事件或存在震动了下层的墓穴，都激起了阵阵狂怒的幻影和受折磨的灵魂，将这片圣地变成了险象环生的鬼蜮。其中被惊醒的就包括受人崇敬的安威玛尔之灵，需要以恭敬而坚定的手段来平息这些被唤醒的先祖的怒火，使墓穴重归平静。"}},faq={{q="“不安的亡灵”任务是关于什么的？",a="“不安的亡灵”是一项调查并平息领主大厅地下幽灵骚乱的任务。某人或某种东西惊扰了埋葬在此的灵魂，导致看守者们在处理掉这些幽灵之前不敢进入地下室。",al={"什么是 不安的亡灵","这个任务是什么","不安的亡灵 任务概述"}},{q="灵魂为什么会苏醒？",a="地下室深处一场未知的骚乱唤醒了安葬的亡者。由于领主大厅的灵魂被描述为睡眠很浅，发生在墓穴底部的任何事情都可能惊扰他们，使其陷入愤怒和痛苦的疯狂。",al={"鬼魂为什么愤怒","是谁惊扰了墓穴","幻影为什么苏醒"}},{q="骚乱发生在哪里？",a="这场骚乱集中在领主大厅的地下墓穴和拱顶，这里是位于铁炉堡下方的一处祖先安息之地，古老的矮人灵魂在此长眠。",al={"领主大厅在哪里","不安的亡灵 在哪里刷新","领主大厅位置"}},{q="安威玛尔之灵是谁？",a="安威玛尔之灵是一个安息在领主大厅深处墓穴中的古老而显赫的灵魂。与其他较弱的幻影一样，这位伟大的灵魂从沉睡中被惊醒，必须让他重归宁静的安息。",al={"安威玛尔之灵是谁","安威玛尔之灵背景故事","安威玛尔鬼魂是谁"}},{q="为什么看守者需要冒险者的帮助？",a="看守者是被指派照看墓穴并在领主大厅履行日常职责的守护者。由于愤怒的灵魂在厅内游荡，在威胁被消除之前，他们拒绝下到下层地下室。",al={"看守者是谁","为什么看守者需要帮助","领主大厅看守者"}},{q="领主大厅里有哪些灵魂在作祟？",a="受到惊扰的地下室里有狂怒的幻影、受折磨的灵魂，以及受人尊崇的安威玛尔之灵本身，它们都因受到惊吓而在墓室中开始了狂暴的游荡。",al={"下面有哪些鬼魂","领主大厅里的幻影","不安的亡灵 的类型"}}},fp="17,207,30.381.0,22.328.1,38.153.0,30.187.0,39.152.0,30.182.0,45.190.0,38.169.0"}
P.entries["quest:96395"] = {n="An Ancient Grudge",s="在历史悠久的领主大厅深处，一位以太侍从恳求结束一位陨落统治者的折磨。Faldrim Anvilmar 的灵魂仍在徘徊，被旧日的怨恨所吞噬，无法获得永恒的安宁。冒险者们被委派去让这位不安息的领主获得安息。",h="在历史悠久的领主大厅深处，一位以太侍从恳求结束一位陨落统治者的折磨。Faldrim Anvilmar 的灵魂仍在徘徊，被旧日的怨恨所吞噬，无法获得永恒的安宁。冒险者们被委派去让这位不安息的领主获得安息。",kw={"古老的仇怨","安威玛尔","矮人鬼魂","法尔德林·安威玛尔","幽灵侍从","领主大厅","不安的灵魂","领主"},ang={["class:Paladin"]="让受折磨的灵魂安息是发誓为受苦死者带来和平的神圣战士的神圣职责。",["class:Priest"]="牧师们明白，挥之不去的怨恨和未获救赎的悲伤可以在肉体化为尘土许久之后，仍将凡人的灵魂束缚在物质位面。",["race:Dwarf"]="对于矮人来说，面对自己族人的一位不安领主是一个令人清醒的提醒：古老的怨恨可以比死亡本身更长久。"},sec={{t="An Ancient Grudge",b="在领主大厅的石质拱顶内，死亡并没有提供即刻的解脱。Faldrim Anvilmar 的一位幽灵侍从在那里徘徊，几乎无法积攒起足够的力量穿过凡世的面纱进行交谈。这个幻影并不寻求自身的自由，它唯一关心的是它的主人，恳求旅行者安抚这位不安的领主灵魂。"},{t="过去的重负",b="死亡并没有让 Faldrim Anvilmar 从过去中解脱出来。被一种吞噬一切的古老怨恨束缚在物质世界，Faldrim 的灵魂依然躁动且充满敌意，如果不被强行解脱，就无法找到安眠。"}},faq={{q="法尔德林·安威玛尔 是谁？",a="法尔德林·安威玛尔 是一位矮人领主，他那不安的幻影如今盘踞在领主大厅。他的幽灵侍从说他被一种古老的怨恨所吞噬，无法找到安宁。该任务没有提及关于他的生平或血统的更多信息。",al={"法尔德林·安威玛尔 传说","法尔德林 是谁","领主 安威玛尔"}},{q="领主大厅位于何处？",a="领主大厅位于铁炉堡这座矮人首都内部，旧铁炉堡 下方的洞穴中。",al={"领主大厅位置","领主大厅在哪里","领主大厅入口"}},{q="为什么 法尔德林·安威玛尔 的灵魂带有敌意？",a="根据这位幽灵侍从的说法，这位前任领主被一种古老的怨恨所吞噬。矮人的历史沉浸在数百年的部族竞争中，而 法尔德林 挥之不去的仇恨阻止了他的灵魂进入安宁的沉睡。",al={"法尔德林 为什么愤怒","为什么领主会攻击","远古的仇恨 解释"}},{q="谁提供了任务 古老的怨恨？",a="该任务由在领主大厅内发现的一位幽灵侍从提供。即使死后仍被束缚在仆役身份中，这位侍从只寻求为其前主人带来安宁。",al={"谁给予 远古的仇恨","幽灵侍从任务","任务提供者"}},{q="你必须做什么来完成这个任务？",a="你必须在领主大厅内面对 法尔德林·安威玛尔 的灵魂，在战斗中击败他那不安的鬼魂以将其从折磨中解脱，然后回到幽灵侍从那里报告。",al={"如何完成 远古的仇恨","让 法尔德林 安息","远古的仇恨 目标"}},{q="法尔德林 与安威玛尔镇有关吗？",a="目前尚不清楚。法尔德林 与寒脊山谷的安威玛尔定居点名字相同，但该任务没有提及他的家人或与该镇的任何联系。",al={"法尔德林 来自 安威玛尔 吗","安威玛尔 和寒脊山谷的联系","安威玛尔 家族"}}},fp="17,147,21.261.0,22.169.1,24.167.0,36.98.0,45.151.0,38.91.0,39.160.0,43.164.0"}
P.entries["quest:96403"] = {n="Important Heirlooms",s="Important Heirlooms 是一个任务，冒险者将协助一位名叫Thom的紧张的侏儒。当黑铁矮人利用地下钻探机突破金库时，他正潜伏在领主大厅内被当场撞见。任务要求玩家在所谓的“历史保护”幌子下，找回散落在各处的矮人遗物。",h="Important Heirlooms...",kw={"黑铁矮人","矮人传家宝","侏儒","领主大厅","重要的传家宝","钻探机","汤姆","宝库"},ang={["class:Rogue"]="潜行者很容易看穿Thom那拙劣的“巡逻”借口，认出这是另一个因地下入侵而被困住的拾荒者。",["race:Dwarf"]="矮人冒险者可能会对Thom突然热衷于打捞祖先遗物持深度怀疑态度，尤其是考虑到他关于战利品和估价的口误。",["race:Gnome"]="Thom的投机本性和笨拙的掩饰，突显了在面对宝贵文物时，侏儒好奇心不那么学术的一面。"},sec={{t="宝库中的麻烦",b="在探索领主大厅的地下宝库时，一位投机取巧的侏儒Thom被突然出现的黑铁矮人打断了，他们正驾驶着钻探机从地下钻出。Thom无法独自确保该地区的安全，于是招募路过的冒险者深入危险的挖掘现场，在入侵者抢走或摧毁文物之前，找回散落在各房间里的宝贵矮人遗物。"},{t="文化保护还是牟取暴利？",b="尽管Thom坚持说他只是在巡逻，并希望将这些遗物编目以进行保护，但他不断说漏嘴提到“无价的战利品”和“评估收获”，这表明他有更自私的动机。冒险者因其勇敢行为获得了丰厚的报酬，但这些古代矮人宝藏最终是会被送进博物馆，还是落入拍卖行，仍是个未知数。"}},faq={{q="汤姆是谁？",a="这个任务由汤姆发布，他是一个出现在宝库附近的投机侏儒。他紧张时的口误表明，相比合法的金库安保，他对那些利润丰厚的战利品更感兴趣。",al={"任务发布者是谁","汤姆是谁","任务发布者"}},{q="什么是领主大厅？",a="领主大厅是一处矮人地下宝库，内存放着古代文物和传家宝。最近，该处被黑铁矮人的地下部队攻破。",al={"什么是领主大厅","领主大厅在哪里"}},{q="为什么黑铁矮人在宝库里？",a="一支黑铁矮人突击队利用地下钻探机直接从深处攻破了宝库，使该地区陷入混乱，其目的尚不明确。",al={"为什么黑铁矮人会出现在那里","黑铁矮人钻探机"}},{q="汤姆真的在归还传家宝吗？",a="汤姆经常说漏嘴，把潜入称为“巡逻”，把传家宝称为“战利品”和“收获”，把编目称为“评估”。虽然他支付了约定的报酬，但他声称要将遗物送回荣誉之地的说法非常可疑。",al={"汤姆在撒谎吗","汤姆在偷窃吗","汤姆是否值得信赖"}},{q="什么是矮人传家宝？",a="它们是存放在领主大厅内的古代矮人文物，被历史学家视为无价之宝，而被像汤姆这样的投机者视为利润丰厚的战利品。",al={"什么是传家宝","矮人传家宝背景"}},{q="为什么汤姆不能自己找回传家宝？",a="当黑铁矮人的钻探机突然出现时，汤姆正潜伏在宝库中，被打了个措手不及，导致他在没有冒险者保护的情况下无法安全地搜寻这些遗物。",al={"为什么汤姆需要帮助","为什么要帮助汤姆"}}},fp="19,189,21.287.0,43.264.1,12.166.0,27.132.0,40.97.0,39.165.0,31.151.0,46.152.0"}
P.entries["quest:96408"] = {n="A Visitor to Dun Morogh",s="“丹莫罗的访客”是贝尔丁·钢架在卡拉诺斯外发布的一项调查任务。山地巡逻队员报告称，在俯瞰古博拉采掘场的悬崖高处发现了一处陌生的营火，因此派遣一名侦察兵去查明那个陌生人是否对当地的矮人构成了威胁。",h="“丹莫罗的访客”是贝尔丁·钢架在卡拉诺斯外发布的一项调查任务。山地巡逻队员报告称，在俯瞰古博拉采掘场的悬崖高处发现了一处陌生的营火，因此派遣一名侦察兵去查明那个陌生人是否对当地的矮人构成了威胁。",kw={"贝尔丁·钢架","丹莫罗","大地之环先知法尔森","farsen's watch","古博拉采掘场","领主大厅","卡拉诺斯","访客"},ang={["class:Shaman"]="与大地之环先知法尔森的会面直接联系着与山石的精神沟通，这在丹莫罗的雪域高地上是非常罕见的景象。",["faction:Alliance"]="协助卡拉诺斯外的当地山地巡逻队员，可以确保补给线和采掘场工人们免受突发威胁。",["race:Dwarf"]="对于铜须矮人而言，监视那些俯瞰如古博拉采掘场等大型矿区的未经邀请的观察者，是保护卡兹莫丹边境的标准安全措施。"},sec={{t="高处的烟雾",b="丹莫罗的山地巡逻队员们一直勤勉地守护着铁炉堡周围的峭壁和雪谷。当一处营火突然出现在古博拉采掘场上方的高处时，卡拉诺斯的人们警觉了起来。贝尔丁·钢架对这处位于矮人重要挖掘地点正上方的异常营地感到担忧，于是招募旅行者前往山脊，确认这位神秘的陌生人究竟是无害的旅人还是入侵者。"},{t="会见大地之环先知",b="前往山脊调查后发现，这位旅行者是大地之环先知法尔森，一位在风雪高地上搭起营地的神秘人士。这位神秘的观察者并非劫掠的穴居人或怀有敌意的间谍，而是与大地有着深厚的精神联系。他在俯瞰采掘场的悬崖上的存在，开启了一段揭示卡兹莫丹地下深处潜藏的更严重动荡的旅程，并最终与领主大厅的谜团联系在了一起。"}},faq={{q="是谁派你去调查这位访客的？",a="贝尔丁·钢架，驻扎在丹莫罗的卡拉诺斯外，在山地巡逻队员报告山上出现不明火光后发布了此任务。",al={"谁发布此任务","任务起始","贝尔丁·钢架任务"}},{q="神秘的营地位于哪里？",a="营火位于卡拉诺斯以东积雪覆盖的山脊高处，正好俯瞰着古博拉采掘场的挖掘现场。",al={"营地位置","访客在哪里","访客地点"}},{q="在采掘场上方俯瞰的访客是谁？",a="这位访客是大地之环先知法尔森，一位居住在采掘场上方高处偏僻营地里的精神观察者。",al={"谁是法尔森","谁是访客","大地之环先知法尔森"}},{q="为什么矮人们会对那处营火起疑？",a="古博拉采掘场是矮人的一项关键作业，本就承受着当地穴居人的压力。任何位于矿坑上方的高处不明营地，都有可能是监视矮人动向的侦察兵或敌对势力。",al={"为何怀疑","为何调查","为何派我去"}},{q="这项任务会引出什么后续？",a="向大地之环先知法尔森报告后将直接开启任务“法尔森的注视”，这也是领主大厅准入任务线的开端。",al={"what comes next","后续任务","领主大厅引导"}},{q="你需要在这个营地与那个陌生人战斗吗？",a="不需要。虽然贝尔丁·钢架让你做好了可能发生暴力的准备，但这位访客是大地之环先知法尔森，他是一位愿意与你交谈的和平观察者。",al={"访客是否有敌意","我要杀死访客吗","访客战斗"}}},fp="23,167,28.237.0,21.242.1,41.119.0,41.85.0,42.89.1,48.207.0,31.102.1,46.135.1"}
P.entries["quest:965"] = {n="奥萨拉克斯之塔",s="哨兵艾莉萨·星风肩负着保卫奥伯丁的重任，她怀疑北方的古代遗迹中隐藏着邪恶的勾当。她委托冒险者去寻找巴苏尔·影击，一名被派去监视神秘的奥萨拉克斯之塔，却未按时汇报情况的侦察兵。",h="哨兵艾莉萨·星风肩负着保卫奥伯丁的重任，她怀疑北方的古代遗迹中隐藏着邪恶的勾当。她委托冒险者去寻找巴苏尔·影击，一名被派去监视神秘的奥萨拉克斯之塔，却未按时汇报情况的侦察兵。",kw={"奥萨拉克斯","奥伯丁","巴苏尔·影击","黑海岸","艾莉萨·星风","侦察兵","哨兵","塔"},ang={["faction:Alliance"]="奥伯丁是联盟进入卡利姆多北部的门户，因此保卫其周边道路和边界对所有来访的盟友来说都至关重要。",["race:NightElf"]="奥萨拉克斯的遗迹是古代卡利姆多陨落的上层精灵历史的见证，而保护奥伯丁免受那些腐朽石块中的腐蚀影响，是暗夜精灵哨兵的一项重要职责。"},sec={{t="失踪的侦察兵",b="奥伯丁的哨兵必须时刻警惕黑海岸潜伏的危险。哨兵艾莉萨·星风注意到森林北部的奥萨拉克斯之塔周围有可疑的活动。她派遣了巴苏尔·影击去调查这座古代遗迹。几天过去了，侦察兵却杳无音信，这促使艾莉萨寻找一位愿意前往北方、定位巴苏尔并确保他没有遭遇不幸的旅行者。"},{t="注视遗迹",b="从奥伯丁向北的道路穿过古老的卡多雷遗迹，跨过壁泉河，然后到达阴影笼罩的塔楼区域。虽然与奥伯丁失去了联络，巴苏尔在最初的监视行动中幸存了下来。当你在周围的树林中找到他时，他证实了艾莉萨的直觉是正确的：在坍塌的石塔内，黑暗而令人不安的事件正在进行中。"}},faq={{q="哨兵艾莉萨·星风是谁？",a="艾莉萨·星风是一名驻扎在奥伯丁的暗夜精灵哨兵。她负责保护该定居点免受整个黑海岸外部威胁的影响，并监控区域内的危险，例如奥萨拉克斯之塔。",al={"艾莉萨·星风","谁给予任务","奥伯丁任务发布者"}},{q="巴苏尔·影击是谁？",a="巴苏尔·影击是哨兵艾莉萨·星风派遣的一名侦察兵，负责刺探奥萨拉克斯之塔周围的神秘活动。他守候在遗迹外，以监视敌对势力的动向。",al={"巴苏尔","谁是侦察兵","影击"}},{q="奥萨拉克斯之塔在哪里？",a="这座塔坐落在黑海岸的东北部。旅行者可以从奥伯丁向东出发，沿着北面的道路经过巴莎兰，跨过壁泉河上的桥，直到看到那座尖塔。",al={"奥萨拉克斯之塔位置","塔在哪里","如何找到奥萨拉克斯"}},{q="为什么要派侦察兵去塔那里？",a="艾莉萨在履行保护奥伯丁职责的同时，派遣巴苏尔去观察奥萨拉克斯之塔周围发生的怪事。",al={"为什么要监视塔","奥萨拉克斯出了什么问题","为什么要派巴苏尔"}},{q="为什么巴苏尔没有回到奥伯丁？",a="艾莉萨没有收到巴苏尔的报告，因此请求你去查看他的情况。当你找到他时，巴苏尔会向你解释他的处境。",al={"为什么巴苏尔失踪","巴苏尔被困了吗","为什么巴苏尔留下了"}},{q="这个任务链有后续吗？",a="有的。找到巴苏尔·影击将开启一系列调查任务，探究占据奥萨拉克斯之塔的黑暗势力及其在黑海岸的险恶野心。",al={"这是任务链吗","下一个任务是什么","奥萨拉克斯任务链"}}},fp="22,173,23.345.0,18.352.1,34.188.0,29.184.0,40.211.0,53.118.0,42.129.0,31.156.0"}
P.entries["quest:966"] = {n="奥萨拉克斯之塔",s="侦察兵巴苏尔·影击在黑海岸北部奥萨拉克斯之塔周边调查可疑活动时，寻求帮助以从聚集的术士那里搜集情报。通过从废墟外的狂热者身上找回丢弃的羊皮纸残片，他试图揭开这些邪教徒的身份及其阴险目的。",h="侦察兵巴苏尔·影击在黑海岸北部奥萨拉克斯之塔周边调查可疑活动时，寻求帮助以从聚集的术士那里搜集情报。通过从废墟外的狂热者身上找回丢弃的羊皮纸残片，他试图揭开这些邪教徒的身份及其阴险目的。",kw={"奥萨拉克斯之塔","奥伯丁","巴苏尔","黑岸","黑海岸","德尔格伦","狂热者","羊皮纸","净化者","影击","术士"},ang={["class:Paladin"]="在黑海岸北部发现一个有组织的黑暗邪教，直接助力了净化者德尔格伦的远征，他是一位致力于清除邪能和恶魔腐化的盟友。",["class:Warlock"]="黑岸邪教证明了不受约束的结社将占据古老的废墟，在远离联盟和部落当局窥探的地方进行召唤仪式。",["race:NightElf"]="奥萨拉克斯之塔被黑暗邪教徒亵渎，代表了古老精灵遗产在卡利姆多海岸上遭遇的又一次玷污。"},sec={{t="浅滩之眼",b="巴苏尔·影击站在黑海岸北部雾气缭绕的海岸线上，警惕地注视着被称为奥萨拉克斯之塔的古老废墟。他被派往此地为奥伯丁监视现场，并向净化者德尔格伦报告任何迫在眉睫的危险。巴苏尔不愿离开岗位去报告，因为他担心自己会错过那些占据废墟的黑暗施法者们的关键动向，因此他转而依靠过往的旅人来侦察周边营地。"},{t="破解邪教",b="出没在废墟中的低阶追随者身上携带着破碎的卷轴和笔记。通过拼凑从这些外围邪教徒身上找回的几张破旧的羊皮纸，巴苏尔发现了一个令人不安的名字：黑岸邪教。侦察兵对这个阴暗的教派一无所知，他意识到这些威胁比一伙流氓术士要组织严密得多，必须立即向德尔格伦发出警告。"}},faq={{q="巴苏尔·影击是谁？",a="巴苏尔·影击是一名联盟侦察兵，驻扎在黑海岸北部奥萨拉克斯之塔附近的道路上。他受奥伯丁的领导层和圣骑士净化者德尔格伦之托，被派往监视塔内可疑的集会。",al={"巴苏尔·影击传说","巴苏尔是谁","巴苏尔黑海岸"}},{q="奥萨拉克斯之塔是什么？",a="奥萨拉克斯之塔是位于黑海岸北部的一座古老精灵废墟。最近，阴险的术士及其邪教徒爪牙占据了周边的场地和塔楼内部，在远离奥伯丁守望的地方进行黑暗仪式。",al={"奥萨拉克斯之塔","奥萨拉克斯之塔是什么","黑海岸废弃之塔"}},{q="塔楼周边的邪教徒是谁？",a="他们属于黑岸邪教，这是一个由术士和狂热者组成的秘密组织，聚集在这座古老的精灵废墟中进行黑暗召唤仪式。",al={"术士是谁","黑岸邪教","黑岸狂热者"}},{q="为什么巴苏尔告诫不要进入塔内？",a="巴苏尔指出，居住在塔楼上层的术士比在废墟外扎营的狂热者要强大且危险得多。他建议在尝试强攻据点之前，先从外围搜集情报。",al={"我可以进入塔内吗","塔中术士危险吗","塔内部"}},{q="破旧的羊皮纸揭示了什么？",a="邪教狂热者随身携带的零散碎片提供了该组织名字——黑岸邪教——的第一个明确证据，向巴苏尔揭示了占领者是一个有组织的教派，其存在对该地区构成了直接威胁。",al={"羊皮纸上写了什么","破旧的羊皮纸传说","邪教笔记"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷迈斯特拉岗哨的联盟圣骑士，致力于净化恶魔和腐化势力。他怀疑奥萨拉克斯之塔正在滋生邪恶活动，并依赖像巴苏尔这样的侦察兵提供情报。",al={"德尔格伦","德尔格伦是谁","净化者德尔格伦"}}},fp="22,252,20.370.0,20.280.1,29.215.0,31.218.0,43.179.0,50.225.0,35.185.0,28.262.0"}
P.entries["quest:96604"] = {n="The Great Outdoors",s="The Great Outdoors是一项由Brakk向有抱负的冒险者提供的入门级荒野生存任务。通过学习在简易营火旁休息，旅行者们能在追求实用专业技能之前，掌握在野外维持生存的基础知识。",h="The Great Outdoors是一项由Brakk向有抱负的冒险者提供的入门级荒野生存任务。通过学习在简易营火旁休息，旅行者们能在追求实用专业技能之前，掌握在野外维持生存的基础知识。",kw={"强效休息","布拉克","营地设施","营火","户外天地","专业技能","荒野生存"},ang={["faction:Horde"]="伴随着传统的兽人问候语“你好”，这门生存课程为初出茅庐的部落冒险者在踏入危险区域前提供了基础的指导。"},sec={{t="荒野课程",b="冒险进入艾泽拉斯未受驯服的疆域，需要的不仅仅是武力，还需要能够忍受恶劣环境的基础知识。Brakk用一声豪迈的“你好”欢迎有抱负的冒险者，认可那些寻求财富与荣耀之人的躁动灵魂。为了在前方漫长的道路上生存下来，每一位旅行者都必须首先掌握安营扎寨并在荒野中恢复体力的艺术。"},{t="从炉火到技艺",b="在Brakk的简易营火旁坐下，可以传授恢复体力的精髓，让人在露天环境下获得恢复性休息。一旦理解了这些生存基础，初出茅庐的冒险者就会被指引前往当地村庄的工匠处。在那里，他们可以学习专业技能，并探索如何建造适合其所选技艺的功能性营地设施。"}},faq={{q="什么是广阔的荒野？",a="广阔的荒野是一项由布拉克提供的入门级生存任务，旨在教导新冒险者在学习专业技能之前，通过在营火旁休息来学会在荒野中茁壮成长。",al={"什么是户外生活","户外生活任务"}},{q="布拉克是谁？",a="布拉克是一位经验丰富的户外生存专家，他欢迎躁动的旅行者，提供关于荒野生存和在营火旁休息的实用课程。",al={"布拉克是谁","任务发布者"}},{q="什么是“强效休息”增益效果？",a="在布拉克的简易营火旁休息可以获得“强效休息”增益效果，这展示了在野外，通过寻找遮蔽处并在明火旁恢复体力是如何让冒险者重获新生的。",al={"强效休息增益","营火增益"}},{q="完成任务后你应该做什么？",a="在学完荒野休息的基础知识后，布拉克会建议冒险者去拜访附近村庄的训练师，学习一项专业技能，并了解如何构建适合其技艺的营地设施。",al={"任务后的下一步","营火之后要做什么"}},{q="什么是营地设施？",a="营地设施是由附近村庄的专业训练师教授的专门营地装置，使旅行者能够改造他们的营地，以支持他们所选择的专业技能。",al={"营地设施","什么是营地设施"}},{q="这项训练是为谁准备的？",a="任何在荒野中寻求财富和荣耀的躁动灵魂都能从这门课程中受益，特别是那些刚刚踏上旅程并准备选择职业的人。",al={"谁应该做这个任务","这是部落任务吗"}}},fp="18,131,19.303.0,20.303.0,27.97.0,13.133.0,30.138.0,46.153.0,23.164.0,34.151.0"}
P.entries["quest:96605"] = {n="The Great Outdoors",s="“The Great Outdoors”是一个引导任务，旨在教导胸怀大志的冒险者掌握荒野生存的基本技能。在旅行者Kaga的指引下，新人将学会如何在简易营火旁恢复体力，并进而学习专业技能和制作特制的营地设施。",h="“The Great Outdoors”是一个引导任务，旨在教导胸怀大志的冒险者掌握荒野生存的基本技能。在旅行者Kaga的指引下，新人将学会如何在简易营火旁恢复体力，并进而学习专业技能和制作特制的营地设施。",kw={"boosted rest","营地设施","营火","kaga","生存","the great outdoors","专业技能","荒野"},ang={["profession:Cooking"]="营火和荒野生存构成了野外烹饪的基础，使得营地制作成为在露天环境下准备餐点的自然补充。"},sec={{t="荒野课程",b="每一个踏出文明安全区冒险者很快就会发现，光靠勇气是不足以在边境地带生存下去的。“The Great Outdoors”向新人们介绍了荒野适应能力的至关重要性。通过经验丰富的旅行者Kaga的教导，这一简短的课程提醒那些初出茅庐的英雄们：在未知的领土中兴旺发展，始于学会如何建立营地并忍受露天环境的考验。"},{t="炉火与工艺",b="一堆简单的营火往往就是探险者与荒野疲劳之间的唯一屏障。坐在Kaga的炉火旁并获得“Boosted Rest”增益效果，冒险者们就能体会到营地生活的恢复力量。一旦理解了荒野休息的基本原理，Kaga就会督促旅行者们拜访附近的定居点工匠，学习专业技能并掌握专业营地设施的制作方法。"}},faq={{q="什么是“The Great Outdoors”？",a="“The Great Outdoors”是由Kaga提供的一项荒野生存入门任务。它向初出茅庐的冒险者介绍了荒野生存、在营火旁休息以及为专业技能做准备的基本知识。",al={"什么是“the great outdoors”","“the great outdoors”任务"}},{q="谁提供这个任务？",a="Kaga是一位经验丰富的旅行者和户外导师，他指导有抱负的冒险者掌握荒野生存的基础知识。他维护着一处基础营火，新人可以在那里学习如何休息和恢复。",al={"谁是kaga","kaga任务发布者"}},{q="什么是“Boosted Rest”增益？",a="“Boosted Rest”是通过安静地坐在Kaga的基础营火旁所获得的有益放松状态。它代表了在荒野营地适当休息所带来的恢复效果。",al={"boosted rest","什么是“boosted rest”增益"}},{q="什么是营地设施？",a="在掌握了基本的荒野休息方法后，附近定居点的专业训练师可以教导冒险者如何根据他们选择的职业建造特制的营地设施。",al={"营地设施背景知识","专业营地设施"}},{q="为什么Kaga让你坐在营火旁？",a="在文明城镇外生存需要学会如何扎营并恢复体力。坐在营火旁可以让冒险者在危险的旅途中获得温暖、专注和休息恢复。",al={"为什么要在营火旁休息","营火休息"}},{q="完成这节课后你应该做什么？",a="在学会如何正确地在荒野中休息后，Kaga建议去寻找附近村庄的专业训练师，学习一门手艺并获取特定职业营地设施的配方。",al={"完成“the great outdoors”后做什么","kaga任务之后"}}},fp="18,162,19.184.0,24.259.0,27.125.0,22.128.0,30.141.0,23.140.0,43.158.0,48.161.0"}
P.entries["quest:96606"] = {n="The Great Outdoors",s="“The Great Outdoors”是一门由名为莱瑞娜（Lyreena）的资深斥候为猎人提供的入门级野外生存课程。该课程强调在营火旁休息以恢复体力，并在穿越荒野时获得“强化休息”增益的重要性。",h="“The Great Outdoors”是一门由名为莱瑞娜（Lyreena）的资深斥候为猎人提供的入门级野外生存课程。该课程强调在营火旁休息以恢复体力，并在穿越荒野时获得“强化休息”增益的重要性。",kw={"冒险者","强化休息","营火","猎人","莱瑞娜","生存","户外天地","荒野"},ang={["class:Hunter"]="这门课程直接面向猎人，强化了在荒野中追踪时野外生存和露营技巧的必要性。"},sec={{t="荒野课程",b="冒险深入文明之外的边境，需要的不仅仅是敏锐的准星和灵敏的感知，更需要对原始荒野元素的敬畏。一位经验丰富的斥候莱瑞娜为流浪的猎人们提供指导，欢迎他们停下脚步，在她的营火旁寻求慰藉。在艾泽拉斯危险的荒野中，学会如何建立炉火并在狩猎间隙恢复体力，与学会如何追踪猎物同样至关重要。"},{t="营火休憩",b="熊熊燃烧的营火能让人在寒冷的夜晚感到舒适，提供片刻的宁静，让疲惫的旅人驱散困倦。靠近火焰坐下，冒险者便能获得“强化休息”效果，这能让他们恢复精力，为严酷的探索做好准备。花时间坐在余烬旁会让年轻的冒险者明白，耐心和休息是野外生存不可或缺的支柱。"}},faq={{q="莱瑞娜是谁？",a="莱瑞娜是一位经验丰富的野外导师，她教导有抱负的冒险者和猎人如何在荒野中正确休息和生存。她会在营火旁提供实用的建议。",al={"莱瑞娜是谁","莱瑞娜 营火","任务发布者"}},{q="什么是“广阔天地”？",a="“广阔天地”是一项野外生存入门任务，一位名叫莱瑞娜的资深户外专家会邀请猎人坐在她的营火旁，学习如何在长途远征中维持体力。",al={"什么是户外活动","这是什么任务","户外活动任务"}},{q="什么是“强化休息”？",a="在简易营火旁坐下，可以让疲惫的流浪者从旅途的劳顿中恢复，并获得“强化休息”效果，为接下来的旅程重振精神。",al={"强化休息增益","强化休息 营火","如何获得强化休息"}},{q="为什么要坐在营火旁休息？",a="营火在严酷的荒野中提供至关重要的温暖和休憩。在营火旁休息可以让冒险者喘口气，清醒头脑，并为穿越荒野之地的危险跋涉做好准备。",al={"营火的用途","为什么要在火边坐下","在营火旁休息"}},{q="为什么户外生存对猎人至关重要？",a="猎人的大部分时间都在与世隔绝的地区穿行，附近既没有旅店也没有安全的城镇。掌握基本的露营技巧能确保猎人在严苛的环境中生存，而不至于被疲惫击垮。",al={"猎人生存技能","户外生存","为什么是猎人任务"}},{q="完成这项任务需要做什么？",a="要完成这项任务，你只需要在莱瑞娜的简易营火旁坐下，等待片刻，直到营火的温暖为你赋予“强化休息”增益即可。",al={"任务目标","如何完成户外活动","户外活动目标"}}},fp="18,127,19.247.0,16.179.0,15.123.0,27.80.0,21.130.0,38.127.0,44.153.0,38.75.0"}
P.entries["quest:96607"] = {n="The Great Outdoors",s="The Great Outdoors 是一项入门级的生存课程，由经验丰富的旅行者为艾泽拉斯各地初出茅庐的流浪者们提供。通过在温暖的篝火旁小憩片刻，新手们可以了解到保持充分休息和做好准备对于冒险者在城墙之外生存的重要性。这标志着掌握野外生存和专业野外营地技巧的第一步。",h="The Great Outdoors...",kw={"冒险者","强化休息","篝火","露营","埃莉诺·沙克尔顿","艾尔文森林","山姆·萨萨帕里拉","生存","专业技能"},ang={["faction:Alliance"]="在安全的艾尔文森林中，人类旅行者在面对西部荒野和赤脊山潜藏的严酷威胁之前，会先从经验丰富的旅者那里学习这些生存基础知识。",["faction:Horde"]="无论是穿越杜隆塔尔干旱的平原，还是莫高雷风吹过的平顶山，部落的生存专家们都会向每一位年轻的战士灌输火种工艺和野外纪律。",["profession:Cooking"]="每一个野外营地都始于火焰，这使得烹饪成为野外生存的天然伴侣。在这堂课程之后，露营大师会立即引导你进行路边烹饪教学。"},sec={{t="小径之课",b="无论你的刀刃多么锋利，魔法多么强大，如果你忽视了生存的基本知识，艾泽拉斯的荒野很快就会磨损你的锐气。驻扎在路边空地附近的资深流浪者们，会为那些从家乡谷地出发的旅行者提供这堂简单的课程。花点时间在篝火旁休息，不仅能缓解双脚的酸痛，更能平复心境，为前方艰险的旅途做好准备。只有那些掌握了定期休息和准备这一准则的人，才有机会生存得足够久，从而获得财富与荣耀。"},{t="他乡之居",b="一旦冒险者明白了跳动的火焰和适当休息的价值，导师们就会指引他们直接前往城镇的技艺工匠处。野外营地很少仅凭火星和睡袋就能搭建完成；生存需要实际的技能。无论是锻造修补用的铆钉、烹饪行军口粮，还是在星空下缝补破损的装备，每一项专业技能都提供了独特的营地设施，能将荒芜的山坡变为自给自足的前哨站。"}},faq={{q="谁会向新晋的流浪者提供这堂课程？",a="根据你所在的位置，会有各种各样的老练旅行者提供指导。在艾尔文森林，经验丰富的流浪者 萨姆·萨萨帕里拉 会挺身而出，而在其他地方，像 艾瑞克·明锤、莱瑞娜·暮刃、布拉克、埃莉诺·沙克尔顿、卡加·蛮蹄 和 拉恩·狂风 这样的人物也会分享他们的野外生存经验。",al={"谁给予户外活动","谁开启户外活动","任务给予者户外活动"}},{q="在篝火旁休息的目的是什么？",a="安静地坐在熊熊燃烧的篝火旁，可以让冒险者喘口气并获得“强化休息”效果。在野外刻意安排休整时间，对于在穿越荒野的长途跋涉中保持体力至关重要。",al={"为什么要坐在火堆旁","篝火的作用是什么","强化休息增益效果"}},{q="这项训练接下来会导向什么内容？",a="一旦你在火堆旁休息完毕，你的导师会引导你前往附近的定居点学习实用的专业技能。从那里开始，你将学习 露营 101: 烹饪 以及针对你选择追求的任何专业而定制的特定野外露营课程。",al={"户外活动之后是什么","户外活动后续任务","露营任务"}},{q="部落的冒险者也能参加这堂课程吗？",a="是的。无论效忠于哪一方，在严酷的荒野中生存都是一项必备技能。来自联盟和部落的资深导师——例如 布拉克、埃莉诺·沙克尔顿 和 卡加·蛮蹄——都会向各自阵营的新手教授完全相同的基本营地技巧。",al={"这是联盟专属吗","部落的户外活动","兽人可以做这个任务吗"}},{q="为什么导师们让你去和专业训练师交谈？",a="生存不仅仅意味着坐在火焰旁；冒险者需要具备自力更生的能力。专业技能训练师会教你如何制作专门的营地设施，让你能够运用你的技艺，无论是在户外烹饪行军口粮、修理护甲，还是酿制药物。",al={"为什么要学习专业技能","营地设施与专业训练师","专业技能与营地的联系"}},{q="在接受这个任务之前需要什么样的先前经验？",a="冒险者通常是在完成“冒险者”之后紧接着接到这堂课程，此时他们已经证明了自己的基本志向，并已走出新手封地进入了更广阔的区域。",al={"户外活动的前提条件","如何解锁户外活动","户外活动之前"}}},fp="18,163,20.367.0,21.304.0,40.260.0,47.178.0,35.203.0,52.194.0,61.225.0,59.144.0"}
P.entries["quest:96608"] = {n="The Great Outdoors",s="The Great Outdoors向流浪的冒险者们介绍了荒野生存和露营技巧的基础知识。在艾瑞克的营火旁坐下后，旅行者们可以学习如何在野外适当地休整，并在此后学习通过专业技能来支持自己的旅程。",h="The Great Outdoors向流浪的冒险者们介绍了荒野生存和露营技巧的基础知识。在艾瑞克的营火旁坐下后，旅行者们可以学习如何在野外适当地休整，并在此后学习通过专业技能来支持自己的旅程。",kw={"强效休息","营地装置","营火","艾瑞克","生存","户外天地","专业技能","荒野"},ang={["class:Priest"]="虽然牧师们通常在神圣的圣所和教堂中寻找他们的使命，但道路上的生活除了祈祷和祝福之外，还需要实用的生存技能。"},sec={{t="荒野课程",b="踏入广阔的世界需要的不仅仅是雄心壮志和武器或圣契。对于初出茅庐的旅行者来说，生存取决于如何学会在荒野中适当地休息。在简易的营火旁，经验丰富的旅行者艾瑞克欢迎流浪的冒险者们坐下，在余烬中取暖，并了解在进入未开发的荒野之前进行适当休息的重要性。"},{t="从营火到制造",b="在漫长的旅途中，简单的营火只是维持有效营地生活的第一步。在掌握了荒野恢复的基础知识后，旅行者们被鼓励去邻近定居点的专业技能训练师那里访问。在那里，工匠和制作者会教导他们如何组装专门的营地装置，使冒险者们无论走到哪里，都能在营地中练习他们的专业技能并为探险提供支持。"}},faq={{q="艾瑞克是谁？",a="艾瑞克是一位经验丰富的户外生存专家和冒险同伴，他主动向初出茅庐的旅行者传授在荒野中生存的基本要领。他欢迎旅行者们在营火旁休息，并分享远离城市围墙后如何生存的实用建议。",al={"谁提供这个任务","艾瑞克是谁","谁教授户外知识"}},{q="什么是强效休息增益？",a="在艾瑞克的营火旁休息可以提供强效休息效果，帮助疲惫的旅行者恢复精力，为接下来的挑战做好精神准备。这代表了在野外环境中抽出时间进行适当地休整。",al={"什么是强效休息","营火有什么帮助","营地休息增益"}},{q="什么是营地装置？",a="营地装置是针对特定专业技能的实用结构或工具，冒险者们可以在野外设置这些装置。正如附近定居点的专业技能训练师所解释的那样，学习一项专业技能可以让工匠们在营地中建立工作台。",al={"什么是营地装置","专业装置","专业技能营地物品"}},{q="为什么要坐在艾瑞克的营火旁？",a="在营火旁坐下可以让冒险者们停下来，取暖，并聆听艾瑞克关于荒野生存的指导。这给了身体放松的时间，并能获得在户外舒适庇护所中充分休息的好处。",al={"为什么要坐在火旁","在营火旁坐下","营火目标"}},{q="完成这门课程后，冒险者应该去哪里？",a="在掌握了营地休息的基础知识后，艾瑞克建议前往附近的村庄，在当地的专业训练师那里学习一项专业技能。一旦受训，你就可以开始学习如何构建适合你专业的营地装置了。",al={"之后做什么","接下来去哪里","户外活动之后"}},{q="这门生存课程是为谁准备的？",a="艾瑞克呼唤着过往的冒险者，注意到了他们那不安分的灵魂以及在世界各地寻求财富与荣耀的决心。他的荒野指导可以帮助任何离开安全区并冒险进入广阔荒野的人。",al={"谁可以完成这个任务","仅限牧师","这是给冒险者准备的吗"}}},fp="18,70,19.256.0,22.277.0,12.165.0,30.144.0,23.199.0,44.176.0,59.179.0,41.199.0"}
P.entries["quest:96626"] = {n="Camping 101: Cooking",s="Camping 101: Cooking告诉初出茅庐的冒险者，烹饪是在野外建立营地的基石。通过向闪金镇的Cook Tomas学习这项技艺，旅行者们可以获得建造营火和搭建野外营地的能力。",h="Camping 101: Cooking告诉初出茅庐的冒险者，烹饪是在野外建立营地的基石。通过向闪金镇的Cook Tomas学习这项技艺，旅行者们可以获得建造营火和搭建野外营地的能力。",kw={"营火","露营","露营101: 烹饪","营地","烹饪","陈设","闪金镇","托马斯"},ang={["faction:Alliance"]="艾尔文森林的新手联盟冒险者被指引前往闪金镇的狮王之傲旅店寻找Cook 厨师托马斯，以掌握烹饪基础和营火制作。",["profession:Cooking"]="烹饪训练是野外生存的重要基石，赋予了冒险者建造能够固定营地的基础营火的技能。"},sec={{t="野外的炉火",b="对于任何在艾泽拉斯荒野中冒险的勇士来说，建立营地首先需要一团可靠的火焰。任务Camping 101: Cooking告诉新手旅行者，烹饪训练不仅仅是为了准备热食；它是野外生存的重要基础。通过掌握烹饪专业，旅行者可以学会如何点燃合适的营火，将未开发的空地变成安全的避难所。"},{t="闪金镇的指导",b="在艾尔文森林的新旅行者会被派往闪金镇与Cook Tomas交谈，以学习这项技艺的基础知识。在接受他的指导后，冒险者将获得建立基础野外营地的能力。虽然最初的营地比较简陋，陈设也有限，但提升烹饪熟练度可以解锁更大的营火，而其他制造专业则提供了布置和定制营地的更多选择。"}},faq={{q="什么是任务露营 101: 烹饪？",a="露营 101: 烹饪向冒险者介绍了在野外生存的基础知识。它引导你学习烹饪专业，教你如何点燃基本的营火，作为你在野外营地的核心。",al={"什么是露营101: 烹饪","露营101教授什么","露营101的目的"}},{q="托马斯是谁，在哪里可以找到他？",a="托马斯是位于艾尔文森林闪金镇的驻地烹饪训练师。他以狮王之傲旅店为基地，指导有抱负的冒险者学习基础烹饪和点燃营火的艺术。",al={"托马斯是谁","托马斯在哪里","闪金镇的托马斯"}},{q="为什么建立营地需要烹饪？",a="营火是任何野外营地的基础。学习烹饪提供了建造营火所需的基本知识，冒险者可以围绕营火休息并布置他们的营地陈设。",al={"为什么露营需要烹饪","露营需要烹饪吗","烹饪与营火的关系"}},{q="随着技能的提高，可以制作更大的营火吗？",a="提升你的烹饪专精可以让你建造更大、更坚固的火堆。随着烹饪技能的发展，你的营火将成为野外探索更坚实的基地。",al={"如何升级营火","可以建造更大的营火吗","更大的烹饪营火"}},{q="如何获取营地陈设？",a="除了烹饪之外，额外的营地陈设可以向世界各地的其他专业技能训练师学习。精通各种制造专业的冒险者可以制作物品来装饰和增强他们的野外营地。",al={"如何增加营地陈设","营地陈设从哪里来","制作营地物品"}},{q="冒险者可以在哪里建立营地？",a="一旦你掌握了烹饪和营火制作的基础知识，你就能获得在开阔荒野中搭建营地的能力。然而，在提升技能之前，最初的营地规模较小，且仅能容纳极少量的陈设。",al={"可以在任何地方露营吗","野外露营规则","营地放置限制"}}},fp="20,133,22.193.0,24.328.0,39.73.0,39.151.0,48.120.0,53.86.0,49.161.0,36.183.0"}
P.entries["quest:96627"] = {n="The Adventurer",s="The Adventurer是治安官玛克布莱德在北郡山谷发布的一项引导任务。玛克布莱德认可了你初期的能力，并指示你离开封闭的北郡修道院前往闪金镇，去调查一位名叫Sam Sarsaparilla的新来者。",h="The Adventurer是治安官玛克布莱德在北郡山谷发布的一项引导任务。玛克布莱德认可了你初期的能力，并指示你离开封闭的北郡修道院前往闪金镇，去调查一位名叫Sam Sarsaparilla的新来者。",kw={"艾尔文森林","闪金镇","治安官玛克布莱德","北郡","山姆·萨萨帕里拉","冒险者"},ang={["faction:Alliance"]="对于刚在北郡完成服役的联盟新兵来说，这标志着他们第一次正式踏入更广阔的艾尔文森林。",["race:Human"]="走出北郡修道院的人类保卫者迈出了通往闪金镇的第一步，那里是艾尔文的繁华中心。"},sec={{t="离开山谷",b="一旦新兵清除了北郡山谷中诸如迪菲亚兄弟会成员和害虫之类的直接威胁，治安官玛克布莱德就会开始关注道路上的情况。由于暴风城的正规军在王国各地兵力吃紧，当地驻军必须依靠有前途的战士来监视在周边森林中游荡的旅人和流浪者。"},{t="一位好奇的新来者",b="这并非一项军事命令或悬赏任务，玛克布莱德指派给你一件不寻常的差事：去查看一下闪金镇附近出现的一位名叫Sam Sarsaparilla的冒险者。这项请求标志着你从与世隔绝的北郡山谷走向更广阔、更危险的艾尔文森林。"}},faq={{q="谁派我执行这项任务？",a="驻扎在北郡山谷的暴风城守军指挥官治安官玛克布莱德，会在你证明了自己保卫修道院的能力后提供这项任务。",al={"任务发布者","谁发布了冒险者","治安官玛克布莱德任务"}},{q="萨姆·萨萨帕里拉是谁？",a="萨姆·萨萨帕里拉是一位徘徊在闪金镇附近道路上的冒险者。治安官玛克布莱德听闻了他的行踪，并要求你去调查他的意图。",al={"山姆·萨萨帕里拉","山姆是谁","闪金镇冒险者"}},{q="我在哪里可以找到萨姆·萨萨帕里拉？",a="他在从北郡通往艾尔文森林闪金镇的主路上。",al={"山姆·萨萨帕里拉位置","山姆在哪里","寻找山姆·萨萨帕里拉"}},{q="为什么治安官玛克布莱德会关心一个普通的冒险者？",a="北郡始终对强盗和入侵者保持高度戒备。玛克布莱德更倾向于密切关注在这一地区出没的陌生雇佣兵和流浪者，并利用可靠的当地人才进行初步接触。",al={"为什么派我去","玛克布莱德的动机","为什么要找山姆"}},{q="我需要离开北郡山谷才能完成这项任务吗？",a="是的。这项任务指引你穿过北郡山谷的南门，来到通往闪金镇的森林道路上。",al={"北郡之外","这需要离开北郡吗","前往闪金镇"}},{q="这是暴风城正常军事指挥链的一部分吗？",a="虽然这是由暴风城的一名军官发布的，但玛克布莱德明确表示这是一项不同寻常的任务，而非标准的守卫职责，他更看重你作为独立护卫的判断力，而非正式的军事规程。",al={"暴风城军队","这是标准职责吗","公务"}}},fx={dd262048={q="治安官玛克布莱德为什么选我去调查萨姆？",a="治安官玛克布莱德认为这是一项特殊任务，并非常规的驻防差事。他见过你如何应对北郡当地的威胁，认为你是一名能干的保护者，可以在修道院大门之外谨慎行事。他的驻军正忙于应付当地的麻烦，人手紧张，因此派一名可信的新兵去调查道路沿线的传闻，远比派遣常规守卫更合适。",al={"治安官玛克布莱德为什么选我","玛克布莱德为什么派我","为什么不派守卫去找山姆"}}},fp="14,186,18.198.0,18.232.0,26.131.0,24.138.0,33.96.0,56.182.0,52.100.0,63.202.0"}
P.entries["quest:96628"] = {n="The Adventurer",s="The Adventurer 是一项由驻守在丹莫罗南门的巡山人萨鲁斯派发的本地任务。在指引旅行者穿过山间隧道前往卡拉诺斯之前，萨鲁斯会要求他们将一捆补给包带给埃里克·亮锤，一位刚在村庄外扎营的新人。",h="The Adventurer 是一项由驻守在丹莫罗南门的巡山人萨鲁斯派发的本地任务。在指引旅行者穿过山间隧道前往卡拉诺斯之前，萨鲁斯会要求他们将一捆补给包带给埃里克·亮锤，一位刚在村庄外扎营的新人。",kw={"寒脊山小径","丹莫罗","埃里克·亮锤","卡拉诺斯","巡山人萨鲁斯","补给包","冒险者"},ang={["faction:Alliance"]="巡山人依靠联盟新兵在冰雪覆盖的道路上运送关键补给品，以确保在卡拉诺斯外围游历的盟友能够获得足够的物资。",["race:Dwarf"]="对于离开寒脊山谷的年轻矮人来说，将物资带给埃里克·亮锤标志着他们与巡山人在广阔的丹莫罗大地上进行的首次合作。"},sec={{t="帮巡山人的忙",b="守卫寒脊山谷与广阔的丹莫罗雪原之间的高地关隘和隧道，对于铁炉堡巡山人来说是一项艰巨的工作。巡山人萨鲁斯驻扎在边境大门，时刻警惕着当地的危险和沿小径经过的旅行者。当哨所收到关于一名独自的冒险者抵达卡拉诺斯附近的消息时，萨鲁斯便会委托值得信赖的过路人将必要的补给品运送过去，以支援那些深入冰封峭壁的新人。"},{t="送往卡拉诺斯的补给品",b="从南部关隘蜿蜒而下的道路通往卡拉诺斯定居点，这里是丹莫罗中部矮人手工艺和旅行的主要枢纽。埃里克·亮锤最近在村庄外围扎下了营地。通过将巡山人的补给包送到他手中，旅行者们协助在偏远的哨兵与活跃在荒野中的人们之间建立起了一条重要的纽带。"}},faq={{q="谁发布了 冒险者 这个任务？",a="巡山人萨鲁斯发布了这个任务。他驻守在连接寒脊山谷小径与广阔丹莫罗的山隘大门处。",al={"任务发布者","谁发布 冒险者","萨鲁斯任务"}},{q="埃里克·亮锤是谁？",a="埃里克·亮锤是一位最近抵达矮人城镇卡拉诺斯外围的冒险者。巡山人萨鲁斯派遣旅行者给他带去了一份必要的补给包。",al={"埃里克·亮锤在哪里","谁是 冒险者","亮锤"}},{q="这次运送的地点在哪里？",a="运送地点位于丹莫罗的卡拉诺斯外围，在巡山人萨鲁斯驻守的寒脊山小径隧道的北面。",al={"在哪里交付补给品","埃里克·亮锤的位置","补给包掉落"}},{q="巡山人萨鲁斯为什么要运送补给品？",a="巡山人时刻关注着丹莫罗各地的旅行者。当萨鲁斯得知一名冒险者在卡拉诺斯附近扎营后，他便安排人手运送物资，以支持他在严寒中的生活。",al={"为什么要运送补给品","萨鲁斯的目的","补给包的原因"}},{q="你携带的是什么物品？",a="你携带的是由巡山人萨鲁斯直接提供的补给包，你需要将其交给埃里克·亮锤。",al={"什么补给品","补给包物品"}},{q="部落玩家可以接取这个任务吗？",a="不可以。巡山人萨鲁斯是丹莫罗的一名联盟阵营矮人卫兵，因此该任务仅限联盟阵营。",al={"部落可以做这个吗","是否仅限联盟","部落的冒险者任务"}}},fx={["95095969"]={q="巡山人萨鲁斯为什么请你运送补给？",a="巡山人萨鲁斯和他的巡逻队驻守在山口，负责监视道路，保护隧道免受当地危险的侵扰。因为你本就要穿过山口，继续前往卡拉诺斯，他便请你顺路运送补给，以免将手下的巡山人从哨位上调走。",al={"冒险者为什么选我","萨鲁斯为什么需要我","为什么派玩家去找艾瑞克·亮锤"}}},fp="14,201,28.398.0,21.296.0,36.135.0,25.142.0,36.164.0,43.175.0,27.71.0,41.107.0"}
P.entries["quest:96629"] = {n="Camping 101: Cooking",s="《Camping 101: Cooking》向丹莫罗的冒险者介绍了烹饪这项基本的生存技能。除了准备补给品，学习这项专业还能让旅行者点燃篝火，作为野外营地的基石。",h="《Camping 101: Cooking》向丹莫罗的冒险者介绍了烹饪这项基本的生存技能。除了准备补给品，学习这项专业还能让旅行者点燃篝火，作为野外营地的基石。",kw={"篝火","露营","烹饪","丹莫罗","陈设","格雷姆罗克·匹斯诺尔","卡拉诺斯","荒野"},ang={["class:Priest"]="即使是虔诚的圣光信徒，在远离神殿和定居点旅行时，也必须掌握生火等基本的生存技能。",["faction:Alliance"]="在丹莫罗附近起步的联盟冒险者会向卡拉诺斯的矮人导师学习丛林生存和烹饪的基础知识。",["profession:Cooking"]="烹饪提供了建立野外营地和放置营地陈设所必需的基础篝火。"},sec={{t="野外篝火",b="对于任何在荒野中跋涉的旅行者来说，建立可靠的营地始于火焰。在丹莫罗，新手冒险者会被指引前往卡拉诺斯，在格雷姆罗克·匹斯诺尔的指导下学习烹饪基础。烹饪不仅仅是为了在旅途中用热食填饱肚子；坚固的篝火是任何户外营地实质且实用的核心。"},{t="扩展营地",b="新学的篝火可以让冒险者在开阔的荒野中搭建简陋的营地。虽然简易的炉火只能支撑最基本的陈设，但提高烹饪熟练度可以解锁建造更大篝火的能力。此外，精通其他制造专业的工匠可以制作额外的陈设，将简单的休息点变成设施齐全的驻地。"}},faq={{q="《露营 101: 烹饪》任务是什么？",a="《露营 101: 烹饪》是一个教学任务，向冒险者介绍烹饪这一基本专业，将其作为野外生存和营地搭建的基石。",al={"什么是露营101 烹饪","任务目标","露营基础烹饪"}},{q="格雷姆罗克·匹斯诺尔是谁？",a="格雷姆罗克·匹斯诺尔是位于丹莫罗卡拉诺斯的当地烹饪训练师，他教导新手如何准备食物和建造篝火。",al={"谁在卡拉诺斯教授烹饪","格雷姆罗克·匹斯诺尔的位置","丹莫罗烹饪训练师"}},{q="为什么露营需要烹饪？",a="烹饪能让冒险者建造基本的篝火，这是搭建野外营地并放置营地陈设的核心基础。",al={"为什么露营需要烹饪","篝火的作用","烹饪与营地"}},{q="可以在哪里建立营地？",a="一旦你掌握了生火技巧，就可以在荒野中搭建一个基础营地，为旅途提供休息之处。",al={"在哪里可以扎营","营地规则","搭建营地"}},{q="如何改进或扩展营地？",a="提升烹饪技能可以让你建造更大的篝火，而学习其他制造专业则能让你制作并放置更多的营地陈设。",al={"如何升级营地","更大的篝火","更多营地装饰"}},{q="其他专业能对露营有帮助吗？",a="如果你精通其他专业，其他商业技能训练师可以传授为你营地制作陈设的基础知识。",al={"谁提供营地陈设","商业技能营地物品","其他营地训练师"}}},fp="20,225,22.208.0,22.298.0,39.91.0,24.79.0,37.91.0,36.115.0,40.122.0,44.105.0"}
P.entries["quest:96630"] = {n="The Adventurer",s="“The Adventurer”是一个发生在泰达希尔的简短任务，涉及在野外发现一本丢弃的日志。这本朴素的笔记本记录了一名不知名旅行者平凡的旅程和露营经历，需要将其送到多兰纳尔附近的莱琳娜·暮刃手中。",h="“The Adventurer”是一个发生在泰达希尔的简短任务，涉及在野外发现一本丢弃的日志。这本朴素的笔记本记录了一名不知名旅行者平凡的旅程和露营经历，需要将其送到多兰纳尔附近的莱琳娜·暮刃手中。",kw={"露营","多兰纳尔","日志","丢失的日志","莱琳娜·暮刃","泰达希尔","冒险者"},ang={["faction:Alliance"]="对于那些在世界之树下刚刚起步的联盟新手来说，将遗失物品归还给同行的旅行者有助于维护树林中的秩序。",["race:NightElf"]="在泰达希尔巡逻的年轻暗夜精灵经常会发现旅行者经过的痕迹，他们会将捡到的遗失私人物品交给像莱琳娜·暮刃这样的流浪者。"},sec={{t="流浪者日志",b="在泰达希尔茂密的枝叶和盘根错节的树根间，旅行者偶尔会偶然发现遗弃的私人物品。这本简单的日志记录了一名无名冒险者平凡却真挚的流浪生活。书中大部分页面并没有记录什么宏大的英雄事迹或危险的怪物狩猎，而是热情地记载了在暮色树冠下露营的简单快乐。"},{t="送往多兰纳尔",b="发现者没有让这件私人物品在潮湿的荒野中风化，而是选择将其带往多兰纳尔。驻扎在暗夜精灵定居点附近的莱琳娜·暮刃是这些散落页面的接收者，她或许能通过这些记录了解这位逝去之人的旅程，并给予其慰藉。"}},faq={{q="任务中提到的日志是什么？",a="这是一本在泰达希尔野外发现的朴素个人笔记本。其中的条目详细记录了一个陌生人的平静生活和旅程，突显了平凡的冒险以及对户外露营的持久热爱。",al={"遗失的日志","这是什么书","冒险者日志"}},{q="莱琳娜·暮刃是谁？",a="莱琳娜·暮刃是一位出现在多兰纳尔附近的暗夜精灵。她是这本在森林中找到的遗失日志的预期接收者。",al={"莱琳娜","莱琳娜·暮刃在哪里","任务上交角色"}},{q="这个任务发生在哪里？",a="该任务发生在暗夜精灵的巨枝泰达希尔，主要集中在多兰纳尔村周围的荒野地区。",al={"冒险者任务在哪里","任务区域"}},{q="日志中是否描述了危险的怪物或战斗？",a="没有。书写的内容被描述为相当平淡，主要集中在一名不知名人士平庸的生活和流浪经历上，特别强调了露营是多么令人愉悦。",al={"日志背景故事","日志里有什么","它写了什么"}},{q="谁可以完成这项任务？",a="这项任务仅限在泰达希尔新手区游荡的联盟成员，特别是那些在多兰纳尔附近探险的暗夜精灵新手。",al={"部落可以做这个任务吗","联盟任务"}},{q="为什么要将日志上交到多兰纳尔？",a="多兰纳尔是泰达希尔该地区主要的集散地和十字路口，因此那里是归还遗失私人物品最合理的地方，而且莱琳娜·暮刃就在附近等待接收这本日志。",al={"为什么是多兰纳尔","为什么找莱琳娜"}}},fp="14,156,20.179.0,20.163.0,43.152.0,25.83.0,33.65.0,56.125.0,27.106.0,36.135.0"}
P.entries["quest:96634"] = {n="Camping 101: Cooking",s="“Camping 101: Cooking”是一项入门任务，旨在通过烹饪艺术教导冒险者野外露营的基本知识。通过向多兰纳尔的扎瑞恩等当地训练师学习如何生火，旅行者可以建立起搭建野外营地的必要基础。这是掌握户外生存技能并布置个人营地的第一步。",h="“Camping 101...",kw={"篝火","露营101","营地","烹饪","多兰纳尔","家具","野外生存","扎瑞恩"},ang={["profession:Cooking"]="烹饪是野外生存的基础学科，提供了锚定任何户外营地所需的篝火。提升烹饪技艺可以让冒险者建造更大、更耐用的篝火。",["race:NightElf"]="途经多兰纳尔的暗夜精灵新手冒险者，在深入泰达希尔的荒野之前，通常会先向扎瑞恩学习野外生存和生火的基本知识。"},sec={{t="荒野之炉",b="每一次穿越荒野的长途跋涉，都始于能够燃起一堆温暖篝火的能力。在“Camping 101: Cooking”中，初出茅庐的冒险者会被引导去寻求烹饪训练，作为他们野外生存技巧的第一课。学习烹饪不仅仅是为了用野生猎物烹制食物；点燃基础篝火这一核心技能，是任何户外营地在物理和实践层面上的锚点。如果没有篝火来驱散寒冷和黑暗，在荒野中建立一个可靠的营地是不可能的。"},{t="扩建营地",b="学会点燃基础篝火，就具备了在荒野各处建立简易营地的能力。虽然初级营地只能容纳少数简陋的家具，但专心致志的冒险者可以扩展其功能。随着冒险者磨练烹饪熟练度，他们将解锁点燃更大、更稳固篝火的方法。此外，精通其他专业技能的工匠可以咨询各自的训练师，学习如何制作家具和改良设施，从而充实他们的营地。"}},faq={{q="“露营 101: 烹饪”的目的是什么？",a="“露营 101: 烹饪”通过指导冒险者学习烹饪专业，向他们介绍野外生存的基本知识。建立篝火是你在荒野中任何地方搭建营地的核心基础。",al={"这个任务有什么用","露营101: 烹饪 的目的","为什么要完成 露营101"}},{q="扎瑞恩是谁？",a="扎瑞恩是一位位于泰达希尔的多兰纳尔的烹饪训练师。他教导新手冒险者烹饪艺术的基础知识，以及如何搭建基础篝火。",al={"扎瑞恩是谁","扎瑞恩 多兰纳尔","多兰纳尔的烹饪训练师在哪里"}},{q="如何在荒野中搭建营地？",a="搭建营地始于通过烹饪专业学会的建立基础篝火。虽然基础训练允许你带着简单的家具在野外露营，但提升你的技能可以解锁更大的篝火和额外的营地改进。",al={"如何搭建营地","露营是如何运作的","建立一个营地"}},{q="可以为营地添加家具吗？",a="虽然烹饪提供了固定营地的篝火，但艾泽拉斯各地的其他专业技能训练师可以教导熟练的工匠如何用专门的装备和装饰来布置和升级他们的营地。",al={"营地布置","营地装饰","其他专业的营地家具"}},{q="为什么露营需要烹饪？",a="烹饪教导冒险者如何在野外搭建和维护露天篝火。因为火是任何户外营地的核心，学习烹饪是进行正规野外露营的第一步。",al={"为什么露营需要烹饪","烹饪与露营的联系"}},{q="可以制造更大的篝火吗？",a="可以。当你练习烹饪技艺并提升烹饪等级时，你可以学习如何建造更大的篝火，以更好地支持你的野外营地。",al={"我可以制造更大的篝火吗","如何升级篝火"}}},fp="20,180,22.333.0,22.297.0,44.101.0,14.121.0,44.196.0,41.154.0,36.163.0,30.87.0"}
P.entries["quest:96638"] = {n="The Adventurer",s="“The Adventurer”是泽风岛上的一项引导旅程任务。该任务由森达尔林地的Aetheen of the Gales发布，引导初出茅庐的游荡者向西南方前往申达尔村，去拜访一位了解荒野的露营老手Raan Wildwind。",h="“The Adventurer”是泽风岛上的一项引导旅程任务。该任务由森达尔林地的Aetheen of the Gales发布，引导初出茅庐的游荡者向西南方前往申达尔村，去拜访一位了解荒野的露营老手Raan...",kw={"狂风艾瑟恩","拉恩·狂风","申达尔村","冒险者","森达尔林地","泽风岛"},ang={["race:Skyborne"]="对于从森达尔林地遮蔽的树冠下走出的年轻天裔来说，与Raan Wildwind的相遇标志着他们迈向岛屿家园更广阔、未被驯服地域的第一步。"},sec={{t="离开林地",b="虽然森达尔林地提供了庇护和安静的避风港，但泽风岛更广阔的区域依然狂野且充满危险。Aetheen of the Gales注视着初学者，观察着他们何时准备好跨出熟悉的边界。对于那些寻求名声、财富或目标的人来说，留在这片林地的庇护范围内已不再足够。"},{t="道路上的向导",b="在林地西南方向通往申达尔村的路上，另一位旅行者已经扎下了营地。Raan Wildwind曾花时间在安全区外探索，历经艰险。寻找他能为新兴的游荡者们提供关于森达尔林地以外生存的实用入门知识，并向已经在大道上历练过的人学习。"}},faq={{q="谁派你去寻找拉恩·狂风？",a="疾风使者艾希恩在森达尔林地内发布该任务。在你证明了自己的实力后，她会鼓励你寻找一位对这片广阔岛屿有着第一手经验的人。",al={"谁发布冒险者","谁开启冒险者任务","艾瑟恩任务"}},{q="拉恩·狂风在哪里？",a="拉恩·狂风在森达尔林地西南方扎下了营地，位置就在通往申达尔村的主路旁。",al={"拉恩·狂风位置","拉恩在哪里","如何找到拉恩·狂风"}},{q="这项任务的目的是什么？",a="它起到了引导作用，将旅行者带出森达尔林地的安全区，并让他们与更深入泽风岛的导师和挑战建立联系。",al={"为什么要做冒险者","冒险者任务目的","拉恩教什么"}},{q="在领取此任务前必须完成什么前提条件？",a="你必须为疾风使者艾希恩完成有关邪恶主母的任务，之后她才会指引你沿路前往拉恩·狂风处。",al={"冒险者前置条件","冒险者要求"}},{q="申达尔村对旅行者来说安全吗？",a="申达尔村位于拉恩的营地之外，在森达尔林地向西南延伸的道路尽头。虽然它是岛上一个显著的定居点，但年轻的冒险者在道路和周围荒野行进时仍需保持谨慎。",al={"申达尔安全吗","申达尔村是什么"}},{q="拉恩·狂风是谁？",a="拉恩·狂风是一位勇敢的游荡者，他冒险离开森达尔林地，在申达尔村外建立了营地，为沿途的新人提供建议和任务。",al={"拉恩背景故事","拉恩·狂风是谁"}}},fx={dc12ab9c={q="烈风艾瑟恩为什么派你去寻找拉恩·狂风？",a="艾瑟恩注意到，越来越多的流浪者为了追逐荣耀与财富，踏出森达尔林地的安全地带。艾瑟恩知道荒野对缺乏经验的人来说十分危险，因此想让你去寻找同为旅人的拉恩·狂风。他在申达尔村附近扎营，可以传授实用的知识和生存经验，帮助你在岛上的旅途中活下来。",al={"艾瑟恩为什么派你去","疾风艾瑟恩的动机","为什么要见拉恩·狂风"}}},fp="14,209,17.275.0,19.252.0,36.189.0,31.96.0,33.100.0,64.113.0,39.179.0,21.174.0"}
P.entries["quest:96646"] = {n="Camping 101: Cooking",s="Camping 101: Cooking 是一项入门任务，向冒险者传授烹饪艺术，作为荒野生存的重要基石。通过向申达尔村的 Zerril Softbreeze 学习如何生起篝火，旅行者将解锁在野外搭建营地的能力。",h="Camping 101: Cooking 是一项入门任务，向冒险者传授烹饪艺术，作为荒野生存的重要基石。通过向申达尔村的 Zerril Softbreeze 学习如何生起篝火，旅行者将解锁在野外搭建营地的能力。",kw={"篝火","露营","营地","烹饪","陈设","申达尔村","泽里尔·柔风"},ang={["profession:Cooking"]="学习基础烹饪提供了建造篝火所需的基本知识，从而为任何野外营地建立起中心支柱。"},sec={{t="荒野炉火",b="对于行走在荒蛮之地的冒险者来说，生存之道始于炉火。Camping 101: Cooking 为游荡者介绍了烹饪工艺的艺术，这不仅是为了准备食物，更是因为掌握基本的生火技巧是建立野外安全休息点的第一步。"},{t="营地基础",b="有志于露营的冒险者需要前往申达尔村寻找 Zerril Softbreeze，学习烹饪行业的入门知识。一旦冒险者掌握了如何点燃篝火，他们就获得了在荒野各处建立小型营地的能力。虽然简陋的营地只能提供最基本的陈设，但提升工艺水平可以让你通过其他专业技能的辅助，生起更大的篝火并进行更丰富的布置。"}},faq={{q="什么是 露营 101: 烹饪？",a="这是一项野外生存入门教学，教导冒险者烹饪艺术和点燃基础篝火如何成为建立营地的核心基础。",al={"什么是 露营101 烹饪","露营烹饪任务"}},{q="泽里尔·柔风 是谁？",a="泽里尔·柔风 是一位位于申达尔村的烹饪训练师，负责指导新手掌握基本的烹饪艺术以及如何生起篝火。",al={"泽里尔·柔风 是谁","申达尔村烹饪训练师"}},{q="为什么建立营地需要学习烹饪？",a="烹饪教导冒险者如何建造并维护篝火，这是建立任何野外营地的核心基础。",al={"为什么要学烹饪来露营","为什么露营需要烹饪"}},{q="泽里尔·柔风 在哪里？",a="可以在申达尔村找到正在传授专业技能的 泽里尔·柔风。",al={"泽里尔·柔风 在哪里","申达尔村位置"}},{q="营地如何进行装饰？",a="新手可以在他们的篝火旁放置基础陈设，但学习其他工匠训练师的专业技能后，冒险者将能够制作并布置更多的营地陈设。",al={"营地陈设","如何装饰营地"}},{q="篝火可以升级吗？",a="通过提升你的烹饪技能，你可以学会如何生起更大的篝火，从而改善你的野外营地。",al={"更大的篝火","升级营地"}}},fp="20,166,22.159.0,27.323.0,29.97.0,25.74.0,41.81.0,35.41.0,31.82.0,26.64.0"}
P.entries["quest:96652"] = {n="The Adventurer",s="在探索杜隆塔尔崎岖荒野的过程中，旅人们无意间发现了一本朴素且被遗弃的日记，记录着一位陌生人平静的旅途。日记的字里行间流露出对户外生活的热爱，以及在星空下露营的惬意，并提到要将其送交到剃刀岭附近的布拉克手中。",h="在探索杜隆塔尔崎岖荒野的过程中，旅人们无意间发现了一本朴素且被遗弃的日记，记录着一位陌生人平静的旅途。日记的字里行间流露出对户外生活的热爱，以及在星空下露营的惬意，并提到要将其送交到剃刀岭附近的布拉克手中。",kw={"冒险者","布拉克","露营","杜隆塔尔","日记","遗失的日记","剃刀岭"},ang={["class:Hunter"]="那些一生都在野外求生的猎人，很容易对日记中反复提及的荒野露营之乐产生共鸣。",["faction:Horde"]="杜隆塔尔干旱的道路上有许多新兵行走；回收遗失的财物并将其交给像剃刀岭附近的布拉克这样的流浪者，有助于维护中部边境的秩序。"},sec={{t="流浪者的笔记",b="杜隆塔尔是一片严酷的土地，生存通常远比悠闲的旅行重要，因此发现一本流浪记述者的书是一件罕见的事。这本朴素的日记孤零零地躺在红色的尘土中，记载着一位对于部落的普通英雄来说完全陌生的人的所思所想和经历。日记中没有详述血腥的战斗或宏大的战役，而是沉浸在露宿荒野和野外露营的平凡乐趣之中。"},{t="送交布拉克",b="无论这本笔记出自谁之手，他都留下了一些线索——或是某种联系——指向了布拉克，一位在剃刀岭定居点附近露营的冒险者。将遗失的旅人私人物品送还给那些熟悉道路的人，往往是分散的流浪者寻回财物，或者至少被那些守望尘土飞扬的道路的人们所铭记的唯一途径。"}},faq={{q="遗失的日记里有什么？",a="这本书内容极其普通，写满了关于一位默默无闻的冒险者平静经历的日常条目。特别是在字里行间，反复强调了在荒野中扎营的简单快乐与乐趣。",al={"日记里说了什么","遗失日记的内容","日记文本"}},{q="谁写了这本日记？",a="在寻获的书页中，作者的身份依然是个谜；它描述了在你于荒野中发现这本书之前，从未听说过的一个人的生活和旅程。",al={"冒险者是谁","遗失日记的作者","谁写了这本书"}},{q="布拉克是谁？",a="布拉克是一位在杜隆塔尔中部剃刀岭附近露营的冒险者，他负责接收这本遗失的日记。",al={"布拉克 剃刀岭","布拉克是谁","布拉克在哪里"}},{q="日记在哪里找到？",a="这本朴素的日记被发现遗弃在杜隆塔尔的地形之中，等待着路过的部落旅人将其寻回。",al={"我在哪里可以找到日记","遗失日记的位置","冒险者任务起始"}},{q="布拉克为什么关心这本日记？",a="任务中并未提及。布拉克是一位经验丰富的冒险者，在剃刀岭外露营，专门教导新手基本的露营技巧，因此一本写满露营故事的日记对他来说十分受用。",al={"为什么要带给布拉克","布拉克的用途","布拉克的日记"}},{q="写日记的冒险者有危险吗？",a="寻获的书页并未显示有任何不测，仅仅记录了关于露营的美好回忆。然而，在杜隆塔尔的红尘中遗落旅行日记，暗示着作者要么是不小心弄丢了，要么是意外离开了。",al={"作者还活着吗","冒险者死了吗","遗失冒险者的状态"}}},fp="14,158,18.287.0,17.206.0,32.121.0,22.106.0,13.99.0,27.95.0,39.185.0,41.136.0"}
P.entries["quest:96655"] = {n="Camping 101: Cooking",s="Camping 101: Cooking向冒险者介绍了荒野生存的基本技能。通过指引旅行者前往剃刀岭的厨师托尔卡处，它教授了烹饪和篝火制作的基础知识，这是在野外建立个人营地的必要条件。",h="Camping 101: Cooking向冒险者介绍了荒野生存的基本技能。通过指引旅行者前往剃刀岭的厨师托尔卡处，它教授了烹饪和篝火制作的基础知识，这是在野外建立个人营地的必要条件。",kw={"篝火","露营101","露营101: 烹饪","营地","厨师托尔卡","烹饪","杜隆塔尔","陈设","剃刀岭"},ang={["faction:Horde"]="在杜隆塔尔各地开始冒险的冒险者可以向剃刀岭的厨师托尔卡报到，学习烹饪这一基础行业。",["profession:Cooking"]="烹饪是建造基本篝火的核心要求，也是荒野生存和建立营地不可或缺的锚点。"},sec={{t="荒野炉火",b="对于任何踏出定居点大门的漫游者来说，在荒野中生存需要的不仅仅是锋利的钢铁和坚固的护甲。任务Camping 101: Cooking指引初露头角的冒险者前往剃刀岭的厨师托尔卡处学习烹饪艺术。在杜隆塔尔及更远处的开阔荒野中，烹饪不仅意味着准备热腾腾的饭菜，它更是点燃可靠篝火所需的基本准则，而篝火是任何营地的核心。"},{t="建立和布置营地",b="掌握了这些基础知识，旅行者几乎可以在边境的任何地方搭建一个简陋的营地。虽然新手篝火只能支持少数基本陈设，但对这项工艺的进一步钻研会开启新的可能性。加深烹饪专精可以建造更大的火堆，而追求其他商业技能则提供了布置营地所需的工艺，并将其增强为对抗蛮荒野外的坚固堡垒。"}},faq={{q="什么是露营 101: 烹饪任务？",a="露营 101: 烹饪是一项入门任务，教授冒险者户外生存的基础知识。通过学习烹饪和篝火制作，冒险者获得了在野外任何地方建立自己营地的能力。",al={"什么是露营101 烹饪","露营101 烹饪任务","这个任务有什么作用"}},{q="谁是厨师托尔卡？",a="厨师托尔卡是位于杜隆塔尔剃刀岭的部落烹饪训练师。他教授有抱负的冒险者烹饪专业的基础知识，以及如何点燃基本的篝火。",al={"谁在剃刀岭教授烹饪","谁是厨师托尔卡","厨师托尔卡在哪里"}},{q="为什么露营需要烹饪？",a="烹饪不仅仅是为了准备食物；通过烹饪制作的篝火是搭建营地的基础锚点。没有火，在野外就无法维持一个像样的营地。",al={"为什么露营需要烹饪","烹饪与篝火的联系","露营需要烹饪吗"}},{q="冒险者可以在哪里搭建营地？",a="一旦你学会了烹饪和篝火制作的基础知识，你就能在开阔的荒野中几乎任何地方搭建一个小营地。初始营地非常基础，无法容纳很多陈设。",al={"我可以在哪里露营","露营是如何运作的","营地放置"}},{q="如何升级你的篝火？",a="随着你提高烹饪专业的熟练度，你可以学会建造更大、更持久的篝火，从而获得更强的营地能力。",al={"更大的篝火","升级篝火","如何改善营地"}},{q="如何获得营地的陈设？",a="虽然烹饪提供了篝火基础，但世界各地的其他商业技能训练师可以教授冒险者如何制作和放置额外的陈设，以定制和扩展他们的营地。",al={"营地装饰","布置营地","营地陈设训练师"}}},fp="20,131,22.315.0,30.329.0,39.148.0,18.139.0,36.149.0,42.177.0,33.133.0,45.155.0"}
P.entries["quest:96656"] = {n="The Adventurer",s="The Adventurer 是执行官阿伦交给丧钟镇外经验丰富的年轻被遗忘者勇士的一项入门任务。在打击血色十字军的行动中证明了可靠性后，你被派往布瑞尔方向的道路上，调查在定居点附近徘徊的陌生人。这项任务并没有让你发现又一个狂热间谍，而是让你接触到了 Eleanor Shackleton，一位渴望传授野外生存实用技能的独立旅行者。",h="The Adventurer...",kw={"布瑞尔","露营","丧钟镇","埃莉诺·沙克尔顿","执行官阿伦","血色十字军","冒险者","户外天地","提瑞斯法林地"},ang={["faction:Horde"]="虽然执行官阿伦守卫着被遗忘者领土的新生边界，但与流浪的生存专家进行和平对话，能为部落的新手们获得宝贵的实用技能。",["race:Undead"]="对于刚走出丧钟镇的被遗忘者来说，遇见像 Eleanor 这样的被遗忘者冒险家，是让他们了解到并非布瑞尔附近的所有陌生人都是血色间谍的一门早期课程。"},sec={{t="可疑的监视",b="执行官阿伦时刻警惕着丧钟镇及其周边的动向。由于血色十字军积极地在这一地区进行侦察并渗透进洛丹伦北部，任何在布瑞尔附近游荡的陌生人都必须受到立即审查。既然你已经通过清除边境上的十字军威胁证明了自己的忠诚，阿伦便转而让你秘密调查这位未知的人物，以确定她是否对被遗忘者构成潜在威胁。"},{t="林间的旅行者",b="当你循迹在布瑞尔附近的路上找到 Eleanor Shackleton 时，她的意图与十字军的狂热阴谋或天灾军团的死灵法术毫无关联。作为一名在踏上前往荒野的下一次旅程前稍作停顿的被遗忘者，Eleanor 仅仅是一位冒险者。相反，她从被派来盘问她的人身上认出了冒险者的火花，并提出分享在开阔荒野中生存和建立营地的实用基本常识。"}},faq={{q="为什么执行官阿伦要调查 埃莉诺？",a="丧钟镇和布瑞尔不断受到血色十字军渗透者和敌对间谍的威胁。任何在高路上徘徊的陌生人，在证实其动机无害之前，都会被视为可疑对象。",al={"为什么要调查 埃莉诺","谁派我去见 埃莉诺","阿伦 埃莉诺 任务"}},{q="埃莉诺·沙克尔顿 是谁？",a="埃莉诺·沙克尔顿 是一位在布瑞尔附近的道路旁露营的独立冒险者。她对血色十字军没有任何忠诚，一心专注于探索荒野，并向其他旅行者分享生存经验。",al={"埃莉诺 是谁","埃莉诺·沙克尔顿 传说","冒险者 角色 是谁"}},{q="埃莉诺 与血色十字军有关联吗？",a="没有。抵达她的营地后，埃莉诺 很快澄清说，她与威胁提瑞斯法林地的狂热十字军没有任何从属关系。",al={"埃莉诺 是血色十字军吗","埃莉诺 敌人","埃莉诺 是间谍吗"}},{q="这个任务通向哪里？",a="向 埃莉诺 报告后会开启任务“户外活动”，在那里她会开始教你野外生存和搭建营地的基础知识。",al={"冒险者 之后是什么","冒险者 之后的任务","埃莉诺·沙克尔顿 后续"}},{q="在哪里可以找到 埃莉诺·沙克尔顿？",a="她在通往提瑞斯法林地布瑞尔镇的主路旁扎营。",al={"埃莉诺 位置","埃莉诺·沙克尔顿 在哪里","埃莉诺 提瑞斯法营地"}},{q="为什么执行官阿伦选择了你来执行这项任务？",a="你通过在丧钟镇附近清除血色十字军特工和信使的出色表现赢得了阿伦的信任，证明你有能力处理敏感的侦察工作。",al={"为什么选我","阿伦的信任","为什么执行官阿伦派你去"}}},fp="14,219,18.368.0,23.319.0,50.157.0,26.158.0,44.87.0,27.123.0,38.74.0,51.154.0"}
P.entries["quest:96658"] = {n="Camping 101: Cooking",s="学习烹饪时，一堆基础营火就能让你在坚固城墙之外露营时有火可用。在联盟和部落的土地上，烹饪训练师会教初出茅庐的冒险者如何点燃营火，为野外生活做好准备。",h="学习烹饪时，一堆基础营火就能让你在坚固城墙之外露营时有火可用。在联盟和部落的土地上，烹饪训练师会教初出茅庐的冒险者如何点燃营火，为野外生活做好准备。",kw={"营火","露营101","烹饪","闪金镇","沙克尔顿","托马斯","荒野","扎瑞恩"},ang={["faction:Alliance"]="作为一名离开北郡、丹莫罗或泰达希尔的联盟冒险者，你会被指引前往闪金镇、卡拉诺斯和多兰纳尔这样的城镇。在那里，你会先学会自力更生，再去勇闯荒野。",["faction:Horde"]="作为一名身处杜隆塔尔、莫高雷或提瑞斯法的年轻部落战士，你会被指引前往剃刀岭、血蹄村或布瑞尔的营火旁。",["profession:Cooking"]="烹饪能提供恢复体力的食物，也能让你点燃基础营火，作为野外营地的中心。"},sec={{t="荒野之炉",b="在坚固的城墙之外，营火可以烧水烤肉。当你穿行于陌生的地域并扎营歇脚时，营火的火焰便是你的炉火。"},{t="从余烬到营地",b="烹饪学徒点起的火堆很小，周围也没什么陈设。随着烹饪技艺的提升，你可以点燃更大的火堆，布置更精致的营地。其他实用专业技能会教你制作有用的陈设。"}},faq={{q="这个任务的目的是什么？",a="初出茅庐的冒险者会拜访附近定居点的烹饪训练师，学习基础烹饪，并为野外营地点燃一堆基础营火。",al={"为什么要学习 露营101","露营101 烹饪 的目的","这个任务有什么用"}},{q="谁为旅行者提供此任务？",a="经验丰富的野外向导和冒险者在双方阵营中提供这项训练。他们包括埃莉诺·沙克尔顿、艾瑞克·亮锤、莉蕾娜·暮刃、山姆·萨萨帕里拉、布拉克、卡加·野蹄和拉恩·野风。",al={"谁提供 露营101","露营任务发布者"}},{q="联盟玩家在哪里交任务？",a="联盟冒险者向各自领地内的训练师报到，例如闪金镇的托马斯、卡拉诺斯的格雷姆罗克·匹斯诺尔，或多兰纳尔的扎瑞恩。",al={"联盟在哪交任务","联盟烹饪训练师"}},{q="部落玩家在哪里交任务？",a="部落冒险者可以向剃刀岭的厨师托尔卡、布瑞尔的威廉·匹克曼，或血蹄村的派尔·沉默行者学习。",al={"部落烹饪训练师","部落在哪交任务"}},{q="营地规模以后可以扩大吗？",a="可以。随着烹饪技能的提升，你可以学会点燃更大的火堆，从而在野外支撑更多的营地设施。",al={"更大的营火","升级营地"}},{q="其他专业能对露营做出贡献吗？",a="可以。烹饪让你能够点燃基础营火，而其他专业技能则能教你制作实用的陈设，前提是你修习过这些技能。",al={"露营专业","营地设施"}}},fp="20,216,28.150.0,26.199.0,34.137.0,35.217.0,39.147.0,36.128.0,36.109.0,44.129.0"}
P.entries["quest:96659"] = {n="The Adventurer",s="当年轻的牛头人准备离开他们红云台地上的祖传训练场时，鹰风酋长请求他们帮最后一个忙。他委托他们将一份必要的补给包交给卡加·野蹄，一位驻扎在血蹄村附近、曾经在鹰风酋长过去遭遇困境时伸出援手的资深流浪者。",h="当年轻的牛头人准备离开他们红云台地上的祖传训练场时，鹰风酋长请求他们帮最后一个忙。他委托他们将一份必要的补给包交给卡加·野蹄，一位驻扎在血蹄村附近、曾经在鹰风酋长过去遭遇困境时伸出援手的资深流浪者。",kw={"血蹄村","纳拉其营地","鹰风酋长","卡加·野蹄","莫高雷","红云台地","补给包","冒险者"},ang={["faction:Horde"]="鹰风酋长确保离开新手台地的部落盟友能与莫高雷经验丰富的流浪者和哨站建立早期的联系。",["race:Tauren"]="对于第一次迈出纳拉其营地的年轻牛头人来说，向卡加·野蹄传递鹰风的荣誉债务，代表了他们为莫高雷广阔平原上的族人所做的初步贡献。"},sec={{t="酋长的报偿",b="在旅人们沿着台地小径走下莫高雷广阔平原之前，鹰风酋长停下来处理一笔未了的私人债务。早在指引纳拉其营地的新一代猎人和萨满之前，鹰风就与卡加·野蹄有过交集。在酋长口中，她是一位成就卓著的冒险者，曾在他最需要的时候提供了至关重要的帮助。听说她已经在血蹄村外扎营，鹰风便借着这些刚证明了自己的新手的离去，将物资送给这位老恩人。"},{t="离开台地",b="这个任务标志着年轻的部落勇士离开红云台地的一个关键成年礼。通往高原下的小径直达血蹄村，那里是莫高雷中部的文化和后勤中心。将补给包带过平原，连接了台地上受庇护的训练生活与牛头人部族更广阔、更野性的斗争。"}},faq={{q="卡加·野蹄是谁？",a="卡加·野蹄是一位资深的牛头人冒险者，最近在血蹄村外扎营。她与鹰风酋长有着长久的友谊，在过去几年里曾为他提供过重要的帮助。",al={"卡加·野蹄","野蹄是谁","卡加在哪里"}},{q="为什么鹰风酋长要送这些补给？",a="鹰风认为，年轻勇士动身前往血蹄村正是一个绝佳的机会，可以用来偿还对野蹄的一笔旧债，确保这位同为冒险者的朋友有足够的补给继续她的旅程。",al={"鹰风的债务","为什么送补给","补给包的用途"}},{q="卡加·野蹄的营地在哪里？",a="她的营地位于血蹄村外的平原上，从红云台地沿蜿蜒的南向小径进入莫高雷中部即可到达。",al={"卡加的营地位置","寻找卡加","血蹄村营地"}},{q="这个任务什么时候可以接到？",a="一旦旅人在红云台地上证明了自己的实力，并准备好前往莫高雷的广阔领地冒险时，鹰风酋长就会提供这项任务。",al={"什么时候接到冒险者任务","鹰风任务时机","台地出口任务"}},{q="这个任务会让你离开纳拉其营地吗？",a="是的。运送这些补给直接促使你离开纳拉其营地，踏上前往血蹄村的道路。",al={"离开红云台地","前往血蹄村的旅程"}},{q="补给包里装的是什么？",a="补给包里装满了由纳拉其营地的部族所收集的必需品，以维持冒险者在定居点之外生存的需求。",al={"补给品是什么","补给包内容物"}}},fp="14,173,23.296.0,16.244.0,21.122.0,44.92.0,38.111.0,38.117.0,48.86.0,43.94.0"}
P.entries["quest:96661"] = {n="Camping 101: Cooking",s="“Camping 101: Cooking”是一项入门任务，旨在向冒险者传授基本的烹饪知识如何成为在荒野中建立营地的基础。通过寻找血蹄村的派尔·沉默行者，旅行者们可以学习如何搭建营火来锚定他们的营地，并为边境的生活做好准备。",h="“Camping 101...",kw={"血蹄村","营火","露营入门101","营地","烹饪","家具","派尔·沉默行者","荒野"},ang={["faction:Horde"]="穿越莫高雷的冒险者将在当地牛头人工匠和厨师的指导下，在血蹄村开始他们的边境生存训练。",["profession:Cooking"]="烹饪是荒野生存的核心基石，不仅提供营养，还是点燃营火的必要技能，而营火则是建立整个营地的中心。"},sec={{t="荒野之炉",b="每一次穿越未开化荒野的长途跋涉都需要基本的荒野生存技能，而每一个真正的营地都始于火。对于踏上卡利姆多的流浪者来说，任务“Camping 101: Cooking”介绍了烹饪训练与边境生存之间的核心联系。烹饪不仅仅是烹饪猎物的肉来提供营养，它还提供了在野外环境中建造一个实用营火所需的基础知识。没有火，冒险者在夜幕降临时就无处栖身。"},{t="建立营地",b="在莫高雷的草海平原，冒险者会被指引去血蹄村寻找派尔·沉默行者学习烹饪的基础知识。通过这项基础训练，冒险者便能在荒野的任何地方点燃营火并搭建一个简单的营地。虽然最初的营地比较简陋，能放置的家具也很少，但随着烹饪技能的提升，你可以解锁更大营火的秘诀。与此同时，精通其他行业的工匠可以制作家具来充实他们的边境哨所。"}},faq={{q="什么是“露营101：烹饪”？",a="“露营101：烹饪”是一项入门任务，它教导冒险者烹饪和生火是如何成为荒野生存的真正基石的。通过学习烹饪，冒险者将获得在野外制造营火和建立营地的能力。",al={"什么是露营101 烹饪","露营烹饪任务","露营烹饪基础"}},{q="谁是派尔·沉默行者？",a="派尔·沉默行者是一位位于莫高雷血蹄村的烹饪训练师。他指导新手冒险者进行烹饪艺术的学习，并教导他们如何建造基础的营火。",al={"谁是派尔·沉默行者","派尔·沉默行者位置","血蹄村烹饪训练师"}},{q="为什么学习露营需要烹饪？",a="在荒野中，烹饪不仅仅是为了准备食物；学习烹饪可以教冒险者如何点燃营火，这正是任何营地的物理和实际锚点。",al={"为什么露营需要烹饪","为什么为了露营要学烹饪","营火与露营的联系"}},{q="随着技能提高，可以制造更大的营火吗？",a="随着你的进步并提升烹饪技能，你将掌握建造更大、更坚固营火所需的知识，从而允许在荒野中进行更完善的营地设置。",al={"可以升级营火吗","更大的营火","如何制作更大的火"}},{q="如何布置营地？",a="虽然营火是营地的核心锚点，但如果你接受过其他工艺的训练，你也可以向世界各地的其他专业训练师学习额外的家具和饰品制作方法。",al={"营地家具如何运作","营地装饰","通过专业技能布置营地"}},{q="可以在哪里搭建营地？",a="一旦你通过基础烹饪训练掌握了如何点燃营火，你就可以在旅途所及的任何开阔荒野中建立一个简陋的营地。",al={"哪里可以放置营地","可以随处露营吗","营地限制"}}},fp="20,177,22.243.0,17.274.0,29.84.0,26.132.0,42.95.0,53.95.0,30.107.0,28.125.0"}
P.entries["quest:967"] = {n="奥萨拉克斯之塔",s="这个任务将黑海岸北部对暗滩教派的调查与整个卡利姆多北部的防御行动联系在了一起。巴苏尔·影击派遣一名联盟信使向南前往灰谷的迈斯特拉岗哨，向他的导师净化者德尔格伦警示教派在奥萨拉克斯之塔的可疑集会。",h="这个任务将黑海岸北部对暗滩教派的调查与整个卡利姆多北部的防御行动联系在了一起。巴苏尔·影击派遣一名联盟信使向南前往灰谷的迈斯特拉岗哨，向他的导师净化者德尔格伦警示教派在奥萨拉克斯之塔的可疑集会。",kw={"灰谷","巴苏尔·影击","暗滩","黑海岸","净化者德尔格伦","圣光","迈斯特拉岗哨","奥萨拉克斯之塔"},ang={["class:Paladin"]="见到德尔格伦为圣骑士们提供了一个在陌生土地上实践神圣使命的鼓舞人心的榜样：一位人类十字军挥舞着圣光，赢得了卡利姆多隐居的暗夜精灵们的深深信任。",["faction:Alliance"]="巴苏尔在黑海岸与德尔格伦在灰谷之间的合作，展示了将卡利姆多北部散落的联盟驻军联系在一起的重要通讯线。",["race:NightElf"]="对于暗夜精灵来说，这项任务凸显了她们的哨兵与那些前来帮助肃清林中恶魔残余的东部王国种族之间日益增长且务实的伙伴关系。"},sec={{t="请求增援",b="在与奥萨拉克斯之塔周围的暗滩教派成员进行初步交锋后，暗夜精灵侦察兵巴苏尔·影击意识到这一威胁已超出了他独自一人所能应对的范畴。为了组织起决定性的反击，他写了一份详细的报告，并将其托付给一名联盟信使，带给他效忠的导师——净化者德尔格伦。由于教派的召唤者们每小时都在变得更加猖狂，必须将消息传达给那些有能力指挥肃清行动的资深领袖。"},{t="通往灰谷之路",b="传递巴苏尔的信件需要跋涉过整个黑海岸，沿着漫长的海岸公路向南走出迷雾，穿过森林边界进入灰谷。净化者德尔格伦驻扎在西侧道路旁的迈斯特拉岗哨，他致力于净化徘徊在林地中的恶魔与亡灵。尽管最初并不了解暗夜精灵的风俗，这位人类圣骑士还是与哨兵建立了深厚的相互尊重关系，成为了不可或缺的盟友。"},{t="觉醒的神圣战士",b="德尔格伦神色严峻地收到了巴苏尔的紧急信件。作为一名忠诚于圣光的战士，他将黑暗教派、灵魂腐蚀以及恶魔爪牙出现在这片古老森林中视为一种不可容忍的亵渎。在读到关于暗滩教派在废墟般的上层精灵之塔中已根深蒂固的消息后，德尔格伦立即准备接管行动并进行反击。"}},faq={{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷迈斯特拉岗哨的人类圣骑士。他忠诚于圣光，向暗夜精灵哨兵提供他的军事与精神专长，以肃清侵蚀她们祖传森林的恶魔和亡灵。",al={"净化者德尔格伦","德尔格伦是谁","德尔格伦背景故事"}},{q="巴苏尔·影击为什么要给灰谷发送信使？",a="巴苏尔是驻扎在奥萨拉克斯之塔外的一名侦察兵，一直在研究暗滩教派。他意识到该教派的黑暗仪式与人数正在迅速升级，因此将他的发现发给他的导师德尔格伦，以便组织一场有计划的突袭。",al={"为什么给德尔格伦送信","巴苏尔送信原因"}},{q="巴苏尔与德尔格伦是什么关系？",a="德尔格伦是巴苏尔的导师。这位人类圣骑士教导了这位暗夜精灵战斗的艺术，并将他引向圣光的教义，跨越了他们的文化隔阂，建立了不同寻常的亲密纽带。",al={"巴苏尔与德尔格伦","巴苏尔与德尔格伦如何认识"}},{q="迈斯特拉岗哨在哪里？",a="迈斯特拉岗哨是位于灰谷西部、沿着从黑海岸通往南方的干道上的一个联盟前哨站。它是往来于黑海岸与森林深处的旅行者的早期警戒哨岗。",al={"迈斯特拉岗哨位置","迈斯特拉岗哨在哪"}},{q="暗滩教派在奥萨拉克斯之塔做什么？",a="暗滩是一个以黑海岸北部的上层精灵废墟——奥萨拉克斯之塔为基地的教派。他们从事黑暗魔法，与恶魔力量勾结，威胁要将腐蚀之力释放到整个海岸线。",al={"暗滩教派奥萨拉克斯","奥萨拉克斯之塔教派成员"}},{q="德尔格伦如何看待他与暗夜精灵的联盟？",a="德尔格伦承认，他刚来到卡利姆多时，对暗夜精灵的行为举止和生活方式并不习惯。然而随着时间的推移，与她们并肩对抗共同的邪恶，使他对哨兵产生了极大的敬意。",al={"德尔格伦与暗夜精灵","人类圣骑士与暗夜精灵"}}},fp="22,206,25.325.0,21.382.0,23.356.1,28.234.0,62.216.0,54.179.0,24.149.0,61.217.0,56.159.0"}
P.entries["quest:96773"] = {n="The Coldbringer's Eye",s="肯瑞托正在寻找 Coldbringer’s Eye。这是一颗占卜宝珠，巫妖王的一名仆从曾在剃刀高地使用它。肯瑞托请你取回宝珠，以便研究这件神器。",h="肯瑞托正在寻找 Coldbringer’s Eye。这是一颗占卜宝珠，巫妖王的一名仆从曾在剃刀高地使用它。肯瑞托请你取回宝珠，以便研究这件神器。",kw={"coldbringer","coldbringer之眼","肯瑞托","巫妖王","quilboar","剃刀高地","占卜宝珠","仆从"},sec={{t="肯瑞托的委托",b="巫妖王的一名仆从居住在剃刀高地，藏身于那里的 quilboar 巢穴中。肯瑞托称，他用 Coldbringer’s Eye 指挥其他地方的低阶爪牙。肯瑞托请你取回宝珠，以供研究。"}},faq={{q="Coldbringer’s Eye 是什么？",a="Coldbringer’s Eye 是一颗占卜宝珠，巫妖王的一名仆从曾在剃刀高地使用它。",al={"coldbringer之眼","这颗眼睛是什么","占卜宝珠"}},{q="谁想要 Coldbringer’s Eye？",a="肯瑞托想要 Coldbringer’s Eye，以便研究这件神器并了解它的运作方式。",al={"谁想要这颗宝珠","肯瑞托之眼","谁提出了请求"}},{q="Coldbringer’s Eye 在哪里？",a="Coldbringer’s Eye 位于剃刀高地。",al={"眼睛在哪里","剃刀高地宝珠","眼睛的位置"}},{q="谁在使用这颗宝珠？",a="剃刀高地中巫妖王的一名仆从使用这颗宝珠，指挥其他地方的低阶爪牙。",al={"谁拿着眼睛","巫妖王的仆从","coldbringer的使用者"}}},fp="21,172,19.228.0,32.94.0,34.101.0,33.45.0,17.93.0"}
P.entries["quest:96781"] = {n="What's the Big Idea?",s="拉文霍德庄园的 Myrokos Silentform 要你查明辛迪加在奥特兰克废墟寻找什么。侦察报告由 Barton 保管，或许能揭示他们的目的。",h="拉文霍德庄园的 Myrokos Silentform 要你查明辛迪加在奥特兰克废墟寻找什么。侦察报告由 Barton 保管，或许能揭示他们的目的。",kw={"barton","myrokos silentform","拉文霍德庄园","奥特兰克废墟","侦察报告","斯坦恩布莱德","辛迪加"},ang={["class:Rogue"]="作为一名潜行者，你要拿到 Barton 的报告，但不能杀他。"},sec={{t="Barton 的报告",b="拉文霍德庄园的 Myrokos Silentform 需要 Barton 的侦察报告。由 Barton 率领的辛迪加小队在奥特兰克废墟一带徘徊，寻找某样东西。你要从他那里拿到报告，但不要杀他，以免辛迪加察觉自己的行动已经引起注意。"}},faq={{q="Barton 是谁？",a="Barton 率领一支辛迪加侦察小队，在奥特兰克废墟一带徘徊。",al={"barton","谁是 barton","辛迪加侦察兵"}},{q="辛迪加在寻找什么？",a="辛迪加小队正在奥特兰克废墟寻找某样东西，但 Myrokos 需要 Barton 的侦察报告才能查明具体是什么。",al={"辛迪加在找什么","他们在寻找什么","辛迪加搜寻"}},{q="Myrokos 为什么想要这份报告？",a="Myrokos Silentform 想通过这份报告查明辛迪加在寻找什么。",al={"为何拿报告","barton 的报告","大计划"}},{q="为什么不杀 Barton？",a="如果 Barton 死了，辛迪加就会意识到有人在监视他们，并可能采取措施掩盖踪迹。",al={"别杀 barton","偷 barton 的东西","为何偷报告"}},{q="在哪里能找到 Barton？",a="Barton 很可能就在斯坦恩布莱德的辛迪加成员当中。",al={"barton 在哪里","寻找 barton","斯坦恩布莱德侦察兵"}},{q="报告要交给谁？",a="Barton 的侦察报告是要交给拉文霍德庄园的 Myrokos Silentform。",al={"谁拿报告","报告交到哪里","myrokos"}}},fp="20,173,17.280.0,14.77.0,36.129.0,33.81.0,20.107.0,26.56.0,25.77.0"}
P.entries["quest:96783"] = {n="A Way In",s="辛迪加的一桩交易引你前往阿拉希高地的激流堡。你需要从诺斯弗德农场取得伪装，才能不引起怀疑地进入。",h="辛迪加的一桩交易引你前往阿拉希高地的激流堡。你需要从诺斯弗德农场取得伪装，才能不引起怀疑地进入。",kw={"a way in","阿拉希高地","诺斯弗德农场","激流堡","辛迪加","交易","制服"},sec={{t="秘密交易",b="一名联络人派你前往阿拉希高地的激流堡，辛迪加在堡内进行重要的交易。联络人已收到消息，辛迪加成员之间有一桩交易，详情或许就在堡内。要想进入时不引起怀疑，你需要从诺斯弗德农场取得一套辛迪加制服。"}},faq={{q="激流堡正在发生什么？",a="激流堡是辛迪加最大的据点之一，而其成员之间的一桩交易正在阿拉希高地的某处进行。",al={"激流堡交易","激流堡有什么","辛迪加城堡"}},{q="我为什么要去诺斯弗德农场？",a="你要在诺斯弗德农场寻找一套辛迪加制服，以便在进入激流堡之前乔装打扮。",al={"诺斯弗德农场","为什么去诺斯弗德农场","获取伪装"}},{q="进入城堡需要什么？",a="你需要从诺斯弗德农场取得一套辛迪加制服，才能不引起怀疑地进入激流堡。",al={"制服","辛迪加伪装","进入激流堡的方法"}},{q="辛迪加的交易是关于什么的？",a="这桩交易由辛迪加成员在阿拉希高地的某处进行。交易的详情或许能在激流堡内找到。",al={"辛迪加交易","什么交易","交易详情"}}},fp="8,144,14.314.0,37.152.0,34.112.0,33.102.0,34.122.0"}
P.entries["quest:968"] = {n="上层精灵的工具",s="“上层精灵的工具”是一个由奥伯丁的桑德里斯·织风者提供的联盟任务。旅行者们被派往南部的亚米萨兰废墟，从那些躁动不安的上层精灵幽灵手中夺回遗留的魔法遗物。目标很简单：在这些潜藏的魔法力量对卡利姆多造成进一步危害之前，回收这些古代神器。",h="“上层精灵的工具”是一个由奥伯丁的桑德里斯·织风者提供的联盟任务。旅行者们被派往南部的亚米萨兰废墟，从那些躁动不安的上层精灵幽灵手中夺回遗留的魔法遗物。目标很简单：在这些潜藏的魔法力量对卡利姆多造成进一步危害之前，回收这...",kw={"亚米萨兰","奥伯丁","黑海岸","上层精灵","遗物","大分裂","桑德里斯·织风者"},ang={["class:Druid"]="清除亚米萨兰受腐化的奥术残余，有助于抚平破坏黑海岸荒野自然宁静的精神创伤。",["class:Mage"]="虽然卡多雷社会因恐惧而寻求粉碎这些神器，但奥术学者们却将其视为大分裂前上层精灵工艺的珍稀且原始的范例。",["faction:Alliance"]="协助暗夜精灵保卫他们受诅咒的领土，巩固了联盟在卡利姆多北部原始森林中的存在感与团结。",["race:NightElf"]="对于卡多雷而言，直面亚米萨兰的鬼魂是一个令人悲伤的提醒，让他们想起祖先的傲慢以及其祖先帝国那灾难性的大分裂。"},sec={{t="废墟中的回响",b="在奥伯丁以南，沿海大路以东，坐落着杂草丛生的亚米萨兰石砌地基。一万年前，这座定居点曾是上层精灵——即古代暗夜精灵帝国中的特权贵族——的堡垒。当他们肆无忌惮的奥术实验最终导致了世界大分裂时，亚米萨兰也被摧毁了。然而，它的居民却从未真正离去。在黑海岸巡逻的哨兵们报告说，这些贵族的鬼魂依然游荡在沉没的广场上，紧紧抓着他们生前拥有的附魔工具和饰品。"},{t="净化奥术往事",b="对于现代卡多雷社会而言，奥术不仅是被禁止的知识，更是一种几乎将艾泽拉斯的生命抹去的生存威胁。桑德里斯·织风者深知，将这些上层精灵的器具留在幽灵手中无异于为腐化敞开大门。通过派遣冒险者从这些躁动不安的灵魂手中夺回遗物，桑德里斯意图彻底摧毁它们，确保那潜藏的、被污染的魔法永远不会再引发另一场灾难。"}},faq={{q="我在哪里可以找到上层精灵的遗物？",a="这些遗物可以在亚米萨兰的废墟中找到，它位于奥伯丁以南，黑海岸主路东侧。游荡在废弃石砌庭院中的灵魂携带着这些古代器具。",al={"遗物在哪里","亚米萨兰位置","去哪里找遗物"}},{q="桑德里斯·织风者是谁？",a="桑德里斯·织风者是一位居住在港口城镇奥伯丁的暗夜精灵学者兼长者。他与当地的哨兵紧密合作，协调各项工作，以保护黑海岸免受大分裂遗留下来的魔法污染和古老诅咒的侵害。",al={"桑德里斯·织风者","谁提供上层精灵的工具任务"}},{q="为什么桑德里斯想要销毁这些遗物？",a="由于上层精灵的鲁莽魔法导致了毁灭性的大分裂，暗夜精灵社会严令禁止奥术魔法。桑德里斯担心如果放任不管，这些物品中残留的奥术力量可能会重新唤醒潜伏的邪恶。",al={"为什么要销毁遗物","上层精灵的工具任务目标"}},{q="在亚米萨兰游荡的是什么样的灵魂？",a="这些灵魂是上古之战中丧生的上层精灵精英的残影。即使在死后，他们依然执着于曾经的骄傲、力量和魔法神器，在废墟的石头间重演着他们已逝的生前时光。",al={"亚米萨兰的鬼魂","这些灵魂是什么"}},{q="为什么上层精灵仍然被束缚在废墟中？",a="桑德里斯没有明说。他只知道哨兵告诉他的情况：上层精灵的灵魂依然徘徊在亚米萨兰的废墟之中，并且仍然挥舞着他们古老的魔法器具。",al={"为什么它们变成了鬼魂","上层精灵的诅咒"}},{q="当你上交遗物后，它们会怎样？",a="桑德里斯·织风者会将收集到的遗物收管，并明确计划将它们永久拆解和销毁，以确保其潜藏的奥术污染永远不会再被利用或释放。",al={"桑德里斯如何处理遗物","遗物的命运"}}},fp="22,167,19.507.0,23.350.0,37.149.0,27.204.0,46.169.0,38.187.0,47.192.0,50.176.0"}
P.entries["quest:96800"] = {n="Past Due",s="一位学者请你从血色修道院找回一本遗失的典籍。他需要这本书来研究格瑞姆巴托古老的蛮锤符文大师。",h="一位学者请你从血色修道院找回一本遗失的典籍。他需要这本书来研究格瑞姆巴托古老的蛮锤符文大师。",kw={"奥法师杜安","达拉然图书馆","格瑞姆巴托","逾期未还","血色修道院","符文大师的失落魔法","蛮锤符文大师"},sec={{t="逾期未还的书",b="这位学者正在撰写论文，研究格瑞姆巴托古老的蛮锤符文大师。达拉然旧图书馆的账簿记载，杜安在第三次战争前借走了这本典籍，却从未归还。他如今身在提瑞斯法林地的血色修道院，那本书也在那里，等待寻回。"}},faq={{q="谁需要这本书？",a="一位正在撰写论文、研究格瑞姆巴托古老蛮锤符文大师的学者需要这本书，以完成研究。",al={"谁想要这本典籍","学者的研究"}},{q="借走的是哪本书？",a="这本书名为《符文大师的失落魔法》。",al={"哪本典籍","失落的符文大师之书"}},{q="谁借走了这本书？",a="达拉然旧图书馆的账簿记载，一位名叫杜安的法师在第三次战争前借走了这本书。",al={"谁借走了这本书","杜安 的书"}},{q="这本书在哪里？",a="这本书在提瑞斯法林地的血色修道院，奥法师杜安如今也在那里。",al={"典籍在哪里","书籍位置"}},{q="研究的内容是什么？",a="这位学者正在研究格瑞姆巴托古老的蛮锤符文大师。",al={"蛮锤符文大师","格瑞姆巴托论文"}}},fp="8,113,15.121.0,19.112.0,23.62.0,22.97.0,18.84.0,27.76.0"}
P.entries["quest:96821"] = {n="Legging It",s="“Legging It”是一个专注于清理南部危险道路以保护苦工的任务。道路沿线的威胁吓坏了劳工，使他们停止了前行，导致日常工作陷入停滞。通过击退这些危险，冒险者们恢复了道路的安全，使劳工们能够重返工作岗位。",h="“Legging It”是一个专注于清理南部危险道路以保护苦工的任务。道路沿线的威胁吓坏了劳工，使他们停止了前行，导致日常工作陷入停滞。通过击退这些危险，冒险者们恢复了道路的安全，使劳工们能够重返工作岗位。",kw={"清理了路径","部落劳工","拔腿就跑","监工","苦工劳作","苦工","南部路径"},ang={["faction:Horde"]="兽人的劳工和补给线在很大程度上依赖于苦工，因此路线安全对于部落的建设和资源采集至关重要。",["race:Orc"]="苦工是兽人定居点的支柱，监工们依靠勇士来清除路径上的威胁，以确保工作能够持续进行。"},sec={{t="确保路线安全",b="“Legging It”解决了当地劳工运作中的中断问题，因为苦工们因害怕而不敢南下。工人们拒绝在充满危险的道路上冒险，而不去执行指派的任务。通过介入并清除沿途的威胁，旅行者们恢复了足够的安全保障，使监工们能够派遣劳工队继续工作。"},{t="劳工与路线安全",b="苦工是部落基础设施的支柱，负责采伐木材、采石和建造哨所。由于苦工几乎没有战斗能力，即使是轻微的路边掠食者或敌对侦察兵也会导致供应链中断。确保交通要道的畅通对于维持定居点的补给和生产至关重要。"}},faq={{q="什么是“拔腿就跑”？",a="“拔腿就跑”是一项旨在为劳工队确保南部运输路线安全的任务。道路沿线的威胁恐吓了当地苦工，使他们的日常工作陷入停顿，直到一位冒险者介入清除了障碍。",al={"什么是拔腿就跑","拔腿就跑任务信息","拔腿就跑任务"}},{q="为什么苦工们不敢往南走？",a="苦工们因为道路上存在的实际威胁而不敢向南行进。在没有保护或清理路径的情况下，工人们拒绝冒险前往目的地，导致当地的劳作陷入瘫痪。",al={"为什么苦工会害怕","苦工的恐惧","为什么苦工停止工作"}},{q="完成该任务能达成什么效果？",a="随着南部路线的清理和直接威胁的消除，监工们能够安全地将苦工队伍派回实地，恢复劳作和资源采集。",al={"完成拔腿就跑之后会发生什么","拔腿就跑任务结果","清理路径的成果"}},{q="任务中提到的苦工是谁？",a="苦工是部落的基础劳动力，负责搬运重物、采伐木材、采矿和建造防御工事。虽然他们对定居点的运作至关重要，但他们并不适合战斗，遇到危险往往会退缩。",al={"谁是苦工","苦工的角色","苦工做什么"}},{q="苦工们要去哪里？",a="道路通往南部的外围工作区和资源矿点，这些地方需要苦工进行日常维护，但在路线清理之前，这段旅程已经变得极其危险，迫使所有交通中断。",al={"路径通向哪里","南部路径","前往南方"}},{q="为什么苦工需要冒险者来清理路线？",a="苦工缺乏正规的军事训练和战斗装备，这使他们容易受到荒野掠食者和敌对势力的伤害。监工们必须依靠经验丰富的冒险者来消除外围威胁并维护安全的工作通道。",al={"为什么苦工需要保护","苦工安全","保护苦工"}}},fp="10,121,17.210.0,24.276.0,19.112.0,42.162.0,44.139.0,40.185.0,31.177.0,55.199.0"}
P.entries["quest:96822"] = {n="为了荣耀",s="为了荣耀是一项旨在纪念阵亡战士的任务，让他们的事迹不被遗忘。通过完成这项任务，冒险者可以确保这些战斗人员的牺牲被永远铭记。",h="为了荣耀是一项旨在纪念阵亡战士的任务，让他们的事迹不被遗忘。通过完成这项任务，冒险者可以确保这些战斗人员的牺牲被永远铭记。",kw={"阵亡战士","为了荣耀","荣耀","纪念","任务","缅怀","战士"},ang={["class:Warrior"]="这项任务直接以纪念阵亡战士为核心，能与那些珍视战场牺牲和永恒缅怀的战士产生强烈共鸣。"},sec={{t="缅怀之责",b="为了荣耀任务是一项庄严的使命，核心在于纪念阵亡的战士。在一个不断受到冲突考验的世界里，确保那些付出了一切的士兵不被遗忘，对于生者而言是一项至关重要的职责。"},{t="守护传承",b="在完成任务后，任务发布者会确认，多亏了你的努力，那些阵亡战士的事迹将永载史册。这项已完成的功绩确保了他们的牺牲得到认可与尊重，而非湮没在历史的长河中。"}},faq={{q="为了荣耀任务的内容是什么？",a="为了荣耀是一项专注于纪念阵亡战士的任务。通过承接并完成这项任务，你能够帮助确保这些战士的牺牲得到认可，而不会被历史遗忘。",al={"为了荣耀是什么","为了荣耀任务概览"}},{q="任务完成后提到的战士是指谁？",a="任务文本特别致敬了那些阵亡的战士，他们的事迹和记忆通过你的行动得以保存。那些坚持完成任务的人，让他们的服务与牺牲得以延续。",al={"战士是谁","谁被铭记"}},{q="为什么要纪念这些战士？",a="这项任务的目的是缅怀。在这个充满战乱与冲突的世界里，纪念那些战死沙场的人们既是给予他们尊严，也是确保他们的勇气得到认可。",al={"为什么要完成这个任务","为了荣耀的含义"}},{q="是谁要求完成这项任务的？",a="这项任务是由想要纪念阵亡战友的人所指派的。当你归来时，他们会核实任务是否完成，并确认这些战士将永远被铭记。",al={"谁发布了为了荣耀","为了荣耀的任务发布者"}},{q="这项任务会引出其他任务吗？",a="任务中没有任何线索指向后续任务。它本身就是为了纪念阵亡战士而存在，巩固他们的遗产，确保他们的牺牲永不被遗忘。",al={"为了荣耀是否属于任务链","为了荣耀之后是什么"}},{q="为了荣耀这个标题意味着什么？",a="这个名称反映了纪念阵亡士兵这一核心主题。它强调了承认牺牲并让战场的记忆长存，是战士所能承担的最庄严的职责之一。",al={"为何它被称为荣耀","为了荣耀的意义"}}},fp="9,117,21.110.0,21.114.0,34.95.0,47.119.0,41.95.0,34.140.0,36.86.0,38.143.0"}
P.entries["quest:96825"] = {n="This Fruit Could Bite Back",s="“This Fruit Could Bite Back”是一项采集任务，专注于在奥格瑞玛附近的干旱土地上收集野生仙人掌果。这些果实既可加工成食物，其种子也会被保存下来用于日后种植，目的是培育出一种适应性强的沙漠作物，以养活部落的首府。",h="“This Fruit Could Bite...",kw={"仙人掌果","杜隆塔尔","果实","奥格瑞玛","种子","这果子会咬人"},ang={["faction:Horde"]="确保可持续的食物来源（如充实的沙漠果实）对于供养兽人首府和滋养部落不断增长的人口至关重要。",["profession:Cooking"]="在杜隆塔尔的干旱气候下，仙人掌果具备极佳的烹饪潜力，既可作为美味菜肴的配料，也是城市居民的给养。",["profession:Herbalism"]="采集者和植物学家们深知沙漠植物的顽强，也了解为了耕种而收集多刺野生果实所付出的努力。"},sec={{t="收获干旱荒原",b="杜隆塔尔是一片崎岖、被烈日烘烤的土地，传统的农业几乎无法在此开展。为了支持日益壮大的奥格瑞玛首府，足智多谋的居民们转向了本地的沙漠植物。仙人掌果是一种生命力顽强的仙人掌果实，长有保护性的尖刺，在干旱的土壤中茁壮成长，小心采集后可提供急需的养分。"},{t="耕种与补给",b="采集仙人掌果不仅仅是为了提供一顿即时的餐食。虽然果肉可以加工成美味的菜肴，但采摘下来的种子会被仔细保存以供种植。其宏愿是在奥格瑞玛周围种植这些适应性强的作物，在堡垒城墙外建立一个触手可及且持久的食物来源。"}},faq={{q="“这果子会咬人”是什么？",a="“这果子会咬人”是一项专注于在杜隆塔尔收集野生仙人掌果的任务。收集到的果实既用于即时的烹饪，也用于保存种子，以便在奥格瑞玛周围的干旱地带进行繁殖。",al={"什么是 这水果会反咬一口","这水果会反咬一口 任务","咬人果实任务"}},{q="为什么要采集仙人掌果？",a="采集的仙人掌果具有双重用途：为当地居民准备美味的餐食，以及收获可用的种子。长远目标是在奥格瑞玛周围的干旱土地上广泛种植仙人掌果。",al={"为什么要采集仙人掌果","仙人掌果的用途","仙人掌果的作用"}},{q="种子将种在哪里？",a="从收获中留存的种子计划种在奥格瑞玛的郊区和周边土地上，以帮助在贫瘠的沙漠土壤中建立一个具有韧性、可持续的食物供应。",al={"仙人掌果生长在哪里","在奥格瑞玛种植仙人掌果"}},{q="谁要求采集这些果实？",a="一位当地居民希望改善本地食物储备，并在杜隆塔尔严酷的沙漠气候中耕种作物，因此请求采集这些果实，以供养过往旅人并培育未来的作物。",al={"谁需要仙人掌果","任务发放者咬人果实"}},{q="为什么这种果实会“咬人”？",a="仙人掌果覆盖着坚韧沙漠仙人掌特有的锋利尖刺和针芒，如果处理不当，采集它们会有危险。",al={"为什么会咬人","为什么果实会咬人"}},{q="为什么在奥格瑞玛周围种植果实很重要？",a="杜隆塔尔主要由干旱的岩石地形构成，传统的农业难以开展。建立耐旱作物（如仙人掌果）有助于为这座首府城市提供可持续的补给。",al={"奥格瑞玛缺粮吗","奥格瑞玛农业","杜隆塔尔农耕"}}},fp="26,174,26.262.0,26.288.0,35.120.0,37.146.0,32.166.0,32.137.0,31.103.0,49.159.0"}
P.entries["quest:96873"] = {n="A Pain in the Neck",s="Pa'zula请你剥除扎拉赞恩用来控制回音群岛巨魔的吊坠上的誓缚魔法。这些残渣或许能让他们的灵魂摆脱巫医的控制。",h="Pa'zula请你剥除扎拉赞恩用来控制回音群岛巨魔的吊坠上的誓缚魔法。这些残渣或许能让他们的灵魂摆脱巫医的控制。",kw={"a pain in the neck","誓缚法术","回音群岛","hexed pendants","发光的残渣","pa'zula","森金村","扎拉赞恩"},ang={["profession:Tailoring"]="作为一名附魔师，你通过为Pa'zula剥除Hexed Pendants上的誓缚魔法来磨练技艺。"},sec={{t="Pa'zula的请求",b="森金村的Pa'zula需要从Hexed Pendants上剥离下来的残渣。扎拉赞恩在吊坠上施加誓缚法术，以控制他的囚徒。你要除去那些魔法，再把留下的东西带给Pa'zula。巨魔能否获得自由，正岌岌可危。"},{t="吊坠",b="Pa'zula说，誓缚法术控制着巨魔的心智，并提醒你千万别自己戴上吊坠。你带回残渣后，Pa'zula说法术已经被清除，被杀巨魔的灵魂终于可以安息。"}},faq={{q="谁想要这些残渣？",a="森金村的Pa'zula请你带回从Hexed Pendants上剥离下来的残渣。",al={"谁想要残渣","pa'zula的请求"}},{q="扎拉赞恩用这些吊坠做什么？",a="扎拉赞恩在吊坠上施加誓缚法术，以控制囚徒的心智。",al={"扎拉赞恩的吊坠","hexed pendants"}},{q="在哪里能找到Hexed Pendants？",a="回音群岛的巨魔身上带着Hexed Pendants。",al={"吊坠位置","吊坠在哪里"}},{q="什么是发光的残渣？",a="从Hexed Pendants上剥离魔法后，就能得到发光的残渣。",al={"吊坠上的残渣","发光的东西"}},{q="Pa'zula为什么要除去吊坠上的魔法？",a="Pa'zula说，除去誓缚法术，就能让被杀巨魔的灵魂安息。",al={"为什么要剥除吊坠魔法","解放巨魔灵魂"}}},fp="18,175,17.241.0,12.215.1,30.77.0,40.88.0,35.59.0,25.72.0,48.77.0"}
P.entries["quest:96874"] = {n="This Is Spinal Axe",s="奥格瑞玛的 Ug’thok 请你收集雷霆山巨兽的脊刺。他希望将脊刺制成斧刃，作为你锻造课程的一部分。",h="奥格瑞玛的 Ug’thok 请你收集雷霆山巨兽的脊刺。他希望将脊刺制成斧刃，作为你锻造课程的一部分。",kw={"斧刃","奥格瑞玛","粗制磨刀石","萨鲁","锻造","雷霆山","乌格索克","风化脊刺"},ang={["profession:Blacksmithing"]="作为锻造学徒，你帮助 Ug’thok 收集材料，打造他希望制成的斧刃。"},sec={{t="铁匠的设想",b="Ug’thok 想要五根风化脊刺和五块粗制磨刀石。他觉得脊刺或许能制成不错的斧刃，尽管萨鲁对此嗤之以鼻。"},{t="坚硬的材料",b="脊刺比 Ug’thok 预想的还要坚硬，用它们来制作斧刃恐怕不容易。他打算继续完善设计。"}},faq={{q="谁在索要脊刺？",a="奥格瑞玛的 乌格索克 请你收集风化脊刺和粗制磨刀石。",al={"谁要脊刺","乌格索克 斧子","锻造课程"}},{q="乌格索克 想制作什么？",a="乌格索克 希望用巨兽的脊刺打造一把斧子的斧刃。",al={"脊刺斧","他要制作什么","斧刃设想"}},{q="脊刺来自哪里？",a="风化脊刺来自雷霆山的巨兽。",al={"脊刺在哪里","雷霆山巨兽","脊刺位置"}},{q="乌格索克 还需要什么？",a="除了脊刺，他还要粗制磨刀石。",al={"需要磨刀石","需要什么材料","粗制石块"}},{q="乌格索克 为什么想要这些材料？",a="作为你锻造课程的一部分，他想试着用脊刺打造斧刃。",al={"为什么要脊刺","脊刺有什么用","乌格索克 材料"}}},fp="18,154,16.165.0,14.123.1,29.85.0,33.62.0,30.64.0,30.63.0,38.91.0"}
P.entries["quest:96875"] = {n="Beasts of Thunder Ridge",s="Beasts of Thunder Ridge是奥格瑞玛的一项任务，由制皮师卡玛瑞发布，他支持部落首都的持续扩建。冒险者们被派往雷霆山的峭壁，收集耐用的蜥蜴皮，并提供熟化皮毛来加固这座城市新建的建筑。",h="Beasts of Thunder Ridge是奥格瑞玛的一项任务，由制皮师卡玛瑞发布，他支持部落首都的持续扩建。冒险者们被派往雷霆山的峭壁，收集耐用的蜥蜴皮，并提供熟化皮毛来加固这座城市新建的建筑。",kw={"雷霆山的野兽","熟化轻皮","杜隆塔尔","卡玛瑞","制皮","奥格瑞玛","苦工","粗糙蜥蜴皮","雷霆山"},ang={["faction:Horde"]="随着部落在杜隆塔尔确立其势力，从周边荒野收集的补给直接推动了奥格瑞玛的防御加固和发展。",["race:Orc"]="兽人的建筑依赖于猎人和劳工采集的坚固耐用材料，以抵御杜隆塔尔恶劣的自然环境。"},sec={{t="不断扩建的首都",b="随着部落在杜隆塔尔干旱的土地上建立家园，首都奥格瑞玛依然处于不断的扩建状态。新的住所、作坊和防御工事需要源源不断的木材、石料和动物皮毛。虽然木材必须从更远的地方运来，但杜隆塔尔当地的动物为城市的苦工和建造者们提供了坚韧耐用的皮革补给。"},{t="峡谷中的野兽",b="在雷霆山深处，本地的蜥蜴生长着坚硬、粗糙的皮。虽然这些皮毛通常太厚且太硬，无法制成可穿戴的皮甲，但它们的韧性使其成为绝佳的建筑材料。如果采集得当，它们可以用来覆盖奥格瑞玛木石结构建筑的天花板和墙壁，保护室内免受烈日和峡谷强风的侵袭。"}},faq={{q="为什么奥格瑞玛需要雷霆山的蜥蜴皮？",a="在雷霆山采集的粗糙蜥蜴皮对于制作可穿戴的护甲来说太粗、太厚了，但它们的韧性使其非常适合用于建筑。奥格瑞玛的苦工们用它们来覆盖新建建筑的墙壁和屋顶，以抵御恶劣的天气。",al={"皮革的用途","为什么要粗糙蜥蜴皮","雷霆山皮革的用途"}},{q="卡玛瑞是谁？",a="卡玛瑞是部落首都奥格瑞玛的一名制皮师，他为城市的建造者和苦工提供持续建设工程所需的坚固皮毛和皮革。",al={"谁是卡玛瑞","卡玛瑞 奥格瑞玛","雷霆山的野兽的发布者"}},{q="雷霆山在哪里？",a="雷霆山是位于杜隆塔尔干旱领地内的一处崎岖峡谷，以卡玛瑞为城市新建筑所需的、皮质厚实的蜥蜴而闻名。",al={"雷霆山在哪里","雷霆山位置","雷霆山 杜隆塔尔"}},{q="为什么要和蜥蜴皮一起收集熟化轻皮？",a="除了沉重的蜥蜴皮，卡玛瑞还需要熟化轻皮来配合这些较重的材料，这是对冒险者在皮革加工方面更广泛的了解和技能的考验。",al={"为什么需要熟化轻皮","熟化皮革的用途"}},{q="为什么奥格瑞玛扩建得如此迅速？",a="作为部落新建立的首都，奥格瑞玛正在进行持续的施工和扩建，以容纳日益增多的兽人及其盟友，从而对原材料产生了持续的需求。",al={"为什么奥格瑞玛在施工","奥格瑞玛扩建"}},{q="雷霆山的蜥蜴皮能制成护甲吗？",a="来自雷霆山的粗糙蜥蜴皮通常太厚且太僵硬，无法制成柔韧的护甲，因此它们的主要实际价值在于建筑而非穿戴。",al={"蜥蜴皮可以穿吗","粗糙蜥蜴皮是护甲吗"}}},fp="23,157,17.236.0,20.266.0,56.205.0,14.155.0,31.119.0,60.180.0,38.186.0,59.126.0"}
P.entries["quest:96876"] = {n="Ukor's Lost Pack",s="Ukor's Lost Pack是一个在杜隆塔尔南部荒野中发现的掉落物品，上面粗糙地缝着主人的名字。在乌克尔遭遇该地区原生的一种巨型蜘蛛并仓皇逃窜时，他不慎将其遗弃。",h="Ukor's Lost Pack是一个在杜隆塔尔南部荒野中发现的掉落物品，上面粗糙地缝着主人的名字。在乌克尔遭遇该地区原生的一种巨型蜘蛛并仓皇逃窜时，他不慎将其遗弃。",kw={"杜隆塔尔","部落","失落的包裹","杜隆塔尔南部","蜘蛛","乌克尔","乌克尔丢失的背包"},ang={["faction:Horde"]="在杜隆塔尔南部冒险的年轻部落冒险者经常会帮助像乌克尔这样的当地人，通过从危险的野生动物手中找回遗失的个人物品，来证明自己的价值和可靠性。"},sec={{t="失落的物品",b="当The Adventurer穿越杜隆塔尔南部干旱的荒野时，发现了一个被遗弃的旅行包，包盖上粗糙地缝着“乌克尔”的名字。在杜隆塔尔这片严酷的土地上生存，没有粗心大意的余地，发现被遗弃的装备通常意味着附近发生过不幸的遭遇。"},{t="逃离荒野",b="将包裹归还给杜隆塔尔南部的乌克尔后，它被遗弃背后的故事浮出水面。乌克尔在遭遇该地区原生的一种巨型蜘蛛伏击时惊慌失措，丢下了包裹，并确信自己永远无法再找回补给品。找回完好无损的包裹为旅行者赢得了他衷心的感激和赞美。"}},faq={{q="乌克尔是谁？",a="乌克尔是居住在杜隆塔尔南部的一名居民。在干旱的荒野中面对一只巨型蜘蛛时，为了安全脱身，他被迫遗弃了自己的财物。",al={"乌克尔是谁","乌克尔 杜隆塔尔"}},{q="乌克尔为什么会弄丢他的包裹？",a="乌克尔在躲避杜隆塔尔中潜伏的一只巨型蜘蛛时，为了保命而丢下了包裹。在冒险者追踪并找到这个包裹之前，他以为自己的财物已经彻底遗失了。",al={"为什么包裹会丢失","乌克尔在哪里丢失的包裹"}},{q="这个包裹需要送到哪里？",a="找回的包裹属于乌克尔，他就在杜隆塔尔南部等待，随时准备迎接归来的旅行者。",al={"去哪里归还包裹","乌克尔 任务提交"}},{q="如何辨认这个包裹？",a="包裹上粗糙地缝着乌克尔的名字，这使得它很容易辨认。",al={"如何辨认包裹","包裹缝线"}},{q="是什么样的生物追赶了乌克尔？",a="乌克尔遭到了杜隆塔尔南部地形中游荡的一只巨型蜘蛛的伏击，这让他惊恐万分，丢下所有财物逃命去了。",al={"杜隆塔尔的蜘蛛","袭击乌克尔的是什么蜘蛛"}},{q="把包裹归还给乌克尔会发生什么？",a="乌克尔对于能再次见到自己失落的财物感到非常惊讶和感激，并称赞找回他包裹的冒险者是一位真正的英雄。",al={"乌克尔的奖励","乌克尔的反应"}}},fp="16,125,16.162.0,17.222.0,12.118.0,27.131.0,37.97.0,27.54.0,34.106.0,46.116.0"}
P.entries["quest:96877"] = {n="Halikor's Hoof",s="Halikor's Hoof 是一项任务，核心在于猎杀强大的蜥蜴 Halikor 后取得实物证据。将那只巨大的断蹄带回部落首都奥格瑞玛，是对猎人战胜这只强大荒野野兽的荣耀嘉奖。",h="Halikor's Hoof 是一项任务，核心在于猎杀强大的蜥蜴 Halikor 后取得实物证据。将那只巨大的断蹄带回部落首都奥格瑞玛，是对猎人战胜这只强大荒野野兽的荣耀嘉奖。",kw={"哈利科尔","哈利科尔之蹄","部落","狩猎","蜥蜴","奥格瑞玛","战利品"},ang={["class:Hunter"]="击败像 Halikor 这样巨大而强大的野兽，是追踪者技艺和狩猎快感的典范。",["faction:Horde"]="将强大野兽被击败的证明带到奥格瑞玛，彰显了部落崇尚力量和狩猎技艺的传统。"},sec={{t="强大野兽的战利品",b="Halikor's Hoof 是从体型极其巨大的蜥蜴 Halikor 的遗骸上获取的有形战利品。在穿梭于蛮荒前线的猎人和勇士中，从如此强大的生物身上获取实物信物来验证猎杀成果是一项古老的习俗。蹄子巨大的尺寸毫无疑问地证明了这只野兽生前的庞大规模和力量。"},{t="带给首都的证明",b="将沉重的蹄子带回奥格瑞玛那防御森严的大门，是为了向部落宣告野兽的覆灭。在一个崇尚原始力量并在严酷的荒野掠食者面前求生存的勇士社会中，展示这样的战利品不仅能为猎人带来荣耀，也能让首都确信这只危险的生物已被击杀。"}},faq={{q="哈利科尔 是什么？",a="哈利科尔 是一只强大无比的蜥蜴生物。其巨大的体型可以通过其断蹄的庞大规模来体现，猎人们以此作为其覆灭的铁证。",al={"什么是 哈里科尔","哈里科尔 是谁","哈里科尔 蜥蜴"}},{q="为什么必须将蹄子送到奥格瑞玛？",a="将蹄子带回部落首都奥格瑞玛是为了作为野兽被击败的实物证明，向全城展示猎人的凯旋。",al={"为什么要将蹄子带到奥格瑞玛","哈里科尔 蹄子交付","蹄子要去哪里"}},{q="哈利科尔之蹄 是如何获得的？",a="哈利科尔之蹄 是在追踪并战斗击杀这只巨大的蜥蜴后，直接从 哈利科尔 的尸体上获得的。",al={"如何获取 哈里科尔的蹄子","哈里科尔 掉落"}},{q="为什么蜥蜴会有蹄子？",a="哈利科尔 并非普通的蜥蜴，而是一只荒野中的强大野兽，其巨大的蹄子就是证明你将其击倒的战利品。至于为什么它会长着蹄子，无人知晓。",al={"哈里科尔 有蹄子吗","为什么蜥蜴会有蹄子"}},{q="奥格瑞玛里谁想要 哈利科尔之蹄？",a="你将蹄子带回奥格瑞玛作为胜利的证明；并没有指定特定的猎人或官员来接收它。",al={"在奥格瑞玛谁接收 哈里科尔的蹄子","在奥格瑞玛上交 哈里科尔 蹄子"}},{q="哈利科尔之蹄 这个任务背后的故事是什么？",a="哈利科尔之蹄 是一项围绕击败巨大蜥蜴 哈利科尔 的任务。将其巨大的断蹄带回奥格瑞玛，展现了猎人的武勇，并将野兽覆灭的消息传达给部落。",al={"什么是 哈里科尔的蹄子 任务","哈里科尔的蹄子 的故事"}}},fp="14,166,24.231.0,21.278.0,16.113.0,44.89.0,31.93.0,30.126.0,38.114.0,50.176.0"}
P.entries["quest:96895"] = {n="The Argent Emissary",s="银色特使标志着两名效力于银色黎明的被遗忘者代表抵达此地，追踪幽暗城附近的亡灵天灾邪教徒。他们的出现既凸显了双方共同对抗天灾军团的事实，也反映了这个中立组织与被遗忘者当局之间微妙的紧张关系。",h="银色特使标志着两名效力于银色黎明的被遗忘者代表抵达此地，追踪幽暗城附近的亡灵天灾邪教徒。他们的出现既凸显了双方共同对抗天灾军团的事实，也反映了这个中立组织与被遗忘者当局之间微妙的紧张关系。",kw={"银色黎明","银色特使","邪教徒","被遗忘者","天灾军团邪教徒","提瑞斯法林地","幽暗城"},ang={["faction:Horde"]="虽然银色黎明是中立的，但部落当局对他们在幽暗城附近的独立行动保持着警惕。",["race:Undead"]="看到被遗忘者同胞选择加入银色黎明而非幽暗城，这鲜明地提醒了人们自由亡灵之间效忠对象的不同。"},sec={{t="谨慎的欢迎",b="两名来自银色黎明的被遗忘者使者最近抵达了提瑞斯法林地，这让当地的当局感到不安。尽管银色黎明反对天灾军团，但当地的被遗忘者依然对任何未经监督就在其领土内活动的武装中立组织持怀疑态度。即使这些使者本身就是同族，也难以缓解他们的警惕。"},{t="大门外的邪教徒",b="这些使者并非为了瞻仰洛丹伦废墟而来；他们正在追踪一群被发现潜伏在幽暗城东南郊外的天灾军团邪教徒。为了在巫妖王的代理人站稳脚跟前将其铲除，其中一名使者已经前往城门附近，监视敌人的动向。"}},faq={{q="银色黎明使者是什么人？",a="两名代表银色黎明的使者最近前往了提瑞斯法林地。值得注意的是，这两名使者都是已经加入该神圣中立组织的被遗忘者，而不是单纯效力于幽暗城。",al={"谁是使者","银色黎明访客","谁来到了提瑞斯法"}},{q="为什么银色黎明要在幽暗城附近活动？",a="他们正在追踪在幽暗城东南郊外窥探的天灾军团邪教徒。银色黎明致力于在任何天灾残党出现的地方将其猎杀，即使是在部落的主要定居点附近也是如此。",al={"为什么他们在幽暗城附近","银色黎明提瑞斯法任务","使者在做什么"}},{q="为什么当地的被遗忘者对这些使者保持警惕？",a="尽管银色黎明与天灾军团这一共同敌人作战，但当地的被遗忘者并不喜欢中立的武装组织在没有监督的情况下在提瑞斯法林地活动，无论这些使者是否与他们同为亡灵。",al={"为什么对银色黎明感到紧张","我们能信任银色黎明吗","被遗忘者对银色黎明的看法"}},{q="邪教徒构成了什么威胁？",a="一小群天灾军团邪教徒被发现在城市东南的郊外潜伏。由于巫妖王对自由亡灵持续构成的威胁，他们的出现立刻引起了当地斥候和银色黎明的注意。",al={"幽暗城外的邪教徒","提瑞斯法的亡灵天灾","邪教徒是什么人"}},{q="使者去哪了？",a="其中一名使者向东南方移动，前往幽暗城的入口，跟踪监视那些在城墙外活动的亡灵天灾邪教徒。",al={"在哪里可以找到使者","使者位置","寻找银色黎明成员"}},{q="被遗忘者可以在银色黎明效力吗？",a="可以。与血色十字军不同，银色黎明欢迎所有愿意对抗天灾军团的人，包括那些投身于此事业的自由意志亡灵。",al={"被遗忘者是否允许加入银色黎明","银色黎明亡灵","亡灵能否加入银色黎明"}}},fp="19,181,12.319.0,21.231.0,30.157.0,52.185.0,46.173.0,41.187.0,26.111.0,41.161.0"}
P.entries["quest:96896"] = {n="A Righteous Cause",s="“正义事业”见证了受人尊敬的列奥尼德·巴萨洛缪与达妮萨·莫尔之间的交谈，他们回顾了幽暗城防御纳克萨玛斯进攻的往事。他们的交流重点提到了加瑞克·班达里恩，一位重新发掘如何以圣骑士身份运用圣光的被遗忘者英雄。该任务揭示了那些尽管遭到同胞质疑，却依然努力维持与圣光联系的少数被遗忘者。",h="“正义事业”见证了受人尊敬的列奥尼德·巴萨洛缪与达妮萨·莫尔之间的交谈，他们回顾了幽暗城防御纳克萨玛斯进攻的往事。他们的交流重点提到了加瑞克·班达里恩，一位重新发掘如何以圣骑士身份运用圣光的被遗忘者英雄。该任务揭示了那些...",kw={"达妮萨·莫尔","被遗忘者","加瑞克·班达里恩","列奥尼德·巴萨洛缪","圣光之愿礼拜堂","纳克萨玛斯","圣骑士","正义事业","天灾军团","幽暗城"},ang={["class:Paladin"]="加瑞克·班达里恩和达妮萨的队伍代表了一种非凡的发展：被遗忘者尽管处于亡灵状态，却重新发掘了以圣骑士身份运用圣光的方法。",["faction:Horde"]="列奥尼德·巴萨洛缪的出现凸显了幽暗城防御者与驻扎在瘟疫之地圣光之愿礼拜堂的银色黎明之间的联系。",["race:Undead"]="虽然列奥尼德和达妮萨努力与圣光重新建立联系，但大多数被遗忘者仍然对他们在亡灵状态下的这条圣光之路保持冷漠或敌视。"},sec={{t="老兵重聚",b="“正义事业”围绕两位洛丹伦老兵防御者的感人重聚展开：受人尊敬的列奥尼德·巴萨洛缪和达妮萨·莫尔。在经历了纳克萨玛斯向幽暗城发动天灾军团袭击的惨烈战斗后，两人共同缅怀了阵亡的战友，并反思了那些依然崇敬圣光的被遗忘者所走的艰难道路。"},{t="加瑞克·班达里恩的遗产",b="他们共同记忆的焦点是加瑞克·班达里恩，这座堡垒正是以这位阵亡英雄的名字命名的。据列奥尼德所言，加瑞克或许是第一位重新发掘如何以真正的圣骑士身份运用圣光的被遗忘者。虽然大多数被遗忘者已经完全背弃了圣光，但达妮萨和她的同伴致力于继承加瑞克的遗产，并探索圣光不死之身的潜力。"},{t="重返瘟疫之地",b="与达妮萨谈话后，列奥尼德准备离开堡垒。他的忠诚属于在满目疮痍的东部地区持续对抗天灾军团的战斗，他在东瘟疫之地的圣光之愿礼拜堂驻扎，欢迎任何愿意为这一事业拿起武器的健壮冒险者。"}},faq={{q="受人尊敬的列奥尼德·巴萨洛缪是谁？",a="受人尊敬的列奥尼德·巴萨洛缪是银色黎明中一位著名的亡灵成员。虽然他在东瘟疫之地的圣光之愿礼拜堂开展工作，但他仍与洛丹伦曾并肩对抗天灾军团的旧日战友保持着联系。",al={"列奥尼德·巴萨洛缪是谁","列奥尼德","列奥尼德·巴萨洛缪背景故事"}},{q="达妮萨·莫尔是谁？",a="达妮萨·莫尔是一位在纳克萨玛斯袭击幽暗城时与列奥尼德·巴萨洛缪并肩作战的被遗忘者领袖。她现在领导着一支致力于传承加瑞克·班达里恩的教诲和神圣遗产的队伍。",al={"达妮萨·莫尔是谁","达妮萨","达妮萨·莫尔背景故事"}},{q="加瑞克·班达里恩是谁？",a="加瑞克·班达里恩是一位英勇的被遗忘者战士，在纳克萨玛斯袭击幽暗城的防御战中阵亡。列奥尼德指出，他可能是第一位重新发掘如何以圣骑士身份运用圣光的被遗忘者。",al={"加瑞克·班达里恩是谁","加瑞克·班达里恩背景故事","堡垒命名来源"}},{q="幽暗城受袭期间发生了什么？",a="当纳克萨玛斯大墓地对幽暗城发起突袭时，包括达妮萨·莫尔、列奥尼德·巴萨洛缪和加瑞克·班达里恩在内的被遗忘者勇士们团结起来，共同抵御天灾军团的猛攻，在战斗中损失惨重。",al={"幽暗城纳克萨玛斯袭击","幽暗城之战","天灾军团袭击幽暗城"}},{q="被遗忘者能以圣骑士的身份运用圣光吗？",a="虽然引导圣光会给亡灵躯体带来剧痛，且被大多数被遗忘者所排斥，但加瑞克·班达里恩证明了亡灵战士以圣骑士身份运用圣光是可能的，这也是达妮萨和她的同伴继续研究的方向。",al={"被遗忘者可以成为圣骑士吗","亡灵圣骑士背景","运用圣光的被遗忘者"}},{q="列奥尼德·巴萨洛缪之后去了哪里？",a="在拜访朋友并与达妮萨·莫尔交谈后，列奥尼德计划返回东瘟疫之地的圣光之愿礼拜堂，银色黎明在那里协调针对天灾军团的十字军征讨。",al={"列奥尼德去哪了","之后在哪里找到列奥尼德","圣光之愿礼拜堂列奥尼德"}}},fp="17,257,19.268.0,29.329.0,25.260.0,38.223.0,20.194.0,24.192.0,49.211.0,45.214.0,44.197.0"}
P.entries["quest:96897"] = {n="诅咒神教",s="诅咒神教是活跃在提瑞斯法林地内，威胁着天灾军团凡人仆从的一项任务。通过清除黑暗新信徒和黑暗执行者，防御者能够阻止巫妖王那些阴险的活人代理人重演当年摧毁洛丹伦的背叛行径。",h="诅咒神教是活跃在提瑞斯法林地内，威胁着天灾军团凡人仆从的一项任务。通过清除黑暗新信徒和黑暗执行者，防御者能够阻止巫妖王那些阴险的活人代理人重演当年摧毁洛丹伦的背叛行径。",kw={"诅咒神教","黑暗执行者","黑暗新信徒","活着的仆从","洛丹伦","通灵术","天灾军团","提瑞斯法林地"},ang={["class:Paladin"]="圣骑士曾立誓要铲除摧毁洛丹伦的阴影，这使得致力于天灾军团的活人邪教徒成为了圣光的不共戴天之敌。",["class:Priest"]="所有流派的牧师都认识到诅咒神教所代表的信仰扭曲，这些人用神圣的虔诚换取了黑暗的通灵术。",["race:Undead"]="被遗忘者非常清楚这些活着的邪教徒是如何摧毁洛丹伦并导致他们沦为亡灵的。在提瑞斯法阻止新的邪教组织对于保卫这个新王国至关重要。"},sec={{t="天灾军团的凡人代理人",b="诅咒神教代表了天灾军团的凡人面孔。这些邪教徒由发誓效忠巫妖王的活人男女组成，他们在没有思想的死者无法行动的地方进行活动。在提瑞斯法林地，当地居民本已在应付游荡的亡灵和血色十字军那毫不留情的狂热分子，而新发现的黑暗新信徒和黑暗执行者巢穴则发出了天灾军团试图重新建立立足点的阴险信号。"},{t="陨落的教训",b="洛丹伦的毁灭不仅是因为亡灵军团的进军，更是因为邻里之间的互相背叛。诅咒神教最初渗透进各个村庄，毒害粮仓，并从阴影中策划了王国的崩溃。在提瑞斯法对新的邪教活动保持警惕，对于确保历史不会在这片北方的伤痕之地重演至关重要。"}},faq={{q="什么是诅咒神教？",a="诅咒神教是一个由自愿侍奉巫妖王和天灾军团的凡人组成的组织。这些活着的侍僧并非被复活为无脑的亡灵，而是刻意为了侍奉死亡而散布瘟疫、破坏防御并进行通灵术。",al={"什么是诅咒神教","谁是邪教徒","谁是黑暗新信徒"}},{q="为什么邪教成员会在提瑞斯法林地活动？",a="提瑞斯法林地仍然是一片充满争议的边境之地，这里不仅有游荡的无脑亡灵、血色十字军的狂热分子，还有幸存的天灾军团残党。邪教在该地区秘密行动，以破坏当地的抵抗力量并推进天灾军团的黑暗计划。",al={"为什么邪教徒在提瑞斯法","提瑞斯法林地的邪教"}},{q="谁是黑暗新信徒和黑暗执行者？",a="黑暗新信徒是刚开始学习黑暗艺术和仪式的初学者，而黑暗执行者则充当守卫邪教行动并维护组织纪律的打手。他们共同在地面上组成了活跃的行动小组。",al={"谁是黑暗执行者","黑暗新信徒的作用"}},{q="为什么说活着的仆从比无脑的亡灵更糟糕？",a="无脑的亡灵仅凭本能或直接命令行动，但活着的邪教徒却是出于完全的清醒而选择了背叛。他们能够融入凡人社会并渗透进定居点的能力，使他们比游荡的食尸鬼或骷髅要阴险得多。",al={"为什么活着的邪教徒更糟","天灾军团的活人仆从"}},{q="任务中所说的“不要让洛丹伦的历史重演”是什么意思？",a="洛丹伦的陨落不仅是因为一场公开的外部入侵，更是因为诅咒神教在内部悄悄毒害了粮食供应，并背叛了自己的同胞。允许邪教徒立足，只会招致同样的灾难。",al={"洛丹伦历史重演","洛丹伦的陷落与邪教"}},{q="该邪教与提瑞斯法的血色十字军有何关系？",a="血色十字军疯狂地猎杀任何受到亡灵天灾污染的事物，这使得天灾军团和该邪教都成为了他们的主要目标。这种持续不断的冲突使当地居民陷入了无脑的恐怖生物、狂热的十字军和隐秘的邪教徒之间。",al={"与血色十字军的关系","邪教与血色十字军"}}},fp="22,219,28.323.0,19.316.0,31.229.0,57.215.0,46.182.0,62.226.0,74.194.0,60.224.0"}
P.entries["quest:96898"] = {n="Remnants of War",s="“战争残余”委托冒险者回收纳克萨玛斯在袭击幽暗城时坠落的亡灵聚焦水晶碎片。被遗忘者和银色黎明在击退这座浮空城时都遭受了惨重的损失，收集这些危险的碎片可以阻止天灾军团的邪教徒利用其中的黑暗魔法。",h="“战争残余”委托冒险者回收纳克萨玛斯在袭击幽暗城时坠落的亡灵聚焦水晶碎片。被遗忘者和银色黎明在击退这座浮空城时都遭受了惨重的损失，收集这些危险的碎片可以阻止天灾军团的邪教徒利用其中的黑暗魔法。",kw={"银色黎明","邪教徒","被遗忘者","纳克萨玛斯","亡灵水晶碎片","战争的残余","天灾军团","提瑞斯法林地","幽暗城"},ang={["class:Mage"]="即便是破碎且大多已耗尽能量，纳克萨玛斯的亡灵聚焦水晶依然保留着不稳定的魔法能量，需要极端谨慎地对待。",["class:Priest"]="亡灵碎片中残留的邪恶腐化代表着一种危险的枯萎病，必须在它进一步玷污这片土地之前将其封存。",["faction:Horde"]="从残留的天灾魔法中保护提瑞斯法林地，有助于守护幽暗城并巩固部落在洛丹伦北部的关键据点。",["race:Undead"]="纳克萨玛斯的袭击威胁到了幽暗城的存亡。回收这些碎片可以保护你的人民免受家门口的天灾死灰复燃的威胁。"},sec={{t="城上阴影",b="不久前，恐怖的浮空城纳克萨玛斯曾笼罩在提瑞斯法林地上空，企图摧毁幽暗城并将被遗忘者彻底抹去。在一场孤注一掷的防御战中，被遗忘者和银色黎明付出了巨大代价才击退了这座浮空要塞。战斗中，纳克萨玛斯顶端巨大的亡灵聚焦水晶被摧毁，碎片散落到下方的林地中。"},{t="散落的死灵术",b="尽管纳克萨玛斯已经被击退，但残留的碎片仍深深嵌入了土地之中。天灾军团的邪教徒们开始行动，试图回收这些亡灵水晶碎片，希望汲取其中残留的黑暗魔法。收集这些碎片能够剥夺天灾军团的原始邪恶力量，尽管要将所有碎片从提瑞斯法林地清理干净，可能需要数年的时间。"}},faq={{q="什么是亡灵水晶碎片？",a="它们是曾经安装在恐怖浮空城纳克萨玛斯顶端的大型亡灵聚焦水晶破碎后的残片。当水晶在针对幽暗城的袭击中被摧毁时，碎片像雨点般落在了提瑞斯法林地上。",al={"什么是亡灵水晶碎片","这些水晶是什么","亡灵水晶"}},{q="纳克萨玛斯为什么要袭击幽暗城？",a="纳克萨玛斯降临提瑞斯法林地，直接目的是毁灭幽暗城并将被遗忘者从地图上彻底抹去。被遗忘者和银色黎明的联合防御成功击退了这座浮空城，但双方阵营都遭受了惨重的损失。",al={"为什么纳克萨玛斯要进攻","纳克萨玛斯袭击幽暗城","纳克萨玛斯在这里做了什么"}},{q="为什么天灾军团的邪教徒要收集这些水晶碎片？",a="天灾军团的邪教徒正在搜寻提瑞斯法林地以回收这些破碎的残片。即使已经破损且耗尽能量，这些水晶中仍然残留着天灾军团可以回收或用于其邪恶仪式的亡灵魔法。",al={"为什么邪教徒想要水晶","邪教徒要残片做什么","天灾军团邪教徒水晶"}},{q="接触这些亡灵水晶危险吗？",a="是的。尽管已经破碎且大部分主要充能已经耗尽，这些碎片仍然蕴含着强大且不稳定的亡灵能量，直接进行身体接触是非常危险的。",al={"水晶接触危险吗","水晶身体接触","亡灵水晶会伤人吗"}},{q="谁帮助被遗忘者击退了纳克萨玛斯？",a="在保卫幽暗城的战斗中，被遗忘者与银色黎明并肩作战，共同对抗纳克萨玛斯的部队，为了确保被遗忘者的生存而付出了沉重的人员伤亡。",al={"谁在纳克萨玛斯之战中作战","谁保卫了幽暗城","银色黎明保卫幽暗城"}},{q="提瑞斯法林地里的亡灵水晶会被清理干净吗？",a="短期内很难清理完毕。因为巨大的水晶是在高空破碎的，碎片散落得到处都是，这意味着当地居民可能在未来几年里都得不断从土地中清理这些残片。",al={"提瑞斯法会清理干净水晶吗","他们能清理所有残片吗","提瑞斯法残留的水晶"}}},fp="15,287,24.346.0,20.278.0,40.203.0,39.168.0,58.160.0,44.144.0,44.124.0,61.182.0"}
P.entries["quest:96899"] = {n="班达里安堡",s="班达里安堡是提瑞斯法林地中的一个任务，指引冒险者前往一处隐秘的要塞会见银色黎明指挥官莱奥尼德·巴萨洛梅。这座堡垒曾是银色黎明对抗天灾军团的集结基地，现在由达尼莎和她的圣骑士教团负责维护。",h="班达里安堡是提瑞斯法林地中的一个任务，指引冒险者前往一处隐秘的要塞会见银色黎明指挥官莱奥尼德·巴萨洛梅。这座堡垒曾是银色黎明对抗天灾军团的集结基地，现在由达尼莎和她的圣骑士教团负责维护。",kw={"银色黎明","班达里安堡","诅咒神教","达尼莎","莱奥尼德·巴萨洛梅","圣骑士","天灾军团","提瑞斯法林地"},ang={["class:Paladin"]="班达里安堡是由达尼莎和她的圣骑士同伴们管理的据点，作为提瑞斯法林地对抗黑暗势力的圣洁堡垒。"},sec={{t="堡垒的召唤",b="班达里安堡是一个银色黎明的任务，指引冒险者穿过提瑞斯法林地去会见指挥官莱奥尼德·巴萨洛梅。在协助银色黎明对抗诅咒神教的活动后，旅行者被指引向西北方前往要塞，与指挥官会合，并进一步了解该组织针对黑暗势力的持续远征。"},{t="历史与管理",b="这座据点曾是银色黎明在提瑞斯法林地对抗天灾军团入侵时的重要集结地。当银色黎明将重心转向东瘟疫之地和西瘟疫之地时，这座堡垒被遗弃，面临着沦为废墟的危险，直到圣骑士达尼莎和她的同伴接管了这里。"},{t="关于一位共同好友的回忆",b="在要塞与莱奥尼德·巴萨洛梅重逢时，这位指挥官回顾了曾经在这里的城墙上进行的战斗。虽然他为这座据点没有被荒废感到欣慰，但他提到，是达尼莎为了纪念一位共同的好友才为其命名。"}},faq={{q="莱奥尼德·巴萨洛梅是谁？",a="莱奥尼德·巴萨洛梅是银色黎明的一位指挥官。在早些时候天灾军团入侵提瑞斯法林地时，他曾将班达里安堡作为基地，现在他已返回此处与达尼莎和她的圣骑士们会面。",al={"莱奥尼德·巴萨洛梅是谁","莱奥尼德·巴萨洛梅在哪里","莱奥尼德 班达里安堡"}},{q="什么是班达里安堡？",a="班达里安堡是一座位于提瑞斯法林地西部的要塞。它最初是银色黎明在天灾军团袭击期间的前哨站，当该组织撤回瘟疫之地后，它曾一度失修，后来被达尼莎的圣骑士们修复并占据。",al={"什么是班达里安堡","班达里安堡历史","谁占据着班达里安堡"}},{q="达尼莎是谁？",a="达尼莎是一位圣骑士，在银色黎明向东撤往瘟疫之地后，她与她的教团接管了班达里安堡的管理工作。她还以一位与莱奥尼德·巴萨洛梅共同的好友的名义，为这座堡垒命名。",al={"达尼莎是谁","达尼莎 圣骑士","谁管理班达里安堡"}},{q="为什么它被称为班达里安堡？",a="这座要塞由达尼莎命名，以纪念她和指挥官莱奥尼德·巴萨洛梅共同的一位好友。",al={"为什么命名为班达里安堡","班达里安是谁","班达里安名字含义"}},{q="银色黎明为什么对班达里安堡感兴趣？",a="银色黎明的成员前往班达里安堡与达尼莎的圣骑士们进行协调，并保持警惕，以对抗提瑞斯法林地各处的天灾军团势力和诅咒神教的活动。",al={"为什么要前往班达里安堡","银色黎明 提瑞斯法林地","班达里安堡 银色黎明"}},{q="银色黎明以前为什么要放弃这座堡垒？",a="当银色黎明将主力部队转移到东方，在瘟疫之地与天灾军团作战时，他们从要塞中撤出，留下了这座空荡荡的建筑，直到达尼莎和她的圣骑士们介入并进行了维护。",al={"战争结束后堡垒发生了什么","银色黎明为什么要离开班达里安堡"}}},fp="14,214,21.234.0,23.298.0,27.172.1,26.184.0,23.226.0,15.205.0,32.93.0,52.180.0,52.183.0"}
P.entries["quest:96984"] = {n="Heart of Disruption",s="大法师沃迪恩·伍德格莱尔让你穿过他的结界进入达拉然，寻找奥术微粒。他担心这座城市陷落也会给幽暗城带来灾难。",h="大法师沃迪恩·伍德格莱尔让你穿过他的结界进入达拉然，寻找奥术微粒。他担心这座城市陷落也会给幽暗城带来灾难。",kw={"奥术微粒","达拉然","heart of disruption","大法师沃迪恩·伍德格莱尔","塔伦米尔","幽暗城","紫罗兰城堡","结界"},sec={{t="穿越结界的钥匙",b="塔伦米尔的大法师沃迪恩·伍德格莱尔让你带着一把他注入魔力的钥匙进入达拉然，以穿过他的结界。他担心这座城市一旦陷落，幽暗城也会受到威胁。找到奥术微粒后，前往紫罗兰城堡与他会合，那里正是事情开始的地方；当务之急是避免灾难。"}},faq={{q="是谁派我去达拉然？",a="塔伦米尔的大法师沃迪恩·伍德格莱尔派你前往达拉然寻找奥术微粒。",al={"是谁给了我这个","沃迪恩·伍德格莱尔","大法师是谁"}},{q="我为什么要去达拉然？",a="你受命寻找奥术微粒。沃迪恩担心达拉然陷落会连累幽暗城。",al={"为什么去达拉然","我要找什么","达拉然任务"}},{q="我怎样才能穿过沃迪恩的结界？",a="沃迪恩会为你的钥匙注入魔力，让它穿过他的结界，使你得以进入这座城市。",al={"钥匙","达拉然钥匙","穿过结界"}},{q="我该在哪里与沃迪恩会合？",a="沃迪恩要你在达拉然的紫罗兰城堡与他会合，那里正是事情开始的地方。",al={"与大法师会合","紫罗兰城堡","沃迪恩在哪里"}},{q="沃迪恩最优先考虑的是什么？",a="沃迪恩说，当务之急是避免灾难。",al={"避免灾难","什么最重要","优先事项"}}},fp="19,161,23.287.0,24.85.0,26.107.0,34.76.0,28.80.0,33.50.0"}
P.entries["quest:96986"] = {n="The Grave Knight",s="塔伦米尔的梅里萨拉要你去对付阿特雷克西斯。他是个在达拉然城下复活死者的亡灵法师。她认为他的所作所为冒犯了被遗忘者。",h="塔伦米尔的梅里萨拉要你去对付阿特雷克西斯。他是个在达拉然城下复活死者的亡灵法师。她认为他的所作所为冒犯了被遗忘者。",kw={"阿特雷克西斯","达拉然","被遗忘者","墓穴骑士","梅里萨拉","亡灵法师","塔伦米尔","亡灵大军"},ang={["faction:Alliance"]="梅里萨拉派你去追捕阿特雷克西斯时说，她并不在意达拉然的命运。",["race:Undead"]="梅里萨拉称阿特雷克西斯是被遗忘者的叛徒，并说他的亡灵大军违背了他们的信念。"},sec={{t="梅里萨拉的命令",b="梅里萨拉说，阿特雷克西斯是被遗忘者的叛徒，并在达拉然城下组建亡灵大军。她要你替她击败墓穴骑士。她并不在意这座法师之城的命运，但她说，没人能逃脱黑暗女王的掌控。"}},faq={{q="墓穴骑士是谁？",a="阿特雷克西斯是达拉然的一名亡灵法师，梅里萨拉称他为墓穴骑士。",al={"阿特雷克西斯","阿特雷克西斯墓穴骑士","墓穴骑士是谁"}},{q="是谁派我去追捕阿特雷克西斯？",a="塔伦米尔的梅里萨拉要你击败阿特雷克西斯。",al={"谁发布了墓穴骑士任务","梅里萨拉阿特雷克西斯","谁想杀死阿特雷克西斯"}},{q="梅里萨拉为什么要击败阿特雷克西斯？",a="梅里萨拉说，阿特雷克西斯是被遗忘者的叛徒，正在组建亡灵大军。",al={"为什么杀死阿特雷克西斯","为什么是墓穴骑士","被遗忘者对付阿特雷克西斯的原因"}},{q="阿特雷克西斯在哪里？",a="阿特雷克西斯在达拉然城。",al={"阿特雷克西斯的位置","墓穴骑士的位置","墓穴骑士在哪里"}}},fp="16,135,17.210.0,24.74.0,26.51.0,40.98.0,17.34.0"}
P.entries["quest:96987"] = {n="Opportunistic Education",s="Rexxie Copperclutch趁达拉然的法师忙于他事，请你去图书馆取一本典籍。她想卖掉这本书，并与你平分所得。",h="Rexxie Copperclutch趁达拉然的法师忙于他事，请你去图书馆取一本典籍。她想卖掉这本书，并与你平分所得。",kw={"达拉然","达拉然的建立","图书馆","法师","投机取巧的求知","rexxie copperclutch","典籍","亡灵"},ang={["race:Undead"]="作为亡灵，Rexxie称你志趣相投，并欢迎你加入她的计划。"},sec={{t="为Rexxie取书",b="Rexxie Copperclutch就在下水道入口附近，她看中了达拉然图书馆里的赚钱机会。趁法师们忙于他事，她请你把一本名为Founding of 达拉然的典籍带给她。她愿意与你平分卖书所得。"},{t="书值多少",b="Rexxie觉得你带回来的书不值几个钱。她考虑给书喷上金漆，再声称它曾属于一位大法师。"}},faq={{q="谁想要这本书？",a="Rexxie Copperclutch就在达拉然的下水道入口附近，她请你去城里的图书馆给她找一本典籍。",al={"谁想要这本典籍","rexxie copperclutch","rexxie是谁"}},{q="Rexxie想要哪本书？",a="Rexxie想要《Founding of 达拉然》。",al={"什么书","达拉然的建立","典籍名称"}},{q="Rexxie为什么想要这本典籍？",a="Rexxie想卖掉这本典籍，并与你平分所得。",al={"为什么偷书","这本书有什么用"}},{q="这本书应该从哪里找？",a="Rexxie请你去达拉然城寻找《Founding of 达拉然》。",al={"去哪里找典籍","达拉然图书馆","书的位置"}},{q="达拉然的法师们怎么了？",a="Rexxie说法师们正忙着，她便请你去找一本书。",al={"法师正忙","为何趁机行事","达拉然法师"}},{q="Rexxie觉得你带回来的书怎么样？",a="Rexxie觉得这本书不值几个钱，还考虑给它喷上金漆，让它看起来更值钱。",al={"这本书值钱吗","这本典籍会怎样","rexxie的反应"}}},fp="23,157,17.231.0,18.142.1,27.109.0,28.36.0,30.60.0,40.67.0,41.73.0,45.103.0"}
P.entries["quest:96988"] = {n="Source of Power",s="Source of Power是幽暗城的一项任务，由马丁·费尔本医生委托，他试图利用达拉然内部的动荡。当这座魔法城市正遭受其自身流氓构装体围攻时，费尔本指派冒险者去获取它们的奥术核心。他的野心是将达拉然的魔法科技与被遗忘者的缝合技术相结合，制造出注入奥术力量的憎恶，从而引起黑暗女王的注意。",h="Source of...",kw={"憎恶","奥术构装体","破碎的哨兵核心","达拉然","马丁·费尔本医生","皇家药剂师学会","力量之源","希尔瓦娜斯·风行者","幽暗城"},ang={["class:Mage"]="法师们会发现达拉然的魔法构装体反戈一击，而它们先进的奥术能源却被掠夺去进行幽暗城的恐怖炼金实验，这真是一种残酷的讽刺。",["faction:Horde"]="在洛丹伦活动的部落冒险者支持被遗忘者从周围的竞争对手那里获取先进军事资产的努力，此时达拉然正因其自身的流氓造物而陷入瘫痪。",["profession:Engineering"]="工程师们可以欣赏达拉然自主哨兵背后复杂的工艺，即使它们脆弱的奥术动力核心被拆除，去供给恐怖的缝合憎恶。",["race:Undead"]="被遗忘者严重依赖皇家药剂师学会冷酷的创新来在洛丹伦求得生存。协助费尔本医生可以推进该派系在黑暗女王监视下对奥术缝合术的研究。"},sec={{t="投机取巧的收割",b="达拉然这座魔法城市内的混乱为被遗忘者创造了一个他们渴望利用的缺口。随着达拉然自身的奥术构装体失控暴走并围攻法师们，马丁·费尔本医生在这场混乱中看到了一个绝佳的机会。这位药剂师没有向被围困的施法者提供援助，而是寻求搜刮那些为这些流氓守卫提供动力的奥术核心。长期以来，达拉然一直严密守护着其魔法研究，但目前的脆弱状态使得其魔法哨兵成为了幽暗城那些机会主义研究者眼中的肥肉。"},{t="皇家药剂师学会的野心",b="费尔本医生对破碎的哨兵核心的兴趣完全源于他在皇家药剂师学会内的个人野心。费尔本梦想着通过向被遗忘者的憎恶中注入不稳定的达拉然构装体魔法，来组建一支具有奥术动力的毁灭性肉体野兽大军。他计算过，这样的恐怖突破将能吸引希尔瓦娜斯·风行者的全部注意力，并展示他无与伦比的炼金天赋。最终，费尔本希望这一发明能大幅提升他的地位，甚至可能确保他获得皇家药剂师学会的领导权，这是一个崇尚冷酷狡诈和强大成果来决定生存与排名的派系。"}},faq={{q="谁发布了力量之源任务？",a="该任务由马丁·费尔本医生发布，他是一位居住在被遗忘者首都幽暗城的药剂师。费尔本是一位雄心勃勃的研究员，他试图通过开发全新的军事怪兽来向皇家药剂师学会和希尔瓦娜斯·风行者证明自己的炼金才华。",al={"谁发布力量之源","力量之源任务发布者","马丁·费尔本任务"}},{q="在此任务期间达拉然发生了什么？",a="达拉然目前正遭受其自身奥术构装体的围攻，这些构装体已经反戈一击。魔法城市内部由此产生的混乱和战斗为局外人创造了一个难得的机会，可以潜入达拉然并打捞那些驱动这些流氓守卫的强大魔法组件。",al={"达拉然发生了什么","达拉然被围攻","为什么构装体攻击达拉然"}},{q="费尔本医生为什么想要这些构装体核心？",a="费尔本医生打算利用达拉然哨兵核心内的奥术能量来增强被遗忘者的憎恶。通过将原始的奥术机械与缝合技术相结合，他希望创造出一支奥术驱动的憎恶大军，向希尔瓦娜斯·风行者证明他的炼金术造诣。",al={"为什么要收集哨兵核心","费尔本需要核心做什么","费尔本的哨兵核心计划"}},{q="力量之源的任务目标是什么？",a="冒险者被指派前往达拉然城，对抗流氓构装体并收集六个破碎的哨兵核心。一旦获得，这些不稳定的魔法遗物必须运回幽暗城交给马丁·费尔本医生，以供给他正在进行的实验。",al={"力量之源目标","我需要多少个核心","力量之源收集什么"}},{q="费尔本医生在皇家药剂师学会内的目标是什么？",a="马丁·费尔本医生寻求在被遗忘者的等级制度中获得认可和快速晋升。通过向希尔瓦娜斯·风行者展示一支由奥术强化的憎恶组成的强大部队，他希望给这位黑暗女王留下足够深刻的印象，从而被任命为皇家药剂师学会的领导者。",al={"费尔本药剂师的目标","谁领导皇家药剂师学会","费尔本获得黑暗女王认可"}},{q="为什么被遗忘者要搜刮达拉然的技术？",a="皇家药剂师学会和被遗忘者不断寻找非传统的武器和能源，以确保他们在洛丹伦的生存。在达拉然内部防御崩溃时利用这座魔法城市，使被遗忘者的药剂师能够在不与法师正式交战的情况下获得先进的奥术组件。",al={"为什么被遗忘者想要达拉然的魔法","幽暗城达拉然构装体","被遗忘者对达拉然的兴趣"}},{q="在哪里可以找到破碎的哨兵核心？",a="破碎的哨兵核心可以从目前正在围攻达拉然城的流氓构装体身上收集。玩家必须在这座魔法城市中与这些充满敌意的附魔守卫战斗，从而为费尔本医生在幽暗城的研究提取必要的完整组件。",al={"在哪里寻找破碎的哨兵核心","破碎的哨兵核心位置","达拉然哨兵核心掉落"}}},fp="15,210,24.393.0,34.472.0,36.238.0,47.222.0,48.276.0,44.181.0,65.242.0,53.298.0,41.186.0"}
P.entries["quest:97"] = {n="斯塔文的传说",s="调查的这一阶段终于证实了将这位行踪诡秘的导师与夜色镇的记录联系起来的邪恶真相。书记员达尔塔成功地将从寻回文件中发现的笔迹与斯塔文·密斯曼托进行了比对，并立即向指挥官阿尔泰娅·埃伯洛克进行了汇报。这一时刻标志着守夜人的怀疑成为了不可否认的事实。",h="调查的这一阶段终于证实了将这位行踪诡秘的导师与夜色镇的记录联系起来的邪恶真相。书记员达尔塔成功地将从寻回文件中发现的笔迹与斯塔文·密斯曼托进行了比对，并立即向指挥官阿尔泰娅·埃伯洛克进行了汇报。这一时刻标志着守夜人的怀疑...",kw={"阿尔泰娅·埃伯洛克","书记员达尔塔","夜色镇","暮色森林","笔迹","密斯曼托","守夜人","斯塔文"},ang={["faction:Alliance"]="对于联盟的调查者来说，解开斯塔文的线索证明了夜色镇饱受打击的领导层与四处游历的冒险者之间必须进行必要的合作，才能确保王国南部领土的安全。",["race:Human"]="人类玩家在这里看到了自身社会悲剧性的衰落，受人尊敬的导师和乡村城镇一样，悄无声息地从文明滑向了疯狂与孤立。"},sec={{t="记录比对",b="在搜遍了人类王国各地的遥远庄园、旅店和市政档案后，破碎的线索回到了夜色镇的市政厅。书记员达尔塔将染血的日记页面与城镇登记册上的签名进行了比对。结果是不言而喻的：笔迹属于斯塔文·密斯曼托，这为守夜人提供了将此事视为紧急地方威胁所需的铁证。"},{t="守夜人的怀疑",b="从调查一开始，指挥官阿尔泰娅·埃伯洛克就对斯塔文有着不祥的预感。暮色森林本已在狂暴的狼人、骷髅亡灵和潜伏的通灵师的重压下不堪重负；一个隐藏在森林阴影中、下落不明的凶手是她无法忽视的危险。收到达尔塔的确认验证了她最深层的恐惧，也让守夜人开始着手定位并彻底铲除这个隐居者。"}},faq={{q="书记员达尔塔发现了什么？",a="书记员达尔塔将染血的日记页面与夜色镇城镇登记册上的签名进行了比对，并确认笔迹与斯塔文·密斯曼托完全吻合，正如指挥官埃伯洛克所怀疑的那样。",al={"达尔塔发现了什么","达尔塔笔迹比对","斯塔文笔迹证据"}},{q="为什么指挥官阿尔泰娅·埃伯洛克如此在意斯塔文？",a="指挥官阿尔泰娅·埃伯洛克领导着夜色镇那支饱受困扰的民兵组织——守夜人。在这片本已深受恐怖威胁的土地上，她不能容忍一个有着黑暗过去的暴力阴影人物在暮色森林境内逍遥法外且下落不明。",al={"为什么阿尔泰娅要在意","埃伯洛克调查","守夜人斯塔文"}},{q="这一步发生在什么地方？",a="这一步全部发生在夜色镇内。书记员达尔塔驻守在市政厅内，而指挥官阿尔泰娅·埃伯洛克则可以在镇中心道路附近巡逻时找到。",al={"这个任务在哪里","任务地点","夜色镇斯塔文交任务"}},{q="上报笔迹比对结果后会发生什么？",a="一旦指挥官埃伯洛克收到书记员达尔塔的确认，调查重点就会转向在暮色森林闹鬼的荒野中积极搜寻斯塔文目前的下落。",al={"斯塔文下一步","达尔塔比对之后","斯塔文系列任务下一步"}},{q="斯塔文·密斯曼托原本是谁？",a="斯塔文·密斯曼托曾经在月溪镇校舍任教，后来担任弗林特里奇家族孩子的私人导师。他留下的书信和日记页的线索从月溪镇和闪金镇一路延伸回暮色森林，如今他作为一名危险的隐居者生活在森林里。",al={"斯塔文是谁","斯塔文背景","斯塔文·密斯曼托的故事"}},{q="为什么需要进行笔迹分析？",a="由于围绕斯塔文发生的事件和指控发生在不同的地区——包括月溪镇和闪金镇——官方记录并不连贯。夜色镇的市政登记册保存了经过验证的本地样本，可以明确地将外来的线索与此人联系起来。",al={"为什么要比对笔迹","为什么达尔塔要检查笔迹","证明斯塔文身份"}}},fp="21,137,22.323.0,28.315.1,31.183.0,63.224.0,32.159.0,51.128.0,38.255.0,39.225.0"}
P.entries["quest:970"] = {n="奥萨拉克斯之塔",s="这个任务标志着对邪恶的暗滩教派调查工作中的一个关键转折点，将追查目标从黑海岸的奥萨拉克斯之塔转移到了边界另一侧的灰谷迈斯特拉岗哨。净化者德尔格伦派遣冒险者前往附近的教派营地，以夺取一颗强力的发光的灵魂宝石。解开这个神器的秘密将揭示这股正在腐蚀北部森林的教派力量背后所隐藏的邪恶巫术。",h="这个任务标志着对邪恶的暗滩教派调查工作中的一个关键转折点，将追查目标从黑海岸的奥萨拉克斯之塔转移到了边界另一侧的灰谷迈斯特拉岗哨。净化者德尔格伦派遣冒险者前往附近的教派营地，以夺取一颗强力的发光的灵魂宝石。解开这个神器的...",kw={"奥萨拉克斯之塔","灰谷","暗滩教派","黑海岸","德尔格伦","净化者德尔格伦","发光的灵魂宝石","迈斯特拉岗哨","奥迪拉兰"},ang={["class:Paladin"]="净化黑暗灵魂容器并处决堕落的教派成员，这与圣骑士肃清世间邪恶腐化的职责不谋而合。",["class:Priest"]="检查黑暗灵魂容器与牧师对抗腐化并安抚痛苦灵魂的使命产生了共鸣。",["faction:Alliance"]="协调黑海岸和灰谷的前哨站工作，能巩固北部防线，抵御威胁联盟旅行者的黑暗施法者。",["race:NightElf"]="眼见邪恶教派成员玷污奥迪拉兰等古代废墟并腐蚀北部森林，肃清暗滩教派成为了任何暗夜精灵的当务之急。"},sec={{t="越过边境的请求",b="在揭露了黑暗海岸北部奥萨拉克斯之塔周围的阴险活动后，报告显示这些线索直指灰谷南部的净化者德尔格伦。德尔格伦驻扎在迈斯特拉岗哨，长期以来一直致力于对抗那些侵蚀古代精灵森林的暗滩教派。意识到教派的威胁横跨了这两个地区，德尔格伦决心从源头打击他们的邪恶巫术。"},{t="奥迪拉兰的秘密",b="迈斯特拉岗哨的东北方坐落着奥迪拉兰废墟，如今已被狂热的暗滩教派成员所占据。德尔格伦发现他们的成员身上携带着发光的灵魂宝石——这些注入了邪恶魔法的黑暗容器维持着教派的力量。通过在废墟中猎杀这些教派成员并夺回其中一颗宝石，德尔格伦打算打破上面的咒语，揭露他们邪恶仪式背后的真正来源。"},{t="被困的灵魂",b="在破译了束缚在发光的灵魂宝石上的邪恶符文后，德尔格伦不仅发现了黑暗咒语，还揭开了一个痛苦的牢笼。打破宝石上的结界释放了萨格斯的灵魂，他是亚米萨兰的精灵之一，在大分裂期间被阿斯瑞库斯·纳拉辛囚禁在灵魂宝石中并一直被缓慢汲取能量。这个灵魂提到了阿斯瑞库斯的副官伊尔库德·玛格苏尔，他的典籍或许能揭示剩余的灵魂宝石被藏在哪里。"}},faq={{q="我在哪里可以找到发光的灵魂宝石？",a="发光的灵魂宝石由位于灰谷迈斯特拉岗哨东北方奥迪拉兰废墟的暗滩教派成员持有。潜伏在废墟中的各类教派成员都有可能携带此物，不过你可能需要多尝试几次才能获得。",al={"灵魂宝石位置","灵魂宝石掉落地点","暗滩教派灵魂宝石"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷北部的联盟勇士。他积极对抗侵入森林的邪恶势力，尤其专注于追捕并消灭暗滩教派。",al={"德尔格伦","德尔格伦是谁"}},{q="什么是暗滩教派？",a="暗滩教派是一个从黑海岸的奥萨拉克斯之塔以及灰谷的奥迪拉兰等古代精灵废墟中运作的邪恶组织。他们从事黑暗巫术、灵魂绑定和死灵仪式。",al={"暗滩教派","暗滩教派成员"}},{q="为什么黑海岸的任务要让我去灰谷？",a="虽然调查是从黑海岸的奥萨拉克斯之塔开始的，但该教派的网络延伸到了南部的灰谷边境。位于迈斯特拉岗哨的净化者德尔格伦拥有对抗该教派灵魂绑定魔法所需的专业知识。",al={"为什么去迈斯特拉岗哨","为什么去灰谷"}},{q="当灵魂宝石被破译后会发生什么？",a="德尔格伦打算破译发光的灵魂宝石上的黑暗咒语。你将他带回宝石后，便能揭晓他发现了什么。",al={"灵魂宝石里有什么","灵魂宝石幽灵"}},{q="奥迪拉兰在哪里？",a="奥迪拉兰是一处古代精灵废墟，位于灰谷北部迈斯特拉岗哨的东北方，目前已被暗滩教派侵占。",al={"奥迪拉兰位置","奥迪拉兰在哪里"}}},fp="22,227,24.334.0,25.322.0,16.347.1,37.199.0,28.173.0,36.214.0,49.182.0,45.126.1,28.130.0"}
P.entries["quest:97003"] = {n="Chol'aruk the Ravener",s="Chol'aruk the Ravener 是贫瘠之地的一项狩猎任务，目标是一头据传栖息在荆棘岭洞穴中的巨型野猪人。兽人 Gur'ak 在遭遇过类似的野兽后，对此类传言深信不疑，于是委托冒险者前往其巢穴并带回它的头颅。",h="Chol'aruk the Ravener 是贫瘠之地的一项狩猎任务，目标是一头据传栖息在荆棘岭洞穴中的巨型野猪人。兽人 Gur'ak 在遭遇过类似的野兽后，对此类传言深信不疑，于是委托冒险者前往其巢穴并带回它的头颅。",kw={"贫瘠之地","乔尔阿鲁克","古尔阿克","野猪人","钢鬃","吞噬者","荆棘岭"},ang={["class:Hunter"]="追踪一只据传比普通野猪人大五倍的怪物，需要猎人敏锐的直觉和针对强大猎物的准备。",["class:Warrior"]="面对一只以贪得无厌的嗜血本性而闻名的残暴生物，需要前线战士做好准备，以应对其压倒性的物理狂暴。",["faction:Horde"]="兽人 Gur'ak 以部落传统的战斗口号“鲜血与雷鸣”发出了这一集结号召，委托冒险者去消灭潜伏在贫瘠之地的一个危险威胁。"},sec={{t="关于吞噬者的传说",b="在贫瘠之地的荒原上，钢鬃野猪人部落中流传着关于 Chol'aruk 的低语，这头巨兽被称为“吞噬者”。据当地的流言称，这头噩梦般的野兽栖息在荆棘岭东北部的一处深洞中。野猪人声称它大约是普通野猪人大小的五倍，内心充满了暴力和对鲜血永不满足的渴望。虽然许多人将这些故事斥为夸大的篝火传说，但 Gur'ak 因为过去与类似怪物的战斗经历，对此有更清醒的认识。"},{t="Gur'ak 的警告",b="意识到这种体型的野兽带来的真正威胁，Gur'ak 指引有能力的旅者追踪这只生物，前往它在荆棘岭的地下巢穴。他的指示很直接：除掉这头怪兽，并带回它的头颅作为无可辩驳的证据。鉴于 Chol'aruk 传闻中的凶猛和巨大的体型，Gur'ak 严厉告诫，只有准备充分的小队才应冒险进入洞穴去对抗这只“吞噬者”。"}},faq={{q="吞噬者乔尔阿鲁克 是谁？",a="乔尔阿鲁克，也就是钢鬃部落所称的“吞噬者”，是一头传奇且凶猛的野猪人。传闻它的体型是普通野猪人的五倍，有着无法满足的嗜血欲望，栖息在贫瘠之地的一处深洞中。",al={"谁是 乔拉鲁克","乔拉鲁克 是什么","吞噬者"}},{q="在哪里可以找到 乔尔阿鲁克？",a="乔尔阿鲁克 栖息在荆棘岭的一处深洞中，位于贫瘠之地 古尔阿克 营地的东北方。冒险者必须深入荆棘岭的洞穴才能找到它的巢穴。",al={"乔拉鲁克 在哪","乔拉鲁克 位置","荆棘岭洞穴在哪里"}},{q="谁提供了针对 乔尔阿鲁克 的狩猎任务？",a="驻扎在贫瘠之地的兽人 古尔阿克 提供了这项任务。与其他将关于这只巨兽的故事视为酒馆闲谈的人不同，古尔阿克 因为曾面对过类似的怪物，所以相信这些传言。",al={"谁提供 乔拉鲁克 任务","谁是 古拉克","古拉克 贫瘠之地"}},{q="为什么 古尔阿克 要狩猎 乔尔阿鲁克？",a="古尔阿克 希望消灭 乔尔阿鲁克，以消除恐吓该地区的野蛮威胁，并要求带回这头野兽被砍下的头颅，作为“吞噬者”已被击败的证据。",al={"为什么要杀死 乔拉鲁克","乔拉鲁克 悬赏原因"}},{q="我可以独自挑战 乔尔阿鲁克 吗？",a="古尔阿克 明确警告旅行者不要独自寻找 科尔阿鲁克。鉴于其巨大的体型和凶猛的嗜血本性，击败“吞噬者”是一项艰巨的挑战，需要组织一支准备充分的狩猎小队。",al={"我可以单挑 乔拉鲁克 吗","乔拉鲁克 很难吗","带队打 乔拉鲁克"}},{q="科尔阿鲁克 与钢鬃野猪人之间有什么联系？",a="野猪人是卡利姆多中部平原上的一种类人生物，钢鬃部落居住在贫瘠之地的部分地区。钢鬃人在谈论 科尔阿鲁克 时充满了恐惧，并给予了它“吞噬者”的称号。",al={"什么是野猪人","钢鬃 乔拉鲁克","为什么 钢鬃 害怕他"}}},fp="21,155,25.395.0,16.307.0,29.209.0,29.149.0,34.130.0,32.141.0,31.151.0,68.209.0"}
P.entries["quest:97005"] = {n="Chol'aruk the Ravener",s="Chol'aruk the Ravener 是一头令人胆寒的巨大畸变怪，潜伏在贫瘠之地荆棘岭的一处洞穴中。当地的钢鬃野猪人称它为 Chol'aruk，或者“掠食者”。有传言说这头怪兽体型巨大，能将一名兽人整个吞下。Bainham 想要得到它的头颅，以祭奠那些在类似恐怖灾难中丧生的战友。",h="Chol'aruk the Ravener 是一头令人胆寒的巨大畸变怪，潜伏在贫瘠之地荆棘岭的一处洞穴中。当地的钢鬃野猪人称它为...",kw={"畸变怪","贝恩汉姆","贫瘠之地","乔尔阿鲁克","钢鬃","掠食者","荆棘岭"},ang={["class:Hunter"]="面对一头传说中能将全身披甲的战士一口吞下的顶级掠食者，是对追踪者实力与胆识的终极考验。",["class:Warrior"]="Bainham 的恳求直接诉诸了战士的信条：通过在地下巢穴中与庞然大物正面交锋，来为牺牲的战友复仇。",["faction:Horde"]="在高地上肆意游荡的怪物威胁着穿行于贫瘠之地的旅行者和商队，因此铲除这头野兽已成为关乎地区安全的问题。"},sec={{t="荆棘岭的恐怖",b="在贫瘠之地，Bainham 等候之处的西北方坐落着被称为荆棘岭的高原，这里长期以来一直是被当地的钢鬃部族所争夺的领地。最近，有流言悄悄传出，在那里的某个洞穴中盘踞着一个可怕的存在：一头被钢鬃野猪人称为 Chol'aruk，或称“掠食者”的巨大畸变怪。尽管许多旅行者将这头能一口吞下全身披甲的兽人的怪兽传说视为篝火边的奇谈怪论，但那些亲眼目睹了血腥场面的人知道，这种威胁是千真万确的。"},{t="了结夙愿",b="对于 Bainham 来说，Chol'aruk 的存在绝非神话。他过去曾与类似的恐怖生物交过手，身上留下了个人的伤疤，也为倒在这些野兽蹄下的战友感到哀伤。深知这种贪婪的畸变怪对所有漫游在草原上的人构成的危险，他委托经验丰富的勇士登上高原，突入其地下巢穴，击杀 Chol'aruk 并取回它巨大的头颅。"}},faq={{q="科尔阿鲁克 是一种什么样的生物？",a="科尔阿鲁克 被描述为潜伏在荆棘岭一处洞穴中的巨大畸变怪。据传它体型极其庞大，能够将一名成年兽人整个吞下，这使得它在当地的钢鬃野猪人中获得了“掠食者”这一恐怖称号。",al={"什么是 乔拉鲁克","乔拉鲁克 怪物类型","谁是掠食者"}},{q="科尔阿鲁克 的巢穴在哪里？",a="科尔阿鲁克 的巢穴位于贫瘠之地西北方荆棘岭高地上的一个洞穴内。",al={"乔拉鲁克 在哪里","乔拉鲁克 位置","荆棘岭洞穴"}},{q="贝恩汉姆 是谁？为什么要杀死 科尔阿鲁克？",a="贝恩汉姆 身处贫瘠之地，有着与此类野兽作战的个人经历。他过去曾有盟友死于类似的畸变怪之手，因此出于荣誉感和为牺牲战友复仇的念头，他寻求终结 科尔阿鲁克 的生命。",al={"谁给予 乔拉鲁克 任务","为什么要杀 乔拉鲁克","贝恩汉姆 传说"}},{q="“掠食者”是什么意思？",a="当地的钢鬃野猪人以此为名来形容 科尔阿鲁克 那贪得无厌、暴食成性的本性，因为有传言称它毫不犹豫地将身披重甲的战士整个吞食。",al={"乔拉鲁克 的含义","为什么叫掠食者","钢鬃 乔拉鲁克"}},{q="钢鬃野猪人是崇拜还是恐惧 科尔阿鲁克？",a="目前尚不得而知。钢鬃野猪人称这头生物为 科尔阿鲁克 或“掠食者”，但任务描述中并未说明他们究竟是恐惧还是崇拜这头盘踞在荆棘岭洞穴中的巨大畸变怪。",al={"野猪人喜欢 乔拉鲁克 吗","钢鬃与 乔拉鲁克"}},{q="需要什么证据来确认 科尔阿鲁克 已死？",a="贝恩汉姆 要求你带回 科尔阿鲁克 的头颅，作为这头畸变怪已被铲除的无可辩驳的证明。",al={"乔拉鲁克 任务交付","我要带什么给 贝恩汉姆"}}},fp="21,141,20.371.0,15.372.0,35.145.0,34.81.0,51.134.0,29.135.0,52.198.0,52.78.0"}
P.entries["quest:97048"] = {n="Returning to Port",s="一名获救的厨师请你去藏宝海湾找 Aransas 船长。她失去了一名船员，你把他送回去对她很重要。",h="一名获救的厨师请你去藏宝海湾找 Aransas 船长。她失去了一名船员，你把他送回去对她很重要。",kw={"藏宝海湾","aransas 船长","厨师","船员","库尔森的营地","mathers","返回港口"},sec={{t="回到船长身边",b="Aransas 船长正在藏宝海湾等你，你把厨师送回她的船上。厨师答应回去后替你美言几句，还说船长一定很高兴见到他回来。她向你表示欢迎，并听你讲述 Mathers 对你们逃离库尔森的营地一事的说法。"},{t="船长的谢意",b="Aransas 船长知道 Mathers 所说的惊险剑术故事是编出来的；她说这名厨师只配用厨房刀。不过，她还是感谢你救回了她的一名船员。对她的船来说，一名好厨师十分宝贵。"}},faq={{q="Aransas 船长是谁？",a="Aransas 船长指挥着那艘船，你把她的厨师送回了她在藏宝海湾的船上。",al={"aransas 船长","aransas"}},{q="Mathers 是谁？",a="Mathers 是 Aransas 船长的厨师，也是她的一名船员。",al={"mathers","厨师 mathers"}},{q="我在哪里能找到 Aransas 船长？",a="Aransas 船长在藏宝海湾。",al={"aransas 的位置","藏宝海湾的船长"}},{q="船长为什么感谢我？",a="她感谢你救回了她的一名船员。",al={"感谢的原因","救回厨师"}},{q="Mathers 对这次逃脱说了什么？",a="Mathers 告诉 Aransas 船长，你和他一起逃出了库尔森的营地。",al={"mathers 的说法","他告诉 aransas 什么"}}},fp="17,137,19.272.0,20.212.1,23.76.0,15.58.0,32.32.0,30.47.0,38.85.0"}
P.entries["quest:971"] = {n="深渊中的知识",s="“深渊中的知识”是联盟的一项任务，由铁炉堡荒弃的洞穴的葛利·硬骨提供。他指派冒险者横跨海洋，前往灰谷的黑暗深渊沉没遗迹，寻回古老的洛迦里斯手稿。在硬骨那学者外表的伪装下，隐藏着一个与黑暗实体及末日预言相关的险恶计划。",h="“深渊中的知识”是联盟的一项任务，由铁炉堡荒弃的洞穴的葛利·硬骨提供。他指派冒险者横跨海洋，前往灰谷的黑暗深渊沉没遗迹，寻回古老的洛迦里斯手稿。在硬骨那学者外表的伪装下，隐藏着一个与黑暗实体及末日预言相关的险恶计划。",kw={"灰谷","黑暗深渊","荒弃的洞穴","葛利·硬骨","铁炉堡","深渊中的知识","洛迦里斯手稿"},ang={["class:Warlock"]="硬骨就在铁炉堡荒弃的洞穴中潜藏的术士们旁边活动，分享着他们对扭曲位面的禁忌书籍的渴望。",["faction:Alliance"]="尽管帮助一名联盟学者看起来人畜无害，但硬骨的真实动机及其背后的黑暗同伙暗示了铁炉堡城墙内正在进行更阴险的勾当。",["race:NightElf"]="书稿位于黑暗深渊中，那是一处被淹没的暗夜精灵圣所，现在被邪教徒和其他入侵者占据。"},sec={{t="阴影中的学者",b="葛利·硬骨潜藏在铁炉堡潮湿的荒弃的洞穴深处，伪装成一位致力于收集古籍的学者。然而，他的学术追求却带有明显的邪恶意味。硬骨对世俗的历史或城市编年史毫无兴趣；他明确地在寻找那些能够开启门户并唤醒“沉睡者”的遗忘知识。他谈论着在“末日”之后生存的话题，这让他显得不仅是个怪人，更像是一个危险的、崇拜黑暗与沉睡力量的信徒。"},{t="洛迦里斯的沉没遗迹",b="硬骨指示寻求者穿越整个艾泽拉斯，前往灰谷阴影笼罩的海岸，那里沉没着古老的暗夜精灵圣所——黑暗深渊。在大分裂将卡利姆多撕裂之前，暗夜精灵学者曾在这些沿海神庙中汇聚了极其庞大的魔法知识。如今，在布满娜迦、萨特和暮光之锤邪教徒的被淹没的走廊中，安放着洛迦里斯手稿——一本存放在凹陷的铁皮箱里的禁忌知识之书。"},{t="兄弟姐妹",b="当把浸水的书稿交给他时，硬骨并没有打算将其归档到铁炉堡的探险者大厅。相反，他公开欢呼这些书稿将被复制并分发给他那些神秘的“兄弟姐妹”。虽然他感谢取回书稿的联盟冒险者，但硬骨显然忠于一个秘密教派，该教派渴望利用这些寻回的知识进行改变世界的秘术仪式。硬骨与暮光之锤有关联，该组织的成员一直在搜寻关于古神的禁忌知识。"}},faq={{q="谁给予了“深渊中的知识”任务？",a="该任务由葛利·硬骨给予，他是一位矮人寻古者，居住在矮人山城铁炉堡内光线昏暗的荒弃的洞穴中。",al={"任务给予者","哪里接任务","谁开启深渊中的知识"}},{q="什么是洛迦里斯手稿？",a="洛迦里斯手稿是葛利·硬骨想要从黑暗深渊中找回的文献。它被存放在被淹没的废墟中一个凹陷的铁皮箱里。",al={"什么是洛迦里斯手稿","洛迦里斯传说","我能找到什么书"}},{q="洛迦里斯手稿在哪里？",a="该手稿位于黑暗深渊地下城深处，该地下城坐落在卡利姆多灰谷西北海岸的佐拉姆海岸旁。",al={"洛迦里斯手稿位置","黑暗深渊里的书在哪里","黑暗深渊书籍位置"}},{q="葛利·硬骨提到的“沉睡者”是谁？",a="硬骨用这个神秘的名字来称呼他在收集的禁忌知识中所描述的那些沉睡的力量。任务的受保护部分探索了他与黑暗势力的联系。",al={"沉睡者","硬骨在谈论谁","葛利崇拜什么"}},{q="葛利计划与谁分享这些书稿的“兄弟姐妹”是谁？",a="硬骨的同伙与他有着同样的对禁忌知识的兴趣。找回书稿可以揭示更多关于他效忠对象的信息。",al={"葛利的兄弟姐妹","葛利在为谁工作","硬骨阵营"}},{q="为什么在铁炉堡的任务会把玩家派到灰谷那么远的地方？",a="铁炉堡的荒弃的洞穴吸引了那些寻求隐秘知识的非正统施法者、术士和潜行者。硬骨收集古老且强大的知识，而他想要的洛迦里斯手稿据传就在灰谷黑暗深渊的底部，那里曾是早已消亡、掌握着巨大知识的精灵们的居所。",al={"为什么要前往灰谷","铁炉堡到黑暗深渊的任务","前往黑暗深渊"}}},fx={["32faf93b"]={q="葛利·硬骨为什么想要洛迦里斯手稿？",a="葛利·硬骨收集古老而强大的典籍，这些典籍能够开启被遗忘的门扉，唤醒沉睡者。他相信洛迦里斯手稿记载着黑暗深渊古代暗夜精灵失传已久的秘密，并打算在末日来临前抄录这份黑暗知识，分发给他那些行事隐秘的兄弟姐妹。",al={"葛利·硬骨的动机","葛利为什么要手稿","葛利·硬骨的任务缘由"}}},fp="22,175,24.364.0,27.407.0,20.458.1,43.110.0,32.145.0,41.129.0,55.102.0,77.123.1,68.305.0"}
P.entries["quest:97130"] = {n="Ancient Gurubashi Secrets",s="Lan'dalock请你从荆棘谷近海一处新近浮现的古拉巴什遗迹中取回一尊神像。遗迹中或许藏有关于古拉巴什血魔法的重要线索。",h="Lan'dalock请你从荆棘谷近海一处新近浮现的古拉巴什遗迹中取回一尊神像。遗迹中或许藏有关于古拉巴什血魔法的重要线索。",kw={"ancient gurubashi idol","古拉巴什的古老秘密","血魔法","沉没之城","古拉巴什","lan'dalock","南海","荆棘谷","巫医"},sec={{t="重现的遗迹",b="Lan'dalock和你一直在谈论南海发生的一件怪事。一处古拉巴什遗迹出现在荆棘谷海岸附近。它突然重现，引起了研究往昔之人的关注。"},{t="古拉巴什神像",b="沉没之城中藏有极具考古价值的遗物。Lan'dalock正在寻找一尊神像，古拉巴什的某些巫医曾用它施展血魔法。有人请你带回一尊以供研究。"}},faq={{q="谁想要这尊神像？",a="Lan'dalock和一位同伴想从沉没之城寻找一尊古老的古拉巴什神像。",al={"是谁派我来的","lan'dalock 神像","谁想要它"}},{q="古拉巴什遗迹出现在哪里？",a="古拉巴什遗迹出现在南海的荆棘谷海岸附近。",al={"沉没之城在哪里","遗迹位置","古拉巴什之城"}},{q="他们为什么想要一尊神像？",a="古拉巴什的某些巫医曾用神像施展血魔法，Lan'dalock想找一尊来研究。",al={"为什么要神像","神像用途","神像有什么用"}},{q="沉没之城是什么地方？",a="那是一处古拉巴什遗迹，出现在荆棘谷海岸附近。",al={"沉没之城","古拉巴什沉没遗迹","古代遗迹"}}},fp="25,164,12.212.0,24.204.0,19.80.0,36.90.0,25.114.0,25.81.0"}
P.entries["quest:97196"] = {n="The Coldbringer's Eye",s="巫妖王的一名仆从在剃刀高地透过 Coldbringer’s Eye 监视四周。你受命取回宝珠，以便追捕潜伏在卡利姆多的天灾军团特工。",h="巫妖王的一名仆从在剃刀高地透过 Coldbringer’s Eye 监视四周。你受命取回宝珠，以便追捕潜伏在卡利姆多的天灾军团特工。",kw={"亚门纳尔","寒冰之王","coldbringer’s eye","亡首野猪人","巫妖王","剃刀高地","scourge","占卜宝珠"},sec={{t="巢穴中的宝珠",b="占卜宝珠能让寒冰之王亚门纳尔观察并指挥远方的爪牙。他盘踞在剃刀高地深处，那是亡首野猪人的巢穴。你受命取回 Coldbringer’s Eye，借此追捕潜伏在卡利姆多的天灾军团特工。"}},faq={{q="寒冰之王亚门纳尔是谁？",a="寒冰之王亚门纳尔是巫妖王的仆从，盘踞在剃刀高地。",al={"亚门纳尔","寒冰之王是谁"}},{q="Coldbringer’s Eye 是什么？",a="Coldbringer’s Eye 是一颗占卜宝珠，亚门纳尔用它观察并指挥远方的爪牙。",al={"coldbringer’s eye","眼球宝珠"}},{q="Coldbringer’s Eye 在哪里？",a="Coldbringer’s Eye 位于剃刀高地，在寒冰之王亚门纳尔的巢穴中。",al={"眼睛在哪里","剃刀高地宝珠"}},{q="为什么要夺取宝珠？",a="这颗宝珠或许能帮助追捕潜伏在卡利姆多的天灾军团特工，消除他们带来的威胁。",al={"为何取回眼睛","天灾军团特工"}}},fp="21,172,18.262.0,32.84.0,30.97.0,31.79.0,22.94.0"}
P.entries["quest:972"] = {n="水之灵契",s="水之灵契是水之先知伊斯伦交给贫瘠之地沿岸的年轻部落萨满祭司的一项过渡性任务。在炼金药剂的加持下，萨满祭司将被派遣横跨无尽之海，前往银松森林那片被腐蚀的土地，去面对一口被污染的泉水。",h="水之灵契是水之先知伊斯伦交给贫瘠之地沿岸的年轻部落萨满祭司的一项过渡性任务。在炼金药剂的加持下，萨满祭司将被派遣横跨无尽之海，前往银松森林那片被腐蚀的土地，去面对一口被污染的泉水。",kw={"水之召唤","水之先知伊斯伦","萨满试炼","银松森林","贫瘠之地","图腾任务","水之灵契"},ang={["class:Shaman"]="水之灵契标志着你元素试炼中的一个关键转折点，它开启了你对灵魂世界的视野，随后你才能获得掌控水之图腾的治疗能力。",["faction:Horde"]="这项试炼展示了新部落横跨大陆的团结精神，将新兵从阳光炙烤的卡利姆多平原送往洛丹伦那阴森诡谲的树林中。"},sec={{t="水的幻象",b="在部落萨满的元素传统中，sapta是一种炼金药剂，可以使人的感官直接与世界的灵魂调和。当普通人的眼睛只能看到平静的溪流或停滞的池塘时，喝下这种sapta就能穿透物理层面的面纱，揭示出隐藏在水流中的元素生物。"},{t="通往银松森林之路",b="在证明了自己对灵魂的奉献之后，萨满祭司可以直接从水之先知伊斯伦那里获得这种药剂，伊斯伦是一位居住在棘齿城以南荒凉海岸上的隐士。伊斯伦并没有让新兵在卡利姆多的干旱山谷中测试这种sapta，而是命令他们横跨无尽之海，长途跋涉来到银松森林那阴暗且被遗弃的树林，去对抗正在毒害洛丹伦溪流的元素腐蚀。"}},faq={{q="什么是水之灵契？",a="灵契是一种由萨满导师准备的仪式药剂。饮用后，它会增强精神感知力，使饮用者能够直接看到并与那些在凡人眼中不可见的元素灵魂进行交流。",al={"什么是灵契","水之灵契的含义","灵契有什么作用"}},{q="水之先知伊斯伦是谁？",a="水之先知伊斯伦是一位萨满大师，居住在商旅海岸以南、贫瘠之地东海岸的僻静处进行沉思。她引导年轻的部落萨满踏上艰苦的旅程，与水元素沟通并驾驭它们。",al={"水之先知伊斯伦背景故事","伊斯伦是谁"}},{q="萨满祭司为什么要前往银松森林？",a="银松森林的水元素灵魂正遭受着广泛的折磨。为了完成他们的试炼，萨满祭司必须带着灵契横跨海洋，亲眼观察被腐蚀的水源并净化那里的污秽。",al={"为什么要前往银松森林","为什么要前往东部王国"}},{q="喝下灵契后会发生什么？",a="饮用水之灵契可以让萨满祭司亲眼目睹潜伏在银松森林受污染水池中的受腐蚀水元素，从而开启对抗腐化源头的道路。",al={"饮用灵契","灵契的效果"}},{q="所有的部落萨满都需要进行这次试炼吗？",a="是的。无论是兽人、牛头人还是巨魔萨满，都必须响应水之召唤，将这种灵契作为获得水之图腾之前必不可少的成人礼。",al={"谁会接到这个任务","这是职业任务吗"}},{q="银松森林里的腐蚀水池在哪里？",a="受腐蚀的泉水位于银松森林的海岸边，瑟伯切尔的西侧。",al={"银松森林水池位置","水源在哪里"}}},fp="11,195,17.259.0,22.331.0,22.160.0,23.207.0,48.216.0,38.157.0,44.138.0,50.78.0"}
P.entries["quest:97220"] = {n="Philmor's Favor",s="Philmor's Favor是暴风城内的一项运送任务，起因是当地码头工人持续短缺。信使需要将一批易碎的Gatehouse货物运送到位于贸易区的提亚斯奶酪坊店二楼的一个隐蔽仓库入口。",h="Philmor's Favor是暴风城内的一项运送任务，起因是当地码头工人持续短缺。信使需要将一批易碎的Gatehouse货物运送到位于贸易区的提亚斯奶酪坊店二楼的一个隐蔽仓库入口。",kw={"伊莱恩","门楼","门楼货物","菲尔莫","菲尔莫的请求","暴风城","贸易区","提亚斯奶酪坊"},ang={["faction:Alliance"]="协助完成暴风城贸易区各处的运送任务，可以在码头工人短缺的情况下保持城市物流平稳运行。"},sec={{t="暴风城内紧张的物流状况",b="暴风城各地的码头工人持续短缺，导致城市的日常货运业务吃紧。为了不让当地的货物进度落后，搬运工们一直在寻找可靠的过路人，愿意将敏感的板条箱直接运进商业区。"},{t="在提亚斯奶酪坊的秘密投递",b="这批货物是标记给Gatehouse的，但其投递方式却一点也不寻常。货物不是通过正规的卫兵岗哨入口，而是被搬运到位于贸易区的提亚斯奶酪坊店二楼。这家店隐藏着一个仓库入口，用于悄悄地搬运供给品和送给守卫军官的礼品，以免被他人窥见。"}},faq={{q="谁需要这项运送任务的帮助？",a="这项任务旨在缓解暴风城周围的货物运输压力，此时当地的码头人手不足。",al={"谁发布了菲尔莫的请求","菲尔莫任务发布者"}},{q="送货目的地在哪里？",a="这批货物必须送到卫所的仓库入口，该入口可以通过暴风城贸易区的提亚斯奶酪坊店二楼进入。",al={"我该把包裹送到哪里","提亚斯奶酪运送","卫所入口在哪里"}},{q="谁负责接收货物？",a="伊莱恩是提亚斯奶酪坊店的女主人，她习惯处理运往毗邻的卫所仓库的机密货物。",al={"谁是伊莱恩","提亚斯奶酪坊的伊莱恩"}},{q="卫所的货物里装的是什么？",a="这批货物包含运往卫所的易碎物品。据当地搬运工称，为了方便安排给守卫军官的仪式性惊喜，货物通常需要特别谨慎地送达。",al={"包裹里有什么","卫所运送内容"}},{q="为什么可以通过奶酪店进入军事仓库？",a="提亚斯奶酪坊店的楼上有一个通往卫所仓库的入口，允许在不经过主军事入口招摇过市的情况下，进行机密的通行和货物卸载。",al={"为什么通过提亚斯奶酪坊进入卫所","提亚斯奶酪坊的秘密入口"}},{q="为什么码头工人会短缺？",a="由于全周人员短缺，码头和货物搬运工手头紧缺，迫使物流协调员不得不依靠路过的旅行者来保证运送进度。",al={"为什么码头工人短缺","暴风城码头工人短缺"}}},fp="15,191,31.219.0,36.281.0,34.99.0,34.121.0,26.99.0,38.147.0,59.142.0,34.141.0"}
P.entries["quest:97222"] = {n="Gatehouse Goods",s="Gatehouse Goods是一项暴风城的本地任务，要求将一批货物运送到提亚斯奶酪坊店内的楼梯上方。由于这家奶酪店与相邻的城门卫所共用一个楼层，货物可以安静地放置在储藏室门外，供卫兵回收。这一安排突显了暴风城商业区与防御区紧凑、互通的城市设计。",h="Gatehouse...",kw={"送货","埃林·提亚斯","门楼货物","卫所货物","储藏室","暴风城","提亚斯奶酪"},ang={["class:Rogue"]="对于那些重视谨慎行事的人来说，在提亚斯奶酪坊周围安静地操作并注意向内开启的门等建筑细节是第二天性。",["faction:Alliance"]="通过提亚斯奶酪坊协助安排谨慎的送货，可以保持暴风城当地店主与邻近卫所人员之间的物资顺畅流通。"},sec={{t="共用的区域与楼层",b="Gatehouse Goods是一项简单的运送任务，地点位于繁忙的暴风城街道内。该工作要求将城门卫所的货物搬运到提亚斯奶酪坊的内部楼梯上方。虽然这家著名的奶酪店是一家完全独立的生意，拥有自己的库存，但其实体建筑与邻近的卫所设施共用一个楼层。这种建筑布局上的巧合使得该店的上方平台成为在相邻区域之间运输物资的便利通道，且不会干扰到正面的街道。"},{t="便利的卸货点",b="运送流程非常明确：信使必须将板条箱直接放在储藏室门外，而不是搬进里面。常规的卫所守卫会留意到货物的送达，并指派人员在返回岗位时顺便将其取回。此外，储藏室的门特意设计为向内开启的合页，确保堆放在外面的货物永远不会堵塞入口，也不会妨碍里面的人员自由通行。"}},faq={{q="什么是卫所的货物？",a="卫所的货物是暴风城的一项本地送货差事，涉及提亚斯奶酪坊和邻近的卫所。信使需要将货物搬上楼梯，并将其放在卫所储藏室门外。",al={"什么是卫所货物","卫所货物任务"}},{q="货物应该送到哪里？",a="货物需要送到提亚斯奶酪坊店内的楼梯上方。虽然提亚斯奶酪坊是一家独立的企业，但它的建筑与卫所共用一个楼层，允许直接将货物卸在储藏室门外。",al={"提亚斯 奶酪卫所","货物送到哪里"}},{q="为什么板条箱要留在门外，而不是搬进里面？",a="接收方特别指示信使将板条箱留在储藏室门外，而不是搬进去。卫所的守卫会注意到货物的送达，并在返回岗位时派人顺便将其搬进去。",al={"为什么不搬进里面","谁来取走箱子"}},{q="为什么储藏室的门要向内开启？",a="储藏室的门合页设计为向内开启，主要是为了防止放置在门外的包裹和货物堵塞门口或将里面的人困住。",al={"提亚斯内部开门","储藏室门合页"}},{q="提亚斯奶酪坊与卫所有关联吗？",a="没有，提亚斯奶酪坊不属于卫所，也不共用库存。然而，这两处设施共用一个楼层，这使得楼上成为了一个便利的转运点。",al={"提亚斯奶酪坊属于卫所吗","提亚斯奶酪坊库存"}},{q="谁负责监管货物的运送？",a="这项任务由当地的操作员安排，他们期待专业的尊重和相互的谨慎，并在货物成功送达且不阻碍门口的情况下，对可靠的信使表示认可。",al={"谁发布卫所货物","谁接收货物"}}},fp="15,269,33.307.0,20.281.0,24.184.0,47.186.0,65.171.0,40.106.0,47.109.0,39.181.0"}
P.entries["quest:97223"] = {n="Bloodtalon Matriarch",s="血爪 Matriarch是森金村附近一支敏捷狡诈的迅猛龙群的首领。由于成年后的她太过危险且桀骜不驯，无法被驯服，因此必须将其解决，这样才能获取她的后代，将它们从蛋开始培养，使其成为暗矛巨魔忠诚的伙伴。",h="血爪 Matriarch是森金村附近一支敏捷狡诈的迅猛龙群的首领。由于成年后的她太过危险且桀骜不驯，无法被驯服，因此必须将其解决，这样才能获取她的后代，将它们从蛋开始培养，使其成为暗矛巨魔忠诚的伙伴。",kw={"血爪","暗矛","族母","迅猛龙","迅猛龙蛋","森金村","森金","巨魔坐骑"},ang={["class:Hunter"]="猎人们深知驯服经验丰富的成年野兽的难度，也明白必须从出生起就抚养掠食者才能建立真正的羁绊。",["faction:Horde"]="将当地的掠食者培养成忠诚的盟友，有助于巩固暗矛巨魔的定居点，并加强部落在杜隆塔尔海岸的影响力。",["race:Troll"]="森金村的暗矛巨魔将迅猛龙视为敏捷的伙伴和战马，他们非常看重血爪血脉的狡诈与迅捷。"},sec={{t="血爪血脉",b="血爪兽群以其卓越的速度和敏锐的狡诈在杜隆塔尔海岸闻名。当暗矛巨魔的驯兽师想要寻找可靠的坐骑和伙伴时，他们最看重的正是这些特质。然而，成年迅猛龙有着固执且暴力的本能，一旦它们适应了野外生活，几乎不可能被驯化。"},{t="保护血脉",b="尽管曾多次尝试直接捕获并训练这位Matriarch，但她日益增长的攻击性使她成为了对周边地区的一大威胁。为了在保护部落的同时确保其优秀的血脉不被断绝，巨魔们决定解决这位危险的母亲并抢救她的那一窝蛋，以确保下一代能从蛋开始就被培养成忠诚的盟友。"}},faq={{q="谁是血爪族母？",a="血爪 族母是一只凶猛的成年迅猛龙，她的兽群以速度和狡诈著称。虽然早期曾尝试捕获并训练她，但她最终变得太危险而无法控制，因此暗矛巨魔转而选择获取她的蛋。",al={"谁是血爪主母","血爪迅猛龙首领","迅猛龙首领"}},{q="为什么必须对付血爪族母？",a="成年迅猛龙以难以驯服而著称，而这位族母对当地定居点构成了巨大的危险。通过制服她并收集她的蛋，森金村的驯兽师们可以在消除危险的同时保存其血脉。",al={"为什么要杀掉主母","为什么要获取蛋","为什么要猎杀主母"}},{q="为什么不直接驯服族母？",a="成年迅猛龙拥有凶猛且无法驯服的本能，一旦成年就几乎无法训练。驯兽师通过获取蛋并直接从小培养幼崽，能取得更好的成果，使其与未来的伙伴建立联系。",al={"可以驯服成年迅猛龙吗","训练成年迅猛龙"}},{q="族母的后代会怎么样？",a="捕获的蛋会被带回森金村进行孵化和培育。巨魔们打算从幼年开始训练这些小迅猛龙，让它们成长为部落可靠的盟友和坐骑。",al={"蛋会怎么样","主母的后代","森金村的迅猛龙"}},{q="这个任务发生在哪里？",a="该任务以森金村为中心，这是暗矛巨魔在杜隆塔尔南部的沿海避风港，驯兽师们在这里致力于为他们的人民繁育和培养忠诚的迅猛龙。",al={"这个任务在哪里交","森金村迅猛龙任务"}},{q="血爪兽群有什么特别之处？",a="血爪迅猛龙因其敏捷和智慧而备受推崇。只要在它们野性本能占据主导之前进行训练，这些特质就使它们的血脉成为极佳的伙伴和坐骑选择。",al={"血爪迅猛龙特征","为什么选择血爪迅猛龙"}}},fp="20,247,22.284.0,24.325.0,32.216.0,48.223.0,35.154.0,46.178.0,29.131.0,39.156.0"}
P.entries["quest:97225"] = {n="Forgotten Loa Idols",s="“Forgotten Loa Idols”的核心内容是为暗矛巨魔寻回神圣的宗教雕像。这些遗失的圣物对于恢复至关重要的精神仪式，并维系部落与其守护荒野之神之间长久的崇敬纽带至关重要。",h="“Forgotten Loa Idols”的核心内容是为暗矛巨魔寻回神圣的宗教雕像。这些遗失的圣物对于恢复至关重要的精神仪式，并维系部落与其守护荒野之神之间长久的崇敬纽带至关重要。",kw={"暗矛","被遗忘的洛阿神像","雕像","洛阿","崇敬","仪式","神灵","巨魔"},ang={["class:Priest"]="巨魔牧师和巫医直接依赖仪式和祖传圣物来引导精神力量并供奉洛阿。",["class:Shaman"]="虽然萨满修行调用的是元素力量，但巨魔灵术士对与部落生存息息相关的荒野之神和祖先洛阿怀有深切的崇敬。",["faction:Horde"]="暗矛巨魔是部落的创始成员，协助他们的圣职长老保护重要的宗教文物，能够加强部落内部的团结。",["race:Troll"]="对于暗矛巨魔来说，与洛阿的交流是精神生活的核心。寻回遗失的雕像能确保重要的仪式得以继续，并使部落保持在神灵的庇佑之中。"},sec={{t="洛阿的圣洁遗物",b="对暗矛巨魔而言，精神平衡与他们和洛阿——即他们祖先遗产中的原始动物之灵与荒野之神——的联系密不可分。“Forgotten Loa Idols”涉及找回对于开展部落仪式必不可少的遗失宗教圣物。没有这些神圣的物品，精神领袖们就无法执行那些与神圣守护者保持和谐所需的仪式。"},{t="暗矛的纽带",b="虽然艾泽拉斯各地有几个敌对的巨魔部族实行血祭，或者试图通过武力来强迫神灵屈服，但暗矛巨魔以保持相互尊重和谦卑的崇敬纽带而自豪。对暗矛巨魔来说，失去守护者的青睐是一场严重的灾难，这使得找回这些遗失的雕像成为了维系部落生存的重要举措。"}},faq={{q="“被遗忘的洛阿神像”的目的是什么？",a="“被遗忘的洛阿神像”是一项为暗矛巨魔进行的任务，旨在寻回失落的神圣雕像。这些雕像对于恢复关键的部落仪式并保持他们对所崇敬荒野之神的尊崇是必不可少的。",al={"被遗忘的洛阿神像","这是什么任务","什么是 被遗忘的洛阿神像"}},{q="什么是洛阿？",a="洛阿是巨魔所崇敬的古老、强大的原始之灵和动物神。巨魔文化通过祭品、祈祷和仪式来供奉他们，以换取保护、恩惠和精神指引。",al={"什么是洛阿","巨魔之神","谁是洛阿"}},{q="与其他巨魔部族相比，暗矛巨魔如何看待他们的洛阿？",a="与那些试图使黑暗神灵屈服或进行祭祀的残酷巨魔部族不同，暗矛巨魔将他们与洛阿的关系视为深切的崇敬、相互尊重和精神职责。他们相信自己的生存取决于能否继续获得神灵的青睐。",al={"暗矛洛阿关系","为什么要崇敬洛阿","其他部族的洛阿"}},{q="为什么部落仪式需要这些雕像？",a="这些雕像作为部落仪式的圣洁焦点。没有它们，长老和精神领袖就无法妥善地进行与守护神灵交流及表达敬意所需的仪式。",al={"为什么需要雕像","洛阿雕像的用途","为什么雕像很重要"}},{q="为什么保持洛阿的青睐对暗矛巨魔如此重要？",a="暗矛长老们担心，如果没有适当的仪式和祭品，他们的部落可能会失去洛阿的恩惠和庇护，使部落在这个充满危险的世界中变得脆弱。",al={"如果不归还雕像会发生什么","失去青睐","暗矛洛阿的恩惠"}},{q="谁在寻求找回“被遗忘的洛阿神像”？",a="该任务由一位暗矛巨魔精神向导授予，他急于恢复集体仪式并确保获得部落祖先守护者的祝福。",al={"谁发布 被遗忘的洛阿神像","任务发布者","谁要求找回雕像"}}},fp="19,142,26.307.0,18.305.0,43.117.0,13.198.0,67.163.0,44.157.0,57.159.0,48.157.0"}
P.entries["quest:97234"] = {n="Reading Room",s="Reading Room围绕着Roy's Book Club和暴风城图书馆之间的一次交换展开。冒险者们协助该俱乐部，将一包包裹好的旧文学书籍送到图书馆，以便为成员们的讨论获取现代著作。",h="Reading Room围绕着Roy's Book Club和暴风城图书馆之间的一次交换展开。冒险者们协助该俱乐部，将一包包裹好的旧文学书籍送到图书馆，以便为成员们的讨论获取现代著作。",kw={"书籍","传说","图书管理员","阅览室","罗伊的读书会","暴风城图书馆","卷宗"},ang={["faction:Alliance"]="联盟的旅行者经常造访位于暴风要塞内的皇家图书馆，那里的公民和学术交流维持着城市的知识生活。"},sec={{t="暴风城的文学追求",b="在繁忙的暴风城首都，文学爱好者们聚集在Roy's Book Club的旗帜下，剖析经典传说，辩论发人深省的著作。该俱乐部通过轮换文本来保持讨论的新鲜感，用较旧或不太受欢迎的作品换取城市庞大馆藏中更新、更引人入胜的卷宗。"},{t="图书馆交换",b="为了保持他们的阅读清单与时俱进，该俱乐部依靠与暴风城图书馆建立的借阅协议。Roy使用一种标志性的包装技术将俱乐部归还的卷宗打包，让冒险者们可以直接将包裹送到图书管理员手中，以换取一份新的现代书籍清单。"}},faq={{q="什么是阅览室任务？",a="阅览室是一项涉及罗伊的读书俱乐部的任务，这是一个讨论传奇故事和文学的读者聚会。该任务要求一名冒险者将一捆不太受欢迎的包裹送到暴风城图书馆，以换取更现代的书籍。",al={"阅览室任务","什么是阅览室","阅览室故事"}},{q="罗伊是谁？",a="罗伊经营着一个活跃的读书俱乐部，成员们在那里聚集，辩论传奇故事和文学的深层含义。他与暴风城图书馆保持着轮换阅读材料的安排，并将借来的书籍以完好无损的状态归还。",al={"罗伊是谁","罗伊的读书会","读书俱乐部负责人"}},{q="书被送往哪里？",a="包裹好的阅读材料被直接送到暴风城的图书馆。那里的图书管理员认出了罗伊的俱乐部所使用的独特包装技术，并欣然接受了用其交换新鲜的现代著作。",al={"书被送往何处","暴风城图书馆投递","包装好的阅读材料交付"}},{q="为什么要交换这些书？",a="俱乐部正在淘汰一些不太受欢迎的文学作品，以换取更现代、更引人深思的著作，并依赖于与城市图书馆建立的借阅安排。",al={"为什么要交换书籍","为什么要归还书籍","交换阅读材料"}},{q="暴风城的图书管理员如何看待这个读书俱乐部？",a="暴风城的图书管理员对这一安排非常满意，并指出罗伊的俱乐部始终能以极好的状态归还借阅的材料，并且无论主题多么具有挑衅性，都能小心地对待所有的文本。",al={"图书管理员怎么看","读书俱乐部是被允许的吗","图书馆协议"}},{q="提到的俱乐部茶点是什么？",a="俱乐部为赞助者和协助在阅读场所与城市档案馆之间进行图书交换的帮手提供免费茶点。",al={"俱乐部免费茶点","俱乐部福利","有什么茶点"}}},fp="12,163,30.238.0,20.236.0,31.161.0,11.185.0,32.154.0,34.135.0,52.182.0,41.136.0"}
P.entries["quest:97236"] = {n="Fang of Githyiss",s="Fang of Githyiss是一种罕见且可怕的样本，取自一只潜伏在奥达希尔附近荒野中的巨型蜘蛛。将这枚毒牙交给保护区内的一位博物学家，可以帮助学者们研究这种怪物，并监测幽影谷内滋生的捕食威胁。",h="Fang of Githyiss是一种罕见且可怕的样本，取自一只潜伏在奥达希尔附近荒野中的巨型蜘蛛。将这枚毒牙交给保护区内的一位博物学家，可以帮助学者们研究这种怪物，并监测幽影谷内滋生的捕食威胁。",kw={"奥达希尔","基塞伊斯之牙","基塞伊斯","幽影谷","蜘蛛","蜘蛛研究","泰达希尔"},ang={["class:Druid"]="德鲁伊密切关注着泰达希尔内部的自然平衡，通过研究异常的捕食者和过度生长的蜘蛛来监测周边荒野的健康状况。",["faction:Alliance"]="对泰达希尔各地危险野生动物的研究有助于联盟确保年轻的招募者和研究人员了解在奥达希尔附近滋生的腐化威胁。",["race:NightElf"]="作为泰达希尔的保卫者，幽影谷的年轻暗夜精灵冒险者通过消灭危险的怪物并协助当地研究人员，帮助守护奥达希尔的枝干。"},sec={{t="一个巨大的样本",b="Fang of Githyiss是取自潜伏在幽影谷荒野中的巨型蜘蛛基塞伊斯身上的一种战利品和生物样本。这种体型巨大的野兽对从奥达希尔出发的年轻旅行者构成了明显的威胁，因此回收它的毒牙既关乎安全，也具有科学意义。与其让这只生物的遗骸在灌木丛中腐烂，足智多谋的侦察兵们会将样本带回这棵巨树的保护区。"},{t="在奥达希尔的研究",b="在奥达希尔，暗夜精灵的博物学家和学者们密切关注着在森林地面上游荡的野生动物。呈现一枚来自基塞伊斯这样规模的生物的新鲜、完整的毒牙，能为研究泰达希尔树冠下繁衍的蜘蛛种群提供关键的洞察。当地的研究人员欢迎这种意外的发现，并利用这枚巨大的毒牙进一步开展他们对林地攻击性动物群的持续研究。"}},faq={{q="什么是基塞伊斯的毒牙？",a="基塞伊斯的毒牙是取自巨型蜘蛛基塞伊斯身上的一枚新鲜样本。回收这样一枚巨大的毒牙可以提供有关栖息在奥达希尔周围荒野中的捕食性蜘蛛的罕见研究材料。",al={"什么是基塞伊斯的毒牙","基塞伊斯毒牙任务","基塞伊斯的毒牙物品"}},{q="基塞伊斯是谁，或者是什么？",a="基塞伊斯是一只体型巨大且危险的蜘蛛，在幽影谷奥达希尔附近的森林中徘徊。它的体型使它成为旅行者的威胁，也是当地博物学家研究的有趣对象。",al={"谁是基塞伊斯","基塞伊斯蜘蛛","基塞伊斯在哪里"}},{q="谁想要基塞伊斯的毒牙？",a="这枚毒牙会被带给奥达希尔的一位专门研究蜘蛛的学者。这类研究人员欢迎新鲜的样本，以推进他们对当地蜘蛛生物学的了解。",al={"谁上交基塞伊斯的毒牙","我把毒牙带到哪里","奥达希尔蜘蛛研究员"}},{q="奥达希尔在哪里？",a="奥达希尔是幽影谷的巨大枝干和中心保护区，位于世界之树泰达希尔的树冠之内。它是年轻暗夜精灵的训练场和避难所。",al={"奥达希尔在哪里","奥达希尔位置"}},{q="为什么奥达希尔的学者要研究蜘蛛毒牙？",a="奥达希尔的学者和博物学家研究当地的蜘蛛，是为了更好地了解幽影谷的生态，并监测泰达希尔树冠下栖息的攻击性超大野兽。",al={"为什么他们在奥达希尔研究蜘蛛","为什么要研究蜘蛛毒牙"}},{q="部落玩家可以上交基塞伊斯的毒牙吗？",a="不能。该任务发生在泰达希尔之上的暗夜精灵新手区域——幽影谷，因此只有在奥达希尔开启旅程的联盟冒险者才能完成。",al={"这个任务是联盟专属吗","部落能做基塞伊斯的毒牙任务吗"}}},fp="16,158,20.218.0,21.285.0,29.145.0,24.165.0,31.125.0,19.157.0,52.169.0,47.133.0"}
P.entries["quest:97237"] = {n="Shelf Picked",s="“Shelf Picked”是暴风城的一项信差差事，需要为Roy Lewells从图书馆书架上取回一份特定的阅读清单。作为授权代理人，跑腿者将代表公园里的一个本地读书会领取这些书籍。",h="“Shelf Picked”是暴风城的一项信差差事，需要为Roy Lewells从图书馆书架上取回一份特定的阅读清单。作为授权代理人，跑腿者将代表公园里的一个本地读书会领取这些书籍。",kw={"读书会","信差","图书馆","公园","罗伊·卢埃尔斯","书架选书","暴风城"},ang={["faction:Alliance"]="在暴风城的图书馆和当地聚会点之间跑腿送信，反映了在王国局势紧张的情况下，首都里依旧持续着的平静的日常公民生活。"},sec={{t="书架差事",b="“Shelf Picked”的内容是担任Roy Lewells的官方信差，此人与暴风城的公园区有关。Roy提交了一份各种阅读书目的请求，虽然负责的图书管理员确认了所列书目皆有库存，但信差必须亲自从书架上找到并取下每一本书。图书管理员留在前台处理监督性的簿记工作，在委托物理取书的同时确保库存记录维护妥当。"},{t="地窖读书会",b="处理借阅的图书馆藏书通常带有严格的归还义务，但携带Roy Lewells的授权书可提供官方信差身份。主管图书管理员指出，个人责任并不由跑腿者承担；相反，Lewells的机构承担归还借阅作品的全部责任。一旦送到公园，Roy就会准备好这些散发着异香的书籍，供晚些时候在地窖里举办的活跃讨论会使用。"}},faq={{q="谁发布了“书架取书”这个任务？",a="该任务是在罗伊·卢威尔斯发送了一张差事便条后，从负责管理图书馆库存的图书管理员那里接取的。图书管理员证实了罗伊要求的阅读清单有货，但指示你亲自从书架上取下这些书籍。",al={"谁发布书架精选","书架精选任务发布者","书架精选在哪里开始"}},{q="罗伊·卢威尔斯是谁？",a="罗伊·卢威尔斯是暴风城公园区一个本地读书会的组织者。他派遣信差从图书馆取回预订的书籍，用于即将在他们地窖中举行的非正式讨论会。",al={"罗伊·卢埃尔斯是谁","罗伊·卢埃尔斯公园","卢埃尔斯是谁"}},{q="藏书是在哪里取出的？",a="该任务发生在图书馆，卢威尔斯先生所选的读物都存放在那里。负责的图书管理员管理着库存记录，而信差则在场所的书架上寻找特定的书籍。",al={"这是什么图书馆","在哪里取书","书架取书是哪个图书馆"}},{q="为什么罗伊·卢威尔斯需要这些书？",a="罗伊·卢威尔斯请求这些阅读材料是为了让一个非正式读书会的成员激发热烈的讨论。由于聚会的性质，一旦书送到，他们就会在下班后的时间在地窖里集合。",al={"为什么要为卢维尔斯取书","什么是卢维尔斯读书会","地窖下班后读书会"}},{q="你有责任归还借来的书吗？",a="不。图书管理员明确澄清，以官方信差身份持有罗伊·卢威尔斯的便条可以免除你归还书籍的个人责任；归还书籍的重担完全由罗伊的机构承担。",al={"我有责任归还书籍吗","谁归还从书架取来的书","图书馆图书归还责任"}},{q="取回书后该带到哪里？",a="你将收集到的阅读材料直接送回给罗伊·卢威尔斯，他就在暴风城的公园区。",al={"书架取书在哪里交任务","哪里找到罗伊·卢维尔斯","书架取书交任务"}}},fp="12,89,24.274.0,23.294.0,33.201.0,19.175.0,42.154.0,38.122.0,53.127.0,44.65.0"}
P.entries["quest:97242"] = {n="Yelmak's Medley",s="Yelmak's Medley是奥格瑞玛的一个任务，旨在缓解荣誉谷中耶尔玛克药剂店内部的紧张局势。炼金大师耶尔玛克试图通过调制一种由当地水生植物制成的舒缓自制药剂，来遏制他的学徒伍特那破坏性的笨拙和顽固的自尊心。",h="Yelmak's Medley是奥格瑞玛的一个任务，旨在缓解荣誉谷中耶尔玛克药剂店内部的紧张局势。炼金大师耶尔玛克试图通过调制一种由当地水生植物制成的舒缓自制药剂，来遏制他的学徒伍特那破坏性的笨拙和顽固的自尊心。",kw={"炼金术","香蒲","考吉尔德","奥格瑞玛","矛草","荣誉谷","伍特","耶尔玛克","耶尔玛克的混合物"},ang={["faction:Horde"]="这项差事直接在奥格瑞玛的荣誉谷内进行，有助于维持秩序并平息首都炼金业内部的不满情绪。",["profession:Herbalism"]="沿着城市水道采集新鲜的香蒲和矛草，突显了奥格瑞玛城内的当地植物是如何被用于调制药剂和草药饮料的。"},sec={{t="实验室里的麻烦",b="在奥格瑞玛荣誉谷的耶尔玛克药剂店里，商店年轻学徒伍特的顽固自尊让生活变得复杂。这位新手调配师不仅不寻求帮助，也不承认自己力不从心，反而因为沮丧而开始破坏商店设备。为了减少损失并平息这名年轻人的暴躁脾气，同时又不伤及他脆弱的自尊心，炼金大师耶尔玛克设计了一种镇静的自制药剂。"},{t="舒缓的当地植物",b="配方需要新鲜采摘的野外香蒲和矛草插条，它们生长在荣誉谷蜿蜒的水流边。考吉尔德无法离开商店，否则会引起这位多疑学徒的注意，因此需要一个第三方谨慎地收集这些河岸植物。一旦收集完毕，这种植物混合剂将被调制出来，以微妙地控制伍特的态度，恢复炼金商店的平静。"}},faq={{q="谁发布了耶尔玛克的混合物任务？",a="考吉尔德位于奥格瑞玛荣誉谷的耶尔玛克药剂店内，他代表该店的炼金大师发布了这项任务。",al={"谁发布耶尔玛克的混合药剂","任务发布者耶尔玛克的混合药剂"}},{q="伍特是谁？",a="伍特是在荣誉谷跟随耶尔玛克训练的学徒调配师。他以顽固的自尊心闻名，他宁愿破坏设备也不愿承认自己需要指导或帮助。",al={"伍特是谁","耶尔玛克的学徒","奥格瑞玛的伍特"}},{q="这种自制药剂的目的是什么？",a="这是一种由炼金大师耶尔玛克用新鲜香蒲和矛草插条调制的特殊自制混合剂，旨在微妙地安抚或缓和其傲慢学徒的不良情绪。",al={"耶尔玛克的混合药剂的配方是什么","耶尔玛克想酿造什么"}},{q="在哪里采集原料？",a="野生香蒲和矛草直接生长在奥格瑞玛荣誉谷流经的淡水溪流和水池边。",al={"在哪里寻找香蒲和矛草","荣誉谷的插条"}},{q="为什么考吉尔德不亲自去采集插条？",a="考吉尔德不能离开耶尔玛克药剂店，因为伍特会立刻意识到商店员工是在秘密地费尽心思迁就他那难以相处的脾气。",al={"为什么考吉尔德需要帮助","为什么考吉尔德不能采摘植物"}},{q="耶尔玛克药剂店位于何处？",a="耶尔玛克药剂店坐落在荣誉谷，这是部落首都奥格瑞玛的东部地区，以其水道、战士兵营和工匠商店而闻名。",al={"耶尔玛克药剂店在哪里","耶尔玛克商店位置"}}},fp="15,228,25.302.0,20.325.0,37.142.0,13.167.0,46.140.0,35.117.0,52.131.0,46.149.0"}
P.entries["quest:97243"] = {n="Call of Fire",s="火焰的召唤指引一名初学者穿过天空之墙的风，寻找与火元素相契合的申多雷塑风者奥拉里安·迅燃。旅者将眠炎火炬带到阵风浆果低地的火焰神殿，开始学习如何在风的领域中聆听火焰的召唤。",h="火焰的召唤指引一名初学者穿过天空之墙的风，寻找与火元素相契合的申多雷塑风者奥拉里安·迅燃。旅者将眠炎火炬带到阵风浆果低地的火焰神殿，开始学习如何在风的领域中聆听火焰的召唤。",kw={"火焰的召唤","元素神域","阵风浆果低地","奥拉瑞安·迅焰","辛多雷","烈焰神殿","天空之墙","眠炎火炬","瓦拉纳尔","塑风者"},ang={["class:Shaman"]="聆听元素的召唤是萨满祭司修行的根本，即使在天空之墙，与火焰沟通也需要悉心的指引和对先祖的敬意。",["race:Skyborne"]="尽管生于天空之墙的风中，天裔旅者与塑风者仍明白，维持平衡需要认可全部四种原始元素。"},sec={{t="来自元素神域的声音",b="即使在风元素统治的天空之墙，元素神域中更广阔的元素流动依然彼此相连。大地、水与火之灵仍会向那些感知敏锐、能够聆听它们的人诉说。塑风者之中，有些成员对这些其他力量尤为敏感，其中就包括与火元素有着深厚共鸣的shen'dorei Olariaan Swiftburn。"},{t="火焰神龛",b="初学者受托携带眠炎火炬，前往阵风浆果低地。在遥远的岛屿边缘，瓦拉纳尔以西的隐蔽处，矗立着火焰神殿。在那里，奥拉里安·迅燃接过沉眠的火焰，愿意教导有志求学者，如何在风之领域翻涌的气流中回应火焰严苛的召唤。"}},faq={{q="奥拉里安·迅燃是谁？",a="奥拉里安·迅燃是塑风者中的一名深多雷，天生便与火焰相契合。他居住在火焰神殿，那里位于阵风浆果低地边缘的隐蔽处，在瓦拉纳尔以西。",al={"谁提供火焰的召唤任务","火炬交给谁","奥拉里安·迅燃"}},{q="火焰神殿在哪里？",a="火焰神殿位于天空之墙的阵风浆果低地。它隐于浮空岛屿的边缘，就在瓦拉纳尔正西方。",al={"烈焰神殿在哪里","阵风浆果低地位置","如何找到奥拉里安"}},{q="为何在天空之墙研习火焰？",a="尽管天空之墙主要是风的元素领域，它仍是更广阔的元素神域不可分割的一部分。对于那些与元素足够契合、能够聆听的人而言，四种元素之灵的声音仍在这片领域各处回荡。",al={"天空之墙为何有火焰","元素神域火焰","天空之墙不只有风吗"}},{q="眠炎火炬是什么？",a="眠炎火炬是一件带给奥拉里安·迅燃的元素法器，为寻求火焰沟通之道的初学者充当媒介。",al={"沉眠的火焰是什么","休眠烈焰火炬","携带什么物品"}},{q="塑风者是谁？",a="塑风者是在天空之墙中驾驭和塑造元素力量的修行者，其成员来自不同族群，包括深多雷。",al={"塑风者是谁","塑风者阵营"}},{q="这个任务会引向何处？",a="奥拉里安·迅燃教导弟子如何聆听火焰的召唤，并强调，要在天空之墙这一严苛的领域中掌握原始力量，需要极大的毅力。",al={"奥拉里安教什么","天空之墙火焰修行"}}},fp="12,133,33.297.0,20.312.0,26.163.0,30.145.0,37.152.0,35.145.0,24.146.0,29.142.0"}
P.entries["quest:97244"] = {n="Call of Fire",s="“火焰的召唤”是来自塑风者的一个任务，要求处决天祭司法拉迪尔（Skypriest Faladiel），他曾是一名为了力量而背叛教派的兄弟。冒险者必须追踪这名叛变的天祭司前往阵风浆果低地，并取回他的心脏，以作为一种强大元素仪式的燃料。",h="“火焰的召唤”是来自塑风者的一个任务，要求处决天祭司法拉迪尔（Skypriest...",kw={"奥拉凯斯","火焰的召唤","法拉迪尔","法拉迪尔的心脏","阵风浆果低地","阿基尔神殿","天祭司法拉迪尔","瓦拉纳尔","塑风者"},ang={["class:Priest"]="牧师们或许会认为天祭司法拉迪尔的腐化与堕落引人深思，因为他原本神圣的召唤职责被扭曲，变成了对自身教派的背叛与谋杀。",["class:Shaman"]="专注于火焰和元素仪式的萨满祭司们会认出这种严酷、原始的本质：将叛徒的精华喂给火焰，以增强其神圣的力量。"},sec={{t="烈焰中的叛徒",b="“火焰的召唤”要求冒险者猎杀天祭司法拉迪尔。他曾是一名塑风者，为了加入奥拉凯斯而抛弃了自己的忠诚。法拉迪尔曾是一名忠诚的火焰召唤者，但最终选择了力量而非盟誓，向同僚挥下屠刀，手上沾满了兄弟的鲜血。塑风者派遣了一名代理人去向他传达不容妥协的判决。"},{t="低地的清算",b="法拉迪尔躲藏在阵风浆果低地的一处农场中，该地位于瓦拉纳尔东北方，阿基尔神殿正南。杀死这名叛变的天祭司不仅仅是为了复仇；塑风者需要他的心脏作为即将举行的仪式中必不可少的残酷材料，他们坚信，吞噬叛徒的心脏能让他们的圣火燃烧得更加炽热。"},{t="以血偿血",b="在收到心脏后，塑风者重申了他们的信条：以血偿血。然而，法拉迪尔的死亡只是他们工作的一个阶段，因为这颗心脏只是仪式结束前，他们祭祀之火所需的一部分。"}},faq={{q="谁是天祭司法拉迪尔？",a="天祭司法拉迪尔曾是一名虔诚的火焰召唤者和塑风者的忠实成员。像许多奥拉凯斯成员一样，他为了追求力量而背弃了忠诚，转而对付自己的族人，手上沾满了他们的鲜血。",al={"谁是法拉迪尔","法拉迪尔背景故事","天祭司法拉迪尔传说"}},{q="为什么塑风者要杀掉法拉迪尔？",a="塑风者寻求报复是因为法拉迪尔为了力量背叛了他们，并杀害了昔日的兄弟姐妹。根据塑风者的信条，必须以血偿血，因此对他的处决既是正义的伸张，也是必要的报复。",al={"为什么要杀法拉迪尔","为什么塑风者要杀死法拉迪尔","法拉迪尔的背叛"}},{q="为什么塑风者需要法拉迪尔的心脏？",a="法拉迪尔的心脏是极其有效的仪式试剂。塑风者相信，火焰渴望吞噬叛徒心脏的祭品，以此为食会让烈焰燃烧得更加猛烈和炽热。",al={"为什么需要法拉迪尔的心脏","心脏有什么用","仪式试剂心脏"}},{q="在哪里可以找到天祭司法拉迪尔？",a="天祭司法拉迪尔在阵风浆果低地的一处农场中避难，该地位于瓦拉纳尔的东北方，阿基尔神殿的正南方。",al={"法拉迪尔在哪里","天祭司法拉迪尔位置","找到法拉迪尔"}},{q="塑风者的信条是什么？",a="塑风者是一个受严格且坚定信条约束的组织，在他们的教义中，背叛永不被遗忘，鲜血必须以鲜血偿还。他们修习火焰召唤和神圣的元素仪式。",al={"谁是塑风者","塑风者信条","塑风者派系"}},{q="奥拉凯斯与这次任务有什么联系？",a="奥拉凯斯是一个已知的派系或团体，其成员为了个人力量而交易掉了他们曾经的忠诚和荣誉，法拉迪尔就是他们天祭司中一个显著的例子。",al={"什么是奥拉凯斯","法拉迪尔奥拉凯斯","奥拉凯斯叛徒"}}},fp="12,165,25.301.0,25.282.0,21.176.1,26.207.0,44.181.0,45.145.0,38.123.0,37.122.0,50.127.0"}
P.entries["quest:97245"] = {n="Call of Fire",s="“火焰的召唤”是一项任务，冒险者受Olariaan Swiftburn委托，前往申达尔高地寻找并对决古老的森林精灵Kuramaa。通过从树桩中召唤精灵并用火焰将其击败，旅行者可以获得它强大的木制面具。随后，这件圣物会被带到阵风浆果低地，点燃永恒之火，并与火之灵沟通。",h="“火焰的召唤”是一项任务，冒险者受Olariaan...",kw={"锚点塔","火焰的召唤","森林精灵","阵风浆果低地","库拉玛","库拉玛的面具","奥拉里安·迅焰","申达尔高地"},ang={["class:Mage"]="Kuramaa对大多数魔法流派有着极强的抗性，迫使施法者只能纯粹依赖火焰魔法来战胜该精灵。",["class:Shaman"]="虽然该仪式与传统的萨满火焰试炼同名，但其重点在于用火焰制服强韧的高地之灵，从而汇聚力量以与火之灵进行沟通。"},sec={{t="高地的精灵",b="在申达尔高地，当地居民流传着关于Kuramaa的传说，这是一位古老的森林精灵，居住在靠近该地区锚点塔的一座山顶上的扭曲树桩内。想要引出这位隐居的实体，挑战者必须用赤手空拳敲击它木制家园的树皮，以此要求它现身，并在战斗中考验他们的勇气。"},{t="火与木",b="对于奥术或神圣力量的使用者来说，战胜Kuramaa并非易事，因为该精灵对大多数形式的魔法有着深厚的天然防护。只有灼热的火焰才能穿透它古老的树皮并将其击倒。击败该生物会掉落Kuramaa的木制面具，这是一件蕴含强大力量的文物。即便如此，Kuramaa依然是永恒的，注定会在被召唤时再次成形并显现。"},{t="永恒之火",b="在阵风浆果低地，Olariaan Swiftburn正等待着Kuramaa面具的带回。这件附魔的木制圣物是进行神秘仪式的催化剂：点燃永恒之火以直接与火之灵沟通，并通过击败高地自然之灵来开启古老的元素交流。"}},faq={{q="库拉玛是谁？",a="库拉玛是一位居住在申达尔高地的古老森林精灵。据当地高地居民所述，它居住在靠近高地锚点塔的一座山顶上的扭曲树桩内。",al={"库拉玛是谁","库拉玛背景故事","库拉玛是什么"}},{q="奥拉里安·迅焰是谁？",a="奥拉里安·迅焰是委托冒险者与库拉玛对决的仪式主持者。奥拉里安驻扎在阵风浆果低地，需要库拉玛的木制面具来执行神圣的火焰仪式。",al={"谁发布火焰的召唤任务","奥拉里安·迅燃是谁","火焰的召唤在哪里交任务"}},{q="如何召唤库拉玛？",a="库拉玛生活在申达尔高地锚点塔附近一座山顶上的扭曲树桩内。要将该精灵召唤出来进行战斗，必须用拳头用力敲击树桩的树皮。",al={"如何召唤库拉玛","库拉玛的树桩在哪里","召唤森林精灵"}},{q="库拉玛在战斗中有什么弱点？",a="库拉玛对大多数形式的魔法拥有卓越的天然抗性。只有火焰的触碰才能克服它的防御，并在战斗中击倒这位古老的森林精灵。",al={"库拉玛的弱点","如何击败库拉玛","库拉玛魔法免疫"}},{q="奥拉里安·迅焰为什么需要库拉玛的面具？",a="库拉玛的木制面具被公认为是一个拥有强大力量的容器。奥拉里安·迅焰利用这件强力的圣物作为点燃永恒之火并直接与火之灵沟通的关键组件。",al={"为什么要收集库拉玛面具","面具有什么用","库拉玛面具的用途"}},{q="库拉玛被击败后会永久死亡吗？",a="库拉玛是永恒的林地精灵，而非凡人生物。尽管它的物理形态会被击败以夺取其面具，但该精灵依然存在，并会在需要时再次显现。",al={"库拉玛死了吗","我杀了库拉玛吗","库拉玛刷新背景"}}},fp="12,243,27.254.0,13.259.0,17.259.1,15.169.0,26.161.0,26.171.0,40.113.0,48.113.0,47.113.0"}
P.entries["quest:97246"] = {n="Meal Appeal",s="Meal Appeal 是奥格瑞玛的一项跑腿任务，发布者是 Thatog。Thatog 是一位被日常职责束缚的兽人，他担心自己年幼的儿子 Migi 因为玩耍而错过了吃饭。旅行者需要从 博斯坦的火坑 取一份准备好的午餐，并找到在 索尔的堡垒 后方玩耍的 Migi。这个任务展现了部落首都里平凡的家庭生活。",h="Meal Appeal 是奥格瑞玛的一项跑腿任务，发布者是 Thatog。Thatog 是一位被日常职责束缚的兽人，他担心自己年幼的儿子 Migi 因为玩耍而错过了吃饭。旅行者需要从 博斯坦的火坑...",kw={"博斯坦","博斯坦的火坑","索尔的堡垒","午餐派送","美食的诱惑","米吉","奥格瑞玛","萨托格"},ang={["faction:Horde"]="奥格瑞玛城墙内的生活并非只有战争与防御；像给在力量谷奔跑的孩子们喂饭这样的日常琐事，维系着这座城市的社区活力。",["race:Orc"]="即使在严酷的兽人文化中，像 Thatog 这样的父母也会担心他们的孩子因为在杜隆塔尔首都的街头玩耍而忽略了吃饭。"},sec={{t="奥格瑞玛的为人父母之道",b="在奥格瑞玛那熙熙攘攘的红石大道上，平凡的家庭生活与步兵的操练及部落的阴谋并存。Thatog 因为职责在身，无法时刻照看精力充沛的幼子 Migi。没人管束的 Migi 从早到晚都在城里和朋友们追逐打闹，总是饿着肚子直到回家。"},{t="要塞后方的派送",b="为了不让孩子下午饿肚子，Thatog 在博斯坦的火坑安排了一份热乎的午餐。因为 Migi 不会为了拿午餐而中断游戏，Thatog 便请求路过的冒险者充当私人信使。这项跑腿任务将指引旅行者从博斯坦的炉火处前往索尔的堡垒后方的空地，Migi 和街坊邻里的孩子们通常总能在那里找到，沉浸在他们的儿时游戏中。"}},faq={{q="萨托格 是谁？",a="萨托格 是一位驻守在奥格瑞玛的忙碌兽人父亲，他的日常职责使他无法抽身去监管年幼的儿子 米吉。出于对 米吉 因为和朋友玩耍而错过饭点的担忧，萨托格 请一位乐于助人的冒险者去为男孩取餐并送餐。",al={"萨托格 是谁","任务发布者 萨托格","萨托格 奥格瑞玛"}},{q="去哪里能找到 米吉？",a="米吉 白天都在首都和朋友们一起玩耍。萨托格 指出，孩子们几乎肯定会在奥格瑞玛的索尔的堡垒后方嬉戏打闹。",al={"米吉 在哪里","米吉 位置","找到 米吉"}},{q="博斯坦的火坑是什么？",a="博斯坦经营着博斯坦的火坑，这是奥格瑞玛的一家地方餐饮店。萨托格 请旅行者先去那里，告知博斯坦你是来取一份预定好的午餐，并亲自送给 米吉。",al={"博斯坦的火坑 在哪里","博斯坦的火坑 位置","博斯坦 午餐"}},{q="米吉 为什么会忘记吃饭？",a="和许多精力充沛的年轻兽人一样，米吉 因为在索尔的堡垒后方和朋友们玩得太投入，以至于忘记或者选择不去博斯坦的火坑吃饭，往往在一天结束时饿着肚子回到家。",al={"米吉 为什么不吃午饭","米吉 挨饿","米吉 为什么不吃饭"}},{q="米吉 是谁？",a="米吉 是 萨托格 的幼子。他在奥格瑞玛四处游荡，和一群朋友玩游戏，比起回家或去取准备好的饭菜，他把玩耍放在了第一位。",al={"米吉 是谁","米吉 兽人小孩","萨托格 的儿子"}},{q="午餐的呼唤 的任务目标是什么？",a="任务要求前往博斯坦的火坑告知博斯坦你是 萨托格 派来取 米吉 的午餐的人，然后将食物直接送到索尔的堡垒后方的 米吉 手中，这样男孩在游戏时就不会挨饿了。",al={"美食诱惑 任务目标","美食诱惑 怎么做","美食诱惑 任务"}}},fp="11,160,28.244.0,24.234.0,14.203.0,24.115.0,26.132.0,28.130.0,12.137.0,37.121.0"}
P.entries["quest:97249"] = {n="Favorite Food",s="“Favorite Food”是一个关于Migi的奥格瑞玛任务。Migi是个贪玩的孩子，常在格罗玛什要塞后玩耍，他的父母担心他吃得不够多。为了在不让他饿肚子的情况下拓宽他的口味，Borstan's Meats的博斯坦准备了各种午餐，并用Migi最爱的蜜汁酥脆猪皮调味。这份午餐确保了这孩子和他的朋友们会停下游戏，享受一顿营养均衡的饭菜。",h="“Favorite Food”是一个关于Migi的奥格瑞玛任务。Migi是个贪玩的孩子，常在格罗玛什要塞后玩耍，他的父母担心他吃得不够多。为了在不让他饿肚子的情况下拓宽他的口味，Borstan's...",kw={"博斯坦","博斯坦的肉","最爱的食物","索尔的堡垒","猪腩","午餐","米吉","奥格瑞玛","蜜汁"},ang={["faction:Horde"]="这个任务展现了奥格瑞玛日常生活的一瞥，展示了当地商贩和家庭如何确保首都的孩子们得到照顾和喂养。",["profession:Cooking"]="这项任务演示了部落首都中实用的烹饪工艺，将酥脆的熏猪腩猪皮碎屑再利用，作为日常餐食的美味调料。"},sec={{t="玩耍的胃口",b="在部落权力的中心——格罗玛什要塞后方，年幼的Migi和他的朋友们常常在奥格瑞玛尘土飞扬的小路上玩耍。然而，Migi的父母担心这孩子在玩的时候经常不吃饭，没法填饱肚子。为了确保他能按时进食，他们找来了Borstan's Meats制作每日盒装午餐。但父母提出了一个严格的要求：博斯坦不能每天都提供同样的餐食，他们坚持要让Migi尝试不同的食物，而不是只依赖他最爱的那一道菜。"},{t="蜜汁妥协",b="博斯坦面临着烹饪挑战，因为众所周知，Migi非常钟爱蜜汁猪腩三明治，而且只有在熏肉房里飘出那种甜味时，他才会准时出现吃午饭。为了满足父母对餐食多样性的要求，同时又能让孩子吃饱，这位屠夫想出了一个巧妙的办法。当准备蜜汁猪肉时，剩下的酥脆蜜汁猪皮碎屑可以制成一种咸香的调料，撒在任何菜肴上。送到格罗玛什要塞后方的这份带有香气的调料，成功让Migi和他的同伴们停下游戏，聚在一起享用午餐。"}},faq={{q="米吉是谁？",a="米吉是奥格瑞玛的一名小居民，平日里总是在格罗玛什要塞后方和朋友们一起玩游戏。因为他玩得太投入，父母很担心他没法填饱肚子，所以安排了博斯坦肉铺每天送午餐过来。",al={"米吉 奥格瑞玛","格罗玛什要塞后面的孩子是谁","米吉的午餐"}},{q="是谁发布了“最喜欢的食物”任务？",a="该任务由奥格瑞玛博斯坦肉铺的博斯坦发布。在了解到米吉父母对其营养和饮食习惯的担忧后，博斯坦准备了一份旨在拓宽这孩子口味的特别餐点。",al={"最爱的食物任务发布者","谁开启最爱的食物","博斯坦 最爱的食物"}},{q="米吉在哪里可以找到？",a="米吉位于奥格瑞玛的格罗玛什要塞后方，他常在那里和当地的其他孩子一起玩耍。这些孩子经常经过通往要塞的路，仅凭气味就能认出博斯坦每日提供的特色菜。",al={"米吉的位置","米吉在哪里","在哪递送米吉的午餐","寻找米吉 奥格瑞玛"}},{q="米吉最喜欢吃什么？",a="米吉最喜欢吃的是博斯坦肉铺熏肉房里制作的蜜汁猪腩三明治。只要熏肉房开工，米吉总会准时来吃午饭，被飘向格罗玛什要塞的独特香气所吸引。",al={"米吉喜欢吃什么","米吉最爱的食物","蜜汁猪腩 米吉"}},{q="为什么米吉的父母要求提供不同的餐食？",a="米吉的父母要求博斯坦不要每天都打包完全一样的午餐，这样他们的儿子就能培养对更多食物的兴趣。虽然他们很想让孩子吃饱，但更希望他能养成全面的饮食习惯，而不是只靠蜜汁猪肉度日。",al={"为什么要改变米吉的午餐","米吉父母的要求","为什么不能每天都吃蜜汁三明治"}},{q="博斯坦是如何让米吉吃下不同食物的？",a="博斯坦将熏猪腩剩下的酥脆蜜汁猪皮碎片捣碎，做成一种可以撒在不同菜肴上的配料。这种浓郁且熟悉的蜜汁风味，让博斯坦能提供各种各样的饭菜，而米吉依然会吃得干干净净。",al={"博斯坦的诀窍","博斯坦如何让米吉吃饭","蜜汁碎屑"}},{q="什么是博斯坦肉铺？",a="博斯坦肉铺是位于奥格瑞玛的一家熏肉房和肉铺，以其熏猪腩三明治和为城中居民提供盒装餐食而闻名。博斯坦利用他的烹饪天赋，让社区里的孩子们吃得饱饱的。",al={"博斯坦的肉铺 奥格瑞玛","博斯坦的肉铺在哪里","博斯坦是什么人"}}},fp="13,185,20.349.0,25.403.0,12.215.0,34.147.0,24.188.0,29.167.0,46.167.0,49.153.0,24.171.0"}
P.entries["quest:97250"] = {n="Wrongly Blamed, Justly Corrected",s="“误会被责，正义纠正”聚焦于部落与联盟在东海岸日益升级的紧张局势，起因是一间路边旅店的离奇毁灭。这一事件给了联盟军队一个严厉的警告，同时也留下了一个悬而未决的疑点：究竟是谁威胁到了这条重要的平民贸易路线。",h="“误会被责，正义纠正”聚焦于部落与联盟在东海岸日益升级的紧张局势，起因是一间路边旅店的离奇毁灭。这一事件给了联盟军队一个严厉的警告，同时也留下了一个悬而未决的疑点：究竟是谁威胁到了这条重要的平民贸易路线。",kw={"联盟警告","平民路线","东海岸","部落贸易","旅店","领土冲突","蒙受冤屈, 公正昭雪"},ang={["faction:Alliance"]="这一结果是部落军队针对联盟日益增长的势力和挑衅行为，在东海岸发出的严厉警告。",["faction:Horde"]="该任务标志着一次显著的胜利和对联盟入侵行为的防御性声明，同时也引起了对保护重要部落贸易和平民路线的担忧。"},sec={{t="海岸摩擦",b="随着部落与联盟在东海岸沿线的摩擦不断加剧，冲突已经开始蔓延至争议地区。主要通道上一间当地旅店的毁灭将这些紧张局势推向了顶峰，并威胁到了普通旅客的安全与地区的稳定。"},{t="疑点与破坏",b="虽然最初的怀疑指向部落的侵略行为，但当地领导层怀疑并非己方力量摧毁了旅店。这条通道是部落平民和商人们运输货物的生命线，部落有充分的理由保持这条道路畅通，这也促使人们更深入地调查究竟是谁摧毁了它。"},{t="对联盟的警告",b="尽管关于旅店本身的疑问尚存，但这件事的结局标志着部落军队在当地取得了一次决定性的胜利。这一结果向联盟发出了明确的警告：任何沿海岸的领土侵犯都将遭到立即的抵抗。"}},faq={{q="“误会被责，正义纠正”讲的是什么？",a="“误会被责，正义纠正”是一个部落任务，讲述了因一条重要旅行路线上的路边旅店被毁，而导致的东海岸阵营间摩擦升级。",al={"这个任务是什么","误会被责正义纠正剧情","误会被责发生了什么"}},{q="是部落摧毁了旅店吗？",a="部落领导层仍然非常怀疑部落军队是否负有责任。太多的部落平民依赖这条路线进行贸易和日常通行，摧毁它只会适得其反。",al={"部落摧毁了旅店吗","谁烧了旅店","谁摧毁了旅店"}},{q="为什么被毁的旅店对部落很重要？",a="这家旅店位于一条重要的通道上，平民旅客和商人们高度依赖它进行贸易和通行，因此它的损毁是一个战略性的忧虑。",al={"为什么旅店路线很重要","为什么旅店很重要"}},{q="是什么导致了东海岸的紧张局势？",a="最初导致紧张局势的原因尚不明确。部落与联盟在东海岸的摩擦由来已久，现在冲突已经波及到了部落领地。",al={"为什么在东海岸战斗","东海岸冲突"}},{q="这一结果向联盟传达了什么信息？",a="这次行动是一次战术上的胜利，并向联盟发出了严厉的警告，表明针对部落利益的领土入侵行为不会不受惩罚。",al={"部落取得了什么成就","为什么要警告联盟"}},{q="是否会对旅店的损毁进行进一步调查？",a="由于旅店损毁的情况依然存疑，且平民通行受到威胁，各方都在寻求进一步调查以查明究竟是谁造成了这次破坏。",al={"调查什么","会调查旅店吗"}}},fp="32,254,21.212.0,20.248.1,25.211.0,47.160.0,33.171.0,50.162.0,42.162.0,52.105.0,61.139.0"}
P.entries["quest:97253"] = {n="Parts and Pieces",s="“Parts and Pieces”是卑鄙的维尼克斯在棘齿城港口发布的一个取回任务。在几名雇佣兵相继在当地海盗手中丧命后，维尼克斯部署了一台机械装置来应对威胁，结果却被海盗拆成了废铁。冒险者受命前往海盗的上层营地，在造成进一步损失前找回散落的零件。",h="“Parts and...",kw={"复杂零件","机器","零零碎碎","海盗","海盗们","棘齿城","弯刀","上层海盗营地","卑鄙的维尼克斯"},ang={["profession:Engineering"]="技师和工程师们一定能体会到这一讽刺：一台精密的机械装置，竟然败给了粗野的海盗。打捞维尼克斯的复杂零件，能让人深刻地意识到，在没有足够的物理防护下将自动化原型机部署到敌对营地是多么危险。"},sec={{t="机械方案",b="棘齿城南侧海岸的海盗活动对该港口的居民和商贩来说愈发令人头疼。为了在不浪费更多金钱雇佣无用打手的情况下解决这些掠夺者，技师卑鄙的维尼克斯决定亲自出马。在先后派出了五六个一去不复返的雇佣兵后，维尼克斯想出了一个似乎更高明的替代方案：派出一台自动化机器来对付海盗。与其让其他活人去冒险，不如让这台机械构装体自主解决营地的问题。"},{t="弯刀与螺丝刀",b="这一天才的部署并没有按计划顺利进行。占据城南营地的海盗出人意料地机敏，他们很快发现手中的弯刀可以当成简易螺丝刀使用。在维尼克斯下令让机器撤回棘齿城之前，掠夺者们就已经把装置拆得七零八落，并将它精细的组件散落在了上层营地各处。现在，海盗没被消灭，发明家却需要一位勇敢的斥候潜入营地，从泥土中收集五把散落的复杂机械零件。"}},faq={{q="谁是卑鄙的维尼克斯？",a="卑鄙的维尼克斯是一位住在中立港口城市棘齿城的古怪技师。面对南侧海岸的一群气焰嚣张的掠夺者，维尼克斯试图通过技术创新来解决海盗问题。在几名雇佣兵相继丧命后，他制造并派出了一台自动化机器来应对威胁，结果很快就被拆毁了。",al={"谁是维尼克斯","卑鄙的维尼克斯背景","棘齿城 维尼克斯"}},{q="维尼克斯之前雇佣的那些佣兵怎么了？",a="在诉诸机械自动化之前，维尼克斯雇佣了五六个不同的冒险者来消灭棘齿城南面的海盗威胁。没有一个人活着回来，这证明了海盗营地是何等致命且防御森严。他们的惨死让维尼克斯断定，依赖血肉之躯的雇佣兵既低效又致命。",al={"维尼克斯之前的佣兵","其他冒险者发生了什么","维尼克斯先派了谁"}},{q="维尼克斯为什么要派一台机器去对付海盗？",a="维尼克斯制造并派遣了这台机械装置，因为他之前使用真人士兵的尝试彻底失败，导致了人员伤亡。他相信钟表驱动的造物可以在凡人战士倒下的地方取得成功——或者至少避免进一步的伤亡——于是他直接将机器送进了营地，期待着机械的巧妙设计能压制住海盗。",al={"为什么要派机器","维尼克斯的机器人计划","维尼克斯为何使用机械装置"}},{q="海盗是如何拆毁维尼克斯的机器的？",a="在面对维尼克斯的构装体时，海盗们展现出了惊人的创造力。掠夺者们用弯刀充当临时螺丝刀，在维尼克斯发出指令让机器撤回棘齿城之前，就迅速将机器拆散了。他们把装置拆得只剩下框架，并将错综复杂的组件扔得到处都是。",al={"机器是如何被摧毁的","海盗如何拆毁机器人","海盗 弯刀 螺丝刀"}},{q="那些复杂的零件在哪里？",a="维尼克斯破碎机器的组件位于棘齿城南侧海岸线上的上层海盗营地内。在用弯刀拆解了设备后，海盗们将其复杂的零件散落在山顶营地的地面上。冒险者必须潜入营地，收集五把这些复杂零件。",al={"零件在哪里","上层海盗营地位置","复杂零件收集地点"}},{q="为什么维尼克斯认为这个回收任务更安全？",a="维尼克斯认为这项任务存活几率高得多，因为这纯粹是一次打捞行动，而不是公开的突袭。之前的雇佣兵受命直接根除海盗，而这项回收任务只需要潜入上层营地，从泥土中拾取五把散落的机器组件，然后返回棘齿城。",al={"零件与碎片任务安全吗","为什么维尼克斯认为你能存活","维尼克斯的生存几率分析"}},{q="“复杂零件”有什么用？",a="这些复杂零件是为维尼克斯的自动化构装体提供动力的特制齿轮、弹簧和精密机械配件。由于他消灭海盗的尝试最终导致机器被拆，维尼克斯需要找回这些精密的零件，以免他宝贵的工程工艺和材料彻底浪费。",al={"什么是复杂零件","维尼克斯为什么要零件","维尼克斯用零件做什么"}}},fp="16,217,21.426.0,26.363.0,27.277.0,54.135.0,51.180.0,47.262.0,40.206.0,56.254.0,42.154.0"}
P.entries["quest:97257"] = {n="Call of Fire",s="火焰的召唤是由天空之墙内的塑风者所监督的萨满祭司成年礼。初学者必须协助召唤烈焰之灵，捕获 Eternal Flame，并与时间赛跑，在瓦拉纳尔点燃火盆。成功完成这项试炼证明了对元素的尊重，并让初学者获得他们的火焰图腾。",h="火焰的召唤是由天空之墙内的塑风者所监督的萨满祭司成年礼。初学者必须协助召唤烈焰之灵，捕获 Eternal Flame，并与时间赛跑，在瓦拉纳尔点燃火盆。成功完成这项试炼证明了对元素的尊重，并让初学者获得他们的火焰图腾。",kw={"火焰的召唤","永恒之火","火焰图腾","火焰之地","奥拉里安","天空之墙","瓦拉纳尔","塑风者"},ang={["class:Shaman"]="这个仪式标志着萨满祭司的关键成年礼，赋予他们对火焰的掌控力，并在完成后授予他们火焰图腾。",["race:Skyborne"]="该试炼由天空之墙的塑风者管理，反映了尊崇元素位面的天空萨满传统。"},sec={{t="烈焰仪式",b="火焰的召唤是在天空之墙内进行的一种神圣的元素调和试炼。在塑风者的 Olariaan 的带领下，初学者聚集在 Brazier of Offering 旁，召唤来自 Firelands 的烈焰之灵。如果供品被认为值得，烈焰之灵就会用神圣的 Eternal Flame 点燃祭坛，等待有志之士来驾驭它。"},{t="前往瓦拉纳尔",b="一旦点燃，Eternal Flame 必须被捕获到火炬上，并迅速穿过天空之墙运送到瓦拉纳尔。由于 Firelands 的能量在元素空气位面的旋涡大气中自然会减弱和消散，初学者必须与时间赛跑，在火焰熄灭前到达 Brazier of Eternal Flames 处。"},{t="火焰图腾",b="在瓦拉纳尔重新点燃火盆证明了初学者对元素的纪律和敬畏。为了表彰这一成就，塑风者会授予初学者他们的火焰图腾。正如长者所教导的那样，元素之力乐于服务尊重它的人，但会无情地吞噬那些不尊重它的人。"}},faq={{q="什么是火焰的召唤？",a="火焰的召唤是一种神圣的成年礼，在此仪式中，有抱负的萨满祭司会协助召唤烈焰之灵并捕获 永恒之火。将这神圣之火带到瓦拉纳尔证明了初学者对元素位面的尊重，并使他们获得火焰图腾。",al={"火焰的召唤 是什么","火焰的召唤 任务","这个任务的内容是什么"}},{q="奥拉里安 是谁？",a="奥拉里安 是指导 献祭火盆 仪式的主祭。他将必要的材料放在祭坛上，并召唤烈焰之灵来点燃 永恒之火。",al={"奥拉里安 是谁","奥拉里安 的职责","谁发起了仪式"}},{q="什么是 永恒之火？",a="永恒之火 是在塑风者仪式中从 火焰之地 召唤而来的烈焰之灵的显现。初学者必须将其捕获到火炬上，并点燃瓦拉纳尔的 永恒烈焰火盆。",al={"什么是 永恒之火","天空之墙的 永恒之火"}},{q="为什么必须尽快将火焰带到瓦拉纳尔？",a="召唤出的原始元素之火起源于 火焰之地，其强烈的热量在天空之墙这个以空气为主导的位面中会迅速消散。初学者必须迅速行动，以确保火炬在到达瓦拉纳尔之前不会熄灭。",al={"为什么 永恒之火 会消散","为什么要赶往瓦拉纳尔","天空之墙的 火焰之地 之火"}},{q="谁是塑风者？",a="塑风者是居住在天空之墙的一个组织，他们引导初学者通过元素试炼。他们尊崇元素位面的平衡与力量，并监督图腾的授予。",al={"谁是塑风者","塑风者派系"}},{q="完成试炼的奖励是什么？",a="完成仪式并成功重新点燃瓦拉纳尔的火盆，初学者将获得他们的火焰图腾，这是引导炽热元素之力的重要工具和焦点。",al={"火焰的召唤 奖励","火焰图腾奖励","完成 火焰的召唤 能得到什么"}}},fp="12,164,19.298.0,23.246.0,14.247.0,25.197.0,16.148.0,26.201.0,50.148.0,24.178.0,44.140.0"}
P.entries["quest:97263"] = {n="Your Package Has Arrived",s="“Your Package Has Arrived”是一个关于在铁炉堡投递的失落邮件的紧急快递任务。一个从蛮锤部族的堡垒鹰巢山一路寄来的快递板条箱被遗弃在邮箱旁边，收件人明确写着Eldrun Stormbreaker。发现包裹的旅行者需要完成投递任务，确保它到达其合法的收件人手中。",h="“Your Package Has Arrived”是一个关于在铁炉堡投递的失落邮件的紧急快递任务。一个从蛮锤部族的堡垒鹰巢山一路寄来的快递板条箱被遗弃在邮箱旁边，收件人明确写着Eldrun...",kw={"鹰巢山","埃尔德伦·破风","铁炉堡","邮箱","错置的包裹","紧急投递","蛮锤","你的包裹已送达"},ang={["faction:Alliance"]="在辛特兰和铁炉堡之间保持开放和可靠的通讯路线，对于联盟在卡兹莫丹和北部领土的利益至关重要。",["race:Dwarf"]="矮人们会认可铁炉堡的铜须部族与他们身处鹰巢山的蛮锤表亲之间紧密的联系，这使得这个包裹的安全抵达成为关乎部族尊严的大事。"},sec={{t="错置的货运",b="一次邮政失误导致几个遗失的包裹被丢弃在城市邮箱旁，它们被暴露在外，而没有安全地送到目的地。在这堆被忽视的杂乱货物中，有一个标记为紧急投递的包裹，它是从辛特兰的蛮锤矮人山地据点——鹰巢山一路寄来的。在卡兹莫丹和洛丹伦的遥远前哨站之间运输货物可能充满危险和混乱，这意味着偶尔需要警觉的过路人介入，妥善完成投递路线。"},{t="寄给Eldrun Stormbreaker的包裹",b="这个被放错位置的包裹上清楚地贴着标签，标明铁炉堡为目的地，Eldrun Stormbreaker为最终收件人。包裹上明确标有紧急通知，无论这个包裹里装的是什么货物，都被认为重要到需要从辛特兰的乡村山峰加急运送到矮人首都的地下大厅。拿起这个板条箱就意味着承担起邮政服务的责任，确保Eldrun收到这件跨越山脊和荒原寄来的物品，以免它被盗走或彻底遗忘。"}},faq={{q="邮箱旁发现的包裹是什么？",a="这个包裹是一件从辛特兰的鹰巢山寄出的紧急快递，收件人是铁炉堡的一位名叫埃尔德伦·破风者的人。它似乎在正常的快递处理过程中没有到达最终目的地，而是与其他几个包裹一起被错放在了邮箱旁边。",al={"包裹是什么","错置的包裹","邮箱旁边丢了什么","邮箱包裹"}},{q="谁是埃尔德伦·破风者？",a="埃尔德伦·破风者是这件在矮人首都铁炉堡内被错置的包裹的指定收件人。虽然包裹上清楚地写着他们的名字并注明了加急，但在包裹安全送到他们手中之前，货运标签上并没有透露太多其他信息。",al={"谁是艾尔德伦·破风者","艾尔德伦·破风者","谁收到包裹","包裹收件人"}},{q="包裹是从哪里寄出的？",a="这批货物始发于鹰巢山，这是蛮锤部族位于辛特兰群山之中的重要定居点和堡垒。标签显示它在前往铁炉堡的途中，在经过路线上的当地邮箱附近被错放了。",al={"包裹从哪里来","包裹起源","它是从哪里寄出的","鹰巢山投递"}},{q="为什么包裹被标记为紧急？",a="货运标签上带有紧急标签，是因为从鹰巢山寄出板条箱的人认为其内容或到达时间非常重要。考虑到蛮锤高地与铁炉堡城之间横跨的领土距离，延迟的货物可能会给埃尔德伦·破风者造成重大麻烦。",al={"为什么是紧急的","紧急投递","包裹里有什么","为何紧急"}},{q="为什么包裹被丢在邮箱旁边？",a="几个包裹莫名其妙地被丢弃在邮箱旁，而不是由当地的快递员进行分拣和配送。繁重的快递流量、后勤混乱或单纯的疏忽经常导致货物在运输途中暂时失落，这需要乐于助人的冒险者来解决这一失误。",al={"为什么它被遗弃了","为什么包裹被丢弃","丢失的邮件","错置的包裹"}},{q="这个包裹需要送到哪里？",a="这个包裹标明要投递到铁炉堡，明确指名交给埃尔德伦·破风者。任何发现这批失落货物的人都必须承担起快递员的角色，将这个紧急包裹直接带给身处地下矮人要塞城市里的埃尔德伦。",al={"我该送到哪里","包裹目的地","投递地点","我该把包裹带给谁"}},{q="鹰巢山和铁炉堡之间有什么联系？",a="鹰巢山是蛮锤矮人的心脏，而铁炉堡是铜须部族的宏伟王座。虽然这些部族维持着各自独特的习俗和家园，但辛特兰的峭壁和大锻炉的地下大厅之间依然流动着定期的通信、贸易和亲缘关系。",al={"鹰巢山和铁炉堡","蛮锤与铜须贸易","铁炉堡鹰巢山联系","为什么要从鹰巢山寄信"}}},fp="24,144,17.359.0,32.258.0,41.199.0,27.195.0,31.198.0,33.183.0,46.149.0,45.138.0,56.245.0"}
P.entries["quest:97265"] = {n="Hate the Hatefury",s="葬影村的Aka'rai请你袭击萨格隆的怨怒萨特。他的怨恨源于一场交易，如今他一心复仇。",h="葬影村的Aka'rai请你袭击萨格隆的怨怒萨特。他的怨恨源于一场交易，如今他一心复仇。",kw={"aka'rai","凄凉之地","痛恨怨怒","怨怒","萨格隆","萨特","葬影村","灵魂石"},sec={{t="Aka'rai的怨恨",b="Aka'rai讲述了他与一名萨特的交易，对方许诺给予他力量与知识。他说，怨怒抛弃了他，让他落得比从前更差的境地。如今，他请你袭击葬影村东北方萨格隆的营地。他要用他们的鲜血来复仇。"},{t="鲜血交易",b="战斗结束后，Aka'rai说有一名怨怒逃过了你的袭击。他指出，那名萨特曾与他一同举行过以鲜血为印记的仪式。萨特拿着Aka'rai的灵魂石，所以只要灵魂石还在他手中，Aka'rai就不敢离开葬影村。他说，眼下你的任务已经完成。"}},faq={{q="谁在寻求帮助？",a="葬影村的Aka'rai请你袭击萨格隆的怨怒萨特。",al={"谁是aka'rai","aka'rai","怨怒给予者"}},{q="Aka'rai为何想要袭击怨怒？",a="Aka'rai说，怨怒在一场许诺给予他力量与知识的交易后抛弃了他。",al={"为何怨怒","aka'rai复仇","萨特怨恨"}},{q="怨怒在哪里？",a="怨怒营地位于凄凉之地的萨格隆，在葬影村东北方。",al={"怨怒位置","萨格隆萨特","营地在哪里"}},{q="Aka'rai交易的内容是什么？",a="Aka'rai说，交易许诺给予他力量、超越寻常典籍的知识，以及一个热切效忠的仆从。",al={"aka'rai交易","萨特交易","力量交易"}}},fp="17,149,19.285.0,17.298.1,23.80.0,44.91.0,23.78.0,29.94.0"}
P.entries["quest:97275"] = {n="Whuut's the Rush",s="“Whuut's the Rush”是一个炼金术差事，突显了天赋与严谨工艺之间的张力。耶尔玛克委托一位冒险者将一瓶不起眼、精心调制的药剂送给他的天才学徒伍特，以此展示真正的大师从日常植物开始，而不是浪费稀有试剂。",h="“Whuut's the Rush”是一个炼金术差事，突显了天赋与严谨工艺之间的张力。耶尔玛克委托一位冒险者将一瓶不起眼、精心调制的药剂送给他的天才学徒伍特，以此展示真正的大师从日常植物开始，而不是浪费稀有试剂。",kw={"炼金术","黑莲花","香蒲","草药学","山鼠草","药剂","长矛草","伍特","耶尔玛克"},ang={["faction:Horde"]="耶尔玛克教导有抱负的炼金术师如何保持耐心、足智多谋，以及尊重当地的卡利姆多原料，而不是挥霍宝贵的物资。",["profession:Herbalism"]="采集者和草药师会领会这个差事核心的教训：了解像长矛草和香蒲这样的日常杂草的特性，对于这门手艺来说，可能与寻找传奇花朵同样重要。"},sec={{t="急切的天才",b="在繁忙的炼金药店里，天赋往往会与鲁莽的野心发生碰撞。伍特被公认为一位真正的天才，在搅拌棒背后有着极高的本能。然而，他的急躁导致他在尚未打下扎实的酿造技术基础前，就耗尽了店里最稀有的试剂。在还没学会普通草药的细微平衡之前，他就去寻找那些传奇植物，把炼金术当成了一场竞赛，而不是一门学科。"},{t="瓶中的一课",b="为了在不压抑伍特热情的情况下约束他，耶尔玛克将一课浓缩进了一个药瓶里。耶尔玛克没有责骂伍特，而是用普通的长矛草和香蒲通过快速药剂法调制了一种精致的药剂。当这位年轻人在对着黑莲花和山鼠草做白日梦时，这份朴素的混合物被交到了他手中，揭示了真正的炼金术造诣源于技术、耐心以及对日常植物的尊重。"}},faq={{q="伍特是谁？",a="伍特是一位年轻的炼金术天才，急于尝试现存最稀有的草药。虽然他无疑很有天赋，但他急于使用异域试剂进行调制，导致他忽略了炼金术的基础。",al={"伍特是谁","伍特背景故事","关于伍特"}},{q="耶尔玛克是谁？",a="耶尔玛克是一位经验丰富的炼金术师，在店里担任导师。由于担心伍特在浪费宝贵的补给，耶尔玛克调制了一种简单的药剂，以证明真正的大师是从不起眼的本地原料开始的。",al={"谁给这个任务","耶尔玛克的角色","耶尔玛克是谁"}},{q="为什么耶尔玛克让你送药剂给伍特？",a="耶尔玛克想要教会伍特炼金术基础中的耐心与尊重。通过展示即使使用长矛草和香蒲这样的普通植物也能调制出有效的药剂，他希望抑制伍特直接冲向那些未经研究的稀有草药的习惯。",al={"耶尔玛克的课程是什么","为什么耶尔玛克要送药剂","任务的核心目的"}},{q="耶尔玛克在他的药剂里使用了什么原料？",a="耶尔玛克调制这瓶示范药剂时，只使用了普通的长矛草和香蒲，向他的学徒证明，当以细致的手法进行准备时，普通的路边植被也能产生惊人的效果。",al={"药剂里有什么","耶尔玛克药剂试剂","快速药剂原料"}},{q="伍特试图使用哪些稀有试剂？",a="在被打断之前，伍特正急切地去抓艾泽拉斯最珍贵和传奇的植物，特别是黑莲花和山鼠草，完全跳过了日常原料。",al={"伍特在调制什么","伍特想要的稀有草药","伍特使用了什么试剂"}},{q="伍特学到教训了吗？",a="在品尝了药剂并了解了其朴素的配方后，伍特惊讶于普通植物竟然能调制出这样的药水。他虚心地承认耶尔玛克是对的，并决定更加关注他之前忽视的日常植物。",al={"伍特改变主意了吗","伍特对药剂的反应","伍特的急躁的结果"}}},fp="16,161,17.283.0,18.341.0,13.140.0,14.131.0,49.165.0,46.106.0,50.130.0,28.213.0"}
P.entries["quest:97277"] = {n="Grund and Gozwin",s="Grund and Gozwin讲述了西北部雪山营地的一次伏击事件，一名矮人和一名侏儒遭到了雪豹的袭击。虽然侏儒在伙伴的猎枪掩护下幸存了下来，但他珍贵的戈兹温的机械日志却在混乱中遗失了。冒险者们被派往山中取回这些精密的笔记，并除掉那只潜伏的野兽。",h="Grund and...",kw={"矮人","侏儒工程师","gozwin","grund","机械陆行鸟","机械日志","潜行雪豹"},ang={["profession:Engineering"]="Gozwin因丢失戈兹温的机械日志而产生的焦虑，体现了工匠们对于机械陆行鸟的设计和专有笔记是多么看重。",["race:Dwarf"]="Grund迅速的猎枪反应和坚定的篝火情谊，体现了矮人在与侏儒盟友结伴旅行时所展现出的坚定忠诚。",["race:Gnome"]="Gozwin体现了典型的侏儒工匠形象，在从凶猛的捕食者袭击中幸存下来后，他的第一反应是担心自己的机械陆行鸟蓝图的安全。"},sec={{t="篝火旁的伏击",b="当矮人Grund和他的侏儒伙伴Gozwin在雪山中旅行时，他们在晚上搭起了营地。就在Grund转过身准备在火上烤野猪肉时，一只潜行雪豹从灌木丛中猛扑出来，咬住了Gozwin。Grund反应迅速，拿起他那把可靠的猎枪向野兽头顶上方开了一枪，这只捕食者受惊之下丢下侏儒，逃入了寒冷的岩壁之中。"},{t="工匠遗失的作品",b="虽然Gozwin从猫科动物的利齿下逃脱，身上只有深浅不一的抓痕而没有致命伤，但他们的营地已被彻底搅乱。在撤退的混乱中，Gozwin弄丢了他珍贵的戈兹温的机械日志——一本包含他机械陆行鸟关键蓝图的技术笔记本。这名饱受惊吓的侏儒因为担心自己的工程秘密被别人发现而焦急万分，直到一位冒险者同意前往西北部的山中寻回他的日志并除掉那只潜行的捕食者，他才得以安心。"}},faq={{q="Grund和Gozwin是谁？",a="Grund是一名使用猎枪的矮人露营者，Gozwin是他的侏儒工程师伙伴。当他们在雪山中扎营准备烤野猪肉时，他们遭到了潜行雪豹的伏击，导致Gozwin受伤，装备散落一地。",al={"grund和gozwin是谁","grund gozwin"}},{q="是什么袭击了营地里的Gozwin？",a="当Grund正在准备晚餐时，一只凶猛的潜行雪豹从背后伏击了Gozwin。这只野兽咬住了侏儒，正试图把他拖走，Grund开了一记警告射击，吓跑了这只猫科动物。",al={"什么袭击了gozwin","谁袭击了gozwin"}},{q="为什么戈兹温的机械日志对他如此重要？",a="戈兹温的机械日志包含了关于他机械陆行鸟的重要技术蓝图和笔记。Gozwin担心如果其他人得到了他的私人工程笔记，他的项目就会彻底毁了。",al={"为什么日志很重要","gozwin的机械日志"}},{q="Gozwin在袭击中伤得有多重？",a="是的，多亏了Grund迅速开出的那一枪，Gozwin在伏击中幸存了下来。他虽然带着深层的抓痕和严重的惊吓，但在Grund的照料下正在安全地恢复。",al={"gozwin还好吗","gozwin幸存了吗"}},{q="Grund和Gozwin的营地在哪里？",a="这对伙伴的营地坐落在西北部的山中。冒险者们被派遣到该营地取回丢失的日志，并消灭潜伏在周围区域的雪豹捕食者。",al={"营地在哪里","grund的营地位置"}},{q="Grund准备的食物怎么了？",a="在Grund的枪声吓跑了潜行雪豹后，那只野兽又回到了被遗弃的营地，吃掉了Grund原本为晚餐准备的烤野猪肉。",al={"烤野猪肉怎么了","雪豹吃野猪"}}},fp="16,180,21.316.0,22.332.0,25.181.0,29.176.0,51.147.0,40.146.0,41.123.0,46.118.0"}
P.entries["quest:97279"] = {n="Wayward Weapons",s="Wayward Weapons是试炼谷的一项早期训练任务，由监工高内克发布。随着年轻的战士们源源不断地加入部落，武器装备变得愈发匮乏。为了证明纪律性并支持营地，新兵们必须搜寻灌木丛，找回那些能力不足的前任留下的装备。",h="Wayward Weapons是试炼谷的一项早期训练任务，由监工高内克发布。随着年轻的战士们源源不断地加入部落，武器装备变得愈发匮乏。为了证明纪律性并支持营地，新兵们必须搜寻灌木丛，找回那些能力不足的前任留下的装备。",kw={"杜隆塔尔","高内克","克赞·荆条","新兵","回收","大兽穴","训练武器","试炼谷"},ang={["class:Warrior"]="尊重武器是任何战士的基础。回收失败新兵丢弃的武器，在真正的战斗开始前就强调了纪律和自力更生的重要性。",["faction:Horde"]="部落在杜隆塔尔通过坚韧和足智多谋生存下来，即使是那些不称职的人丢弃的武器，他们也拒绝浪费。",["profession:Blacksmithing"]="在杜隆塔尔，每一块金属都很重要。帮助克赞回收损毁的装备，体现了铁匠回收铁料并将残破边缘重铸为可用战争工具的职责。"},sec={{t="为新血武装",b="试炼谷是新兵们在杜隆塔尔残酷的红色荒原中经受考验的熔炉。随着无数渴望为大酋长效忠的志士挺身而出，营地的武器库存已到了极限。武器匠克赞·荆条忙于应付需求，尤其是当早期的训练因未准备好的学员而变得致命或充满挫败感时。"},{t="足智多谋的考验",b="监工高内克将这种短缺转化为一项实际的考验。他不愿浪费金属，而是指引新到达的学员去回收那些失败的新兵在尘土中倒下或逃跑时丢弃的残破利刃和钝重训练武器。将这些回收的武器交给克赞，使铁匠能够修理并回火这些装备以供下一批学员使用，这同时也教导新学员：在部落中生存，既需要挥舞钢铁，也需要学会回收利用。"}},faq={{q="为什么地上会有这么多废弃的训练武器？",a="并非每一个踏入试炼谷的希望之星都拥有部落所要求的力量或决心。胆怯或粗心的新兵经常会在恐慌中丢下装备，或者倒在当地的野猪和蝎群面前，导致配发的武器散落在尘土中。",al={"为什么地上会有武器","杜隆塔尔废弃武器","失败新兵的武器"}},{q="克赞·荆条是谁？",a="克赞·荆条是驻守在试炼谷大兽穴内的驻地武器匠。他负责为新兵装备武器、修理受损的训练器材，并维护部落在新手谷地的军事物资。",al={"克赞·荆条背景故事","克赞是谁","武器匠克赞"}},{q="是谁发布了这个任务？",a="站在大兽穴外面的监工高内克分配了这个任务。他注视着到来的志士，评估他们的基本潜力，并派遣他们去处理试炼场周边的紧急需求。",al={"谁给予了失落的武器任务","高内克任务"}},{q="克赞会用这些回收的武器做什么？",a="克赞会修理、磨快并修复那些受损的练习武器。由于杜隆塔尔资源稀缺且不断有新兵涌入，回收的铁器和木材必须重新利用，以训练下一批学员。",al={"训练武器会怎样","克赞修理武器"}},{q="这个任务发生在什么地方？",a="它发生在试炼谷，这是一个位于杜隆塔尔南部的孤立峡谷，年轻的兽人和暗矛巨魔在这里开启他们作为部落战士的道路。",al={"试炼谷位置","失落的武器在哪里"}},{q="为什么部落不干脆锻造全新的武器？",a="杜隆塔尔是一片崎岖干旱的土地，容易获取的铁矿储备有限，年轻的部落承担不起浪费。回收落选者的练习用刃可以确保原始金属被保留给前线部队。",al={"为什么要回收武器","杜隆塔尔金属短缺"}}},fp="15,190,20.275.0,25.331.0,62.212.0,23.198.0,21.185.0,46.191.0,33.153.0,54.192.0"}
P.entries["quest:97281"] = {n="A Simmering Storm",s="当一名冒险者从枯水谷的鹰身人手中夺回一件名为 Dull Stormy Orb 的奇异放电圣物时，A Simmering Storm 便开始了。将这团旋转的微型风暴带给地精技师雷兹拉克，可以了解到鹰身人这些奇怪饰品的来历，并引起棘齿城那些富有进取心的打捞者们的兴趣。",h="当一名冒险者从枯水谷的鹰身人手中夺回一件名为 Dull Stormy Orb 的奇异放电圣物时，A Simmering Storm...",kw={"酝酿中的风暴","枯水谷","黯淡的风暴宝珠","杜隆塔尔","尘风","加兹鲁维","鹰身人","雷兹拉克"},ang={["class:Shaman"]="宝珠内包含的微型电风暴反映了原始元素的力量，尽管在这种简陋的容器中驾驭它，让人对鹰身人的手段产生了疑问。",["faction:Horde"]="在枯水谷附近协助地精雷兹拉克的部落冒险者，通过从威胁杜隆塔尔峡谷的敌对鹰身人手中回收的物品，帮助保护了神秘的魔法圣物。",["profession:Engineering"]="像雷兹拉克这样的修补匠和工程师天生就被那些带有不稳定电荷和内部翻腾雾气的奇物所吸引。"},sec={{t="尘土中的火花",b="在与盘踞在整个枯水谷的侵略性极强的 Dustwind 鹰身人交战时，旅行者可能会发现一件不同寻常的奇物：Dull Stormy Orb。虽然它的外表看起来暗淡磨损，但握住它时，能感受到一股原始电流持续不断的振动。在球体内部，黑色的雾气不停翻涌，并不时被内部产生的尖锐火花照亮。这是鹰身人通过奇怪的圣物操纵风暴魔法的铁证。"},{t="地精的好奇心",b="与其让这种不稳定的魔法留在野蛮的鹰身人利爪之中，不如直接将宝珠带给雷兹拉克。这位务实的地精技师驻扎在枯水谷入口处，他对这件奇怪的圣物产生了浓厚的兴趣，并指出它的发现让他想起了他在棘齿城的雇主——首席工程师加兹鲁维——曾给出的古老建议。无论鹰身人想用这股微型风暴酝酿什么，现在它都落入了地精的手中。"}},faq={{q="什么是 暗淡的风暴宝珠？",a="暗淡的风暴宝珠 是从杜隆塔尔的一只鹰身人身上回收的奇异魔法古玩。尽管外表暗淡，但它内部嗡嗡作响，带有微弱的电流、翻腾的黑雾和周期性的火花。",al={"什么是 暗淡的风暴宝珠","风暴宝珠","来自鹰身人的宝珠"}},{q="谁想要 暗淡的风暴宝珠？",a="这颗宝珠被带给了雷兹拉克，他是一位驻扎在杜隆塔尔枯水谷外的地精侦察兵，对奇异的古玩和有价值的打捞品有着敏锐的眼光。",al={"谁需要 暗淡的风暴宝珠","上交风暴宝珠","把宝珠带到哪里"}},{q="为什么鹰身人会有这颗宝珠？",a="其具体用途尚不清楚，但枯水谷的鹰身人显然是在利用这颗宝珠来引导或容纳电气和风暴元素能量。",al={"鹰身人用宝珠做什么","为什么鹰身人有风暴宝珠","鹰身人宝珠的用途"}},{q="雷兹拉克是谁？",a="雷兹拉克是在杜隆塔尔北部枯水谷附近工作的一名地精特工，隶属于热砂港，效命于棘齿城的首席工程师加兹鲁维。",al={"雷兹拉克是谁","杜隆塔尔的雷兹拉克","枯水谷附近的地精"}},{q="枯水谷在哪里？",a="枯水谷是杜隆塔尔北部的一个崎岖峡谷系统，到处是充满敌意的 尘风 鹰身人，它们骚扰旅行者，破坏当地的贸易和定居点。",al={"枯水谷在哪里","枯水谷位置","杜隆塔尔鹰身人峡谷"}},{q="雷兹拉克对这颗宝珠有什么看法？",a="看到宝珠后，雷兹拉克立刻想起了他的老板——首席工程师加兹鲁维——关于奇异且可能有利可图的怪物的教诲和评论。",al={"雷兹拉克关于加兹鲁维说了什么","雷兹拉克和加兹鲁维的关系"}}},fp="17,168,19.298.0,16.275.0,28.168.0,30.155.0,34.160.0,14.155.0,25.162.0,34.143.0"}
P.entries["quest:97282"] = {n="Stormy Potential",s="Stormy Potential是杜隆塔尔的一个任务，由枯水谷附近的哥布林雷兹拉克提供。雷兹拉克希望能保护他的贸易商队免受掠夺成性的鹰身人的侵害，因此他试图利用本地雷蜥强大的带电器官来为一颗耗尽能量的宝珠充能。",h="Stormy Potential是杜隆塔尔的一个任务，由枯水谷附近的哥布林雷兹拉克提供。雷兹拉克希望能保护他的贸易商队免受掠夺成性的鹰身人的侵害，因此他试图利用本地雷蜥强大的带电器官来为一颗耗尽能量的宝珠充能。",kw={"带电器官","枯水谷","杜隆塔尔","加兹鲁维","鹰身人","宝珠","雷兹拉克","风暴潜能","雷蜥"},ang={["faction:Horde"]="雷兹拉克的行动支持着部落在杜隆塔尔的立足点和交通往来，而来自枯水谷的掠夺成性的鹰身人威胁着这里的旅行者和补给商队。",["profession:Engineering"]="利用雷蜥体内不稳定的生物能量来激活休眠装置是典型的哥布林式发明，尽管其安全系数几乎为零。"},sec={{t="把握机会",b="在杜隆塔尔枯水谷的阴影附近，哥布林雷兹拉克发现自己面临两个问题：商队受到当地鹰身人的持续威胁，以及一颗完好无损但能量耗尽的魔法宝珠。雷兹拉克想起了棘齿城首席工程师加兹鲁维的实用建议——机会来临时要果断把握——于是他制定了一个雄心勃勃的计划，通过为这件休眠的装置充能来同时解决这两个问题。"},{t="驾驭风暴",b="为了恢复这颗干涸的宝珠，雷兹拉克需要一个强大且直接的原始电力来源。枯水谷以西的峡谷里栖息着雷蜥——这些生物以其能够产生和传导致命雷电的内脏器官而闻名。通过派遣冒险者去收集这些带电的器官，雷兹拉克希望安全地将它们不稳定的电流直接导入装置中，从而使他脆弱的补给货车在面对未来的鹰身人伏击时拥有强大的防御力。"}},faq={{q="谁提供了风暴潜能这个任务？",a="风暴潜能由驻扎在杜隆塔尔枯水谷附近的哥布林商人和技工雷兹拉克提供。他采纳了加兹鲁维关于把握机会的建议，试图利用当地野兽天然的带电特性来恢复一颗未充能的宝珠。",al={"谁提供风暴潜能","雷兹拉克在哪里","雷兹拉克任务提供者"}},{q="雷兹拉克想用这些器官为什么充能？",a="雷兹拉克拥有一颗完好无损但能量耗尽的宝珠。他希望利用雷蜥的带电器官将其重新充满能量，这样他就能保护他的商队免受该地区鹰身人的骚扰。",al={"雷兹拉克在为充能什么","为什么需要雷蜥器官","雷兹拉克的宝珠用途"}},{q="雷蜥在哪里可以找到？",a="雷蜥栖息在杜隆塔尔枯水谷附近，雷兹拉克所在位置以西的一个峡谷中。猎人们必须收集它们的带电器官并带回给雷兹拉克。",al={"在哪里寻找雷蜥","杜隆塔尔雷蜥位置","器官在哪里"}},{q="为什么收集雷蜥器官很危险？",a="尽管名字里带有“雷”，但雷蜥不仅仅是咆哮，它们还会释放危险的闪电。正如雷兹拉克所警告的那样，它们的电击往往会给大多数旅行者上一堂终生难忘的痛苦课程。",al={"为什么雷蜥有闪电","雷蜥会使用闪电吗"}},{q="雷兹拉克为什么害怕鹰身人？",a="雷兹拉克的商队遭到了盘踞在枯水谷的敌对鹰身人的伏击。他打算将这颗充能后的宝珠作为威慑手段或武器，让鹰身人在再次袭击他的货物前三思而后行。",al={"雷兹拉克为何需要防御","谁袭击了雷兹拉克","鹰身人袭击商队"}},{q="雷兹拉克与加兹鲁维有什么联系？",a="雷兹拉克视棘齿城的首席工程师加兹鲁维为经验丰富的导师和商业灵感来源。雷兹拉克在制定为宝珠充能的计划时，明确引用了加兹鲁维关于把握机会的商业哲学。",al={"加兹鲁维对雷兹拉克来说是谁","雷兹拉克加兹鲁维建议"}}},fp="16,171,19.284.0,20.331.0,37.253.0,48.158.0,36.141.0,45.155.0,33.159.0,39.160.0"}
P.entries["quest:97286"] = {n="Research Access",s="图书馆向你敞开大门，供你研习。你的行为表明你尊重知识。",h="图书馆向你敞开大门，供你研习。你的行为表明你尊重知识。",kw={"权限","知识","图书馆","研究权限","尊重","研习"},sec={{t="图书馆使用权限",b="你已获得在图书馆研习的权限。大门已向你敞开。"}},faq={{q="我为什么能进入图书馆？",a="你的行为表明你尊重知识，图书馆现已向你开放，供你研习。",al={"图书馆权限","图书馆为何开放","图书馆研习"}},{q="图书馆能为我提供什么？",a="图书馆向你开放，供你研习。",al={"图书馆有何用","研习权限","我能做什么"}},{q="我的行为表明了什么？",a="你的行为表明你尊重知识。",al={"尊重知识","为何获准","我证明了什么"}}},fp="15,87,14.82.0,28.83.0,31.35.0,25.42.0"}
P.entries["quest:97287"] = {n="Shrewd Negotiations",s="大法师沃迪恩·伍德格莱尔称赞了你对法师之城的渗透，并表示现在是时候进行一些谈判了。你需要将你获得的奥术微粒带给达拉然的大法师塞琳德拉。",h="大法师沃迪恩·伍德格莱尔称赞了你对法师之城的渗透，并表示现在是时候进行一些谈判了。你需要将你获得的奥术微粒带给达拉然的大法师塞琳德拉。",kw={"奥特兰克山脉","奥术微粒","大法师塞琳德拉","达拉然","肯瑞托","精明的谈判","沃迪恩·伍德格莱尔"},sec={{t="谈判之时",b="大法师沃迪恩·伍德格莱尔承认，在艾泽拉斯，没有任何地方在奥术知识方面能与肯瑞托相提并论，即使是他自己那些杰出的研究成果在他们古老的智慧面前也显得黯然失色。他认为现在是让部落进入这个排他性组织的时候了。你需要将你获得的微粒带给达拉然的大法师塞琳德拉，因为沃迪恩确信肯瑞托为了拿回它，什么代价都愿意付出。"}},faq={{q="是谁派你去和达拉然谈判的？",a="大法师沃迪恩·伍德格莱尔，他在你渗透了该城市后，想要采取更具谈判性的手段。",al={"谁发布谈判任务","沃迪恩·伍德格莱尔","谈判任务发布者"}},{q="你要去和谁交涉？",a="达拉然的大法师塞琳德拉。",al={"我该去找谁","塞琳德拉位置","塞琳德拉在哪里"}},{q="你有什么筹码？",a="你获得的奥术微粒。沃迪恩确信肯瑞托为了拿回它，什么代价都愿意付出。",al={"什么是奥术微粒","谈判筹码","奥术微粒"}},{q="为什么沃迪恩·伍德格莱尔想要和达拉然做交易？",a="沃迪恩承认在艾泽拉斯，没有地方在奥术知识方面能与肯瑞托相提并论，并认为现在是时候让部落获得进入他们这个排他性组织的权限了。",al={"为什么要与肯瑞托谈判","沃迪恩的动机","为什么要找达拉然"}}},fp="19,198,17.359.0,40.81.0,31.56.0,27.104.0,53.141.0"}
P.entries["quest:97288"] = {n="Unending Torment",s="Unending Torment始于一个奇怪的憎恶被击杀之时，由于缝合处反复撕裂，它的头颅随之滚落。这个遗物有着被多次切割又重新接上的痕迹，指向了被遗忘者首都内部蓄意进行的黑暗实验。将这个可怕的战利品带给幽暗城的大药剂师法拉尼尔，便能揭开其反复重组背后的扭曲幽默。",h="Unending...",kw={"憎恶头颅","憎恶","炼金房","黑暗女王","大药剂师法拉尼尔","皇家药剂师协会","希尔瓦娜斯·风行者","幽暗城","无尽的折磨"},ang={["faction:Horde"]="见证法拉尼尔接收头颅的部落冒险者，能够直接窥见他们幽暗城盟友那令人不安的行为。尽管这些手段行之有效，但被遗忘者无休止的复活和缝合血肉的方法，常常让那些更重荣誉的盟友感到不安。",["race:Undead"]="对于被遗忘者来说，这颗头颅展示了他们的女王希尔瓦娜斯·风行者那冷酷的幽默和不近人情的天性。它时刻提醒着人们黑暗女王的绝对权威以及皇家药剂师协会那阴森可怕的创造力。"},sec={{t="松动的缝合线",b="当那个高大的憎恶在战斗中最终倒下时，它的头颅猛然从肩膀上掉落。仔细观察会发现，它的颈部不仅仅是被切断过一次，而是被缝合、撕裂、又重新接上了无数次。随着每一次重建，缝合处变得越来越脆弱，以至于头颅几乎无法再固定在构装体的肩膀上。这种拙劣却持久的修补，即便对于亡灵构装体来说也是极不寻常的，这表明这个特定的憎恶经历了反复的毁灭与重组循环。任何检查遗骸的人很快就会意识到，普通的拾荒者无法解释这种工艺，只有幽暗城技术精湛的缝合师才能辨认出这个生物的起源。"},{t="黑暗女王的玩笑",b="将断头送到炼金房，便会呈现在皇家药剂师协会的领袖——大药剂师法拉尼尔面前。法拉尼尔对这个可怕的样本一点也不感到惊讶，他立刻认出了这张脸。他断定这种反复的重组并非死灵法术的意外失败，而是希尔瓦娜斯·风行者本人精心设计的一个残酷玩笑。至于究竟是什么冒犯或轻视让这个生物受到了如此永恒且令人屈辱的惩罚，只有黑暗女王和她的核心圈子知道。法拉尼尔并没有丢弃这个破损的遗物，而是欣然接受了这颗断头，并坚信皇家药剂师协会可以将它重新用于他们正在进行的炼金和死灵实验中。"}},faq={{q="什么是憎恶头颅？",a="憎恶头颅是某个独特构装体在被击败后掉落的断头。它的颈部留下了反复重新接上的伤疤，每一次重新连接都削弱了血肉和缝合线。它是该生物所遭受的一种怪异且循环往复的惩罚的证明，促使发现者将其带到幽暗城交给大药剂师法拉尼尔进行检查。",al={"憎恶头颅背景故事","什么是憎恶头颅","憎恶头颅任务物品"}},{q="为什么头颅被重新接上了那么多次？",a="这个生物的头颅被反复缝合回身体上，作为一种折磨的手段。据大药剂师法拉尼尔所说，这个生物的状态是希尔瓦娜斯·风行者精心策划的一个残酷玩笑。每当这个构装体倒下或失去头颅时，它就会被重新拼凑起来以继续服役或受折磨，导致颈部越来越脆弱，最终再次断裂。",al={"为什么重接头颅","为什么头颅被缝回去","无尽的折磨头颅缝合线"}},{q="大药剂师法拉尼尔是谁？",a="大药剂师法拉尼尔是皇家药剂师协会的负责人，驻扎在幽暗城的炼金房。在女王希尔瓦娜斯·风行者的授权下，法拉尼尔监督被遗忘者的药剂师们进行毒药、瘟疫和解剖改造的研究。他对黑暗女王的项目非常了解，这使他能够立即辨认出这个缝合头颅的起源。",al={"法拉尼尔是谁","大药剂师法拉尼尔背景故事","法拉尼尔幽暗城"}},{q="为什么希尔瓦娜斯认为这是一个残酷的玩笑？",a="虽然法拉尼尔没有详细说明这个生物原本的身份，但他认为这个构装体无休止的死亡与重组循环是黑暗女王的一个美妙玩笑。强迫一个生物忍受反复的毁灭，仅仅是为了让它被拙劣地复活并一次又一次地缝合回去，这体现了希尔瓦娜斯对敌人那冷酷无情的讽刺和惩罚方式。",al={"希尔瓦娜斯的玩笑","为什么是黑暗女王的玩笑","黑暗女王的残酷玩笑"}},{q="法拉尼尔会用这个头颅做什么？",a="在收到这颗破损的头颅后，法拉尼尔带着阴森的笑意表示他有用处。作为皇家药剂师协会怪诞实验的监督者，他经常将死灵残骸、血肉和生物畸变体重新用于开发新的配方、瘟疫和构装体强化装置，以协助被遗忘者在不断的冲突中获益。",al={"头颅会怎样","法拉尼尔的用途","药剂师们会用它做什么"}},{q="在哪里提交无尽的折磨任务？",a="通过将憎恶头颅直接带给大药剂师法拉尼尔即可完成任务。他居住在幽暗城南区的炼金侧翼——炼金房。被遗忘者冒险者和部落盟友可以在那里找到他，他正被沸腾的大锅、助手和实验体包围着，监督着协会的研究工作。",al={"无尽的折磨在哪里交","无尽的折磨任务上交","谁收走憎恶头颅"}},{q="联盟玩家可以完成这个任务吗？",a="由于任务目标要求将任务物品直接交给幽暗城炼金房内的大药剂师法拉尼尔，因此该任务专为部落冒险者设计。任何试图接近法拉尼尔的联盟玩家在进入他们的地下据点时，都会面临敌对的幽暗城卫兵，并会被被遗忘者处死。",al={"无尽的折磨是部落专属吗","联盟 无尽的折磨","联盟可以做无尽的折磨吗"}}},fp="16,224,14.544.0,20.519.1,28.279.0,47.183.0,34.337.0,45.303.0,36.253.0,48.218.0,40.281.0"}
P.entries["quest:97289"] = {n="Unending Torment",s="Unending Torment是一个幽暗城的任务，内容涉及复活大元帅奥斯玛尔·加里瑟斯的断头。被遗忘者试图通过准备一个缝合怪作为他的新躯体，来审讯这位曾经的联盟敌人。",h="Unending Torment是一个幽暗城的任务，内容涉及复活大元帅奥斯玛尔·加里瑟斯的断头。被遗忘者试图通过准备一个缝合怪作为他的新躯体，来审讯这位曾经的联盟敌人。",kw={"憎恶","被遗忘者","加里瑟斯","大元帅","男爵的徽记","奥斯玛尔","希尔瓦娜斯·风行者","幽暗城","无尽的折磨"},ang={["faction:Alliance"]="对大元帅加里瑟斯遗骸进行毛骨悚然的复活，展示了那些在洛丹伦对抗女妖之王的联盟领袖们将面临的惨痛命运。",["faction:Horde"]="在幽暗城协助皇家药剂师学会进行复活实验，展示了被遗忘者邪恶的技艺以及他们对曾经压迫者的复仇。",["race:Undead"]="对于被遗忘者来说，对大元帅加里瑟斯的遗骸进行实验，代表了因果报应，也是对希尔瓦娜斯·风行者征服洛丹伦的直接提醒。"},sec={{t="征服者的战利品",b="在幽暗城深处的地下实验室里，被遗忘者的从业者们用死者的遗骸缝合成了可怕的憎恶。然而，在无数保存完好的颅骨中，有一件遗物承载着非同寻常的历史怨恨：大元帅奥斯玛尔·加里瑟斯的断头。就是这位傲慢的指挥官，在死于黑暗女王之手前，曾率领联盟残部横跨洛丹伦。"},{t="墓穴的秘密",b="被遗忘者保留加里瑟斯的头颅不仅仅是为了作为战争的战利品。通过准备一具拼凑而成的憎恶躯体作为新的宿主，被遗忘者的死灵法师们意图审讯这位前大元帅，并揭开锁在他断头内的联盟秘密。当头颅被带到那具毫无生气的构造体前，拼凑而成的憎恶便涌现出痛苦的知觉，在无尽的折磨中重温其恐怖的最后时刻。"}},faq={{q="奥斯玛尔是谁？",a="奥斯玛尔指的是大元帅奥斯玛尔·加里瑟斯，他是一位臭名昭著的军事指挥官，在第三次战争后率领着洛丹伦的联盟残部。他仇视非人类种族，大药剂师法拉尼尔说，黑暗女王很乐意亲手解决他。",al={"谁是奥斯玛尔","奥斯玛尔的身份","奥斯玛尔是谁"}},{q="为什么被遗忘者要复活奥斯玛尔的遗骸？",a="被遗忘者希望从他带进坟墓的秘密中挖掘出有价值的信息。通过将他保存完好的头颅放置在准备好的憎恶宿主附近，被遗忘者可以直接从复活的遗骸中提取信息。",al={"为什么要复活奥斯玛尔","复活头颅的目的","奥斯玛尔的秘密"}},{q="奥斯玛尔是怎么死的？",a="大药剂师法拉尼尔说，黑暗女王希尔瓦娜斯·风行者很乐意亲手解决大元帅加里瑟斯。",al={"谁杀了奥斯玛尔","奥斯玛尔是怎么死的","奥斯玛尔之死"}},{q="为什么任务物品叫“男爵的徽记”？",a="“男爵”是洛丹伦废墟中那具高大憎恶的名字，这颗头颅正是属于它的。法拉尼尔透露，这颗头颅曾经属于大元帅加里瑟斯。",al={"男爵的徽记奥斯玛尔","为什么叫男爵的徽记"}},{q="奥斯玛尔的新身体在哪里？",a="那具为了接收奥斯玛尔的头颅而建造的无头憎恶被保存在幽暗城内的一间相连的房间里，等待着被遗忘者的从业者们进行复活。",al={"奥斯玛尔的身体在哪里","憎恶位置幽暗城"}},{q="当构造体苏醒时会发生什么？",a="当被放置在拼凑好的构造体附近时，缝合的血肉会剧烈地抽搐并复活。在恢复意识后，遗骸会立刻因为重温加里瑟斯生前最后时刻的恐怖而陷入恐慌。",al={"身体苏醒时会发生什么","完成任务后的反应奥斯玛尔"}}},fp="16,179,20.297.0,20.320.1,15.239.0,50.182.0,19.132.0,51.144.0,35.155.0,40.179.0"}
P.entries["quest:97290"] = {n="Unending Torment",s="Unending Torment 是一项代表幽暗城皇家药剂师学会执行的任务。一位特使面对着一名拒绝合作的挑衅囚犯或目标，对方称请求者为憎恶。将这种抗命行为报告给大药剂师法拉尼尔后，他感到满意而非失望，因为这位药剂师领袖乐于见到折磨顽固目标的机会。",h="Unending Torment...",kw={"憎恶","炼金房","法拉尼尔","被遗忘者","大药剂师法拉尼尔","皇家药剂师学会","幽暗城","无尽的折磨"},ang={["faction:Horde"]="在洛丹伦活动的部落勇士经常观察到他们被遗忘者盟友身上那令人胆寒的冷酷。法拉尼尔在折磨顽固囚犯时流露出的愉悦，突显了幽暗城内部运作的黑暗实用主义。",["race:Undead"]="被遗忘者冒险者对于被活物称为憎恶早已习以为常。协助大药剂师法拉尼尔巩固了他们对皇家药剂师学会冷酷工作的承诺。"},sec={{t="阴影中的抗命",b="皇家药剂师学会经常与试验品、囚犯和怀有对被遗忘者深深仇恨的敌对实体打交道。在 Unending Torment 中，调查员会遇到一个不合作的个体，对方公开蔑视请求者，称他们为憎恶并坚决拒绝提供任何帮助。该目标绝望的抗命行为突显了许多活物或囚犯对洛丹伦亡灵所抱有的纯粹厌恶与敌意。"},{t="法拉尼尔的野心",b="将囚犯的拒绝报告给幽暗城的大药剂师法拉尼尔会产生意想不到的反应。这位皇家药剂师学会的首领并没有对缺乏进展感到沮丧，反而以一种邪恶的热情欢迎这种反抗。对法拉尼尔来说，一个坚决不从的目标并不是审讯的失败，而是一个引人入胜的挑战——这正好为在药剂师区内施行的残忍独创性和实验方法提供了机会。"}},faq={{q="什么是 无尽的折磨？",a="无尽的折磨 是与皇家药剂师学会相关的一项任务。冒险者会审讯或调查一名拒绝提供任何帮助并辱骂他们为憎恶的不合作囚犯或实体。冒险者随后必须将此失败的消息传达给幽暗城内的大药剂师法拉尼尔。",al={"无尽的折磨 任务","什么是 无尽的折磨","无尽的折磨 背景故事"}},{q="谁给予了 无尽的折磨 任务？",a="该任务始于与一名拒绝任何合作的挑衅目标互动后，对方在咒骂玩家为憎恶并将其驱赶走之后开始。在最初的交谈中，该囚犯并未透露姓名，指示受挫的冒险者将发现带回皇家药剂师学会的领导层。",al={"谁开启 无尽的折磨","无尽的折磨 任务给予者","在哪领取 无尽的折磨"}},{q="大药剂师法拉尼尔是谁？",a="大药剂师法拉尼尔是皇家药剂师学会的首领，基地位于洛丹伦废墟下方的幽暗城药剂师区。他监管着被遗忘者的炼金术士和研究人员，开发新的瘟疫、药剂和毒药，以保卫被遗忘者并铲除艾泽拉斯各地的敌人。",al={"法拉尼尔是谁","大药剂师法拉尼尔","大药剂师法拉尼尔的角色"}},{q="为什么说话者称玩家为憎恶？",a="囚犯对亡灵及其代理人怀有深切的厌恶，这是活物和被遗忘者的敌人中的普遍情绪。斥责访客为憎恶反映了局外人对如今居住在幽暗城的复活亡者所感到的深层偏见与恐惧。",al={"为什么是憎恶","谁称你为憎恶","为什么囚犯很生气"}},{q="完成任务后必须向哪里汇报？",a="必须直接向幽暗城的大药剂师法拉尼尔交付来自不合作目标的调查结果。法拉尼尔居住在药剂师区的深处，周围环绕着沸腾的坩埚、实验室大桶以及致力于为希尔瓦娜斯·风行者女王和被遗忘者制造致命药剂的研究同僚。",al={"在哪里上交 无尽的折磨","无尽的折磨 交付","向谁汇报 无尽的折磨"}},{q="大药剂师法拉尼尔对目标的抗命有何反应？",a="大药剂师法拉尼尔对该目标顽固拒绝合作的态度感到非常满意。他并没有因为僵局而感到愤怒，反而将其视为一项有趣的挑战。这位药剂师首领热衷于使用皇家药剂师学会开创的冷酷无情的方法来测试那些棘手目标的极限。",al={"法拉尼尔的反应","法拉尼尔说了什么","法拉尼尔会生气吗"}}},fp="16,165,23.236.0,19.258.0,25.241.0,37.198.0,34.290.0,52.188.0,48.222.0,68.219.0"}
P.entries["quest:97291"] = {n="Unending Torment",s="Unending Torment是幽暗城的一个任务，大药剂师法拉尼尔试图将一个拼凑而成的俘虏束缚在黑暗女王的意志之下。为了完成这种奴役药剂，冒险者必须从被遗忘者的首都各处收集致命的试剂。",h="Unending Torment是幽暗城的一个任务，大药剂师法拉尼尔试图将一个拼凑而成的俘虏束缚在黑暗女王的意志之下。为了完成这种奴役药剂，冒险者必须从被遗忘者的首都各处收集致命的试剂。",kw={"炼金房","水疱草","苦楚精华","法拉尼尔","大药剂师法拉尼尔","塔文·格瑞斯特","剧毒黄芩","幽暗城","无尽折磨"},ang={["class:Rogue"]="该任务需要冒险进入潜行者区购买苦楚精华，这是一种通常受毒药制造者和刺客青睐的强效试剂。",["faction:Horde"]="皇家药剂师学会在洛丹伦废墟深处继续酿造邪恶的药剂，测试炼金术奴役的极限。",["profession:Herbalism"]="从炼金房的草药训练师那里获取Blisterweed，突显了标准植物学研究与学会更黑暗的炼金项目之间的重叠。",["race:Undead"]="对于被遗忘者来说，通过炼金折磨将复活的尸骸束缚在黑暗女王的麾下，是炼金房日常运作中的标准做法。"},sec={{t="束缚意志",b="在幽暗城炼金房的深处，大药剂师法拉尼尔监督着旨在增强被遗忘者力量的恐怖实验。在成功重新接上了一个饱受摧残的俘虏的断头后，法拉尼尔需要一种特殊的炼金混合物，以粉碎这个生物残存的一点反抗意志，并将其永久地束缚在希尔瓦娜斯·风行者的意志之下。"},{t="药剂试剂",b="为了准备他的奴役药水，法拉尼尔派遣代理人穿过幽暗城去收集强效成分。这项任务包括从贸易区的塔文·格瑞斯特处获得Toxic Skullcap，从欠他债的附近草药训练师那里索取Blisterweed，并从潜伏在潜行者区的毒药商那里购买苦楚精华。"},{t="杰作",b="在收到这些成分后，法拉尼尔对他即将完成的杰作表示阴森的满意。他很期待将这种药剂在他们的“尊贵客人”身上进行测试，并确信这种痛苦的药水将剥去俘虏残存的虚张声势，使这个迷途的生物顺从地回到黑暗女王的麾下。"}},faq={{q="谁发布了无尽的折磨任务？",a="该任务由皇家药剂师学会的领袖、大药剂师法拉尼尔发布，可以在幽暗城的炼金房找到他。",al={"谁发布了无尽的折磨","无尽的折磨任务发布者","无尽的折磨起始"}},{q="法拉尼尔的药剂需要什么试剂？",a="大药剂师法拉尼尔需要三种特定的成分：从贸易区的塔文·格瑞斯特处获得的毒性黄芩，从炼金房的草药训练师附近获得的水疱草，以及从潜行者区的毒药商处获得的苦楚精华。",al={"有什么成分","无尽的折磨物品","法拉尼尔需要什么试剂"}},{q="大药剂师法拉尼尔正在对谁进行实验？",a="实验对象是一个不情愿的俘虏，他的断头刚刚被重新接上。法拉尼尔嘲弄地称他为“迷途的羔羊”和“尊贵的客人”，试图粉碎他在遭受毒打后依然坚持的反抗虚张声势。",al={"这个野兽是谁","法拉尼尔提到的迷途羔羊是谁","谁在遭受折磨"}},{q="法拉尼尔的药水目的是什么？",a="这种药水旨在从精神上摧毁实验对象，并强行将其束缚在被遗忘者的黑暗女王希尔瓦娜斯·风行者的意志之下。法拉尼尔认为该生物遭受重创的状态使其特别容易受到化学控制。",al={"为什么要制作这种药水","无尽的折磨药水的目的","这种药剂有什么作用"}},{q="玩家可以在哪里找到塔文·格瑞斯特？",a="塔文·格瑞斯特位于幽暗城的贸易区，她提供包括药剂师所需的毒性黄芩在内的特种商品。",al={"塔文·格瑞斯特在哪里","剧毒黄芩商人","找到格瑞斯特女士"}},{q="水疱草在哪里？",a="水疱草位于幽暗城的草药训练师艾雷斯塔一家附近，他们居住在炼金房内。法拉尼尔提到他们欠他一个人情，允许冒险者自由拿取所需之物。",al={"在哪里找到水疱草","奥列斯塔草药学","幽暗城草药训练师水疱草"}}},fp="16,175,16.305.0,19.289.0,15.316.1,38.134.0,51.224.0,51.231.0,38.142.0,38.138.0,33.171.0"}
P.entries["quest:97292"] = {n="Unending Torment",s="Unending Torment 是幽暗城的一项任务，由位于药剂师区的大药剂师法拉尼尔委派。玩家需要协助皇家药剂师学会，将腐蚀性的嘶嘶药剂倒入悬挂在 Othmar 残骸上方的滴注装置中。这项任务是对过去针对黑暗女王所犯罪行的持久报复。",h="Unending Torment 是幽暗城的一项任务，由位于药剂师区的大药剂师法拉尼尔委派。玩家需要协助皇家药剂师学会，将腐蚀性的嘶嘶药剂倒入悬挂在 Othmar...",kw={"炼金房","黑暗女王","加里索斯","嘶嘶药剂","大药剂师法拉尼尔","奥特马尔","幽暗城","无尽折磨"},ang={["faction:Horde"]="在幽暗城协助法拉尼尔，展现了被遗忘者对待那些背叛他们与女妖之王的敌人们时所采用的严酷手段。",["race:Undead"]="大药剂师法拉尼尔领导着幽暗城的皇家药剂师学会，而惩罚像加里索斯这样黑暗女王的敌人，是被遗忘者报复行动的核心。"},sec={{t="药剂师的报复",b="在幽暗城药剂师区阴暗的走廊里，大药剂师法拉尼尔正在进行严酷的实验，以确保被遗忘者的敌人永远无法安宁。为了这项任务，法拉尼尔准备了一种被称为嘶嘶药剂的腐蚀性物质，旨在无休止地滴落在悬挂于炼金设备下的受试者身上。"},{t="加里索斯的命运",b="法拉尼尔实验装置的受试者正是 Othmar，也就是大元帅加里索斯的残骸。由于他曾对黑暗女王犯下罪行，法拉尼尔认为持续的化学折磨是他应得的惩罚。药剂被导入 Othmar 躯体上方的悬挂框架中，持续灼烧他的血肉，确保这位陨落的指挥官成为承受永恒惩罚与研究的对象。"}},faq={{q="奥瑟玛尔 是谁？",a="奥瑟玛尔 指的是大元帅 奥瑟玛尔·加里瑟斯，他曾是人类指挥官。在收复洛丹伦期间，他曾与希尔瓦娜斯·风行者达成过不稳固的盟约，随后却背叛了被遗忘者并被其所杀。大药剂师法拉尼尔获得了他的残骸，以便对他进行持续的折磨与实验。",al={"奥瑟玛 是谁","奥瑟玛 是什么","奥瑟玛·加里瑟斯"}},{q="为什么 奥瑟玛尔 要受折磨？",a="奥瑟玛尔·加里瑟斯 曾与希尔瓦娜斯·风行者并肩作战，从恐惧魔王手中夺回了洛丹伦王都，但他对非人类种族怀有深深的蔑视，并试图完全为人类收复洛丹伦。被遗忘者认为他应对针对黑暗女王的罪行负责，视这种无休止的化学折磨为对他傲慢与过去行径的恰当报复。",al={"为什么要折磨 奥瑟玛","奥瑟玛 做了什么","针对希尔瓦娜斯的罪行"}},{q="谁是大药剂师法拉尼尔？",a="大药剂师法拉尼尔是幽暗城药剂师区皇家药剂师学会的负责人。他负责监督新型药剂、毒素和瘟疫的研发，并直接指挥这项针对 奥瑟玛尔 的行动。",al={"法拉尼尔的角色","谁给予 无尽的折磨 任务","大药剂师法拉尼尔"}},{q="嘶嘶药剂有什么作用？",a="嘶嘶药剂是大药剂师法拉尼尔调配的一种炼金混合物，旨在灼烧血肉并引发剧痛。药剂会被滴入悬挂在 奥瑟玛尔 躯体上方的滴注装置中。",al={"什么是嘶嘶药剂","药剂的效果","法拉尼尔的药剂"}},{q="奥瑟玛尔 是活着的还是亡灵？",a="奥瑟玛尔 是亡灵。加里索斯是被黑暗女王亲自杀死的，他的头颅已被缝合到一个抽搐着重获生机的憎恶躯体上。法拉尼尔称他为“新客人”，并计划让他继续在滴注药剂的折磨下受苦。",al={"奥瑟玛 是死是活","加里索斯还活着吗","奥瑟玛 的状态"}},{q="法拉尼尔接下来打算怎么处置 奥瑟玛尔？",a="大药剂师法拉尼尔打算让 奥瑟玛尔 的血肉继续在滴注装置下灼烧，同时严密监视他。法拉尼尔表示他对 奥瑟玛尔 的未来有详尽的计划，打算利用这个可怜虫进行持续的实验和报复。",al={"法拉尼尔未来的计划","接下来 奥瑟玛 会怎样","奥瑟玛 的未来"}}},fp="16,237,22.247.0,20.274.1,14.280.0,30.290.0,34.193.0,31.175.0,26.236.0,47.226.0"}
P.entries["quest:973"] = {n="奥萨拉克斯之塔",s="此任务是奥萨拉克斯之塔调查任务线的第五章，指引联盟的冒险者从黑海岸向南进入灰谷。净化者德尔格伦派遣你去击败居住在被腐蚀的火痕神殿中的兽人术士伊克鲁德·玛格苏尔，并取回他的奥术之书。",h="此任务是奥萨拉克斯之塔调查任务线的第五章，指引联盟的冒险者从黑海岸向南进入灰谷。净化者德尔格伦派遣你去击败居住在被腐蚀的火痕神殿中的兽人术士伊克鲁德·玛格苏尔，并取回他的奥术之书。",kw={"奥萨拉克斯","灰谷","德尔格伦","火痕神殿","伊克鲁德","迈斯特拉","玛格苏尔","书籍","术士"},ang={["class:Paladin"]="与净化者德尔格伦并肩作战，击败邪能召唤师并没收腐化的书籍，体现了圣光对抗恶魔腐化的经典使命。",["class:Warlock"]="对抗伊克鲁德·玛格苏尔意味着你要与一位黑暗技艺的同道者交锋，他会使用召唤的魅魔和虚空行者来守护他的邪恶文献。",["faction:Alliance"]="此项任务将联盟的冒险者带出安全的黑海岸，深入灰谷被恶魔污染的角落，以清除日益增长的黑暗威胁。",["race:NightElf"]="火痕神殿代表了对灰谷古老森林的一种卑劣亵渎，铲除伊克鲁德成为了保卫神圣祖地的一项使命。"},sec={{t="深入灰谷的狩猎",b="沿着在黑海岸奥萨拉克斯之塔发现的黑暗邪教活动线索，神圣战士净化者德尔格伦认出了一个危险施法者的签名：兽人术士伊克鲁德·玛格苏尔。伊克鲁德盘踞在灰谷西南部被称为火痕神殿的恶魔枯萎之地，他的阴暗交易威胁着要将邪恶魔法扩散到纯净的精灵林地。德尔格伦指派你去击杀术士并夺取他的魔法书，以揭露他主子的计划。"},{t="术士的巢穴",b="火痕神殿是一处布满恶魔奴仆的邪能伤痕遗迹。神殿沿其岩石斜坡矗立着险恶的红色柱子，伊克鲁德与他召唤的魅魔以及守护神殿的邪能杀手就栖息于此。在他的邪能领地中心击败这名兽人，就能让德尔格伦从伊克鲁德的书中搜寻到与奥萨拉克斯之塔发生的险恶仪式相关的黑暗知识和指令。"}},faq={{q="谁是净化者德尔格伦？",a="净化者德尔格伦是一位驻扎在迈斯特拉岗哨的联盟勇士，这是位于黑海岸与灰谷交界处的一个暗夜精灵哨所。他负责指挥针对该地区恶魔腐化和邪教徒的行动。",al={"德尔格伦","德尔格伦剧情","任务起始人"}},{q="谁是伊克鲁德·玛格苏尔？",a="伊克鲁德·玛格苏尔是一位强大的兽人术士，他在灰谷西南部的火痕神殿筑巢。虽然德尔格伦最初认为他只是个小麻烦，但由于他与奥萨拉克斯之塔的黑暗仪式有关联，他成为了一个关键目标。",al={"伊克鲁德","谁是伊克鲁德·玛格苏尔","灰谷兽人术士"}},{q="火痕神殿位于何处？",a="该神殿位于灰谷西南部，艾森娜神殿以南，阿斯特兰纳以西。这是一个被腐蚀、被恶魔侵扰的飞地，两侧有两根独特的红色柱子，通向伊克鲁德的祭坛。",al={"火痕神殿位置","伊克鲁德在哪里","如何到达伊克鲁德处"}},{q="为什么德尔格伦需要伊克鲁德·玛格苏尔之书？",a="伊克鲁德的书里记载了他的黑暗仪式和通讯信息。德尔格伦旨在破译这些文字，以揭开将这位兽人术士与徘徊在奥萨拉克斯之塔周围的邪教徒联系在一起的险恶阴谋。",al={"为什么需要书籍","伊克鲁德之书的内容","书籍的作用"}},{q="这个任务是如何将黑海岸与灰谷连接起来的？",a="故事线始于对黑海岸北岸奥萨拉克斯之塔的调查。随着谜团加深，邪教徒的网络引导冒险者穿过黑海岸，深入到饱受争夺的灰谷森林。",al={"从黑海岸到灰谷的任务","奥萨拉克斯之塔任务链关联"}},{q="取回那本书后会发生什么？",a="德尔格伦会查阅书中的内容，以推断奥萨拉克斯之塔的邪教徒身影背后的更深层阴谋，从而引出任务链的最终对抗。",al={"下一个任务","奥萨拉克斯之塔5后续"}}},fp="22,205,21.347.0,18.253.1,28.204.0,24.236.0,38.193.0,46.176.0,51.193.0,39.154.0"}
P.entries["quest:97326"] = {n="Rocks to Rests",s="“Rocks to Rests”是为Thra执行的一个轻松跑腿任务。Thra是一位兽人幼童，正在奥格瑞玛的索尔的堡垒后方与朋友们玩游戏。孩子们需要一位冒险者的力量，将圆滑的巨石搬运到他们的空地上，用作临时的座椅和桌子。这个任务为玩家提供了一个迷人的视角，一窥在部落首都长大的年轻一代的日常生活和游戏。",h="“Rocks to...",kw={"杜隆塔尔","索尔的堡垒","兽人","奥格瑞玛","让岩石安息","圆滑的巨石","桌面游戏","瑟拉"},ang={["faction:Horde"]="花时间在大酋长的据点后方帮助年轻的兽人，这表明即使在一个崇尚武力的社会中，奥格瑞玛的社区和日常生活也同样重要。",["race:Orc"]="在索尔的堡垒后方自创游戏的兽人幼童，反映了在杜隆塔尔中心地带成长起来的下一代的日常成长环境。"},sec={{t="奥格瑞玛的一处静谧角落",b="在奥格瑞玛索尔的堡垒后方的一片泥土地上，一群年轻的兽人聚在这里，远离了要塞卫兵严厉的目光。这片空地提供了充足的开阔地带供他们摆放微型人偶，但这里没有任何像样的家具，使得孩子们只能直接坐在尘土中玩耍。"},{t="临时家具",b="发现路过的冒险者后，一个名叫Thra的幼童请求帮助，希望能搬运八块中等大小、圆滑的巨石到他们的游戏场地。多亏了巨石平坦的侧面，这些沉重的石头成了坚固的临时座椅和低矮的桌子，让孩子们可以舒适地摆弄他们的游戏，而不必坐在尘土中。"}},faq={{q="谁发布了“岩石变座椅”任务？",a="瑟拉是一个年轻的兽人，正在奥格瑞玛索尔的堡垒后方的空地上与朋友们玩游戏。瑟拉观察敏锐且生性活泼，请求路过的冒险者伸出援“手”，以改善他们的游戏区。",al={"谁发布了搬石作凳","瑟拉 奥格瑞玛","瑟拉是谁"}},{q="这个任务发生在哪里？",a="该任务发生在索尔的堡垒后方的空地上，此处位于奥格瑞玛智慧谷内，是萨尔大酋长的所在地。孩子们聚集在这片远离要塞繁忙交通的相对清净的泥土地上。",al={"搬石作凳在哪里","瑟拉的位置","索尔的堡垒后方在哪里"}},{q="为什么瑟拉需要圆滑的巨石？",a="瑟拉和其他孩子需要圆滑的中型岩石来充当临时座椅和桌子。没有家具，他们在摆放和进行微型游戏时只能直接坐在地上。",al={"为什么需要石头","圆滑的巨石有什么用","为什么是巨石"}},{q="在索尔的堡垒后方玩什么游戏？",a="瑟拉和同伴们正在进行一种非正式的桌面游戏，他们在地上铺开了许多小人偶。圆滑的巨石提供了稳定的表面，让他们在玩游戏时可以放置人偶并舒适地就座。",al={"他们在玩什么游戏","瑟拉 游戏 奥格瑞玛","索尔的堡垒后方的人偶"}},{q="“岩石变座椅”涉及战斗吗？",a="不，“岩石变座椅”是一个简单、和平的跑腿任务，而非军事行动或战斗考验。它完全依赖蛮力将沉重的巨石搬回孩子们玩耍的地方。",al={"搬石作凳危险吗","搬石作凳有战斗吗"}},{q="孩子们在巨石运到后会怎么做？",a="一旦八块圆滑的巨石送达，瑟拉和孩子们会将它们挪到泥土地上的相应位置，利用平坦的侧面为他们的桌面人偶制作座位和桌子。",al={"搬石作凳完成后会发生什么","瑟拉用石头做什么"}}},fp="14,127,27.214.0,19.223.0,35.178.0,33.204.0,35.171.0,47.202.0,37.145.0,57.176.0"}
P.entries["quest:97328"] = {n="Anything of Value",s="荆棘谷一艘坠毁的飞艇留下了货物遭到劫掠的痕迹。货物上撕破的标签仍指向藏宝海湾。",h="荆棘谷一艘坠毁的飞艇留下了货物遭到劫掠的痕迹。货物上撕破的标签仍指向藏宝海湾。",kw={"anything of value","藏宝海湾","坠毁","脚印","货物","被盗的补给物资","飞艇","zul'kunda"},sec={{t="撕破的标签",b="在荆棘谷，坠毁残骸中留有一批补给物资遭到劫掠的痕迹。货运标签被撕得粉碎，但其中一张仍能看见藏宝海湾的字样。双趾脚印和地上的凹痕通向西北方的祖昆达废墟。"}},faq={{q="这批货物出了什么事？",a="补给物资遭到劫掠，货运标签也被撕得粉碎。",al={"被盗的货物","飞艇货物","什么遭到劫掠"}},{q="脚印通向哪里？",a="脚印和地上的凹痕通向西北方的祖昆达废墟。",al={"双趾足迹","踪迹在哪里","脚印"}},{q="残存的标签上写着什么？",a="一张撕破的标签上仍能看见藏宝海湾的字样。",al={"藏宝海湾标签","撕破的货运标签","原本运往哪里"}},{q="谁需要找回的货物？",a="这些货物要归还给藏宝海湾的某个人。",al={"谁要这些货物","送到哪里","归还货物"}}},fp="17,128,12.249.0,30.69.0,30.78.0,34.47.0,34.57.0"}
P.entries["quest:97331"] = {n="Zimmix's Great Escape",s="Zimmix Sputterspark请求你护送他离开祖昆达废墟。他担心巨魔会再次抓住他，并希望藏宝海湾的码头管理员罗兹基尔得知他获救的消息。",h="Zimmix Sputterspark请求你护送他离开祖昆达废墟。他担心巨魔会再次抓住他，并希望藏宝海湾的码头管理员罗兹基尔得知他获救的消息。",kw={"藏宝海湾","大逃亡","钥匙","祖昆达废墟","巨魔","码头管理员罗兹基尔","zimmix","zimmix sputterspark"},sec={{t="地精的请求",b="在祖昆达废墟，Zimmix Sputterspark请求你在他离开时替他望风。他说自己曾被巨魔抓住，担心他们会再次抓住他。你已经削弱了巨魔的力量，足以取得他需要的钥匙。如今，Zimmix希望你帮他逃往安全之地，而藏宝海湾的码头管理员罗兹基尔正等着听到他获救的消息。"}},faq={{q="Zimmix是谁？",a="Zimmix Sputterspark是一名地精，他请求你护送他离开祖昆达废墟。",al={"zimmix","zimmix是谁","zimmix sputterspark"}},{q="Zimmix为什么需要护送？",a="Zimmix担心巨魔会再次抓住他，此前他们曾抓住过他。",al={"为什么护送zimmix","zimmix害怕","巨魔抓住了他"}},{q="你要护送Zimmix离开哪里？",a="你要护送Zimmix离开祖昆达废墟。",al={"zimmix在哪里","祖昆达","zimmix的位置"}},{q="应该把获救的消息告诉谁？",a="应该把Zimmix成功获救的消息告诉藏宝海湾的码头管理员罗兹基尔。",al={"告诉谁","罗兹基尔","报告获救消息"}},{q="Zimmix需要什么钥匙？",a="Zimmix说他需要一把钥匙，而你削弱了巨魔的力量，足以取得它。",al={"zimmix的钥匙","为什么要拿钥匙","给zimmix的钥匙"}}},fp="21,174,15.336.0,14.87.0,31.78.0,36.58.0,33.73.0,25.79.0"}
P.entries["quest:97386"] = {n="The Offense of Grom'gol",s="斥候发现东边洞穴里有食人魔后，指挥官阿格罗戈什请求你协助格罗姆高营地。营地已经遭受过他们的袭击，危险仍未解除。",h="斥候发现东边洞穴里有食人魔后，指挥官阿格罗戈什请求你协助格罗姆高营地。营地已经遭受过他们的袭击，危险仍未解除。",kw={"阿格罗戈什","营地","格罗姆高","mosh'ogg","食人魔","斥候"},sec={{t="斥候的报告",b="你协助格罗姆高营地抵御食人魔并击退附近的食人魔后，指挥官阿格罗戈什派出一名斥候寻找更多食人魔。斥候发现远东的一处洞穴里住着食人魔。阿格罗戈什请你袭击 Mosh'Ogg Ogre Mount，免得营地再受他们威胁。"}},faq={{q="谁请求帮助对付食人魔？",a="格罗姆高营地的指挥官阿格罗戈什请你处理食人魔。",al={"谁发布了任务","阿格罗戈什的请求"}},{q="斥候在哪里发现了食人魔？",a="斥候在远东的一个洞穴里发现了他们，那里就是 Mosh'Ogg Ogre Mount。",al={"食人魔洞穴在哪里","他们在哪里"}},{q="阿格罗戈什为何担心食人魔？",a="格罗姆高已经遭遇过附近的食人魔，而斥候又发现东边的洞穴里住着更多食人魔。",al={"为何与食人魔战斗","食人魔的威胁"}},{q="之前发生了什么？",a="斥候寻找更多食人魔之前，你曾协助保卫格罗姆高，并对附近的食人魔发起反击。",al={"前置步骤","格罗姆高的防御"}}},fp="23,177,16.292.0,36.75.0,35.75.0,44.97.0,26.94.0"}
P.entries["quest:97453"] = {n="Weed Whacked",s="Gemmil请你处理格罗姆高南面的Carnivorous Weeds。年轻的学徒采集植物时，它们吓到了Gemmil，如今营地的安全岌岌可危。",h="Gemmil请你处理格罗姆高南面的Carnivorous Weeds。年轻的学徒采集植物时，它们吓到了Gemmil，如今营地的安全岌岌可危。",kw={"炼金术士","carnivorous weeds","gemmil","格罗姆高","草药学","丛林","weed whacked"},ang={["profession:Herbalism"]="作为一名草药学学徒，你能理解Gemmil想要研究植物并成为炼金术士的愿望。"},sec={{t="受惊的学徒",b="Gemmil在丛林营地门外采集植物时，几株巨大的杂草突然出现，朝这位年轻学徒吐口水。Gemmil安然逃脱，但现在不能在营地外玩耍了。你需要确保格罗姆高南面的区域安全，然后去和Gemmil的母亲谈谈。"}},faq={{q="Gemmil是谁？",a="Gemmil是一名年轻的草药学学徒，希望将来成为炼金术士。",al={"gemmil是谁","谁是gemmil"}},{q="Gemmil遭遇了什么？",a="Gemmil在营地门外采集植物时，被几株会吐口水的巨大杂草吓到了。Gemmil安然逃脱。",al={"gemmil遭袭","杂草吐口水"}},{q="Carnivorous Weeds在哪里？",a="Carnivorous Weeds在格罗姆高南面。",al={"杂草位置","杂草在哪里"}},{q="Gemmil为什么不能在营地外玩耍？",a="那些杂草吓到Gemmil后，Gemmil的父母就不再让Gemmil在营地外玩耍了。",al={"gemmil不能玩耍","为何不能在外面玩"}},{q="确保区域安全后，你应该和谁谈谈？",a="确保格罗姆高南面的区域安全后，你需要告知Gemmil的母亲。",al={"告诉gemmil的母亲","gemmil的母亲"}}},fp="12,173,20.274.0,14.72.0,24.121.0,32.44.0,35.90.0,53.86.0"}
P.entries["quest:97485"] = {n="Traditions of the Bluff",s="Tauren的一项传统要求你从Hunter’s Rise抛撒熏香。这份供奉可以用来敬奉Earthmother、为狩猎祈福、庆祝某个时刻，或寻求指引。",h="Tauren的一项传统要求你从Hunter’s Rise抛撒熏香。这份供奉可以用来敬奉Earthmother、为狩猎祈福、庆祝某个时刻，或寻求指引。",kw={"先祖","雪松枝","仪式用燧石","earthmother","hunter’s rise","熏香","tauren传统","traditions of the bluff"},ang={["race:Tauren"]="身为Tauren，你遵循的这项传统可以用来祈求Earthmother庇佑，或向先祖寻求指引。"},sec={{t="随风飘散的熏香",b="Hunter’s Rise的一位Tauren请你遵循传统，将熏香撒向风中。你从指定的供应者那里收集草药、雪松枝、筋线，以及仪式用的燧石和火绒。在仪式场地，你将这些材料组合起来，再从朝南的悬崖上抛撒熏香。"},{t="不同的场合",b="抛撒熏香可以祈求Earthmother守护某人、赐福狩猎、纪念某个时刻，或向先祖寻求指引。这一举动饱含敬意，但不必遵循某一种固定的仪式。不同氏族遵循的传统步骤各不相同。"}},faq={{q="Hunter’s Rise有什么传统？",a="这项传统是从Hunter’s Rise朝南的悬崖上，将熏香撒向风中。",al={"熏香传统","抛撒熏香","悬崖熏香"}},{q="供奉熏香可以祈求什么？",a="可以祈求Earthmother守护某人、赐福狩猎、庆祝某个时刻，或请先祖给予指引。",al={"为何供奉熏香","熏香用途","赐福狩猎"}},{q="制作熏香需要什么？",a="材料包括草药、雪松枝、筋线，以及仪式用的燧石和火绒。",al={"熏香材料","所需材料","草药 雪松 筋线 燧石"}},{q="仪式场地在哪里？",a="仪式场地位于Hunter’s Rise朝南的悬崖上。",al={"抛撒熏香的地点","仪式场地位置","南面悬崖"}},{q="所有氏族遵循这项传统的方式都一样吗？",a="不一样。不同氏族遵循的传统步骤可能各不相同，这一举动也不受严格的仪式约束。",al={"不同氏族习俗","相同仪式","熏香步骤"}}},fp="23,155,20.290.0,14.259.0,41.96.0,37.124.0,35.85.0,29.68.0,49.101.0"}
P.entries["quest:97538"] = {n="Pigments for Paints",s="雷霆崖的塔·冬蹄需要一位旅行者前往石爪山脉，为他补充红色颜料。他所需的材料来自幽暗草，这是一种生长在暗色湖中的独特水生植物，其干燥后的幽暗草荚可以制成鲜艳的绯红色染料。",h="雷霆崖的塔·冬蹄需要一位旅行者前往石爪山脉，为他补充红色颜料。他所需的材料来自幽暗草，这是一种生长在暗色湖中的独特水生植物，其干燥后的幽暗草荚可以制成鲜艳的绯红色染料。",kw={"暗色湖","幽暗草","幽暗草荚","绘画颜料","红色颜料","石爪山脉","塔·冬蹄","雷霆崖"},ang={["faction:Horde"]="这个请求展示了牛头人主城雷霆崖与附近崎岖的石爪山脉山口之间日常的往来联系。",["profession:Herbalism"]="虽然暗色湖的水域十分危险，但原生的幽暗草证明了区域性水生植物除了作为常规草药之外，还能提供有用的材料和颜料。",["race:Tauren"]="塔·冬蹄代表了雷霆崖的工匠们，他们依赖卡利姆多各地的天然植物来生产传统的颜料和染料。"},sec={{t="工匠的需求",b="塔·冬蹄是雷霆崖高地城市里的一位年长牛头人工匠，在用光了红色颜料后，他的创作被迫停止了。由于年轻时四处游历的日子已经过去，这位画家只能指望体力充沛的旅行者前往北方的石爪山脉，为他补充颜料储备。"},{t="暗色湖的水域",b="塔·冬蹄那鲜艳绯红色的秘密隐藏在暗色湖的深处，那是一个位于石爪山脉山口的显眼圆形水域。幽暗草就潜生在这些水域中，这是一种独特的水生植物，其种荚在采摘并妥善干燥后，会变成一种鲜艳夺目的红色。通过收集三十个这样的草荚，旅行者可以为这位大师级工匠提供恢复工作所需的原材料。"}},faq={{q="谁发布了“制作颜料的色素”这个任务？",a="塔·冬蹄在雷霆崖发布了这个任务。作为一位年长的牛头人工匠，他早已过了四处奔波的年纪，因此他寻找那些腿脚更灵便的人代为收集原材料。",al={"谁发布了绘画用的颜料","颜料任务发布者","塔·冬蹄位置"}},{q="幽暗草荚在哪里可以找到？",a="幽暗草生长在暗色湖的水域中，这是一个位于石爪山脉山口中央的大型圆形湖泊。",al={"去哪里找幽暗草荚","幽暗草位置","暗色湖在哪里"}},{q="为什么塔·冬蹄需要幽暗草？",a="塔·冬蹄的艺术创作已经没有红色颜料可用了。幽暗草的草荚在干燥后会变成鲜艳的红色，这使它们成为他制作颜料的理想天然染料。",al={"为什么要收集幽暗草","幽暗草有什么用","为什么是红色颜料"}},{q="需要多少个幽暗草荚？",a="塔·冬蹄需要30个直接从暗色湖水域中收集的幽暗草荚，以补充他的红色颜料储备。",al={"需要多少草荚","幽暗草数量"}},{q="什么是幽暗草？",a="幽暗草是一种生长在石爪山脉暗色湖中的独特水生植物。它的主要特征是其草荚干燥后会变成深红色颜料。",al={"幽暗草是什么植物","幽暗草详情"}},{q="塔·冬蹄在哪里？",a="塔·冬蹄居住在莫高雷的雷霆崖高地城市上，他在那里从事手工艺创作并制作传统的颜料。",al={"塔·冬蹄在哪里","雷霆崖的塔·冬蹄"}}},fp="19,175,17.239.0,24.243.0,40.144.0,30.116.0,38.119.0,34.92.0,17.118.0,32.130.0"}
P.entries["quest:97539"] = {n="Silky Sutures",s="“Silky Sutures”是阿拉希高地的一项部落任务，由落锤镇前哨站的格里高利·维克托医生提供。由于一直未修复的攻城战损和日渐匮乏的医疗物资，这位营地驻地医师对现状感到沮丧，他招募冒险者去采集有毒的高地蜘蛛丝，用作紧急野战缝合线。这项任务突显了落锤镇守军所面临的绝望而物资匮乏的处境，他们正竭尽全力让守卫和劳工保持战斗力。",h="“Silky...",kw={"阿拉希高地","格里高利·维克托医生","野战缝合","落锤镇","医务室","丝质缝线","蜘蛛丝","医用蛛丝"},ang={["faction:Horde"]="落锤镇是部落在阿拉希高地的一个关键据点，因此维克托医生为保持守卫者健康并随时准备战斗所做的努力，对于该阵营在这一地区的生存至关重要。",["race:Undead"]="格里高利·维克托医生将一种被遗忘者特有的务实且不带个人情感的医疗专业知识带到了落锤镇，利用高地上的临时资源来维持诊所的运作。"},sec={{t="摇摇欲坠的前哨站",b="落锤镇在崎岖的阿拉希高地苦苦支撑，但这座营地显露出长期压力下的可见痕迹。未修复的攻城战损遍布外围，这让当地医师格里高利·维克托医生苦涩地感叹，疏于管理似乎已成了官方方针。尽管防御工事摇摇欲坠，且缺乏广泛的支持，维克托拒绝让腐朽侵蚀他的医务室。维持一家运作正常的诊所对于让劳工和哨兵守卫保持站立并随时准备战斗至关重要。"},{t="临时医疗物资",b="物资的减少让落锤镇的医务室濒临耗尽，迫使维克托医生转向战场应急方案。当传统的绷带和缝合线稀缺时，从高地蜘蛛身上采集到的坚韧且富有弹性的蛛丝可以被拧成出人意料的强韧野战缝合线。虽然维克托冷淡地打趣说，感染风险对于受伤士兵来说是最小的忧虑，但采集这些蛛丝确实为医务室提供了在敌对领地补救伤员所需的关键器材。"},{t="落锤镇的苦涩幽默",b="在被围困的情况下经营一线诊所需要坚毅的性格，而格里高利·维克托医生充分展现了这一点。他用关于严峻预后和蜘蛛丝缝合的讽刺笑话来迎接旅行者，以此掩盖落锤镇被孤立的严酷现实。高地上的常规援助依然罕见，因此任何来自过往勇士的帮助对于维持诊所至关重要。通过临时补救措施和顽强的反抗，维克托确保了落锤镇的伤员能够得到照顾，即使他们身处的哨站看起来已被遗弃而任其腐朽。"}},faq={{q="格里高利·维克托医生是谁？",a="格里高利·维克托医生是阿拉希高地落锤镇医务室的驻地医疗官兼创伤外科医生。他拥有尖刻的机智，对待战场分诊有着务实的态度，不懈地治疗着受伤的守卫和劳工。尽管整个哨站面临严重的物资短缺和未修复的攻城战损，维克托仍决心防止医务室因被忽视而荒废。",al={"谁是维克托","格里高利·维克托背景故事","落锤镇医生"}},{q="为什么维克托医生需要蜘蛛丝？",a="落锤镇的医务室几乎完全耗尽了标准的医疗物资和器材。在极端的战场压力下，维克托医生只能依靠应急手段，将结实的高地蜘蛛丝捻成有效的医用缝合线，用来缝合裂伤和创口。在缺乏正规临床缝合线的情况下，这些蜘蛛丝提供了足以将撕裂的皮肉缝合在一起的耐用线材。",al={"为什么需要蜘蛛丝","医用蛛丝的用途","蜘蛛丝缝合线"}},{q="这个任务期间落锤镇处于什么状况？",a="落锤镇处于一种肉眼可见的荒废和物理破败状态。旧的攻城战损在营地的防御工事上依然未得到任何修复，这让维克托医生认为行政上的漠视已成了官方方针。该基地缺乏持续的外部援助和补给，使得驻守的卫兵、劳工和医务人员不得不自谋生路。",al={"落锤镇现状","为什么落锤镇会受损","落锤镇的状况"}},{q="这个任务中的蜘蛛来自哪里？",a="这些蜘蛛潜伏在落锤镇营地周边的阿拉希高地荒野中。冒险者冒险走出哨站围墙，必须在高地平原上猎杀这些充满侵略性的蛛形纲生物，以采集维克托医生进行野战缝合所需的医用蛛丝，然后安全返回诊所。",al={"阿拉希蜘蛛","在哪里寻找蛛丝","医用蛛丝位置"}},{q="为什么维克托医生会讽刺感染问题？",a="当把收集到的蜘蛛丝交给他时，维克托医生开玩笑说，对于正在缝合伤口的受伤士兵来说，一点感染根本算不了什么。这种黑色幽默反映了落锤镇前线分诊的残酷现实：在战场上，防止严重失血和致命创伤比追求无菌的临床环境更为优先。",al={"医生的幽默感","蜘蛛丝与感染","维克托的玩笑"}},{q="为什么落锤镇的物资如此匮乏？",a="落锤镇坐落在阿拉希高地内一个充满争议且与世隔绝的位置，四周环绕着敌对威胁，且与稳定的补给线隔绝。外部的增援和物流补给很少抵达，这使得该哨站的驻军和医务室不得不长期忍受原材料、工具和基本治疗用品的短缺。",al={"为什么没有补给","落锤镇物资短缺","落锤镇缺乏援助"}},{q="落锤镇的医务室治疗哪些人？",a="医务室直接归格里高利·维克托医生管理，负责治疗驻扎在落锤镇的劳工和卫兵。由于该哨站不断承受着来自高地危险和结构性损伤的压力，维护这些守卫者的身体健康对于保持该定居点的防御能力和运作功能至关重要。",al={"维克托治疗谁","落锤镇伤员","诊所患者"}}},fp="13,181,21.353.0,26.364.0,27.407.0,29.245.0,40.200.0,50.227.0,46.198.0,47.257.0,41.226.0,43.198.0"}
P.entries["quest:97558"] = {n="Hides for the Forsaken",s="在提瑞斯法林地，被遗忘者的亡灵生存环境十分严峻，他们必须收集兽皮来替换腐烂的血肉。舍伦尼·洛巴尔特指派冒险者收集Darkhound毛皮、夜行蝙蝠翼膜和邪鳍鱼人皮，以修补受损的躯体。",h="在提瑞斯法林地，被遗忘者的亡灵生存环境十分严峻，他们必须收集兽皮来替换腐烂的血肉。舍伦尼·洛巴尔特指派冒险者收集Darkhound毛皮、夜行蝙蝠翼膜和邪鳍鱼人皮，以修补受损的躯体。",kw={"黑暗犬毛皮","夜行蝙蝠翼","被遗忘者的兽皮","舍伦尼·洛巴尔特","提瑞斯法林地","亡灵移植","邪鳍鱼人"},ang={["profession:Tailoring"]="被遗忘者的裁缝技艺通常与殡葬学有所重叠，他们使用缝合技巧不仅是为了制作服装，更是为了将未处理的野兽膜层固定在腐烂的骨架上。",["race:Undead"]="这鲜明地提醒着人们被遗忘者所承受的现实负担，他们的生存需要手动维护和搜寻移植组织，而不是自然愈合。"},sec={{t="亡灵的代价",b="被遗忘者的血肉无法自然愈合。身体受到的创伤会留下无法通过正常生理方式再生的腐烂空洞。为了维持形态并保持尸体功能正常，被遗忘者必须从生者的世界获取有机材料，并将替代组织缝合在伤口上。"},{t="特殊材料",b="并非所有的毛皮都有相同的解剖学用途。厚实的Darkhound毛皮可以提供耐用性，用于大面积、稳固的修补。精致的夜行蝙蝠翼膜轻盈柔软，足以覆盖脸部和手指，而不会产生僵硬、笨拙的层次。与此同时，收集柔软的邪鳍鱼人皮是为了内衬内部膜层和敏感区域，例如口腔内壁。"}},faq={{q="被遗忘者为什么要动物皮？",a="亡灵的皮肤在受损后不会自然愈合或再生。为了在身体受伤后继续存在并延缓外部腐烂，被遗忘者会采集活体生物的皮肤和膜层，缝补在他们受伤的躯体上。",al={"被遗忘者为何需要毛皮","亡灵愈合背景知识","亡灵会自愈吗"}},{q="舍伦尼·洛巴尔特是谁？",a="舍伦尼·洛巴尔特是提瑞斯法林地的一名被遗忘者制皮师。她收集各种毛皮和生物材料，以确保受损的被遗忘者有足够的资源来修补他们腐烂的躯体。",al={"舍伦尼·洛巴尔特","舍伦尼是谁"}},{q="为什么特别需要夜行蝙蝠翼膜？",a="与沉重的毛皮相比，夜行蝙蝠翼膜异常薄且柔软。这种轻盈的特性使其成为覆盖敏感和复杂解剖部位（如面部特征和手指）的理想选择，避免移植的皮肤变得过于厚重或僵硬。",al={"夜行蝙蝠翼的用途","为什么要用夜行蝙蝠翼膜"}},{q="鱼人皮有什么用？",a="邪鳍鱼人皮具有独特的湿润度和柔韧性，非常适合用作内部膜层或脆弱的粘膜表面，例如脸颊内部和口腔。",al={"为什么用鱼人皮","鱼人皮与亡灵"}},{q="这些材料在哪里可以找到？",a="这三种生物都在提瑞斯法林地那令人不安的土地上徘徊。黑暗犬和夜行蝙蝠潜伏在树林和路边，而邪鳍鱼人则在北部海岸和内陆水道筑巢。",al={"到哪里获取毛皮","提瑞斯法林地的野兽"}},{q="使用动物皮对被遗忘者来说很常见吗？",a="是的。从动物和搜寻到的遗骸中获取组织是被遗忘者日常生存的基础。如果没有可替换的血肉和毛皮，未愈合的伤口会将底层的骨骼、器官和肌肉完全暴露在外界环境中。",al={"所有被遗忘者都会用毛皮吗","被遗忘者的血肉构造"}}},fp="22,159,20.196.0,21.301.0,38.139.0,23.147.0,51.140.0,29.108.0,32.196.0,46.166.0"}
P.entries["quest:97583"] = {n="WRIGGLE.",s="WRIGGLE. 是一场与一只极其兴奋的年轻软泥怪的邂逅，它热爱跳舞，直到耗尽所有精力。为了复苏并与这只生物成为朋友，冒险者必须从幽暗城的运河中取回一批特殊的营养丰富的泥浆怪淤泥。",h="WRIGGLE.",kw={"运河","兴奋的软泥怪","营养丰富的泥浆怪淤泥","软泥怪","淤泥","幽暗城","蠕动"},ang={["faction:Horde"]="获取这种特殊的淤泥需要冒险进入被遗忘者的首都幽暗城的运河，与当地商人进行交易。",["race:Undead"]="被遗忘者非常习惯于幽暗城运河网络中流动的有毒径流和活体软泥怪，因此让软泥怪成为同伴再合适不过了。"},sec={{t="跳舞的软泥怪",b="WRIGGLE. 涉及与一只活泼、兴奋的小软泥怪互动，它喜欢模仿友好旅行者的舞蹈动作。尽管热情高涨，但跳舞很快会耗尽这只小软泥怪的体力，使它变得疲惫，需要补充养分来恢复精力。"},{t="来自运河的养分",b="为了让疲惫不堪的生物恢复活力，冒险者必须寻找营养丰富的泥浆怪淤泥，这是一种在幽暗城恶臭的运河中出售的特殊混合物。在吸收了这种它钟爱的污秽佳肴后，精力充沛的软泥怪会急切地与提供者建立羁绊，准备跟随它的新朋友。"}},faq={{q="什么是 蠕动.？",a="蠕动. 是一场遭遇战，冒险者通过跳舞与一只兴奋的小软泥怪结为朋友，却发现这只生物需要专门的养分来维持它的精力。",al={"扭动 任务","什么是 扭动","软泥怪跳舞任务"}},{q="去哪里寻找营养丰富的泥浆怪淤泥？",a="营养丰富的泥浆怪淤泥由幽暗城运河内的一位商人出售，在那里炼金废料和径流随处可见。",al={"哪里获取淤泥","营养丰富的泥浆怪淤泥商人","喂食幽暗城软泥怪"}},{q="如果软泥怪看起来累了，该如何引起它的注意？",a="如果这只兴奋的软泥怪变得疲惫或分心，与它共舞可以吸引它的注意力，并模仿它顽皮的动作。",al={"如何引起软泥怪注意","疲惫的软泥怪","唤醒软泥怪 扭动"}},{q="为什么软泥怪以淤泥为食？",a="软泥怪吸收周围的炼金淤泥和泥浆来维持自身并恢复活力，在消耗体力后进行恢复。",al={"为什么软泥怪吃淤泥","软泥怪吃什么"}},{q="喂食软泥怪后会发生什么？",a="在用它偏爱的淤泥喂养后，恢复活力的软泥怪会与冒险者建立羁绊，并试图跟随他们。",al={"软泥怪会跟随你吗","软泥怪同伴","扭动 奖励"}},{q="联盟玩家能轻易获得这些淤泥吗？",a="由于获得必要的营养丰富的泥浆怪淤泥需要前往幽暗城运河中的商人处，联盟旅行者会发现进入被遗忘者之城极其危险。",al={"联盟可以完成 扭动 吗","联盟软泥怪淤泥"}}},fp="8,133,15.156.0,26.198.0,17.107.0,42.107.0,57.80.0,34.103.0,35.92.0,46.118.0"}
P.entries["quest:976"] = {n="奥伯丁的补给品",s="“运往奥伯丁的补给”是一个护送任务，联盟的冒险者需要保护费罗·艾隆汉，护送他带着关键的补给品和信件，从迈斯特拉岗哨向北前往黑海岸。鉴于奥萨拉克斯之塔散发的威胁日益加剧，以及灰谷中潜伏着充满敌意的渗透者，这条道路的安全无法得到保障。",h="“运往奥伯丁的补给”是一个护送任务，联盟的冒险者需要保护费罗·艾隆汉，护送他带着关键的补给品和信件，从迈斯特拉岗哨向北前往黑海岸。鉴于奥萨拉克斯之塔散发的威胁日益加剧，以及灰谷中潜伏着充满敌意的渗透者，这条道路的安全无法...",kw={"灰谷","奥伯丁","怨恨者巴利扎尔","黑海岸","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨","哨兵星风","奥萨拉克斯之塔"},ang={["faction:Alliance"]="守护这条走廊确保了灰谷的前哨站能与奥伯丁的后勤枢纽保持联系，维护了联盟在卡利姆多北部脆弱的据点。",["race:Human"]="费罗·艾隆汉代表了人类愿意深入陌生且危险的古老森林，去支持卡多雷盟友的意愿。",["race:NightElf"]="运往北方的补给和公文直接帮助了奥伯丁的哨兵们，使她们能够应对横跨黑海岸和灰谷边境日益增长的黑暗。"},sec={{t="险象环生的北上之路",b="迈斯特拉岗哨坐落在灰谷的西侧前线，这是一个宁静的前哨站，夹在丛林中狂野的紧张局势和黑海岸动荡的土地之间。在调查了围绕奥萨拉克斯之塔的邪恶活动后，净化者德尔格伦收集了重要的补给品和情报，准备送往奥伯丁的哨兵星风处。为了不让信使孤身犯险，前哨站决定指派武装护卫，陪同费罗·艾隆汉踏上穿越林间道路的旅程。"},{t="小径阴影",b="旅途揭示了道路周边的荒野处境是多么危险。费罗的路线遭到了一连串协调一致的伏击。暗滩邪教徒试图封锁任何有关其恶魔仪式的消息，被遗忘者斥候在林地灌木丛中潜伏，而像怨恨者巴利扎尔、折磨者阿里加和恶毒的凯达卡尔这样凶残的指挥官，都试图在商队抵达边境前将其歼灭。"}},faq={{q="费罗·艾隆汉是谁？",a="费罗·艾隆汉是一名驻扎在灰谷西部的迈斯特拉岗哨的人类信使。他受净化者德尔格伦之托，携带重要信件和后勤物资前往奥伯丁。他非常谨慎，如果没有得力的保镖随行，他拒绝踏上旅程。",al={"费罗","费罗·艾隆汉背景故事","护送的矮人是谁"}},{q="为什么奥伯丁需要这些补给？",a="黑海岸和灰谷北部正面临日益严重的腐化，以及从奥萨拉克斯之塔活动的恶魔邪教徒所带来的威胁。驻扎在奥伯丁的暗夜精灵哨兵们，在哨兵星风等当地人物的领导下，需要新鲜的补给和最新的情报，以维持对海岸线的防御。",al={"为什么要运送补给到奥伯丁","奥伯丁补给","哨兵星风"}},{q="是谁在路上袭击了费罗？",a="费罗警告说森林里到处都是危险的敌人，并请求派人保护。在护送过程中，袭击者的身份将会被揭露。",al={"谁伏击了费罗","费罗的伏击者","谁在路上发动攻击"}},{q="这与奥萨拉克斯之塔有什么联系？",a="净化者德尔格伦一直在策划旨在揭露并破坏奥萨拉克斯之塔邪教徒黑暗仪式的行动。这次护送正是该调查工作的一部分，旨在确保情报和关键支持能送达奥伯丁的暗夜精灵领导层手中。",al={"奥萨拉克斯之塔关联","奥萨拉克斯之塔","德尔格伦关联"}},{q="护送费罗完成后我该向谁汇报？",a="在确保费罗安全通过灰谷的伏击区后，你需要回到迈斯特拉岗哨向净化者德尔格伦汇报，确认任务顺利完成。",al={"交还奥伯丁补给任务","护送费罗后去哪里","任务交付"}}},fp="21,199,21.359.0,23.343.1,22.201.0,39.255.0,33.117.0,49.232.0,41.145.0"}
P.entries["quest:97663"] = {n="Supplies and Studies",s="在卡加斯，Mus'hale请你找回被盗的补给，并拓下漫尘盆地中刻有雕纹的石头。那些拓印是Mus'hale失去的研究资料，附近的食人魔袭击时将它们夺走了。",h="在卡加斯，Mus'hale请你找回被盗的补给，并拓下漫尘盆地中刻有雕纹的石头。那些拓印是Mus'hale失去的研究资料，附近的食人魔袭击时将它们夺走了。",kw={"漫尘盆地","卡加斯","mus'hale","食人魔","拓印","被盗的补给","石刻雕纹"},sec={{t="遗失的资料",b="附近的食人魔在漫尘盆地抓住了学者Mus'hale，他如今正在卡加斯旅店休养。遭袭前，Mus'hale发现了刻有雕纹的奇特石头，并拓下印记供研究。如今行囊和拓印都不见了，因此请你到东边搜寻，并重新拓下石刻上的印记。"}},faq={{q="Mus'hale是谁？",a="Mus'hale是一位学者，他在漫尘盆地发现了刻有雕纹的石头，并拓下印记供研究。",al={"mushale","谁是mus'hale","mus'hale的经历"}},{q="Mus'hale的补给怎么了？",a="附近的食人魔在漫尘盆地袭击了Mus'hale。他醒来时，旅店老板正在照料他，而行囊已经不见了。",al={"被盗的补给","mus'hale的行囊在哪里","食人魔抢走行囊"}},{q="Mus'hale要我找什么？",a="Mus'hale请你到东边寻找被盗的行囊，并拓下附近石刻上的印记。",al={"补给与研究任务","我要找什么","寻找拓印"}},{q="刻有雕纹的石头在哪里？",a="那些刻有雕纹的奇特石头位于漫尘盆地。",al={"漫尘盆地石刻","石头在哪里","石刻雕纹"}},{q="我该去哪里找Mus'hale？",a="Mus'hale在卡加斯，正在旅店老板的照料下休养。",al={"返回mus'hale处","mus'hale在哪里","卡加斯旅店"}}},fp="20,186,14.307.0,16.88.0,37.110.0,35.100.0,28.45.0,30.62.0"}
P.entries["quest:97884"] = {n="Armory of Sunnyglade",s="有人请你从河林的阳光林地找回一本锻造典籍。典籍的标题与 Tremayne 家族有关。",h="有人请你从河林的阳光林地找回一本锻造典籍。典籍的标题与 Tremayne 家族有关。",kw={"阳光林地军械库","锻造技艺","河林","阳光林地","典籍","tremayne 家族"},sec={{t="家族典籍",b="有人请你从河林的阳光林地找回一本介绍 Tremayne 家族锻造技艺的书。委托的重点是这本典籍；眼下要紧的是找到它在阳光林地的下落。"}},faq={{q="我要找什么？",a="你要找的是《Tremayne Family Blacksmithing Techniques》典籍。",al={"什么典籍","锻造书籍","tremayne 典籍"}},{q="典籍在哪里？",a="要在河林的阳光林地寻找这本典籍。",al={"在哪里找","阳光林地典籍","军械库位置"}},{q="Tremayne 家族是什么人？",a="标题表明，这些锻造技艺与 Tremayne 家族有关。",al={"tremayne 家族","tremayne 家族是谁"}}},fp="20,126,13.218.0,22.73.0,18.53.0,27.75.0"}
P.entries["quest:97891"] = {n="Prompt Potion Runner",s="“Prompt Potion Runner”是一项紧急的幽暗城运送任务，玩家必须穿过粘液运河，将一种不稳定的药剂争分夺秒地送到炼金房。该任务突显了亡灵躯体的孱弱以及被遗忘者炼金研究的挥发性。",h="“Prompt Potion Runner”是一项紧急的幽暗城运送任务，玩家必须穿过粘液运河，将一种不稳定的药剂争分夺秒地送到炼金房。该任务突显了亡灵躯体的孱弱以及被遗忘者炼金研究的挥发性。",kw={"亚历山德罗","炼金房","马丁·费尔本药剂师","及时送药","皇家药剂师学会","粘液运河","幽暗城","不稳定药剂"},ang={["faction:Horde"]="幽暗城是部落的关键枢纽，尽管旅行者必须穿过其有毒的粘液运河，协助被遗忘者完成他们危险的炼金事业。",["race:Undead"]="这次运送展示了被遗忘者不死状态下脆弱的生理现实，易碎的关节和腐朽的膝盖很容易导致皇家药剂师学会的重要实验室工作毁于一旦。"},sec={{t="与腐朽的赛跑",b="在幽暗城的地下走廊里，被遗忘者炼金师亚历山德罗急需一名迅捷的信使。他配制了一种极不稳定、保质期极短的药剂，由于他那脆弱的亡灵关节无法承受奔跑，他不敢冒险亲自带着药剂穿过城内的毒液运河。冒险者必须与时间赛跑，确保药剂在降解成无用的淤泥之前完好地送达。"},{t="炼金房的需求",b="目的地是炼金房，马丁·费尔本药剂师正焦急地等待着这份药剂以继续他的研究。费尔本透露，之前的六名信使或尝试都失败了，因为药剂在运输途中变得不稳定。及时的送达能让药剂师继续他那阴暗的实验，这既强调了皇家药剂师学会制剂的易挥发性，也展示了亡灵躯体的生理缺陷。"}},faq={{q="谁发布了这个任务？",a="该任务由幽暗城的亚历山德罗发布。他需要一名冒险者飞奔穿过粘液运河，因为他那腐朽的亡灵膝盖一跑就会脱臼并发出响声。",al={"谁发布了迅捷药水跑腿","谁开启了迅捷药水跑腿","谁是亚历山德罗"}},{q="药剂需要送到哪里？",a="药剂必须送给马丁·费尔本药剂师，他在幽暗城的炼金房进行炼金实验。",al={"要把药剂带到哪里","谁是马丁·费尔本药剂师","迅捷药水跑腿交任务"}},{q="为什么这次运送有时间限制？",a="这种制剂是一种不稳定的药剂，保质期极短。如果不尽快穿过运河送达，混合物就会变得不稳定并失去效用。",al={"为什么有时间限制","不稳定药剂的保质期","为什么要赶时间"}},{q="之前的运送尝试是否失败过？",a="马丁·费尔本药剂师指出，亚历山德罗之前尝试送出的六瓶药剂在到达炼金房之前就已在中途变得不稳定，因此你的成功送达是一次难得的胜利。",al={"是否有其他信使失败过","亚历山德罗过去的尝试","有多少瓶药剂失败了"}},{q="为什么亚历山德罗不能亲自送药？",a="亚历山德罗解释说，每当他试图奔跑时，他的膝盖就会发出嘎吱声并脱臼，这是亡灵身份带来的不幸生理副作用，导致他无法亲自赶去送药。",al={"为什么亚历山德罗不能自己去送","亚历山德罗的膝盖"}},{q="费尔本药剂师在进行什么实验？",a="马丁·费尔本是一位在炼金房进行实验的药剂师。虽然具体配方保密，但一旦稳定的混合物送达，他就会立即继续他的研究。",al={"费尔本药剂师的工作","药剂的用途是什么"}}},fp="20,141,20.272.0,26.371.0,21.164.0,33.115.0,26.136.0,36.129.0,48.139.0,37.179.0"}
P.entries["quest:97894"] = {n="Business in Auberdine",s="“Business in Auberdine”是暴风城的一位矮人商人博古斯·钢手发布的差事。博古斯请求前往西方的旅客顺道探望他的兄弟高尔博德，后者最近在暗夜精灵港口奥伯丁做起了生意。这项任务连接着人类首都繁忙的码头与卡利姆多北部迷雾缭绕的海岸。",h="“Business in...",kw={"奥伯丁","博古斯·钢手","奥伯丁的生意","黑海岸","高尔博德·钢手","商人","钢手","暴风城港口"},ang={["faction:Alliance"]="暴风城港口与奥伯丁之间的直接海上航线加强了人类王国与卡利姆多北部的卡多雷领地之间的贸易和军事联系。",["race:Dwarf"]="矮人的商业触角远及卡兹莫丹群山之外，像钢手这样的进取商人甚至在暗夜精灵宁静幽暗的定居点中也设立了摊位。"},sec={{t="背井离乡的矮人",b="钢手家族以头脑精明和交易公道而闻名，博古斯也总是以此为荣。他的兄弟高尔博德·钢手最近冒险横跨无尽之海，前往奥伯丁经营一个商铺。为停靠在黑海岸的船只提供补给看起来是一条致富捷径，但几周以来杳无音信，这让博古斯对远在铁炉堡和暴风城之外的兄弟的处境感到不安。"},{t="港口航线",b="从东部王国航行到卡利姆多那未受开发的荒野，过去需要通过米奈希尔港或藏宝海湾这类中立地精港口进行复杂的转运。博古斯指引旅客前往暴风城港口最南端的码头，那里有一艘船只，提供直达奥伯丁漫长木质码头的海上航线。"}},faq={{q="博古斯·钢手是谁？",a="博古斯·钢手是暴风城的一名矮人商人。他对自己家族诚实交易的声誉感到自豪，因此寻找路过的冒险者为他远在海外的兄弟高尔博德捎去口信。",al={"博古斯·钢手","谁发布了奥伯丁的生意","博古斯"}},{q="高尔博德·钢手在哪里？",a="高尔博德·钢手驻扎在奥伯丁，这是卡利姆多西北海岸黑海岸的主要港口定居点。他在那里经营着一家面向进出港船只的商铺。",al={"高尔博德在哪里","寻找高尔博德·钢手","高尔博德位置"}},{q="如何从暴风城前往奥伯丁？",a="一艘船直接从暴风城港口最南端的码头出发，运送乘客横跨无尽之海，直达黑海岸的奥伯丁码头。",al={"前往奥伯丁的船","如何从暴风城前往黑海岸","暴风城到奥伯丁的船"}},{q="为什么博古斯担心他的兄弟？",a="高尔博德几周前离开家乡前往奥伯丁的商铺，本指望靠补给航行船只赚上一大笔钱。然而他自离开后就再也没有寄回任何消息，这促使博古斯请求旅客前去调查。",al={"为什么要探望高尔博德","高尔博德发生了什么"}},{q="奥伯丁是什么样的定居点？",a="奥伯丁是一个主要由暗夜精灵建造和居住的沿海避风港。它位于黑海岸，是联盟连接卡利姆多北部与泰达希尔岛屿王国的主要航运枢纽和渡轮中转点。",al={"什么是奥伯丁","奥伯丁城镇"}},{q="钢手家族以什么闻名？",a="钢手家族是一个矮人商人家族，以经商、商铺经营以及无论对旅客还是码头工人都能提供公道交易而闻名。",al={"钢手家族","钢手"}}},fp="21,164,21.234.0,18.230.0,24.166.0,35.156.0,42.116.0,40.175.0,37.190.0,39.100.0"}
P.entries["quest:97899"] = {n="Camping 101: Alchemy",s="奥格瑞玛的炼金师可以学习制作供营地使用的法力之井。它能为治疗者和施法者提供提神的饮品，而搭建营地则需要一堆营火。",h="奥格瑞玛的炼金师可以学习制作供营地使用的法力之井。它能为治疗者和施法者提供提神的饮品，而搭建营地则需要一堆营火。",kw={"炼金师","炼金术","营火","露营","治疗者","法力之井","奥格瑞玛","施法者","伍特"},sec={{t="营地之井",b="当你展现出炼金术的本领后，奥格瑞玛有人会请你去找伍特谈谈。伍特可以教你制作法力之井，这种露营物品能吸引前来寻求补给的治疗者和施法者。要在荒野中搭建营地，你还需要一堆营火。烹饪训练师可以教你如何生火。"}},faq={{q="谁能教我制作法力之井？",a="当你展现出熟练的炼金术技艺后，奥格瑞玛的伍特就可以教你制作法力之井。",al={"法力之井训练师","伍特炼金术","伍特是谁"}},{q="法力之井有什么用？",a="法力之井是一种露营物品，能让治疗者和施法者品尝到清爽的滋味。",al={"法力之井用途","法力之井是什么","营地法力"}},{q="我能在城镇里搭建营地吗？",a="大多数人不喜欢有人在城镇中心搭建营地，因此任务完成文本会指引你前往荒野，试用你的法力之井。",al={"奥格瑞玛露营","法力之井城镇","城镇露营"}},{q="搭建营地还需要什么？",a="营地需要以一堆营火为基础。烹饪训练师可以教你如何生火。",al={"需要营火","搭建营地","营地生火"}}},fp="20,165,15.310.0,37.97.0,25.89.0,26.146.0,31.89.0"}
P.entries["quest:97900"] = {n="Camping 101: Blacksmithing",s="剃刀岭的杜克可以根据你的锻造技能，教你一门适合野营的手艺。磨刀石能让附近的战士磨砺武器。",h="剃刀岭的杜克可以根据你的锻造技能，教你一门适合野营的手艺。磨刀石能让附近的战士磨砺武器。",kw={"锻造","篝火","野营","杜克","剃刀岭","潜行者","磨刀石","武器"},ang={["class:Rogue"]="作为潜行者，只要营地架设了磨刀石，你就能在附近磨砺武器。",["profession:Blacksmithing"]="作为锻造师，你可以向杜克学习制作磨刀石，在野外营地使用。"},sec={{t="野营手艺",b="向杜克展示你的锻造技艺后，他会教你制作磨刀石。你可以在野外营地架设磨刀石，让附近的战士和潜行者磨砺武器。扎营需要篝火，厨师可以教你如何制作篝火。"}},faq={{q="谁教我制作磨刀石？",a="向杜克展示你的锻造技艺后，他会教你制作磨刀石。",al={"磨刀石训练师","杜克 锻造","谁教野营锻造"}},{q="磨刀石有什么用？",a="在你的营地，附近的战士和潜行者可以使用磨刀石磨砺武器。",al={"磨刀石用途","磨刀石有什么用","营地磨砺武器"}},{q="我可以在哪里试试扎营？",a="你得前往野外才能试试扎营；营地不该设在城镇中心。",al={"营地设在哪里","野营地点","在城镇扎营"}},{q="我需要篝火吗？",a="需要。扎营前必须先准备篝火，厨师可以教你如何制作篝火。",al={"需要篝火","如何扎营","野营用篝火"}}},fp="26,153,12.250.0,42.97.0,34.89.0,28.86.0,21.85.0"}
P.entries["quest:97901"] = {n="Camping 101: Enchanting",s="你可以制作附魔的鲁特琴，但镇民不喜欢在城镇中心扎营。要在野外扎营，必须生起篝火。",h="你可以制作附魔的鲁特琴，但镇民不喜欢在城镇中心扎营。要在野外扎营，必须生起篝火。",kw={"篝火","露营","烹饪","附魔的鲁特琴","火","野外"},ang={["profession:Cooking"]="作为一名厨师，你可以教别人如何生起篝火，为营地打好基础。"},sec={{t="先点起篝火",b="你可以用篝火作为营地的基础。大多数厨师都能教你怎么生火；如果你还没学过基础知识，就去找一位烹饪训练师。"}},faq={{q="我能制作什么？",a="你可以制作附魔的鲁特琴。",al={"附魔的鲁特琴","制作鲁特琴","露营鲁特琴"}},{q="我可以在哪里试试？",a="你得去野外试试，因为大多数人都不喜欢在城镇中心扎营。",al={"在哪里扎营","露营地点","试试鲁特琴"}},{q="为什么需要篝火？",a="篝火是营地的基础。",al={"需要篝火","篝火","露营篝火"}},{q="谁能教我生火？",a="大多数厨师都能教你生火。如果你还没学过基础知识，可以找一位烹饪训练师请教。",al={"学习生火","烹饪训练师","生起篝火"}}},fp="23,132,16.135.0,17.32.0,23.105.0,25.47.0,32.112.0"}
P.entries["quest:97902"] = {n="Camping 101: Engineering",s="一位老师指引你去剃刀岭找 Mukdrak。证明你的工程学技艺后，他就能教你制作试剂机器人。机器人能为营地补充施法所需的材料。",h="一位老师指引你去剃刀岭找 Mukdrak。证明你的工程学技艺后，他就能教你制作试剂机器人。机器人能为营地补充施法所需的材料。",kw={"营地","篝火","扎营入门","工程学","mukdrak","剃刀岭","试剂机器人"},ang={["profession:Engineering"]="作为一名工程师，证明你的工程学技艺后，就能学习制作试剂机器人，为营地提供帮助。"},sec={{t="营地机器助手",b="在剃刀岭找到 Mukdrak，证明你的工程学技艺后，就能向他学习制作试剂机器人。这台自动装置能为你和盟友补充施法所需的材料。想在营地试用它，就前往野外；镇民不欢迎有人在镇中心扎营。"},{t="备好篝火",b="扎营前也需要先备好篝火。大多数烹饪训练师都能教你制作篝火；如果你需要入门指导，可以找一位烹饪训练师。"}},faq={{q="谁能教我制作试剂机器人？",a="在剃刀岭找到 Mukdrak，证明你的工程学技艺后，他就能教你制作试剂机器人。",al={"mukdrak 机器人","谁教试剂机器人","试剂机器人训练师"}},{q="试剂机器人有什么用？",a="试剂机器人能为你和盟友补充施法所需的材料。",al={"机器人有什么用","试剂机器人用途","营地机器人"}},{q="我该在哪里扎营？",a="完成说明建议你前往野外试用机器人，因为大多数人不喜欢有人在镇中心扎营。",al={"营地地点","扎营地点","在哪里试用机器人"}},{q="扎营前还需要准备什么？",a="扎营前需要先备好篝火。大多数烹饪训练师都能教你制作篝火。",al={"需要篝火","扎营准备","营地篝火"}},{q="谁能教我制作篝火的基础知识？",a="烹饪训练师可以教你制作篝火的基础知识。",al={"篝火训练师","学习制作篝火","烹饪篝火"}}},fp="24,189,14.300.0,14.164.0,37.101.0,29.91.0,30.131.0,43.84.0,49.71.0"}
P.entries["quest:97903"] = {n="Camping 101: First Aid",s="Camping 101: 急救是一项指导性任务，旨在指引技术娴熟的旅行者前往剃刀岭寻找拉乌克，他会传授如何制作野外生存所需的急救包。该任务强调了旅途中自力更生的必要性，提醒冒险者们掌握篝火制作方法，并尊重当地定居点，选择在荒野中露营。",h="Camping 101...",kw={"篝火","露营101","杜隆塔尔","急救包","拉乌克","剃刀岭","生存","荒野营地"},ang={["faction:Horde"]="这项训练以杜隆塔尔的剃刀岭为基地，旨在为那些希望在卡利姆多崎岖边境上维持生存的部落旅行者提供帮助。",["profession:Cooking"]="露营技巧和烹饪技能相辅相成；拉乌克指出，搭建一个合适的营地需要熊熊燃烧的篝火，这是一项由烹饪训练师传授的基本技术。"},sec={{t="边境生存之道",b="在杜隆塔尔及更广阔的蛮荒之地生存，需要的不仅仅是纯粹的武力，更需要在旅途中自给自足。在剃刀岭，拉乌克为寻求制作必要野外装备的有能力的漫游者提供指导。通过Camping 101: 急救，那些已经证明自己具备基础能力的实践者可以学会组装专属的急救包，这让他们即便远离药剂师或医务所，也有手段包扎伤口、处理伤情。"},{t="篝火的艺术",b="搭建营地是一门遵循实用边境礼仪和需求的艺术。拉乌克告诫冒险者，在剃刀岭这样的定居点中心搭建帐篷是不受欢迎的，这意味着这些野外站点必须在开阔的荒野中进行测试。此外，没有熊熊燃烧的篝火来抵御夜晚的寒冷，任何营地都无法正常运作，因此，对于任何有志于露营的人来说，掌握烹饪艺术（即最初学习生火的地方）是一项至关重要的资产。"}},faq={{q="拉乌克是谁？他在哪里？",a="拉乌克位于杜隆塔尔的剃刀岭。他提供生存露营技巧的指导，教导已证明自身能力的实践者如何组装属于他们自己的急救包，以用于偏远地区的旅行。",al={"谁教授露营急救","拉乌克在哪里","露营 101训练师"}},{q="搭建野外营地前需要什么条件？",a="搭建营地需要开阔的荒野环境和合适的篝火。拉乌克警告说，在城镇范围内露营是不被提倡的，并提醒旅行者在出发前应先向烹饪训练师学习基本的生火技巧。",al={"露营需要什么","如何搭建营地","露营篝火需求"}},{q="可以在城镇或定居点内搭建营地吗？",a="营地不能放置在定居点或城镇中心内。当地居民反对旅行者在街道中间搭帐篷，因此冒险者必须前往开阔的荒野来搭建营地。",al={"可以在剃刀岭露营吗","在城市内露营","可以在哪里放置营地"}},{q="这项训练教会冒险者制作什么？",a="完成这项训练可以指导冒险者制作个人急救包，这是一种用于维持健康并支持在荒野中进行持续探险的必备野外配件。",al={"露营 101: 急救奖励","这教导什么物品","急救包制作"}},{q="为什么拉乌克建议学习烹饪？",a="一个合适的营地需要一堆温暖的篝火作为核心。由于生火和照看基本火堆的基础知识是由烹饪训练师传授的，拉乌克建议露营者预先学习烹饪艺术。",al={"为什么露营需要烹饪","烹饪篝火露营"}},{q="学习这项工艺前需要什么先决条件？",a="旅行者必须先展现出他们在医疗和生存技能方面的基础熟练度，拉乌克才会教他们如何制作专业的野外急救包。",al={"露营 101: 急救前置要求","露营急救所需技能"}}},fp="22,154,24.169.0,23.254.0,35.130.0,53.177.0,49.108.0,51.100.0,42.129.0,57.121.0"}
P.entries["quest:97904"] = {n="Camping 101: Fishing",s="你的钓鱼技能能为营地带来慰藉。在森金村附近，有人可以教你为同伴制作鱼缸。",h="你的钓鱼技能能为营地带来慰藉。在森金村附近，有人可以教你为同伴制作鱼缸。",kw={"营地设施","露营","鱼缸","渔夫","钓鱼","劳迪克","森金村"},ang={["profession:Cooking"]="作为一名渔夫，展现出娴熟的钓鱼技艺后，你就能学会为营地制作鱼缸。"},sec={{t="营地的慰藉",b="展现出娴熟的钓鱼技艺后，你可以去森金村附近找劳迪克。劳迪克可以教你制作鱼缸，这是一件能为你和同伴带来欢乐的营地设施。赠予者希望，更快乐的营地能让战士们更加强大。"}},faq={{q="钓鱼能为我的营地做些什么？",a="你可以通过钓鱼学习为营地制作鱼缸。",al={"钓鱼营地物品","营地钓鱼"}},{q="谁能教我制作鱼缸？",a="展现出娴熟的钓鱼技艺后，森金村附近的劳迪克可以教你制作鱼缸。",al={"鱼缸教导者","劳迪克钓鱼"}},{q="鱼缸有什么用？",a="鱼缸是一件营地设施，旨在为你和同伴带来欢乐。",al={"鱼缸用途","营地鱼类设施"}},{q="我在哪里能找到劳迪克？",a="劳迪克就在森金村附近。",al={"劳迪克位置","森金村钓鱼"}}},fp="20,133,14.259.0,32.72.0,35.101.0,26.89.0,26.33.0"}
P.entries["quest:97905"] = {n="Camping 101: Herbalism",s="《Camping 101: Herbalism》向采集者介绍了利用野生植物制作熏香蜡烛的技艺。它强调了荒野生存的基本规则，从搭建合适的篝火到在扎营前离开文明城镇。",h="《Camping 101: Herbalism》向采集者介绍了利用野生植物制作熏香蜡烛的技艺。它强调了荒野生存的基本规则，从搭建合适的篝火到在扎营前离开文明城镇。",kw={"营地","篝火","露营","烹饪","草药学","熏香蜡烛","荒野"},ang={["profession:Cooking"]="基础烹饪训练教授旅行者如何点燃合适的篝火，这是任何营地的必要中心。",["profession:Herbalism"]="草药师学习使用采集的植物制作熏香蜡烛，为荒野营地带来温暖、芳香和实用价值。"},sec={{t="荒野的芳香技艺",b="在艾泽拉斯的荒野中生存，需要的不仅仅是利刃，还需要将采集到的植物转化为实用生活用品的知识。通过草药学，采集者可以学会制作自己的熏香蜡烛，将采集物转化为适合旅途生活的舒缓芳香。由于城镇居民不希望帐篷挤占城市街道，这些蜡烛被设计用于在受保护的定居点城墙之外使用。"},{t="营地的核心",b="在荒野中，如果没有篝火的温暖光芒，任何营地都算不上真正完整。在营地中心搭建合适的篝火是使用熏香蜡烛的前提。草药学提供芳香的燃烧体验，而旅行者必须通过烹饪技艺向各地的厨师学习基本的生火技巧。"}},faq={{q="什么是熏香蜡烛？",a="熏香蜡烛是一种由草药师制作的芳香露营用品。它混合了野生植物，旨在荒野营地中与熊熊燃烧的篝火一同使用。",al={"什么是熏香蜡烛","熏香蜡烛用途","露营草药学物品"}},{q="在哪里可以搭建营地？",a="营地不能在城镇中心搭建，因为城镇居民不希望旅行者在公共通道上铺开营地。任何想要试用熏香蜡烛并搭建营地的人都必须前往开阔的荒野。",al={"哪里可以搭建营地","可以在城镇里露营吗","在城市里露营"}},{q="为什么搭建营地需要篝火？",a="每个功能性的营地都需要一堆熊熊燃烧的篝火作为核心。基本的篝火搭建技巧由艾泽拉斯各地的烹饪训练师教授，因此旅行者在出发前应学习入门级的烹饪技艺。",al={"如何制作篝火","露营需要篝火吗","烹饪与篝火露营"}},{q="谁教授篝火搭建方法？",a="烹饪训练师会教授旅行者如何点燃简单的篝火。学习烹饪技艺的基础知识，是你在野外生火的先决条件。",al={"谁教授篝火搭建","学习生火","烹饪训练师篝火"}},{q="草药学与露营有何关联？",a="草药学提供制作专用熏香蜡烛所需的芳香植物和树脂，利用在荒野中采集的天然植物来改善营地的环境，让人倍感舒缓。",al={"草药学与露营的联系","为什么草药学与露营有关","草药学能为营地提供什么"}},{q="使用熏香蜡烛需要篝火吗？",a="如果没有合适的篝火，营地就被认为是不完整的。旅行者被要求先搭建好篝火，再安顿下来享受熏香蜡烛带来的益处。",al={"没有篝火可以点燃熏香蜡烛吗","熏香蜡烛对篝火的需求"}}},fp="22,177,26.201.0,25.216.0,26.103.0,28.103.0,44.107.0,35.114.0,36.131.0,48.86.0"}
P.entries["quest:97906"] = {n="Camping 101: Leatherworking",s="在奥格瑞玛，等你展现出专业技能的本领后，Karolek就能教你制作制皮匠的帐篷。帐篷能在旅途中为你遮风避雨，不过扎营还需要一堆营火。",h="在奥格瑞玛，等你展现出专业技能的本领后，Karolek就能教你制作制皮匠的帐篷。帐篷能在旅途中为你遮风避雨，不过扎营还需要一堆营火。",kw={"营火","露营入门","露营用品","烹饪","karolek","制皮","奥格瑞玛","帐篷"},ang={["profession:Cooking"]="作为厨师，你可以学会生起营火，让营地齐备。"},sec={{t="扎营之地",b="奥格瑞玛的一位制皮匠指引你去找Karolek，他能教你制作旅途中使用的帐篷。帐篷能在炎热的日子里遮阳，也能挡雨，让你在旅途中有个休息的地方。等你熟练掌握制皮技艺后，Karolek就能教你制作这件露营用品。"},{t="先备营火",b="你的帐篷已经准备好了，但还要有营火，营地才算齐备。厨师可以教你生火，烹饪训练师也能教你基础知识。要试用帐篷，就离开城镇中心，到野外把它搭起来。"}},faq={{q="谁能教我制作制皮匠的帐篷？",a="等你熟练掌握制皮技艺后，奥格瑞玛的Karolek就能教你制作帐篷。",al={"帐篷训练师","谁教制作皮匠帐篷","karolek帐篷"}},{q="帐篷有什么用？",a="帐篷能为你挡雨，在炎热的日子里遮阳，还能在旅途中提供一个休息的地方。",al={"帐篷有什么用","制皮露营用品","帐篷用途"}},{q="我能在城里搭帐篷吗？",a="任务完成文本中说，大多数人不喜欢有人在城镇中心搭帐篷，所以你需要到野外试用。",al={"城里搭帐篷","哪里可以扎营","扎营地点"}},{q="扎营还需要什么？",a="除了帐篷，你还需要一堆营火。厨师可以教你生火。",al={"需要营火","如何生营火","营地齐备需要什么"}},{q="谁能教我烹饪的基础知识？",a="烹饪训练师可以教你烹饪技艺的基础知识。",al={"烹饪训练师","学习烹饪技艺","营火训练师"}}},fp="27,201,15.299.0,14.210.0,50.96.0,22.103.0,29.141.0,36.74.0,39.71.0"}
P.entries["quest:97907"] = {n="Camping 101: Mining",s="Camping 101: Mining是一项教学性专业任务，指引初出茅庐的矿工前往剃刀岭寻找克鲁恩。通过展示其专业技能，矿工们可以学会锻造磁石，这是一种专门的营地设施，可以增强在荒野篝火旁聚集的战士的战斗力。",h="Camping 101: Mining是一项教学性专业任务，指引初出茅庐的矿工前往剃刀岭寻找克鲁恩。通过展示其专业技能，矿工们可以学会锻造磁石，这是一种专门的营地设施，可以增强在荒野篝火旁聚集的战士的战斗力。",kw={"营地","篝火","露营101: 采矿","烹饪","杜隆塔尔","克鲁恩","磁石","采矿","剃刀岭"},ang={["faction:Horde"]="穿行于杜隆塔尔的部落矿工可以向剃刀岭的克鲁恩报到，学习为他们的探险活动制作磁石的工艺。",["profession:Cooking"]="烹饪训练师提供了建造基础篝火所需的基础知识，这是任何功能性野外营地的核心。",["profession:Mining"]="采矿让你能够挖掘原始矿石，并制作像磁石这样的专门野外工具，以在营地支持你的盟友。"},sec={{t="矿工营地",b="采矿业是一份诚实的工作，能为荒野探索和生存提供实用的材料。随着矿工不断提升专业水平并展示出熟练的采掘技巧，他们可以学会制作专门的营地装备。在杜隆塔尔，熟练的矿工会被指引前往剃刀岭的聚落寻找克鲁恩，了解如何为他们的旅途锻造磁石。"},{t="篝火情谊",b="磁石是荒野中休息的冒险者们休憩时的魅力核心。当设置在营地旁时，它能为聚集在火堆旁的战斗人员提供额外的战斗力加成。然而，正当的营地礼仪要求离开文明定居点：城镇居民不乐意看到营地搭建在城市广场上，这意味着旅行者必须前往开阔的荒野来测试他们的手艺。"},{t="火焰与野外技艺",b="如果没有合适的火焰作为营地的锚点，即使是最坚固的磁石也毫无用处。在建立任何休息点之前，基础的篝火是必不可少的，那些不熟悉如何生火的人建议去寻找烹饪训练师。接受烹饪艺术的训练可以确保野外探险有足够的温暖和城墙之外生存所需的基本补给。"}},faq={{q="什么是露营 101: 采矿？",a="露营 101: 采矿是一项针对矿工的入门培训任务。它引导已证明自身能力的矿工前往剃刀岭寻找克鲁恩，以学习如何制作一种名为磁石的营地工具。",al={"什么是露营 101 采矿","采矿露营任务","采矿磁石任务"}},{q="克鲁恩是谁？",a="克鲁恩是位于杜隆塔尔剃刀岭的一位训练师。当熟练的矿工展现出足够的专业技能时，他会指导他们如何打造磁石等营地物品。",al={"克鲁恩是谁","克鲁恩在哪里","剃刀岭训练师"}},{q="磁石有什么用？",a="磁石是一种由矿工制作的可制造营地设施。当放置在野外篝火旁时，它能使聚集在火堆周围的物理战斗者获得额外的战斗天赋，从而增强他们的作战能力。",al={"磁石有什么用","磁石的好处","为什么要制作磁石"}},{q="可以在剃刀岭内安营扎寨吗？",a="城镇居民和定居点当局不喜欢在人口稠密的街道中间搭建营地。你必须前往周边的荒野去扎营并放置你的磁石。",al={"我可以在城里露营吗","为什么我不能在剃刀岭露营","在城市内露营"}},{q="为什么在扎营前需要篝火？",a="每一个功能性的营地都需要以篝火为中心。基础篝火的建造由烹饪训练师教授，这使得烹饪成为前往荒野的露营者的一项重要辅助技能。",al={"我需要篝火吗","如何开始露营","露营的生火要求"}},{q="谁可以学习制作磁石？",a="制作磁石需要接受采矿专业的训练。在采矿技艺上展现出足够水平的矿工可以直接从剃刀岭的克鲁恩那里学习该技术。",al={"谁可以制作磁石","任何人都可以制作磁石吗"}}},fp="19,119,16.226.0,20.272.0,19.265.0,28.90.0,13.141.0,29.129.0,38.154.0,50.156.0,35.85.0"}
P.entries["quest:97908"] = {n="Camping 101: Skinning",s="《Camping 101: Skinning》是一项入门级的野外探索任务，它指引奥格瑞玛的剥皮师前往苏尔德处学习如何制作营地椅子。通过将采集到的毛皮用于野外休憩，冒险者可以在卡利姆多的荒野中建立合适的营地。",h="《Camping 101: Skinning》是一项入门级的野外探索任务，它指引奥格瑞玛的剥皮师前往苏尔德处学习如何制作营地椅子。通过将采集到的毛皮用于野外休憩，冒险者可以在卡利姆多的荒野中建立合适的营地。",kw={"营地椅子","营火","露营","露营101: 剥皮","奥格瑞玛","剥皮","苏尔德"},ang={["faction:Horde"]="苏尔德在奥格瑞玛训练剥皮师，这使得在杜隆塔尔活动的部落冒险者能够以独特的方式接触到这种野外工艺入门。",["profession:Cooking"]="一个合适的营地既需要座位也需要热源；我们鼓励新手剥皮师学习烹饪基础，掌握如何搭建基础营火。"},sec={{t="荒野中的舒适",b="采集倒下野兽的毛皮和皮革是冒险者在野外可以培养的最实用的生存技能之一。虽然生皮通常用于制皮，但熟练的剥皮师也能将采集到的毛皮转化成野外休憩的工具。在奥格瑞玛，导师会指引有能力的剥皮师去找苏尔德，学习用鞣制的皮革组装一把坚固的营地椅子的工艺。"},{t="旅行规则",b="城镇居民和卫兵不赞成旅行者在繁忙的城市街道上搭建临时营地。正如苏尔德提醒新工匠的那样，营地椅子是为远离定居点围墙的开阔地带准备的。此外，没有任何野外营地是单靠座位就能完善的；一个合适的营地还需要温暖的营火，这是卡利姆多各地的厨师都会教授的一项基本技术。"}},faq={{q="谁教剥皮师如何制作营地物品？",a="该任务指引剥皮师新手在证明了自己在采集工艺方面的基本熟练度后，前往部落主城奥格瑞玛，与剥皮和制皮训练师苏尔德交谈。",al={"谁提供 露营 101 剥皮 任务","在奥格瑞玛找谁对话","苏尔德是谁"}},{q="剥皮师可以制作什么营地物品？",a="剥皮师学习如何利用从倒下的野兽身上采集的毛皮和皮革来制作营地椅子。它提供了一个舒适的座位，让人们在野外时可以休息和恢复体力。",al={"剥皮师为营地制作什么","剥皮营地工艺","营地椅子剥皮"}},{q="可以在城市里架设营地椅子吗？",a="城市居民和卫兵不赞成在城镇中心架设营地设备。冒险者必须前往定居点大门之外的荒野，才能扎营并摆放椅子。",al={"我能在奥格瑞玛扎营吗","在城市内露营","在哪里扎营"}},{q="完成一个营地还需要什么？",a="没有用于保暖、照明和烹饪的火，营地就不完整。建议冒险者在扎营前咨询烹饪训练师，学习如何建造简单的营火。",al={"为什么需要营火","扎营先决条件","如何搭建营地"}},{q="为什么冒险者需要制作一把营地椅子？",a="在狩猎间隙坐在舒适的椅子上休息片刻，有助于冒险者从旅途中恢复体力，并确保他们在进入下一次冲突前保持最佳状态。",al={"剥皮对露营的益处","为什么要坐在营地椅子上休息","营地椅子的好处"}},{q="苏尔德什么时候会传授营地椅子图纸？",a="剥皮师必须证明自己在从倒下的野兽身上采集皮毛方面的基本熟练度，苏尔德才会分享制作野外营地家具的秘诀。",al={"什么时候可以学习营地椅子","露营 101 要求","需要的剥皮技能"}}},fp="21,166,19.192.0,18.238.0,44.126.0,37.131.0,42.151.0,41.144.0,44.112.0,45.118.0"}
P.entries["quest:97914"] = {n="Expanding Horizons",s="“Expanding Horizons”是一项始于黑海岸的外交信使任务，它将暗夜精灵定居点奥伯丁与人类王国暴风城直接联系起来。受桑德瑞斯·风织者之托，一位冒险者跨越重洋，将官方信件送达给城市建筑师巴隆斯·阿历克斯顿，旨在加强这两个遥远的联盟领地之间的联系与贸易。",h="“Expanding...",kw={"亚米萨兰","奥伯丁","巴隆斯·阿历克斯顿","巴莎兰","黑海岸","达纳苏斯","拓展视野","港口","暴风城","桑德瑞斯·风织者"},ang={["faction:Alliance"]="这项任务展示了将跨越两块大陆的不同种族融合为一个运作良好的统一阵营，需要付出怎样的实际基层工作。",["race:Human"]="带着卡多雷避难所的印记回到暴风城，突显了这个重建王国的触角延伸和全球影响力。",["race:NightElf"]="对于卡多雷来说，开辟通往东部王国的海上航线，代表着对一万年来与世隔绝状态的根本性突破，使你们的种族与人类文明紧密地联系在了一起。"},sec={{t="跨越两半球",b="数千年来，暗夜精灵一直栖息在卡利姆多的森林中，与东部王国隔绝。第三次战争后，他们加入了大联盟，这使得双方不仅在意识形态上，更需要在后勤物流上建立真正的联系。奥伯丁是卡多雷大陆的主要北部港口，但长期以来，它一直处于亚米萨兰和巴莎兰等古老废墟城市的阴影之下。随着奥伯丁与暴风城之间直接海上航线的建立，当地领导人试图巩固这些新开辟的航运路线，并将他们的沿海社区融入到更广阔的联盟网络中。"},{t="给城市建筑师的信",b="这封穿越无尽之海的信件是专门写给暴风城城市建筑师巴隆斯·阿历克斯顿的。作为负责人类首都重建与基础设施建设的总建筑师，阿历克斯顿掌管着宏大的公共工程和物流事务。桑德瑞斯的目的更简单：他希望奥伯丁的工作得到认可，让它的家园为人所知。"}},faq={{q="是谁让你执行这项任务？",a="奥伯丁的一位有影响力的暗夜精灵桑德瑞斯·风织者将此任务交给旅行者。他感到奥伯丁既被高高在上的达纳苏斯所忽视，也被海洋彼岸的遥远盟友所遗忘，因此他寻求与人类王国建立正式的联系。",al={"任务发起人 拓展视野","谁给予 拓展视野","桑德瑞斯任务"}},{q="巴隆斯·阿历克斯顿是谁？",a="巴隆斯·阿历克斯顿是暴风城的城市建筑师。他是一位受人尊敬的城市规划师，年轻时曾结识艾德温·范克里夫，他负责监督整个首都的建筑和结构管理工作。",al={"巴隆斯·阿历克斯顿背景故事","巴隆斯是谁","暴风城城市建筑师"}},{q="为什么奥伯丁要寻求与暴风城的联系？",a="奥伯丁希望其港口能被视为补给、商业和联盟旅行的重要门户。随着黑海岸和东部王国之间新建立的海上航线，当地领导人希望加强与人类王国的经济和后勤联系。",al={"为什么寄信给暴风城","奥伯丁与暴风城的联系","为什么要联系人类"}},{q="奥伯丁和暴风城之间的交通是如何运作的？",a="一艘新船现在连接着奥伯丁与暴风城王国，它横跨无尽之海，直达暴风城港口，为奥伯丁的海岸带来了生机与补给。",al={"前往暴风城的船","如何从奥伯丁前往暴风城"}},{q="亚米萨兰和巴莎兰是什么？",a="它们曾是上古黑海岸繁荣的艾萨拉上层精灵城市，在一万年前大分裂粉碎了这片大陆之前。今天，它们沦为闹鬼的废墟，在卡多雷的历史中，它们往往比奥伯丁这样的现存村庄更被人铭记。",al={"亚米萨兰背景故事","巴莎兰","古代黑海岸城市"}},{q="为什么要把这封信交给建筑师，而不是安度因国王或伯瓦尔？",a="任务中没有说明桑德瑞斯为什么选择他。桑德瑞斯只是要求将这封信交给一位名叫巴隆斯·阿历克斯顿的人类，即暴风城的城市建筑师，以便奥伯丁的工作能得到认可。",al={"为什么是巴隆斯·阿历克斯顿","为什么不是伯瓦尔","为什么不是大领主伯瓦尔"}}},fp="18,127,24.291.0,31.231.0,28.209.0,22.198.0,43.238.0,53.126.0,36.258.0,66.168.0"}
P.entries["quest:97915"] = {n="Camping 101: Alchemy",s="炼金师可以向暴风城附近的Alchemist Mallory学习制作法力之井。它能让治疗者和施法者在营地享用清爽的饮品。",h="炼金师可以向暴风城附近的Alchemist Mallory学习制作法力之井。它能让治疗者和施法者在营地享用清爽的饮品。",kw={"炼金师","alchemist mallory","炼金术","营地","营火","露营","艾尔文森林","治疗者","法力之井","施法者","暴风城"},sec={{t="酿饮营地",b="炼金师可以向艾尔文森林中暴风城附近的Alchemist Mallory请教一门露营技艺。你需要先证明自己技艺娴熟，才能学习制作法力之井。治疗者和施法者可以来到营地，享用清爽的饮品。"},{t="搭建营地",b="掌握这门技艺后，你就能制作自己的法力之井。营地应当搭建在荒野中，而且搭建之前需要先点起营火。烹饪训练师可以教你生火的基本方法。"}},faq={{q="谁能教炼金师制作法力之井？",a="证明自己技艺娴熟后，艾尔文森林中暴风城附近的Alchemist Mallory就会传授这门技艺。",al={"法力之井训练师","炼金露营技艺","mallory炼金"}},{q="法力之井有什么用途？",a="法力之井能让治疗者和施法者在营地享用清爽的饮品。",al={"法力之井用途","法力之井有什么用","炼金营地物品"}},{q="在哪里可以找到Alchemist Mallory？",a="Alchemist Mallory位于艾尔文森林的暴风城附近。",al={"mallory位置","mallory在哪里","艾尔文森林炼金训练师"}},{q="搭建营地前需要准备什么？",a="搭建营地前，你需要先点起营火。烹饪训练师可以教你如何生火。",al={"需要营火","如何搭建营地","露营基础"}},{q="应该在哪里试用法力之井？",a="去荒野中试试吧，因为大多数人都不喜欢有人在镇子中央扎营。",al={"法力之井露营","镇中扎营","在哪里试用法力之井"}}},fp="20,144,16.246.0,15.204.0,43.115.0,24.70.0,35.53.0,38.105.0,36.86.0"}
P.entries["quest:97916"] = {n="Camping 101: Blacksmithing",s="《野营基础：锻造》是闪金镇的一项入门任务，指导铁匠制作野外装备。通过咨询铁匠阿古斯，熟练的金属工可以学会锻造一种用于野外旅行的便携式磨刀石。它强调了野外准备工作，重点介绍了在开阔地区建立工作营地和准备合适的篝火的必要性。",h="《野营基础：锻造》是闪金镇的一项入门任务，指导铁匠制作野外装备。通过咨询铁匠阿古斯，熟练的金属工可以学会锻造一种用于野外旅行的便携式磨刀石。它强调了野外准备工作，重点介绍了在开阔地区建立工作营地和准备合适的篝火的必要性。",kw={"锻造","篝火","野营","野营基础","艾尔文森林","闪金镇","磨刀石","铁匠阿古斯"},ang={["faction:Alliance"]="在闪金镇开启旅程的联盟工匠可以咨询铁匠阿古斯，为城镇围墙之外的长期探险做好准备。",["profession:Blacksmithing"]="在艾尔文森林学习手艺的铁匠可以制作磨刀石，以便在野外维护装备和磨砺利刃。",["profession:Cooking"]="一个合适的营地需要可靠的篝火，这使得基础烹饪训练成为野外金属加工的天然伙伴。"},sec={{t="行囊中的锻造",b="闪金镇的铁匠阿古斯为有志于成为金属工的玩家提供指导，教他们如何将手艺带到路上。比起只能在城镇的铁砧旁工作，展现出足够技巧的铁匠可以学习制作适合野外生存的实用装备。本次教学专注于锻造个人磨刀石，这是在长途旅行中保持利刃锋利的基本工具。"},{t="野外生活",b="建立营地不仅仅需要野外装备；适当的野外礼仪和准备工作也同样至关重要。镇民们不赞成在闪金镇这样的定居点中间扎营，这意味着工匠必须寻找开阔的边境地区来部署他们的装备。此外，没有温暖的篝火，野外营地就不算完整，因此拜访当地的烹饪师学习基本的生火技巧是必不可少的第一步。"}},faq={{q="什么是《野营基础：锻造》？",a="该任务向初级铁匠介绍生存工艺，教他们如何为野外探险锻造便携式磨刀石。",al={"该任务的作用","《野营基础：锻造》的目的","我能学到什么"}},{q="铁匠阿古斯是谁？",a="铁匠阿古斯是位于艾尔文森林闪金镇的常驻铁匠兼训练师。他指导有前途的铁匠进行基础的金属加工和野营工艺。",al={"铁匠阿古斯是谁","闪金镇铁匠训练师","阿古斯 闪金镇"}},{q="什么是磨刀石？",a="磨刀石是一种专业特定的野营物品，铁匠可以学习制作它以备探险之需，让他们在远离传统城镇铁匠铺的地方磨砺工具和武器。",al={"什么是磨刀石","野营 磨刀石","铁匠野营物品"}},{q="可以在镇内扎营吗？",a="镇民们不喜欢在像闪金镇这样的定居区扎营。铁匠必须前往野外才能部署他们的装备。",al={"我能在闪金镇扎营吗","在镇内扎营","我可以在哪里扎营"}},{q="为什么扎营需要篝火？",a="每个营地都需要一堆熊熊燃烧的篝火才算完整。建议铁匠在出发前咨询烹饪训练师，学习基本的生火技巧。",al={"扎营需要烹饪技能吗","营地篝火","如何建立营地"}},{q="什么时候可以学习这种野营工艺？",a="在铁匠阿古斯教你如何锻造专业的野营装备之前，你必须展现出足够的锻造技艺。",al={"《野营基础》的要求","锻造技艺要求"}}},fp="26,188,21.201.0,17.265.0,35.103.0,19.143.0,27.115.0,32.120.0,40.126.0,38.76.0"}
P.entries["quest:97917"] = {n="Camping 101: Enchanting",s="Camping 101: Enchanting 指导附魔师前往暴风城寻找贝蒂·奎因（贝蒂·奎恩），以学习专业的露营技巧。通过为附魔的鲁特琴等休闲物品注入魔法，附魔师能够帮助旅途中的人们保持高昂的士气和充分的休息。",h="Camping 101: Enchanting 指导附魔师前往暴风城寻找贝蒂·奎因（贝蒂·奎恩），以学习专业的露营技巧。通过为附魔的鲁特琴等休闲物品注入魔法，附魔师能够帮助旅途中的人们保持高昂的士气和充分的休息。",kw={"贝蒂·奎因","露营","露营101","露营101: 附魔","附魔的鲁特琴","附魔","暴风城"},ang={["faction:Alliance"]="在联盟领地旅行的附魔师会被指引前往暴风城中心，寻找贝蒂·奎因以接受露营指导。"},sec={{t="旅途中的魔法",b="在艾泽拉斯的旅途中，生存所需的不仅仅是钢铁和口粮；在野外，士气和舒适度对于长途旅行的生存同样至关重要。附魔师可以为营火增添魔法色彩，利用他们深奥的技艺将宁静的休息时间转化为恢复性的娱乐活动，为旅行者应对前路的考验做好准备。"},{t="寻找贝蒂·奎因",b="想要制作特色露营物品的附魔师应前往暴风城寻找贝蒂·奎因。一旦修行者证明了其附魔技艺足够精湛，她就会传授制作附魔的鲁特琴所需的知识，这是一种编织了法术咒语、能在营火旁提振精神的乐器。"}},faq={{q="什么是 露营 101: 附魔？",a="露营 101: 附魔 指导附魔专业的修行者学习如何制作魔法露营用品。当附魔师磨练好技艺后，它会指引他们前往暴风城寻找贝蒂·奎因。",al={"什么是 露营 101 附魔","露营 101 附魔师","附魔露营任务"}},{q="贝蒂·奎因是谁？",a="贝蒂·奎因是一位居住在暴风城的导师，她教导知识渊博的附魔师如何制作有用的魔法装备，以供在路途中的生存与休闲使用。",al={"贝蒂·奎因是谁","暴风城附魔训练师贝蒂","贝蒂·奎因在哪里"}},{q="什么是附魔的鲁特琴？",a="附魔的鲁特琴是一种注入了魔法的乐器，旨在为营地休息期间提供娱乐和士气加成，帮助冒险者在踏上旅途时面对困难。",al={"附魔的鲁特琴有什么用","为什么制作附魔的鲁特琴","附魔的鲁特琴用途"}},{q="为什么营地需要附魔师？",a="附魔师能为营地带来有益的魔法，将日常的休息时间转化为恢复、准备和娱乐的时刻，帮助旅行者忍受艰苦的荒野旅程。",al={"为什么营地需要附魔师","附魔师的营地作用"}},{q="我该去哪里完成这个任务？",a="该任务指引你在暴风城的主城内寻找贝蒂·奎因，该城市位于同名的王国之中。",al={"我在哪里提交 露营 101 附魔","贝蒂·奎因位置"}},{q="学习露营附魔配方需要什么技能？",a="在贝蒂·奎因教你制作附魔的鲁特琴等露营物品之前，你必须展现出扎实的附魔造诣。",al={"露营 101 附魔 要求","我什么时候可以学习附魔的鲁特琴"}}},fp="23,171,18.231.0,18.216.0,32.130.0,18.106.0,26.142.0,40.118.0,36.70.0,57.125.0"}
P.entries["quest:97919"] = {n="Camping 101: First Aid",s="Camping 101: 急救向艾尔文森林的初出茅庐的冒险者们介绍了野外医疗这一实用的生存艺术。它指引旅行者前往闪金镇寻找米歇尔·贝利，学习如何为野外营地准备急救包。",h="Camping 101: 急救向艾尔文森林的初出茅庐的冒险者们介绍了野外医疗这一实用的生存艺术。它指引旅行者前往闪金镇寻找米歇尔·贝利，学习如何为野外营地准备急救包。",kw={"绷带","营地急救包","露营101","艾尔文森林","急救","闪金镇","米歇尔·贝利","生存"},ang={["class:Rogue"]="潜行者在远离支援的阴影中行动，他们依靠野外医疗在前往下一个目标前包扎流血的伤口。",["class:Warrior"]="没有与生俱来的治疗法术，前线战士在野外进行持久战时，严重依赖绷带和急救包来生存。",["faction:Alliance"]="闪金镇仍然是联盟旅行者从北郡开始旅程并进入广阔的艾尔文地区的重要十字路口。"},sec={{t="路途中的野外医疗",b="在艾尔文森林中旅行的冒险者很快就会发现，战斗和严酷的野外生存环境会带来沉重的代价。虽然城镇里的治疗者和旅店能提供喘息之机，但在危险地区穿行往往需要即时的、自给自足的护理。学习急救技能提供了一种治疗流血和外伤的实用方法，让旅行者无需依赖奥术仪式或圣光祈祷就能处理伤口。"},{t="营地补给",b="一个稳固的营地不仅仅是有火堆和睡袋，它是抵御野外危险的临时避风港。在闪金镇狮王之傲旅店的米歇尔·贝利的指导下，技艺娴熟的修行者可以学会组装专门的急救包。在营地备好医疗物资，可以确保疲惫的队伍在面对前方的危险之前，能够处理伤势并恢复体力。"}},faq={{q="这个任务的目的是什么？",a="这个任务引导已经掌握了基础急救技能的冒险者去寻找闪金镇的米歇尔·贝利。她会教导修行者如何制作急救包，以便让他们的野外营地储备必要的医疗物资。",al={"露营急救目的","这个任务是做什么的","为什么露营 101 急救"}},{q="我需要在闪金镇与谁交谈？",a="你需要与闪金镇的训练师米歇尔·贝利交谈。一旦你证明了自己拥有足够的急救技能，她就会分享制作适合野外医疗的露营补给品所需的技巧。",al={"米歇尔·贝利是谁","闪金镇急救训练师","营地急救训练师"}},{q="为什么急救对旅行者很重要？",a="冒险总是伴随着来自野兽、强盗和恶劣环境的身体伤害风险。急救让任何人，无论是否掌握神圣或奥术魔法，都能在战斗间隙包扎伤口并恢复状态。",al={"为什么要学急救","急救是否有用","急救背景知识"}},{q="闪金镇在哪里？",a="闪金镇是艾尔文森林的主要村庄，位于暴风城以南的主贸易道路上。它是补给、本地训练师和在狮王之傲旅店休息的中心枢纽。",al={"闪金镇在哪里","闪金镇位置","如何找到米歇尔·贝利"}},{q="我需要先前的训练才能完成这个任务吗？",a="是的。米歇尔·贝利要求你在她教你制作适合该专业的营地急救包之前，先证明你在急救方面的熟练程度。",al={"露营 101要求","所需的急救技能","前置条件"}},{q="急救包如何应用在露营中？",a="野外营地提供了一个安全的休整区域，而配备急救包可以确保受伤的流浪者能够及时获得包扎和治疗，从而在远离城镇医疗者的地方挽救生命。",al={"营地急救包用途","露营物品急救","为什么要制作急救包"}}},fp="22,181,26.227.0,25.224.0,34.158.0,41.153.0,41.178.0,27.185.0,47.99.0,42.155.0"}
P.entries["quest:97920"] = {n="Camping 101: Fishing",s="Camping 101: Fishing向艾尔文森林的初级垂钓者介绍了荒野生存和露营设施的实用工艺。通过寻找闪金镇附近的当地钓鱼专家李·布朗，旅行者可以学习如何将他们的垂钓知识应用于制作舒适的露营地装饰，比如能鼓舞冒险者士气的装饰性鱼缸。",h="Camping 101...",kw={"露营工艺","露营101: 钓鱼","水晶湖","艾尔文森林","鱼缸","闪金镇","李·布朗"},ang={["faction:Alliance"]="在艾尔文森林开始冒险的人类旅行者可以依靠闪金镇熟悉的水域来学习基本的荒野自给自足技能。"},sec={{t="垂钓者的露营工艺",b="虽然钓鱼常被认为是一种在安静的湖岸和河边进行的孤独消遣，但经验丰富的生存专家明白，露营生活需要的不仅仅是食物和住所。制作像鱼缸这样令人舒适的装置，能为在探险间隙休息的疲惫旅行者带来轻松和士气，这强化了一种信念：健全的心智和高昂的斗志能造就强大的战士。"},{t="李·布朗的专业知识",b="经验丰富的垂钓者李·布朗驻扎在闪金镇外的水域旁，为寻求扩展技艺的初级渔夫提供协助。那些展示出足够钓竿和鱼线熟练度的垂钓者会被指引去向他请教如何将简单的渔获和基础材料转化为功能性的露营地强化物品。"}},faq={{q="这个任务的目的是什么？",a="该任务将有志向的垂钓者指引至闪金镇附近的李·布朗处。一旦你展示了基础的钓鱼熟练度，他就会教你如何制作专门的露营物品，例如鱼缸，来美化路边的营地。",al={"为什么要露营钓鱼","露营 101有什么用","任务目的"}},{q="李·布朗是谁？",a="李·布朗是一位知识渊博的钓鱼训练师，驻扎在艾尔文森林闪金镇外侧的水晶湖畔。他提供垂钓指导，并教授如何建造专为垂钓者设计的露营工艺品。",al={"李·布朗在哪里","谁教授露营钓鱼","李·布朗"}},{q="鱼缸对营地有什么用？",a="鱼缸是一种露营装置，旨在为休息的冒险者带来舒适和快乐。宜人的露营环境能提升士气，帮助冒险者在面对荒野危险时感到准备充分且能力出众。",al={"鱼缸的效果","鱼缸的作用","为什么要制作鱼缸"}},{q="这种训练在哪里进行？",a="该任务发生在艾尔文森林，引导玩家前往闪金镇周边当地垂钓者聚集的水域。",al={"任务地点","我要去哪里","艾尔文森林露营训练师"}},{q="我需要有之前的钓鱼技能才能完成吗？",a="是的。李·布朗只会指导那些已经练习过抛竿并展示了钓鱼行业基本熟练度的旅行者。",al={"钓鱼技能要求","需要钓鱼技能吗","熟练度要求"}},{q="露营对战斗有帮助吗？",a="是的。一个维护良好的营地能提供舒适感，从而增强冒险者的身心准备，并直接反映在他们在野外的韧性和战斗效率上。",al={"露营有助战斗吗","露营增益","为什么要露营"}}},fp="20,179,21.187.0,21.190.0,34.169.0,17.154.0,40.155.0,36.105.0,50.93.0,29.154.0"}
P.entries["quest:97921"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism是一项训练任务，旨在引导熟练的采集者前往艾尔文森林寻求专业的野外指导。在展示了采集植物的熟练技巧后，草药师将被指引去寻找草药师博米洛伊，学习制作营地用品的艺术。完成此项训练将解锁制作熏香蜡烛的能力，这种植物辅助品旨在为在野外休息的施法者提供专注力与精神上的支持。",h="Camping 101...",kw={"营地","露营101","艾尔文森林","治疗者","草药学","草药师博米洛伊","熏香蜡烛","施法者"},ang={["class:Mage"]="法师在野外非常重视熏香蜡烛那种舒缓的植物特性，这使得草药师同伴在漫长的野外旅行中格外受欢迎。",["class:Priest"]="牧师和其他虔诚的治疗者能从靠近熏香蜡烛的休息中获益良多，它能振奋精神并帮助在远征期间恢复重要的能量。",["faction:Alliance"]="由于草药师博米洛伊居住在艾尔文森林，联盟的冒险者可以轻松方便地获得这项专业的营地指导。",["profession:Herbalism"]="此任务将草药学从一种简单的采集行业提升为一种主动的营地支持角色，使植物学家能够制作出协助旅行同伴的熏香蜡烛。"},sec={{t="旅途中的植物用品",b="对于漫游的草药师来说，在艾泽拉斯的荒野中采集草药，其目的远不止于酿制基础的恢复药水或将成捆的花束卖给城市商人。随着从业者磨练他们的采集技艺，将植物学知识应用于野外生存的机会随之而来。野外营地需要的不仅仅是熊熊燃烧的营火和干燥的睡袋；维持旅行团队的耐力和精神敏锐度需要专业的舒适保障。经验丰富的采集者知道，某些植物具有能够振奋疲惫心灵的芳香特性。通过将有潜力的草药师引荐给资深的导师，这项任务将简单的采集与实用的野外生存技巧结合在了一起，证明了对自然馈赠的敏锐洞察力可以支撑整个远征队在远离文明的地方生存下去。"},{t="草药师博米洛伊的指引",b="渴望拓展营地技艺的草药师学徒将被派往艾尔文森林的中心地带，去请教草药师博米洛伊。博米洛伊精通周边林地的各种植物，她深知如何将干燥的花瓣、芳香的茎秆和天然树脂混合制成实用的营地装备。她不再仅仅让草药师将药草用于炼金药剂，而是指导他们制作熏香蜡烛。在营地燃烧时，这种芬芳的创作能够安抚疲惫的旅行者，并鼓舞依赖法力的同伴。找到博米洛伊并证明自己使用镰刀的熟练程度，将确保草药师成为任何冒险进入蛮荒之地的探险队中不可或缺的一员。"}},faq={{q="什么是露营 101: 草药学？",a="露营 101: 草药学是一项入门任务，指导经验丰富的草药师如何将他们的采集行业扩展到营地用品的制作上。它指引玩家前往艾尔文森林会见草药师博米洛伊，她将传授如何为野外营地制作专门的熏香蜡烛。",al={"露营 101 草药学 任务","草药学营地任务","什么是 露营 101 草药学"}},{q="谁传授草药师的营地配方？",a="草药师博米洛伊传授草药学营地配方。她位于艾尔文森林，在那里她分享关于当地植物的知识，并指导熟练的采集者如何制作芳香的熏香蜡烛以增强他们在营地的休息效果。",al={"谁传授草药学营地技能","露营 101 训练师","草药师博米洛伊 在哪里","草药师博米洛伊 位置"}},{q="通过此任务，草药师学会制作什么物品？",a="完成此项训练后，草药师可以为他们的营地制作熏香蜡烛。使用采集到的草药和植物材料制成的蜡烛，能散发出舒缓的香气，提振精神，并为在野外休息的施法者和治疗者提供受欢迎的增益效果。",al={"草药师为营地制作什么","草药学营地物品","熏香蜡烛 草药学","露营 101 教授什么"}},{q="开始露营 101: 草药学有哪些要求？",a="在接受此任务之前，你必须练习草药学专业并展示出足够的采集熟练度。一旦你的草药学技能超过了新手水平，导师们就会认为你已足够老练，可以从草药师博米洛伊那里学习如何准备植物营地用品了。",al={"露营 101 草药学 要求","什么时候可以接取 露营 101 草药学","露营 101 所需草药学技能"}},{q="为什么熏香蜡烛对探险队有用？",a="熏香蜡烛释放出的舒缓草药香气可以提升士气并恢复精神专注。在野外，施法者和治疗者需要消耗巨大的精力来引导魔法力量，这使得这些香氛蜡烛所带来的精神和魔法增益在野外休整期间显得尤为宝贵。",al={"熏香蜡烛有什么用","为什么要制作熏香蜡烛","熏香蜡烛的好处","草药学熏香蜡烛用途"}},{q="此任务在哪里进行？",a="任务目标引导冒险者前往艾尔文森林，这片环绕着暴风城的茂密林地。玩家将前往艾尔文乡间咨询草药师博米洛伊，完成任务并解锁制作植物类营地补给的能力。",al={"露营 101 草药学 区域","去哪里提交 露营 101 草药学","艾尔文森林草药学任务"}},{q="非草药师可以制作熏香蜡烛吗？",a="不能，制作熏香蜡烛直接与草药学专业挂钩。该配方依赖于对野生植物、花卉保存和芳香精油的专业理解，这些知识由草药师博米洛伊专门传授给那些采集植物的冒险者。",al={"任何人都能制作熏香蜡烛吗","熏香蜡烛是草药学专属吗","制作熏香蜡烛需要草药学吗"}}},fp="22,192,32.406.0,33.393.0,31.122.0,46.103.0,55.155.0,58.93.0,55.111.0,33.90.0,44.133.0"}
P.entries["quest:97922"] = {n="Camping 101: Leatherworking",s="《露营指南：制皮》指引制皮学徒前往闪金镇寻找阿黛尔·菲尔德，学习制作旅行帐篷的手艺。在野外搭建帐篷可以提供遮蔽和休息，帮助冒险者抵御恶劣天气，是定居城镇之外重要的生存工具。",h="《露营指南：制皮》指引制皮学徒前往闪金镇寻找阿黛尔·菲尔德，学习制作旅行帐篷的手艺。在野外搭建帐篷可以提供遮蔽和休息，帮助冒险者抵御恶劣天气，是定居城镇之外重要的生存工具。",kw={"阿黛尔·菲尔德","篝火","露营","艾尔文森林","闪金镇","制皮","帐篷","荒野求生"},ang={["faction:Alliance"]="这项训练以艾尔文森林的闪金镇为基地，旨在引导联盟制皮师学习实用的生存工艺，以应对他们在艾泽拉斯各地的旅程。",["profession:Cooking"]="阿黛尔·菲尔德指出，没有篝火的野外营地是不完整的，她敦促旅人们学习烹饪，掌握如何点燃一堆合适的火焰。"},sec={{t="广阔道路上的庇护所",b="对于在城门外漫游的冒险者来说，住所与护甲同样重要。艾尔文森林的制皮师们被指引前往闪金镇的阿黛尔·菲尔德那里，以学习制作腰带和外套之外的新手艺。一旦工匠证明了自己对兽皮和针线的熟练掌握，阿黛尔就会传授这种实用的技术：制作能抵御长途远征中恶劣天气的耐用露营帐篷。"},{t="露营基础",b="完成的帐篷不仅仅是装饰性的遮蔽物；它能在烈日下为疲惫的旅人提供阴凉，在暴雨中保持干燥，并在危险的遭遇战之间提供充分的休息。然而，野外礼仪和城市条例同样重要：闪金镇的居民和城市守卫绝不容忍在城镇街道中间搭建营地。工匠必须前往广阔的野外来设立营地。阿黛尔还提醒所有旅人，没有从烹饪训练师那里学到的篝火，露营地就不算完整。"}},faq={{q="谁教导制皮师如何制作帐篷？",a="阿黛尔·菲尔德位于艾尔文森林的闪金镇。一旦合格的制皮师证明了他们的工艺水平，她就会教导他们如何制作坚固的求生帐篷。",al={"谁提供帐篷训练","阿黛尔·菲尔德位置","制皮帐篷导师"}},{q="制作出的帐篷有什么用？",a="精心制作的帐篷可以保护旅人免受极端天气的侵袭，在炎热的日子里保持凉爽，在倾盆大雨中保持干燥。更重要的是，它能为冒险者提供在荒野旅行时保持敏锐所需的休息。",al={"为什么要制作帐篷","帐篷有什么作用","帐篷的好处"}},{q="可以在城镇内搭帐篷吗？",a="帐篷不能随意搭建；城镇居民不喜欢旅人在街道或城镇中心堆放露营地。冒险者应该带着装备去野外妥善设立营地。",al={"可以在镇里搭帐篷吗","在哪里可以使用帐篷","在暴风城或闪金镇使用帐篷"}},{q="除了帐篷，搭建营地还需要什么？",a="仅有一个帐篷并不能构成一个功能齐全的营地。阿黛尔·菲尔德强调，每个合格的营地都需要篝火，它在野外提供了温暖和实际的用途。",al={"搭建营地还需要什么","帐篷和篝火需求","如何完成营地"}},{q="旅人在哪里可以学习建造篝火？",a="烹饪训练师和当地厨师会教授点燃篝火的基本知识。准备露营的冒险者被建议学习烹饪艺术，这样无论走到哪里，他们都知道如何生起可靠的火堆。",al={"谁教导篝火","如何学习篝火","营地用火"}},{q="制皮师什么时候可以学习制作露营帐篷？",a="有志于此的制皮师必须首先证明自己在制皮方面的熟练度，阿黛尔·菲尔德才会教导他们制作帐篷。一旦展现出足够的工艺水准，就可以学习该项技术。",al={"帐篷技能需求","如何获取帐篷配方","什么时候可以制作帐篷"}}},fp="27,196,25.319.0,27.420.0,46.127.0,39.163.0,35.107.0,56.103.0,47.142.0,55.91.0"}
P.entries["quest:97923"] = {n="Camping 101: Mining",s="“Camping 101: Mining”是一项入门任务，旨在教导矿工如何制作磁石来强化野外营地。在暴风城的吉尔曼·石手指导下，勘探者们将学会引导共鸣大地技艺，以增强伙伴们在营火旁的战斗能力。",h="“Camping 101: Mining”是一项入门任务，旨在教导矿工如何制作磁石来强化野外营地。在暴风城的吉尔曼·石手指导下，勘探者们将学会引导共鸣大地技艺，以增强伙伴们在营火旁的战斗能力。",kw={"营火","露营101: 采矿","营地","吉尔曼·石手","磁石","采矿","暴风城","荒野"},ang={["faction:Alliance"]="吉尔曼·石手在暴风城工作，指导联盟的工匠们将原始的大地技艺转化为实用的野外工具。",["profession:Cooking"]="营地的运作从根本上依赖于照料良好的营火，这使得基础烹饪训练成为专业营地配件不可或缺的伙伴。",["profession:Mining"]="磨练过技艺的矿工可以锻造磁石来强化他们的野外营地，为在身旁休息的盟友提供武力加成。"},sec={{t="大地共鸣之力",b="采矿是一门艰苦而诚实的劳动，但它的回报远不止于熔炼矿锭和锻造护甲。暴风城的专业矿工可以学习如何将大地天然的磁性引导至功能性的磁石中。当放置在远征营地时，这种石头能增强围坐在营火旁的任何战士的战斗活力。身为王国首都经验丰富的采矿训练师，吉尔曼·石手会将这门手艺传授给证明了自己镐法娴熟的勘探者们。"},{t="野外营地与营火",b="磁石不能随意丢弃在大教堂广场或贸易区的鹅卵石路上。城镇居民对于在城市范围内搭建临时营地的旅行者持排斥态度，这意味着先驱者们必须前往荒野去建立营地。此外，如果没有营火这一温暖的基础，像磁石这样的专业装备将毫无用处，而营火本身是整个领域内厨师都会传授的一种基础野外生存技能。"}},faq={{q="什么是“露营 101: 采矿”？",a="这项任务旨在向矿工介绍制作专业营地强化物品的艺术。一旦你证明了自己在采矿方面的造诣，就可以与暴风城的吉尔曼·石手交谈，学习如何锻造磁石。",al={"什么是露营 101 采矿","任务目标","我该做什么"}},{q="谁教授磁石图纸？",a="吉尔曼·石手是一位位于暴风城的采矿训练师。他教导合格的矿工如何制作磁石，以支持他们在野外的远征。",al={"谁教授磁石","吉尔曼·石手在哪里","石手位置"}},{q="磁石有什么作用？",a="磁石是一种放置在野外营地的物品。它会在营火周围散发出一种强化能量，提升聚集在此休息的战士和其他武技斗士的战斗实力。",al={"磁石有什么作用","磁石增益","为什么要做磁石"}},{q="我可以在暴风城内扎营吗？",a="城市当局和普通民众不喜欢人们在城镇广场或城市街道上扎营。你必须前往定居点大门之外的荒野，才能扎营并部署你的磁石。",al={"我可以在城镇里扎营吗","我在哪里可以放置营地","扎营限制"}},{q="为什么扎营时需要营火？",a="在可以使用任何专业营地装备之前，每个营地都需要一个基础营火作为核心基础。厨师通常会教旅行者如何用简单的木材和燧石生火。",al={"扎营需要烹饪技能吗","如何搭建营地","营火需求"}},{q="谁从磁石的聚集中受益最大？",a="任何挥舞刀剑、斧头或锤子的人都能从磁石的力量中获益匪浅。它散发出一种额外的武力优势，战士们在危险战斗前围坐在火堆旁休息时，正是为了寻求这种加成。",al={"谁能从磁石中获益","磁石适合近战吗","磁石职业"}}},fp="19,152,26.291.0,30.285.0,28.145.0,36.132.0,25.110.0,35.156.0,40.163.0,52.164.0"}
P.entries["quest:97924"] = {n="Camping 101: Skinning",s="Camping 101: Skinning是一项针对在艾尔文森林中旅行的熟练剥皮者的入门指导任务。它指引冒险者前往闪金镇寻找赫琳·皮皮斯金，学习如何用收集的皮革制作一把营地椅子。学会制作个人营地用品可以让荒野旅行者在远离城镇安全区的地方休息和恢复。",h="Camping 101...",kw={"营地椅子","营火","露营101: 剥皮","闪金镇","赫琳·皮皮斯金","剥皮","荒野露营"},ang={["faction:Alliance"]="造访艾尔文森林的新手联盟剥皮者会被指引前往闪金镇的赫琳·皮皮斯金处，以提升他们的荒野生存技能。",["profession:Cooking"]="学习搭建野外营地的剥皮者建议咨询厨师，因为没有用于保暖和烹饪食物的简单营火，营地就不算完整。"},sec={{t="荒野中的生活舒适度",b="对于荒野猎人和侦察兵来说，采集兽皮的艺术不仅仅是为了获取贸易商品和护甲废料。经验丰富的剥皮者可以制作营地椅子等野外生活用品，让旅行者能够坐下来休息肢体，并在穿越危险地区的漫长旅途中保持最佳身体状态。闪金镇的赫琳·皮皮斯金会指导熟练的剥皮者如何将生兽皮转化为舒适的营地座椅。"},{t="营地规则",b="建立野外休息点需要尊重当地定居点，并做好适当的户外准备。大多数城镇居民反感冒险者在城镇广场搭建个人营地，因此旅行者必须前往荒野地区才能展开装备。此外，如果没有营火，任何野外营地都无法真正发挥作用，这促使许多剥皮者学习基本的烹饪艺术来掌握生火技巧。"}},faq={{q="什么是露营 101: 剥皮？",a="露营 101: 剥皮是一项入门训练任务，指导熟练的剥皮者学习如何用收集的兽皮制作营地椅子，从而扩展他们的荒野生存能力。",al={"什么是露营 101 剥皮","这个任务有什么用","剥皮营地椅子任务"}},{q="谁教授剥皮者如何制作营地椅子？",a="赫琳·皮皮斯金是一位位于艾尔文森林闪金镇的制皮和剥皮训练师，她负责教授熟练的剥皮者如何制作这种椅子。",al={"谁教授营地椅子","赫琳·皮皮斯金位置","露营 101 剥皮在哪里交任务"}},{q="制作营地椅子的目的是什么？",a="营地椅子可以为冒险者在他们的营地中提供一个舒适的座位，用于休息和恢复，确保他们保持最佳状态以应对荒野中的旅行和战斗。",al={"营地椅子有什么用","为什么要制作营地椅子","营地椅子用途"}},{q="冒险者可以在哪里安营扎寨？",a="城镇居民通常不喜欢在定居点中心搭建营地。冒险者在架设椅子和营地之前，应当先进入荒野地区。",al={"我可以在镇里露营吗","我可以在哪里放置营地椅子","在闪金镇露营"}},{q="搭建一个完整的营地还需要什么？",a="在布置装备之前，每一个正式的营地都需要基本的营火。不懂生火技术的冒险者，建议向当地厨师学习烹饪艺术。",al={"露营需要什么","露营需要营火吗","营火要求"}},{q="谁有资格学习这种露营工艺？",a="这种特殊的露营工艺是为那些已经在剥取野兽毛皮方面证明了熟练度的剥皮者量身定制的，他们可以将野外采集的皮革用于实际的生存用途。",al={"谁可以学习营地椅子","非剥皮者可以做这个吗","露营的剥皮要求"}}},fp="21,184,29.212.0,21.213.0,30.103.0,47.81.0,45.83.0,34.107.0,51.110.0,44.122.0"}
P.entries["quest:97925"] = {n="Camping 101: Tailoring",s="《露营指南101：裁缝》引导技艺高超的裁缝前往艾尔文森林东谷伐木场的埃尔德林处。通过他，裁缝们可以学习编织阵营旗帜，这种旗帜能为野外营地带来激励效果，并提升士气。",h="《露营指南101：裁缝》引导技艺高超的裁缝前往艾尔文森林东谷伐木场的埃尔德林处。通过他，裁缝们可以学习编织阵营旗帜，这种旗帜能为野外营地带来激励效果，并提升士气。",kw={"旗帜","露营","露营指南101","东谷伐木场","埃尔德林","艾尔文森林","阵营旗帜","裁缝"},ang={["faction:Alliance"]="联盟冒险者被指引前往艾尔文森林东谷伐木场的埃尔德林处，以学习阵营旗帜的缝制方法。",["profession:Tailoring"]="裁缝可以编织一面鼓舞人心的阵营旗帜，以在长期探险期间提振士气，并使营地保持充沛的精力。"},sec={{t="编织者在野外的使命",b="《露营指南101：裁缝》将有前途的缝纫工引向埃尔德林，一位常驻在艾尔文森林东部东谷伐木场的工匠。裁缝往往因制作防护性布甲和背包而受到赞誉，但这项任务强调了其在维持野外探险方面的重要作用。对于那些证明了自己在针线和织布机方面拥有才能的冒险者，埃尔德林会提供专业的指导，帮助他们制作出支持在荒野中长期旅行的露营装备。"},{t="士气旗帜",b="这项指导中教授的主要工艺是阵营旗帜，这是一种设计用于在旅行者营火旁竖立的标志。无论是在危险的旅途中还是战场上，保持高昂的士气与维护武器或口粮同样重要。在营地上方展示一面鼓舞人心的旗帜，能为疲惫的冒险者提供熟悉的决心象征，赋予他们深入敌境所需的能量。"}},faq={{q="《露营指南101：裁缝》的目的是什么？",a="《露营指南101：裁缝》引导有抱负的裁缝寻找位于艾尔文森林东谷伐木场的埃尔德林。一旦裁缝展示出足够的熟练度，埃尔德林就会指导他们如何缝制一面鼓舞人心的阵营旗帜，以提振营地士气。",al={"什么是露营指南101裁缝","裁缝营地物品任务","如何获得营地旗帜"}},{q="埃尔德林是谁？在哪里可以找到他？",a="埃尔德林是一位居住在艾尔文森林东部东谷伐木场的工匠。他拥有指导熟练裁缝制作适用于营地的阵营旗帜的专业知识。",al={"埃尔德林是谁","埃尔德林在哪里","埃尔德林位置"}},{q="阵营旗帜对营地有什么作用？",a="阵营旗帜是营地的核心装饰，旨在促进士气和激发灵感。在野外，展示你的阵营立场有助于让疲惫的旅行者在艰苦的战役中保持活力和专注。",al={"裁缝旗帜有什么作用","阵营旗帜露营","为什么要制作阵营旗帜"}},{q="从埃尔德林那里学习这门工艺需要什么条件？",a="在埃尔德林传授该技术之前，需要展示出在裁缝方面的熟练度。只有磨练过针线活的从业者才能正确地编织和组装这种旗帜。",al={"我需要什么技能","露营旗帜要求","任何裁缝都能制作旗帜吗"}},{q="东谷伐木场位于哪里？",a="东谷伐木场坐落在艾尔文森林东部的树林中，位于通往赤脊山的道路沿线。这是一个活跃的伐木中心，当地的工匠和工人们聚集于此。",al={"东谷伐木场在哪里","艾尔文森林东谷伐木场"}},{q="这项任务是联盟裁缝独有的吗？",a="这项特定的任务会将工匠送往位于艾尔文森林中心地带的埃尔德林处，这里完全处于联盟领地。因此，它服务于在东部定居点运作的联盟阵营工匠。",al={"部落可以做这个任务吗","这是联盟专属吗"}}},fp="22,192,30.298.0,17.274.0,46.159.0,40.138.0,43.143.0,60.135.0,43.170.0,43.153.0"}
P.entries["quest:97926"] = {n="Making Do",s="“Making Do”是一个连接黑海岸的奥伯丁港口与遥远的暴风城王国的联盟任务。探险家受托将巴隆斯·阿历克斯顿的一封正式回复送交给桑德拉斯·风织者长老，却带来了一个严峻的消息：暴风城日益枯竭的国库已经无力援助这个陷入困境的暗夜精灵定居点。",h="“Making...",kw={"阿历克斯顿","阿历克斯顿的回复","奥伯丁","国库","黑海岸","将就应付","暴风城","桑德拉斯·风织者"},ang={["faction:Alliance"]="这个任务突显了联盟内部脆弱的凝聚力，说明了地理距离和内部压力是如何让像奥伯丁这样的偏远定居点在没有暴风城财政支持的情况下只能自谋生路。",["race:Human"]="阿历克斯顿的信反映了暴风城王国所面临的严峻现实，国库枯竭和广泛的国内困境使王室无法为海外救援行动提供资金。",["race:NightElf"]="对于奥伯丁的暗夜精灵来说，暴风城的拒绝更加深了他们的认识，即无论是远在海对岸的人类盟友，还是近在咫尺的达纳苏斯，都没有站出来解决他们的当地困难。"},sec={{t="跨海信使",b="“Making Do”任务要求旅行者带着阿历克斯顿的回复穿越海洋，送交奥伯丁的桑德拉斯·风织者长老。这封信里并非援助承诺或派兵部署，而是一份不幸的拒绝信。暴风城的代表惋惜地表示，王国的财政已经捉襟见肘，仅存的那点财富也已经难以维持其自身苦苦挣扎的领土。"},{t="自生自灭",b="在收到回复后，桑德拉斯·风织者对结果深感惋惜，但感谢了旅行者完成这段漫长的旅途。由于暴风城无法提供援助，达纳苏斯也同样缺席，桑德拉斯只能无奈地接受现实，让族人自食其力，并感叹奥伯丁的命运完全掌握在他们自己手中。"}},faq={{q="“将就应付”是什么任务？",a="“将就应付”是一个任务，探险家需要将巴隆斯·阿历克斯顿从暴风城寄来的正式回复送回奥伯丁，交给桑德拉斯·风织者长老，信中带着令人失望的消息，即暴风城无力支援黑海岸。",al={"什么是因陋就简","因陋就简任务","奥伯丁暴风城任务"}},{q="为什么暴风城拒绝援助奥伯丁？",a="暴风城的代表解释说，王国的国库已经严重亏空，仅存的资源在支撑其本土领土时已十分勉强，导致他们无法资助奥伯丁。",al={"为什么暴风城拒绝","暴风城国库空虚","为什么暴风城不援助奥伯丁"}},{q="桑德拉斯·风织者对这个消息有何反应？",a="桑德拉斯·风织者怀着沉重的心情收下了这封信，但接受了现实，结论是既然暴风城和达纳苏斯都不会提供支持，奥伯丁的人民只能掌握自己的命运。",al={"桑德拉斯对暴风城的反应","桑德拉斯作何反应"}},{q="是谁寄出了阿历克斯顿的回复？",a="巴隆斯·阿历克斯顿是暴风城的城市建筑师，他传达了王国的回应，在传达暴风城无力提供经济援助的残酷事实的同时，也表达了对奥伯丁困境的个人同情。",al={"阿历克斯顿是谁","阿历克斯顿的回复发送者"}},{q="达纳苏斯在帮助奥伯丁吗？",a="在读过阿历克斯顿的信后，桑德拉斯·风织者指出，无论是暴风城还是他们附近的首都达纳苏斯，都没有伸出援手，导致奥伯丁定居点孤立无援，只能靠自己。",al={"达纳苏斯援助奥伯丁","为什么达纳苏斯不提供帮助"}},{q="阿历克斯顿的回复是在哪里交付的？",a="该任务在黑海岸沿岸的奥伯丁港口小镇结束，桑德拉斯·风织者正在那里等待从暴风城归来的信使。",al={"该任务在哪里结束","因陋就简交接地点"}}},fp="9,142,24.276.0,22.238.1,28.155.0,43.153.0,47.154.0,26.138.0,31.114.0,36.102.0"}
P.entries["quest:97927"] = {n="Camping 101: Alchemy",s="雷霆崖的Kray可以教你制作法力之井，供炼金师的营地使用。这口井会吸引前来恢复精力的治疗者和施法者。",h="雷霆崖的Kray可以教你制作法力之井，供炼金师的营地使用。这口井会吸引前来恢复精力的治疗者和施法者。",kw={"炼金师","炼金术","营火","露营","治疗者","kray","法力之井","施法者","雷霆崖"},sec={{t="营地之井",b="炼金师可以向雷霆崖的Kray学习制作法力之井。你已经展现了娴熟的技艺，Kray可以传授你这项露营技艺。治疗者和施法者会前来饮上一口，恢复精力。要在野外扎营，你还需要一堆营火，厨师可以教你如何生火。"}},faq={{q="谁能教我制作法力之井？",a="当你展现出娴熟的炼金术技艺后，雷霆崖的Kray就可以教你制作法力之井。",al={"法力之井训练师","kray是谁","kray炼金术"}},{q="法力之井有什么用？",a="法力之井是炼金师可以制作的露营设施。治疗者和施法者会前来恢复精力。",al={"法力之井用途","井有什么用","炼金术营地物品"}},{q="在哪里可以学习这项露营技艺？",a="与雷霆崖的Kray交谈，就能学习制作法力之井。",al={"kray在哪里","雷霆崖炼金术","法力之井位置"}},{q="扎营还需要什么？",a="扎营前需要先准备一堆营火。厨师可以教你如何生火。",al={"需要营火","如何扎营","扎营用火"}},{q="我可以在城镇里测试法力之井吗？",a="完成任务的说明中提到，大多数人都不喜欢有人在城镇中心扎营，所以你需要前往野外测试。",al={"城镇扎营","在哪里试用法力之井","法力之井测试"}}},fp="20,144,15.311.0,36.100.0,24.99.0,36.66.0,35.82.0,33.138.0"}
P.entries["quest:97928"] = {n="Camping 101: Blacksmithing",s="你学会了制作可在野外使用的磨刀石。搭建营地前需要先准备好篝火。",h="你学会了制作可在野外使用的磨刀石。搭建营地前需要先准备好篝火。",kw={"锻造","篝火","扎营","厨师","磨刀石","野外"},ang={["profession:Blacksmithing"]="你现在可以制作可在野外使用的磨刀石。",["profession:Cooking"]="你可以向厨师学习制作篝火。"},sec={{t="准备扎营",b="你现在可以制作磨刀石了。想试试的话，就去野外吧，那里可以在远离城镇中心的地方扎营。记得带上篝火；厨师可以教你如何制作。"}},faq={{q="我现在可以制作什么？",a="你可以制作自己的磨刀石。",al={"磨刀石","锻造制作","制作什么"}},{q="我可以在哪里试用磨刀石？",a="你可以在野外测试，那里可以在远离城镇中心的地方扎营。",al={"在哪里测试","磨刀石位置","在哪里扎营"}},{q="扎营前需要准备什么？",a="开始扎营前需要先准备好篝火。",al={"需要篝火","如何扎营","扎营基础"}},{q="谁能教我制作篝火？",a="厨师可以教你制作篝火。",al={"学习制作篝火","谁教生火","烹饪篝火"}}},fp="26,119,13.198.0,21.44.0,37.89.0,38.47.0,36.40.0"}
P.entries["quest:97931"] = {n="Camping 101: First Aid",s="现在你可以制作自己的绷带包了。想试用它，你需要在野外露营，而且还需要篝火。",h="现在你可以制作自己的绷带包了。想试用它，你需要在野外露营，而且还需要篝火。",kw={"绷带包","篝火","露营","烹饪","急救","野外"},sec={{t="露营地点",b="绷带包已经可以制作了，但大多数人不喜欢在城镇中央露营。你需要在野外试用它。露营前必须先生起篝火，大多数烹饪训练师都能教你如何生火。"}},faq={{q="我可以在哪里试用绷带包？",a="你需要在野外试用它，因为大多数人不喜欢在城镇中央露营。",al={"在哪里试用绷带包","绷带包地点"}},{q="露营前需要准备什么？",a="露营前需要先生起篝火。",al={"需要篝火","露营需要什么"}},{q="谁能教我生火？",a="大多数烹饪训练师都能教你如何生火。",al={"生火","生火教学"}}},fp="22,74,15.207.0,34.90.0,38.47.0,36.48.0"}
P.entries["quest:97932"] = {n="Camping 101: Fishing",s="Camping 101: Fishing 向垂钓者介绍了如何用手工制品装饰野外营地。通过向血蹄村的尤萨恩·静水展示精湛的技艺，渔夫们可以学会制作鱼缸，为在野外休息的旅行者带来鼓舞士气的乐趣。",h="Camping 101: Fishing 向垂钓者介绍了如何用手工制品装饰野外营地。通过向血蹄村的尤萨恩·静水展示精湛的技艺，渔夫们可以学会制作鱼缸，为在野外休息的旅行者带来鼓舞士气的乐趣。",kw={"血蹄村","营火","露营","露营101: 钓鱼","鱼缸","钓鱼","莫高雷","尤萨恩·静水"},ang={["faction:Horde"]="穿行于莫高雷的部落垂钓者可以从血蹄村的尤萨恩·静水那里学习制作营地设施。",["profession:Cooking"]="每个像样的营地都需要一个基本的营火才能开始，这使得基本的烹饪训练成为任何渔夫野外营地的天然补充。"},sec={{t="野外垂钓",b="穿行于莫高雷的垂钓者可以通过 Camping 101: Fishing 将他们安静的消遣转化为实用的营地工艺。已经证明了自己拥有精湛钓鱼技术的冒险者应前往血蹄村寻找尤萨恩·静水。熟练的渔夫不仅能提供食物，还能学会为野外生活制作一件家居饰品：一个能让营地增色的个人鱼缸。"},{t="营地舒适度",b="对于饱经风霜的流浪者来说，鱼缸可能是一个奇怪的伙伴，但一个舒适的休息点会让旅途获益匪浅。这个小装置为严酷的荒野带来了一丝轻松与宁静，为在火焰旁休息的任何人提振士气。正如老练的生存专家所知，高昂的精神直接转化为敏锐的直觉和更强的战斗韧性。"},{t="营火与旷野",b="搭建营地既需要尊重当地习俗，也需要扎实的基本功。像血蹄村这样的定居点不允许旅行者在城镇中央搭建临时营地，这意味着鱼缸只能在广阔的荒野中测试。此外，没有合适的营火就无法建立营地，这要求有抱负的露营者寻找烹饪训练师，掌握基本的生火技能。"}},faq={{q="鱼缸对营地有什么作用？",a="鱼缸是由熟练的渔夫制作的装饰性营地设施。它的设计初衷是为在荒野中休息的冒险者带来快乐和舒适，保持高昂的士气，使他们在战斗中保持敏锐和能力。",al={"鱼缸营地","鱼缸的作用","鱼缸的好处"}},{q="谁传授鱼缸配方？",a="尤萨恩·静水在位于莫高雷草海平原的血蹄村传授这门手艺。他会指导那些已经在钓鱼技能上展现出足够熟练度的垂钓者。",al={"哪里学习鱼缸制作","谁传授鱼缸","尤萨恩·静水 的位置"}},{q="为什么不能在定居点内搭建营地？",a="城镇居民和村庄守卫通常不赞成旅行者在街道中央搭建完整的营地并点火。营地必须搭建在野外的旷野之中。",al={"在城镇内露营","为什么不能在血蹄村露营","在城市内露营"}},{q="搭建营地还需要什么？",a="没有以营火为核心，合适的营地就无法运作。没有生火技能的旅行者建议在搭建营地前寻找烹饪训练师，掌握生火的艺术。",al={"露营需要营火","露营需要生火","露营基础生火"}},{q="学习鱼缸前需要满足什么要求？",a="在尤萨恩·静水分享制作营地设施的秘密之前，需要证明在钓鱼方面的熟练度。新手垂钓者需要先花些时间在水边磨练自己的技艺。",al={"钓鱼熟练度与露营","什么时候可以获得鱼缸","露营 101: 钓鱼 要求"}},{q="为什么冒险者在露营时需要一个鱼缸？",a="在艾泽拉斯的旅途中，生活是严峻而疲惫的。一点点家庭生活的点缀和宁静的爱好，比如在篝火旁看着鱼缸里的鱼，能提供难得的快乐火花，提振冒险者的精神。",al={"为什么露营要带鱼缸","营地鱼缸背景"}}},fp="20,218,19.257.0,16.237.0,25.248.0,42.185.0,33.128.0,45.124.0,39.128.0,59.169.0,55.146.0"}
P.entries["quest:97933"] = {n="Camping 101: Herbalism",s="雷霆崖的克米恩·冰蹄可以教你为营地制作熏香蜡烛。掌握草药学，就能学会制作这种对治疗者和施法者有用的辅助物品。",h="雷霆崖的克米恩·冰蹄可以教你为营地制作熏香蜡烛。掌握草药学，就能学会制作这种对治疗者和施法者有用的辅助物品。",kw={"营火","野营","野营入门","草药学","熏香蜡烛","克米恩·冰蹄","雷霆崖"},ang={["profession:Cooking"]="身为厨师，你可以传授生起营火的基本方法，这是扎营所必需的。",["profession:Herbalism"]="身为草药师，你可以凭借自己的技能，学习为营地制作熏香蜡烛。"},sec={{t="营地里的蜡烛",b="雷霆崖的一位老师请你运用草药学技能，学习一门野营手艺。熏香蜡烛可以提振治疗者和施法者的精神。离开时，你已学会如何制作熏香蜡烛，但要试用它，还得在城镇外扎营，并生起营火。"}},faq={{q="谁教授这门野营手艺？",a="雷霆崖的克米恩·冰蹄会教你制作熏香蜡烛。",al={"野营草药学训练师","谁教授熏香蜡烛"}},{q="草药学和野营有什么关系？",a="展现出对草药学的熟练掌握，就能学习为营地制作熏香蜡烛。",al={"草药学野营物品","草药学野营"}},{q="熏香蜡烛有什么用途？",a="熏香蜡烛可以提振治疗者和施法者的精神。",al={"熏香蜡烛用途","营地蜡烛"}},{q="在哪里可以试用蜡烛？",a="你需要前往荒野试用它，因为大多数人都不喜欢有人在城镇中心扎营。",al={"哪里试用熏香蜡烛","城镇内扎营"}},{q="扎营还需要别的东西吗？",a="扎营之前需要先有一堆营火。大多数厨师都能教你如何生起营火。",al={"需要营火","扎营还需要什么"}}},fp="22,165,17.285.0,27.73.0,44.89.0,30.68.0,27.109.0,33.86.0"}
P.entries["quest:97934"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking 指导有抱负的制皮师前往莫高雷的血蹄村，学习制作便携式露营帐篷的艺术。通过在查尔·硬皮的指导下掌握这项基本工艺，旅行者可以在旅途中建立起提供保护的荒野避难所，保持休息和韧性。它强调了在边境地区自力更生、荒野生存和户外准备的重要性。",h="Camping 101: Leatherworking...",kw={"血蹄村","营火","露营101","查尔·硬皮","制皮","莫高雷","避难所","帐篷"},ang={["faction:Horde"]="穿越卡利姆多广阔干旱地形的部落旅行者，必须依靠坚固的露营装备，才能在远离防御堡垒的地方生存。",["profession:Cooking"]="烹饪训练师传授建造合适营火的艺术，这对于将简单的皮革帐篷变成功能齐全、温暖的营地至关重要。",["race:Tauren"]="制作便携式皮革避难所，与莫高雷平原上牛头人部落的游牧传统和荒野生存遗产自然地契合。"},sec={{t="广阔平原上的避难所",b="对于在卡利姆多广袤荒野中穿行的制皮师来说，知道如何缝制坚固的帐篷与鞣制皮革同样重要。制作精良的帐篷能保护疲惫的旅行者免受正午烈日的炙烤，也能抵挡无情的草原骤雨。它不仅仅是简单的帆布和皮革，更提供了一个安静的庇护所，让冒险者可以在面对广阔平原上的下一次考验之前，得到充分的休息并恢复体力。"},{t="查尔·硬皮的手艺",b="在莫高雷金色的草丛中，坐落着宁静的牛头人定居点血蹄村，查尔·硬皮在这里传授荒野生存的实用秘诀。查尔会观察制皮师是否已经具备了处理更厚重的皮革和进行粗犷缝合的必要技能。一旦工匠证明了自己的熟练程度，他就会教导他们如何建造一种耐用的露营帐篷，这种帐篷专为在远离文明的漫长旅途中抵御恶劣天气而设计。"},{t="荒野营地",b="搭帐篷需要良好的判断力，并尊重当地的定居点。村民们不喜欢旅行者在他们的中心道路和交通要道上随意搭建个人营地，这意味着制皮师必须前往荒野边境，才能扎下他们的避难所。此外，没有噼啪作响的炉火带来的温暖和保护，荒野营地就不算真正完整，这促使漫游者去咨询熟练的厨师，学习如何生起一堆像样的营火。"}},faq={{q="这个任务教给制皮师什么？",a="这个任务指导制皮师学习如何为旅行建造个人露营帐篷。坚固的帐篷能提供对抗恶劣天气的关键保护，在酷热下让旅行者保持凉爽，在倾盆大雨中保持干爽，同时确保他们在荒野中得到充分的休息。",al={"制皮帐篷任务","露营 101 教什么","制皮露营物品"}},{q="谁教制皮师制作露营帐篷？",a="位于莫高雷血蹄村的查尔·硬皮指导制皮师制作露营避难所。一旦制皮师展示出足够的工艺熟练度，他就会同意分享他的帐篷制作知识，传授适用于在荒野中进行长途探险的传统生存技巧。",al={"谁教帐篷制作","查尔·硬皮 帐篷","制皮帐篷训练师"}},{q="旅行者可以在哪里搭设露营帐篷？",a="露营帐篷必须搭在开阔的荒野中，而不是人口稠密的定居点内。城镇居民和村长不喜欢旅行者在城镇广场或繁忙的道路中间搭设私人避难所，所以漫游者必须冒险进入野外乡村来测试他们的新装备。",al={"我可以在哪里搭帐篷","我可以在城里露营吗","帐篷放置"}},{q="为什么帐篷旁边需要营火？",a="一个像样的荒野营地，如果没有噼啪作响的营火来提供光亮、温暖和食物，就不算完整。虽然制皮师可以制作遮蔽用的帐篷，但生火需要基本的生存烹饪技巧。建议旅行者在进入荒野之前，先拜访当地的厨师，学习如何建造和维护营火。",al={"为什么需要营火","烹饪 营火 帐篷","帐篷和火"}},{q="血蹄村位于哪里？",a="血蹄村是一个重要的牛头人定居点，位于莫高雷中部，雷霆崖以南，石牛湖岸边。它是当地猎人、采集者和工匠的重要社区中心，为探索周边平原的旅行者提供训练、贸易物资和指导。",al={"血蹄村在哪里","血蹄村位置","如何找到 查尔·硬皮"}},{q="维持一个像样的营地需要烹饪技能吗？",a="虽然缝制皮革帐篷并不严格要求烹饪技能，但强烈建议任何露营者学习烹饪艺术。厨师会教旅行者如何点燃基本的营火，这对完成户外营地、温暖夜间空气以及在无人居住的土地上进行长途旅行时准备食物至关重要。",al={"露营需要烹饪吗","我需要烹饪吗","营火烹饪基础"}},{q="露营帐篷为旅行者提供什么好处？",a="露营帐篷提供了可靠的避难所，可以抵御边境地区严酷的天气，保护漫游者免受晴天烈日的炙烤，并在倾盆大雨中保持干爽。在制作精良的帐篷内休息，可以确保冒险者在探索遥远领土时保持精神饱满、警觉，并随时准备面对危险。",al={"露营帐篷的好处","为什么要制作帐篷","帐篷有什么用"}}},fp="27,181,28.219.0,28.228.0,17.253.0,42.140.0,51.167.0,44.162.0,42.141.0,35.247.0,56.202.0,53.147.0"}
P.entries["quest:97935"] = {n="Camping 101: Mining",s="《Camping 101: Mining》向矿工介绍了如何通过自身专业进行野外生存。通过寻找雷霆崖的布瑞克·石蹄，矿工可以学会制作一种特殊的磁石，从而增强在营火旁休息的冒险者的战斗力。",h="《Camping 101: Mining》向矿工介绍了如何通过自身专业进行野外生存。通过寻找雷霆崖的布瑞克·石蹄，矿工可以学会制作一种特殊的磁石，从而增强在营火旁休息的冒险者的战斗力。",kw={"布瑞克·石蹄","营地","营火","露营101: 采矿","磁石","采矿","雷霆崖"},ang={["faction:Horde"]="在矿工营火旁休息的部落远征队员会从准备好的磁石中获益，从而为即将到来的战斗增强他们的前线战斗人员。",["profession:Mining"]="矿工通过为远征营地准备磁石，学习如何将他们的采集工艺直接应用于野外生存。",["race:Tauren"]="这项指导会将矿工带到位于雷霆崖台地顶部的布瑞克·石蹄处，利用牛头人对石料和土木工艺的知识。"},sec={{t="大地上的诚实劳动",b="采矿或许缺乏高等奥术那样的华丽与优雅，但它依然是整个艾泽拉斯最基础、最诚实的劳动。从业者从深层的岩壁中开采出有用的矿物和致密的石料，为武器、护甲以及如今的实用野外工艺提供了必要的材料。通过露营工艺，矿工可以将开采出的石料塑造成坚固的增强道具，供他们在野外驻留时使用。"},{t="雷霆崖的磁石",b="对于那些寻求将自身专业转向生存之道的勘探者，雷霆崖的布瑞克·石蹄提供了专门的指导。一旦矿工展示出对矿镐的熟练运用，布瑞克就会传授如何塑形营地磁石的工艺。将这种石头放置在燃烧的篝火旁，它能为任何准备在战斗中挥舞利刃的人提供战斗活力和关键优势。"}},faq={{q="磁石对营地有什么作用？",a="放置在营地的制作磁石会散发出微妙的武力属性，为聚集在营火旁的战士和冒险者提供额外的战斗力和活力。",al={"磁石营地增益","磁石加成","磁石有什么作用"}},{q="布瑞克·石蹄是谁？",a="布瑞克·石蹄位于牛头人的主城雷霆崖。他指导经验丰富的矿工如何利用开采出的石料和矿石制作专业的露营工具。",al={"布瑞克·石蹄位置","布瑞克·石蹄在哪里","谁教授采矿露营物品"}},{q="矿工什么时候可以学习制作磁石？",a="矿工必须首先展示出其采矿专业的基础熟练度，布瑞克·石蹄才会教授他们构建磁石所需的技术。",al={"什么时候可以学习磁石","磁石采矿技能要求"}},{q="谁能从矿工的磁石中获益最大？",a="任何需要挥舞武器的人都能从磁石的存在中获益，因为当物理战斗者在其身旁休息时，它散发出的影响能提供额外的战斗力量。",al={"谁能从磁石中获益","磁石适合近战吗"}},{q="采矿与建立营地有何关联？",a="除了为熔炼炉和铁匠提供原始金属外，采矿还允许野外旅行者制作诸如磁石之类的坚固石制工具，从而加强野外生存营地的功能。",al={"为什么为了露营而采矿","采矿如何帮助露营"}},{q="《露营 101: 采矿》的目的是什么？",a="《露营 101: 采矿》是一份指导指令，旨在引导有志向的矿工前往雷霆崖，以便他们学习制作适用于野外生存的实地工具。",al={"露营 101: 采矿概览","什么是露营 101: 采矿"}}},fp="19,171,25.301.0,30.269.0,42.90.0,22.126.0,48.106.0,43.101.0,49.137.0,43.109.0"}
P.entries["quest:97936"] = {n="Camping 101: Skinning",s="《露营指南：剥皮》指引熟练的剥皮者前往血蹄村，以拓展他们的实际野外生存技能。在姚恩·深刺的指导下，剥皮者学会了将野兽毛皮制成舒适的营地椅子，用于野外生存。这项训练强调了当深入远离文明安全区的地方旅行时，休息与准备的重要性。",h="《露营指南：剥皮》指引熟练的剥皮者前往血蹄村，以拓展他们的实际野外生存技能。在姚恩·深刺的指导下，剥皮者学会了将野兽毛皮制成舒适的营地椅子，用于野外生存。这项训练强调了当深入远离文明安全区的地方旅行时，休息与准备的重要性...",kw={"血蹄村","营地椅子","营火","露营指南","露营101: 剥皮","莫高雷","剥皮","姚恩·深刺"},ang={["faction:Horde"]="在莫高雷活动的部落剥皮者可以造访血蹄村，学习如何用他们收集的兽皮制作实用的露营装备。",["profession:Cooking"]="一个像样的营地需要温暖的营火来搭配座位，世界各地的烹饪训练师都可以教冒险者如何生火。",["race:Tauren"]="姚恩·深刺在莫高雷中心地带教导剥皮者如何用兽皮制作舒适的椅子，以便在野外休息。"},sec={{t="荒野之皮",b="采集倒下野兽的兽皮和毛皮是艾泽拉斯最实用的生存技能之一。除了鞣制皮革以制作护甲和装备外，一个足智多谋的剥皮者还能将粗糙的兽皮变成野外舒适用品。对于那些花上数周时间穿越荒野的旅行者来说，学会如何将兽皮加工成休息装备，是避免精疲力竭与在战斗中保持敏锐的关键区别。"},{t="血蹄村的课程",b="在莫高雷，剥皮者会被指引前往血蹄村与姚恩·深刺交谈。一旦剥皮者展现出采集兽皮的基本功底，姚恩就会传授缝制营地椅子的工艺。城镇和村庄里的居民不欢迎旅行者在街道中央扎营，因此这些椅子是专门为野外使用而设计的，并搭配由当地厨师传授的噼啪作响的营火。"}},faq={{q="什么是《露营指南：剥皮》？",a="《露营指南：剥皮》是一项入门任务，指引熟练的剥皮者在莫高雷寻找专门的导师。在展示了采集兽皮的技能后，剥皮者将学习如何制作营地椅子来布置他们的野外营地。",al={"什么是露营指南剥皮","露营剥皮任务","这个任务有什么用"}},{q="谁传授营地椅子配方？",a="驻扎在莫高雷血蹄村的剥皮训练师姚恩·深刺，会在冒险者证明了采集兽皮的熟练度后，传授制作营地椅子的技术。",al={"谁教营地椅子","露营剥皮找谁","姚恩·深刺在哪里"}},{q="营地椅子有什么用途？",a="营地椅子为在野外扎营时提供了一个舒适的休息场所。花时间坐下来放松有助于冒险者恢复体力，并保持最佳状态以迎接即将到来的战斗。",al={"营地椅子有什么用","营地椅子使用","为什么要制作营地椅子"}},{q="在哪里可以扎营？",a="城镇居民不欢迎旅行者在定居点中间扎营。冒险者必须前往荒野去扎营并测试他们制作的装备。",al={"在哪里可以扎营","可以在镇里扎营吗","城市里的营地椅子"}},{q="扎营还需要什么？",a="没有熊熊燃烧的营火，营地就不完整。冒险者在建立营地之前必须先升起一堆火，这是一项通常由烹饪训练师和厨师传授的基本技能。",al={"扎营还需要什么","需要营火","扎营需要生火吗"}},{q="血蹄村在哪里？",a="血蹄村是位于莫高雷风吹草动的平原上的一个主要牛头人定居点，这里居住着各种各样的商人和工匠，包括剥皮训练师。",al={"血蹄村在哪里","血蹄村位置"}}},fp="21,192,17.269.0,28.353.0,30.131.0,34.137.0,30.139.0,28.98.0,39.90.0,35.110.0"}
P.entries["quest:97938"] = {n="Camping 101: Alchemy",s="Camping 101: Alchemy 是一项引导任务，它将基础的药水制作与野外生存结合了起来。炼金师会被指引前往多兰纳尔寻找辛达·轻语，学习如何为营地搭建一座清凉的法力之井，为旅行中的施法者和治疗者提供关键的魔法补充。",h="Camping 101: Alchemy...",kw={"炼金","营地","露营101","露营101: 炼金术","辛达·轻语","多兰纳尔","法力之井","泰达希尔"},ang={["faction:Alliance"]="在泰达希尔冒险的联盟炼金师会被直接引导至多兰纳尔，通过魔法营地设施提升他们的野外生存技能。",["race:NightElf"]="在多兰纳尔工作的暗夜精灵草药师和炼金师将自然植物学与野营技艺相结合，以支持野外的施法者。"},sec={{t="炼金师的野外技艺",b="Camping 101: Alchemy 指导炼金师学员将他们的药水制作技巧应用到旅途中。冒险者们不再仅仅是在实验室的玻璃器皿中酿制药剂，而是学会创建野外设施，在漫长的荒野旅途中为旅行小队提供支持。"},{t="多兰纳尔的法力之井",b="该任务指示冒险者在展现出初步的专业能力后，前往多兰纳尔寻找辛达·轻语。她会传授在营地搭建法力之井的技术，这是一种专门为帮助远离城镇和定居点的法力依赖型治疗者和施法者而设计的清凉之泉。"}},faq={{q="什么是 露营 101: 炼金术？",a="露营 101: 炼金术 是一项指导任务，引导炼金新手前往多兰纳尔。它教授旅行者如何将药水制作技巧应用于在荒野中建立功能性的营地设施。",al={"什么是 露营 101 炼金术","露营 101 炼金术 任务","炼金营地任务"}},{q="谁教授这项野营技能？",a="辛达·轻语是一位炼金训练师，位于泰达希尔的多兰纳尔。她会指导那些在酿造和制作专业野营物品方面展现出足够能力的从业者。",al={"辛达·轻语是谁","辛达·轻语位置","辛达·轻语在哪里"}},{q="什么是法力之井？",a="法力之井是炼金师为营地制作的一种专业野外设施。它提供了一种清凉的奥术恢复源，能够吸引需要在旅途中补充魔法储备的施法者和治疗者。",al={"法力之井有什么作用","法力之井营地物品","法力之井背景故事"}},{q="这个任务会将你带到哪里？",a="多兰纳尔是位于泰达希尔中部的一个暗夜精灵村庄，是年轻冒险者在离开幽影谷后的重要枢纽和商业技能训练中心。",al={"多兰纳尔在哪里","如何前往多兰纳尔","多兰纳尔位置"}},{q="谁能从炼金师的营地设施中获益？",a="治疗者和旅行中的施法者最能从法力之井中获益，因为这些召唤或酿造的泉水在远离城镇的艰苦旅程中能提供至关重要的恢复与补给。",al={"谁能从法力之井获益","谁使用法力之井","法力之井施法者"}},{q="学习制作法力之井需要什么条件？",a="炼金师必须先证明自己在基础酿造和药水制作方面的熟练度，辛达·轻语才会教授他们组装法力之井之类的野营设施。",al={"我什么时候可以学习法力之井","露营 101 要求","所需的技能熟练度"}}},fp="20,198,26.192.0,25.227.0,29.165.0,31.182.0,20.155.0,31.144.0,51.140.0,54.154.0"}
P.entries["quest:97940"] = {n="Camping 101: Enchanting",s="神谕林地的一份指南指引你学习一门适合露营的附魔技艺。附魔的鲁特琴能在野外驻留时带来乐趣。",h="神谕林地的一份指南指引你学习一门适合露营的附魔技艺。附魔的鲁特琴能在野外驻留时带来乐趣。",kw={"alanna raveneye","露营工艺","露营","附魔的鲁特琴","附魔","神谕林地","泰达希尔"},ang={["profession:Tailoring"]="身为附魔师，只要展现出娴熟的技艺，你就能学会为营地制作附魔的鲁特琴。"},sec={{t="露营工艺",b="附魔师能为营地制作实用的物品，而你被指引去神谕林地寻找Alanna Raveneye。只要你展现出娴熟的技艺，她就能教你制作附魔的鲁特琴。这件物品能让你在再次踏上旅途前的闲暇时光里享受乐趣。"}},faq={{q="谁能教我制作附魔的鲁特琴？",a="只要你展现出娴熟的技艺，神谕林地的Alanna Raveneye就能教你制作附魔的鲁特琴。",al={"alanna raveneye","谁教制作鲁特琴","鲁特琴训练师"}},{q="附魔的鲁特琴有什么用？",a="附魔的鲁特琴是一件露营用品，能在野外的闲暇时光里带来乐趣。",al={"鲁特琴用途","露营鲁特琴","附魔的鲁特琴有何用"}},{q="为什么营地欢迎附魔师？",a="附魔师能让东西变得更好，因此在野外营地很受欢迎。",al={"附魔师露营","附魔营地","露营附魔"}},{q="我在哪里能学到这门露营技艺？",a="你可以向泰达希尔神谕林地的Alanna Raveneye学习。",al={"神谕林地训练师","alanna在哪里","附魔地点"}}},fp="23,152,12.295.0,36.123.0,31.97.0,36.76.0,36.69.0"}
P.entries["quest:97942"] = {n="Camping 101: First Aid",s="《Camping 101: 急救》向冒险者介绍了野外生存的基础，教导他们如何为营地制作简易的急救包。本课程由多兰纳尔的拜恩希指导，强调了远离城镇诊所时的自给自足与实用分诊能力。",h="《Camping 101: 急救》向冒险者介绍了野外生存的基础，教导他们如何为营地制作简易的急救包。本课程由多兰纳尔的拜恩希指导，强调了远离城镇诊所时的自给自足与实用分诊能力。",kw={"拜恩希","篝火","露营","多兰纳尔","野外军医","急救","急救包","猎人"},ang={["class:Hunter"]="对于那些需要长时间在外追踪野兽、远离文明社会的猎人来说，将野外生存技能与急救相结合，让他们无需依赖城镇的治疗师即可处理伤势。",["profession:Cooking"]="营地生活既需要食物也需要温暖，因此基础的烹饪训练对于学习如何点燃所需的篝火至关重要。"},sec={{t="野外实地医疗",b="深入荒野意味着时刻面临危险，无论是猛兽的撕咬还是崎岖的地形。对于游侠和野外旅行者而言，他们无法总是等待回到城镇才能获得医疗补给。学习制作专用的急救包可以将简单的路边休息点变成功能性的野外工作站，确保轻微的擦伤在露天环境下不会恶化成致命伤。"},{t="多兰纳尔的课程",b="拜恩希位于多兰纳尔绿荫掩映的凉亭中，她指导那些在分诊方面受过训练的旅行者，教他们如何打包适合艰苦野外生活的医疗补给。设置这类装备需要尊重当地定居点；城镇居民不会容忍在城镇中心搭建帐篷和随意堆放补给品，因此露营者必须前往森林深处才能建立营地。"},{t="营地的炉火",b="每个功能完备的营地都始于一团营火。在放下急救包或铺盖之前，冒险者必须先点燃篝火以获取温暖和保护。由于生火与维持火势是野外生存的基础，训练师建议在尝试维持野外营地之前，先向厨师请教并掌握生火的艺术。"}},faq={{q="拜恩希是谁？",a="拜恩希是位于泰达希尔的多兰纳尔定居点的一名导师。她专门指导那些在医疗技能方面展现出熟练度的冒险者，教他们如何组装用于野外露营的专用急救包。",al={"拜恩希是谁","拜恩希的位置","拜恩希在哪里"}},{q="什么是露营急救包？",a="急救包是由受过医疗训练的冒险者制作的一种专业露营工具。当它被放置在建立好的营地时，它会提供一个专门的工作站，用于在野外治疗伤口并提供必要的医疗救护。",al={"什么是急救包营地","急救包如何运作","露营急救包"}},{q="在哪里可以搭建营地？",a="定居点的居民和卫兵对旅行者在城市广场或定居点中心搭建临时营地的行为表示不满。营地必须建立在远离城镇边界的开阔荒野中。",al={"我可以在城镇里露营吗","为什么要到城镇外露营","露营规则"}},{q="为什么营地需要篝火？",a="篝火是任何野外营地的核心基础，它提供热量、照明和安全保障。冒险者通常从烹饪训练师和厨师那里学习如何点燃基础篝火。",al={"我为什么需要篝火","烹饪篝火营地","篝火需求"}},{q="为什么急救被认为对猎人很有实用价值？",a="猎人经常独自在偏远的荒野中活动，远离已知的治疗师或圣殿骑士。掌握野外分诊和绷带制作技术，可以确保他们在追踪猎物或遭遇伏击时能够自给自足。",al={"为什么猎人需要急救","猎人治疗"}},{q="如何学习制作露营急救包？",a="冒险者必须首先展示出在急救学科方面的基本熟练度，之后多兰纳尔的拜恩希便可传授他们组装露营急救包所需的具体技术。",al={"如何获得急救包","学习急救包制作"}}},fp="22,148,27.249.0,19.239.0,22.284.0,15.151.0,32.180.0,28.150.0,38.116.0,50.152.0,50.113.0"}
P.entries["quest:97943"] = {n="Camping 101: Fishing",s="《Camping 101: Fishing》为垂钓者介绍了荒野生活的舒适艺术，教导他们为营地制作装饰性的鱼缸。来到达纳苏斯寻找阿斯塔娅的钓鱼好手们会学到，生活中的一点小乐趣就能鼓舞冒险者的士气，并增强在荒野中的作战能力。",h="《Camping 101: Fishing》为垂钓者介绍了荒野生活的舒适艺术，教导他们为营地制作装饰性的鱼缸。来到达纳苏斯寻找阿斯塔娅的钓鱼好手们会学到，生活中的一点小乐趣就能鼓舞冒险者的士气，并增强在荒野中的作战能力。",kw={"阿斯塔娅","营火","露营","露营101: 钓鱼","营地","达纳苏斯","鱼缸","钓鱼"},ang={["faction:Alliance"]="阿斯塔娅居住在达纳苏斯，这使得这座暗夜精灵的主城成为了联盟垂钓者扩展营地工艺的主要目的地。",["profession:Cooking"]="营地需要适当的营火才能建立，这使得基础烹饪训练成为垂钓者户外避难所的重要伙伴。"},sec={{t="营地的舒适",b="在卡利姆多旅行的垂钓者经常发现，水边安静的时光能起到更大的作用。在达纳苏斯，技师阿斯塔娅会向经验丰富的钓鱼者展示如何将渔获和技艺转化为营地设施，特别是制作可在营地展示的鱼缸。这件装饰品能为旅途劳顿的旅行者提供舒适和欢乐。"},{t="荒野必需品",b="建立一个像样的荒野避难所需要的不仅仅是钓鱼装备。营地不能设在拥挤的市中心或城区，冒险者需要前往开阔的户外。此外，每个营地的基础都需要一个温暖的营火，因此冒险者在入夜休息前，需要先拜访当地的烹饪训练师，掌握基本的生火技能。"}},faq={{q="谁教你制作钓鱼用的露营物品？",a="阿斯塔娅位于达纳苏斯。一旦垂钓者展现出足够的钓鱼水平，阿斯塔娅就会教他们如何为营地制作装饰性的鱼缸。",al={"谁教授营地钓鱼","阿斯塔娅在哪里","鱼缸训练师"}},{q="鱼缸在营地里有什么用？",a="鱼缸是营地设施，旨在为休息的冒险者带来舒适和快乐。快乐且休息充分的露营者战斗时会更有活力，这对户外探险直接有利。",al={"鱼缸有什么用","营地鱼缸用途","鱼缸营地设施"}},{q="可以在达纳苏斯或其他城市设置营地吗？",a="营地不能搭建在定居点或城镇中心。要搭建营地并放置鱼缸之类的设施，旅行者必须前往荒野。",al={"可以在达纳苏斯露营吗","在哪里搭建营地","在城市中露营"}},{q="在搭建营地之前需要什么？",a="没有基础营火的营地是不完整的。建议旅行者在建立荒野营地之前，先寻找烹饪训练师学习如何生火。",al={"露营需要什么","如何开始露营","需要营火"}},{q="需要钓鱼技能才能学习制作鱼缸吗？",a="要从阿斯塔娅那里学习这项工艺，冒险者必须首先展现出垂钓专业的熟练度。",al={"露营钓鱼技能","什么时候可以学习鱼缸"}},{q="为什么冒险者要在荒野中搭建营地？",a="搭建营地为户外旅行者提供了休息之所和提振士气的设施，例如制作的鱼缸，确保冒险者在荒野探险期间保持充足的休息和能力。",al={"为什么要露营","露营的好处"}}},fp="20,180,23.262.0,22.270.0,55.129.0,44.133.0,55.148.0,42.134.0,60.96.0,44.157.0"}
P.entries["quest:97944"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism向采集者介绍了该专业在野外生存方面的实用应用。通过拜访多兰纳尔的玛洛尼·刃叶，熟练的草药师可以学会制作舒缓的熏香蜡烛，从而为营火旁的治疗者和施法者提供辅助。",h="Camping 101: Herbalism向采集者介绍了该专业在野外生存方面的实用应用。通过拜访多兰纳尔的玛洛尼·刃叶，熟练的草药师可以学会制作舒缓的熏香蜡烛，从而为营火旁的治疗者和施法者提供辅助。",kw={"露营","露营101: 草药学","多兰纳尔","草药学","熏香蜡烛","玛洛尼·刃叶","泰达希尔"},ang={["faction:Alliance"]="在泰达希尔周围活动的联盟草药师会被指引前往多兰纳尔，向当地的暗夜精灵从业者学习专业的野外制作技术。",["profession:Herbalism"]="草药师们发现，采集植物不仅仅是为了炼金，还可以用于实际的荒野生存，提供原始的植物原料来制作像熏香蜡烛这样的营地用品。",["race:NightElf"]="暗夜精灵早已了解自然草药的氛围和恢复特性，并在多兰纳尔这样的定居点分享这些传统。"},sec={{t="不仅仅是采花",b="草药学远不止是在草地上漫步采摘花朵。虽然采集者通常会出售他们的发现或供应给炼金术师，但经验丰富的荒野旅行者知道，野生植物可以直接制作成有价值的营地装备。学习如何将收获的植物用于生存目的，可以确保采集的产出直接支持在野外的长途跋涉。"},{t="多兰纳尔的舒缓之火",b="在多兰纳尔定居点，一位名叫玛洛尼·刃叶的导师会教导精通草药学的玩家如何制作熏香蜡烛。这些芳香的蜡烛可以在营火周围营造一个专注、精神振奋的避风港，为治疗者和施法者在危险间隙恢复魔法能量时提供一种令人恢复活力的氛围。"}},faq={{q="这个任务的目的是什么？",a="露营 101: 草药学是一项入门级的专业任务，旨在指导熟练的采集者学习专业的荒野工艺。它引导草药师学习如何利用他们在野外采集的植物来制作营地用品。",al={"什么是露营 101 草药学","草药学营地任务"}},{q="熏香蜡烛对营地有什么作用？",a="熏香蜡烛可以在营地提供一种令人振奋的氛围，振奋精神并提供一种舒缓的增益，施法者和治疗者在维持魔法专注时非常依赖这种增益。",al={"熏香蜡烛的作用","熏香蜡烛的好处"}},{q="谁是玛洛尼·刃叶？",a="玛洛尼·刃叶是一位居住在多兰纳尔的导师，他拥有制作草药师营地补给品的知识，专门指导精通采集的玩家制作熏香蜡烛。",al={"谁教授熏香蜡烛制作","谁是玛洛尼·刃叶","多兰纳尔的刃叶"}},{q="这个任务会把你带到哪里？",a="多兰纳尔是位于泰达希尔岛上的一个暗夜精灵定居点，是旅行者、训练师和林地工匠的区域中心。",al={"多兰纳尔在哪里","多兰纳尔位置"}},{q="为什么熏香蜡烛对魔法使用者有用？",a="治疗者和施法者最能直接受益于熏香蜡烛所营造的宁静、专注的环境，这有助于他们在荒野探险期间补充精力和恢复魔法意志。",al={"谁能从熏香蜡烛中受益","熏香蜡烛是给施法者用的吗"}},{q="玛洛尼·刃叶教你之前有什么要求？",a="采集者必须在草药学方面表现出足够的实际技能和熟练度，玛洛尼·刃叶才会愿意分享制作营地用品的工艺。",al={"什么时候可以学习熏香蜡烛","营地任务的草药学技能要求"}}},fp="22,203,25.245.0,30.276.0,34.112.0,42.93.0,25.106.0,31.118.0,46.155.0,57.107.0"}
P.entries["quest:97946"] = {n="Camping 101: Leatherworking",s="《露营基础：制皮》向泰达希尔的熟练工匠们介绍了户外生存帐篷的制作技艺。通过寻找在多兰纳尔和达纳苏斯之间道路上的纳迪亚·织鬃（纳迪娅·织发），制皮师们可以学会制作耐用的帐篷，保护旅行者免受荒野旅途中的恶劣天气侵袭。",h="《露营基础：制皮》向泰达希尔的熟练工匠们介绍了户外生存帐篷的制作技艺。通过寻找在多兰纳尔和达纳苏斯之间道路上的纳迪亚·织鬃（纳迪娅·织发），制皮师们可以学会制作耐用的帐篷，保护旅行者免受荒野旅途中的恶劣天气侵袭。",kw={"营火","露营","达纳苏斯","多兰纳尔","制皮","纳迪亚·织鬃","帐篷","荒野"},ang={["class:Rogue"]="在荒野中穿行的潜行者依靠良好的休息和庇护所来保持敏锐，这使得个人皮革帐篷成为不可或缺的生存工具。",["profession:Cooking"]="建立一个合格的营地需要温暖的营火，这是通过各地的烹饪训练师传授的一项基本技能。"},sec={{t="荒野中的庇护所",b="对于在卡利姆多的荒野中跋涉的冒险者来说，露宿野外意味着要应对突如其来的暴雨或烈日灼烤等严酷挑战。熟练的制皮师被传授如何利用兽皮和毛皮制作耐用的庇护所，让旅行者无论走到哪里都能建立一个可靠的栖身之所。通过制作个人露营帐篷，游荡者可以确保获得必要的休息，在远离城镇旅店安全区的地方，依然能保持敏锐的反应和清晰的头脑。"},{t="多兰纳尔之路",b="在蜿蜒于多兰纳尔定居点与达纳苏斯枝干之间的林间道路上，纳迪亚·织鬃（纳迪娅·织发）为高阶制皮师提供指导。她传授缝制适合野外生活、坚固耐用帐篷的技艺。然而，仅有一个帐篷并不能构成一个功能齐备的营地；旅行者还必须知道如何点燃营火——这是一项由厨师传授的基础生存技能，并且必须记住在广阔的荒野中搭建帐篷，而不是在城镇街道上造成阻碍。"}},faq={{q="谁传授这项露营技能？",a="该任务指引渴望进阶的制皮师前往泰达希尔，在从多兰纳尔通往达纳苏斯的路上与纳迪亚·织鬃（纳迪娅·织发）交谈。",al={"谁给予露营基础制皮任务","谁传授露营基础","纳迪亚·织鬃"}},{q="制皮师能从这个任务中学到什么？",a="它指导制皮师如何制作他们自己的露营帐篷，旨在让旅行者在野外炎热的白天保持凉爽，并在雨天保持干爽。",al={"露营基础传授什么","帐篷配方","我能从露营基础中学到什么"}},{q="在哪里可以搭建露营帐篷？",a="帐篷不能在定居点或城市中心内搭建，因为镇民不喜欢在镇中心看到营地。旅行者必须前往城镇之外的广阔荒野中设置他们的营地。",al={"我在哪里可以搭建帐篷","我能在镇里搭建帐篷吗","城市里露营"}},{q="设置营地还需要什么？",a="每个合格的营地在建立之前，除了帐篷外还需要一堆点燃的营火。基础营火的制作通常可以向烹饪训练师学习。",al={"建立营地需要什么","营火需求","搭建帐篷需要营火吗"}},{q="为什么帐篷对旅行者有用？",a="可靠的帐篷能提供避风港，确保冒险者获得充足的休息，从而在远离旅店的旅途中保持警觉和敏锐。",al={"为什么要建造帐篷","帐篷休息增益","为什么要露营"}},{q="纳迪亚·织鬃（纳迪娅·织发）在哪里？",a="纳迪亚·织鬃（纳迪娅·织发）位于从多兰纳尔村通往暗夜精灵主城达纳苏斯的主干道上。",al={"纳迪亚·织鬃在哪里","纳迪亚位置","通往达纳苏斯之路的训练师"}}},fp="27,210,25.256.0,22.297.0,31.104.0,45.97.0,32.73.0,39.94.0,42.102.0,35.95.0"}
P.entries["quest:97948"] = {n="Camping 101: Mining",s="“Camping 101: Mining”是一项入门任务，指引矿工前往奥伯丁寻找库德拉姆·石锤。通过展示他们的专业技能，矿工们可以学习制作营地磁石，从而增强在篝火旁休息的盟友的战斗能力。",h="“Camping 101: Mining”是一项入门任务，指引矿工前往奥伯丁寻找库德拉姆·石锤。通过展示他们的专业技能，矿工们可以学习制作营地磁石，从而增强在篝火旁休息的盟友的战斗能力。",kw={"奥伯丁","野营工艺","篝火","露营101: 采矿","黑海岸","库德拉姆·石锤","磁石","采矿"},ang={["faction:Alliance"]="库德拉姆·石锤在黑海岸的奥伯丁海岸边提供指导，这使得经过卡利姆多北部的联盟旅行者可以轻松获得这项野营工艺。",["profession:Mining"]="矿工可以利用矿物工艺来帮助路上的旅行者，将粗糙的石头变成实用的营地磁石，从而增强前线战士的能力。"},sec={{t="土石的实用艺术",b="采矿是一项艰苦而诚实的劳动，但它的用途远不止于冶炼矿锭和锻造护甲。经验丰富的勘探者可以将原始矿石和磁性矿石塑造成专门的野营装备，让旅行者能够在荒野中建立坚固的营地。“Camping 101: Mining”向矿工介绍了这项技艺的实际应用。"},{t="奥伯丁的导师",b="该任务指引有前途的矿工前往黑海岸熙熙攘攘的沿海避风港——奥伯丁，寻找库德拉姆·石锤。一旦矿工证明了自己的奉献精神和技能，库德拉姆就会传授制作营地磁石的方法。将磁石放置在火堆旁，它会散发出一种强化的气息，提升附近聚集的近战同伴的战斗力。"}},faq={{q="什么是“露营 101: 采矿”？",a="“露营 101: 采矿”指引矿工前往港口城镇奥伯丁寻找库德拉姆·石锤。一旦你展现出了采矿方面的专业能力，他就会教你如何制作一种特殊的磁石来增强营地效果。",al={"这个任务是什么","露营 101: 采矿 目标","露营 101: 采矿 我该做什么"}},{q="库德拉姆·石锤是谁？",a="库德拉姆·石锤是一位位于黑海岸沿岸奥伯丁的专家工匠。他会指导合格的矿工如何制作营地辅助物品，特别是磁石。",al={"库德拉姆·石锤是谁","奥伯丁采矿训练师","库德拉姆·石锤位置"}},{q="什么是营地磁石？",a="磁石是由矿工为营地制作的物品。当竖立在篝火旁时，它能提供一种令人振奋的气息，使物理战斗者获得额外的力量和战斗能力。",al={"磁石有什么用","营地磁石效果","野营加成增益"}},{q="这个任务发生在哪里？",a="奥伯丁是黑海岸的一个沿海港口定居点，也是卡利姆多北部联盟的主要港口和交通枢纽。库德拉姆·石锤居住在那里，指导有抱负的矿工学习野营工艺。",al={"奥伯丁在哪里","奥伯丁位置","如何前往奥伯丁"}},{q="谁能从营地磁石中受益？",a="磁石特别受到那些在近距离挥舞刀剑和武器的近战战士的青睐，因为当他们在火堆旁休息时，其共鸣力量能为战斗型旅行者提供增强的活力。",al={"谁能从磁石中受益","磁石对战士有用吗","营地磁石增益目标"}},{q="什么时候可以学习制作磁石？",a="你必须在采矿行业表现出足够的专业能力，库德拉姆·石锤才会与你分享制作营地磁石的秘密。",al={"什么时候可以学习磁石","制作营地磁石的采矿等级","专业技能要求"}}},fp="19,180,36.263.0,21.270.0,28.148.0,27.146.0,25.105.0,33.159.0,35.134.0,42.88.0"}
P.entries["quest:97949"] = {n="Camping 101: Skinning",s="《Camping 101: Skinning》指导野外旅行者如何制作他们自己的便携式营地椅子。它强调了户外生存的基础知识，提醒冒险者们，一个合适的营地需要远离城镇，并生起一堆营火。",h="《Camping 101: Skinning》指导野外旅行者如何制作他们自己的便携式营地椅子。它强调了户外生存的基础知识，提醒冒险者们，一个合适的营地需要远离城镇，并生起一堆营火。",kw={"营地椅子","营火","露营101","露营101: 剥皮","烹饪","剥皮","荒野"},ang={["profession:Cooking"]="建议露营者向烹饪训练师学习基本的烹饪，因为知道如何生火对于在荒野中建立一个合适的营地至关重要。"},sec={{t="旅途的舒适",b="《Camping 101: Skinning》向户外爱好者和剥皮者介绍了荒野生存的技艺。通过将采集到的毛皮和材料投入实际用途，旅行者们可以学会为他们的旅途制作一把便携式的营地椅子。冒险者们不应在繁忙的城市中心造成拥堵——当地人会反对搭建营地——而应该将他们的技艺带到艾泽拉斯广阔的荒野中去。"},{t="必不可少的营火",b="在荒野中，如果没有一堆温暖的营火，任何营地都无法正常运作。建立营地首先需要生火，以提供热量并抵御风雨。尚未掌握基本烹饪技能的新手生存者，建议去拜访一位烹饪训练师，他们可以教导如何在野外任何地方生火的基本技艺。"}},faq={{q="从《露营 101: 剥皮》中你能学到什么？",a="完成这项任务将教你如何制作自己的营地椅子，这是在荒野中休息时必不可少的舒适装备。",al={"我能得到什么","露营 101奖励什么","制作营地椅子"}},{q="可以在城镇里建立营地吗？",a="城镇居民通常不欢迎旅行者在城镇广场或城市街道上扎营。你需要前往荒野才能正确地搭建你的营地。",al={"可以在城里扎营吗","在暴风城搭帐篷","在城市内扎营"}},{q="建立营地需要营火吗？",a="一个合适的营地在建立之前需要先点燃营火。基本的生火技巧可以从艾泽拉斯各地的烹饪训练师那里学到。",al={"扎营需要火吗","如何制作营火","营地椅子的火"}},{q="在哪里可以学会如何生火？",a="大多数烹饪导师和烹饪训练师都能教你基本的食物烹饪方法，其中就包括如何用简单的火石和木材生起一堆营火。",al={"谁教导营火","烹饪营火训练师","哪里学习烹饪营火"}},{q="为什么必须前往荒野扎营？",a="荒野提供了足够的空地，可以在不打扰城镇居民或阻塞当地道路和定居点的情况下扎营。",al={"为什么需要荒野","我在哪里可以使用营地椅子","在哪里扎营"}},{q="剥皮与制作营地椅子有什么关系？",a="剥皮者使用从野兽身上获取的皮革和毛皮，这些材料非常适合拉伸和缝制成营地椅子这样便携的户外座椅。",al={"剥皮与露营的关系","为什么椅子需要剥皮","剥皮营地椅子"}}},fp="21,132,21.243.0,22.217.0,45.70.0,30.105.0,36.98.0,43.95.0,53.124.0,48.118.0"}
P.entries["quest:97950"] = {n="Camping 101: Tailoring",s="裁缝可以学习为营地制作Rallying Banner。只要你展现出裁缝技艺，达纳苏斯的Trianna就会传授这张图样。",h="裁缝可以学习为营地制作Rallying Banner。只要你展现出裁缝技艺，达纳苏斯的Trianna就会传授这张图样。",kw={"营火","扎营","达纳苏斯","阵营旗帜","rallying banner","裁缝","trianna"},ang={["profession:Tailoring"]="身为裁缝，只要展现出娴熟的技艺，你就可以学习为自己的营地制作Rallying Banner。"},sec={{t="营地旗帜",b="一位看重裁缝技艺的人指引你去找达纳苏斯的Trianna。只要你展现出娴熟的裁缝技艺，她就能教你为营地制作阵营旗帜。旗帜能在战场上鼓舞斗志、提振士气，技艺娴熟的裁缝也能掌握这门手艺。"},{t="搭建营地",b="在Trianna的教导下，你可以制作Rallying Banner。要试用它，就去野外找个地方，因为大多数人都不喜欢有人在城镇中央扎营。也要备好营火；厨师可以教你如何生火。"}},faq={{q="谁会教裁缝制作营地旗帜？",a="只要你展现出娴熟的裁缝技艺，达纳苏斯的Trianna就能教你为营地制作阵营旗帜。",al={"裁缝旗帜教师","trianna裁缝","营地旗帜训练师"}},{q="裁缝能为营地制作什么？",a="技艺娴熟的裁缝可以学习为营地制作Rallying Banner。",al={"裁缝营地物品","裁缝营地制作","裁缝制作什么旗帜"}},{q="为什么要制作Rallying Banner？",a="鼓舞人心的旗帜能帮助你保持精神振奋，而斗志和士气在战场上十分重要。",al={"旗帜用途","为何制作rallying banner","旗帜士气"}},{q="我可以在哪里试着搭建营地？",a="完成时的建议是去野外试用旗帜，因为大多数人都不喜欢有人在城镇中央扎营。",al={"哪里试用旗帜","扎营地点","旗帜试用地点"}},{q="我需要营火吗？",a="营地需要营火，大多数厨师都能教你如何生火。",al={"营地营火","是否需要生火","如何生营火"}}},fp="22,137,17.279.0,15.217.0,36.115.0,34.65.0,27.104.0,31.114.0,21.66.0"}
P.entries["quest:97951"] = {n="Camping 101: Alchemy",s="作为一名炼金师，你可以学习为营地制作法力之井。你在布瑞尔向卡罗莱·安尼斯证明自己的炼金技艺后，她就会教你。",h="作为一名炼金师，你可以学习为营地制作法力之井。你在布瑞尔向卡罗莱·安尼斯证明自己的炼金技艺后，她就会教你。",kw={"炼金师","炼金术","布瑞尔","营地","篝火","露营入门","卡罗莱·安尼斯","法力之井"},sec={{t="药剂营地",b="卡罗莱·安尼斯可以教你制作法力之井，这是适合你这门专业的露营物品。学会制作后，你就能在野外扎营。扎营需要篝火，烹饪师可以教你如何制作篝火。"}},faq={{q="谁会教我制作法力之井？",a="你在炼金术方面证明自己的技艺后，布瑞尔的卡罗莱·安尼斯就会教你制作法力之井。",al={"法力之井训练师","谁教制作法力之井","卡罗莱·安尼斯炼金术"}},{q="法力之井有什么用？",a="法力之井是炼金师可以制作的露营物品。治疗者和施法者都喜欢它清爽的滋味。",al={"法力之井用途","法力之井有什么用","法力营地物品"}},{q="我在哪里能学会制作法力之井？",a="你可以向布瑞尔的卡罗莱·安尼斯学习制作方法。",al={"法力之井位置","布瑞尔炼金术训练师","卡罗莱在哪里"}},{q="开始扎营前需要准备什么？",a="扎营前需要准备篝火。大多数烹饪师都能教你制作篝火。",al={"需要篝火","如何扎营","露营基础"}}},fp="20,135,16.203.0,36.95.0,24.120.0,38.57.0,38.85.0"}
P.entries["quest:97952"] = {n="Camping 101: Blacksmithing",s="铁匠可以学习制作供营地使用的磨刀石。在你展现出熟练的技艺后，幽暗城的Basil Frye就能传授你这门手艺。",h="铁匠可以学习制作供营地使用的磨刀石。在你展现出熟练的技艺后，幽暗城的Basil Frye就能传授你这门手艺。",kw={"basil frye","锻造","营地","潜行者","磨刀石","幽暗城","战士"},ang={["class:Rogue"]="营地里的磨刀石能让你磨砺武器。",["class:Warrior"]="营地里的磨刀石能让你磨砺武器。",["profession:Blacksmithing"]="身为铁匠，你可以学习制作供营地使用的磨刀石。"},sec={{t="铁匠的营地",b="有人让你去找幽暗城的Basil Frye，打听一件与你的锻造技能有关的露营物品。你需要先展现出熟练的技艺，他才会教你制作磨刀石。在营地里，磨刀石能让附近的战士和潜行者磨砺武器。"}},faq={{q="Basil Frye能教我什么？",a="在你展现出熟练的锻造技艺后，Basil Frye就能教你制作供营地使用的磨刀石。",al={"basil frye 锻造","磨刀石","营地锻造物品"}},{q="磨刀石有什么用？",a="营地里的磨刀石能让附近的战士和潜行者磨砺武器。",al={"磨刀石作用","磨砺武器","磨刀石用途"}},{q="在哪里能找到Basil Frye？",a="Basil Frye在幽暗城。",al={"basil 位置","basil 在哪里","basil frye 幽暗城"}}},fp="26,152,14.264.0,29.119.0,32.83.0,27.27.0"}
P.entries["quest:97953"] = {n="Camping 101: Enchanting",s="附魔师展现出娴熟技艺后，可以与布瑞尔的范斯·安德格鲁姆交谈，学习为营地制作附魔的鲁特琴。",h="附魔师展现出娴熟技艺后，可以与布瑞尔的范斯·安德格鲁姆交谈，学习为营地制作附魔的鲁特琴。",kw={"布瑞尔","营地","露营入门","附魔的鲁特琴","附魔师","附魔","范斯·安德格鲁姆"},ang={["profession:Tailoring"]="作为一名附魔师，展现出娴熟技艺后，你可以学习为营地制作附魔的鲁特琴。"},sec={{t="营地伴侣",b="野外营地欢迎附魔师。你可以学习制作附魔的鲁特琴，为远离旅途的闲暇时光增添乐趣。"}},faq={{q="我能学会制作什么？",a="你可以学习为营地制作附魔的鲁特琴。",al={"附魔的鲁特琴","露营附魔物品","范斯 教什么"}},{q="谁会教我制作鲁特琴？",a="布瑞尔的范斯·安德格鲁姆可以教你制作附魔的鲁特琴。",al={"范斯 是谁","范斯·安德格鲁姆","鲁特琴导师"}},{q="我在哪里能找到范斯·安德格鲁姆？",a="范斯·安德格鲁姆在布瑞尔。",al={"范斯 在哪里","范斯 所在位置","布瑞尔附魔师"}},{q="和范斯交谈前，我需要做什么？",a="学习制作这件露营物品前，你需要展现出娴熟技艺。",al={"技能要求","展现娴熟技艺","附魔要求"}},{q="为什么要带附魔的鲁特琴去营地？",a="附魔的鲁特琴能为你在营地的闲暇时光增添乐趣。",al={"鲁特琴用途","营地娱乐","为何需要附魔的鲁特琴"}}},fp="23,120,16.147.0,26.55.0,30.67.0,33.29.0,42.74.0,36.61.0"}
P.entries["quest:97955"] = {n="Camping 101: First Aid",s="《露营基础：急救》指引有医学背景的冒险者前往布瑞尔寻找护士妮拉。通过学习制作适合营地的急救包，旅行者可以在荒野深处生存时提供救命的治疗和休养。",h="《露营基础：急救》指引有医学背景的冒险者前往布瑞尔寻找护士妮拉。通过学习制作适合营地的急救包，旅行者可以在荒野深处生存时提供救命的治疗和休养。",kw={"布瑞尔","营火","露营","露营基础","急救","急救包","护士妮拉","提瑞斯法林地"},ang={["faction:Horde"]="护士妮拉在提瑞斯法林地的被遗忘者定居点布瑞尔开展工作，这使得该指导成为部落冒险者的一项重要本地资源。",["profession:Cooking"]="烹饪导师教授点燃基础营火的艺术，这是在添加医疗设施之前建立任何荒野营地的必要条件。",["race:Undead"]="护士妮拉常驻布瑞尔，帮助被遗忘者及其盟友调整医疗技能，以适应洛丹伦废墟景观中的生存需求。"},sec={{t="野外医疗",b="冒险进入防御城镇之外的地区总是伴随着持续的身体危险，从敌对野兽到敌对阵营皆是如此。对于急救专业的旅行者来说，学习组装专用的急救包可以让普通的荒野休息站变成移动的野战医院，在远离文明基础设施的地方包扎伤口并恢复生命力。"},{t="布瑞尔的指导",b="在被遗忘者城镇布瑞尔，护士妮拉提供如何将基础医学知识转化为实用营地装备的指导。一旦旅行者表现出足够的绷带和治疗技巧，她就会传授制作便携式急救包所需的技能。设置此类装备需要一个以基础营火为中心的合适的荒野营地，标准的烹饪导师可以教导旅行者建造营火。"}},faq={{q="护士妮拉是谁？",a="护士妮拉是一位位于提瑞斯法林地被遗忘者定居点布瑞尔的医疗从业者。她指导熟练的急救专业人士如何制作专为野外营地设计的急救包。",al={"护士妮拉是谁","护士妮拉在哪里","护士妮拉位置"}},{q="急救包在营地有什么作用？",a="急救包是由急救专业人士制作的专业露营配件。当在荒野营地设置时，它提供基本的治疗资源，用于处理冒险时受到的伤害。",al={"什么是急救包","急救包用途","营地急救包"}},{q="为什么设置营地需要营火？",a="营火是任何荒野营地的基础，在设置医疗包等额外设施之前必须先有营火。基础营火的建造通常由烹饪训练师和厨师教授。",al={"为什么需要营火","如何制作营火","烹饪营火营地"}},{q="可以在城镇内扎营吗？",a="城镇居民和当地政府通常反对旅行者在城镇街道中间搭帐篷和生火。营地必须建立在开阔的荒野中。",al={"可以在城镇里露营吗","在布瑞尔露营","为什么要在大荒野露营"}},{q="谁教授如何制作急救包？",a="布瑞尔的护士妮拉在符合条件的冒险者表现出足够的急救专业熟练度后，会教授他们如何制作该急救包。",al={"谁教授露营急救","露营急救训练师","急救包训练师"}},{q="《露营基础：急救》的目标是什么？",a="《露营基础：急救》是一项入门任务，指引有志于医疗的冒险者前往布瑞尔寻找护士妮拉。它教授冒险者如何将他们的野外医学技能应用于为户外营地制造医疗用品。",al={"什么是露营基础急救","露营基础任务"}}},fp="22,199,21.228.0,20.283.0,19.157.0,39.145.0,42.162.0,36.144.0,42.110.0,43.113.0"}
P.entries["quest:97956"] = {n="Camping 101: Fishing",s="布瑞尔有人觉得，你的钓鱼技能能让营地更添欢乐。克莱德·凯林可以教你制作营地鱼缸。",h="布瑞尔有人觉得，你的钓鱼技能能让营地更添欢乐。克莱德·凯林可以教你制作营地鱼缸。",kw={"布瑞尔","营地","露营基础","克莱德·凯林","鱼缸","钓鱼"},ang={["profession:Cooking"]="作为一名渔夫，你可以运用钓鱼技能为营地制作鱼缸。"},sec={{t="营地纪念品",b="你的钓鱼技能或许能派上用场。证明自己的本领后，有人请你去布瑞尔找克莱德·凯林，学习如何为营地制作鱼缸。委托者相信，愉快的冒险者战斗起来更勇猛，希望鱼缸能给你和其他人带来欢乐。"}},faq={{q="我需要做什么？",a="证明你的钓鱼本领，然后去布瑞尔找克莱德·凯林，学习如何为营地制作鱼缸。",al={"要做什么","钓鱼营地任务"}},{q="克莱德·凯林是谁？",a="克莱德·凯林是布瑞尔的一位居民，可以教你为营地制作鱼缸。",al={"谁是克莱德","克莱德·凯林"}},{q="鱼缸有什么用？",a="鱼缸是营地用品，旨在给你和其他冒险者带来欢乐。",al={"鱼缸用途","营地鱼缸"}},{q="钓鱼怎么能帮到营地？",a="你可以运用钓鱼技能制作鱼缸，委托者希望它能让冒险者们心情愉快。",al={"钓鱼如何派上用场","为什么钓鱼能帮营地"}}},fp="20,122,15.273.0,28.115.0,20.76.0,25.76.0,32.95.0"}
P.entries["quest:97957"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism 指引初出茅庐的草药师前往艾泽拉斯各地的专业训练师处（例如布瑞尔的法鲁萨），以掌握熏香蜡烛的制作工艺。这些芬芳的产物能为在野外营地休息的施法者提供关键的恢复帮助。",h="Camping 101: Herbalism 指引初出茅庐的草药师前往艾泽拉斯各地的专业训练师处（例如布瑞尔的法鲁萨），以掌握熏香蜡烛的制作工艺。这些芬芳的产物能为在野外营地休息的施法者提供关键的恢复帮助。",kw={"布瑞尔","露营","埃莉诺·沙克尔顿","法鲁萨","草药学","熏香蜡烛","提瑞斯法"},ang={["class:Mage"]="施法者非常重视能制作熏香蜡烛的草药师，因为在远离酒馆舒适环境的地方，这种舒缓的烟雾能帮助他们恢复注意力和精神。",["profession:Herbalism"]="草药师不仅可以酿造药水或出售茎叶，还能通过为营火制作芬芳的熏香蜡烛，直接支援冒险队伍。",["race:Undead"]="从丧钟镇和布瑞尔出发的被遗忘者旅行者会向法鲁萨学习如何利用提瑞斯法枯萎的植被制作实用的野外手工艺品。"},sec={{t="营地植物",b="虽然草药学通常被视为炼金术的基础，但实际的野外生存同样依赖于采集到的根茎和花朵。经验丰富的旅行者会指引有抱负的采集者前往地区的草药学大师处，学习如何制作熏香蜡烛。在提瑞斯法林地，Eleanor Shackleton 会指引有潜力的采集者，在证明自己具备基本技能后，前往布瑞尔拜访法鲁萨。"},{t="精神食粮",b="旅途生活会对施法者和通灵师的精神造成巨大负担。熏香蜡烛散发的芬芳旨在振奋精神、舒缓疲惫的心智。通过将干燥的植物融入蜡烛，采集者能为在长途旅行中魔法储备衰竭的治疗者和法师提供至关重要的帮助。"}},faq={{q="这个任务的目的是什么？",a="该任务指引草药师达到一定的熟练度，以便他们能从草药学训练师那里学习如何制作熏香蜡烛。这些蜡烛用于在野外休息时维持和协助施法者。",al={"为什么进行露营草药学","露营 101 提供什么","露营 101 草药学目标"}},{q="谁在提瑞斯法林地提供这个任务？",a="埃莉诺·沙克尔顿 在提瑞斯法林地为草药师提供指导，并指引他们前往附近的布瑞尔定居点寻找法鲁萨。",al={"谁提供提瑞斯法 露营 101 草药学","埃莉诺·沙克尔顿 任务"}},{q="熏香蜡烛有什么作用？",a="熏香蜡烛能为营地提供环境增益，提振精神，并帮助那些需要在野外休息时恢复精神集中的治疗者和施法者。",al={"熏香蜡烛效果","熏香蜡烛的作用"}},{q="谁传授熏香蜡烛配方？",a="当冒险者获得资格后，当地的草药学训练师会进行指导。在提瑞斯法林地，布瑞尔的法鲁萨负责训练；而在其他城市和城镇，则由奥格瑞玛的加迪、铁炉堡的雷纳·石枝以及多兰纳尔的玛洛尼·刃叶等训练师负责。",al={"谁教授露营草药学","在哪提交 露营 101 草药学"}},{q="其他阵营和种族的成员可以接受这个任务吗？",a="可以。虽然 埃莉诺·沙克尔顿 和法鲁萨服务于提瑞斯法林地的旅行者，但其他任务给予者和训练师也会为卡利姆多和东部王国的草药师提供相同的指导。",al={"露营 101 是部落专属吗","联盟 露营 101 草药学"}},{q="完成训练需要什么技能要求？",a="草药师必须展现出专业技能的真正熟练度，达到二十点的草药学技能后，训练师才会传授蜡烛配方。",al={"需要多少草药学技能","露营 101 技能等级"}}},fp="22,157,18.293.0,23.259.0,34.148.0,41.95.0,31.116.0,38.206.0,56.168.0,58.85.0"}
P.entries["quest:97958"] = {n="Camping 101: Leatherworking",s="只要你展示出自己的制皮技艺，舍伦尼·洛巴尔特就能教你制作帐篷。帐篷能在旅途中为你遮阳挡雨。",h="只要你展示出自己的制皮技艺，舍伦尼·洛巴尔特就能教你制作帐篷。帐篷能在旅途中为你遮阳挡雨。",kw={"布瑞尔","扎营帐篷","营火","露营","烹饪","制皮","舍伦尼·洛巴尔特","帐篷","幽暗城"},ang={["profession:Cooking"]="身为厨师，你可以教旅人如何生起营火，让营地一应俱全。"},sec={{t="制皮匠的帐篷",b="一位制皮训练师指引你去找舍伦尼·洛巴尔特，她就在布瑞尔通往幽暗城的路上。只要你展示出熟练的技艺，她就能教你制作一件露营用品。帐篷能在炎热的日子里为你遮阳，在下雨时为你挡雨，让你在旅途中得到休息。"},{t="扎营之地",b="你的帐篷适合在野外使用，因为大多数人都不喜欢有人在镇子中央搭帐篷。营地有了营火才算齐全，厨师可以教你如何生火。如果你需要学习烹饪基础，就去找一位烹饪训练师。"}},faq={{q="谁能教我制作帐篷？",a="舍伦尼·洛巴尔特可以教你用制皮技艺制作一件露营用品。",al={"帐篷训练师","谁教制作帐篷","舍伦尼帐篷"}},{q="舍伦尼·洛巴尔特在哪里？",a="舍伦尼·洛巴尔特就在布瑞尔通往幽暗城的路上。",al={"舍伦尼位置","舍伦尼在哪","通往幽暗城的路"}},{q="帐篷有什么用？",a="帐篷能在炎热的日子里为你遮阳，在下雨时为你挡雨，让你在旅途中得到休息。",al={"帐篷用途","帐篷有什么用","露营帐篷"}},{q="我应该在哪里搭帐篷？",a="帐篷适合在野外使用；大多数人都不喜欢有人在镇子中央搭帐篷。",al={"哪里可以扎营","镇里搭帐篷","扎营地点"}},{q="我需要营火吗？",a="需要。营地有了营火才算齐全，厨师可以教你如何生火。",al={"营火","扎营需要营火吗","露营营火"}},{q="怎样学习生营火？",a="大多数厨师都能教你生火。如果你需要学习烹饪基础，就去找一位烹饪训练师。",al={"学习生火","烹饪训练师","生营火"}}},fp="27,140,22.273.0,15.243.0,32.73.0,25.55.0,22.96.0,31.99.0,21.74.0,34.107.0"}
P.entries["quest:97959"] = {n="Camping 101: Mining",s="你将学会制作一块用于野外营地的磁石。开始搭建营地前，还需要篝火。",h="你将学会制作一块用于野外营地的磁石。开始搭建营地前，还需要篝火。",kw={"篝火","露营","厨师","磁石","采矿","野外"},sec={{t="扎营之处",b="你现在可以制作自己的磁石了。想试试的话，就前往野外；大多数人可不希望有人在镇中心扎营。开始搭建营地前，你还需要篝火。厨师可以教你如何制作篝火。"}},faq={{q="我现在能制作什么？",a="你现在可以制作自己的磁石了。",al={"磁石配方","制作磁石"}},{q="我该去哪里试用磁石？",a="前往野外试试吧，大多数人可不喜欢有人在镇中心扎营。",al={"扎营地点","试用磁石"}},{q="开始搭建营地前需要什么？",a="开始搭建营地前，你需要篝火。",al={"需要篝火","搭建营地"}},{q="谁能教我制作篝火？",a="厨师可以教你制作篝火。",al={"学习制作篝火","谁教制作篝火"}}},fp="19,110,15.231.0,20.37.0,33.100.0,38.46.0,36.40.0"}
P.entries["quest:97960"] = {n="Camping 101: Skinning",s="Camping 101: Skinning 是一项为提瑞斯法林地和艾泽拉斯各地的初级采集者提供的荒野生存入门指导。它指引那些已经磨练过自己手艺的剥皮师前往当地的工匠处，学习如何用采集到的皮毛制作一把耐用的营地椅子。",h="Camping 101: Skinning 是一项为提瑞斯法林地和艾泽拉斯各地的初级采集者提供的荒野生存入门指导。它指引那些已经磨练过自己手艺的剥皮师前往当地的工匠处，学习如何用采集到的皮毛制作一把耐用的营地椅子。",kw={"布瑞尔","营地椅子","露营","埃莉诺·沙克尔顿","兰德·洛巴尔特","剥皮","提瑞斯法林地","幽暗城"},ang={["faction:Horde"]="部落的猎人和采集者会利用被杀野兽的每一块碎料，确保在无情的道路上没有任何浪费。",["race:Undead"]="即使是已经摆脱了凡人疲劳的被遗忘者，在猎杀提瑞斯法遭受瘟疫的野兽时，也发现维持实用的野外营地具有现实意义。"},sec={{t="荒野中的舒适",b="在荒野中生存不仅需要锋利的刀刃，还需要懂得如何在艰难困苦间养精蓄锐。像 Eleanor Shackleton 这样的冒险者强调，采集野兽毛皮所带来的不仅仅是原材料。通过培养基本的野外技能，剥皮师可以用处理过的毛皮制作必需的营地舒适用品，例如椅子，让疲惫的旅人在下一次危险的遭遇前能够好好休息和恢复。"},{t="掌握这门手艺",b="在提瑞斯法林地，年轻的被遗忘者剥皮师在达到初步能力后，会被指引去找兰德·洛巴尔特，他在连接布瑞尔和幽暗城废墟的道路旁从事他的行当。洛巴尔特分享了将粗糙的皮革转化为实用营地座椅的实用技巧，这种艺术在部落和联盟的领地中，都有剥皮大师在效仿。"}},faq={{q="这个任务的目的是什么？",a="该任务指引初级剥皮师寻找一位熟练的行业导师，学习如何使用采集到的动物毛皮组装一把野外营地椅。",al={"露营 101 剥皮 有什么作用","为什么要完成 露营 101 剥皮","露营 101 奖励"}},{q="在提瑞斯法林地，谁提供这种训练？",a="在提瑞斯法林地，这项任务由 埃莉诺·沙克尔顿 发布，旨在引导新的剥皮师前往布瑞尔和幽暗城之间的大道上寻找兰德·洛巴尔特。",al={"提瑞斯法林地的任务发布者","埃莉诺·沙克尔顿 任务"}},{q="完成此任务需要什么技能等级？",a="你的剥皮技能必须至少达到 20 点，训练师才会认为你经验足够，可以学习如何制作野外营地装备。",al={"我需要多少剥皮等级","露营 101 剥皮 要求","需要的剥皮技能"}},{q="兰德·洛巴尔特在哪里可以找到？",a="兰德·洛巴尔特驻扎在提瑞斯法林地从布瑞尔向南通往幽暗城入口的主路旁。",al={"兰德·洛巴尔特 位置","兰德·洛巴尔特 在哪里","兰德·洛巴尔特 提瑞斯法"}},{q="其他阵营的成员可以学习这项技术吗？",a="可以。虽然被遗忘者向兰德·洛巴尔特学习，但同等的导师也会在闪金镇、铁炉堡、多兰纳尔、奥格瑞玛、血蹄村和申达尔村训练剥皮师。",al={"这是部落专属吗","联盟可以做 露营 101 剥皮 吗","联盟剥皮营地椅"}},{q="制作营地椅子有什么用？",a="营地椅子可以在荒野中提供一个舒适的休息处来恢复体力，帮助冒险者保持充沛的精力以应对即将到来的战斗。",al={"营地椅有什么用","为什么要制作营地椅"}}},fp="21,181,20.264.0,19.348.0,34.115.0,44.143.0,51.100.0,32.112.0,51.164.0,36.146.0"}
P.entries["quest:97961"] = {n="Camping 101: Tailoring",s="裁缝训练师可以教你为营地制作阵营旗帜。向Bowen Brisboise证明你的手艺后，他就会传授你这门技艺。",h="裁缝训练师可以教你为营地制作阵营旗帜。向Bowen Brisboise证明你的手艺后，他就会传授你这门技艺。",kw={"bowen brisboise","布瑞尔","营火","露营","丧钟镇","阵营旗帜","rallying banner","裁缝"},sec={{t="营地的旗帜",b="裁缝训练师指引你去找Bowen Brisboise，他就在丧钟镇通往布瑞尔的路上。向他证明你的手艺，他就能教你为营地制作阵营旗帜。旗帜能让你在野外保持振奋。"},{t="安营扎寨",b="Bowen Brisboise会教你制作Rallying Banner。要试用它，你需要在荒野中扎营，因为大多数人都不喜欢有人在镇上扎营。你还需要一堆营火，厨师可以教你如何生火。"}},faq={{q="谁能传授裁缝的露营技艺？",a="向Bowen Brisboise证明你的裁缝技艺后，他就能教你制作阵营旗帜。",al={"bowen是谁","bowen brisboise","裁缝训练师"}},{q="在哪里能找到Bowen Brisboise？",a="Bowen Brisboise就在丧钟镇通往布瑞尔的路上。",al={"bowen在哪","bowen的位置","通往布瑞尔的路"}},{q="裁缝能为营地制作什么？",a="学习裁缝可以让你为营地制作阵营旗帜。",al={"裁缝露营物品","制作旗帜","营地旗帜"}},{q="这面旗帜叫什么？",a="你学会制作的旗帜叫作Rallying Banner。",al={"rallying banner","旗帜名称","什么旗帜"}},{q="我需要营火吗？",a="是的。扎营前需要先有一堆营火，厨师可以教你如何生火。",al={"是否需要营火","扎营用火","开始扎营"}}},fp="22,137,17.225.0,15.211.1,34.92.0,33.56.0,35.63.0,26.58.0,21.86.0"}
P.entries["quest:97963"] = {n="Camping 101: Alchemy",s="申达尔村的 Nyassa Swiftdraught 可以教你制作法力之井，前提是你在炼金术方面展现出足够的本领。法力之井能吸引治疗者和施法者来到营地，享用清爽饮品。",h="申达尔村的 Nyassa Swiftdraught 可以教你制作法力之井，前提是你在炼金术方面展现出足够的本领。法力之井能吸引治疗者和施法者来到营地，享用清爽饮品。",kw={"炼金术","篝火","野营","治疗者","法力之井","nyassa swiftdraught","申达尔村","施法者"},ang={["profession:Cooking"]="厨师可以教你生起扎营所需的篝火。"},sec={{t="炼金术士的营地",b="在申达尔村的 Nyassa Swiftdraught 可以教你制作法力之井，前提是你已展现出足够的炼金术本领。清爽的饮品会吸引治疗者和施法者前来。想在营地试试，你得先生起篝火；厨师可以教你怎么生火。"}},faq={{q="Nyassa 能教我什么？",a="申达尔村的 Nyassa Swiftdraught 可以教你制作法力之井，前提是你已展现出足够的炼金术本领。",al={"nyassa 炼金术","法力之井训练师","野营炼金术"}},{q="法力之井有什么用？",a="法力之井能吸引治疗者和施法者来到你的营地，享用清爽饮品。",al={"法力之井用途","法力之井有什么用","法力之井"}},{q="在哪里能学会制作法力之井？",a="Nyassa Swiftdraught 在申达尔村传授这项配方。",al={"nyassa 在哪里","申达尔村炼金术","法力之井位置"}},{q="扎营前需要准备什么？",a="你需要先生起篝火才能扎营。厨师可以教你怎么生火。",al={"需要篝火","如何扎营","野营炼金术要求"}}},fp="20,173,21.279.0,25.118.0,25.79.0,37.59.0,38.73.0"}
P.entries["quest:97964"] = {n="Camping 101: Blacksmithing",s="作为一名锻造师，你可以学会制作磨刀石，在营地中使用。申达尔村的Aedi Thriceforged可以在你展现出足够的技艺后传授给你。",h="作为一名锻造师，你可以学会制作磨刀石，在营地中使用。申达尔村的Aedi Thriceforged可以在你展现出足够的技艺后传授给你。",kw={"aedi thriceforged","锻造","营地入门","潜行者","磨刀石","申达尔村","战士"},ang={["class:Rogue"]="作为附近的潜行者，你可以在营地中使用磨刀石磨砺武器。",["class:Warrior"]="作为附近的战士，你可以在营地中使用磨刀石磨砺武器。",["profession:Blacksmithing"]="作为一名锻造师，你可以学会制作磨刀石，在营地中使用。"},sec={{t="Aedi Thriceforged的教导",b="磨刀石可以让附近的战士和潜行者在你的营地中磨砺武器。申达尔村的Aedi Thriceforged可以在你展现出足够的锻造技艺后，传授你制作磨刀石的方法。"}},faq={{q="谁能教我制作磨刀石？",a="申达尔村的Aedi Thriceforged可以在你展现出足够的锻造技艺后，教你制作磨刀石。",al={"磨刀石导师","aedi是谁","aedi锻造"}},{q="磨刀石有什么用？",a="在你的营地中，磨刀石可以让附近的战士和潜行者磨砺武器。",al={"磨刀石用途","磨砺武器","营地磨刀工具"}},{q="我在哪里能找到Aedi Thriceforged？",a="Aedi Thriceforged在申达尔村。",al={"aedi位置","aedi在哪里","aedi申达尔"}}},fp="26,165,13.196.0,42.129.0,32.84.0,34.41.0"}
P.entries["quest:97965"] = {n="Camping 101: First Aid",s="《Camping 101: 急救》指引旅行者前往申达尔村，学习如何为野外营地制作必要的医疗补给。通过寻找Naleeia Tattermend，技艺精湛的从业者可以制作能够治疗伤口并挽救生命，且远离文明社会的营地急救包。",h="《Camping 101: 急救》指引旅行者前往申达尔村，学习如何为野外营地制作必要的医疗补给。通过寻找Naleeia Tattermend，技艺精湛的从业者可以制作能够治疗伤口并挽救生命，且远离文明社会的营地急救包。",kw={"绷带","露营","露营101: 急救","急救","急救包","娜莉娅·补衣","申达尔村","荒野生存"},sec={{t="荒野中的治疗",b="艾泽拉斯的旅途充满了暴力、野兽和环境危险。对于任何旅行者而言，学习急救既实用又光荣，它能确保在不完全依赖法术的情况下包扎流血的伤口和骨折。在野外营地建立一个专门的急救包可以提供一个可靠的治疗中心，让筋疲力尽的冒险者在继续前进之前能够恢复体力和照料同伴。"},{t="申达尔村的导师",b="并非每一位战地医护人员都知道如何正确组装耐用的野外医疗用品。在申达尔村，一位名叫Naleeia Tattermend的专家指导致力于此的从业者学习制作营地急救包的艺术。那些寻求她指导的人必须首先展示自己在基础医疗护理方面的熟练程度，她才会传授她的技巧。"}},faq={{q="我需要找谁来完成这个任务？",a="你必须在申达尔村寻找纳莉娅·补衣。她拥有为野外营地制作专业医疗装备所需的知识。",al={"寻找谁来学习野外急救","纳莉娅·补缀在哪里","露营 101: 急救 任务提交"}},{q="申达尔村在哪里？",a="申达尔村是泽风岛上的一个村庄，医护人员纳莉娅·补衣就住在那里。寻求高级野外急救训练的从业者会在磨练好技能后前往那里。",al={"申达尔村在哪里","申达尔村位置","申达尔村急救"}},{q="制作营地急救包的目的是什么？",a="这项训练允许你为冒险者的营地制作量身定做的急救包。在荒野中，在营地随时备有医疗用品能提供旅途间隙至关重要的治疗，这甚至可能意味着生与死的区别。",al={"野外急救有什么用","营地急救包","为什么制作急救包"}},{q="纳莉娅·补衣什么时候会教我制作急救包？",a="纳莉娅·补衣要求你在她同意分享制作方法之前，先展示出足够的急救技能熟练度。你必须在组装野外急救包之前练习基本的包扎和治疗技术。",al={"什么时候可以学习制作急救包","纳莉娅·补缀 要求","露营 101: 急救 要求"}},{q="为什么急救被认为既光荣又实用？",a="伤口和身体创伤是艾泽拉斯冒险中不可避免的危险。绷带和医疗处理允许各种职业的旅行者处理自己的伤口，并在不完全依赖魔法援助的情况下稳定同伴的伤势。",al={"为什么急救很重要","急救背景知识","急救是否有用"}},{q="任何冒险者都可以制作野营急救包吗？",a="任何致力于学习急救并证明自己能力的冒险者，都可以向申达尔村的纳莉娅·补衣学习如何为他们的营地制作急救包。",al={"任何人都能学习这个急救包吗","谁可以制作营地急救包"}}},fp="22,166,25.300.0,30.185.0,43.112.0,34.164.0,57.180.0,55.131.0,57.199.0,49.147.0"}
P.entries["quest:97967"] = {n="Camping 101: Fishing",s="Camping 101: Fishing 指导有抱负的钓鱼者如何运用他们对钓竿和鱼线的耐心来提升野外探险的体验。通过在申达尔村寻找 Fenn Fairweather，精通钓鱼的玩家可以学习制作装饰性的鱼缸，以增强士气和营地舒适度。",h="Camping 101: Fishing 指导有抱负的钓鱼者如何运用他们对钓竿和鱼线的耐心来提升野外探险的体验。通过在申达尔村寻找 Fenn...",kw={"野营","露营101: 钓鱼","芬恩·晴天","鱼缸","钓鱼","申达尔村"},sec={{t="炉火的慰藉",b="在野外生活不仅仅需要锋利的刀刃和坚固的盔甲；保持高昂的士气往往是决定成功与精疲力竭的关键。虽然钓鱼通常被视为一种安静的消遣或获取食物的手段，但技术娴熟的钓鱼者可以将他们的技艺用于改善营地的舒适度。通过捕获活鱼并准备专门的装置，旅行者可以将荒凉的营地变成温馨的避风港。"},{t="申达尔的工匠",b="在申达尔村，工匠 Fenn Fairweather 会与懂得钓竿和卷轴之耐心的老练钓鱼者分享行业秘密。展现出足够技巧的人可以学习制作鱼缸——一种旨在为疲惫的同伴带来欢乐和放松的简单营地装置。在野外保持高昂的精神有助于小队成员在面对迫在眉睫的危险时保持专注和坚定。"}},faq={{q="谁教授鱼缸野营制作工艺？",a="芬恩·晴天 居住在申达尔村。一旦你证明了自己在钓鱼技艺上的足够造诣，芬恩 就能教你如何制作鱼缸来布置和点亮你的营地。",al={"谁提供鱼缸","芬恩·晴天 在哪里","鱼缸训练师"}},{q="鱼缸在营地中有什么用途？",a="鱼缸是营地的一种装饰性设施，能为你和你的同伴带来一丝舒适和欢乐。维护良好的营地和高昂的精神状态能让冒险者保持敏锐，并增强他们应对野外危险挑战的准备。",al={"鱼缸有什么作用","鱼缸增益","野营鱼缸效果"}},{q="申达尔村在哪里？",a="申达尔村是一个聚集了各行各业的工匠和导师的定居点，其中包括 芬恩·晴天。钓鱼从业者会前往那里学习适合他们技能的实用野营工艺。",al={"申达尔村在哪里","申达尔村位置"}},{q="学习这种野营工艺需要什么技能？",a="在从事这项工艺之前，你必须首先证明自己作为钓鱼者具备扎实的基本功。一旦你磨练了钓鱼技能，申达尔村的导师就会分享组装像鱼缸这样的营地设施的方法。",al={"野营钓鱼要求","什么时候可以学习鱼缸","如何开始野营钓鱼"}},{q="为什么钓鱼对野外露营很重要？",a="除了单纯地捕获猎物以维持生计外，钓鱼者敏锐的眼光和耐心还能以意想不到的方式为营地生活做出贡献。在制作精美的鱼缸中展示新鲜的渔获，可以在漫长的野外探险中提供宁静的亲切感并提振士气。",al={"为什么野营需要钓鱼","钓鱼在营地的用处"}},{q="芬恩·晴天 是谁？",a="芬恩·晴天 是一位位于申达尔村的工匠兼导师。芬恩 深知野外生活的实用舒适性，并与技术娴熟的钓鱼者分享有关营地设施的专业知识。",al={"芬恩·晴天 是谁","芬恩·晴天 背景故事"}}},fp="20,167,22.316.0,23.331.0,40.140.0,44.190.0,26.172.0,51.193.0,47.194.0,24.171.0"}
P.entries["quest:97968"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism 指导采集者前往导师处，学习制作用于野外营地的熏香蜡烛。利用采摘的植物成分，草药师可以提供芳香的慰藉，在漫长的旅途中提振施法者和治疗者的精神。",h="Camping 101: Herbalism 指导采集者前往导师处，学习制作用于野外营地的熏香蜡烛。利用采摘的植物成分，草药师可以提供芳香的慰藉，在漫长的旅途中提振施法者和治疗者的精神。",kw={"营地","露营","露营101: 草药学","治疗者","草药学","草药","熏香蜡烛","施法者"},ang={["class:Mage"]="在战斗中耗尽专注力的施法者非常感激那些旨在舒缓心灵并支持奥术恢复的营地熏香蜡烛。",["class:Priest"]="在营地中点燃的熏香蜡烛能提升神圣治疗者在战斗间隙的精神，并补充他们的精神储备。",["profession:Herbalism"]="采集荒野各处的植物提供了制作营地熏香所需的原始芳香草药，使得草药师的搜寻工作在炼金术之外也具有了生存实用性。"},sec={{t="小径上的野生植物",b="对于整日在荒野中跋涉的旅行者来说，采集根茎和花瓣远不止是无谓的搜寻。Camping 101: Herbalism 向熟练的采集者介绍了实用的野外技艺，将他们引荐给懂得如何将野生芳香植物转化为营地专用熏香蜡烛的导师。采集者不仅可以出售新鲜的茎叶或酿造药剂，还可以利用采集到的植物在旅途中为同伴提供支持。"},{t="舒缓心灵",b="在充满敌意的领土上长途跋涉会消耗治疗者和施法者的精力，他们的精神储备和士气在战斗中至关重要。在活跃的营地中点燃一支熏香蜡烛，空气中会弥漫着令人舒缓、恢复活力的香气，使人精神振奋。魔法使用者和治疗者尤其看重这种芳香带来的加成，确保同伴在重返险境之前恢复清醒和力量。"}},faq={{q="什么是 露营 101: 草药学？",a="露营 101: 草药学 是一项针对已经练习过草药采集的冒险者的任务。它将草药师引荐给专业的工匠，这些工匠能够传授如何为野外营地制作熏香蜡烛。",al={"什么是 露营 101 草药学","露营 101 草药学 任务","草药学露营任务"}},{q="熏香蜡烛有什么用途？",a="熏香蜡烛是一种使用草药材料制作的营地配件。在营地中点燃一支可以增强休息中冒险者的士气和精神，特别能为治疗者和施法者提供有益的加成。",al={"熏香蜡烛有什么用","熏香蜡烛营地效果","为什么制作熏香蜡烛"}},{q="谁教授如何制作熏香蜡烛？",a="训练师取决于你的起始地点：铁炉堡的雷娜·石枝、多兰纳尔的马洛恩·叶刃、艾尔文森林的草药师波默罗伊、奥格瑞玛的詹迪、布瑞尔的法鲁扎、雷霆崖的科敏·冬蹄，或是瓦拉纳尔的希瑞尔·夜雨。",al={"谁教授熏香蜡烛","熏香蜡烛训练师","在哪里学习熏香蜡烛"}},{q="为什么熏香蜡烛对魔法使用者特别有用？",a="在战斗中引导魔法和治疗伤口会消耗体力与精神专注。高昂的士气对于让施法者时刻准备战斗至关重要，而熏香蜡烛散发的舒缓烟雾有助于这种恢复。",al={"为什么施法者需要熏香","熏香蜡烛治疗者","熏香蜡烛魔法使用者"}},{q="做这个任务需要成为草药师吗？",a="这项指导直接针对那些拥有植物和草药采集技能的人，因为这些技术涉及识别和利用芳香的野生植物。",al={"任何人都能学习熏香蜡烛吗","做 露营 101 草药学 需要草药学吗","草药学需求露营蜡烛"}},{q="草药学如何与露营联系起来？",a="除了酿造药剂和药膏之外，采集到的野生植物在营地周围还有实用的芳香用途，例如制作熏香来让疲惫的同伴焕发精神。",al={"草药学只是为了药水吗","草药的露营用途","草药学营地物品"}}},fp="22,218,23.229.0,17.318.0,31.132.0,35.196.0,42.247.0,58.186.0,50.121.0,36.139.0"}
P.entries["quest:97969"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking 指导初出茅庐的制皮师寻求关于制作耐用野外遮蔽物的高级指导。在申达尔村的 Indari Sunseam 的引导下，工匠们学习缝制保护性帐篷，以便在漫长的野外探险中获得必要的休息。",h="Camping 101: Leatherworking 指导初出茅庐的制皮师寻求关于制作耐用野外遮蔽物的高级指导。在申达尔村的 Indari Sunseam...",kw={"露营帐篷","篝火","露营","烹饪","因达莉·阳缝","制皮","申达尔村","帐篷","荒野"},ang={["profession:Cooking"]="仅有一个帐篷并不能构成一个功能齐全的营地；旅行者还必须掌握基本的篝火制作工艺，这通常向烹饪训练师学习。"},sec={{t="旅途中的住所",b="对于旅行的制皮师来说，将兽皮和毛皮加工成耐用的野外装备的能力至关重要。在学会这门手艺后，工匠们会被指引去寻找申达尔村的 Indari Sunseam，学习如何制作合适的露营帐篷。这样的住所能让冒险者在无情的暴雨中保持干爽，在烈日下保持凉爽，确保他们在漫长的旅途中得到充分的休息。"},{t="野外营地",b="搭帐篷需要尊重市民边界，因为城镇居民不喜欢粗陋的营地挤占市政街道。营地必须搭建在野外。此外，坚固的住所只是成功的一半：没有温暖的篝火，任何营地都是不完整的，这促使冒险者在踏入荒野之前去拜访当地的厨师，学习基本的生火技能。"}},faq={{q="谁教导制皮师如何制作帐篷？",a="因达莉·阳缝 居住在申达尔村，并指导精通制皮的工匠如何制作他们自己的露营帐篷。",al={"谁教制皮帐篷","露营帐篷训练师","因达莉·阳缝 在哪里"}},{q="制作帐篷的目的是什么？",a="制作精良的帐篷可以保护旅行者免受雨水和烈日等恶劣天气的侵袭，让冒险者获得必要的休息，以在旅途中保持警觉。",al={"帐篷有什么用","帐篷用途","帐篷的好处"}},{q="可以在哪里搭建露营帐篷？",a="帐篷不能搭建在当地人反对的城镇中心。旅行者必须前往开阔的荒野才能扎营。",al={"我可以在城里搭帐篷吗","在哪里使用帐篷","营地规则"}},{q="搭建合适的营地还需要什么？",a="每一个完整的营地除了住所外，还需要一堆熊熊燃烧的篝火。建议冒险者寻找烹饪训练师，学习如何生火。",al={"我需要篝火吗","营地要求","营地还需要什么"}},{q="因达莉·阳缝 何时会教你帐篷图纸？",a="你必须练习制皮，并在你的专业技能中展现出足够的熟练度，因达莉·阳缝 才会教你制作露营物品。",al={"我什么时候能学帐篷","帐篷要求","制皮帐篷要求"}},{q="什么是申达尔村？",a="申达尔村是 因达莉·阳缝 生活和工作的地方，为旅行者提供制作露营用品的专业指导。",al={"申达尔村在哪里","申达尔村位置","因达莉·阳缝 所在的城镇"}}},fp="27,216,19.306.0,20.227.0,47.88.0,39.114.0,36.88.0,43.91.0,52.115.0,25.103.0"}
P.entries["quest:97970"] = {n="Camping 101: Mining",s="申达尔村的一位采矿导师可以教你为营地制作 Lodestone。它能让聚集在篝火旁的人在战斗中获得额外力量。",h="申达尔村的一位采矿导师可以教你为营地制作 Lodestone。它能让聚集在篝火旁的人在战斗中获得额外力量。",kw={"营地","篝火","安营入门","lodestone","messana crestwind","采矿","申达尔村"},ang={["profession:Cooking"]="作为厨师，你可以教别人制作安营所需的篝火。",["profession:Mining"]="作为矿工，你可以向 Messana Crestwind 展示自己的本领，学习为营地制作 Lodestone。"},sec={{t="矿工的手艺",b="采矿能带来踏实的工作，你还可以向申达尔村的 Messana Crestwind 学习一门营地手艺。展示出采矿熟练度后，她便能教你制作 Lodestone。聚集在你的篝火旁的人可以借此获得额外力量，因此这门手艺或许能为你的营地招来挥剑作战的人。"},{t="安营之地",b="学会这门手艺后，你就能亲手制作 Lodestone。城镇中心不欢迎营地，所以带它到野外试试。安营之前需要先点起篝火，厨师可以教你如何制作篝火。"}},faq={{q="谁能教我制作 Lodestone？",a="在申达尔村的 Messana Crestwind 可以教你制作 Lodestone，前提是你先展示出采矿熟练度。",al={"lodestone 导师","谁教营地手艺"}},{q="Lodestone 有什么用？",a="它能让聚集在你篝火旁的人在战斗中获得额外力量。",al={"lodestone 用途","lodestone 有什么用"}},{q="我可以在哪里测试 Lodestone？",a="你可以在野外测试；城镇中心不欢迎营地。",al={"在哪里测试 lodestone","lodestone 营地"}},{q="我需要篝火吗？",a="需要。安营之前必须先有篝火，厨师可以教你制作篝火。",al={"需要篝火","如何安营"}},{q="在 Messana 教我之前，我需要做什么？",a="你需要先展示出采矿熟练度，Messana Crestwind 才能教你制作 Lodestone。",al={"采矿熟练度","如何学会制作 lodestone"}}},fp="19,155,15.305.0,15.229.0,35.110.0,25.70.0,30.77.0,21.86.0,41.99.0"}
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="Camping 101: Skinning 指导冒险者如何将收集到的毛皮制作成实用的营地椅子，用于野外露营。在申达尔村的 Mendalass Tattermend 的指引下，剥皮师们学会了将采集技艺与野外生存及篝火休闲相结合。",h="Camping 101: Skinning 指导冒险者如何将收集到的毛皮制作成实用的营地椅子，用于野外露营。在申达尔村的 Mendalass Tattermend...",kw={"营地椅子","篝火","露营101","毛皮","门达拉斯·补衣","申达尔村","剥皮","荒野"},ang={["profession:Cooking"]="烹饪与野外生存相辅相成；正如 Mendalass 所指出的，搭建一个合适的营地需要基础的篝火，这通常是由烹饪训练师传授的技能。"},sec={{t="野外舒适度",b="从被击败的野兽身上采集毛皮是艾泽拉斯各地的一项基本生存技能，但它的用途远不止于简单的护甲制作。通过 Camping 101: Skinning，采集者们学会了将他们的专业技能转向野外生存，制作一把便携式的营地椅子。在野外找个舒适的座位休息片刻，能让疲惫的冒险者在下一次战斗前恢复体力，保持巅峰作战状态。"},{t="申达尔村的教导",b="一旦冒险者证明了自己剥皮刀的熟练度，他们就会被派往申达尔村去见 Mendalass Tattermend，以掌握这个配方。Mendalass 会指导旅行者如何用收集到的毛皮组装耐用的座椅。然而，建立一个营地不仅仅需要家具：定居点不会容忍在城镇范围内搭建临时营地，而且没有噼啪作响的篝火，营地就不算真正完成——这项技能通常是向当地烹饪训练师学习的。"}},faq={{q="露营 101: 剥皮 是关于什么的？",a="露营 101: 剥皮 指引熟练的剥皮师前往申达尔村寻找 门达拉斯·补衣。通过完成此项训练，冒险者可以学会如何将收获的毛皮重新利用，制作成一把实用的营地椅子，用于野外休息和恢复。",al={"这是什么任务","露营 101 的目的","为什么要完成这个任务"}},{q="门达拉斯·补衣 是谁？",a="门达拉斯·补衣 是一位位于申达尔村的剥皮训练师。他教导熟练的剥皮师如何将采集到的毛皮缝制成舒适的野外露营座椅。",al={"门达拉斯 是谁","谁教授营地椅子","门达拉斯·补缀"}},{q="在哪里可以找到 门达拉斯·补衣？",a="门达拉斯·补衣 居住在申达尔村，冒险者必须前往那里展示他们的技能，并学习制作营地装备的艺术。",al={"门达拉斯 在哪里","申达尔村在哪里","我在哪里交任务"}},{q="这个任务教你制作什么物品？",a="剥皮师学会了配方，可以使用从被击败的野兽身上采集到的皮和毛皮来制作营地椅子，为在野外时提供一个舒适的休息座位。",al={"剥皮师制作什么","营地椅子配方","我能得到什么物品"}},{q="你可以在城镇内搭建营地吗？",a="城镇居民不赞成在定居点中间搭建营地。营地和营地椅子应该搭建在远离城市中心的荒野中。",al={"我能在城里露营吗","我在哪里可以搭营地","在哪里使用营地椅子"}},{q="搭建一个合适的营地还需要什么？",a="每一个合适的营地在完成前都需要一堆噼啪作响的篝火。尚未掌握生火技能的冒险者建议咨询烹饪训练师来学习基础知识。",al={"搭营地还需要什么","需要篝火","营地要求"}}},fp="21,162,20.195.0,33.244.0,36.158.0,28.147.0,40.109.0,44.118.0,34.89.0,44.101.0"}
P.entries["quest:97972"] = {n="Camping 101: Tailoring",s="裁缝可以学会为你的营地制作阵营旗帜。你需要展现出对裁缝技能的熟练掌握，Taleen Shimmerthread 才能教你。",h="裁缝可以学会为你的营地制作阵营旗帜。你需要展现出对裁缝技能的熟练掌握，Taleen Shimmerthread 才能教你。",kw={"露营","阵营旗帜","专业","申达尔村","裁缝","taleen shimmerthread"},ang={["profession:Tailoring"]="身为裁缝，只要展现出对自身技艺的熟练掌握，你就能学会为营地制作阵营旗帜。"},sec={{t="营地的旗帜",b="申达尔村有人能教你制作阵营旗帜。只要你证明自己的裁缝技艺，Taleen Shimmerthread 就能教你制作这件露营物品。一面鼓舞人心的旗帜能让你在战场上保持振奋。"}},faq={{q="谁能教我制作阵营旗帜？",a="只要你展现出对裁缝技能的熟练掌握，申达尔村的 Taleen Shimmerthread 就能教你为营地制作阵营旗帜。",al={"旗帜教师","谁教裁缝制作旗帜","taleen 旗帜"}},{q="阵营旗帜有什么用？",a="阵营旗帜是一件露营物品。一面鼓舞人心的旗帜能让你在战场上保持振奋。",al={"旗帜用途","为何制作旗帜","营地旗帜"}},{q="Taleen 教我之前，我需要满足什么条件？",a="你需要展现出对裁缝技能的熟练掌握，Taleen Shimmerthread 才能教你制作阵营旗帜。",al={"裁缝要求","制作旗帜所需熟练程度","旗帜技能"}}},fp="22,143,17.250.0,42.134.0,31.109.0,42.112.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="《Camping 101: Tailoring》向裁缝们介绍了为野外营地制作专业装备的艺术。通过向申达尔村的Taleen Shimmerthread展示技艺，裁缝们可以学会缝制一面鼓舞人心的阵营旗帜，以提振士气并维持营地状态。",h="《Camping 101: Tailoring》向裁缝们介绍了为野外营地制作专业装备的艺术。通过向申达尔村的Taleen...",kw={"营地旗帜","露营","露营101: 裁缝","阵营旗帜","申达尔村","裁缝","塔琳·烁丝","专业技能"},ang={["profession:Tailoring"]="裁缝们学会制作鼓舞人心的阵营旗帜，这能提升营地士气并为野外的盟友补充活力。"},sec={{t="织布工对营地的贡献",b="《Camping 101: Tailoring》指导布甲工匠将他们的技艺扩展到简单的服装和包袋之外。在荒野中，生存不仅仅需要保暖的衣物；一个合适的营地往往决定了你能坚持多久。我们鼓励裁缝们寻求进阶指导，将布卷转化为团结与坚韧的象征。"},{t="申达尔村的指导",b="该任务引导有抱负的裁缝前往申达尔村，Taleen Shimmerthread将在那里提供露营工艺的指导。那些在裁缝技艺上达到足够熟练度的工匠可以学习制作阵营旗帜的方法。这种旗帜经过精心缝制，骄傲地插在营地中，不仅能作为激励人心的集合点，还能提升士气，让盟友们在接下来的挑战中保持活力。"}},faq={{q="什么是《露营 101: 裁缝》？",a="《露营 101: 裁缝》引导有潜力的裁缝去寻求野外工艺的专业指导。一旦你展示了足够的裁缝技艺，就可以学习如何为野外营地制作一面装饰性且鼓舞人心的阵营旗帜。",al={"这是什么任务","露营 101 裁缝任务","裁缝露营旗帜"}},{q="塔琳·烁线是谁？",a="塔琳·烁线是位于申达尔村的一位裁缝专家。她指导技艺娴熟的工匠如何编织露营专用的裁缝物品，包括能提升营地士气的旗帜。",al={"塔琳·烁线","谁教授裁缝旗帜","塔琳·烁线在哪里"}},{q="申达尔村在哪里？",a="申达尔村是塔琳·烁线居住的定居点。裁缝们会前往那里，接受关于如何将他们的布艺技艺应用到露营装备上的专业指导。",al={"申达尔村在哪里","申达尔村位置"}},{q="裁缝可以学习制作什么露营物品？",a="阵营旗帜是裁缝可以制作的一种露营物品。在任何战场或艰苦的远征中，保持灵感和士气至关重要，插上一面旗帜能为在营地休息的人们提供充满活力的氛围。",al={"阵营旗帜露营","裁缝为营地做什么","裁缝营地物品"}},{q="学习露营旗帜有什么要求？",a="你必须在申达尔村向塔琳·烁线展示你在裁缝专业上的熟练度，她才会教你编织阵营旗帜的图纸。",al={"如何学习阵营旗帜","裁缝露营旗帜要求"}},{q="为什么阵营旗帜在营地中很有价值？",a="士气和灵感在任何战役中都至关重要。裁缝们缝制阵营旗帜是为了展示忠诚，并提供一个能激发活力的焦点，支撑冒险者们度过艰苦的旅程。",al={"为什么制作阵营旗帜","露营旗帜士气"}}},fp="22,136,33.268.0,31.258.0,31.176.0,28.160.0,26.138.0,45.114.0,54.133.0,41.149.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="Nature's Call是幽影谷的一个任务，树妖塔琳德拉试图找出当地的止松熊怪为何会突然反目，背弃与暗夜精灵长久以来的盟友关系。通过收集他们废弃营地中的雕刻图腾，冒险者们得以揭示正在泰达希尔蔓延的令人不安的精神腐蚀。",h="Nature's Call是幽影谷的一个任务，树妖塔琳德拉试图找出当地的止松熊怪为何会突然反目，背弃与暗夜精灵长久以来的盟友关系。通过收集他们废弃营地中的雕刻图腾，冒险者们得以揭示正在泰达希尔蔓延的令人不安的精神腐蚀。",kw={"熊怪","止松","小鬼","贪婪小鬼","自然的召唤","梦魇","幽影谷","塔琳德拉","泰达希尔","图腾"},ang={["class:Druid"]="德鲁伊能感知到自然平衡以及影响卡利姆多生物的精神腐蚀，这使得被梦魇驱动的熊怪图腾腐蚀成为一个令人担忧的动向。",["faction:Alliance"]="保卫泰达希尔的枝干对于保护这个新兴的暗夜精灵国度至关重要，也能确保他们新结识的联盟盟友在卡利姆多站稳脚跟。",["race:NightElf"]="止松熊怪曾是暗夜精灵长期的伙伴，因此他们堕落为敌对和疯狂的状态，对于泰达希尔的守卫者而言是一场极为私人的悲剧。"},sec={{t="调查幽影谷",b="Nature's Call是幽影谷的一个调查任务，由树妖塔琳德拉发布。她无法相信止松熊怪会无缘无故地抛弃与暗夜精灵数百年的友谊，因此请求旅行者们搜寻位于山谷西侧边缘、被熊怪匆忙遗弃的营地，以找回完好的雕刻图腾。"},{t="阴影与梦魇",b="解读找回的图腾揭示了一场悲惨的堕落。止松熊怪一直饱受反复出现的梦魇困扰，梦见某种即将毁灭他们的阴影正在逼近。久而久之，纯粹的恐惧逐渐转化为盲目的愤怒，扭曲了他们的心智，使他们将长久以来的精灵邻居视为他们所恐惧的那种阴影。塔琳德拉希望这些发现能揭示泰达希尔蔓延的不详征兆。"}},faq={{q="谁发布了自然的召唤任务？",a="塔琳德拉是一位在泰达希尔的幽影谷守护的树妖。由于担心当地止松熊怪突然表现出的敌意，她指引冒险者从他们废弃的营地中回收圣物，以调查他们疯狂的根源。",al={"谁发布了自然的召唤","塔琳德拉是谁","塔琳德拉位置"}},{q="为什么止松熊怪会变得充满敌意？",a="从止松图腾中回收的雕刻显示，熊怪开始遭受可怕的梦魇困扰，梦见一个威胁要毁灭他们的阴影。这种蔓延的恐惧逐渐扭曲成无法控制的偏执和狂怒，导致他们将古老的暗夜精灵盟友视为敌人。",al={"为什么止松熊怪发动攻击","为什么止松熊怪疯狂","止松熊怪发生了什么"}},{q="止松图腾在哪里？",a="较小的图腾可以在位于幽影谷西侧边缘的废弃止松熊怪营地中找到，不过在废墟中搜寻的小鬼和贪婪小鬼已经把其中一些散落到了周围的区域。",al={"止松图腾在哪里","寻找止松图腾","止松营地位置"}},{q="为什么玩家无法收集营地里较大的图腾？",a="塔琳德拉特别建议不要尝试回收营地中发现的较大图腾。作为一名树妖，她表示自己完全不知道该如何处理那种笨重的雕刻，更倾向于使用较小、便于携带的雕刻图腾。",al={"为什么忽略大型图腾","我可以拾取大型图腾吗","大型止松图腾"}},{q="谁是止松熊怪？",a="止松部族是泰达希尔原生的熊怪，曾与暗夜精灵作为和平的盟友共同生活。他们最近转变为具有攻击性的敌对势力，是由蔓延的梦魇引起的一种反常现象，而非源于古老的恶意。",al={"谁是止松熊怪","止松传说","止松熊怪是邪恶的吗"}},{q="图腾中提到的伟大阴影是什么？",a="雕刻中提到了一个困扰着熊怪梦境的未知“伟大阴影”。虽然这种黑暗影响的确切来源尚不清楚，但塔琳德拉希望解读他们的命运将有助于理清泰达希尔所受到的更广泛的腐蚀。",al={"止松阴影是什么","泰达希尔的阴影是什么","泰达希尔的梦魇"}}},fp="13,165,22.302.0,28.327.1,34.198.0,44.192.0,39.181.0,57.209.0,30.176.0,49.198.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="“The Goddess Provides”是一项介绍卡多雷的初始任务，核心在于领会Elune的赐福。该任务设定在“Long Vigil”结束后泰达希尔的枝桠间，教导年轻的暗夜精灵接受月神之母带来的月光指引与隐遁阴影。",h="“The Goddess Provides”是一项介绍卡多雷的初始任务，核心在于领会Elune的赐福。该任务设定在“Long Vigil”结束后泰达希尔的枝桠间，教导年轻的暗夜精灵接受月神之母带来的月光指引与隐遁阴影。",kw={"艾露恩","女神的恩赐","海加尔山","卡多雷","漫长的守望","月神之母","影遁","泰达希尔"},ang={["class:Priest"]="卡多雷中的牧师群体致力于侍奉“月神”，直接引导Elune的优雅作为指引的光辉与神圣的庇护。",["faction:Alliance"]="在海加尔山的战斗之后，暗夜精灵结束了长期的孤立并加入了联盟，将他们神圣的月亮力量贡献于共同防御。",["race:NightElf"]="作为群星之子，卡多雷继承了Elune的直接赐福，利用月光揭示未见的道路，并利用隐蔽能力融入阴影之中。"},sec={{t="结束的守望",b="在大分裂后的数千年里，卡多雷维持着孤独的“Long Vigil”，守护着卡利姆多，并保卫着海加尔山的神圣山巅。第三次战争的浩劫以及对世界之树的关键防御迫使这段古老的与世隔绝走向终结。如今，移居至泰达希尔庇护之下的枝桠间，暗夜精灵们面对着一个陌生的世界，通过与远方海洋彼岸的盟友结盟，踏上了艾泽拉斯更广阔的舞台。"},{t="月神之母的祝福",b="即便是在结盟对象更迭与居所变迁之时，卡多雷认同感的根基依然植根于对“月神”Elune的崇拜。暗夜精灵从幼年起就被教导呼唤她的双重形态：指引战斗打击与澄清目标的辉光，以及掩盖自身于敌方视线之外的阴影。呼唤这些与生俱来的天赋，既是精神上的交流，也是为大树之外的危险所做的实践准备。"}},faq={{q="什么是“女神的恩赐”？",a="“女神的恩赐”是为栖居在泰达希尔枝桠间的年轻暗夜精灵准备的入门仪式。它指导卡多雷识别并展示月亮女神艾露恩赋予他们的天赋赐福。",al={"什么是女神的恩赐","女神的恩赐任务"}},{q="任务中提到的女神是谁？",a="这位女神是艾露恩，也被卡多雷尊称为“月神”。她是暗夜精灵文化与精神生活的核心神祇，被认为赐予其子民保护、澄明与潜行的月之祝福。",al={"女神是谁","谁是月神之母","暗夜精灵女神"}},{q="艾露恩赋予了卡多雷什么天赋？",a="艾露恩赋予的优雅可以照亮战士的打击以确保命中，同时也赋予了他们融入周围阴影的能力，正如月亮在日食期间遮蔽太阳一般。",al={"艾露恩给予什么天赋","艾露恩种族技能","艾露恩的力量"}},{q="什么是“漫长的守望”？",a="“漫长的守望”是暗夜精灵为守护卡利姆多而维持的数千年的警戒与孤立状态。在对燃烧军团的海加尔山关键防御战之后，这段时期宣告结束，促使卡多雷最终开放了国界。",al={"什么是漫长的守望","为什么漫长的守望结束"}},{q="为什么暗夜精灵加入了联盟？",a="海加尔山的防御战终结了他们孤独的隐居生活，卡多雷选择与海那边的凡人种族建立联系，加入了大联盟以求共同生存与结伴。",al={"为什么暗夜精灵加入联盟","卡多雷联盟"}},{q="这项指导在何处进行？",a="泰达希尔是位于卡利姆多北海岸外巨大的世界之树。第三次战争后，其高耸且受庇护的枝桠成为了暗夜精灵人民新的家园与圣所。",al={"泰达希尔在哪里","什么是泰达希尔"}}},fp="20,177,17.451.0,24.405.0,29.113.0,44.188.0,46.104.0,24.206.0,45.197.0,39.151.0"}
P.entries["quest:97985"] = {n="Thundering Hearts",s="一名研究憎恶制造奥秘的学者需要一颗巨大的心脏，目标是千针石林的雷霆蜥蜴Stormheart。",h="一名研究憎恶制造奥秘的学者需要一颗巨大的心脏，目标是千针石林的雷霆蜥蜴Stormheart。",kw={"憎恶","制造","心脏","风暴之心","千针石林","雷霆蜥蜴","雷霆之心"},sec={{t="一颗巨大的心脏",b="这名学者研究了制造憎恶的笔记，认为此项工作需要一颗巨大的心脏。据说雷霆蜥蜴Stormheart在千针石林的峡谷边缘巡游，体型似乎正合适。学者提醒你，Stormheart可不好对付。"},{t="心脏",b="Stormheart的心脏仍带有电流脉动。学者说它看起来符合指定的尺寸，会被加入憎恶体内。"}},faq={{q="谁想要风暴之心的心脏？",a="一名研究憎恶制造奥秘的学者想要风暴之心的心脏，用来制造憎恶。",al={"谁需要这颗心脏","憎恶研究者","是谁派我来的"}},{q="风暴之心在哪里？",a="风暴之心在千针石林的峡谷边缘巡游。",al={"风暴之心的位置","雷霆蜥蜴在哪里","风暴之心在哪"}},{q="风暴之心是什么？",a="风暴之心是一只体型惊人的雷霆蜥蜴。",al={"风暴之心是什么生物","大蜥蜴","雷霆蜥蜴"}},{q="为什么需要心脏？",a="学者的笔记指出，制造憎恶需要一颗巨大的心脏。",al={"为什么需要心脏","憎恶心脏","这颗心脏有什么用"}},{q="学者对这颗心脏了解多少？",a="学者说，这颗心脏仍有电流脉动，而且看起来符合笔记中指定的尺寸。",al={"心脏详情","带电的心脏","它有什么特别之处"}}},fp="17,98,13.218.0,9.163.1,31.89.0,20.61.0,19.50.0,22.75.0,46.115.0"}
P.entries["quest:98"] = {n="斯塔文的传说",s="伊瓦夫人的预感指向夜色镇面临的威胁：杀人者斯塔文·密斯特曼托，以及一枚家族戒指。你需要去面对他，并把戒指带给她。",h="伊瓦夫人的预感指向夜色镇面临的威胁：杀人者斯塔文·密斯特曼托，以及一枚家族戒指。你需要去面对他，并把戒指带给她。",kw={"小屋","夜色镇","暮色森林","家族戒指","伊瓦夫人","斯塔文","斯塔文·密斯特曼托"},sec={{t="夜色镇的威胁",b="伊瓦夫人的预感让你找到了斯塔文·密斯特曼托，他的罪行令夜色镇笼罩在恐惧之中。据说他从镇子正北方的小屋里威胁着夜色镇。你受托终结这场危机，并将他的家族戒指带给伊瓦夫人。"}},faq={{q="斯塔文·密斯特曼托是谁？",a="斯塔文·密斯特曼托被描述为一名犯下多起罪行的杀人者，他还威胁着夜色镇。",al={"斯塔文","斯塔文是谁","斯塔文的背景"}},{q="伊瓦夫人为何派我去找斯塔文？",a="伊瓦夫人的预感揭示了斯塔文对夜色镇的威胁。",al={"斯塔文为何如此","伊瓦与斯塔文","为何杀死斯塔文"}},{q="斯塔文的小屋在哪里？",a="斯塔文的小屋就在夜色镇正北方。",al={"斯塔文的小屋","斯塔文在哪里","小屋位置"}},{q="伊瓦夫人要我带回什么？",a="她让你把斯塔文的家族戒指拿给她看。",al={"家族戒指","斯塔文的戒指","带什么给伊瓦"}},{q="斯塔文被杀后发生了什么？",a="伊瓦夫人说斯塔文已死，暮色森林也摆脱了他的嗜血威胁。",al={"斯塔文的结局","斯塔文死了吗","斯塔文遭遇了什么"}},{q="伊瓦夫人为何欣喜？",a="斯塔文死后，她感受到希望在这片遭污染的森林中蔓延，尽管她仍为他的受害者哀悼。",al={"伊瓦欣喜","伊瓦为何欣喜","伊瓦夫人的反应"}}},fp="21,167,21.254.0,26.100.0,42.84.0,27.45.0,42.47.0,39.80.0,23.108.0"}
P.entries["quest:98013"] = {n="Swelling Forces",s="Swelling Forces是一个任务，Arbal指挥古树之林的冒险者去猎杀盘踞在东北方废墟中日益壮大的Stormscale娜迦。这些受到诅咒的前上层精灵与阴险的暮光之锤邪教结盟，威胁着林地。向他们拿起武器对于保护古老森林免遭进一步的破坏至关重要。",h="Swelling...",kw={"阿尔巴尔","古树之林","上层精灵","侍从","娜迦","女巫","雷鳞","日益壮大的势力","暮光之锤"},ang={["faction:Alliance"]="保卫黑海岸和古树之林周围神圣森林的联盟军队，必须应对娜迦和暮光之锤之间协同作战的前线。",["race:NightElf"]="在这些废墟中游荡的娜迦曾经是暗夜精灵的上层精灵同族。看到他们与黑暗邪教徒一起回来亵渎和掠夺古老的森林，这真是一种痛苦的背叛。"},sec={{t="沉没之城的毒蛇",b="在古树之林，Arbal带着深切的担忧注视着东北方的废墟。受到诅咒的上层精灵，已经变成了Stormscale部族的蛇形娜迦，占据了他们曾经辉煌文明的残骸。沉没的石块不再安静地承载着回忆，而是回荡着侵略大军滑行的脚步声。Arbal委派保卫者前往废墟，在他们的力量扩散到更广阔的森林之前，削减其不断增长的数量。"},{t="邪恶的联盟",b="Stormscale娜迦的出现不仅仅是简单的领土侵略。Arbal透露，这些扭曲的前上层精灵正在协助虚无主义的暮光之锤邪教。对于这些生物来说，亵渎和掠夺曾经庇护过它们的森林——特别是在服务于邪恶、阴暗的主人时——是不可原谅的罪行。遏制他们的数量迫在眉睫，以防止该邪教及其蛇形盟友进一步加强对这片土地的控制。"}},faq={{q="谁发布了日益壮大的势力任务？",a="日益壮大的势力由阿尔巴发布，他指引古树之林的冒险者去对抗聚集在东北方废墟中的敌对娜迦势力。",al={"谁发布日益壮大的势力","阿尔巴尔任务发布者","阿尔巴尔在哪里"}},{q="为什么在这个任务中要针对娜迦？",a="怒鳞娜迦已经占领了附近的废墟，并威胁着周围的林地。更令人担忧的是，他们似乎在协助暮光之锤邪教，给他们曾经称之为家园的土地带来了暴力。",al={"为什么要杀娜迦","废墟里的娜迦","怒鳞的威胁"}},{q="娜迦与这些废墟之间有什么联系？",a="正如阿尔巴所指出的，娜迦曾经是古代卡利姆多的上层精灵，遭受了可怕的诅咒。尽管他们曾经居住在这些宏伟的城市中，但现在他们已化身为扭曲的毒蛇，寻求征服和破坏。",al={"什么是怒鳞娜迦","娜迦的起源","被诅咒的上层精灵"}},{q="娜迦与暮光之锤有什么联系？",a="任务揭示了娜迦正在协助阴暗的暮光之锤邪教。虽然他们的具体安排仍未可知，但阿尔巴警告说，他们的结盟只会给古老的森林带来进一步的毁灭和苦难。",al={"暮光之锤娜迦","为什么娜迦与邪教合作"}},{q="怒鳞的势力聚集在哪里？",a="废墟位于古树之林的东北方。冒险者被派往那里，通过猎杀他们的侍从、女巫和战士来遏制日益壮大的怒鳞军队。",al={"废墟在哪里","去哪里找怒鳞"}},{q="为什么阿尔巴认为娜迦的行为是不可原谅的？",a="对阿尔巴来说，听命于黑暗主人而掠夺自己的古老家园是绝对不可原谅的。上层精灵曾经拥有的任何高贵品质，都已经随着他们堕落入残酷和黑暗的联盟中而彻底消失了。",al={"为什么阿尔巴尔痛恨娜迦","阿尔巴尔眼中的不可原谅"}}},fp="15,191,27.366.0,18.316.1,36.132.0,46.182.0,54.180.0,55.141.0,38.133.0,56.181.0"}
P.entries["quest:98021"] = {n="Journey to Sentinel Hill",s="“前往哨兵岭”指引联盟的冒险者前往西部荒野动荡的农田地带，向哨兵岭的哨所报到。当地指挥官数月来一直向暴风城请求皇家增援，却始终杳无音讯，这让他们感到十分沮丧。因此，他们已经准备好让任何愿意帮忙的旅行者直接投入工作。",h="“前往哨兵岭”指引联盟的冒险者前往西部荒野动荡的农田地带，向哨兵岭的哨所报到。当地指挥官数月来一直向暴风城请求皇家增援，却始终杳无音讯，这让他们感到十分沮丧。因此，他们已经准备好让任何愿意帮忙的旅行者直接投入工作。",kw={"前往哨兵岭","人民民兵","哨兵岭","瘦弱的精灵","暴风城","西部荒野"},ang={["faction:Alliance"]="西部荒野是一片急需支援的联盟领土，然而暴风城却将当地指挥官的增援请求置之不理，只能依靠任何出现的志愿者。",["race:NightElf"]="哨兵岭的边境指挥官可能会抱怨派来的是个“瘦弱的精灵”而不是久经沙场的暴风城步兵，但哨兵岭确实需要一切它能得到的援助。"},sec={{t="抵达边境",b="“前往哨兵岭”标志着冒险者踏入了饱受战火蹂躏的西部荒野地区。哨兵岭哨所是周围农田的主要防御堡垒，但其驻军却长期人手不足，且遭到皇家法庭的忽视。当旅行者前来提供援助时，当地指挥官根本无暇去质疑他们的身份，而是急切地想让任何愿意出力的人投入工作。"},{t="向暴风城恳求",b="数月以来，哨兵岭的领导层一直向暴风城请求军事增援，以确保该地区免受日益严重的威胁。王国的漠视迫使当地指挥官只能接受任何上门求助的人——即便这意味着要用一句冷嘲热讽来迎接刚抵达的冒险者，抱怨自己想要的是一支军队，结果却只等来了一个瘦弱的精灵。在西部荒野，乞丐是没资格挑肥拣瘦的。"}},faq={{q="什么是“前往哨兵岭”？",a="“前往哨兵岭”是一项联盟任务，指引冒险者前往西部荒野的边境领土。它向新人介绍了驻扎在哨兵岭的当地守卫，他们一直在向暴风城请求援助，却始终未能获得足够的正式增援。",al={"什么是前往哨兵岭","前往哨兵岭任务","哨兵岭任务"}},{q="为什么哨兵岭要寻求帮助？",a="驻扎在哨兵岭的军事领导层数月来一直恳求暴风城派遣增援部队，以处理困扰西部荒野的种种麻烦。当地领导层被迫依靠偶尔出现的个别冒险者，而不是正规部队。",al={"谁在向暴风城乞求援助","哨兵岭驻军","为什么哨兵岭需要帮助"}},{q="为什么任务文本提到了一个瘦弱的精灵？",a="在完成旅程后，指挥官会提到他们数月来一直恳求暴风城的援助，结果却只被派来了一个瘦弱的精灵。指挥官一边抱怨着乞丐没资格挑肥拣瘦，一边迅速决定让新到的冒险者立即投入工作。",al={"瘦弱的精灵语录","为什么是瘦弱的精灵","哨兵岭对精灵的评论"}},{q="为什么暴风城没有派遣合适的增援部队？",a="暴风城的皇家政府目前正分身乏术，焦头烂额，导致西部荒野等外围领土在很大程度上被忽视了。哨兵岭在几个月内多次发出求援呼吁，但官方的皇家支持始终未能落实，迫使当地指挥官只能依靠志愿者。",al={"为什么暴风城不帮助西部荒野","暴风城忽视西部荒野","暴风城对西部荒野的援助"}},{q="什么是哨兵岭？",a="哨兵岭是西部荒野人民民兵的核心军事哨所和堡垒。它是抵御肆虐该地区农田的无法无天之徒、迪菲亚盗贼和豺狼人的第一道防线。",al={"哨兵岭在哪里","什么是哨兵岭","哨兵岭位置"}},{q="到达哨兵岭后会发生什么？",a="一旦你在哨兵岭报到，当地守卫会毫不拖延地让你投入工作。冒险者的任务是帮助处理西部荒野平原和农田各处的诸多威胁。",al={"在西部荒野做什么","西部荒野后续任务","到达西部荒野后发生什么"}}},fp="24,224,23.270.0,18.284.0,33.163.0,37.169.0,45.167.0,48.129.0,22.155.0,42.151.0"}
P.entries["quest:98024"] = {n="十字路口之旅",s="十字路口之旅引导着刚从元素位面抵达的旅行者前往贫瘠之地那崎岖的草原。冒险者们被指派去向十字路口的索克报到，以协助部落军队应对严酷的前线。这对了解部落在卡利姆多所面临的致命威胁而言是一次必不可少的引导。",h="十字路口之旅引导着刚从元素位面抵达的旅行者前往贫瘠之地那崎岖的草原。冒险者们被指派去向十字路口的索克报到，以协助部落军队应对严酷的前线。这对了解部落在卡利姆多所面临的致命威胁而言是一次必不可少的引导。",kw={"贫瘠之地","十字路口","元素位面","部落","十字路口之旅","索克"},ang={["faction:Horde"]="这次旅程引导刚抵达的勇士们为部落拿起武器，在卡利姆多崎岖的前线提供了一次烈火般的试炼。",["race:Skyborne"]="既然已从元素位面抵达艾泽拉斯，旅行者们被敦促不要小看凡世的冲突，并要在为部落的服务中证明自己的勇气。"},sec={{t="前线的召唤",b="在从元素位面旅途归来并抵达艾泽拉斯的旅行者们面对的是一个清醒的现实：凡人的冲突相比之下似乎微不足道，但部落所面临的危险却是实实在在的。在前线服役为那些寻求成长并在此过程中协助凡世领域的人们提供了一个至关重要的试炼场。"},{t="卡利姆多的十字路口",b="为了开始服役，冒险者们会被指引向西南方，进入贫瘠之地那片广袤且被太阳炙烤的平原。那里坐落着十字路口，这是一个至关重要的枢纽，也是一个关键的部落哨站，其引以为傲的守卫者们时刻都在应对着周遭的危险。直接向索克报到能让新人们融入到定居点的防御体系中。"}},faq={{q="索克是谁？",a="索克是驻扎在贫瘠之地十字路口的一位重要的部落权威人物。他负责监管当地的防御工作，并指挥冒险者们去协助解决威胁着定居点及其周边领土的诸多危险。",al={"索克是谁","十字路口领袖","索克在哪里"}},{q="十字路口是什么？",a="十字路口是坐落于贫瘠之地主要道路交汇处的一个中心部落哨站和贸易枢纽。这里被充满敌意的野生生物、半人马部落和野猪人劫掠者所包围，守卫者们需要不断的援助来确保重要补给线的安全。",al={"十字路口是什么","贫瘠之地十字路口","为什么要去十字路口"}},{q="贫瘠之地位于哪里？",a="贫瘠之地是一片广袤且干旱的草原，位于卡利姆多中部，杜隆塔尔的西南方。它是一片连接整个大陆上部落领土的重要广袤区域。",al={"贫瘠之地在哪里","贫瘠之地位置"}},{q="为什么任务提到了元素位面？",a="任务中提到旅行者最近刚从元素位面抵达。虽然超凡界的冲突看起来似乎宏大，但威胁凡世领域和部落的危险却是迫在眉睫且严峻的。",al={"元素位面抵达","为什么提到元素位面","从元素位面旅程"}},{q="十字路口之旅的任务目的是什么？",a="该任务旨在指引新人们直接向十字路口的索克报到，让他们融入到部落的前线作战中，并通过光荣的服役提供了一条变得强大的途径。",al={"十字路口任务目的","为什么派往十字路口"}},{q="十字路口的居民面临着什么样的危险？",a="贫瘠之地持续面临着来自原生掠食者、游荡的半人马、野猪人战帮以及联盟入侵的侵略，这使得每一个哨站都成为了需要有能力的守卫者驻守的争夺据点。",al={"贫瘠之地有什么危险","贫瘠之地威胁"}}},fp="25,173,22.236.0,26.230.0,13.182.0,23.225.0,30.131.0,47.173.0,49.147.0,52.182.0"}
P.entries["quest:98025"] = {n="WANTED: Jai'vhanel",s="WANTED: Jai'vhanel 是由黑海岸奥伯丁村议会发布的联盟赏金任务。公告要求除掉名为“剑羽”的疯狂黑猫头鹰 Jai'vhanel，她开始袭击奥伯丁附近道路上的旅客。冒险者必须在亚米萨兰遗迹附近猎杀这只生物，并将她死亡的证明交给哨兵戈琳达·纳希恩。",h="WANTED: Jai'vhanel 是由黑海岸奥伯丁村议会发布的联盟赏金任务。公告要求除掉名为“剑羽”的疯狂黑猫头鹰...",kw={"亚米萨兰","奥伯丁","黑猫头鹰","黑海岸","戈琳达·纳希恩","贾伊·瓦内尔","剑羽","通缉: 贾伊·瓦内尔"},ang={["class:Druid"]="暗夜精灵德鲁伊密切关注着黑海岸的野生动物，像 Jai'vhanel 这样高贵的鸟类突然陷入疯狂并产生攻击性，这是一种令人担忧的生态干扰。",["class:Hunter"]="这只被称为“剑羽”的凶猛漆黑猛禽，是黑海岸山区附近极具攻击性的追踪者，她的狩猎习惯变得极其不稳定且具有致命危险。",["faction:Alliance"]="奥伯丁村议会依靠联盟冒险者和暗夜精灵哨兵来保护黑海岸重要的沿海公路免受疯狂掠食者的侵害。"},sec={{t="路上的威胁",b="奥伯丁村议会发布的一则公告向黑海岸沿海道路的旅客发出警告，称存在严重的威胁。一只著名的当地猫头鹰 Jai'vhanel（绰号“剑羽”）突然陷入了疯狂。她不再待在茂密的荒野中，而是开始袭击奥伯丁附近的旅客和信使，将一只普通的林地掠食者变成了该定居点的严重危险。"},{t="议会的赏金",b="为了确保道路安全，议会悬赏捉拿 Jai'vhanel。猎手们被指示追踪这只黑羽猛禽到亚米萨兰遗迹以北、山脚下的狩猎场。猎手必须带回她身上的一根标志性黑羽，交给奥伯丁的哨兵戈琳达·纳希恩以核实猎杀成果并领取奖励。"}},faq={{q="杰伊瓦内尔 是谁？",a="杰伊瓦内尔，也被称为“剑羽”，是一只以浑身漆黑羽毛而闻名的巨型猫头鹰。她本是黑海岸森林中常见的野生生物，但现在已经陷入疯狂，并开始对旅客表现出强烈的攻击性。",al={"贾伊瓦内尔 是谁","贾伊瓦内尔 是什么","剑羽是谁"}},{q="为什么要悬赏 杰伊瓦内尔？",a="奥伯丁村议会之所以对 杰伊瓦内尔 发出正式悬赏，是因为她已经发疯并开始攻击奥伯丁附近主要道路上的旅客，对当地交通构成了严重威胁。",al={"为什么要猎杀 贾伊瓦内尔","为什么要悬赏 贾伊瓦内尔","为什么这只猫头鹰会发起攻击"}},{q="在哪里可以找到 杰伊瓦内尔？",a="人们最后一次见到 杰伊瓦内尔 是在黑海岸的古代亚米萨兰遗迹以北，她在东部山脉的山脚下徘徊。",al={"贾伊瓦内尔 在哪里","贾伊瓦内尔 的位置","在哪里找到剑羽"}},{q="是谁悬赏了 杰伊瓦内尔？",a="这份赏金是由奥伯丁村议会发布的，他们负责监督这个沿海定居点及周边道路的民事安全与当地福利。",al={"谁发布了悬赏","谁想要 贾伊瓦内尔 死"}},{q="谁负责领取 杰伊瓦内尔 的赏金？",a="赏金猎人必须出示 杰伊瓦内尔 的一根黑羽作为她死亡的证明，并交给驻守在奥伯丁镇的哨兵戈琳达·纳希恩。",al={"谁负责收取死亡证明","在哪里上交 贾伊瓦内尔 的羽毛","戈琳达·纳希恩悬赏"}},{q="需要什么证明才能领取赏金？",a="任何要求领取议会赏金的人都必须找回并出示 杰伊瓦内尔 身上的一根标志性黑羽，以证明这只疯狂的鸟已经被杀。",al={"贾伊瓦内尔 的死亡证明是什么","什么物品证明 贾伊瓦内尔 已死"}}},fp="18,212,20.238.0,20.265.0,18.151.0,36.156.0,30.104.0,36.134.0,39.103.0,41.61.0"}
P.entries["quest:98027"] = {n="Gleaming Crescent Necklace",s="一条闪亮的新月形项链上刻着铭文，表明它与阿斯特兰纳的Maliynn有关。你可以将这件纪念物归还给主人。",h="一条闪亮的新月形项链上刻着铭文，表明它与阿斯特兰纳的Maliynn有关。你可以将这件纪念物归还给主人。",kw={"alor'lormah","阿斯特兰纳","crescent necklace","gleaming crescent necklace","maliynn","暗夜精灵符号","银项链"},ang={["race:NightElf"]="身为暗夜精灵，你或许能从见过的符号中认出这种新月形状。"},sec={{t="铭文",b="你仔细端详着一条新月形的银项链。它的形状让你想起见过的其他暗夜精灵符号，背面的铭文写着：“Alor'lormah, Maliynn.”这个名字指向阿斯特兰纳的Maliynn，项链或许能在那里找到主人。"},{t="Maliynn的纪念物",b="阿斯特兰纳的Maliynn认出这条项链是她的。她在向一处前哨站运送补给时弄丢了它，随后沿路寻找，最终放弃了。这是她已故的父母送给她的礼物，能失而复得，对她意义重大。"}},faq={{q="这条项链属于谁？",a="铭文上刻着Maliynn的名字，而阿斯特兰纳的她也认出这条项链是自己的。",al={"属于谁","项链主人","maliynn的项链"}},{q="这条项链是什么样的？",a="这是一条银项链，形状如同一弯小小的新月。",al={"crescent necklace","什么形状","银项链"}},{q="项链上写着什么？",a="铭文写着：“Alor'lormah, Maliynn.”",al={"项链铭文","写着什么","alor'lormah"}},{q="可以把项链带到哪里？",a="把Crescent Necklace交给阿斯特兰纳的Maliynn。",al={"送到哪里","maliynn的位置","阿斯特兰纳项链"}},{q="这条项链为何对Maliynn如此重要？",a="这是她已故的父母送给她的礼物。",al={"为何重要","maliynn的纪念物","父母的礼物"}},{q="Maliynn是怎么弄丢它的？",a="Maliynn在向她的一处前哨站运送补给时弄丢了它。她沿路寻找，最终放弃了。",al={"项链如何丢失","她在哪里弄丢的","丢失的项链"}}},fp="26,127,15.263.0,18.218.1,32.91.0,33.58.0,32.49.0,31.52.0,40.36.0,24.111.0"}
P.entries["quest:98028"] = {n="Baron Marinous",s="安努想弄清一名元素守护者留下的水球究竟发生了什么。你将水球带到古树之林交给他，他从中察觉到了令人不安的征兆。",h="安努想弄清一名元素守护者留下的水球究竟发生了什么。你将水球带到古树之林交给他，他从中察觉到了令人不安的征兆。",kw={"baron marinous","clouded water globe","黑海岸","元素守护者","古树之林","玛塞斯特拉","纳迦","安努"},sec={{t="安努的指点",b="古树之林的安努需要Clouded Water Globe。元素守护者已被击败，但水球依旧浑浊，发生在守护者及其守护的废墟中的异变可能仍在持续。你将水球交给安努，他最有可能了解更多内情。"},{t="安努的忧虑",b="在古树之林，安努看到水球后十分惊讶，想知道玛塞斯特拉是否有向下延伸的阶梯。他说自己必须与其他人商议。他很庆幸你赶在纳迦或它们的教派盟友之前发现了这个水球，并指出击败元素守护者绝非易事。"}},faq={{q="安努是谁？",a="安努是黑海岸古树之林的知识古树。",al={"安努","安努的故事","知识古树"}},{q="Clouded Water Globe是什么？",a="它是一个强大元素生物留下的唯一遗物，是一颗被未知物质搅浑的水球。",al={"浑浊的球体","水球","元素生物留下的球体"}},{q="水球为什么看起来很浑浊？",a="一种未知物质使水球变得浑浊，似乎让任何人都无法看清内部。",al={"球体里有什么","浑浊的水","为什么看不清内部"}},{q="我该把水球送到哪里？",a="将Clouded Water Globe带到黑海岸的古树之林，交给安努。",al={"安努在哪里","古树之林的位置","送交球体"}},{q="元素守护者怎么了？",a="元素守护者已被击败，水球是它留下的唯一遗物。",al={"元素生物的命运","守护者已死","守护者怎么了"}},{q="安努提到纳迦时说了什么？",a="安努说，幸好你赶在纳迦或它们的教派盟友之前发现了水球。",al={"纳迦与球体","教派盟友","为什么要赶在纳迦之前"}}},fp="14,168,13.268.0,13.304.1,11.69.0,32.97.0,32.85.0,26.79.0,40.82.0,33.81.0"}
P.entries["quest:98042"] = {n="It's All Fun and Games Until...",s="It's All Fun and Games Until... 是一个与提交给桑德里斯的一项令人深感不安的发现有关的任务。在辨认出这件古老邪恶之物那无法误认的标记后，桑德里斯安排将该圣物立即送往达纳苏斯进行深入研究。",h="It's All Fun and Games Until...",kw={"古老邪恶","愿你的烦恼消散","达纳苏斯","古老邪恶的标记","暗夜精灵","桑德里斯"},ang={["faction:Alliance"]="联盟冒险者将令人不安的发现带给暗夜精灵当局，有助于确保危险的圣物得到达纳苏斯学者的检查和控制。",["race:NightElf"]="这项调查直接触及了暗夜精灵对古老腐化的警惕，促使达纳苏斯立即介入。"},sec={{t="令人不安的报告",b="一项令人不安的发现促使冒险者前往寻找桑德里斯，就此事寻求建议。在听取了冒险者的报告并检查了所带来的东西后，桑德里斯陷入了沉思，他意识到了一些无法等闲视之的黑暗征兆。"},{t="古老邪恶的标记",b="在仔细检查此事后，桑德里斯辨认出该发现物上附着着无法误认的古老邪恶标记。意识到危险远远超出了当地发生的意外，桑德里斯决定立即将该圣物送往达纳苏斯，托付给首都的学者和祭司进行严格的研究和封印。"}},faq={{q="谁参与完成了此任务？",a="该任务是提交给桑德里斯并由他结束的，他会听取不安的冒险者的汇报，并在准备将其运走之前检查所提交的物品或证据。",al={"谁发布了一切都是玩闹，直到……","桑德里斯任务","谁回收一切都是玩闹，直到……"}},{q="为什么要把这个物体送到达纳苏斯？",a="桑德里斯确认该神器或发现物带有古老邪恶的标记。桑德里斯表示他会立刻将其送往达纳苏斯进行进一步研究，除此之外他没有透露更多信息。",al={"为什么送到达纳苏斯","达纳苏斯研究","达纳苏斯的古老邪恶"}},{q="桑德里斯所指的古老邪恶是什么？",a="桑德里斯确认该发现物带有古老邪恶的标记，尽管关于其确切起源的具体细节在暗夜精灵首都进行更深入的研究之前仍处于保密状态。",al={"古老邪恶是什么","古老邪恶标记的含义"}},{q="'愿你的烦恼烟消云散' 是什么意思？",a="'愿你的烦恼烟消云散' 是桑德里斯在你谈话结束时所说的一句达纳苏斯语，在他说了该发现物将被带到达纳苏斯之后。",al={"愿你的烦恼随风而去的含义","愿你的烦恼随风而去暗夜精灵短语","达纳苏斯语告别桑德里斯"}},{q="任务完成后会发生什么？",a="在揭露了那古老的腐化后，桑德里斯准备将这件令人不安的圣物立即运往达纳苏斯，以便首都的学者们可以对其进行检查。",al={"一切都是玩闹，直到……完成之后会发生什么","玩闹之后的下一个任务","前往达纳苏斯后续"}},{q="哪个阵营负责这项调查？",a="此事由达纳苏斯的领导层和像桑德里斯这样的暗夜精灵人物负责处理，重点在于提交给暗夜精灵当局的威胁。",al={"一切都是玩闹是联盟专属吗","谁能执行一切都是玩闹，直到……"}}},fp="31,128,18.198.0,24.226.1,41.123.0,42.108.0,48.130.0,35.145.0,40.146.0,41.129.0"}
P.entries["quest:98046"] = {n="大地之冠",s="大地之冠是达纳苏斯的一个任务，大德鲁伊范达尔·鹿盔在一次涉及一瓶水的咒语施法失败后，放弃了该仪式并由此开启了此任务。这位沮丧的大德鲁伊打发走了冒险者，命令其将排空的器皿送往月神殿交给女祭司拉里亚进行处理。然而，女祭司在检查瓶子时发现里面还有些许残留的水，这不禁让人怀疑仪式失败的真正原因。",h="大地之冠是达纳苏斯的一个任务，大德鲁伊范达尔·鹿盔在一次涉及一瓶水的咒语施法失败后，放弃了该仪式并由此开启了此任务。这位沮丧的大德鲁伊打发走了冒险者，命令其将排空的器皿送往月神殿交给女祭司拉里亚进行处理。然而，女祭司在检...",kw={"塞纳里奥议会","大地之冠","达纳苏斯","排空的器皿","艾露恩","范达尔·鹿盔","拉里亚","玛法里奥","月神殿"},ang={["class:Druid"]="范达尔明确地将冒险者称为德鲁伊同僚，在将其赶走之前，他对仪式失败表现出了生硬的不耐烦。",["faction:Alliance"]="该任务展示了在玛法里奥·怒风缺席的情况下，卡利姆多主要的联盟主城达纳苏斯内部平静的领导层紧张局势。",["race:NightElf"]="这项差事揭示了达纳苏斯内部日常的压力，将范达尔·鹿盔尖刻的权威与月神殿中艾露恩姐妹会的耐心奉献形成了鲜明对比。"},sec={{t="范达尔的沮丧",b="在达纳苏斯，大德鲁伊范达尔·鹿盔承担着玛法里奥·怒风缺席期间引导暗夜精灵的重任。在寻找答案的过程中，范达尔试图利用瓶中盛放的圣水进行咒语仪式。当仪式似乎毫无结果时，大德鲁伊的脾气爆发了。他认定这些水毫无用处，便言语尖刻地打发走冒险者，并指示他们将排空的器皿送往南方的月神殿，让那里的女祭司处理掉。"},{t="残留的水滴",b="在抵达月神殿后，女祭司拉里亚表现得非常温和，她让冒险者不必介意范达尔严厉的态度，毕竟他肩负着沉重的担子。然而当她检查瓶子时，她发现了大德鲁伊在匆忙中忽略的一件事：瓶中仍残留着几滴水。这一残留物引发了一种明显的可能性：范达尔的仪式并非因魔法本身有缺陷而失败，而是因为容器未被彻底清空。"}},faq={{q="谁发布了大地之冠任务？",a="该任务由达纳苏斯的大德鲁伊范达尔·鹿盔发布。范达尔目前在玛法里奥·怒风缺席期间主持塞纳里奥议会，在一次涉及圣水的咒语未能得出他想要的答案后，他极其烦躁地指派了这项任务。",al={"谁开启了 大地之冠","大地之冠 任务发布者","范达尔任务"}},{q="你需要将排空的器皿送到哪里？",a="你需要将排空的器皿送交至达纳苏斯南部月神殿的女祭司拉里亚。范达尔命令你将其移交以便让艾露恩的女祭司们处理，他认为这个用过的容器已毫无用处。",al={"去哪里上交 排空的器皿","排空的器皿 上交","拉里亚在哪里"}},{q="为什么范达尔·鹿盔如此沮丧？",a="大德鲁伊范达尔·鹿盔在玛法里奥·怒风离职期间领导暗夜精灵和塞纳里奥议会，承受着巨大的压力。当他的魔法咒语毫无所获时，他的烦躁和傲慢使他大发雷霆，并迅速打发走了冒险者，而不是深入探究失败的原因。",al={"为什么范达尔生气","范达尔的态度","为什么范达尔不耐烦"}},{q="为什么范达尔的咒语失败了？",a="范达尔·鹿盔认为水本身缺乏任何有用的力量，但女祭司拉里亚在接过瓶子时注意到一个关键细节。瓶内仍有几滴水残留，这表明咒语之所以失败，可能仅仅是因为在仪式过程中瓶子未被完全清空。",al={"为什么咒语会失败","范达尔的仪式成功了吗","失败的咒语"}},{q="在这个任务中玛法里奥在哪里？",a="玛法里奥·怒风目前不在达纳苏斯，这使得塞纳里奥议会的领导权和对暗夜精灵的指导责任落在了大德鲁伊范达尔·鹿盔身上。这种缺席给范达尔带来了沉重的负担，这也加剧了他的易怒和对挫折的不耐烦。",al={"玛法里奥在哪里","为什么玛法里奥缺席","玛法里奥的状态"}},{q="女祭司拉里亚是谁？",a="女祭司拉里亚是一位驻扎在达纳苏斯月神殿的艾露恩信徒。她从冒险者手中接过了瓶子，在对范达尔沉重的职责表示同情的同时，敏锐地察觉到瓶中仍有残留的水。",al={"谁是拉里亚","女祭司拉里亚背景故事","拉里亚 月神殿"}}},fp="18,166,21.381.0,19.245.1,39.223.0,37.198.0,38.263.0,35.189.0,37.215.0,24.170.0"}
P.entries["quest:98065"] = {n="大地之冠",s="大地之冠是一个达纳苏斯任务，冒险者需要将净化的月亮井残骸送交给高阶女祭司泰兰德·语风。该任务发生在月神殿内部，揭示了艾露恩之水的神圣意义，以及泰兰德与大德鲁伊范达尔·鹿盔之间日益紧张的政治关系。",h="大地之冠是一个达纳苏斯任务，冒险者需要将净化的月亮井残骸送交给高阶女祭司泰兰德·语风。该任务发生在月神殿内部，揭示了艾露恩之水的神圣意义，以及泰兰德与大德鲁伊范达尔·鹿盔之间日益紧张的政治关系。",kw={"大地之冠","达纳苏斯","艾露恩","范达尔·鹿盔","玛法里奥","月亮井残骸","月神殿","泰兰德·语风"},ang={["class:Druid"]="泰兰德对于大德鲁伊范达尔·鹿盔的尖锐言辞，凸显了在玛法里奥缺席的情况下，塞纳里奥议会内部日益增长的摩擦。",["class:Priest"]="服务于高阶女祭司泰兰德·语风，巩固了艾露恩的教士在引导和管理暗夜精灵社会中所扮演的重要角色。",["faction:Alliance"]="获得觐见达纳苏斯领袖的机会，可以让人一窥联盟主要首府之一所面临的内部政治压力。",["race:NightElf"]="直接运送神圣的月亮井水，凸显了卡多雷双重领导体制的现状，即夹在泰兰德的祭司体系与范达尔的德鲁伊体系之间。"},sec={{t="觐见高阶女祭司",b="在收集到神圣的月亮井残骸后，冒险者需要将这些受祝福的圣水转移到一个仪式容器中，并直接交给泰兰德·语风。艾露恩的高阶女祭司居住在达纳苏斯的月神殿高处，守护着这座城市，并为每一位进入其中的人提供女神的光芒。将这神圣之水交由她保管，被视为一种荣耀以及对艾露恩的虔诚表现。"},{t="领导层之间的紧张关系",b="在收到圣水残骸后，泰兰德对冒险者拯救这受祝福之水的行为表示了深深的感激，但她的思绪很快便转回了笼罩着达纳苏斯的政治紧张局势。在玛法里奥·怒风缺席期间，大德鲁伊范达尔·鹿盔接管了德鲁伊事务，但泰兰德明确表示，统治卡多雷是她个人的职责。尽管她敦促人们尊重鹿盔的职位，但这次交流揭示了艾露恩姐妹会与塞纳里奥议会之间尖锐的摩擦。"}},faq={{q="什么是大地之冠？",a="大地之冠是达纳苏斯的一个任务，冒险者需要将一容器的月亮井残骸带给月神殿内的高阶女祭司泰兰德·语风。这标志着与暗夜精灵最高领袖直接交流的一个时刻。",al={"什么是 大地之冠","大地之冠 任务","任务 大地之冠"}},{q="泰兰德·语风是谁？",a="泰兰德·语风是艾露恩的高阶女祭司，也是暗夜精灵的政治领袖。她在月神殿的上层俯瞰着达纳苏斯，肩负着在动荡时期引导她的人民这一重担。",al={"泰兰德·语风是谁","泰兰德在哪里","高阶女祭司泰兰德"}},{q="为什么要将月亮井残骸带给泰兰德？",a="月亮井残骸是受艾露恩祝福的神圣之水。鉴于其神圣属性，必须将其转移至仪式容器中并带给泰兰德，以便她能代表女神接收并守护这些圣水。",al={"为什么要带 月亮井残骸 给泰兰德","什么是 月亮井残骸","达纳苏斯神圣之水"}},{q="泰兰德和范达尔·鹿盔之间有什么争端？",a="在玛法里奥·怒风缺席期间，大德鲁伊范达尔·鹿盔领导着德鲁伊，但泰兰德坚定地主张，管理达纳苏斯和领导卡多雷仍然是她自己的责任，她拒绝让德鲁伊的权威盖过艾露恩的祭司。",al={"泰兰德与范达尔的紧张关系","为什么泰兰德不喜欢鹿盔","范达尔对战泰兰德"}},{q="这个任务期间玛法里奥在哪里？",a="玛法里奥·怒风目前不在达纳苏斯，导致德鲁伊之间出现了领导空缺，大德鲁伊范达尔·鹿盔填补了这一空缺，这加剧了与泰兰德之间的政治紧张关系。",al={"玛法里奥在哪里","玛法里奥发生了什么","玛法里奥缺席"}},{q="月神殿在哪里？",a="月神殿位于达纳苏斯的中心。它是 艾露恩姐妹会 的主要圣殿，泰兰德在主圣殿大厅正上方的上层接见来访者。",al={"月神殿 位置","月神殿 在哪里","在哪里可以找到泰兰德"}}},fp="18,247,32.385.0,22.423.1,27.198.0,27.228.0,49.181.0,57.244.0,37.193.0,32.185.0"}
P.entries["quest:98067"] = {n="Eyes of the Sentinels",s="“Eyes of the Sentinels”是一个达纳苏斯的任务，玩家需要协助哨兵达莉亚·阳刃在暗夜精灵主城的关键哨位部署魔法侦察猫头鹰。面对泰达希尔日益增长的不安局势，这种空中监视不仅加强了城市的防御，还让哨兵们有时间向艾露恩祈祷。",h="“Eyes of the...",kw={"塞纳里奥要塞","工匠区","达莉亚·阳刃","达纳苏斯","艾露恩","哨兵之眼","羽月","哨兵猫头鹰","泰达希尔","月神殿"},ang={["class:Hunter"]="部署侦察猫头鹰体现了典型的暗夜精灵侦察手段，即训练有素的野兽和天上的禽类守望者是女猎手感知的自然延伸。",["class:Priest"]="哨兵们强调，仅靠武器无法保护卡多雷；定期的祈祷和来自艾露恩的精神馈赠对于她们的守护工作至关重要。",["faction:Alliance"]="确保达纳苏斯的安全可以保障暗夜精灵的首都，并巩固联盟在卡利姆多北部的核心据点。",["race:NightElf"]="哨兵部队是暗夜精灵传统的常备军和守护者，她们将武技与艾露恩的神圣祝福及注视结合在一起。"},sec={{t="奉献与防御",b="在月神殿的神圣庇护所中，哨兵达莉亚·阳刃负责守护达纳苏斯。遵照珊蒂斯·羽月将军的谕令——即每一位战士都必须兼顾武技与精神奉献——达莉亚安排在城市的各个关键枢纽部署警觉的哨兵猫头鹰。承担这些日常职责让哨兵们在月亮女神面前获得了宝贵的祈祷与反思时间，同时也确保了卡多雷首都始终处于严密的防守之下。"},{t="守望达纳苏斯",b="泰达希尔上空弥漫着不安的气息，促使哨兵们加倍警惕。为了防范渗透和动乱，哨兵猫头鹰被部署在关键路口：北部的塞纳里奥要塞下方深处、镇中心的繁华银行、工匠区内的旅店，以及主城门处。在当地城卫的协助下，这些禽类哨兵化身为沉默的守护者，监视着每一位行走在世界之树街道上的人。"}},faq={{q="什么是“哨兵之眼”？",a="“哨兵之眼”是达纳苏斯的一项任务，冒险者通过在城市各处的关键位置部署哨兵猫头鹰，协助哨兵达莉亚·阳刃维持警惕，以应对迫在眉睫的威胁。",al={"哨兵之眼任务","什么是哨兵之眼","哨兵之眼概述"}},{q="谁是哨兵达莉亚·阳刃？",a="哨兵达莉亚·阳刃是一位驻守在达纳苏斯月神殿的卡多雷守护者，她负责监督当地的防御常规，并确保警觉的猫头鹰能守卫城市的关键通路。",al={"谁是达莉亚·阳刃","达莉亚·阳刃背景故事","哨兵达莉亚·阳刃"}},{q="为什么要将哨兵猫头鹰安置在达纳苏斯各处？",a="哨兵猫头鹰是警觉的空中哨兵，也是艾露恩赐予的神圣侦察者，使哨兵们能够监视达纳苏斯各处的关键聚集点和交通咽喉。",al={"为什么要放置哨兵猫头鹰","哨兵猫头鹰的作用","哨兵猫头鹰的目的"}},{q="哨兵猫头鹰被放置在哪里？",a="哨兵猫头鹰被部署在北部塞纳里奥要塞下方深处的入口、镇中心的达纳苏斯银行、工匠区的旅店以及城市大门处。",al={"猫头鹰放置点","猫头鹰在哪里","哨兵之眼地点"}},{q="为什么哨兵们在泰达希尔处于高度戒备状态？",a="哨兵达莉亚·阳刃指出，泰达希尔世界之树的各个地方都有些不对劲，这促使哨兵们加强监视，时刻准备应对潜伏的危险。",al={"为什么哨兵感到担忧","泰达希尔出了什么问题","泰达希尔的不安"}},{q="羽月将军在哨兵的日常职责中扮演什么角色？",a="珊蒂斯·羽月将军统领着哨兵部队，并确保她的女猎手们能够平衡武职责任与对月亮女神艾露恩的日常奉献和祈祷。",al={"羽月将军的角色","珊蒂斯·羽月与哨兵","羽月的祈祷准则"}}},fp="21,165,20.384.0,20.363.0,30.164.0,31.167.0,52.151.0,35.181.0,50.158.0,71.144.0"}
P.entries["quest:98069"] = {n="Stolen Freewind Supplies",s="乱风岗的詹迪亚需要从 harpy 手中夺回被盗物资。若没有下一批补给，岗哨很快就会短缺。",h="乱风岗的詹迪亚需要从 harpy 手中夺回被盗物资。若没有下一批补给，岗哨很快就会短缺。",kw={"商队","洞穴","悬崖","乱风岗","鹰身人","詹迪亚","乱风岗被盗补给","补给"},sec={{t="失踪的补给",b="harpy 袭击了最后一支原定向乱风岗运送补给的商队。詹迪亚说，岗哨眼下的物资还够用，但若没有更多补给，这些物资撑不了多久。它们的巢穴在此处以西，沿着悬崖底部，还在上方的一个洞穴里。"}},faq={{q="谁需要这些补给？",a="乱风岗的詹迪亚需要找回被盗的补给。",al={"谁需要补给","詹迪亚补给","乱风岗补给"}},{q="是谁抢走了商队的补给？",a="鹰身人袭击了最后一支原定向乱风岗运送补给的商队。",al={"是谁偷了补给","鹰身人补给","鹰身人偷了什么"}},{q="鹰身人的巢穴在哪里？",a="鹰身人在乱风岗以西筑巢，巢穴位于悬崖底部和顶部的一个洞穴内。",al={"鹰身人在哪里","鹰身人洞穴","西边的鹰身人"}},{q="詹迪亚为什么需要找回这些补给？",a="乱风岗眼下的补给还够用，但若没有下一批补给，很快就会短缺。",al={"为何找回补给","乱风岗补给短缺","补给为何重要"}},{q="詹迪亚让你找回什么？",a="詹迪亚让你为乱风岗找回八份被盗的补给。",al={"需要多少补给","被盗物品","要带回什么"}}},fp="24,147,20.239.0,23.60.0,32.69.0,24.87.0,31.95.0,36.67.0"}
P.entries["quest:98070"] = {n="Stop the Screeching",s="尖啸峡谷的 harpy 袭击了前往乱风岗的补给商队。它们的袭击威胁着这些旅程能否继续。",h="尖啸峡谷的 harpy 袭击了前往乱风岗的补给商队。它们的袭击威胁着这些旅程能否继续。",kw={"商队","乱风岗","鹰身人","飞羽","尖啸峡谷","尖啸 鹰身人","制止尖啸","补给","风语者"},sec={{t="商队危在旦夕",b="一名供应商担心，如果 harpy 继续袭击，商队就会停止前往乱风岗。你受托消灭 Screeching Harpy、尖啸的游荡者 Harpy 和 Screeching Windcaller。敢于穿越峡谷的商队仍面临危险。"},{t="通知供应商",b="解决 harpy 后，供应商会通知为乱风岗提供货物的人。商队在旅途中将少面对一种威胁。"}},faq={{q="商队为何遭到袭击？",a="最近几支经过尖啸峡谷的补给商队都遭到了鹰身人袭击。",al={"袭击商队的 鹰身人","鹰身人 为何袭击","商队遇袭"}},{q="如果袭击继续，会有什么危险？",a="供应商担心，如果袭击持续下去，就不会有商队敢前往乱风岗。",al={"为何保护商队","乱风岗补给","商队停运"}},{q="涉及哪些鹰身人？",a="提到的鹰身人有尖啸的鹰身人、尖啸的游荡者鹰身人和尖啸的唤风者。",al={"鹰身人 种类","尖啸 鹰身人","飞羽 风语者"}},{q="鹰身人在哪里？",a="这些鹰身人生活在尖啸峡谷。",al={"鹰身人 位置","尖啸峡谷 鹰身人","尖啸峡谷在哪里"}}},fp="19,137,16.250.0,17.163.1,36.89.0,40.89.0,27.96.0,22.38.0"}
P.entries["quest:98071"] = {n="Brewer's Trade",s="我们与丹加洛克的酿酒同族达成了一项交易，他们和任何人一样怀念法洛克家族的葡萄园。一箱法洛克特酿会被运往位于希尔斯布莱德丘陵东南部的堡垒，作为回报，我们将带回一袋他们的自酿啤酒花。",h="我们与丹加洛克的酿酒同族达成了一项交易，他们和任何人一样怀念法洛克家族的葡萄园。一箱法洛克特酿会被运往位于希尔斯布莱德丘陵东南部的堡垒，作为回报，我们将带回一袋他们的自酿啤酒花。",kw={"酿酒同族","丹加洛克","法洛克","法洛克特酿","希尔斯布莱德","自酿啤酒花","啤酒花","葡萄酒"},sec={{t="往昔的味道",b="法洛克葡萄酒最棒的陈酿大多早已被饮尽，但仍有一些法洛克特酿存放在地窖中。丹加洛克的酿酒同族也很怀念法洛克家族的葡萄园，因此我们与他们达成了一项交易。"},{t="丹加洛克的交换",b="将那箱酒运往东南方的丹加洛克，放在他们堡垒底部聚集处的壁炉旁。作为回报，你将带回一袋他们的自酿啤酒花。"}},faq={{q="这次交换交易了什么物品？",a="一箱从地窖运出的法洛克特酿葡萄酒，用于交换一袋他们的自酿啤酒花。",al={"我送的是什么","酿酒师的交易物品","法洛克葡萄酒"}},{q="在丹加洛克，酒需要被送到哪里？",a="你需要把它留在堡垒底部，也就是他们聚集处的壁炉旁。",al={"壁炉在哪里","丹加洛克交付地点","把酒留在哪里"}},{q="丹加洛克位于何处？",a="丹加洛克位于希尔斯布莱德丘陵的东南部。",al={"丹加洛克位置","丹加洛克在哪里"}},{q="法洛克一家是谁？",a="法洛克家族经营的葡萄园令人怀念。他们最棒的陈酿大多早已被饮尽，不过地窖里还剩有一些。",al={"法洛克家族","法洛克葡萄园"}}},fp="14,183,19.181.0,25.165.0,38.126.0,44.103.0,27.55.0,23.166.0"}
P.entries["quest:98072"] = {n="Crocs of the Sky",s="詹姆斯询问你是否拿到了鳞片，随后称赞你的天赋。如果你有一天不再冒险，他愿意给你安排工作。",h="詹姆斯询问你是否拿到了鳞片，随后称赞你的天赋。如果你有一天不再冒险，他愿意给你安排工作。",kw={"冒险","空中的鳄鱼","詹姆斯","鳞片","工作"},sec={{t="詹姆斯的提议",b="詹姆斯称你天赋过人，并邀请你在暂停冒险后回来找他。他开玩笑说，那时你可能年纪更大了。"}},faq={{q="谁在询问鳞片？",a="詹姆斯询问你是否拿到了鳞片。",al={"谁想要鳞片","给詹姆斯的鳞片"}},{q="詹姆斯怎么看我？",a="詹姆斯称你天赋过人。",al={"詹姆斯喜欢我吗","詹姆斯的看法"}},{q="詹姆斯提出了什么？",a="詹姆斯愿意在你暂停冒险后给你安排工作。",al={"詹姆斯的工作","工作提议"}}},fp="16,111,13.131.0,31.39.0,28.38.0,22.59.0"}
P.entries["quest:98094"] = {n="Scout Support",s="高级执行官达萨利亚派你将最新命令送给塔伦米尔以南的死亡猎手 Masoj。此行将助被遗忘者夺取这片土地的控制权。",h="高级执行官达萨利亚派你将最新命令送给塔伦米尔以南的死亡猎手 Masoj。此行将助被遗忘者夺取这片土地的控制权。",kw={"死亡猎手 马索伊","丹加洛克","被遗忘者","前线间谍","高级执行官达萨利亚","奈杉德哨岗","支援斥候","塔伦米尔","最新命令"},sec={{t="给 Masoj 的命令",b="达萨利亚说，她信得过你，可以把情报交给前线间谍。她给了你一份最新命令，要送给 Masoj。他驻守在奈杉德哨岗以北、丹加洛克外的一处高地上。被遗忘者夺取这片土地控制权的计划仍在继续，Masoj 正等着接收命令。"}},faq={{q="是谁给了我命令？",a="高级执行官达萨利亚给了你一份最新命令，要送给死亡猎手玛索伊。",al={"谁派我去","达萨利亚的命令","交付人"}},{q="死亡猎手玛索伊是谁？",a="死亡猎手玛索伊是一名驻守在丹加洛克外、奈杉德哨岗以北的前线间谍。",al={"马索伊 是谁","马索伊"}},{q="我该去哪里找玛索伊？",a="玛索伊在塔伦米尔以南、奈杉德哨岗以北的一处高地上，位于丹加洛克外。",al={"马索伊 的位置","马索伊 在哪里","塔伦米尔以南"}},{q="我要带什么给玛索伊？",a="你带着一份给死亡猎手玛索伊的最新命令。",al={"要送什么","给 马索伊 的命令","包裹"}},{q="我为什么要送命令？",a="此行将助被遗忘者夺取这片土地的控制权。",al={"为什么找 马索伊","计划是什么","被遗忘者的计划"}}},fp="13,164,16.293.0,23.71.0,26.87.0,22.96.0,28.48.0,27.72.0"}
P.entries["quest:98095"] = {n="Valuable Vantages",s="亡灵哨兵 Masoj 需要你在希尔斯布莱德丘陵周围恢复三处信号标记。蝙蝠骑手依靠这些地点，引导战略部队前往投放点。",h="亡灵哨兵 Masoj 需要你在希尔斯布莱德丘陵周围恢复三处信号标记。蝙蝠骑手依靠这些地点，引导战略部队前往投放点。",kw={"药剂师药瓶","蝙蝠骑手","亡灵哨兵 马索伊","丹加洛克","敦霍尔德城堡","海岬","希尔斯布莱德丘陵","信号烽火","宝贵的制高点"},sec={{t="三座山峰",b="你带着药剂师药瓶，前往丹加洛克旁的山丘、敦霍尔德城堡上方的高原，以及希尔斯布莱德上方的海岬山脊。药瓶散发的气味会引回蝙蝠，帮助 Masoj 的高层指挥官引导部队穿过丘陵地带。"},{t="Masoj 的命令",b="Masoj 要你寻找破碎的空药瓶，并在三处地点重新布置信号。他称这项工作是以亡灵哨兵之名推进计划的一部分。"}},faq={{q="是谁要我放置药瓶？",a="亡灵哨兵玛索伊要你恢复希尔斯布莱德丘陵周围的信号标记。",al={"谁提出了宝贵的制高点","马索伊 药瓶","马索伊 是谁"}},{q="为什么需要这些信号标记？",a="蝙蝠骑手利用信号点，引导战略部队前往投放点。",al={"蝙蝠为何需要标记","蝙蝠信号","信标有何用途"}},{q="我该把药瓶放在哪里？",a="三处地点分别是丹加洛克旁的山丘、敦霍尔德城堡上方的高原，以及希尔斯布莱德上方的海岬山脊。",al={"药瓶位置","山峰在哪里","三个药瓶放置点"}},{q="药瓶散发的气味有什么作用？",a="这些气味会发出信号，将蝙蝠引回指定的投放点。",al={"药瓶有什么用","蝙蝠气味","药瓶用途"}}},fp="17,169,11.261.0,14.164.0,36.86.0,35.80.0,27.119.0,27.57.0"}
P.entries["quest:981"] = {n="奥萨拉克斯之塔",s="这一差事标志着针对奥萨拉克斯之塔黑滩教派的战役取得了胜利。在消灭了黑海岸邪恶废墟中该教派的领导层后，冒险者将消息带往南方的灰谷，传达给净化者德尔格伦。这对联盟来说是一次至关重要的胜利，清除了古代暗夜精灵边境的恶魔腐蚀。",h="这一差事标志着针对奥萨拉克斯之塔黑滩教派的战役取得了胜利。在消灭了黑海岸邪恶废墟中该教派的领导层后，冒险者将消息带往南方的灰谷，传达给净化者德尔格伦。这对联盟来说是一次至关重要的胜利，清除了古代暗夜精灵边境的恶魔腐蚀。",kw={"奥萨拉克斯","灰谷","巴苏尔","教派","黑滩","黑海岸","德尔格伦","迈斯特拉岗哨"},ang={["class:Paladin"]="向净化者德尔格伦报告对圣骑士来说有着特殊的意义，他们与他有着共同的圣洁使命，即从世界上净化恶魔腐蚀和邪恶教派。",["faction:Alliance"]="消灭该教派保护了连接黑海岸和灰谷的陆路，确保联盟的侦察兵和旅行者免受恶魔伏击的安全。",["race:NightElf"]="对于暗夜精灵来说，净化奥萨拉克斯之塔消除了玷污他们神圣沿海森林的古代上层精灵遗迹中的污秽。"},sec={{t="切断威胁",b="奥萨拉克斯之塔在黑海岸北部矗立了数周，像是一道化脓的伤口，被狂热的黑滩教派及其阴影主人所占据。通过不懈的追踪、情报收集和激烈的冲突，该教派的行动被彻底瓦解。随着他们的术士被杀，黑暗仪式被破坏，黑海岸恶魔渗透的直接威胁终于得到了遏制。"},{t="向迈斯特拉岗哨报告",b="在教派领袖死亡后，巴苏尔·影击指引胜利者前往南方的灰谷迈斯特拉岗哨。净化者德尔格伦正在那里等待，他是圣光的忠实战士，负责监督针对奥萨拉克斯之塔邪恶占领者的十字军行动。传达教派覆灭的消息让区域防御者感到安心，同时也为这位勇士赢得了德尔格伦永恒的祝福和当之无愧的感激。"}},faq={{q="这个任务的目标是什么？",a="这个任务是漫长的奥萨拉克斯之塔任务线的最后一步。你只需要从塔附近前往灰谷的迈斯特拉岗哨，并将你的决定性胜利报告给净化者德尔格伦。",al={"奥萨拉克斯之塔目标","奥萨拉克斯之塔任务提交","981号任务在哪里提交"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷北部迈斯特拉岗哨的联盟勇士。他手握圣光，致力于在整个卡利姆多北部清除腐蚀并对抗像黑滩教派这样的恶魔威胁。",al={"谁是德尔格伦","德尔格伦背景故事","净化者德尔格伦"}},{q="巴苏尔·影击是谁？",a="巴苏尔·影击是一位在黑海岸奥萨拉克斯之塔附近执行任务的联盟特工。他与德尔格伦密切合作，监控教派的动向，并引导冒险者从内部瓦解这个黑暗集团。",al={"巴苏尔","巴苏尔背景故事","谁是巴苏尔·影击"}},{q="黑滩教派在塔里做了什么？",a="黑滩教派占据了奥萨拉克斯之塔的古代遗迹，以进行黑暗仪式、召唤恶魔实体，并扩大他们在黑海岸沿海地区的邪恶影响力。",al={"黑滩教派","奥萨拉克斯发生了什么","奥萨拉克斯之塔背景故事"}},{q="迈斯特拉岗哨位于哪里？",a="迈斯特拉岗哨是一个位于灰谷西北部的联盟哨所，就在沿大路从黑海岸过来的边界关卡以南。",al={"迈斯特拉岗哨位置","迈斯特拉岗哨在哪里","德尔格伦位置"}},{q="黑滩教派被彻底消灭了吗？",a="虽然他们在奥萨拉克斯之塔的领导层已被处决，主要的仪式已被破坏，但分散的教徒和残党仍然在卡利姆多偏僻的角落出没。然而，他们在黑海岸的有组织威胁已被粉碎。",al={"教派消失了吗","黑滩教派被摧毁","我们杀死了教派吗"}}},fp="22,192,16.329.0,24.372.0,31.186.0,28.248.0,29.205.0,56.189.0,32.129.0,52.239.0"}
P.entries["quest:98155"] = {n="Pristine Pesterhide Pelts",s="“Pristine Pesterhide Pelts”是一项代表克里斯蒂·格兰特进行的任务，她是一位旅行者，正在千针石林寻找Pesterhide土狼那色彩鲜艳的毛皮。由于缺乏战斗训练，克里斯蒂依靠能干的冒险者来猎杀这些野兽并收集它们的毛皮。她的目标是将这些独特的皮毛运回无尽之海彼岸的暴风城，交给她的姐妹们，让她们将其制作成精致的服装和商品。",h="“Pristine Pesterhide...",kw={"毛皮","狩猎","土狼","克里斯蒂·格兰特","杂斑","暴风城","千针石林"},ang={["faction:Alliance"]="作为一位暴风城旅行者为她在首都从事工艺创作的家族提供供应的努力，这项任务凸显了联盟子民如何深入卡利姆多边境寻找异域材料。",["profession:Tailoring"]="从事布料和装饰性皮草工作的工匠们能够理解克里斯蒂姐妹们的雄心，她们试图将卡利姆多的野性毛皮转化为精致的服装。",["race:Human"]="克里斯蒂·格兰特体现了暴风城人类跨海远行、与王国内亲人保持密切联系的进取精神。"},sec={{t="姐妹的志向",b="远离暴风城繁华的鹅卵石街道，克里斯蒂·格兰特发现自己正穿行于千针石林那干旱、被阳光炙烤的峡谷底部。在观察当地野生动物时，她被本土Pesterhide土狼所披皮毛那令人惊叹的色泽和品质所吸引。克里斯蒂意识到这些独特的毛皮在东部王国几乎闻所未闻，于是她设想将一批毛皮运回故乡交给她的姐妹们。在她眼中，这些毛皮不仅是卡利姆多边境的一抹特色，更是原料，能经由家族中熟练的工匠之手，转化为真正非凡的物品。"},{t="盐碱平原与峡谷的猎人",b="尽管拥有工艺和贸易的眼光，克里斯蒂·格兰特并非战士，也没有面对峡谷中凶猛掠食者的战斗经验。Pesterhide土狼是凶残的群体食腐动物，游荡在参天平顶山下的尘土旷野中，这使得对于任何独自旅行的人来说，收获完整的毛皮都十分危险。为了在不危及自己生命的情况下获得五张无瑕的毛皮，克里斯蒂寻求路过千针石林的资深冒险者的帮助。这项任务需要冒险进入荒野，战胜那些领地意识极强的野兽，并仔细收集她家族在故乡进行工艺创作所需的毛皮。"}},faq={{q="谁是克里斯蒂·格兰特？",a="克里斯蒂·格兰特是一位来自暴风城王国的旅行者，目前正在卡利姆多游历。与穿行于千针石林的强硬士兵和雇佣兵不同，她承认自己没有任何战斗经验。相反，她依靠敏锐的观察力和对贵重工艺材料的独到眼光，雇佣能干的冒险者代她收集像土狼毛皮这样的货物。",al={"克里斯蒂·格兰特背景故事","谁发布了完整的星斑土狼毛皮任务","克里斯蒂·格兰特是谁"}},{q="什么是杂毛土狼？",a="杂毛土狼是原产于千针石林干旱峡谷底部和旷野的野生犬科掠食者。它们成群结队地在严酷的地形中游荡，进行狩猎和食腐。除了凶猛的本性外，它们还因其绚丽、色彩优美的皮毛而闻名，这些皮毛在沙漠岩石的映衬下显得格外显眼，吸引了过往裁缝和皮草商的注意。",al={"星斑土狼","千针石林的土狼","什么是星斑土狼"}},{q="为什么克里斯蒂·格兰特想要这些毛皮？",a="克里斯蒂·格兰特想要收集完整的土狼毛皮，并将它们运回无尽之海彼岸的暴风城王国交给她的姐妹们。她对这些毛皮绚丽的色泽印象深刻，并相信她的姐妹们拥有将这些异域皮毛编织或剪裁成令人惊叹的成品所需的工艺。",al={"为什么要收集星斑土狼毛皮","星斑土狼毛皮的用途","克里斯蒂如何处理这些毛皮"}},{q="这些毛皮最终会去哪里？",a="在千针石林收集的毛皮最终将运往东部王国，具体来说是暴风城这座城邦。克里斯蒂打算将收获的毛皮运回无尽之海彼岸的故乡，这样她的姐妹们就可以使用那些在艾尔文森林或赤脊山等熟悉的林地中几乎无法获得的异域材料进行创作。",al={"毛皮被运往何处","运往暴风城的毛皮","谁获得了这些土狼毛皮"}},{q="为什么克里斯蒂不能自己猎杀土狼？",a="克里斯蒂·格兰特公开承认她完全没有任何战斗经验。千针石林的野兽极具攻击性且危险重重，特别是对于手无寸铁的工匠或旅行者而言。与其在游荡的土狼群面前冒受伤或死亡的风险，她雇佣熟练的流浪者来安全地猎杀这些动物。",al={"为什么克里斯蒂不能战斗","克里斯蒂·格兰特的战斗能力","为什么克里斯蒂需要帮助"}},{q="是什么让这些毛皮被称为“完整的”（完整的）？",a="由于这些毛皮旨在供克里斯蒂在暴风城的姐妹们进行精细的工艺和时尚创作，普通的或破损的毛皮是不够的。只有未受损、完整的毛皮才能保留制作高质量服装所需的鲜艳色泽和质地，因此必须小心狩猎，并从野兽身上精心挑选出最好的样本。",al={"完整毛皮的含义","为什么需要完整的毛皮","完整的星斑土狼毛皮的质量"}}},fp="25,191,19.290.0,37.280.0,20.213.0,27.221.0,37.183.0,26.185.0,41.198.0,32.139.0"}
P.entries["quest:98156"] = {n="Packaged Pristine Pelts",s="一位旅人请你把完好的毛皮送给她在暴风城的姐妹。你能在她回家前将毛皮送到。",h="一位旅人请你把完好的毛皮送给她在暴风城的姐妹。你能在她回家前将毛皮送到。",kw={"kelly","kimberly grant","包裹","花园区","完好的毛皮","姐妹","暴风城"},sec={{t="送给家人的包裹",b="一位身在暴风城花园区的旅人请你将一包完好的毛皮交给Kimberly Grant。她暂时无法回家，估计你会先抵达暴风城。她的姐妹Kelly和Kimberly通常都在花园区。"}},faq={{q="是谁要送出这些毛皮？",a="一位旅人请你把完好的毛皮送给她的姐妹Kelly和Kimberly。",al={"谁给了我毛皮","毛皮交付委托人"}},{q="包裹应该交给谁？",a="包裹要交给暴风城的Kimberly Grant。",al={"毛皮送给谁","交给kimberly"}},{q="我能在哪里找到这对姐妹？",a="Kelly和Kimberly通常都在暴风城的花园区。",al={"kelly和kimberly的位置","暴风城的姐妹"}},{q="我为什么要带着这些毛皮？",a="这位旅人暂时无法回到暴风城，因此请你把毛皮带给她的姐妹。",al={"为什么要送毛皮","毛皮包裹的缘由"}}},fp="23,128,17.239.0,30.85.0,31.62.0,29.65.0,28.101.0"}
P.entries["quest:98189"] = {n="归还雕像",s="找回的雕像原本要送往米奈希尔港，却因一场悲剧而未能送达。有人请你将它交给米奈希尔城堡的斯托菲队长。",h="找回的雕像原本要送往米奈希尔港，却因一场悲剧而未能送达。有人请你将它交给米奈希尔城堡的斯托菲队长。",kw={"盲眼公主","斯托菲队长","米奈希尔港","米奈希尔城堡","米奈希尔雕像","雕像"},sec={{t="未完成的交付",b="这尊雕像原本要送到米奈希尔港，并由米奈希尔城堡的斯托菲队长签收。有人请你完成这次交付。"}},faq={{q="谁应该接收这尊雕像？",a="米奈希尔城堡的斯托菲队长应该签收米奈希尔雕像。",al={"谁接收雕像","雕像接收者","斯托菲队长交付"}},{q="这尊雕像原本要送到哪里？",a="这尊雕像原本要送往米奈希尔港。",al={"雕像送往何处","雕像目的地","米奈希尔雕像"}},{q="之前是谁带着它？",a="悲剧发生前，盲眼公主原本要送交这尊雕像。",al={"谁带着雕像","盲眼公主雕像","雕像交付"}},{q="我该做什么？",a="有人请你将米奈希尔雕像交给米奈希尔城堡的斯托菲队长。",al={"该做什么","归还雕像","雕像任务"}}},fp="20,134,22.156.0,38.82.0,39.59.0,27.79.0,26.84.0"}
P.entries["quest:98190"] = {n="A Friend of the Family",s="“家族之友”是一项紧急的快递任务，始于湿地的米奈希尔港。由于担心龙喉兽人等当地威胁，港口当局委托一位冒险者将无价的米奈希尔雕像直接送到暴风城的暴风城要塞，交给伯瓦尔·弗塔根公爵。",h="“家族之友”是一项紧急的快递任务，始于湿地的米奈希尔港。由于担心龙喉兽人等当地威胁，港口当局委托一位冒险者将无价的米奈希尔雕像直接送到暴风城的暴风城要塞，交给伯瓦尔·弗塔根公爵。",kw={"伯瓦尔","龙喉氏族","弗塔根","港口","米奈希尔","雕像","暴风城","泰瑞纳斯","湿地"},ang={["class:Paladin"]="“米奈希尔”这个名字让人想起白银之手骑士团的创始赞助人，因此保护这件遗物对任何圣光战士来说都是庄严的职责。",["faction:Alliance"]="运送这件遗物不仅是为了纪念历史悠久的北方联盟，还能防止它落入龙喉氏族的手中。",["race:Human"]="对于人类来说，守护米奈希尔王朝的一件文物，就是守护陨落的洛丹伦那份引以为傲却又充满悲剧色彩的记忆，同时也强化了暴风城作为最后伟大人类王国的职责。"},sec={{t="岌岌可危的港口",b="米奈希尔港是连接东部王国北部和南部的关键海上门户。该港口以洛丹伦已故国王泰瑞纳斯·米奈希尔二世的名字命名，孤立在危险的沼泽和充满敌意的敌人之中。随着当地威胁的增加，港口领导层认识到，与北方陨落王国相关的无价遗物无法在这样一个暴露的前哨站中得到安全保护。"},{t="龙喉氏族的威胁",b="湿地仍然盘踞着龙喉氏族的残党，这些野蛮的兽人以其黑暗的过去和无情的投机主义而闻名。鉴于他们就在附近且渴望征服，港口守卫担心龙喉氏族会不择手段地掠夺像米奈希尔雕像这样的历史珍宝，甚至可能为了自己的目的而亵渎或将这种象征武器化。"},{t="直接面见公爵",b="为了避免通过常规官僚或军事渠道造成的延误，快递员被指示完全绕过指挥链。遗物被直接发往暴风城要塞，交到年轻的安度因·乌瑞恩国王的摄政王——伯瓦尔·弗塔根公爵手中，坚信首都的领导层最能保护这份洛丹伦的遗产。"}},faq={{q="什么是米奈希尔雕像？",a="米奈希尔雕像是一件与洛丹伦王室血统和泰瑞纳斯·米奈希尔二世国王有关的珍贵传家宝。它代表了北方王国与联盟之间的历史纽带，使其成为了拾荒者和敌人的目标。",al={"米奈希尔遗物","雕像是什么","雕像背景"}},{q="为什么雕像不能留在米奈希尔港？",a="米奈希尔港位置偏远，四周环绕着充满敌意的沼泽、黑铁矮人、鱼人和敌对兽人。驻军认为该定居点过于脆弱，无法安全保护如此重要的遗物。",al={"为什么要转移雕像","米奈希尔港不安全吗"}},{q="龙喉氏族是谁，为什么他们想要它？",a="龙喉氏族是盘踞在湿地内的一支兽人派系。港口官员担心他们会不惜牺牲战士来掠夺享有盛誉的联盟遗物，并可能对其进行亵渎或恶意利用。",al={"龙喉氏族威胁","为什么兽人想要雕像"}},{q="为什么要将遗物直接交给伯瓦尔·弗塔根？",a="作为暴风城的摄政王和年轻的安度因国王的守护者，伯瓦尔·弗塔根公爵在首都拥有最高行政权力。直接交给他可以确保遗物绕过行政僵局，并获得最高级别的安全保障。",al={"为什么是伯瓦尔","为什么要绕过指挥链"}},{q="伯瓦尔·弗塔根公爵在哪里？",a="伯瓦尔·弗塔根公爵站在暴风城要塞的王座大厅里，与年幼的安度因·乌瑞恩国王在一起。",al={"伯瓦尔位置","伯瓦尔在哪里"}},{q="米奈希尔港与泰瑞纳斯国王有什么联系？",a="米奈希尔港是为了纪念泰瑞纳斯·米奈希尔二世国王而命名的，他在第三次战争中不幸去世之前，曾领导洛丹伦并在第二次战争期间支持洛丹伦联盟。",al={"为什么叫米奈希尔港","泰瑞纳斯·米奈希尔联系"}}},fp="22,170,19.295.0,20.229.0,24.269.0,31.211.0,48.159.0,46.187.0,51.190.0,43.100.0,49.159.0"}
P.entries["quest:98191"] = {n="A Friend of the Family",s="伯瓦尔·弗塔根公爵委托一位冒险者将一座珍贵的米奈希尔雕像送到光明大教堂。这座遗物描绘了洛丹伦已故的国王泰瑞纳斯·米奈希尔二世，它已经开始汇聚圣光之力。它被移交给格雷森·沙东布瑞克公爵，以在暴风城的精神中心进行永久保存。",h="伯瓦尔·弗塔根公爵委托一位冒险者将一座珍贵的米奈希尔雕像送到光明大教堂。这座遗物描绘了洛丹伦已故的国王泰瑞纳斯·米奈希尔二世，它已经开始汇聚圣光之力。它被移交给格雷森·沙东布瑞克公爵，以在暴风城的精神中心进行永久保存。",kw={"伯瓦尔","大教堂","洛丹伦","米奈希尔","沙东布瑞克","雕像","暴风城","泰瑞纳斯"},ang={["class:Paladin"]="对于一名圣骑士来说，守护一件带有圣光有形触感的泰瑞纳斯国王遗物，代表了对最初批准成立白银之手骑士团的统治者的深切敬意。",["class:Priest"]="在一尊简单的雕像中汇聚圣光能量，印证了洛丹伦信徒即使在王国物质毁灭之后，依然长存的精神遗产。",["faction:Alliance"]="泰瑞纳斯·米奈希尔二世国王是洛丹伦联盟的基石，这使得任何与他有关的文物都成为团结和纪念的宝贵象征。"},sec={{t="一份珍贵的纪念品",b="泰瑞纳斯·米奈希尔二世国王是第二次战争期间大联盟的缔造者，也是一位极具个人奉献精神的人。尽管他在人类诸王国中地位崇高，泰瑞纳斯却非常谦逊，并以不喜欢为自己树碑立传而闻名。由于他的个人抵触，很少有人委托制作他的肖像，而在洛丹伦遭受恐怖的毁灭和天灾军团的蹂躏后，幸存下来的就更少了。"},{t="神恩的触碰",b="当伯瓦尔·弗塔根公爵检查幸存的米奈希尔雕像时，他发现了远超简单工艺的东西。圣光本身已经开始在这尊雕像内汇聚，赋予其宁静的精神共鸣。伯瓦尔认为暴风要塞的皇宫对于这样一件神圣的物品来说并不是合适的圣所，于是他指示将其带过城市送到光明大教堂，交由圣骑士训练师格雷森·沙东布瑞克公爵保管。"}},faq={{q="泰瑞纳斯·米奈希尔二世国王是谁？",a="泰瑞纳斯·米奈希尔二世国王是洛丹伦王国的受人爱戴的统治者。在第二次战争期间，他召集了不同的人类国家，并与矮人、侏儒和高等精灵联手组建了大联盟，最终击败了兽人部落。他在自己王国的陷落中被杀。",al={"泰瑞纳斯·米奈希尔","泰瑞纳斯是谁","洛丹伦国王"}},{q="为什么泰瑞纳斯国王的雕像如此稀少？",a="尽管他享有崇高的声望并深受人民爱戴，泰瑞纳斯国王却以个人谦逊而闻名，不喜欢奢华的自我纪念碑。很少有雕像或纪念碑是以他的形象雕刻的，而且几乎没有在洛丹伦的天灾毁灭中幸存下来。",al={"为什么雕像很少","米奈希尔雕像的稀有度","为什么纪念碑很少"}},{q="为什么米奈希尔雕像会散发出圣光？",a="伯瓦尔注意到圣光似乎已经在雕像中汇聚。他称赞泰瑞纳斯是一位善良而虔诚的人，但并没有解释为什么这座特定的雕像会聚集圣光之力。",al={"为什么雕像有圣光","神圣雕像","汇聚的圣光"}},{q="格雷森·沙东布瑞克公爵是谁？",a="格雷森·沙东布瑞克公爵是一位白银之手骑士团的人类老兵圣骑士，也是光明大教堂内的一位杰出大师。他驻扎在教堂广场，负责训练有志向的圣骑士，并为暴风城的信徒监督圣职事务。",al={"沙东布瑞克是谁","格雷森的角色"}},{q="为什么伯瓦尔公爵要将雕像送到光明大教堂？",a="虽然伯瓦尔尊崇泰瑞纳斯作为联盟之父的角色，但雕像已经明显聚集了圣光之力。伯瓦尔认为，这种圣光的载体不属于暴风要塞的宫廷官僚，而应该在圣职教团的照看下存放在光明大教堂中。",al={"为什么要送到大教堂","为什么不留在暴风要塞"}},{q="光明大教堂位于何处？",a="光明大教堂俯瞰着教堂广场，位于暴风城的中心地带，处于矮人区、贸易区和法师区之间。它是南部王国圣光教会的主要圣所和礼拜中心。",al={"光明大教堂在哪里","教堂广场的位置"}}},fp="22,156,18.328.0,16.369.0,33.285.0,40.164.0,53.156.0,34.250.0,61.248.0,40.251.0"}
P.entries["quest:98197"] = {n="Spoils of War",s="瓦斯塔格·铁腭需要来自米奈希尔港的卡兹莫丹木材和铁料。这些找回的物资将帮助加固城镇防御，抵御龙喉氏族的进犯。",h="瓦斯塔格·铁腭需要来自米奈希尔港的卡兹莫丹木材和铁料。这些找回的物资将帮助加固城镇防御，抵御龙喉氏族的进犯。",kw={"龙喉氏族","卡兹莫丹铁料","卡兹莫丹木材","米奈希尔港","旧部落","战争掠夺品","城镇防御","瓦斯塔格·铁腭"},ang={["faction:Alliance"]="作为一名联盟旅者，你正在帮助加强城镇防御，抵御龙喉氏族。",["race:Dwarf"]="作为一名矮人，你或许会注意到，旧部落当年在此建造舰队，所用资源都是从卡兹莫丹掠夺而来。"},sec={{t="港口仓库",b="米奈希尔港最初是旧部落入侵希尔斯布莱德的集结地。他们在那里建造舰队，所用资源都是从卡兹莫丹掠夺而来，港口里至今还留有部分物资。瓦斯塔格请你把木材和铁料带给他，用来支援城镇防御。"},{t="新的补给",b="瓦斯塔格感谢你带来的物资。有了它们，城镇就不必只依赖塞拉摩或奥伯丁运来的补给。"}},faq={{q="瓦斯塔格需要从米奈希尔港找回什么？",a="瓦斯塔格请你从米奈希尔港找回卡兹莫丹木材和铁料。",al={"他需要什么","木材和铁料","港口物资"}},{q="为什么港口里会有卡兹莫丹的物资？",a="旧部落在米奈希尔港建造舰队，所用资源都是从卡兹莫丹掠夺而来。",al={"木材为何在港口","卡兹莫丹铁料","旧部落物资"}},{q="这些物资有什么用？",a="瓦斯塔格说，这些物资能在龙喉氏族进犯时帮助加强城镇防御。",al={"为何收集物资","防御","这些物资有何用"}},{q="瓦斯塔格·铁腭是谁？",a="瓦斯塔格·铁腭请你从米奈希尔港找回木材和铁料。",al={"瓦斯塔格是谁","瓦斯塔格","铁腭"}},{q="旧部落曾如何利用米奈希尔港？",a="旧部落建造米奈希尔港，将其作为海上入侵希尔斯布莱德的集结地。",al={"旧部落港口","米奈希尔港历史","入侵希尔斯布莱德"}},{q="瓦斯塔格为何欢迎这些补给？",a="有了这些物资，城镇就不必只依赖塞拉摩或奥伯丁运来的补给。",al={"为何道谢","塞拉摩补给","奥伯丁物资"}}},fp="13,133,13.272.0,12.129.1,44.76.0,42.86.0,36.92.0,23.73.0,44.91.0,40.90.0"}
P.entries["quest:982"] = {n="深不可测的海洋",s="“深海，浩瀚之洋”是一个联盟任务，由奥伯丁的高尔博德·钢手提供。玩家的任务是潜入村庄北侧的水域，从两艘沉没的暗夜精灵船只——“银色黎明号”和“迷雾面纱号”中找回私人锁箱。这两艘船都遭到了沿海鱼人的伏击，幸存的船员们正急于寻求一个了结。",h="“深海，浩瀚之洋”是一个联盟任务，由奥伯丁的高尔博德·钢手提供。玩家的任务是潜入村庄北侧的水域，从两艘沉没的暗夜精灵船只——“银色黎明号”和“迷雾面纱号”中找回私人锁箱。这两艘船都遭到了沿海鱼人的伏击，幸存的船员们正急于...",kw={"奥伯丁","黑海岸","深海浩瀚之洋","高尔博德·钢手","锁箱","迷雾面纱号","鱼人","沉船","银色黎明号"},ang={["faction:Alliance"]="奥伯丁船员们共同的悲痛展现了矮人与暗夜精灵在卡利姆多海岸之间紧密的航海合作。",["race:Dwarf"]="高尔博德·钢手展现了矮人缅怀阵亡同伴、在异乡港口支持其他船员的典型本能。",["race:NightElf"]="阵亡的船长们是服务于奥伯丁海上贸易的暗夜精灵航海家，找回他们的遗物是一项关乎祖先荣誉的任务。"},sec={{t="海岸悲剧",b="黑海岸外的水域变得越来越危险，不仅仅是因为暗流和天然暗礁，还有极具攻击性的沿海部落。“银色黎明号”和“迷雾面纱号”在前往奥伯丁港口的途中，被成群的鱼人淹没。两艘船都没能幸免于难，沉没在定居点北部的浅滩中。幸存的船员虽然逃到了岸上，但船只和船长的损失给港口笼罩上了一层沉重的阴影。"},{t="找回失落的记忆",b="驻扎在奥伯丁的矮人高尔博德·钢手主动承担起缅怀阵亡暗夜精灵船长的责任。尽管这些船只现在已是水下废墟，被当地鱼人当作战利品和巢穴，但船长们的锁箱仍锁在进水的船舱里。找回里面的航海日志和个人物品，可以让奥伯丁的幸存船员们妥善哀悼他们的指挥官，并让逝者的灵魂得到安息。"}},faq={{q="沉船位于哪里？",a="“银色黎明号”和“迷雾面纱号”的残骸都淹没在黑海岸外，就在奥伯丁码头的正北方。",al={"沉船位置","沉船地点","在哪里找到银色黎明号"}},{q="“银色黎明号”和“迷雾面纱号”发生了什么事？",a="两艘船在穿越大海前往奥伯丁的途中都遭到了鱼人的伏击。船员们被鱼人压制，两位船长不幸丧生，船只沉没在海底。",al={"船只是如何沉没的","为什么船只沉没","什么让迷雾面纱号沉没"}},{q="高尔博德·钢手是谁？",a="高尔博德·钢手是一位居住在暗夜精灵港口奥伯丁的矮人。他照顾着镇上的幸存船员，并委托冒险者找回失踪船长的遗物。",al={"谁提供深海浩瀚之洋任务","高尔博德·钢手背景故事"}},{q="锁箱里有什么？",a="锁箱里装着阵亡的暗夜精灵船长的个人物品和航海日志，这些都是在海难中幸存的船员们所珍视的物品。",al={"锁箱里有什么","船长锁箱内容物"}},{q="为什么幸存者如此在意这些遗物？",a="这些船长是备受尊崇的暗夜精灵航海家。找回他们的日志和遗物是对幸存船员的一种慰藉，据信这也有助于让逝者的灵魂得到安息。",al={"为什么要找回锁箱","为什么要帮助船长"}},{q="现在是什么生物占据了沉船？",a="废墟已被鱼人占领，它们将沉没的船体当作战利品，并在周围的水域游荡。",al={"什么在守卫沉船","沉船处的怪物"}}},fp="20,205,21.245.0,24.307.0,35.71.0,54.167.0,25.141.0,29.126.0,54.150.0,42.102.0"}
P.entries["quest:98208"] = {n="Bloom of the Heavens",s="“天之绽”涉及到寻回诺德尔，这是一种神圣的暗夜精灵花卉，必须在满月时于海加尔山采集。这朵花在暗夜精灵船只“飞鱼号”于米奈希尔港以南遭遇海难时遗失了，与其一同沉没的还有库尔提拉斯第三舰队的船只。现在，找回这朵花的任务落在了那些勇敢到足以面对盘踞在残骸中的鱼人的冒险者手中。",h="“天之绽”涉及到寻回诺德尔，这是一种神圣的暗夜精灵花卉，必须在满月时于海加尔山采集。这朵花在暗夜精灵船只“飞鱼号”于米奈希尔港以南遭遇海难时遗失了，与其一同沉没的还有库尔提拉斯第三舰队的船只。现在，找回这朵花的任务落在了...",kw={"奥伯丁","天界之花","飞鱼号","米奈希尔港","海加尔山","鱼人","诺德尔","赛蕾莎·暮语","泰达希尔","湿地"},ang={["faction:Alliance"]="遗失的飞鱼号在米奈希尔港海岸外遭遇灾难前，曾与库尔提拉斯第三舰队一同航行。",["profession:Herbalism"]="诺德尔是一种极其罕见的暗夜精灵花卉，必须在海加尔山顶的满月下培育，使其成为一种非凡的植物学奇观。",["race:NightElf"]="诺德尔代表了一种珍贵的来自海加尔山的植物圣物，是在暗夜精灵将家园迁往泰达希尔枝叶之前采集的。"},sec={{t="海加尔山的圣物",b="赛蕾莎·暮语从卡利姆多海岸的奥伯丁远道而来，前往米奈希尔港，试图打捞一件具有深厚文化意义的宝物。她寻找的货物是诺德尔，通用语称其为“天之绽”，这是一种神圣的花朵，在满月时采集于海加尔山之巅。对于如今居住在泰达希尔的流离失所的暗夜精灵来说，这些来自故土山脉的圣物是他们文化传承中无可替代的珍宝。"},{t="飞鱼号的命运",b="这朵花在许多个月前就已经遗失了。当时，暗夜精灵的“飞鱼号”船只在与库尔提拉斯第三舰队同行时，在米奈希尔港以南的岩石海岸遭遇海难。如今，这艘破损的船体残骸静静地躺在浅滩中，作为这场灾难的沉重纪念碑。更糟糕的是，凶猛的鱼人掠夺者占据了沉船残骸，它们极力守卫着这艘破船，并威胁着任何试图收回卡多雷货物的人。"}},faq={{q="什么是诺德尔？",a="诺德尔在达纳苏斯语中的意思是“天之绽”。它是对暗夜精灵具有重要意义的神圣花卉，在满月时从暗夜精灵的祖居地——海加尔山之巅采摘。",al={"什么是诺德尔","诺德尔花卉","什么是天之绽"}},{q="飞鱼号是什么？",a="飞鱼号是一艘与库尔提拉斯第三舰队同行的暗夜精灵船只。许多个月前，这艘船在湿地的米奈希尔港以南海岸遭遇海难，其珍贵的货物也随之散落。",al={"飞鱼号船只","哪艘船沉没了","库尔提拉斯第三舰队湿地"}},{q="赛蕾莎·暮语是谁？",a="赛蕾莎·暮语是一位暗夜精灵使者，她跨越海洋，从奥伯丁和泰达希尔的枝叶间来到米奈希尔港，专门为了替族人寻回这朵遗失的花朵。",al={"谁是赛蕾莎·暮语","米奈希尔港的任务发布者","米奈希尔的暗夜精灵"}},{q="沉船为什么危险？",a="凶猛的鱼人掠夺者已经侵占了米奈希尔港以南的海岸残骸，占领了飞鱼号的残骸，这使得赛蕾莎的打捞工作变得极其危险。",al={"为什么鱼人在残骸处","谁守卫着残骸","米奈希尔以南的残骸"}},{q="为什么诺德尔对暗夜精灵如此重要？",a="这朵花是在泰达希尔建立之前，于卡多雷曾经的家园——海加尔山之巅采摘的。由于其来源的特殊性和在满月下采摘的神圣仪式，它对暗夜精灵而言具有巨大的文化和情感价值。",al={"为什么这朵花很重要","赛蕾莎为什么想要诺德尔"}},{q="在哪里可以找到残骸？",a="飞鱼号的残骸位于湿地的米奈希尔港以南的海岸上，坐落在如今被敌对鱼人占领的岩石之中。",al={"残骸在哪里","花在哪里","湿地沉船地点"}}},fp="20,285,22.299.0,29.295.0,16.175.0,27.182.0,27.145.0,31.155.0,47.190.0,32.122.0"}
P.entries["quest:98209"] = {n="Bloom of the Heavens",s="“天界之花”是一次跨海旅程，旨在运送一种名为“诺德尔”的暗夜精灵奇迹植物遗物。人们认为它已经失传数代，但这一幸存的植株成为了艾露恩的恩典以及卡多雷在失去永生后依然坚韧不拔的强大象征。",h="“天界之花”是一次跨海旅程，旨在运送一种名为“诺德尔”的暗夜精灵奇迹植物遗物。人们认为它已经失传数代，但这一幸存的植株成为了艾露恩的恩典以及卡多雷在失去永生后依然坚韧不拔的强大象征。",kw={"奥伯丁","天界之花","黑海岸","达纳苏斯","艾露恩","米奈希尔港","诺德尔","塞莱萨","桑德里斯风歌","湿地"},ang={["faction:Alliance"]="这一任务连接了东部王国繁忙的联盟港口——米奈希尔港，以及横跨无尽之海后的卡利姆多北部的奥伯丁与达纳苏斯。",["profession:Herbalism"]="草药师和植物学家们一定会对诺德尔的失而复得感到欣喜，这是一种被认为失传已久、需要在达纳苏斯进行培育的神圣植物。",["race:NightElf"]="诺德尔是卡利姆多神圣遗产的珍贵遗存，也是艾露恩在卡多雷适应失去永生的过程中依然眷顾着他们的美好征兆。"},sec={{t="危险的回收",b="在湿地的沼泽中，塞莱萨成功回收了传说中的花朵——诺德尔，并抵御了当地凶猛鱼人的攻击。由于在惊险的逃脱后精疲力竭，她将这株寻回的植物托付给一位冒险者，让他将其带过无尽之海送往奥伯丁。从米奈希尔港出发的船只可以直达黑海岸，连接起东部王国与卡利姆多北部。"},{t="艾露恩恩典的征兆",b="当奥伯丁的桑德里斯·风歌长老收到诺德尔时，他感到无比震惊，因为他一直以为这株神圣的花朵早已永远消失了。对于在海加尔山之战后不得不接受失去永生这一代价的暗夜精灵来说，诺德尔的奇迹般幸存如同艾露恩降下的福泽，闪耀着光芒。桑德里斯准备将这株娇贵的植物送往达纳苏斯，以确保它能被妥善培育并传承给后代。"}},faq={{q="什么是诺德尔？",a="诺德尔是暗夜精灵认为早已失传的一种神圣植物。它在多年后被重新发现并幸存下来，使其成为艾露恩神圣眷顾的珍贵象征，也是大自然顽强生命力的见证。",al={"什么是诺德尔","诺德尔之花","神圣之花"}},{q="谁发布了“天界之花”这个任务？",a="该任务由位于湿地的塞莱萨发布。尽管遭到敌对鱼人的伏击和追击，她还是成功找回了这株神圣的花朵，但这次磨难使她精疲力竭，无法亲自完成余下的旅程。",al={"谁发布天界之花任务","湿地诺德尔任务发布者","湿地塞莱萨"}},{q="诺德尔需要被送往哪里？",a="诺德尔必须被送过大海，交给位于黑海岸沿岸的奥伯丁的桑德里斯·风歌长老。从米奈希尔港出发，旅客可以乘船直达奥伯丁。",al={"我该把诺德尔带到哪里","桑德里斯风歌位置","奥伯丁交付"}},{q="为什么诺德尔对暗夜精灵如此重要？",a="桑德里斯·风歌长老认为这株花朵的幸存是黑暗时期中极其罕见的希望灯塔。它神圣地提醒着人们艾露恩的恩典，以及卡多雷在第三次战争中牺牲了永生后依然坚韧不拔的精神。",al={"为什么诺德尔对暗夜精灵很重要","诺德尔背景故事","暗夜精灵永生诺德尔"}},{q="这朵花到达奥伯丁后会发生什么？",a="在奥伯丁收到这株花后，桑德里斯·风歌会安排将其安全地运往内陆的达纳苏斯，由那里的暗夜精灵植物学家和祭司进行精心的培育。",al={"诺德尔后续","诺德尔达纳苏斯","桑德里斯把诺德尔送到哪"}},{q="如何从米奈希尔港前往奥伯丁？",a="旅客可以搭乘停靠在湿地米奈希尔港的客船，该船会横跨无尽之海，直接抵达黑海岸的奥伯丁码头。",al={"如何从湿地前往奥伯丁","米奈希尔港前往奥伯丁的船","前往黑海岸的船"}}},fp="20,189,20.315.0,23.403.0,16.153.0,41.199.0,40.155.0,49.201.0,56.170.0,52.98.0"}
P.entries["quest:98219"] = {n="The Shamed Lieutenant",s="一名暴风城卫兵请你去南海镇探望法尔林·奥里涅尔中尉。他被调职是为了让他吸取教训，但卫兵仍希望他能有所作为。",h="一名暴风城卫兵请你去南海镇探望法尔林·奥里涅尔中尉。他被调职是为了让他吸取教训，但卫兵仍希望他能有所作为。",kw={"法尔林·奥里涅尔","希尔斯布莱德丘陵","法尔林中尉","米奈希尔港","南海镇","暴风城卫兵","蒙羞的中尉"},ang={["faction:Alliance"]="作为一名联盟旅人，你受托去探望一名在南海镇服役的暴风城城卫。"},sec={{t="前去探望",b="你已安全送达小雕像。如今，你的联系人请你去见法尔林·奥里涅尔中尉。这名城卫被调往希尔斯布莱德丘陵的南海镇。中尉的父亲曾是这名卫兵的朋友，他认为有人帮一把或许能让中尉受益。若你途经米奈希尔港，那里有船前往南海镇。"}},faq={{q="要我去见谁？",a="你要去见法尔林·奥里涅尔中尉，他是一名被调往南海镇的城卫。",al={"法尔林是谁","法尔林中尉","法尔林·奥里涅尔"}},{q="法尔林中尉在哪里？",a="法尔林·奥里涅尔中尉在希尔斯布莱德丘陵的南海镇。",al={"法尔林在哪里","法尔林的位置","南海镇中尉"}},{q="法尔林为何被调职？",a="卫兵说法尔林需要吸取教训，但没有进一步说明他被调职的原因。",al={"为何被调职","法尔林受罚","他为何在南海镇"}},{q="卫兵怎么认识法尔林？",a="法尔林的父亲曾是那名请你去探望他的卫兵的朋友。",al={"法尔林的父亲","他父亲是谁","卫兵与他的关系"}},{q="怎么去南海镇？",a="你可以乘坐从米奈希尔港出发的船前往南海镇。",al={"去南海镇的船","米奈希尔路线","怎么去那里"}},{q="以前有人探望过法尔林吗？",a="法尔林说，上个月有另一名暴风城卫兵来探望过他。",al={"上个月","其他访客","谁去探望法尔林"}}},fp="21,171,10.331.0,35.94.0,27.68.0,26.93.0,31.71.0,28.55.0,36.76.0"}
P.entries["quest:98221"] = {n="From the Ashes",s="斯托菲队长请你调查米奈希尔附近再度活跃的龙喉氏族。袭击计划或许能揭示他们打算攻击何处。",h="斯托菲队长请你调查米奈希尔附近再度活跃的龙喉氏族。袭击计划或许能揭示他们打算攻击何处。",kw={"怒牙营地","袭击计划","斯托菲队长","龙喉氏族","丹奥加兹","灰烬重生","铁炉堡","纳克罗什","红龙"},ang={["faction:Alliance"]="作为一名联盟旅人，你帮助斯托菲队长查明龙喉氏族打算袭击何处。",["race:Dwarf"]="作为一名矮人，你帮助斯托菲队长查明龙喉氏族打算袭击何处，而他的担忧也牵涉到铁炉堡。"},sec={{t="湿地的计划",b="米奈希尔城堡的斯托菲队长想知道龙喉氏族会在哪里发动袭击。第二次战争期间，他们在此地建造了一支舰队，准备进攻希尔斯布莱德，但红龙击溃了他们，将幸存者赶进群山。如今，米奈希尔东北方的怒牙营地活动骤增。你要找到并摧毁氏族的袭击计划。"},{t="新的谋算",b="计划指向丹奥加兹，也预示着他们再度企图挑起战争。纳克罗什继承了父亲的野心，却没有奴役的红色龙兽，无法像第二次战争期间那样让龙喉氏族变得危险。斯托菲队长看出了这次谋算对铁炉堡的威胁，并认定纳克罗什将为此付出惨痛代价。"}},faq={{q="是谁让我寻找袭击计划？",a="米奈希尔城堡的斯托菲队长让你找到并摧毁龙喉氏族的袭击计划。",al={"谁派我来的","斯托菲的计划","队长的请求"}},{q="龙喉氏族在哪里活动？",a="龙喉氏族在米奈希尔东北方的怒牙营地活动日益频繁。",al={"龙喉氏族营地","他们在哪里","怒牙营地的动向"}},{q="斯托菲为什么想要计划？",a="斯托菲想知道龙喉氏族下一步会袭击哪里。",al={"为何要计划","他需要什么","袭击何处"}},{q="第二次战争期间，龙喉氏族遭遇了什么？",a="龙喉氏族曾在此地建造舰队，准备进攻希尔斯布莱德，但红龙击溃了他们，幸存者逃入深山。",al={"龙喉氏族的历史","战争中的红龙","之前发生了什么"}}},fp="14,143,21.356.0,12.293.1,37.91.0,31.85.0,34.62.0,49.123.0"}
P.entries["quest:98223"] = {n="Old Habits",s="一本烧焦的龙喉氏族书册送到了米奈希尔港的斯托菲队长手中。残存的书页提到了束缚巨龙的仪式和Shadow Council。",h="一本烧焦的龙喉氏族书册送到了米奈希尔港的斯托菲队长手中。残存的书页提到了束缚巨龙的仪式和Shadow Council。",kw={"斯托菲队长","恶魔之魂","龙喉氏族","米奈希尔港","纳克罗什","旧习难改","shadow council","破烂的法术书"},sec={{t="一本残破的书册",b="你把一本严重烧焦的书册交给了米奈希尔港的斯托菲队长。这本书或许是在焚毁龙喉氏族的龙焰中幸存下来的。仅存的几页尚可辨认，上面记载着与恶魔之魂有关的仪式，龙喉氏族曾用它控制巨龙。书册并不完整，不过纳克罗什似乎曾试图挽救它，添入了兽皮书页，并用新墨水写下了Shadow Council。"},{t="斯托菲队长的答复",b="斯托菲队长说，这本书应该销毁，因为他不愿冒险让兽人利用它。他担心米奈希尔港会出现龙骑士，而Shadow Council的名字也让他忧心。他打算把消息报告给上级。"}},faq={{q="破烂的法术书里写了什么？",a="残存的书页记载着与恶魔之魂有关的仪式，龙喉氏族曾用它控制巨龙。新写的墨迹还提到了Shadow Council。",al={"法术书内容","是什么书","烧焦的书"}},{q="是谁试图挽救这本书？",a="纳克罗什似乎曾把兽皮制成的书页插进书中，试图挽救它。",al={"谁挽救了它","纳克罗什的书","纳克罗什"}},{q="谁想让你把书带给他们？",a="米奈希尔港的斯托菲队长想听听这本书的情况。",al={"把法术书带到哪里","斯托菲的书","队长想要什么"}},{q="为什么这本书很难读？",a="这本书严重烧毁，大部分内容都已无法辨认。",al={"书为什么烧焦","书册损坏","法术书无法辨认"}}},fp="10,142,14.382.0,20.226.1,34.153.0,27.90.0,35.66.0,29.59.0"}
P.entries["quest:98230"] = {n="This Land Was Their Land",s="霍文·鹰羽已返回湿地，这里曾是蛮锤矮人建立格瑞姆巴托的地方。去米奈希尔港以东找他，他很乐意接受援助。",h="霍文·鹰羽已返回湿地，这里曾是蛮锤矮人建立格瑞姆巴托的地方。去米奈希尔港以东找他，他很乐意接受援助。",kw={"格瑞姆巴托","狮鹫","霍文·鹰羽","米奈希尔港","这片土地曾属于他们","三锤之战","湿地","蛮锤"},ang={["race:Dwarf"]="作为一名矮人，你会遇见霍文·鹰羽，这位蛮锤矮人在三锤之战后返回了湿地。"},sec={{t="东行之路",b="蛮锤矮人霍文·鹰羽正在米奈希尔港以东的路旁等待援助。你前去寻找他，他是多年来最早返回的蛮锤矮人之一。他远离城镇，能得到的帮助也不多。"},{t="蛮锤人的家园",b="三锤之战后，蛮锤矮人定居湿地，并建立了格瑞姆巴托。狮鹫曾在山间要塞上空飞翔，俯冲入湿地捕鱼。那样的生活并未持续太久；如今霍文已返回此地，远离城镇。"}},faq={{q="霍文·鹰羽是谁？",a="霍文·鹰羽是一名蛮锤矮人，也是多年来最早返回故土的族人之一。",al={"霍文","霍文是谁","鹰羽"}},{q="我在哪里能找到霍文？",a="霍文在米奈希尔港以东的路旁，远在城镇之外。",al={"霍文在哪里","寻找鹰羽","霍文的位置"}},{q="霍文为什么待在这里？",a="霍文是多年来最早返回的蛮锤矮人之一，他独自待在城镇之外。",al={"霍文为何在此","霍文归来","蛮锤人归来"}},{q="格瑞姆巴托曾是什么地方？",a="三锤之战后，蛮锤矮人在湿地建立了格瑞姆巴托。",al={"格瑞姆巴托历史","蛮锤要塞","格瑞姆巴托是什么"}},{q="蛮锤人的家园后来怎么样了？",a="格瑞姆巴托曾是个奇妙的地方，狮鹫飞越湿地捕鱼，但那样的生活并未持续太久。",al={"蛮锤人的家园","格瑞姆巴托后来怎样了","湿地的狮鹫"}}},fp="24,156,13.222.0,17.252.0,25.93.0,23.67.0,22.94.0,20.86.0,39.123.0"}
P.entries["quest:98245"] = {n="Razormaw Needling",s="“刃喉之针”是湿地的一项任务，在该任务中，霍文·鹰羽委托旅行者从当地的刃喉迅猛龙身上收集门齿。Howin打算用它们锋利的牙齿制作耐用的锥子，以便刺穿并缝合幼龙鳞片，从而制成抗火护甲。",h="“刃喉之针”是湿地的一项任务，在该任务中，霍文·鹰羽委托旅行者从当地的刃喉迅猛龙身上收集门齿。Howin打算用它们锋利的牙齿制作耐用的锥子，以便刺穿并缝合幼龙鳞片，从而制成抗火护甲。",kw={"黑铁","龙喉","霍文·鹰羽","恐龙岭","迅猛龙","刃喉门齿","锯齿龙的侵扰","盐沫沼泽","湿地","幼龙鳞片"},ang={["faction:Alliance"]="确保防龙火装备的供给，有助于联盟对抗占据东部沼泽的龙类和龙喉部队的持续斗争。",["race:Dwarf"]="霍文·鹰羽与蛮锤矮人和铁炉堡矮人一样，对肆虐湿地和格瑞姆巴托的黑铁氏族和龙喉兽人怀有深切的仇恨。"},sec={{t="复仇工具",b="在湿地那潮湿的土地上，霍文·鹰羽对那些长期祸害该地区的敌人怀有深刻的仇恨：狡诈的黑铁矮人、残暴的龙喉兽人，以及他们带入战场、口吐烈焰的幼龙。为了反击并防备龙火，Howin致力于用幼龙鳞片制作防护护甲。然而，这些坚韧的兽皮在没有特殊制作工具的情况下，极难缝合在一起。"},{t="獠牙化作针",b="为了刺穿坚韧的幼龙皮，Howin需要比普通钢针更锋利、更坚固的工具，因为普通钢针在龙鳞上很容易弯曲或变钝。他将目光投向了潜伏在东北部恐龙岭和西北部盐沫沼泽的本地刃喉迅猛龙。刃喉迅猛龙因其致命且如针尖般锋利的牙齿而得名，完整的刃喉迅猛龙门齿是完美的锥子，可以刺穿坚硬的鳞片而不会在压力下破碎。"}},faq={{q="谁发布了任务“刃喉之针”？",a="霍文·鹰羽在湿地发布了这个任务。他深切痛恨黑铁矮人、龙喉氏族以及他们骑乘的幼龙，并试图用幼龙鳞片制作抗龙火护甲。",al={"谁发布了刃喉之针任务","霍文·鹰羽是谁","刃喉之针任务发布者"}},{q="为什么霍文·鹰羽需要刃喉迅猛龙的门齿？",a="霍温正在使用坚韧的幼龙鳞片制作防护护甲，但这种皮太厚，难以缝合。他需要刃喉迅猛龙锋利而坚固的门齿来制作一套足以刺穿鳞片而不会折断的锥子。",al={"为什么霍文需要迅猛龙牙齿","刃喉迅猛龙门齿的用途","这些牙齿是用来做什么的"}},{q="刃喉迅猛龙在哪里？",a="刃喉迅猛龙在湿地有两处主要的狩猎场：位于东北部高地的恐龙岭，以及位于西北部靠近海岸的盐沫沼泽。",al={"在哪里可以找到刃喉迅猛龙","湿地刃喉迅猛龙位置","迅猛龙在哪里"}},{q="霍文·鹰羽用幼龙鳞片制作什么？",a="霍温正在将幼龙鳞片缝合成防护装备。这些鳞片能提供卓越的防御力来抵御烈焰吐息，从而在对抗龙类和龙喉氏族的幼龙时提供至关重要的保护。",al={"霍文在制作什么护甲","湿地幼龙鳞片护甲","为什么要用幼龙鳞片"}},{q="为什么霍温憎恨黑铁矮人和龙喉氏族？",a="湿地和周围的山脉留下了黑铁氏族和龙喉兽人的深深创伤，这些兽人在第二次战争期间奴役了红龙。霍温痛恨这两个派系以及他们的飞行坐骑，并决心要一雪前耻。",al={"为什么憎恨黑铁和龙喉","霍文的敌人","为什么霍文憎恨龙喉氏族"}},{q="霍温把迅猛龙门齿变成了什么？",a="锥子是一种细长的尖头手工工具，用于在缝纫前在坚硬的兽皮和皮革上钻孔。通过将完整的迅猛龙门齿安装在手柄上，或者利用它们天然的锥度，霍温制作出了耐用的锥子，能够刺穿龙鳞而不会折断。",al={"什么是锥子","刃喉锥子","迅猛龙牙齿如何用作工具"}}},fp="17,157,20.291.0,16.280.0,38.212.0,50.198.0,39.116.0,55.165.0,49.209.0,46.173.0"}
P.entries["quest:98246"] = {n="Trying Times",s="“Trying Times”是湿地的一项联盟任务，冒险者需要协助矮人霍文·羽言。为了让他那脾气暴躁的狮鹫“低音喙”为接下来的任务做好准备，霍文需要收集十二枚从凶猛的剃刀鳄（锯齿龙）迅猛龙那里获得的新鲜蛋。",h="“Trying Times”是湿地的一项联盟任务，冒险者需要协助矮人霍文·羽言。为了让他那脾气暴躁的狮鹫“低音喙”为接下来的任务做好准备，霍文需要收集十二枚从凶猛的剃刀鳄（锯齿龙）迅猛龙那里获得的新鲜蛋。",kw={"低音喙","狮鹫","霍文·羽言","恐龙岭","剃刀鳄蛋","盐沫沼泽","艰难时刻","湿地"},ang={["faction:Alliance"]="保持狮鹫的健康对于卡兹莫丹各地的联盟旅行和通讯至关重要，特别是在当地威胁危及区域安全的时候。",["race:Dwarf"]="矮人狮鹫骑士深知，一只脾气暴躁的狮鹫和任何敌人一样危险，因此在起飞前进行适当的喂养和照料是绝对必要的。",["race:Gnome"]="霍文幽默地指出，剃刀鳄迅猛龙蛋的蛋黄有侏儒脑袋那么大，这提供了一个生动但略显不敬的矮人度量衡。"},sec={{t="安抚饥饿的狮鹫",b="在湿地那阴暗辽阔的区域里，维持一匹能用的坐骑需要时刻保持警惕。与他的狮鹫“低音喙”一同工作的矮人霍文·羽言，在没能满足他伙伴那反复无常的胃口之前，绝不肯启程飞行。饥饿的狮鹫顽固、不可预测，而且容易暴起伤人，因此在沼泽地进行任何空中行动前，提供一顿正餐是首要条件。"},{t="剃刀鳄的赏金",b="在湿地，寻找可靠且未受污染的食物变得越来越困难。为了满足“低音喙”，霍文将目标对准了位于东北方向恐龙岭和西北方向盐沫沼泽中的本地剃刀鳄迅猛龙的巢穴。迅猛龙蛋以拥有如侏儒脑袋般大小的蛋黄而闻名，能为“低音喙”在面对该地区危险之前提供所需的充足且未受污染的食物。"}},faq={{q="霍文·羽言是谁？",a="霍文·羽言是一位在湿地照料一只名叫“低音喙”的狮鹫的矮人驯兽师。他派遣冒险者去收集新鲜的迅猛龙蛋来喂养他的伙伴，然后才会实施他的计划。",al={"霍文·羽言是谁","霍文·羽言 湿地","任务发布者 艰难时刻"}},{q="“低音喙”是谁？",a="“低音喙”是霍文·羽言的狮鹫。据霍文所说，它在饥饿时会变得焦躁不安，甚至极度危险，如果不让它吃饱，骑乘或使用它都是不安全的。",al={"谁是低音喙","狮鹫低音喙","霍文的狮鹫"}},{q="霍文为什么需要迅猛龙蛋？",a="霍文专门寻找剃刀鳄迅猛龙蛋，是因为在湿地很难找到未受污染的食物，而这些蛋能提供巨大的、营养丰富的蛋黄，足以满足“低音喙”那惊人的胃口。",al={"为什么要迅猛龙蛋","为什么要喂狮鹫吃蛋","这些蛋是做什么用的"}},{q="在哪里可以找到剃刀鳄迅猛龙？",a="剃刀鳄迅猛龙栖息在湿地东北部的恐龙岭和西北部的盐沫沼泽。冒险者必须亲自深入这些巢穴以获取完好的蛋。",al={"剃刀鳄迅猛龙在哪里","去哪找剃刀鳄蛋","湿地迅猛龙位置"}},{q="为什么这些蛋必须完美无缺？",a="霍文坚持要求蛋不能有任何裂缝或瑕疵，以确保食物完全新鲜且未受污染，这样才能让“低音喙”保持健康和满足，而不是喂给它变质的残渣。",al={"为什么蛋必须完美","破碎的蛋 艰难时刻"}},{q="霍文打算带“低音喙”做什么？",a="霍文提到他有一个涉及“低音喙”的更宏大的计划，但他坚持在狮鹫吃饱并冷静下来，足以在区域威胁中安全飞行之前，不对外透露细节。",al={"霍文的计划是什么","霍文和低音喙打算做什么"}}},fp="12,140,26.252.0,19.298.0,25.150.0,16.139.0,32.153.0,36.146.0,35.109.0,43.133.0"}
P.entries["quest:98247"] = {n="Shipping Label",s="Shipping Label是一个贴在艾泽拉斯贸易局所属补给箱上的已寻回货运标记。它指示信使前往位于赤脊山三角路口的贸易枢纽，并向旅行者介绍了该组织旗下的独立运输商网络。",h="Shipping Label是一个贴在艾泽拉斯贸易局所属补给箱上的已寻回货运标记。它指示信使前往位于赤脊山三角路口的贸易枢纽，并向旅行者介绍了该组织旗下的独立运输商网络。",kw={"艾泽拉斯贸易局","补给箱","货物配送","商人恩惠","赤脊山","货运标签","三角路口"},ang={["faction:Alliance"]="艾泽拉斯贸易局通过三角路口开展业务，依靠南方的联盟领地里的流动冒险者来回收流失货物并保障陆路运输路线的安全。"},sec={{t="流失的货物",b="这张破损的Shipping Label被发现贴在装满货物的补给箱上，标记着属于艾泽拉斯贸易局的货物。尽管预定的目的地和收件人信息已被撕毁，但上面清楚地指示发现货物的人将其送回或向该局位于赤脊山的贸易前哨报告。在正式文本旁边，有一张简陋的地图，勾勒出了通往三角路口交叉点的道路。"},{t="贸易局的枢纽",b="在三角路口的交叉点，艾泽拉斯贸易局的代表会积极招募旅行者成为独立信使。贸易局并不要求运输商签订严格的商业合同，而是运营着一个非正式网络，冒险者可以通过找回丢失的货物并完成沿途遗弃的配送任务来获得“商人恩惠”作为报酬。"}},faq={{q="什么是货运标签？",a="货运标签是一份在已寻回补给箱侧面发现的破损单据。虽然收件人的名字不见了，但标签上明确了这些货物属于艾泽拉斯贸易局，并指示发现它的人向他们位于三角路口的枢纽报告。",al={"什么是货运标签","货运标签任务","破损的货运标签"}},{q="什么是艾泽拉斯贸易局？",a="艾泽拉斯贸易局是一个负责组织该地区物流、贸易和货运的企业。他们维护着当地的贸易枢纽，用于回收丢失的货物，并雇佣无需长期合同的流动信使。",al={"谁是艾泽拉斯贸易局","艾泽拉斯贸易局","什么是艾泽拉斯贸易局"}},{q="艾泽拉斯贸易局的贸易枢纽位于哪里？",a="艾泽拉斯贸易局的贸易枢纽位于赤脊山的三角路口，战略性地坐落在连接艾尔文森林、暮色森林和湖畔镇的道路上。",al={"艾泽拉斯贸易局贸易枢纽在哪里","三角路口枢纽","在哪里提交货运标签"}},{q="什么是商人恩惠？",a="商人恩惠是一种由艾泽拉斯贸易局发给独立信使的专用代币或信用额。分支机构成员可以用它购买贸易局前哨提供的各种贸易商品和物流服务。",al={"什么是商人恩惠","商人恩惠","艾泽拉斯贸易局报酬"}},{q="如何成为艾泽拉斯贸易局的关联成员？",a="成为关联成员不需要正式合同、文书工作或长期承诺。艾泽拉斯贸易局仅要求信使协助归还或完成在世界各地发现的遗失货物。",al={"如何成为艾泽拉斯贸易局关联成员","加入艾泽拉斯贸易局","我需要合同吗"}},{q="交付标签后补给箱会怎样？",a="标签本身会促使贸易枢纽的代表询问其所附着的实体补给箱的情况，因为归还空置或已完成运输的货运容器对他们的贸易运作至关重要。",al={"补给箱会怎样","丢失的补给箱","他们需要补给箱吗"}}},fp="14,206,16.350.0,28.327.0,27.216.0,39.192.0,58.165.0,25.189.0,65.208.0,53.185.0"}
P.entries["quest:98248"] = {n="Shipping Label",s="在一个重新补给过的货运箱上发现了一份撕毁的派送单，上面指引信使前往贫瘠之地的一个区域商队枢纽。杜隆塔尔补给后勤部依赖四处游历的旅行者来寻回丢失的板条箱，并将文书送回他们位于十字路口以西的哨所。完成送达任务能够维护卡利姆多中部至关重要的供应链和商业贸易。",h="在一个重新补给过的货运箱上发现了一份撕毁的派送单，上面指引信使前往贫瘠之地的一个区域商队枢纽。杜隆塔尔补给后勤部依赖四处游历的旅行者来寻回丢失的板条箱，并将文书送回他们位于十字路口以西的哨所。完成送达任务能够维护卡利姆多...",kw={"板条箱","十字路口","杜隆塔尔补给后勤部","货运标签","贫瘠之地","贸易哨所"},ang={["faction:Horde"]="穿越贫瘠之地的部落冒险者经常会遇到杜隆塔尔补给后勤部的行动，帮助维护杜隆塔尔与卡利姆多中部之间至关重要的商业和供应线。"},sec={{t="一份迷失的派送单",b="这份撕毁的文件贴在一个刚补给过的货运板条箱上，上面写着杜隆塔尔补给后勤部的物流说明。虽然收件人的名字已经因为旅途磨损而难以辨认，但来源标题清晰地标明了这家在部落领地内运营的货运公司。文字旁边的一张粗略绘制的路线图引导着信使直奔该组织位于中部平原的集结地。"},{t="边境贸易",b="这则告示邀请旅行者将流失的集装箱、损坏的货物或打捞证明运送到他们位于十字路口正西方的贸易哨所。杜隆塔尔补给后勤部在贫瘠之地的严酷环境中运作，非常依赖独立的运输者和路人来寻回散落的货物，并向那些协助保持区域供应渠道顺畅的人提供报酬。"}},faq={{q="什么是货运标签？",a="这是一份贴在已补给好的板条箱上的文件，上面详细列出了杜隆塔尔补给后勤部的退还说明，指引丢失或空置的集装箱送回他们靠近十字路口的哨所。",al={"什么是货运标签","货运标签任务","撕毁的货运标签"}},{q="这个标签应该送到哪里？",a="标签指示信使将其交给驻扎在杜隆塔尔补给后勤部贸易枢纽的人员，该枢纽位于贫瘠之地，十字路口的正西方。",al={"货运标签应该送到哪里","谁需要货运标签","货运标签上交"}},{q="什么是杜隆塔尔补给后勤部？",a="杜隆塔尔补给后勤部是一家在杜隆塔尔和贫瘠之地运营的商业货运组织，负责部落领地内的货物运输、板条箱回收和物流支持。",al={"什么是杜隆塔尔补给后勤部","杜隆塔尔补给哨所"}},{q="这批货物最初的收件人是谁？",a="预期收件人的名字已经从标签上完全撕掉了，板条箱上只留下了退还说明和该公司的来源信息。",al={"板条箱原本是给谁的","板条箱收件人"}},{q="杜隆塔尔补给后勤部的贸易哨所在哪里？",a="根据标签上标注的指示和粗略地图，该哨所位于贫瘠之地十字路口定居点的正西方。",al={"贸易哨所在哪里","杜隆塔尔补给点十字路口位置"}},{q="杜隆塔尔补给后勤部会为归还板条箱的旅行者提供补偿吗？",a="是的，印刷的告示明确承诺，信使在将损坏的货物、标签或空板条箱送回枢纽后，其花费的时间和精力将得到补偿。",al={"他们会为归还的板条箱付费吗","杜隆塔尔补给补偿"}}},fp="14,255,18.294.0,17.312.0,27.184.0,36.111.0,37.170.0,45.123.0,64.93.0,76.116.0"}
P.entries["quest:98251"] = {n="Never Coming Back",s="Va'xug Firefure 被困在灰谷的一处峡谷里，请你清除附近的部分野生动物。森林里令人迷失方向的道路和变化无常的法术让 Va'xug 怒火中烧。",h="Va'xug Firefure 被困在灰谷的一处峡谷里，请你清除附近的部分野生动物。森林里令人迷失方向的道路和变化无常的法术让 Va'xug 怒火中烧。",kw={"灰谷","灰谷的熊","草药","never coming back","峡谷","shadowhorn stag","va'xug firefure","不稳定的法术"},sec={{t="森林的困局",b="Va'xug Firefure 在灰谷采集草药时，被林间的道路困在了一处峡谷里。Va'xug 说，自己的法术在愤怒时会变得不稳定，而附近的野兽只会让怒气更盛。Va'xug 请你清除周围的部分野生动物。"},{t="怒气稍平",b="附近的野生动物减少后，Va'xug Firefure 向你道了谢。Va'xug 说，这似乎起了些作用，但对这片森林的怒气仍然显而易见。"}},faq={{q="Va'xug Firefure 是谁？",a="Va'xug Firefure 在灰谷采集草药时，被困在了一处峡谷里。",al={"va'xug","firefure","va'xug 是谁"}},{q="Va'xug 为什么生气？",a="Va'xug 生气是因为灰谷的道路让自己被困在一处峡谷里，附近的野兽又令人心烦。",al={"为什么生气","va'xug 生气","讨厌灰谷"}},{q="Va'xug 要我做什么？",a="Va'xug 请你清除附近的部分野生动物。",al={"要做什么","减少野生动物","击杀野兽"}},{q="Va'xug 的法术为什么不稳定？",a="Va'xug 说，自己生气时，法术就会变得不稳定，产生不同的效果。",al={"不稳定的法术","魔法异常","法术效果不同"}}},fp="17,180,14.258.0,13.152.1,23.85.0,20.114.0,30.44.0,33.82.0"}
P.entries["quest:98252"] = {n="A Void Path",s="Va'xug请你引导他的Eye of Kilrogg从峡谷抵达灰谷的道路。通道中断前，幻象必须到达道路。",h="Va'xug请你引导他的Eye of Kilrogg从峡谷抵达灰谷的道路。通道中断前，幻象必须到达道路。",kw={"虚空之路","灰谷","通道","eye of kilrogg","峡谷","道路","va'xug","voidwalker"},sec={{t="穿过眼睛",b="Va'xug留在原地辨明方向，由你引导这只漂浮的眼睛。如果你迷路了，他可以通过眼睛为你指路。他只能维持通道四分钟，所以幻象必须在通道中断前抵达灰谷的主路。"},{t="畅通之路",b="眼睛带回了路线的景象。Va'xug说，这个幻象能在他再次召唤不听话的Voidwalker时，帮助他沿着小径引路。随着他的谢意从眼睛中传来，Eye of Kilrogg开始消散。"}},faq={{q="是谁要我引导这只眼睛？",a="Va'xug请你引导他的Eye of Kilrogg从峡谷抵达灰谷的道路。",al={"谁是va'xug","va'xug的眼睛","眼睛任务"}},{q="Eye of Kilrogg有什么用？",a="Va'xug说，再次召唤不听话的Voidwalker时，这只眼睛的幻象能帮助他沿着正确的小径引路。",al={"眼睛的作用","kilrogg之眼","漂浮的眼睛"}},{q="Va'xug为什么留在原地？",a="Va'xug留在原地，这样你们中就有人能辨明方向；如果你迷路了，他还能通过眼睛为你指路。",al={"为何留在后方","va'xug留在原地","辨明方向"}},{q="Va'xug能维持通道多久？",a="Va'xug能维持通道四分钟。",al={"通道持续时间","四分钟","眼睛能维持多久"}},{q="我该把眼睛引到哪里？",a="引导Eye of Kilrogg离开峡谷，回到灰谷的主路。",al={"眼睛要去哪里","灰谷道路","峡谷出口"}}},fp="11,138,15.243.0,12.216.0,34.82.0,31.114.0,28.120.0,37.45.0,29.79.0"}
P.entries["quest:98282"] = {n="Alchemical Hazards",s="米奈希尔港的凯特林·格拉斯曼需要一枚完整的蜘蛛毒囊来制作更多解毒药。沼泽里的毒物让这种材料很难安全采集。",h="米奈希尔港的凯特林·格拉斯曼需要一枚完整的蜘蛛毒囊来制作更多解毒药。沼泽里的毒物让这种材料很难安全采集。",kw={"炼金术的危险","解毒药","凯特林·格拉斯曼","米奈希尔港","蜘蛛","瑟根石","未破损的 stalker 毒囊","毒囊"},sec={{t="完整的毒囊",b="米奈希尔港的凯特林·格拉斯曼正在制作解毒药，但她需要一只瑟根石蜘蛛的毒囊。她让你把毒囊完整带回来，这样毒液在送到她手中前就不会漏光。"}},faq={{q="谁需要毒囊？",a="米奈希尔港的凯特林·格拉斯曼需要它来制作更多解毒药。",al={"谁需要毒囊","凯特林·格拉斯曼"}},{q="毒囊从哪里来？",a="凯特林让你去遥远的东南方瑟根石，从一只蜘蛛身上取来毒囊。",al={"哪里能找到毒囊","蜘蛛毒囊位置"}},{q="为什么毒囊必须保持完整？",a="凯特林需要一枚未破损的毒囊，这样你送去之前毒液才不会漏出来。",al={"为何不能破损","完整的毒囊"}},{q="凯特林在制作什么？",a="凯特林需要这枚毒囊来制作更多解毒药。",al={"解毒药材料","她在调制什么"}}},fp="18,151,13.204.0,20.68.0,31.90.0,38.89.0,23.47.0"}
P.entries["quest:98283"] = {n="Carnage",s="“屠戮者”是湿地的一项任务，由绿带草地的绿色守卫者雷希耶尔委派。雷希耶尔请求旅行者引诱并杀死屠戮者，这是一头疯狂的利刃爪迅猛龙首领，其因瘟疫引发的狂乱扰乱了该地区的自然秩序。",h="“屠戮者”是湿地的一项任务，由绿带草地的绿色守卫者雷希耶尔委派。雷希耶尔请求旅行者引诱并杀死屠戮者，这是一头疯狂的利刃爪迅猛龙首领，其因瘟疫引发的狂乱扰乱了该地区的自然秩序。",kw={"屠戮者","洛克莫丹","恐龙岭","利刃爪","绿色守卫者雷希耶尔","烂爪","绿带草地","湿地"},ang={["class:Druid"]="德鲁伊们对于湿地破碎的自然平衡与雷希耶尔有着同样的悲痛，在那里，疾病已将像屠戮者这样的掠食者扭曲成了毫无理智的恐怖存在。",["class:Hunter"]="猎人们明白，当一个掠食者首领因瘟疫引发的愤怒而丧失其本能，并开始捕食同类时，会构成怎样的危险。"},sec={{t="破碎的平衡",b="在湿地的沼泽中，自然秩序已开始破裂。利刃爪迅猛龙曾经扮演着重要的生态角色，防止荒野过度生长。现在，它们的种群等级被其可怕的首领、那头只被称为“屠戮者”的嗜血野兽所打破。屠戮者非但没有引导种群，反而给自己的同类带来了恐惧，它肆意屠杀，使当地的生态系统陷入混乱。"},{t="引诱首领",b="守护着绿带草地的绿色守卫者雷希耶尔认为，屠戮者已经屈服于依然困扰着该地区的邪恶腐化。为了将这头狂乱的野兽从藏身处引出，旅行者必须收集从洛克莫丹游荡下来的患病烂爪熊的恶性内脏。将这些腐肉放置在恐龙岭下方屠戮者的洞穴巢穴中，会激怒这只怪物发起攻击，从而让旅行者结束它的痛苦。"}},faq={{q="谁是屠戮者？",a="屠戮者是湿地利刃爪迅猛龙群中可怕的首领。这头野兽没有正常地领导它的族群，而是被疾病逼疯，所过之处只留下屠杀，甚至连它的迅猛龙同类都感到恐惧。",al={"谁是屠戮者","屠戮者迅猛龙","什么是屠戮者"}},{q="谁发布了“屠戮者”任务？",a="该任务由绿色守卫者雷希耶尔发布，他是一位驻扎在湿地绿带草地的守卫者，致力于恢复该地区被腐化的自然平衡。",al={"谁发布屠戮者任务","在哪里上交屠戮者任务","雷希耶尔湿地"}},{q="为什么要消灭屠戮者？",a="雷希耶尔寻求屠戮者的死亡，因为这头野兽已被一种非自然的疾病逼疯，破坏了利刃爪迅猛龙的自然等级制度，并摧毁了当地的生态。",al={"为什么要杀死屠戮者","为什么雷希耶尔想让屠戮者死"}},{q="如何引诱出屠戮者？",a="屠戮者是通过用在东北方恐龙岭下方发现的患病熊的恶性肉块和内脏作为诱饵，在其洞穴巢穴中引出的。",al={"如何召唤屠戮者","如何引诱屠戮者","屠戮者的洞穴在哪里"}},{q="雷希耶尔提到的患病熊是什么？",a="这些患病的熊是从洛克莫丹迁移下来的烂爪熊。在挥之不去的腐化影响下变得疯狂，它们被污染的肉体成为了引诱那只疯狂迅猛龙首领的有力诱饵。",al={"什么是烂爪熊","患病的熊来自哪里"}},{q="利刃爪迅猛龙最初在湿地扮演什么角色？",a="在正常情况下，利刃爪迅猛龙通过防止自然动植物过度生长来维持湿地的生态平衡。屠戮者的疯狂破坏了这一至关重要的角色。",al={"利刃爪扮演什么角色","为什么迅猛龙对湿地很重要"}}},fp="7,161,16.216.0,16.305.0,15.159.0,28.147.0,30.161.0,25.128.0,49.162.0,68.187.0"}
P.entries["quest:98284"] = {n="Camping 101: Enchanting",s="申达尔村的Nasalanna Windsinger可以教你制作适合你的专业的露营物品。附魔师可以学习制作附魔的鲁特琴，为旅途增添乐趣。",h="申达尔村的Nasalanna Windsinger可以教你制作适合你的专业的露营物品。附魔师可以学习制作附魔的鲁特琴，为旅途增添乐趣。",kw={"露营入门","露营物品","附魔的鲁特琴","附魔师","附魔","nasalanna windsinger","申达尔村"},ang={["profession:Tailoring"]="作为附魔师，你可以学习制作附魔的鲁特琴，为营地生活增添乐趣。"},sec={{t="营地里的鲁特琴",b="附魔师能让野外营地变得更舒适，而你被指引前往申达尔村，寻找Nasalanna Windsinger。证明你已熟练掌握自己的技能后，Nasalanna就可以教你制作附魔的鲁特琴。这件附魔乐器能让你在重新踏上旅途前，享受休息时的乐趣。"}},faq={{q="谁能教我制作附魔的鲁特琴？",a="证明你已熟练掌握自己的技能后，申达尔村的Nasalanna Windsinger就可以教你制作附魔的鲁特琴。",al={"附魔的鲁特琴训练师","谁教制作鲁特琴","nasalanna露营"}},{q="附魔的鲁特琴有什么用途？",a="附魔的鲁特琴能在营地休息时提供消遣。",al={"鲁特琴用途","露营鲁特琴","为什么制作附魔的鲁特琴"}},{q="为什么附魔师在营地里受到欢迎？",a="附魔师能让野外营地变得更舒适，包括制作附魔的鲁特琴来提供消遣。",al={"附魔师露营","附魔师为何受欢迎","露营附魔"}},{q="什么时候可以学习制作露营物品？",a="证明你已熟练掌握自己的技能后，就可以向Nasalanna Windsinger学习。",al={"何时学习制作鲁特琴","技能熟练程度","露营制作要求"}}},fp="23,178,15.304.0,41.128.0,31.68.0,36.103.0,35.87.0"}
P.entries["quest:98285"] = {n="Camping 101: Engineering",s="向影风森林的The Strange Hermit展示你的工程学技艺后，他会教你制作一件露营物品。试剂机器人供野外营地使用。",h="向影风森林的The Strange Hermit展示你的工程学技艺后，他会教你制作一件露营物品。试剂机器人供野外营地使用。",kw={"营火","camping 101","烹饪","工程学","试剂机器人","影风森林","strange hermit","野外营地"},ang={["profession:Cooking"]="身为厨师，你可以教别人生起搭建营地所需的营火。",["profession:Engineering"]="身为工程师，向The Strange Hermit展示你熟练的技艺后，你就能学会为野外营地制作试剂机器人。"},sec={{t="野外营地",b="影风森林的The Strange Hermit要求你先展示工程学方面的熟练技艺，才会传授你一门露营手艺。独自在野外时，工程师也能发挥自己的专长，用实用的构造体完善营地。"},{t="搭建营地",b="The Strange Hermit会教你制作试剂机器人。要搭建营地，你还需要一堆营火，大多数厨师都能教你生火。隐士提醒你，镇民不喜欢有人在镇子中央扎营。"}},faq={{q="谁会教我露营手艺？",a="向影风森林的The Strange Hermit展示你熟练的工程学技艺后，他就会传授你露营手艺。",al={"隐士是谁","露营导师","哪里学习工程学露营"}},{q="工程学和露营有什么关系？",a="隐士说，工程师可以在野外发挥专长，为营地制作实用的构造体。",al={"工程学营地物品","工程师为何露营","camping 101 工程学"}},{q="我能制作什么？",a="隐士会教你制作试剂机器人。",al={"露营物品是什么","试剂机器人","营地物品 工程学"}},{q="搭建营地还需要别的东西吗？",a="你需要一堆营火才能搭建营地。大多数厨师都能教你生火。",al={"需要营火","如何搭建营地","露营营火"}},{q="我该在哪里扎营？",a="隐士说，镇民不喜欢有人在镇子中央扎营，所以要到野外试着搭建营地。",al={"营地位置","哪里试用试剂机器人","能否在镇上扎营"}}},fp="24,167,17.234.0,15.221.1,33.112.0,46.99.0,17.46.0,35.77.0,27.124.0"}
P.entries["quest:98286"] = {n="Camping 101: Enchanting",s="《露营指南：附魔》指引奥术修行者前往申达尔村，学习如何制造专业的野外装备。通过与纳萨兰娜·风歌交谈，经验丰富的附魔师可以学会制作一把附魔的鲁特琴，在营火旁娱乐同伴并振奋他们的士气。",h="《露营指南：附魔》指引奥术修行者前往申达尔村，学习如何制造专业的野外装备。通过与纳萨兰娜·风歌交谈，经验丰富的附魔师可以学会制作一把附魔的鲁特琴，在营火旁娱乐同伴并振奋他们的士气。",kw={"营火","露营","露营指南","附魔的鲁特琴","附魔","鲁特琴","纳萨兰娜·风歌","申达尔村"},sec={{t="炉火的慰藉",b="旅途生活需要的不仅仅是锋利的刀刃和口粮；休息和士气对于维持长期的远征至关重要。附魔师为营地生活带来了独特的魔法慰藉，利用他们对周围奥术的精通，在休息时间为旅行者提供精神支持。在艾泽拉斯各地的荒野营地中，附魔师的存在确保了疲惫的冒险者在重返险峻的道路之前，能够恢复体力和精神。"},{t="申达尔之歌",b="想要学习营地制造的精妙魔法，立志成为附魔师的人会被指引前往申达尔村。在那里，纳萨兰娜·风歌会指导合格的施法者制作附魔的鲁特琴。工匠必须首先证明自己在附魔方面的专注和熟练程度，纳萨兰娜才会分享如何制造一种能在星空下编织治愈旋律的乐器的秘密。"}},faq={{q="纳萨兰娜·风歌是谁？",a="纳萨兰娜·风歌是一位居住在申达尔村的导师。她教导熟练的从业者如何为野外营地制作特殊的专业物品，特别是为证明了自己工艺水平的附魔师制作附魔的鲁特琴。",al={"谁教授附魔的鲁特琴","谁是纳萨兰娜·风歌","纳萨兰娜·风歌在哪里"}},{q="申达尔村在哪里？",a="申达尔村是纳萨兰娜·风歌居住的定居点。在掌握了核心技能后，想要学习如何制作附魔的鲁特琴等露营装备的冒险者都会前往那里。",al={"申达尔村在哪里","如何找到申达尔村"}},{q="什么是附魔的鲁特琴？",a="附魔的鲁特琴是由附魔师制作的一种魔法露营乐器。它能在营火旁的休息时间提供娱乐和恢复士气，帮助旅行者调整心态，为面对前方野外的严酷挑战做好准备。",al={"附魔的鲁特琴有什么用","为什么要制作附魔的鲁特琴","露营鲁特琴"}},{q="学习配方有什么要求？",a="在纳萨兰娜·风歌教你如何制作附魔的鲁特琴之前，你必须先证明自己在附魔这一魔法艺术上的造诣。只有经验丰富的从业者才被信任能制作这些营地功能性附魔物品。",al={"露营指南附魔要求","什么时候可以学习附魔的鲁特琴"}},{q="为什么附魔师在野外营地很有价值？",a="附魔师为偏远的营地带来了微妙的实用性和魔法慰藉，因为普通的补给往往难以满足需求。通过为普通的营地工具注入魔法强化，他们帮助冒险者恢复精力、保持娱乐，并为旅途中可能遇到的突发危险做好准备。",al={"为什么露营者需要附魔师","附魔师露营福利"}},{q="其他专业可以制作露营物品吗？",a="是的，各行各业的工匠和采集者都会学习建造专用的露营工具。对于附魔师来说，这种专业的工艺表现为由申达尔村的纳萨兰娜·风歌教授的附魔的鲁特琴。",al={"还有其他露营物品吗","其他专业的营地制作"}}},fp="23,170,22.284.0,20.330.0,28.190.0,26.185.0,26.202.0,46.172.0,52.188.0,42.179.0"}
P.entries["quest:98291"] = {n="Death to the Dragonmaw",s="霍文·鹰羽请你在龙喉营地削弱龙喉兽人的兵力。他希望接近格瑞姆巴托，为蛮锤氏族夺回那里，或是了解更多情况。",h="霍文·鹰羽请你在龙喉营地削弱龙喉兽人的兵力。他希望接近格瑞姆巴托，为蛮锤氏族夺回那里，或是了解更多情况。",kw={"龙喉潜伏者","龙喉兽人","龙喉收复者","龙喉营地","龙喉缚魂者","格瑞姆巴托","霍文·鹰羽","蛮锤氏族"},sec={{t="龙喉营地",b="龙喉兽人聚集在撤退路线上，红龙曾在这里击溃过他们。Howin必须先削减他们的人数，才能接近格瑞姆巴托。他指给你东边的道路，让你沿路寻找他们。"}},faq={{q="霍文·鹰羽是谁？",a="霍文·鹰羽想重新进入格瑞姆巴托，为蛮锤氏族夺回那里，或者至少了解更多情况。",al={"霍文是谁","霍文这个人"}},{q="霍温为什么需要帮助？",a="霍温说，龙喉兽人正穿过龙喉营地行进。他必须先削减他们的人数，才能接近格瑞姆巴托。",al={"为什么帮霍文","霍文需要什么"}},{q="龙喉兽人在哪里？",a="龙喉兽人就在龙喉营地一带。霍温让你沿路向东寻找他们。",al={"龙喉兽人在哪","龙喉兽人位置"}},{q="我该找哪些人？",a="霍温提到了龙喉收复者、龙喉缚魂者和龙喉潜伏者。",al={"哪些兽人","龙喉兽人种类"}},{q="龙喉营地发生过什么？",a="红龙曾在龙喉营地击溃过龙喉兽人。",al={"龙喉兽人历史","为何撤退"}}},fp="22,166,17.202.0,25.120.0,25.131.0,29.98.0,22.84.0,35.66.0"}
P.entries["quest:98293"] = {n="Forced Disarmament",s="Forced Disarmament是湿地的一项联盟任务，要求冒险者从龙喉营地的龙喉氏族手中夺取武器储藏。通过收集三十捆军械，玩家可以阻止这些敌对兽人武装更多士兵用于未来的突袭。缴获的装备会被送往米奈希尔城堡的斯托菲队长处，以保卫该地区至关重要的港口。",h="Forced...",kw={"斯托菲队长","龙喉军械","龙喉氏族","龙喉营地","强制缴械","米奈希尔港","米奈希尔城堡","湿地"},ang={["faction:Alliance"]="联盟军队将米奈希尔港视为跨越无尽之海的关键生命线，因此解除附近敌对氏族的武装是一项紧急的战略必要。",["race:Dwarf"]="来自铁炉堡的矮人守军负责维持米奈希尔城堡的驻军，致力于保卫卡兹莫丹的边界，防止陷于沼泽中的旧日敌人的侵袭。",["race:Orc"]="龙喉氏族代表了旧部落的一个四分五裂且执迷不悟的残余势力，他们暴力的好战行径使他们与卡利姆多的新部落领导层彻底隔绝。"},sec={{t="沼泽中的军械库",b="在湿地的沼泽地带，敌对的龙喉氏族开始在龙喉营地内囤积惊人数量的武器。如果不加遏制，这些物资将使这些叛变兽人能够武装起一波波新战士，并对邻近定居点发动毁灭性的袭击。解除他们营地的武装是对其后勤能力的直接打击，可以在他们的战团完成动员并走上战场之前，挫败任何预谋的攻势。"},{t="守卫沿海港口",b="米奈希尔港是连接卡兹莫丹、暴风城与海洋的主要门户，因此附近任何军事集结都是严重的威胁。斯托菲队长在米奈希尔城堡协调防御措施，密切监视着入侵城镇的敌对氏族和野兽。回收三十套龙喉军械不仅剥夺了兽人的基本军需品，还能为矮人驻军提供关于敌人准备情况的关键情报。"}},faq={{q="斯托菲队长是谁？",a="斯托菲队长是一位驻扎在米奈希尔城堡的矮人军官，负责保卫米奈希尔港和周边的湿地。面对来自敌对野兽、黑铁矮人破坏者以及龙喉氏族的持续压力，斯托菲积极指挥士兵和冒险者，在港口关键的补给线和港口设施被攻占之前压制附近的威胁。",al={"斯托菲","斯托菲是谁","米奈希尔城堡队长"}},{q="为什么需要解除龙喉氏族的武装？",a="龙喉氏族正在他们的营地中积极囤积武器，以装备新的战斗人员。如果任由他们不受阻挠地囤积军需品，他们的战团可能会压垮当地的联盟防御力量，并危及米奈希尔港。夺取三十捆武器直接阻碍了他们的后勤准备，并阻止更多的兽人士兵走上战场。",al={"为什么要夺取龙喉武器","龙喉军械的目的","解除龙喉武装"}},{q="龙喉营地位于哪里？",a="龙喉营地是龙喉兽人在湿地建立的一处据点，位于米奈希尔港外向东延伸的山脉方向。该氏族利用这一隐蔽的前哨站来集结兵力、储存武器，并对沼泽中的旅行者发动袭击。冒险者必须深入营地中心，回收他们囤积的武器。",al={"龙喉营地位置","龙喉营地在哪里","湿地龙喉营地"}},{q="什么是龙喉军械？",a="龙喉军械是龙喉氏族为了供给战士而锻造或掠夺的战斗装备、刀剑和补给缓存。这些武器代表了该氏族在当地的即时军事实力。斯托菲队长要求没收三十捆这些军需品，并带回米奈希尔城堡进行评估和处理。",al={"龙喉武器","什么是军械","龙喉装备"}},{q="龙喉氏族在黑暗之门开启后25年时是部落的一部分吗？",a="不是，湿地的龙喉氏族是一个独立的敌对派系，不听从萨尔酋长的号令。在第二次战争后，这些兽人依然忠于他们旧有的行事方式，对联盟怀有深仇大恨，并拒绝任何和平提议。因此，联盟守军和独立的旅行者都将他们视为致命的对手。",al={"龙喉氏族属于部落吗","龙喉氏族派系","龙喉萨尔"}},{q="为什么米奈希尔城堡会关注龙喉氏族？",a="米奈希尔城堡是保卫米奈希尔港的行政和军事要塞，而米奈希尔港是联盟在卡兹莫丹的主要海上枢纽。由于港口周边的湿地饱受沼泽野兽和好战兽人的侵扰，斯托菲队长不能允许像龙喉营地这样重装防守的据点在靠近王国码头和贸易路线的地方壮大。",al={"米奈希尔城堡龙喉威胁","为什么斯托菲在意","米奈希尔港防御"}}},fp="18,271,24.276.0,25.378.0,25.349.0,41.274.0,35.290.0,29.311.0,50.325.0,50.342.0"}
P.entries["quest:98297"] = {n="Stopping the Cycle",s="霍文·鹰羽完成试飞归来，带来了令人不安的消息：龙喉术士正在奴役一头红色龙人。蛮锤氏族绝不会让这种事再次发生。",h="霍文·鹰羽完成试飞归来，带来了令人不安的消息：龙喉术士正在奴役一头红色龙人。蛮锤氏族绝不会让这种事再次发生。",kw={"龙喉氏族","龙喉大门","霍文·鹰羽","红色龙人","终结循环","被制服的龙人","术士","蛮锤氏族"},sec={{t="大门前",b="Howin请你前往龙喉大门，对付那头被制服的龙人。他说，必须先杀死压制它的术士，这样它就能挣脱束缚。之后，你要结束它的痛苦。Howin希望你带上同伴；蛮锤氏族不会让龙喉氏族阻挡他们。"}},faq={{q="谁在请求帮助？",a="霍文·鹰羽请求你阻止龙喉氏族奴役一头红色龙人。",al={"谁需要帮助","霍文的任务"}},{q="龙喉氏族在做什么？",a="一群龙喉术士正压制着一头红色龙人，试图奴役它。",al={"龙喉氏族在做什么","龙人为何被制服"}},{q="龙人在哪里？",a="那头被制服的龙人就在龙喉大门。",al={"龙人位置","被制服的龙人在哪里"}},{q="霍温要我做什么？",a="霍温要你杀死压制龙人的术士，然后结束它的痛苦。",al={"我该做什么","终结循环"}},{q="为什么霍温说蛮锤氏族不能容许这种事？",a="霍温说龙喉氏族正在奴役一头红色龙人，并坚称蛮锤氏族绝不会让他们阻挡自己。",al={"为何不能重蹈覆辙","蛮锤氏族的缘由"}}},fp="18,188,12.291.0,23.82.0,29.89.0,25.50.0,29.96.0,52.122.0"}
P.entries["quest:98298"] = {n="阿鲁高的愚行",s="阿鲁高的愚行是银松森林中的一个被遗忘者任务，达拉尔·道恩维沃尔在此调查格雷迈恩之墙附近徘徊的狼人的真正起源。通过分析收集到的狼人残骸，达拉尔试图证明大法师阿鲁高只是一个冒牌货，他仅仅是束缚住了这些生物，而非召唤了他们的诅咒。",h="阿鲁高的愚行是银松森林中的一个被遗忘者任务，达拉尔·道恩维沃尔在此调查格雷迈恩之墙附近徘徊的狼人的真正起源。通过分析收集到的狼人残骸，达拉尔试图证明大法师阿鲁高只是一个冒牌货，他仅仅是束缚住了这些生物，而非召唤了他们的诅...",kw={"阿鲁高","阿鲁高的愚行","达拉尔·道恩维沃尔","格雷迈恩之墙","银松森林","瑟伯切尔","狼人碎片","狼人诅咒"},ang={["class:Mage"]="奥术修行者们可以欣赏达拉尔对阿鲁高所谓魔法诅咒的分析性解构，从而分辨出束缚附魔与传染性苦难之间的区别。",["faction:Horde"]="协助达拉尔·道恩维沃尔的部落冒险者们，帮助保护了银松森林免受猖獗的野蛮掠食者以及正屈服于苦难的邻近人类定居点的侵害。",["race:Undead"]="对于驻扎在瑟伯切尔的被遗忘者来说，理清银松森林中狼人爆发的本质，对于保护洛丹伦免受无法控制的野蛮威胁至关重要。"},sec={{t="揭穿大法师",b="驻扎在银松森林瑟伯切尔的被遗忘者法师达拉尔·道恩维沃尔，试图拆穿他竞争对手大法师阿鲁高的神秘面纱。在检查了附魔枷锁后，达拉尔断定阿鲁高缺乏足以显现或创造出困扰该地区的狼群的原始力量。相反，阿鲁高只是掌握了一些能够暂时束缚住这些野兽的低级附魔，这使得狼人野性传染的真正机制和起源依然是个未解之谜。"},{t="野兽入侵",b="为了寻求实证，达拉尔派遣冒险者前往南方的格雷迈恩之墙那令人生畏的防御工事。在周边的荒野中，凶猛的狼人已经开始攻击并感染附近的人类居民。通过斩杀这些贪婪的生物并取回解剖组织样本，调查员们为达拉尔提供了所需的直接物理标本，以分析这种苦难的生物学和魔法真相。"},{t="苦涩的辩解",b="在检查了收获的狼人残骸后，达拉尔兴高采烈地宣布他在学术声誉上战胜了阿鲁高，证实了这位大法师与苦难的起源毫无关系。然而，这一揭示对被遗忘者来说却带来了一个严峻的后果：如果阿鲁高从未发明过这种诅咒，那么他所制定的所谓补救措施和对策就完全是无用的，这使得狼人爆发的真正谜团依然完全未被解开。"}},faq={{q="谁发布了任务阿鲁高的愚行？",a="该任务由达拉尔·道恩维沃尔发布并完成，他是一位驻扎在银松森林瑟伯切尔的奥术研究员兼被遗忘者法师。",al={"谁发布 阿鲁高的愚行","在哪里交 阿鲁高的愚行","阿鲁高的愚行 任务发布者"}},{q="为什么达拉尔·道恩维沃尔认为阿鲁高是个骗子？",a="达拉尔·道恩维沃尔断定大法师阿鲁高是个傲慢的骗子。达拉尔认为，阿鲁高仅仅拥有勉强能暂时束缚住狼人的魔法能力，而非创造或引发它们，从而将所谓的“阿鲁高的诅咒”揭露为一场骗局。",al={"达拉尔如何看待阿鲁高","阿鲁高是否制造了狼人","阿鲁高是骗子"}},{q="在哪里可以找到给达拉尔的狼人碎片？",a="为了完成任务，冒险者们需要向南穿过银松森林前往格雷迈恩之墙，凶猛的狼人就在当地人类定居点附近徘徊。击杀这些野兽即可获得达拉尔调查所需的狼人碎片。",al={"狼人碎片在哪里","格雷迈恩之墙狼人","阿鲁高的愚行 去哪里"}},{q="达拉尔找到了治愈狼人诅咒的方法吗？",a="此处并未发现补救方法。由于达拉尔发现阿鲁高最初并未创造出狼人苦难，因此阿鲁高调制的任何补救措施或反制法术都毫无用处，这使得被遗忘者不得不去别处寻找真正的解决方案。",al={"狼人诅咒能治愈吗","阿鲁高的补救措施有效吗","是否有狼人解药"}},{q="狼人的苦难是如何在格雷迈恩之墙附近传播的？",a="达拉尔指出，狼人的苦难似乎并非通过阿鲁高施展的某种宏大的奥术仪式或法术，而是通过身体接触和撕咬直接传播给格雷迈恩之墙附近的人类居民。",al={"诅咒如何传播","狼人传播给人类","谁正在被感染"}},{q="达拉尔在检查了狼人碎片后得出了什么结论？",a="检查被击杀狼人的解剖碎片向达拉尔证明了它们的诅咒与阿鲁高的法术毫无关系。虽然这证实了他竞争对手的魔法无能，但也证实了狼人诅咒仍然是一个活跃的、未被解释的威胁，且没有有效的解药。",al={"达拉尔从碎片中学到了什么","阿鲁高的愚行 结论","阿鲁高的愚行 剧情揭示"}}},fp="14,206,21.341.0,21.318.0,20.332.1,35.129.0,50.172.0,44.159.0,44.181.0,62.182.0,58.209.0"}
P.entries["quest:98299"] = {n="Stop the Spread",s="“阻止蔓延”是银松森林的一项任务，内容是遏制与大法师阿鲁高有关的狼人诅咒。当研究人员寻求阻止该痛苦的方法时，针对格雷迈恩之墙附近活着的人类难民的先发制人措施已被下达，以防止他们变成阿鲁高的仆从。",h="“阻止蔓延”是银松森林的一项任务，内容是遏制与大法师阿鲁高有关的狼人诅咒。当研究人员寻求阻止该痛苦的方法时，针对格雷迈恩之墙附近活着的人类难民的先发制人措施已被下达，以防止他们变成阿鲁高的仆从。",kw={"阿鲁高","诅咒","被遗忘者","格雷迈恩之墙","难民","银松森林","天降","阻止蔓延","狼人"},ang={["race:Human"]="聚集在紧闭的格雷迈恩之墙处的未感染人类难民，在被遗忘者研究人员看来是阿鲁高扩散诅咒的主要载体。",["race:Skyborne"]="天降的冒险者在执行格雷迈恩之墙附近的严酷遏制命令时，被直接警告要避免被咬伤。",["race:Undead"]="被遗忘者似乎对狼人痛苦具有独特的免疫力，这使得遏制行动在亡灵部队没有感染风险的情况下变得可行。"},sec={{t="银松森林的痛苦",b="在银松森林，狼人的祸害在叛逃的大法师阿鲁高的手中蔓延。虽然这种野性疾病传播背后的具体方法和机制在很大程度上仍然未知，但它对该领土构成的危险是不可否认的。研究人员正在积极努力了解这种魔法的本质，但他们目前的重点是防止阿鲁高聚集一支无法阻挡的野蛮追随者大军。"},{t="在格雷迈恩之墙的遏制",b="被遗忘者调查人员观察到，他们的亡灵生理结构使他们对狼人感染免疫。然而，活着的人类并没有这种天然的防御能力。在南部的边界，一大群人类难民绝望地聚集在紧闭的格雷迈恩之墙大门周围。由于担心这些毫无防备的幸存者会被咬伤并转化为阿鲁高的忠实奴隶，先发制人且残酷的遏制命令已被下达，要求在痛苦折磨他们之前清除这些聚集的人群。"}},faq={{q="任务“阻止蔓延”是关于什么的？",a="“阻止蔓延”是一项侧重于遏制蹂躏银松森林的狼人诅咒的任务。为了防止大法师阿鲁高获得新的仆从，部队被派遣去消灭格雷迈恩之墙附近的人类难民，以免他们屈服于这种痛苦。",al={"什么是阻止蔓延","阻止蔓延任务背景"}},{q="谁应该为银松森林的狼人负责？",a="大法师阿鲁高被认为应对银松森林内狼人的存在负责，无论是通过他蓄意的阴谋还是他魔法的不可预见后果。他日益壮大的狼群威胁着整个地区。",al={"谁传播了狼人诅咒","阿鲁高狼人关联"}},{q="被遗忘者会感染狼人诅咒吗？",a="根据当地被遗忘者的研究，狼人诅咒无法感染亡灵。这种免疫力使被遗忘者特工能够直面威胁，而不必担心变成阿鲁高的野兽仆从。",al={"被遗忘者能成为狼人吗","亡灵对狼人免疫吗"}},{q="为什么要在格雷迈恩之墙针对人类难民？",a="一大群人类难民聚集在紧闭的格雷迈恩之墙外。因为活着的人类容易受到阿鲁高诅咒的影响，他们被视为壮大狼人队伍的紧迫威胁。",al={"为什么杀害难民","格雷迈恩之墙难民"}},{q="狼人痛苦是如何传播的？",a="虽然已知狼人诅咒可以通过咬伤传播，但其传播的确切魔法和生物学机制仍处于银松森林研究人员的积极调查中。",al={"狼人如何传播","狼人诅咒传播"}},{q="有办法阻止或治愈狼人诅咒吗？",a="目前，尚无已知的治疗狼人痛苦的方法。研究人员正在试图发现一种治疗方法来阻止这种诅咒，但他们的当务之急仍然是积极的遏制。",al={"狼人诅咒能治愈吗","狼人疗法"}}},fp="15,223,25.314.0,23.402.1,40.178.0,48.169.0,40.155.0,59.166.0,38.144.0,48.129.0"}
P.entries["quest:983"] = {n="传声盒827号",s="嗡鸣箱827是侏儒维兹班恩·曲针在黑海岸沿岸建造的一系列实验性通讯中继站中的第一个。这些奇特的机械装置经常发生故障，依靠一种古怪的设计来运作，即利用当地野生动物的身体部位进行现场维修。修复这台沉默的机器可以让维兹班恩直接从奥伯丁测试他的远程语音网络。",h="嗡鸣箱827是侏儒维兹班恩·曲针在黑海岸沿岸建造的一系列实验性通讯中继站中的第一个。这些奇特的机械装置经常发生故障，依靠一种古怪的设计来运作，即利用当地野生动物的身体部位进行现场维修。修复这台沉默的机器可以让维兹班恩直接...",kw={"奥伯丁","嗡鸣箱827","蟹腿","黑海岸","侏儒工程学","礁蟹","潮滩蟹","维兹班恩·曲针"},ang={["profession:Engineering"]="使用有机几丁质和节肢动物的肢体来代替锻造的黄铜齿轮是典型的侏儒式即兴创作，牺牲了耐用性，换取了容易从当地获取的材料。",["race:Gnome"]="维兹班恩的装置代表了经典的侏儒式雄心，试图将技术连接带到一个从未见过电话或无线电的古老、狂野的土地上。",["race:NightElf"]="这些叮当作响、冒着烟的嗡鸣箱是卡利姆多神圣而阴郁的海岸上的一道诡异的风景，尽管奥伯丁的暗夜精灵们容忍了这位技师的实验。"},sec={{t="古老海岸上的侏儒创新",b="在造访奥伯丁期间，古怪的侏儒工程师维兹班恩·曲针试图用一系列被称为“嗡鸣箱”的远程声学中继站，来跨越狂野海岸间的漫长距离。这些装置上布满了操纵杆，专为远距离语音传输而设计，与黑海岸古老的废墟和阴郁的森林形成了鲜明的对比。然而，就像许多雄心勃勃的侏儒发明一样，它们长期处于不稳定状态，需要近乎不断的维护才能让内部齿轮正常运转。"},{t="生态维护",b="维兹班恩没有选择将精炼的铁齿轮和铜销运过荒野，而是采取了一种非传统的解决方案：他将每个嗡鸣箱都设计为使用从附近原生动物身上采集的部件进行维护。嗡鸣箱827位于奥伯丁以南的多雾海岸线上，其工程设计是利用当地潮滩蟹和礁蟹坚固的节肢腿来运作。将蟹腿放入接收料斗中，机器就会自动组装并恢复活力，通过扬声器广播维兹班恩遥远的声音。"}},faq={{q="什么是嗡鸣箱？",a="嗡鸣箱是一种由侏儒维兹班恩·曲针发明的远程语音通讯机器。它配备了操纵杆和内部机械，旨在将声音跨越黑海岸未经开发的广阔区域进行传输，使人们能够在数英里的距离外进行交谈。",al={"嗡鸣箱的作用","嗡鸣箱的目的","黑海岸侏儒装置"}},{q="为什么金属机器需要螃蟹腿来运行？",a="维兹班恩特意将每个嗡鸣箱设计为使用来自周围野生动物的有机部件作为临时替代零件。通过将嗡鸣箱827放置在蟹类栖息的海滩附近，他确保了旅行者可以使用几丁质的肢体代替稀有的机械金属进行紧急机械维修。",al={"为什么用蟹腿","蟹腿修理","为什么喂它腿"}},{q="嗡鸣箱827位于何处？",a="嗡鸣箱827位于黑海岸的海岸线上，就在奥伯丁沿海定居点以南不远处。",al={"嗡鸣箱827位置","嗡鸣箱827在哪里","寻找嗡鸣箱827"}},{q="维兹班恩·曲针是谁？",a="维兹班恩·曲针是一位住在奥伯丁旅店楼上的侏儒技师。他雄心勃勃、富有进取心，尽管他的原型机不断发生故障，但他仍试图在黑海岸建立一个互联的通讯网络。",al={"维兹班恩·曲针","谁制造了嗡鸣箱","奥伯丁侏儒"}},{q="我可以在哪里找到用于维修的蟹腿？",a="蟹腿可以从奥伯丁以南黑海岸海滩的沙地和浅滩上爬行的侏儒潮滩蟹和幼年礁蟹身上收集到。",al={"蟹腿位置","如何获得蟹腿","侏儒潮滩蟹"}},{q="修复嗡鸣箱827后会发生什么？",a="一旦将蟹腿喂入料斗，机器就会将其研磨到位，嗡嗡作响恢复活力，并转播来自奥伯丁的维兹班恩的声音。对成功感到满意的他，会立即要求你前往更远的海岸，去修理链条中的下一个装置——嗡鸣箱411。",al={"嗡鸣箱827之后","嗡鸣箱后续任务","嗡鸣箱827完成"}}},fp="11,237,36.339.0,22.404.0,18.189.0,47.198.0,29.67.0,27.169.0,45.165.0,42.226.1"}
P.entries["quest:98310"] = {n="Gleaning Our Future",s="勘察员维尔加发现了从戈阿兹之石上进一步探究的机会。四个体型更大的魔像刻有铭文，与石头缺失的部分相吻合。",h="勘察员维尔加发现了从戈阿兹之石上进一步探究的机会。四个体型更大的魔像刻有铭文，与石头缺失的部分相吻合。",kw={"阿度斯","收获我们的未来","戈阿兹之石","魔像心脏","高尔姆","铭文","莫德","奈尔鲁","勘察员维尔加","湿地"},sec={{t="四处铭文",b="你找到了戈阿兹之石缺失的部分。维尔加指出了四个体型更大的魔像，它们分别名为阿度斯、莫德、高尔姆和奈尔鲁。他让你在每个魔像附近使用石头，再把它们的心脏带回来，希望能从中发现更多石头上的纹路。"},{t="隐约显现的文字",b="维尔加把心脏靠近戈阿兹之石时，一行新文字在微光中浮现：“血肉诅咒……他们终将失败。”他无法理解这句话的含义，想把石头带到安全的地方进一步研究。"}},faq={{q="维尔加想让我带回什么？",a="维尔加让你在每个魔像附近使用戈阿兹之石，然后带回阿度斯、莫德、高尔姆和奈尔鲁的心脏。",al={"维尔加想要什么","魔像心脏","带回心脏"}},{q="四个魔像在哪里？",a="阿度斯位于格瑞姆巴托附近的龙喉大门。莫德就在丹莫德以北。高尔姆位于格瑞姆巴托地下，在丹奥加兹以东。奈尔鲁在恶铁岭东北方的后面。",al={"阿度斯 莫德 高尔姆 奈尔鲁在哪里","魔像位置","在哪里找到魔像"}},{q="维尔加为什么想要魔像的心脏？",a="这些魔像刻有与戈阿兹之石缺失部分相吻合的铭文，维尔加希望它们的心脏能揭示石头上的更多内容。",al={"为什么要心脏","心脏有什么用","戈阿兹之石碎片"}},{q="维尔加怎么看这些魔像？",a="维尔加怀疑这些构造体会比守护者更难对付。",al={"魔像是否强悍","维尔加的警告","魔像实力"}}},fp="19,125,17.250.0,11.239.1,40.112.0,26.188.0,39.134.0,38.64.0"}
P.entries["quest:98313"] = {n="For Further Study",s="史学家卡尼克正在铁炉堡等候一个与史诗之事有关的包裹。目前所见的一切都让进一步研究显得值得。",h="史学家卡尼克正在铁炉堡等候一个与史诗之事有关的包裹。目前所见的一切都让进一步研究显得值得。",kw={"进一步研究","探险者大厅","史学家卡尼克","铁炉堡","图书馆","维尔加圣物包裹"},sec={{t="卡尼克的图书馆",b="你受托将维尔加圣物包裹交给探险者大厅的史学家卡尼克。他通常在图书馆后面看书。"}},faq={{q="谁在等这个包裹？",a="史学家卡尼克正在铁炉堡探险者大厅等候维尔加圣物包裹。",al={"谁来收取","给谁的包裹"}},{q="我在哪里能找到卡尼克？",a="史学家卡尼克通常在铁炉堡探险者大厅图书馆的后面。",al={"卡尼克在哪里","卡尼克的位置"}},{q="我带着什么包裹？",a="你带着要交给史学家卡尼克的维尔加圣物包裹。",al={"什么包裹","圣物包裹"}},{q="为什么这件事需要进一步研究？",a="文本称此事非同寻常，并说目前所见的一切都让进一步研究显得值得，但没有提供更多细节。",al={"为什么研究","有什么特别之处"}}},fp="17,129,16.139.0,31.83.0,24.96.0,27.64.0,33.123.0"}
P.entries["quest:98319"] = {n="Secure the Mountain",s="“Secure the Mountain”是联盟的一个任务，旨在解决丹莫罗的灰色洞穴中温迪戈突然激增并泛滥成灾的问题。冒险者们需要进入被怪物占据的洞穴，找到一位鲁莽的矮人侦察兵科尼利厄斯，并为白须取回一份重要的报告。",h="“Secure the Mountain”是联盟的一个任务，旨在解决丹莫罗的灰色洞穴中温迪戈突然激增并泛滥成灾的问题。冒险者们需要进入被怪物占据的洞穴，找到一位鲁莽的矮人侦察兵科尼利厄斯，并为白须取回一份重要的报告。",kw={"科尼利厄斯","丹莫罗","灰色洞穴","登山者","确保山区安全","巨魔","温迪戈","白须"},ang={["faction:Alliance"]="确保白须收到情报报告，对于联盟军队维持边境安全以抵御本土山地威胁至关重要。",["race:Dwarf"]="夺回像灰色洞穴这样的洞穴，可以保护矮人登山者和旅行者免受那些侵占丹莫罗道路的温迪戈的伤害。"},sec={{t="泛滥的洞穴",b="驻守在冰冷山坡上的矮人侦察兵们面临着双重威胁。除了时刻存在的霜鬃巨魔威胁外，当地的温迪戈也开始疯狂繁衍，它们放弃了原本孤独的巢穴，成群结队地涌入北边的灰色洞穴。这些野蛮的野兽使山路对于巡逻队和信使来说变得极其危险。"},{t="鲁莽的英勇",b="一位名叫科尼利厄斯的侦察兵一头冲进了灰色洞穴，试图取回一份给白须的重要报告。他这种冲动的英勇行为导致他的同伴被困在外面，只能寻求能干的冒险者进入怪物密布的洞穴，找到那位鲁莽的矮人，并削减凶猛的温迪戈数量。"}},faq={{q="谁是科尼利厄斯？",a="科尼利厄斯是与任务发布者搭档的一名侦察兵或登山者。他因鲁莽的勇气而直接冲进了布满温迪戈的灰色洞穴，将同伴留在外面等待救援，以寻回他本人和白须的报告。",al={"科尼利厄斯是谁","矮人科尼利厄斯","科尼利厄斯在哪里"}},{q="什么是灰色洞穴？",a="灰色洞穴是位于登山者营地北侧的一个洞穴。虽然温迪戈通常只待在深山巢穴中，但最近它们却异常大量地涌入了该洞穴。",al={"什么是灰色洞穴","温迪戈在哪里","丹莫罗温迪戈洞穴"}},{q="为什么温迪戈在扩散？",a="温迪戈通常待在与世隔绝的洞穴里，但当地侦察兵注意到，它们已经开始在冰雪覆盖的山脊上大量繁殖并迅速蔓延，与当地的巨魔威胁一起构成了严重的隐患。",al={"为什么温迪戈在扩散","丹莫罗温迪戈问题","温迪戈像兔子一样繁衍"}},{q="谁是白须，他的报告是什么？",a="白须是一位权威人士或指挥官，正在等待一份关于山区状况的重要侦察报告。科尼利厄斯在鲁莽冲进洞穴之前，正携带着或试图确保这份报告的安全。",al={"谁是白须","白须的报告","森内尔·白须"}},{q="“确保山脉安全”的目标是什么？",a="这是一项营救和清理任务，要求冒险者进入灰色洞穴，找到失踪的侦察兵科尼利厄斯，并清理洞穴中猖獗的温迪戈。",al={"什么是确保山区安全","确保山区安全任务目标"}},{q="巨魔是如何导致山区麻烦的？",a="当地侦察兵在山峰上已经面临着来自本土霜鬃巨魔的持续压力。突然激增的温迪戈为试图守卫山口的巡逻队制造了危险的双重威胁。",al={"丹莫罗的巨魔","巨魔威胁"}}},fp="19,179,13.227.0,14.179.0,17.179.0,25.147.0,31.167.0,41.112.0,40.92.0,54.139.0"}
P.entries["quest:98321"] = {n="Flintfire's Shipment",s="卡拉诺斯的托格努斯·燧火正面临严重的物资短缺，因为凶猛的温迪戈占领了他主要的矿石来源——灰色洞穴。矿工们在撤离时被迫丢下了装满矿石的板条箱，冒险者们受命找回这些遗失的货物，以维持当地熔炉的运转。",h="卡拉诺斯的托格努斯·燧火正面临严重的物资短缺，因为凶猛的温迪戈占领了他主要的矿石来源——灰色洞穴。矿工们在撤离时被迫丢下了装满矿石的板条箱，冒险者们受命找回这些遗失的货物，以维持当地熔炉的运转。",kw={"丹莫罗","燧火","熔炉","灰色洞穴","卡拉诺斯","矿工","矿石","货物","托格努斯·燧火","温迪戈"},ang={["profession:Blacksmithing"]="找回Flintfire的货物对于确保卡拉诺斯的当地熔炉有充足的可加工金属供应至关重要。",["profession:Mining"]="遗失的货物由矿工在温迪戈袭击时撤离主要挖掘点所留下的重要矿石组成。",["race:Gnome"]="托格努斯·燧火特别欢迎愿意在丹莫罗从事繁重体力劳动的侏儒冒险者，并对他们的毅力表示真诚的赞赏。"},sec={{t="卡拉诺斯的物资危机",b="在冰雪覆盖的卡拉诺斯定居点，托格努斯·燧火的熔炉正面临严重的物资危机。在凶猛的温迪戈入侵挖掘现场后，该地区最富产、最可靠的矿石来源突然沉寂了。当地矿工在猝不及防的情况下遭到了这些凶猛捕食者的袭击，被迫立即放弃岗位，四散逃命，留下了散落在洞穴地面上、刚刚打包好的珍贵矿石板条箱。"},{t="深入灰色洞穴",b="这个被占领的矿坑名为灰色洞穴，位于卡拉诺斯以西。虽然托格努斯很庆幸所有矿工都从那些凶猛野兽的口中平安逃脱，但停工却威胁到了当地铁匠铺的全面运作。与其等待武装远征队去清理洞穴，托格努斯更希望寻求勇敢的冒险者潜入温迪戈的巢穴，收集那些滞留的板条箱，并将至关重要的矿石带回熔炉。"}},faq={{q="托格努斯·燧火是谁？",a="托格努斯·燧火是卡拉诺斯的一名矮人，依靠稳定的矿石运输来维持其熔炉的运作。在温迪戈占领了他主要的采矿洞穴并导致严重的物资短缺后，他招募旅行者去面对危险，取回那些被遗弃的板条箱。",al={"托格努斯·燧火是谁","托格努斯·燧火","任务发布者"}},{q="灰色洞穴位于何处？",a="灰色洞穴是位于丹莫罗卡拉诺斯以西的一个洞穴系统。它曾经是一个可靠的采矿点，现在却成了凶猛的温迪戈的巢穴，迫使任何想要寻找遗失矿石的人必须进入这片敌对区域。",al={"灰色洞穴在哪里","灰色洞穴位置","货物在哪里寻找"}},{q="采矿洞穴为何被废弃？",a="在敌对的温迪戈入侵并占领该地点之前，这个洞穴曾是当地矿工最可靠的矿石来源。工人们在绝望的撤离中被迫丢弃了设备和储备的货物，奇迹般地幸存了下来。",al={"矿工为何逃离","矿坑发生了什么","温迪戈袭击"}},{q="丢失的货物里有什么？",a="这些货物由矿工在被驱逐前打包进板条箱的开采矿石组成。没有这些材料，卡拉诺斯的当地金属加工和熔炉作业将陷入停滞。",al={"燧火的货物是什么","板条箱里有什么","货物内容"}},{q="在袭击中是否有矿工受伤？",a="尽管温迪戈极其凶猛，但托格努斯欣慰地表示，所有的矿工都设法平安逃出了灰色洞穴，只留下了他们的补给品和矿石。",al={"矿工生还了吗","矿工伤亡","温迪戈受害者"}},{q="货物被找回后会发生什么？",a="确保找回这些货物，能为托格努斯·燧火提供重启当地熔炉所需的原材料，而无需先清理整个被侵扰的洞穴。",al={"为什么需要矿石","找回后会发生什么","熔炉运转"}}},fp="20,190,27.261.0,31.353.0,24.208.0,34.160.0,34.193.0,37.174.0,42.137.0,46.170.0"}
P.entries["quest:98322"] = {n="Secure the Mountain",s="“Secure the Mountain”是丹莫罗卡拉诺斯的一项联盟任务。一位负责为铁炉堡搜集情报的当地官员在负责调查好斗的温迪戈的侦察兵失联后，派遣冒险者前往镇子西面查看山地巡逻队员格雷琴的情况。",h="“Secure the Mountain”是丹莫罗卡拉诺斯的一项联盟任务。一位负责为铁炉堡搜集情报的当地官员在负责调查好斗的温迪戈的侦察兵失联后，派遣冒险者前往镇子西面查看山地巡逻队员格雷琴的情况。",kw={"丹莫罗","矮人","铁炉堡","卡拉诺斯","山地巡逻队员格雷琴","确保山区安全","温迪戈","白须"},ang={["faction:Alliance"]="协助卡拉诺斯周围的当地矮人巡逻队加强了整个卡兹莫丹冰雪腹地的防御协调。",["race:Dwarf"]="丹莫罗的山地巡逻队员在雪山脊和危险的洞穴中保持着警惕的巡逻，可靠的侦察对于保障矮人定居点的安全至关重要。"},sec={{t="逾期的报告",b="一位卡拉诺斯的官员受命为铁炉堡的王座厅汇编当地的军事情报，但他的日常工作却被打断了。一支被派去评估附近温迪戈活动的山地巡逻队未能带回最新的消息。这位官员没有亲自去钻冰冷的洞穴，而是招募了有能力的旅行者前往镇子西面，去确认侦察兵们的状况。"},{t="西部山脊的麻烦",b="在卡拉诺斯西面找到山地巡逻队员格雷琴后，原本平静的区域监视工作变得令人担忧起来。格雷琴确认她收到了白须的询问，但她透露，周围山岩中的温迪戈骚乱远比最初的报告所显示的更加不稳定，这也为进一步深入附近的荒野进行侦察埋下了伏笔。"}},faq={{q="谁发布了“确保山脉安全”任务？",a="该任务由卡拉诺斯的森内尔·白须发布，山地巡逻队员格雷琴称他为“老白须”。他的职责包括汇编关于当地荒野威胁的正式报告，并将其发送给铁炉堡的矮人领导层。",al={"谁发布了“确保山区安全”","“确保山区安全”任务发布者","谁开启了“确保山区安全”"}},{q="在哪里可以找到山地巡逻队员格雷琴？",a="山地巡逻队员格雷琴驻扎在丹莫罗的卡拉诺斯镇西面，负责监视附近山坡和洞穴中存在的当地温迪戈威胁。",al={"格雷琴在哪里","山地巡逻队员格雷琴的位置","寻找山地巡逻队员格雷琴"}},{q="任务发布者为什么要寻找山地巡逻队员格雷琴？",a="任务发布者负责将情报送回铁炉堡，但被派去调查当地温迪戈活动的侦察兵没能按时报告。由于进度落后，且为了避免危险的洞穴探索，他请求一位路过的冒险者去查看山地巡逻队员格雷琴的情况。",al={"为什么要派遣冒险者","为什么白须需要帮助","为什么要查看格雷琴的情况"}},{q="什么温迪戈问题正在威胁该地区？",a="温迪戈栖息在卡拉诺斯周围的岩石山脚和黑暗洞穴中。它们咄咄逼人的存在对旅行者和当地哨所构成了直接威胁，促使铁炉堡的侦察兵密切监视它们的动向。",al={"卡拉诺斯的温迪戈威胁","温迪戈在做什么","为什么会出现温迪戈问题"}},{q="抵达后山地巡逻队员格雷琴报告了什么？",a="在镇西找到山地巡逻队员格雷琴后，她确认收到了白须的询问，并严肃地指出，附近温迪戈的整个局势已经变得非常糟糕。",al={"格雷琴说了什么","“确保山区安全”任务交付","格雷琴报告的状况"}},{q="山地巡逻队员在卡拉诺斯周围扮演什么角色？",a="山地巡逻队员是铁炉堡矮人的主要边境守卫、追踪者和侦察部队，他们勘测丹莫罗各处的偏远隘口、黑暗洞穴和雪地小径，以保护像卡拉诺斯这样的城镇。",al={"谁是山地巡逻队员","铁炉堡山地巡逻队","山地巡逻队员的职责"}}},fp="19,150,17.281.0,28.237.1,40.184.0,40.134.0,55.226.0,45.176.0,51.145.0,47.185.0"}
P.entries["quest:98323"] = {n="Secure the Mountain",s="《Secure the Mountain》是一份代表登山者格雷琴递交给卡拉诺斯森内尔·白须的侦察报告。在一次前往附近洞穴的探险遭遇灾难性后果后，格雷琴断定该洞穴已经无法挽回，并拒绝再派遣任何侦察兵进入这个到处都是敌人的死亡陷阱。这项任务突显了铁炉堡的登山者们在日益增长的威胁中保卫丹莫罗安全的持续斗争。",h="《Secure the...",kw={"洞穴","科尼利厄斯","丹莫罗","卡拉诺斯","登山者格雷琴","登山者的报告","确保山区安全","森内尔·白须"},ang={["faction:Alliance"]="确保铁炉堡周围的高海拔山口的安全，对于维护联盟在卡兹莫丹冰雪要塞中的安全通行和防御至关重要。",["race:Dwarf"]="丹莫罗是铜须矮人的祖居之地，这使得登山者格雷琴的顽强坚守成为了一项保护她的族人免受周围威胁的重要努力。"},sec={{t="一份严峻的报告",b="登山者格雷琴驻扎在丹莫罗寒冷的峰顶，肩负着确保高海拔山口安全的职责。然而，最近一次对附近洞穴的突入表明，这片荒野远未平定。在评估了局势后，格雷琴认为该洞穴已经变成了一个彻头彻尾的死亡陷阱，充斥着敌对的怪物。与其冒着牺牲更多生命的风险，她选择坚守在斜坡上的岗位，决心守住防线，同时派遣一名信使去递交她的书面评估。"},{t="深渊中的损失",b="放弃继续深入该洞穴的决定是在付出惨重代价后做出的。在这场失败的侦察行动中，科尼利厄斯不幸遇难，他的牺牲让登山者格雷琴感到沉重。在承认当前条件下无法收复该洞穴后，她下令停止所有对地下隧道的进一步探索任务。她的工作重点从进攻性清理转向了防御性封锁，拒绝再让更多的侦察兵白白牺牲在这些潜伏在雪山峭壁下的凶残生物手中。"},{t="森内尔·白须的档案",b="在繁忙的卡拉诺斯定居点，森内尔·白须追踪着侵扰矮人领地的众多危险。在收到格雷琴那份严峻的评估报告后，白须对于洞穴完全失控的消息并没有感到多少惊讶。他默默接受了丹莫罗所面临的严峻现实，将格雷琴的信件收进了他那堆积如山的实地报告中。这些情报成为了铁炉堡在更广泛地记录和管理动荡边境的过程中，又一份发人深省的资料。"}},faq={{q="登山者格雷琴是谁？",a="登山者格雷琴是一名驻扎在丹莫罗冰雪荒野中的铁炉堡哨兵。她恪尽职守，拒绝在周围领土被判定安全之前离开她的高山岗位。在一次进入附近洞穴的致命侦察任务后，她写下了一份详细描述了敌方重兵把守的正式实地报告，并将其送往卡拉诺斯。",al={"格雷琴","登山者格雷琴背景故事","格雷琴是谁"}},{q="森内尔·白须是谁？",a="森内尔·白须是一位驻扎在卡拉诺斯镇的矮人官员。他负责收集情报并协调丹莫罗各地的本地安全行动，接收来自实地登山者们的派遣报告和侦察评估。当获悉危险的敌军入侵或失陷的洞穴时，他会将这些报告编入正式档案，以评估区域威胁等级。",al={"森内尔·白须","白须 卡拉诺斯","森内尔是谁"}},{q="科尼利厄斯是谁？",a="科尼利厄斯是参与探索山上那处受灾洞穴的一名同僚或侦察兵。登山者格雷琴怀着遗憾提到了他的悲惨命运，表明他是在那次不幸的侦察行动中阵亡的。他的死直接影响了格雷琴将洞穴判定为致命死亡陷阱的决定，并禁止任何人再在里面白白送命。",al={"科尼利厄斯","科尼利厄斯是谁","科尼利厄斯发生了什么","科尼利厄斯 确保山区安全"}},{q="山洞里发生了什么？",a="当侦察兵发现隧道完全被敌对的怪物占领后，对洞穴的探索宣告失败。这次任务导致了科尼利厄斯的悲剧性丧生。在这一严峻的发现之后，登山者格雷琴宣布该地下通道已无法挽回，并断定再派人进入无异于自杀，于是决定封锁或避开该区域。",al={"洞穴里有什么","为什么洞穴是死亡陷阱","洞穴无法挽回"}},{q="为什么格雷琴拒绝离开她的岗位？",a="登山者格雷琴非常重视她保护丹莫罗的誓言，并坚定地声明在山脉本身安全之前，她绝不会放弃自己的阵地。尽管她承认附近的洞穴太过危险而无法夺回，但她依然坚守在白雪皑皑的山巅，守卫着通道并保持警惕，同时将威胁的消息传回卡拉诺斯。",al={"为什么格雷琴要留下来","格雷琴的岗位","为什么要留在山上"}},{q="森内尔·白须对格雷琴的报告有何反应？",a="森内尔·白须对得知洞穴被彻底占领的消息几乎毫不惊讶，这表明这种敌对入侵在丹莫罗已成为太过常见的麻烦。比起表现出震惊，他冷静地接受了这个坏消息，并将格雷琴的书面报告收进他那堆积如山的笔记中，细致地记录着威胁到王国的种种危险。",al={"森内尔的反应","白须对报告的反应","森内尔做什么工作"}},{q="登山者在丹莫罗扮演什么角色？",a="登山者是铁炉堡警惕的边境侦察兵和守卫，在丹莫罗险峻的雪覆盖山峰、高海拔小径和山口进行巡逻。这些坚韧的矮人驻扎在远离温暖首都的地方，监控着敌对野兽的动向，侦察洞穴，并将重要情报传回卡拉诺斯这样的本地枢纽，以保护旅行者和定居点。",al={"铁炉堡登山者","什么是登山者","矮人登山者背景故事"}}},fp="19,248,13.377.0,20.352.1,26.274.0,28.270.0,24.242.0,18.248.0,35.216.0,43.233.0,53.205.0,49.275.0"}
P.entries["quest:98326"] = {n="Frosthowl",s="Frosthowl是丹莫罗的一项任务，要求冒险者从一只偷窃的温迪戈那里找回一袋被偷的鱼。这只野兽伏击了一位当地的矮人渔夫，并逃进了灰色洞穴的深处。",h="Frosthowl是丹莫罗的一项任务，要求冒险者从一只偷窃的温迪戈那里找回一袋被偷的鱼。这只野兽伏击了一位当地的矮人渔夫，并逃进了灰色洞穴的深处。",kw={"丹莫罗","霜嚎","冰冻湖泊","灰色洞穴","冰钓","帕克斯顿","被偷的鱼","温迪戈"},ang={["faction:Alliance"]="保护烈酒和卡拉诺斯附近的冰雪小径和钓鱼点免受凶猛掠食者的侵害，是当地联盟冒险者义不容辞的责任。",["race:Dwarf"]="坚韧的矮人渔夫在丹莫罗的冰冻湖面上忍受着刺骨的严寒，这使得温迪戈的捕食性袭击成为了当地家园定居者和生计时刻面临的威胁。"},sec={{t="被盗的渔获",b="在丹莫罗冰冷的水域进行冰钓是一项艰苦而痛苦的工作。一位矮人渔夫和她的丈夫帕克斯顿在冰封的湖面上冒着刺骨的寒风待了数日，才仅仅收获了一袋鱼。当名为Frosthowl的凶猛且咆哮着的温迪戈袭击营地并抢走他们全部的渔获逃进雪原时，他们的辛苦劳作瞬间化为乌有。"},{t="灰色洞穴中的吵闹鬼",b="Frosthowl并非普通的食腐动物；这头野兽以其震耳欲聋的咆哮声而闻名，这些吼声能震碎冰层并吓跑湖中稀少的鱼群。在抢走渔夫的补给袋后，这只流着口水的生物退回到了位于东南方向的灰色洞穴的黑暗隧道深处，留下了陷入困境的渔夫们，他们迫切希望有人能去对抗这只怪物并取回被盗的物品。"}},faq={{q="霜嚎是谁？",a="霜嚎是一只潜伏在丹莫罗的吵闹且极具攻击性的温迪戈。它以咆哮和恐吓冰封的水道而闻名，最近还袭击了一位当地的矮人渔夫，并抢走了她丈夫辛苦捕获的鱼。",al={"关于霜嚎","霜嚎是什么","霜嚎温迪戈"}},{q="在哪里可以找到霜嚎？",a="霜嚎躲在灰色洞穴的深处，这是一个位于帕克斯顿捕鱼的冰冻湖泊东南方向的洞穴系统。",al={"霜嚎在哪里","霜嚎位置","温迪戈躲在哪里"}},{q="霜嚎偷走了什么？",a="霜嚎伏击了一位矮人渔夫，偷走了一整袋鱼，那是她丈夫帕克斯顿在冰冻湖面上花了几天时间才捕获的。冒险者们受托去猎杀这只野兽并找回被盗的渔获。",al={"霜嚎偷了什么","为什么要击杀霜嚎","温迪戈拿走了什么"}},{q="帕克斯顿是谁？",a="帕克斯顿是一位矮人渔夫，他在冰封的湖面上花了数天时间试图捕获一些鱼。在霜嚎偷走了他们唯一的一袋鱼之后，他的妻子委托路过的旅行者去追踪这只野兽。",al={"关于帕克斯顿","丹莫罗的帕克斯顿","渔夫帕克斯顿"}},{q="什么是灰色洞穴？",a="灰色洞穴是丹莫罗冰冻湖泊东南方一处已知的温迪戈巢穴，它是像霜嚎这样的野兽用来囤积腐肉和被盗补给的黑暗巢穴。",al={"什么是灰色洞穴","灰色洞穴温迪戈巢穴","丹莫罗的温迪戈栖息地"}},{q="这头野兽为什么叫霜嚎？",a="这只温迪戈被称为“吵闹鬼”，它那震耳欲聋的咆哮和嚎叫声在雪原上回荡，吓跑了鱼群，并让任何在冰湖上工作的人感到恐惧。",al={"霜嚎得名原因","为什么叫霜嚎","吵闹的温迪戈"}}},fp="9,138,13.252.0,33.302.0,17.204.0,29.95.0,25.168.0,14.158.0,25.147.0,33.181.0"}
P.entries["quest:98340"] = {n="巨豹之灵",s="德迪利特·星焰召你前往月光林地，继续德鲁伊训练的下一步。他指引你踏上理解自然之猫的道路。",h="德迪利特·星焰召你前往月光林地，继续德鲁伊训练的下一步。他指引你踏上理解自然之猫的道路。",kw={"熊","猫","德迪利特·星焰","德鲁伊训练","巨豹之灵","月光林地","自然","永夜港"},ang={["class:Druid"]="作为一名德鲁伊，德迪利特的教导将开启训练的下一阶段：通过猫来理解自然。"},sec={{t="月光林地的召唤",b="德迪利特·星焰在月光林地的村庄永夜港寻找你。你已经学会了前往那里的魔法，见到他后便能继续德鲁伊训练。"},{t="猫的视角",b="德迪利特欢迎你回来，并将训练转向猫，去领悟自然的另一种面貌。和熊一样，这一面的理解要靠你自己。"}},faq={{q="是谁找我？",a="德迪利特·星焰在永夜港，月光林地找你。",al={"月光林地谁在找我","德迪利特召唤","谁找德鲁伊"}},{q="德迪利特想教我什么？",a="德迪利特将指引你踏上理解猫这一自然面貌的道路。",al={"猫的训练","学习猫","接下来是什么"}},{q="我去哪里见德迪利特？",a="德迪利特在月光林地的永夜港村庄。",al={"德迪利特在哪里","见德迪利特","永夜港在哪里"}},{q="我怎么去月光林地？",a="你已经学会了前往月光林地的魔法。",al={"前往月光林地","月光林地旅行","怎么去那里"}},{q="这一步之前是什么？",a="你已经学会了前往月光林地的魔法，德迪利特会将这次学习与熊之面貌相比较。",al={"之前学了什么","熊之训练之前","德鲁伊之前的步骤"}}},fp="20,146,19.185.0,23.157.0,16.61.0,36.86.0,25.54.0,26.63.0,28.114.0"}
P.entries["quest:98341"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit是一位来自泽弗拉斯（Zephras）国度的神圣导师，以塞琳南化身（Avatar of Saeyleenan）的形象出现在月光林地。它引导年轻的申多雷（shen'dorei）德鲁伊通过他们的灵性试炼，以便他们能掌握来自遥远故乡的风生猫形态。",h="The Great Windborne Cat Spirit是一位来自泽弗拉斯（Zephras）国度的神圣导师，以塞琳南化身（Avatar of...",kw={"猫形态","猫灵","德鲁伊试炼","月光林地","塞琳南","申多雷","风生猫","泽弗拉斯"},ang={["class:Druid"]="来自泽弗拉斯的德鲁伊通过与风生猫灵沟通来掌握他们的猫科形态，完成一项为他们独特的文化传承量身定制的仪式，而非采用传统的艾泽拉斯之道。",["race:Skyborne"]="被称为申多雷的逐天者德鲁伊在故乡泽弗拉斯的灵体引导下进行修行，而非采用艾泽拉斯本土的形态。"},sec={{t="来自泽弗拉斯的访客",b="在月光林地的神圣庇护所中，一个来自遥远泽弗拉斯国度的灵体出现在双桥南侧。这个自称为塞琳南化身的风生猫灵穿梭来到艾泽拉斯，旨在引导和教导那些准备解锁猫科变形形态的年轻申多雷德鲁伊。"},{t="风生形态的本质",b="虽然所有德鲁伊最终都会寻求猫科形态的智慧，但来自泽弗拉斯的德鲁伊所传承的传统与艾泽拉斯的原住民截然不同。申多雷德鲁伊并非采用艾泽拉斯野生猫科动物的形态，而是化身为他们故乡的风生掠食者。为了确保他们能领悟其灵性本质，塞琳南会亲自监督他们在月光林地的试炼。"}},faq={{q="伟大的御风猫灵是谁？",a="风生猫灵以塞琳南化身的形象显现，这是一种来自遥远故乡泽弗拉斯的灵体。它来到月光林地是为了教导和考验那些寻求获得其猫科形态的年轻申多雷德鲁伊。",al={"风生猫灵是谁","什么是塞琳南化身","塞琳南背景故事"}},{q="在哪里可以找到塞琳南化身？",a="该灵体的化身出现在月光林地的南部区域，位于双桥正南侧。",al={"月光林地猫灵位置","塞琳南化身所在地","风生猫位置"}},{q="为什么泽弗拉斯的德鲁伊要与不同的猫灵沟通？",a="因为申多雷德鲁伊起源于泽弗拉斯，他们的猫科形态反映的是故乡的风生灵体，而非艾泽拉斯本土的大型猫科动物。该灵体会亲自监督他们的试炼，以确保他们能正确掌握其精髓。",al={"为什么猫形态看起来不同","泽弗拉斯猫形态区别","为什么不用艾泽拉斯猫灵"}},{q="风生猫的试炼包含什么？",a="塞琳南化身会让受试者进行艾泽拉斯巨猫之灵的试炼，同时亲自介入监督，确认德鲁伊能够领悟风生灵体的独特本质。",al={"猫灵给予什么试炼","泽弗拉斯猫灵试炼","如何获得风生猫形态"}},{q="申多雷指的是什么？",a="塞琳南化身将受试者称为申多雷，以此表明他们源自泽弗拉斯，并将他们的传统和灵性习俗与艾泽拉斯的原住民区分开来。",al={"谁是申多雷","申多雷德鲁伊","申多雷是什么意思"}},{q="什么是泽弗拉斯？",a="泽弗拉斯是申多雷遥远的故乡。那里的原生动植物和灵体与艾泽拉斯明显不同，这使得其德鲁伊拥有独特的变形形态。",al={"什么是泽弗拉斯","泽弗拉斯在哪里","泽弗拉斯故乡"}}},fp="30,193,22.262.0,32.302.0,38.177.0,44.87.0,58.213.0,48.192.0,30.176.0,16.170.0"}
P.entries["quest:98362"] = {n="To Thunder Bluff",s="“To Thunder Bluff” 标志着一位年轻的牛头人德鲁伊从月光林地与塞纳里奥议会的交流中凯旋归来。在赢得了巨豹之灵的青睐后，这位新学徒回到了长者高地，寻找图拉克·符文图腾，以掌握猫科变形的艺术。",h="“To Thunder Bluff” 标志着一位年轻的牛头人德鲁伊从月光林地与塞纳里奥议会的交流中凯旋归来。在赢得了巨豹之灵的青睐后，这位新学徒回到了长者高地，寻找图拉克·符文图腾，以掌握猫科变形的艺术。",kw={"猫形态","德迪利特·星焰","德鲁伊","长者高地","巨豹之灵","月光林地","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这项仪式代表着你捕食本能的解锁，让你能够像图拉克·符文图腾所教导的那样，掌握潜行和利爪的技巧。",["faction:Horde"]="虽然塞纳里奥议会保持中立，但部落的德鲁伊必须回到他们的主城，以确保他们日益增长的力量能够为保卫同胞服务。",["race:Tauren"]="这段旅程强调了牛头人与塞纳里奥传统的重新连接，将来自神圣月光林地的教诲带回了雷霆崖的长者高地。"},sec={{t="从月光林地归来",b="在月光林地的神圣树林中向德迪利特·星焰和巨豹之灵证明了自己的见识和价值后，年轻的德鲁伊必须将圣兽的祝福带回莫高雷。与这种原始力量的交流是德鲁伊训练中的一个关键里程碑，它将古老的暗夜精灵教义与牛头人自身的土灵传统联系了起来。"},{t="掌握猫形态",b="图拉克·符文图腾正在雷霆崖的长者高地之巅等待着你的归来。虽然德迪利特促成了你与圣兽本身的交流，但引导身体形态的转变还得依靠图拉克。在巨豹之灵的祝福得到认可后，这位老训练师将传授化身为敏捷、捕食性的猫形态所需的神圣知识。"}},faq={{q="这个任务在哪里开始和结束？",a="该任务由月光林地的德迪利特·星焰发布。它指引旅行者回到雷霆崖的长者高地，与图拉克·符文图腾交谈。",al={"交任务的地方","谁发布 前往雷霆崖","前往雷霆崖 任务交接"}},{q="这个任务的目的是什么？",a="它作为德鲁伊猫之试炼的最终过渡阶段。在月光林地获得巨豹之灵的祝福后，新学徒必须回到雷霆崖的导师身边，最终学会如何变身为猫形态。",al={"为什么要做 前往雷霆崖","做 前往雷霆崖 能得到什么","猫形态任务"}},{q="图拉克·符文图腾是谁？",a="图拉克·符文图腾是一位受人尊敬的牛头人德鲁伊长者，驻扎在雷霆崖的长者高地。他负责监督那些寻求与自然和谐相处并掌握变形形态的部落年轻德鲁伊的训练和入门仪式。",al={"图拉克·符文图腾背景故事","图拉克是谁"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位隶属塞纳里奥议会的暗夜精灵守护者，他在月光林地的永夜港为到访的德鲁伊提供指导。他不顾阵营间的紧张关系，在古老的卡多雷传统与牛头人修行者之间架起了教义的桥梁。",al={"德迪利特·星焰的作用","月光林地的暗夜精灵"}},{q="巨豹之灵是什么？",a="巨豹之灵是一个古老的原始实体，深受德鲁伊的崇敬，它体现了捕食本能、潜行和敏捷。每一位寻求化身为猫形态的德鲁伊都必须通过试炼来赢得它的祝福，并理解它既顽皮又致命的双重本性。",al={"巨豹之灵 背景故事","猫之灵"}},{q="联盟德鲁伊有对应的任务吗？",a="有。暗夜精灵德鲁伊在月光林地进行类似的仪式，他们返回达纳苏斯向自己的导师报告，而不是前往莫高雷那风吹过的平顶山。",al={"前往雷霆崖 的联盟版本","暗夜精灵猫形态任务交接"}}},fp="16,219,21.247.0,22.290.0,36.146.0,34.121.0,23.221.0,26.228.0,29.225.0,43.171.0"}
P.entries["quest:98372"] = {n="An Unfortunate End",s="暮色森林的阴影中躺着一名倒下的守夜人，他被一头身份不明的掠食者残忍撕咬。取回他冰冷手指间那支未点燃的火把，便能驱散周围的黑暗，揭示阴影中隐藏的一切。",h="暮色森林的阴影中躺着一名倒下的守夜人，他被一头身份不明的掠食者残忍撕咬。取回他冰冷手指间那支未点燃的火把，便能驱散周围的黑暗，揭示阴影中隐藏的一切。",kw={"不幸的结局","野兽","暮色森林","撕咬","守夜人","火把"},sec={{t="骇人的发现",b="一名倒下的守夜人成员静静躺在暮色森林昏暗的土地上，身上布满了凶猛搏斗留下的严重伤口和撕裂痕迹。这些狰狞的伤口表明，这名巡逻兵还没来得及逃脱，就遭到了一头巨兽的伏击。"},{t="黑暗中的光明",b="倒下的守卫僵硬的手指间紧握着一支未点燃的火把。将火把从他手中取走，便能得到一件对抗不断逼近的阴影的宝贵工具，照出暮色森林的浓重阴霾和其他黑暗小径中隐藏的事物。"}},faq={{q="这是谁的尸体？",a="这具倒下的尸体属于一名守夜人成员。守夜人负责巡逻暮色森林的黑暗道路和边境。这名守卫独自死在阴影之中，遭遇了暴力袭击。",al={"这具尸体是谁的","谁死在这里","死去的守夜人是谁"}},{q="是什么杀死了守卫？",a="他遭到一头大型野兽撕咬，尸体上留下了深深的伤口和狰狞的撕裂痕迹。袭击他的生物在他来得及自卫或照亮道路之前就制服了他。",al={"什么杀死了守夜人","守卫是怎么死的","是什么袭击了他"}},{q="火把为什么重要？",a="从守卫手中取下的未点燃火把可以照亮周围的阴霾，帮助游荡者揭开暮色森林及其外的土地上浓重黑暗所遮蔽的事物。",al={"火把有什么用","火把要怎么用","暮色森林火把用途"}}},fp="18,147,16.143.0,21.149.0,19.124.0,25.134.0,27.126.0"}
P.entries["quest:98386"] = {n="奥瑟尔伐木场",s="奥瑟尔伐木场是赤脊山的一个任务，由湖畔镇的工头奥斯洛提供。工头需要冒险者清除附近伐木场内危险的塔兰图拉毒蛛，以便工人们能安全地取回完成湖畔镇桥梁所需的木材。",h="奥瑟尔伐木场是赤脊山的一个任务，由湖畔镇的工头奥斯洛提供。工头需要冒险者清除附近伐木场内危险的塔兰图拉毒蛛，以便工人们能安全地取回完成湖畔镇桥梁所需的木材。",kw={"奥瑟尔伐木场","桥梁","工头奥斯洛","湖畔镇","伐木场","赤脊山","塔兰图拉毒蛛"},ang={["faction:Alliance"]="重建湖畔镇的基础设施对暴风城王国至关重要，但不断的威胁一直在分散用于桥梁建设的资源。"},sec={{t="木材瓶颈",b="工头奥斯洛为了维持湖畔镇桥梁的维修进度，可谓焦头烂额。面对敌对的黑石兽人、不断逼近的豺狼人部族以及止水湖沿岸好斗的鱼人，他的工人早已精疲力竭。最新的麻烦直接打击了他的供应链：位于东部的奥瑟尔伐木场被巨大的塔兰图拉毒蛛占领，导致该镇桥梁所需的木材供应中断。"},{t="清除虫害",b="伐木场里潜伏着毒蛛，堆积的木材完全无法使用。工头奥斯洛不敢冒险让工人们进入高等塔兰图拉毒蛛的巢穴，于是他雇佣有能力的冒险者去清除这些蛛形纲生物并摧毁它们的卵囊。虽然奥斯洛对奥瑟尔任由伐木场陷入混乱感到不满，但恢复木材供应比任何个人恩怨都更为重要。"}},faq={{q="工头奥斯洛是谁？",a="工头奥斯洛是负责修复和重建湖畔镇桥梁的石匠兼监工。他一直受到当地各种威胁的困扰，这些威胁延误了他的施工进度。",al={"工头奥斯洛是谁","赤脊山工头奥斯洛"}},{q="什么是奥瑟尔伐木场？",a="奥瑟尔伐木场位于赤脊山，湖畔镇以东。它为湖畔镇周边的建筑工程，包括桥梁工程在内，提供至关重要的木材供应。",al={"什么是奥瑟尔伐木场","奥瑟尔伐木场在哪里"}},{q="奥瑟尔是谁？",a="奥瑟尔是湖畔镇东部伐木场的所有者或经营者。据工头奥斯洛所述，奥瑟尔负责管理该场所，但目前他的伐木场已被蜘蛛侵扰。",al={"奥瑟尔是谁","奥瑟尔在哪里"}},{q="工头奥斯洛为什么要清理奥瑟尔伐木场？",a="在塔兰图拉毒蛛侵扰伐木场的情况下，工头奥斯洛无法安全地派遣工人去收集必需的木材。清除蜘蛛并摧毁它们的卵可以确保伐木场安全地恢复桥梁建设所需的木材供应。",al={"为什么要清理奥瑟尔伐木场","为什么要杀赤脊山的蜘蛛"}},{q="什么在侵扰奥瑟尔伐木场？",a="高等塔兰图拉毒蛛和蜘蛛卵囊侵扰了伐木场，这对任何被派去取回木材的工人来说都构成了严重威胁。",al={"奥瑟尔伐木场有什么蜘蛛","赤脊山蜘蛛"}},{q="工头奥斯洛要建造什么桥？",a="工头奥斯洛正在努力重建湖畔镇的桥梁，但他的进度屡屡被敌对的兽人、豺狼人、鱼人以及当地害虫造成的资源短缺所拖延。",al={"赤脊山的桥","湖畔镇大桥"}}},fp="13,163,22.272.0,24.353.0,21.131.0,22.156.0,14.133.0,50.191.0,32.111.0,45.153.0"}
P.entries["quest:98387"] = {n="Blackrock Blockade",s="“黑石封锁”是湖畔镇的治安官马瑞斯发布的一项联盟军事任务。为了应对止水湖东岸不断逼近的黑石兽人，镇卫兵旨在切断入侵者的补给并缴获他们的武器。",h="“黑石封锁”是湖畔镇的治安官马瑞斯发布的一项联盟军事任务。为了应对止水湖东岸不断逼近的黑石兽人，镇卫兵旨在切断入侵者的补给并缴获他们的武器。",kw={"破斧","黑石封锁","黑石氏族","湖畔镇","治安官马瑞斯","赤脊山","石堡要塞"},ang={["class:Warrior"]="在与粗犷的黑石兽人进行近身遭遇战时，剥夺敌人的重型切肉刀和补给是边境作战的基本原则。",["faction:Alliance"]="从黑石先锋队缴获的每一件武器，都能为湖畔镇争取到宝贵的时间，毕竟这里必须在没有暴风城大量援助的情况下抵御敌军的进攻。"},sec={{t="消耗战",b="尽管黑石氏族已经大举入侵了赤脊山，但他们鲁莽地推进到联盟领土的行为已经让他们的后勤陷入了崩溃的边缘。由于被切断了常规的补给线，他们的先锋作战部队被迫在这片严酷的赤脊山丘陵中寻找生存资源。治安官马瑞斯深知，即使是凶猛的兽人，没有稳定的给养和钢铁武器也无法维持长久的战役。"},{t="切断前沿营地",b="位于石堡要塞南侧的兽人营地是黑石氏族进攻的矛头所在。通过突袭这些营地、搜刮物资储备并夺走他们窃取的武器，联盟守军希望能削弱先遣队的战斗力并摧毁他们的士气。"}},faq={{q="“黑石封锁”的目标是什么？",a="该任务旨在破坏石堡要塞以南黑石氏族的前沿营地。通过突袭他们的补给线、夺取食物并回收武器，湖畔镇守卫希望能断绝兽人的供给，以此减缓他们对赤脊山的攻势。",al={"什么是黑石封锁","黑石封锁目标","封锁目的"}},{q="谁发布了这项任务？",a="治安官马瑞斯，湖畔镇镇守卫的指挥官，负责监督赤脊山的防御并指挥破坏黑石氏族补给的行动。",al={"谁发布黑石封锁","任务发布者","治安官马瑞斯任务"}},{q="这些黑石营地位于何处？",a="目标战营位于赤脊山脉的东部丘陵，就在石堡要塞以南，与湖畔镇隔河相望。",al={"兽人在哪里","黑石营地位置","石堡营地在哪里"}},{q="为什么湖畔镇选择消耗战，而不是直接进攻？",a="湖畔镇守卫人手不足，且几乎没有从暴风城得到增援。这是一场消耗战：黑石兽人鲁莽地深入联盟领土，导致他们陷入了脆弱的境地，补给断绝，只能依赖周围的山区来获取资源，而大军是无法在饥肠辘辘的情况下作战的。",al={"为何饿死兽人","为何不直接攻击石堡","湖畔镇战略"}},{q="哪些武器正从兽人手中没收？",a="治安官马瑞斯希望缴获囤积在黑石营地中的武器和补给，让兽人失去他们的战争工具。",al={"需要什么物品","什么斧头","战损的斧头背景"}},{q="这些兽人是萨尔部落的成员吗？",a="不是。赤脊山的这些黑石兽人属于盘踞在黑石山的叛乱势力——黑石氏族（黑铁氏族/黑石氏族）。他们拒绝萨尔的领导，并且对联盟和新部落都抱有强烈的敌意。",al={"这些是部落兽人吗","黑石是部落吗","萨尔黑石氏族"}}},fp="18,151,18.247.0,26.192.0,43.183.0,27.120.0,46.123.0,67.211.0,49.137.0,46.188.0"}
P.entries["quest:98389"] = {n="A Light in the Darkness",s="这项任务由丧钟镇的Aramis Hammerhand提供，要求被遗忘者冒险者解救困在蛛网洞穴中新复活的亡灵。它突显了那些使用圣光的亡灵与深深不信任他们的民众之间微妙的关系。通过援助他们陨落的同胞，这些圣光修行者希望向希尔瓦娜斯和被遗忘者的大义证明他们的忠诚。",h="这项任务由丧钟镇的Aramis...",kw={"阿拉米斯·锤手","丧钟镇","执行官阿伦","被遗忘者","圣光","蛛网洞穴","提瑞斯法林地","被网住的受害者"},ang={["class:Priest"]="对于引导圣光能量的被遗忘者来说，这项任务说明了在残留的凡人信仰与严酷的亡灵现实之间行走的微妙平衡。",["race:Undead"]="这项任务展示了被遗忘者复杂的内心挣扎，展示了个人如何克服自身刚复活的族群中的偏见。"},sec={{t="摇摇欲坠的信仰",b="圣光对亡灵来说是众所周知的痛苦与危险，然而一些被遗忘者保留了他们生前所使用的神圣魔法的联系。在丧钟镇，像Aramis Hammerhand这样的人物致力于证明他们的信仰并没有让他们背离自己的人民。为了消除人们对圣光修行者会把其他亡灵视为怪物而反戈一击的猜疑，他们积极利用自己的能力和同情心来守护同胞。"},{t="蛛网洞穴",b="在丧钟镇西北方坐落着蛛网洞穴，这是一个阴暗潮湿、爬满凶猛蜘蛛的洞穴。刚刚复活的亡灵，由于苏醒后的迷茫和缺乏自卫的智力，经常误入洞穴，最终被困在粘稠的蛛网中。解救这些不幸的被遗忘者具有双重目的：为黑暗女王挽救新兵，并向执行官阿伦这样的领袖证明，圣光修行者是被遗忘者的忠实仆人。"}},faq={{q="谁给予了任务“黑暗中的圣光”？",a="该任务由驻扎在提瑞斯法林地丧钟镇的圣光修行者阿拉米斯·锤手给予。",al={"任务给予者","谁开启黑暗中的圣光","阿拉米斯·锤手任务"}},{q="蛛网洞穴位于哪里？",a="蛛网洞穴位于提瑞斯法林地的山丘中，丧钟镇的西北方。",al={"蛛网洞穴位置","被蛛网困住的受害者在哪","洞穴在哪"}},{q="为什么被遗忘者不信任圣光的使用者？",a="圣光对亡灵之躯有极大的灼烧感和危险。许多被遗忘者担心任何使用圣光力量的人会将他们视为应当根除的畸形怪物，而不是应当接纳的同胞。",al={"为什么惧怕圣光","为什么被遗忘者讨厌圣骑士","被遗忘者对圣光的恐惧"}},{q="被困在蛛网里的受害者是谁？",a="茧里的受害者是刚刚苏醒、在找到方向前误闯蜘蛛洞穴的被遗忘者冒险者。",al={"谁被网住了","蛛网里有什么","被困的受害者"}},{q="执行官阿伦是谁，为什么阿拉米斯想要打动他？",a="执行官阿伦负责监督丧钟镇的军事和民事秩序。对于希望顺利融入被遗忘者军队的圣光使用者来说，获得他的信任至关重要。",al={"谁是执行官阿伦","为什么阿伦很重要"}},{q="亡灵真的可以使用圣光吗？",a="是的，通过惊人的意志力和虔诚，一些亡灵保留了他们与圣光的联系，尽管引导这种力量会带来巨大的不适，且他们自身的社会也以怀疑的眼光审视他们。",al={"被遗忘者能用圣光吗","亡灵圣光背景故事"}}},fp="23,192,18.305.0,18.343.0,44.90.0,36.80.0,51.119.0,40.110.0,63.142.0,43.155.0"}
P.entries["quest:98391"] = {n="艾露恩姐妹会",s="艾露恩姐妹会是一个入门任务，引导冒险者前往达纳苏斯会见艾奎恩妮。作为暗夜精灵社会主要的精神权威，艾露恩姐妹会需要外界迅速提供援助，以应对领地内日益严峻的挑战。",h="艾露恩姐妹会是一个入门任务，引导冒险者前往达纳苏斯会见艾奎恩妮。作为暗夜精灵社会主要的精神权威，艾露恩姐妹会需要外界迅速提供援助，以应对领地内日益严峻的挑战。",kw={"艾奎恩妮","达纳苏斯","艾露恩","女祭司","艾露恩姐妹会","泰达希尔"},ang={["class:Priest"]="卡多雷文化中的祭司身份等同于对艾露恩的虔诚，而回应艾奎恩妮则直接与神殿的崇高传统相连。",["faction:Alliance"]="达纳苏斯作为卡利姆多联盟的重要首都，协助艾露恩姐妹会能确保暗夜精灵精神与公民治理的稳定。",["race:NightElf"]="艾露恩姐妹会是暗夜精灵社会与领导层的精神核心，对于任何星之子而言，回应她们的召唤是一项神圣的职责。"},sec={{t="首都的召唤",b="“艾露恩姐妹会”是一份召唤令，指引冒险者前往暗夜精灵的首都达纳苏斯寻找艾奎恩妮。作为艾露恩信徒的代表，女祭司们经常会向可靠的勇士发出呼唤，请他们协助处理影响族人和圣地的紧急事务。"},{t="向艾奎恩妮报到",b="当你抵达达纳苏斯并找到艾奎恩妮后，她会为你如此迅速地赶到而深感欣慰。她的欢迎意味着你正式开始为艾露恩姐妹会服务，也表明女祭司们正面临日益繁重的需求，需要来自她们隐修圈之外的可靠帮手。"}},faq={{q="艾奎恩妮是谁？",a="艾奎恩妮是服务于达纳苏斯城内艾露恩姐妹会的一名特使和女祭司。她负责接待那些前来协助教团处理暗夜精灵所面临紧急事务的旅者。",al={"艾奎恩妮是谁","艾奎恩妮 达纳苏斯","艾奎恩妮在哪里"}},{q="什么是艾露恩姐妹会？",a="艾露恩姐妹会是一个古老的暗夜精灵女祭司组织，她们致力于侍奉月之女神艾露恩。作为卡多雷文化中的精神向导、治疗者和领袖，她们负责监督族人的精神福祉与防卫工作。",al={"什么是艾露恩姐妹会","艾露恩姐妹会成员","暗夜精灵女祭司"}},{q="我需要去哪里完成这个任务？",a="你必须前往泰达希尔之上的暗夜精灵伟大首都达纳苏斯。艾奎恩妮会在城中等你，为你传达代表艾露恩姐妹会的简报。",al={"艾露恩姐妹会任务交付","艾露恩姐妹会任务地点","艾露恩姐妹会去哪接"}},{q="为什么艾露恩姐妹会需要援助？",a="艾奎恩妮指出，艾露恩姐妹会需要迅速的外界援助，以应对达纳苏斯及周边暗夜精灵领地所面临的紧迫麻烦。与她交谈将解锁更多代表她们执行的任务。",al={"为什么艾露恩姐妹会需要帮助","艾露恩姐妹会困境","艾露恩姐妹会需要什么援助"}},{q="部落角色可以接受这个任务吗？",a="不能。艾露恩姐妹会是暗夜精灵领导层的核心，且完全与联盟保持一致。达纳苏斯是联盟首都，因此该任务仅限联盟冒险者接取。",al={"部落能接这个任务吗","部落能否完成艾露恩姐妹会"}},{q="谁领导着艾露恩姐妹会？",a="泰兰德·语风大祭司是艾露恩姐妹会的精神领袖，也是卡多雷民族的最高统帅，她在达纳苏斯的月神殿指引着她的姐妹们。",al={"谁领导艾露恩姐妹会","艾露恩姐妹会领袖","泰兰德 艾露恩姐妹会"}}},fp="23,152,21.169.0,27.161.0,22.167.0,32.217.0,45.122.0,36.168.0,42.175.0,34.154.0"}
P.entries["quest:98392"] = {n="Darkness in the Glade",s="Darkness in the Glade是由哨兵阿瑞尼亚·碎云领导的一项调查，旨在调查从神谕林地的鸟身人身上收集到的受污染的皮带。从鸟身人女族长身上找回的护身符证实，恶魔般的魔苔腐蚀已经在泰达希尔的枝干中扎根。",h="Darkness in the Glade是由哨兵阿瑞尼亚·碎云领导的一项调查，旨在调查从神谕林地的鸟身人身上收集到的受污染的皮带。从鸟身人女族长身上找回的护身符证实，恶魔般的魔苔腐蚀已经在泰达希尔的枝干中扎根。",kw={"阿瑞尼亚·碎云","阿莉莎","林间空地的黑暗","魔苔","盖德雷斯","鸟身人","恨啸","神谕林地","泰达希尔"},ang={["class:Druid"]="魔苔污染野生动物和皮革纤维的迹象表明，一种非自然的腐蚀正在影响世界之树的自然平衡。",["faction:Alliance"]="哨兵碎云代表了达纳苏斯的军事警惕，致力于识别威胁联盟领土的恶魔污染。",["race:NightElf"]="邪能腐蚀通过神谕林地等神圣枝干的蔓延，直接打击了卡多雷培育和保护泰达希尔的努力。"},sec={{t="受污染的纤维",b="在神谕林地宁静的树冠下，哨兵阿瑞尼亚·碎云注意到当地的鸟身人族群有些不对劲。从这些生物身上回收的皮带显示出一种直接编织在材料中的非自然污秽。碎云怀疑这不是普通的野兽侵略，而是恶魔入侵，因此在向达纳苏斯发出警报之前，她需要确凿的证据。"},{t="确认腐蚀",b="碎云指挥勇士们前往西部的巢穴，击败了该族群的女族长：Hatescreech、Windmistress Gaedress和Witchmother Arysa。每一位领袖都携带一枚带有其力量明显痕迹的护身符。在检查这些石头时，哨兵发现宝石中包裹着邪恶的绿色旋涡，这证实了魔苔正在积极地扭曲鸟身人，并渗入神圣的枝干中。"}},faq={{q="林地中的黑暗是什么？",a="林地中的黑暗是由哨兵阿瑞尼亚·碎云在神谕林地指挥的一项任务。在注意到鸟身人皮带中存在非自然的污秽后，她派遣冒险者从鸟身人领袖那里找回护身符，以核实这种折磨的来源。",al={"林地中的黑暗是什么","林地中的黑暗任务"}},{q="谁提供了这个任务？",a="哨兵阿瑞尼亚·碎云提供了这项任务。她驻守在神谕林地，守护着泰达希尔的枝干，并调查居住在那里的鸟身人之间出现的异常骚动。",al={"谁发布了林地中的黑暗","神谕林地任务发布者"}},{q="为什么阿瑞尼亚想要鸟身人领袖身上的护身符？",a="哨兵碎云在从普通鸟身人身上获取的皮带中发现了受污染的纤维，因此需要进一步的证据。她怀疑鸟身人领袖所携带的珠宝揭示了这种蔓延的腐蚀的真实性质和起源。",al={"为什么要击杀鸟身人领袖","为什么要获取护身符","鸟身人护身符的原因"}},{q="哪些鸟身人领袖持有护身符？",a="这些护身符属于筑巢于西部的三位杰出领袖：仇啸、风之女王盖德瑞斯和巫母阿瑞莎。",al={"哪些鸟身人持有护身符","神谕林地的鸟身人领袖"}},{q="是什么导致了林地中的腐蚀？",a="这种腐蚀源于魔苔。当阿瑞尼亚检查找回的护身符时，她识别出宝石中邪恶的绿色旋涡，确认魔苔正在污染该地区。",al={"是什么在腐蚀鸟身人","绿色旋涡是什么","林地黑暗的起源"}},{q="这种腐蚀是否出现在其他地方？",a="是的，哨兵碎云指出，有报道称魔苔正在使环境变得对暗夜精灵不利，这种情况也出现在幽影谷以及世界之树的其他枝干上。",al={"其他地方的魔苔","幽影谷是否受到腐蚀"}}},fp="21,142,14.262.0,18.295.1,30.187.0,21.158.0,52.161.0,37.112.0,44.147.0,43.136.0"}
P.entries["quest:98393"] = {n="The Great Cat Spirit",s="巨豹之灵是一项神圣的德鲁伊任务，召唤修行者前往月光林地的永夜港，去见德迪利特·星焰。在已经掌握了熊的形态之后，德鲁伊们受到召唤，要在塞纳留斯大人的祝福下，开始他们探索荒野中猫之视角的旅程。",h="巨豹之灵是一项神圣的德鲁伊任务，召唤修行者前往月光林地的永夜港，去见德迪利特·星焰。在已经掌握了熊的形态之后，德鲁伊们受到召唤，要在塞纳留斯大人的祝福下，开始他们探索荒野中猫之视角的旅程。",kw={"猫之形态","塞纳留斯","德迪利特·星焰","德鲁伊训练","月光林地","永夜港","巨豹之灵"},ang={["class:Druid"]="这次召唤标志着德鲁伊在熊之外扩展对荒野形态掌握能力的重要试炼。",["race:NightElf"]="月光林地是卡多雷德鲁伊回应塞纳留斯所传授的古老教诲的祖地。",["race:Tauren"]="牛头人德鲁伊在塞纳里奥议会的共同指导下，与他们的暗夜精灵同胞一同自由前往永夜港。"},sec={{t="月光林地的召唤",b="在证明了自己已经掌握了持久的熊之形态后，心怀抱负的德鲁伊们发现自己再次受到了召唤，前往神圣的月光林地。德迪利特·星焰长老向这片土地发出了呼唤，邀请弟子们来到宁静的避风港——永夜港，开始他们与自然融合的下一阶段。德鲁伊们施展独特的精神魔法跨越遥远的距离，聚集在塞纳里奥智慧那宁静的核心之地。"},{t="猫之视角",b="当你抵达永夜港后，德迪利特·星焰会向塞纳留斯大人祈祷，在欢迎这位日益成长的弟子时，召唤出一道微弱的力量光环。他揭示了拥抱猫之视角的时刻已经到来，这是一种荒野中富有掠食性和敏捷性的形态。正如之前的试炼一样，德迪利特将开启理解之路，但具体如何去体现并传承这种猫之精神，则完全取决于修行者自己。"}},faq={{q="是谁在巨豹之灵中召唤你？",a="你的德鲁伊训练师代表德迪利特·星焰召唤你，他是一位驻扎在月光林地隐秘避风港——永夜港的长老导师。",al={"谁给予 巨豹之灵 任务","德迪利特·星焰召唤"}},{q="德迪利特·星焰在哪里？",a="德迪利特·星焰居住在月光林地的中心定居点永夜港，可以通过德鲁伊的传送魔法到达。",al={"德迪利特·星焰在哪里","德迪利特·星焰位置"}},{q="面见德迪利特·星焰的目的是什么？",a="德迪利特准备引导你与自然的猫之形态进行沟通并加以理解，在你学习了熊之道后，继续你的精神进阶。",al={"德迪利特教授什么","猫形态训练任务"}},{q="为什么德迪利特要祈求塞纳留斯大人？",a="德迪利特在迎接你时祈求塞纳留斯大人，以此向这位半神，也是最初教导凡人自然与变形秘密的德鲁伊教派守护者表达敬意。",al={"为何提到塞纳留斯大人","塞纳留斯提及德迪利特"}},{q="德鲁伊如何为这项召唤前往月光林地？",a="每当导师召唤时，德鲁伊们会利用他们与自然沟通的天生精神能力，直接传送至月光林地。",al={"如何前往月光林地","德鲁伊传送至月光林地"}},{q="这种形态与熊之形态有何关联？",a="德鲁伊教义通过不同的视角来接触自然。新手首先要掌握熊那持久的力量，然后再进阶到猫那敏捷的掠食者心态。",al={"猫形态与熊形态背景故事","先学熊形态"}}},fp="20,187,24.264.0,26.323.0,42.120.0,38.109.0,50.116.0,41.137.0,51.93.0,47.162.0"}
P.entries["quest:98394"] = {n="巨豹之灵",s="月光林地南部有一位睿智的灵体，教德鲁伊了解猫的本性。它的智慧指引着寻求猎豹形态的人。",h="月光林地南部有一位睿智的灵体，教德鲁伊了解猫的本性。它的智慧指引着寻求猎豹形态的人。",kw={"猫的本性","豹灵","德鲁伊","猎豹形态","巨豹之灵","月光林地"},ang={["class:Druid"]="作为一名寻求猎豹形态的德鲁伊，你来到月光林地拜访巨豹之灵，求取有关猫的智慧。"},sec={{t="月光林地的教诲",b="巨豹之灵在月光林地南部的一座山丘上等待，俯瞰着桥梁。寻求猎豹形态的德鲁伊会来向它请教。你来到这里，是为了学习它对猫之本性的教诲。"}},faq={{q="巨豹之灵在哪里？",a="巨豹之灵居住在月光林地南部的一座山丘上，俯瞰着桥梁。",al={"豹灵位置","哪里能找到豹灵"}},{q="巨豹之灵教什么？",a="巨豹之灵教德鲁伊了解猫的本性和猎豹形态。",al={"豹灵教什么","学习猎豹形态"}},{q="德鲁伊为何寻求巨豹之灵？",a="寻求猎豹形态的德鲁伊会来向巨豹之灵求取智慧和指引。",al={"为何拜访豹灵","德鲁伊豹灵"}},{q="巨豹之灵是谁？",a="巨豹之灵是月光林地南部一位睿智而狡黠的存在，指导寻求猎豹形态的德鲁伊。",al={"巨豹之灵是谁","豹灵"}}},fp="20,127,21.204.0,30.85.0,37.85.0,40.85.0,28.111.0"}
P.entries["quest:98397"] = {n="To Darnassus",s="To Darnassus 是暗夜精灵德鲁伊与巨豹之灵沟通之旅的终点。在月光林地向德迪利特·星焰证明了自己之后，你将被送回塞纳里奥区，学习掌握变身为猎豹形态的技艺。",h="To Darnassus 是暗夜精灵德鲁伊与巨豹之灵沟通之旅的终点。在月光林地向德迪利特·星焰证明了自己之后，你将被送回塞纳里奥区，学习掌握变身为猎豹形态的技艺。",kw={"猎豹形态","塞纳里奥区","德迪利特·星焰","巨豹之灵","玛斯雷·驭熊者","月光林地","泰达希尔","前往达纳苏斯"},ang={["class:Druid"]="这个任务标志着你开始在阴影中狩猎，使你能够通过猎豹形态直接引导巨豹之灵的力量。",["faction:Alliance"]="联盟德鲁伊从月光林地的中立领土返回达纳苏斯，加强了他们家园的魔法防御。",["race:NightElf"]="返回达纳苏斯是对世界之树泰达希尔下由塞纳里奥议会所守护的暗夜精灵传统的致敬。"},sec={{t="返回塞纳里奥区",b="在月光林地接受德迪利特·星焰的指引并与巨豹之灵沟通后，有抱负的暗夜精灵德鲁伊必须回到泰达希尔。星焰承认你已经证明了自己是一名合格的学生，并指引你回到你的首席导师玛斯雷·驭熊者身边，他正在达纳苏斯的塞纳里奥区树荫下等你。"},{t="猎豹的本性",b="抵达达纳苏斯后，玛斯雷·驭熊者承认你已经领悟了巨豹之灵的智慧。在他看来，每一代德鲁伊都要面对由这个古老实体所设定的试炼，它既顽皮又致命。随着你与它的连接建立，你的精神也已准备就绪，玛斯雷将传授你变身为优雅猎豹形态所需的最终仪式。"}},faq={{q="这个任务的目的是什么？",a="这个任务结束了你与巨豹之灵的试炼。在月光林地完成德迪利特·星焰交给你的任务后，他会指引你回到达纳苏斯的玛斯雷·驭熊者身边，让他教你如何变身为猎豹形态。",al={"为什么要做这个任务","前往达纳苏斯 目的","猎豹形态任务"}},{q="是谁让你回到达纳苏斯的？",a="德迪利特·星焰是一位居住在月光林地圣地永夜港的资深德鲁伊，在你获得巨豹之灵的祝福后，他会交给你这个任务。",al={"谁开始这个任务","任务给予者"}},{q="我在哪里可以找到玛斯雷·驭熊者？",a="玛斯雷·驭熊者驻扎在塞纳里奥区，这是位于泰达希尔上达纳苏斯西北区的德鲁伊圣所。",al={"玛斯雷位置","驭熊者在哪里"}},{q="巨豹之灵有什么意义？",a="巨豹之灵是一种古老而野性的自然之灵，代表着敏捷而致命的掠食者。德鲁伊必须在获准引导其形态之前，赢得它的青睐，并理解它那顽皮与致命并存的双重本性。",al={"猎豹之灵传说","什么是 巨豹之灵"}},{q="所有德鲁伊完成的试炼都是一样的吗？",a="根据玛斯雷·驭熊者的说法，虽然所有德鲁伊都必须通过巨豹之灵授予的试炼才能掌握其形态，但每一代试炼的具体内容各不相同。",al={"德鲁伊试炼是否相同","世代试炼"}},{q="非暗夜精灵可以接这个任务吗？",a="这个特定的任务是为返回达纳苏斯的联盟暗夜精灵德鲁伊准备的。牛头人德鲁伊遵循他们自己的道路，在访问月光林地后会向他们自己的训练师汇报。",al={"这是联盟专属吗","牛头人能做吗"}}},fp="12,204,21.301.0,21.285.0,34.200.0,32.138.0,39.103.0,49.202.0,44.144.0,36.174.0"}
P.entries["quest:98398"] = {n="The Oracle Tree",s="神谕之树是一个任务，在该任务中，一名有前途的冒险者被指引去与一棵有感知力的古树进行交流。通过寻找这棵树刻意脱落的一块树皮，旅行者们可以收到它令人舒心的心灵感应信息，并为即将到来的更艰巨的任务做好准备。",h="神谕之树是一个任务，在该任务中，一名有前途的冒险者被指引去与一棵有感知力的古树进行交流。通过寻找这棵树刻意脱落的一块树皮，旅行者们可以收到它令人舒心的心灵感应信息，并为即将到来的更艰巨的任务做好准备。",kw={"神谕之树","神谕之树树皮","有感知力的树","脱落的树皮","心灵感应"},ang={["class:Druid"]="德鲁伊天生就能与有感知力的植物生命和古树的声音产生共鸣，使得与神谕之树的交流成为他们对自然崇敬的一种延伸。"},sec={{t="召唤更伟大的使命",b="神谕之树是一棵睿智且有感知力的树，它守护着周围的环境，并指引那些证明了自己的勇气的旅行者。当它在世界上需要代理人时，它会特意在附近脱落一片树皮。注意到这一点的人会被召唤上前，这标志着他们初步的任务已经完成，更伟大的责任正在等待他们。"},{t="通过树皮进行心灵沟通",b="神谕之树不会用普通的物理声音说话。相反，检查那片落下的树皮可以让这棵树直接触及寻求者的心灵。它的存在平静而舒缓，像微风拂过树冠一样拂过听者的心灵，无需说出一个字就能传达思想和愿望。"}},faq={{q="什么是神谕之树？",a="神谕之树是一棵古老且有感知力的树，能够与附近的人进行心灵感应交流。当它希望传达信息或分配任务时，它会脱落一块树皮来吸引值得信赖的冒险者的注意。",al={"什么是神谕之树","神谕之树背景故事"}},{q="神谕之树如何交流？",a="神谕之树不是用可听见的声音说话，而是通过心灵感应来传达它的思想。任何检查掉落树皮的人都会听到一个平静、舒缓的声音进入他们的脑海，就像微风拂过树叶一样。",al={"神谕之树如何说话","神谕之树交流方式"}},{q="为什么要寻找神谕之树的树皮？",a="当树有需要处理的目标或职责时，它会专门脱落一片树皮。检查树皮是接收这棵树心灵感应指导的焦点。",al={"为什么要寻找树皮","掉落树皮的目的"}},{q="是谁指引你前往神谕之树？",a="一位一直在观察你成就的当地监督者或看护人，他们意识到未来有更伟大的职责等着你。注意到刚脱落的树皮，他们会指引你接近这棵树以接受它的指导。",al={"谁指引你去神谕之树","神谕之树任务发布者"}},{q="任务“神谕之树”的目的是什么？",a="该任务开启了一名有成就的旅行者与这棵树本身之间的接触。通过寻找树皮，你开启心灵去倾听树的信息，并了解它需要完成什么更伟大的任务。",al={"神谕之树任务目标","神谕之树想要什么"}},{q="在哪里可以找到神谕之树的树皮？",a="脱落的树皮位于神谕之树附近的地面上，等待着感知力足够敏锐、能听到其信息的人去检查。",al={"在哪里找到神谕树皮","树皮位置"}}},fp="15,181,24.291.0,26.219.0,24.202.0,37.174.0,47.141.0,35.166.0,49.157.0,36.112.0"}
P.entries["quest:984"] = {n="熊怪的威胁",s="“威胁有多大？”是一个由奥伯丁的特伦希斯给予联盟的任务。在目睹了熊怪的疯狂在泰达希尔蔓延后，这位暗夜精灵德鲁伊派遣斥候调查黑海岸当地的熊怪定居点，以确认这种同样的黑暗腐蚀是否已经跨越了海洋。",h="“威胁有多大？”是一个由奥伯丁的特伦希斯给予联盟的任务。在目睹了熊怪的疯狂在泰达希尔蔓延后，这位暗夜精灵德鲁伊派遣斥候调查黑海岸当地的熊怪定居点，以确认这种同样的黑暗腐蚀是否已经跨越了海洋。",kw={"亚米萨兰","奥伯丁","腐蚀","黑海岸","熊怪","泰达希尔","特伦希斯","威胁"},ang={["class:Druid"]="熊怪与自然和古老的荒野之灵有着深刻的联系，这使得他们突然陷入腐蚀成为致力于修复卡利姆多平衡的德鲁伊们极度担忧的问题。",["faction:Alliance"]="作为联盟进入卡利姆多北部大陆的主要门户，保护奥伯丁免受旷野威胁对于地区安全和后勤保障至关重要。",["race:NightElf"]="对于卡多雷来说，目睹像熊怪这样古老的盟友在第三次大战争后不久就屈服于非理性的黑暗，既是一场痛苦的悲剧，也是对神圣土地的迫在眉睫的危险。"},sec={{t="跨海阴影",b="卡利姆多北部的暗夜精灵长期以来一直与当地的熊怪部落保持着友好或和平的关系。然而，第三次大战争之后，某种奇怪的腐蚀开始侵蚀泰达希尔熊怪的心智，导致他们对曾经的盟友进行暴力绑架和野蛮攻击。驻扎在奥伯丁的德鲁伊特伦希斯担心，这种险恶的折磨并非仅限于世界之树，而是正在黑海岸迷雾笼罩的海岸线上，在大陆部落中积极蔓延。"},{t="风暴前夕",b="对亚米萨兰遗迹附近一个熊怪营地的侦察证实了特伦希斯最糟糕的怀疑。那里的熊怪表现出反复无常、充满敌意的侵略性，带有与困扰北方地区相同的腐蚀迹象。他们距离奥伯丁非常近，这使得他们从一个和平的旷野邻居，变成了一个威胁到联盟定居点的紧急防御隐患。"}},faq={{q="特伦希斯是谁？",a="特伦希斯是一位驻扎在沿海避风港奥伯丁的暗夜精灵德鲁伊。由于泰达希尔各地不断传来暗夜精灵遭到疯狂熊怪袭击和俘虏的消息，他致力于监控并压制整个黑海岸出现的威胁。",al={"特伦希斯 任务给予者","谁给予 威胁有多大","特伦希斯 奥伯丁"}},{q="为什么黑海岸的熊怪变得充满敌意？",a="特伦希斯已经在黑海岸看到了腐蚀的迹象，并怀疑熊怪可能受到了影响，就像泰达希尔的一些熊怪一样。他要求对这些营地进行调查，因为他还没有掌握到广泛传播的证据。",al={"为什么熊怪发狂","黑海岸受腐蚀的熊怪","熊怪腐蚀"}},{q="受腐蚀的熊怪营地在哪里？",a="营地位于黑海岸中部内陆，就在古老的上层精灵遗迹亚米萨兰的北面，奥伯丁的东南方。",al={"营地位置","熊怪营地在哪里","威胁有多大 位置"}},{q="这与泰达希尔发生的事件有什么联系？",a="在泰达希尔，几只受腐蚀的熊怪绑架并伤害了暗夜精灵哨兵和平民。特伦希斯在寻求确认黑海岸大陆是否面临同样的危机时，提到了那些最近的救援行动。",al={"泰达希尔的联系","泰达希尔熊怪","为什么特伦希斯提到泰达希尔"}},{q="向特伦希斯汇报后会发生什么？",a="向奥伯丁的特伦希斯报告任何腐蚀迹象。你返回后，他会揭晓对调查结果的回应。",al={"后续任务","威胁有多大的后续","任务延续"}},{q="为什么暗夜精灵如此担心奥伯丁附近的熊怪营地？",a="奥伯丁是联盟在大陆上的主要港口和补给生命线。如果深陷腐蚀、充满敌意的部落驻扎在触手可及的地方，贸易道路、侦察小队和城镇本身都将变得极易受到突然袭击。",al={"对奥伯丁的威胁","为什么关心熊怪"}}},fp="17,234,22.337.0,17.259.1,17.193.0,50.221.0,42.132.0,45.202.0,47.90.0,68.180.0"}
P.entries["quest:98403"] = {n="扭曲的仇恨",s="扭曲的仇恨是泰达希尔的一个任务，旨在揭露梅伦纳斯领主背后的操纵者。冒险者们前往多兰纳尔西北方的大断崖，去直面邪恶的塞索尔，并在他那邪恶的阴谋蔓延至树冠之前消灭他那些被腐化的蜘蛛。",h="扭曲的仇恨是泰达希尔的一个任务，旨在揭露梅伦纳斯领主背后的操纵者。冒险者们前往多兰纳尔西北方的大断崖，去直面邪恶的塞索尔，并在他那邪恶的阴谋蔓延至树冠之前消灭他那些被腐化的蜘蛛。",kw={"被玷污的蛛木蜘蛛","大断崖","多兰纳尔","梅伦纳斯领主","成熟的魔苔","萨特","塔隆凯·捷根","泰达希尔","扭曲的仇恨","邪恶的塞索尔"},ang={["class:Druid"]="泰达希尔的自然蛛形纲生物被扭曲成污秽的巢群，这破坏了自然平衡，需要塞纳里奥保卫者们将其净化。",["faction:Alliance"]="协助塔隆凯·捷根可以保护多兰纳尔定居点，使其免受萨特阴谋在联盟位于卡利姆多的主要避难所中的蔓延。",["race:NightElf"]="泰达希尔是卡多雷复兴的新生心脏，大断崖本土野生动物中滋生的恶魔腐化，是对你们族人的直接侮辱与威胁。"},sec={{t="阴影中的操纵者",b="梅伦纳斯领主并非孤身一人行事的发现，揭示了泰达希尔荒野下涌动着更黑暗的暗流。在梅伦纳斯的身后站着邪恶的塞索尔，这位盘踞在此的萨特在森林的阴影中操纵着一切，企图破坏世界之树宁静的枝叶。"},{t="大断崖的污秽巢群",b="邪恶的塞索尔在多兰纳尔西北方一处名为大断崖的隐秘飞地中安身，并将注意力转向了泰达希尔本土的蛛形纲生物。通过将当地的蛛木蜘蛛扭曲成污秽的野兽，这名萨特试图将它们的毒液武器化，用于险恶的恶魔阴谋。塔隆凯·捷根派遣冒险者去猎杀这些巢群，并在腐化进一步蔓延之前夺取塞索尔手中的成熟的魔苔。"}},faq={{q="谁是邪恶的塞索尔？",a="邪恶的塞索尔是一名邪恶的萨特，他在泰达希尔策划着腐化。他指挥着梅伦纳斯领主，并将巢穴设在大断崖，通过扭曲本土蜘蛛并利用成熟的魔苔来包藏他险恶的阴谋。",al={"谁是塞索尔","邪恶的塞索尔","谁是那个萨特"}},{q="大断崖位于何处？",a="大断崖是泰达希尔上多兰纳尔西北方森林深处的一处隐秘区域，邪恶的塞索尔和他的污秽巢群就栖居于此。",al={"大断崖在哪里","大断崖位置","在哪里找到塞索尔"}},{q="为什么泰达希尔的蜘蛛会被玷污？",a="被玷污的蛛木蜘蛛是泰达希尔本土的蜘蛛，它们被邪恶的塞索尔所腐化。这名萨特扭曲了它们的心智和生理结构，意图收集它们的毒液来执行一个肮脏的恶魔计划。",al={"为什么蜘蛛会变异","什么是被玷污的蛛木蜘蛛","被玷污的蛛木蜘蛛背景"}},{q="谁是塔隆凯·捷根？",a="塔隆凯·捷根是一名驻扎在泰达希尔多兰纳尔村的暗夜精灵守卫，他会委派冒险者去铲除周围森林中的恶魔颠覆活动。",al={"谁发布了这个任务","塔隆凯在哪里","塔隆凯·捷根的作用"}},{q="什么是成熟的魔苔？",a="成熟的魔苔是邪恶的塞索尔所携带的一种具有腐蚀性的植物样本，塔隆凯·捷根试图寻找它，以进一步揭开这名萨特的真实动机以及他在泰达希尔正在进行的勾当。",al={"成熟的魔苔","为什么要收集魔苔","什么是魔苔"}},{q="梅伦纳斯领主是如何卷入其中的？",a="梅伦纳斯领主的所作所为并非出于孤立的恶意，而是在邪恶的塞索尔明确指使下进行的，这揭露了在泰达希尔内部运作的一个有组织的萨特阴谋。",al={"梅伦纳斯的关联","谁是梅伦纳斯领主","梅伦纳斯与塞索尔"}}},fp="14,191,18.200.0,31.300.1,26.206.0,27.138.0,43.158.0,27.158.0,28.180.0,30.147.0"}
P.entries["quest:98404"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit是摆在德鲁伊新秀面前，关于狡诈与潜行的神圣试炼。受试者必须进入附近的Stormrage Barrow Den，在避开敌对、狂怒的灵魂的同时寻回三件古代圣物。通过这项灵性仪式，证明了受试者掌握了猫科动物潜行、凶猛和狡诈的美德，从而获得驾驭猫形态的祝福。",h="The Great Windborne Cat Spirit是摆在德鲁伊新秀面前，关于狡诈与潜行的神圣试炼。受试者必须进入附近的Stormrage Barrow...",kw={"塞莉南的化身","猫形态","德鲁伊试炼","狂怒的灵魂","利爪圣物","尖牙圣物","静影圣物","塞莉南","怒风兽穴","风行巨豹之灵"},ang={["class:Druid"]="对于学习引导野猫敏捷、潜行和捕食本能的德鲁伊来说，这项仪式是一个重要的里程碑。在灵魂赋予其变形祝福之前，必须证明自己具备狡诈和凶猛的特质。",["race:NightElf"]="Stormrage Barrow Den承载着最显赫的暗夜精灵德鲁伊家族之一的名字。探索其深处能让卡多雷修行者直接与古代兽穴遗产以及他们人民的祖先灵魂相连。"},sec={{t="狡诈与潜行试炼",b="为了汲取巨豹之灵的力量，志向者必须证明他们拥有捕食者的气质。与猫科动物达成真正的和谐需要理解狡诈与耐心，并要在受困时展现出爆发性的凶猛。灵魂不会轻易将天赋赐予那些仅是索求力量的人；相反，它会考验寻觅者是否能像荒野中的猫科猎手那样思考、行动和打击。唯有展现出这些内在特质，新秀才有望获得化身为猫的权利。"},{t="Stormrage Barrow Den",b="这项考验会将寻觅者送入附近Stormrage Barrow Den的阴暗之中，它位于灵魂化身的东面。在这些地下大厅深处存放着三件神圣信物：尖牙圣物、利爪圣物和静影圣物。然而，获取它们绝非易事。这座兽穴已然充斥着狂怒的灵魂，它们会对视野中的任何入侵者进行猛烈攻击。为了在洞穴中生存并抵达圣物所在地，寻觅者不能仅依靠蛮力，而必须在黑暗中小心潜行。"},{t="Saeyleenan的化身",b="这场试炼的核心是Saeyleenan的化身，这是The Great Windborne Cat Spirit与年轻新秀沟通的实体显现。考虑到未经训练的寻觅者缺乏老练捕食者那种与生俱来的潜行能力，兽穴入口处的一座雕像会提供暂时的隐匿祝福。那些成功避开狂乱灵魂并带回全部三件圣物的人，证明了他们已经领悟了捕食者的课程。作为回报，化身会认可他们的资格，并赋予他们化身为猫形态所需的祝福。"}},faq={{q="谁是伟大的御风猫灵？",a="伟大的御风猫灵是一位野性守护者，指引年轻的德鲁伊掌握猫科动物变形术。它通过塞琳南的化身显现，体现了狡诈、潜行和凶猛这些核心的捕食者美德。它并不会随意赋予其形态，而是通过神圣试炼来考验志向者，以确保他们尊重猫科动物的捕食本能与天性。",al={"伟大的御风巨豹之灵","塞琳南是谁","巨豹之灵背景故事"}},{q="什么是塞琳南的化身？",a="塞琳南的化身是伟大的御风猫灵的实体存在与发言人。化身位于怒风兽穴的西面，负责监督该地区的德鲁伊试炼。它指派寻觅者执行找回被盗或隐藏的兽穴圣物的任务，并评估新秀是否展现出足够的潜行和狡诈来赢得猫科动物的祝福。",al={"塞琳南的化身","塞琳南的化身是谁","塞琳南 非玩家角色"}},{q="试炼需要哪些圣物？",a="试炼需要从怒风兽穴内找回三件特定的圣物：尖牙圣物、利爪圣物和静影圣物。这些神器共同象征着定义猫灵形态的核心物理武器与难以捉摸的潜行能力，证明了新秀对捕食者每一面的敬畏。",al={"三件圣物","利爪圣物","怒风兽穴圣物"}},{q="怒风兽穴位于何处？",a="怒风兽穴位于塞琳南的化身东面。这些地下室是德鲁伊试炼的试验场，存放着三件神圣圣物。新秀必须深入这些黑暗的大厅，同时避开在隧道中游荡的危险的狂怒灵魂。",al={"怒风兽穴位置","兽穴在哪里","哪里寻找圣物"}},{q="为什么狂怒的灵魂在守卫兽穴？",a="怒风兽穴已被强大的狂怒灵魂所占据，它们会攻击视野中的任何活体入侵者。这些敌对实体并非自愿的守卫者，而是兽穴内活跃的危险，这迫使德鲁伊志向者必须利用狡诈与潜行来取回圣物，而不是进行直接战斗。",al={"灵魂为何狂怒","兽穴的狂怒灵魂","兽穴守卫"}},{q="寻觅者如何潜行穿过狂怒的灵魂？",a="立在怒风兽穴入口处的一座石像会给予寻觅者暂时的潜行祝福。由于年轻的新秀尚未获得自身固有的猫形态或潜行能力，这种防护附魔使他们能够未被察觉地溜过警惕的敌对灵魂，从而获取圣物。",al={"如何在兽穴潜行","石像潜行增益","如何避开狂怒灵魂"}},{q="完成试炼后会获得什么奖励或祝福？",a="在交回尖牙圣物、利爪圣物和静影圣物后，塞琳南的化身会认为寻觅者有资格获得伟大的御风猫灵的祝福。这项仪式标志着新秀对猫科动物真实本性的理解，赋予他们化身为捕食者形态所需的灵性认可。",al={"试炼奖励","从巨豹之灵获得什么","巨豹之灵的祝福"}}},fp="30,237,32.343.0,24.379.0,24.452.0,38.263.0,33.273.0,39.281.0,42.213.0,48.273.0,46.264.0,61.320.0"}
P.entries["quest:98407"] = {n="Show of Force",s="Show of Force是赤脊山的一项联盟防御任务，由菲尔顿副队长发布。为了阻止在湖畔镇附近不断逼近的豺狼人族群，冒险者们受命猎杀豺狼人剥皮者并收集它们的尖刺项圈，以震慑这些试图侵入人类定居点的生物。",h="Show of Force是赤脊山的一项联盟防御任务，由菲尔顿副队长发布。为了阻止在湖畔镇附近不断逼近的豺狼人族群，冒险者们受命猎杀豺狼人剥皮者并收集它们的尖刺项圈，以震慑这些试图侵入人类定居点的生物。",kw={"菲尔顿副队长","豺狼人剥皮者","豺狼人","湖畔镇","赤脊山","展示力量","尖刺项圈"},ang={["class:Warrior"]="豺狼人只屈服于直接而彻底的暴力——这使得直接的前线武力镇压成为打破它们防线的理想方法。",["faction:Alliance"]="湖畔镇是联盟在南部东部王国最靠东的堡垒之一；确保其边界免受野兽侵袭对于区域稳定至关重要。",["race:Human"]="赤脊山的农场主和镇民是暴风城的臣民，他们处于极其危险的境地，没有任何保护，只能依靠他们的同胞来击退这些狂野的掠夺者。"},sec={{t="大胆的侵袭",b="赤脊山长期以来一直庇护着狂野的豺狼人部落，但它们现在变得愈发猖狂。豺狼人劫掠小队不再只是在崎岖的丘陵高处与世隔绝，而是在距离湖畔镇和外围人类家园极其危险的地方建立了营地。随着暴风城的军事力量捉襟见肘，无法为农村边境提供援军，当地当局必须依靠过往的冒险者来保卫边境，防止这些侵袭小队聚集胆量袭击城镇本身。"},{t="它们的语言",b="菲尔顿副队长深知豺狼人是残忍且毫无组织的生物，除了绝对的武力压制外，它们几乎什么都不怕。要迫使它们退回荒野，外交手段或折中办法毫无用处。菲尔顿试图打击它们最凶猛的先锋——豺狼人剥皮者——并收获它们的尖刺项圈，作为支配地位的冷酷证明。通过击溃它们的前线战士并展示它们的失败战利品，湖畔镇的守卫者希望以此威慑幸存的族群，让它们撤回高地。"}},faq={{q="谁提供了这个任务？他们位于哪里？",a="该任务由菲尔顿副队长提供，他是一名驻扎在赤脊山湖畔镇附近外围的城镇守卫。",al={"任务发布者","菲尔顿副队长位置","谁发布武力展示"}},{q="为什么豺狼人会逼近湖畔镇？",a="豺狼人是极具侵略性的机会主义者，它们会不断试探自己的边界。由于湖畔镇在防守上面临压力，且几乎没有得到暴风城的军事援助，豺狼人变得胆大妄为，直接在人类定居点外建立了狩猎营地。",al={"豺狼人为何攻击","赤脊山豺狼人威胁","为什么豺狼人靠得这么近"}},{q="为了这个任务，需要击败哪些敌人？",a="该任务的目标是豺狼人剥皮者，它们是当地豺狼人族群中更危险、更具侵略性的突击战士，佩戴着沉重的尖刺项圈。",al={"哪些豺狼人","需要击杀什么怪物","豺狼人剥皮者"}},{q="为什么菲尔顿副队长特别想要尖刺项圈？",a="豺狼人依靠残酷的等级制度和原始力量生存。夺取剥皮者的尖刺项圈是一种直接的力量展示，旨在恐吓幸存的豺狼人，迫使它们撤回山丘。",al={"为什么要尖刺项圈","项圈的用途","为什么要拿走项圈"}},{q="暴风城能提供士兵来对付豺狼人吗？",a="暴风城在很大程度上任由赤脊山自生自灭。由于王国国内局势动荡且各处兵力短缺，暴风城几乎没有派遣任何增援部队，迫使当地副队长不得不依靠独立的勇士。",al={"暴风城对赤脊山的援助","为什么没有暴风城军队","守卫在哪里"}},{q="豺狼人通常在赤脊山的什么地方扎营？",a="豺狼人营地散布在止水湖周围的丘陵和低矮山脊上，以及通往东部石堡区域的道路沿线。",al={"豺狼人营地","在哪里找到豺狼人","赤脊山豺狼人位置"}}},fp="13,131,19.326.0,23.332.0,49.102.0,49.164.0,50.109.0,56.119.0,55.129.0,52.109.0"}
P.entries["quest:98423"] = {n="The Treaty of Understanding",s="谅解条约是一块古老的矮人石板，详细记载了三锤之战之后，铜须氏族与蛮锤氏族达成的历史性和平协议。这件文物从地下深处寻回，并被呈交给国王麦格尼·铜须，保存了矮人历史上的一个关键时刻，也揭示了那道令黑铁氏族被排除在和平之外的深刻裂痕。",h="谅解条约是一块古老的矮人石板，详细记载了三锤之战之后，铜须氏族与蛮锤氏族达成的历史性和平协议。这件文物从地下深处寻回，并被呈交给国王麦格尼·铜须，保存了矮人历史上的一个关键时刻，也揭示了那道令黑铁氏族被排除在和平之外的深...",kw={"黑铁","铁炉堡","玛多兰·铜须","麦格尼·铜须","和平条约","谅解条约","三锤之战","蛮锤"},ang={["faction:Alliance"]="铜须矮人和蛮锤矮人之间历史性的和平，奠定了他们在现代大联盟中合作的基础。",["race:Dwarf"]="这块石板是矮人和解的实物记录，展现了你的先祖如何在山峰争夺战后放下世仇。"},sec={{t="矮人和解的遗物",b="谅解条约从一座古老宝库的深处寻回，是一块记载矮人氏族正式停止敌对行动的历史石板。它诞生于三锤之战结束后的动荡时期，见证了铜须氏族在掌控铁炉堡所在的山峰后，与蛮锤氏族缔结和平的时刻。"},{t="未获签署的和平",b="国王麦格尼·铜须看到寻回的石板后，认出这是他的先祖玛多兰·铜须留下的文物，那是铁炉堡的第一位铜须国王。文书上有铜须与蛮锤两族领袖的签名，却唯独缺少黑铁氏族的印记，长久见证着黑铁氏族与山中同胞之间始终未能弥合的裂痕。"}},faq={{q="谅解条约是什么？",a="谅解条约是一块从宝库深处寻回的古老矮人石板。它记载了铜须氏族与蛮锤氏族在三锤之战结束后随即达成的正式和平协议。",al={"谅解条约是什么","条约石板","这份条约是什么"}},{q="这份条约是谁制定的？",a="这份条约起草于三锤之战结束之后，当时在位的是玛多兰·铜须，他是三大氏族争夺山峰控制权之后，铁炉堡的第一位铜须国王。",al={"谁撰写了谅解条约","谁制定了谅解条约","谁起草了条约"}},{q="黑铁氏族为什么没有签署条约？",a="铜须氏族掌控铁炉堡后，黑铁氏族拒绝接受和平。因此，只有铜须与蛮锤两族签署了协议，黑铁氏族则陷入孤立，依然抱持敌意。",al={"黑铁为什么没签署","黑铁签署条约了吗","条约上没有黑铁"}},{q="谁对谅解条约感兴趣？",a="石板被送到铁炉堡的王座厅，交给国王麦格尼·铜须；他将其视为先祖玛多兰与矮人历史留下的无价遗物。",al={"谁想要条约","谅解条约交给谁","在哪里交条约"}},{q="三锤之战是什么？",a="三锤之战是铜须、蛮锤与黑铁三个矮人氏族为争夺铁炉堡所在山峰的控制权而爆发的惨烈内战。铜须氏族最终获胜，占据了山峰，其他氏族则被逐出。",al={"三锤之战是什么","矮人内战","三锤之战"}},{q="玛多兰·铜须是谁？",a="玛多兰·铜须是国王麦格尼·铜须的先祖，也是三个矮人氏族的内战结束后，第一位统治铁炉堡的铜须国王。",al={"玛多兰·铜须是谁","玛多兰·铜须","麦格尼的先祖玛多兰"}}},fp="27,209,33.315.0,18.304.0,36.207.0,23.189.0,47.191.0,49.145.0,38.214.0,28.159.0"}
P.entries["quest:98424"] = {n="Fizsprockets Notizen",s="摩林·云行者正在风​​险投资公司矿洞寻找菲兹普罗克笔记本剩余的页面。这些磨损的笔记记载着关于该公司在此地区阴谋的重要信息。",h="摩林·云行者正在风​​险投资公司矿洞寻找菲兹普罗克笔记本剩余的页面。这些磨损的笔记记载着关于该公司在此地区阴谋的重要信息。",kw={"血蹄村","菲兹普罗克","矿洞","摩林·云行者","笔记本","页面","风险投资公司"},sec={{t="遗失的页面",b="你在菲兹普罗克的口袋里找到了折叠的页面。摩林正在血蹄村等候你从风险投资公司矿洞带回剩余的页面，笔记本中的信息或许能为接下来的行动指明方向。"}},faq={{q="我在找哪些页面？",a="你要寻找的是监工菲兹普罗克笔记本剩余的页面。",al={"菲兹普罗克 笔记","笔记本页面","遗失的笔记"}},{q="其余笔记在哪里？",a="剩余的页面在风险投资公司矿洞里。",al={"页面在哪里","风险投资公司矿洞","笔记本位置"}},{q="谁想要这些页面？",a="摩林·云行者正在血蹄村等候这些页面。",al={"谁需要笔记","摩林的请求","把页面交给谁"}},{q="菲兹普罗克的笔记本里写了什么？",a="这本笔记记载着关于风险投资公司及其在此地区阴谋的重要信息。",al={"笔记内容","菲兹普罗克 笔记本","风险投资公司信息"}}},fp="20,158,17.257.0,28.77.0,32.48.0,20.65.0,36.96.0"}
P.entries["quest:98427"] = {n="Schluss damit!",s="摩林·云行者警告说，伐木机器人能以惊人的速度砍倒整片森林。他请你返回东北方的矿洞，阻止它再砍倒一棵树。",h="摩林·云行者警告说，伐木机器人能以惊人的速度砍倒整片森林。他请你返回东北方的矿洞，阻止它再砍倒一棵树。",kw={"血蹄村","大地母亲的子民","伐木机钥匙","矿洞","摩林·云行者","东北方","伐木机器人","树木"},ang={["race:Tauren"]="作为一名牛头人，摩林关心庇护大地母亲子民的林地，也关心家园附近幼小族人的安危。"},sec={{t="家园的威胁",b="摩林听说了书页中描述的伐木机器人。这种机器砍倒整片森林的速度远胜斧头和人力。庇护大地母亲子民多年的林地，短短几天便可能消失。他请你召集盟友，返回东北方的矿洞，确保机器不再砍倒树木。请将Mechanoroderschlüssel带给血蹄村的摩林。"}},faq={{q="摩林要我做什么？",a="摩林请你召集盟友，返回东北方的矿洞，阻止伐木机器人继续砍树。",al={"摩林想要什么","摩林的请求","伐木机器人任务"}},{q="伐木机器人为何构成威胁？",a="摩林说，伐木机器人砍倒整片森林的速度远胜斧头和人力，还会摧毁庇护大地母亲子民的林地。",al={"为何阻止伐木机器人","伐木机器人的威胁","伐木机器人能做什么"}},{q="摩林要我去哪里？",a="摩林请你返回东北方的矿洞。",al={"矿洞在哪里","东北方的矿洞","要返回哪里"}},{q="我要带什么东西交给摩林？",a="将机械伐木机钥匙交给血蹄村的摩林·云行者。",al={"摩林要什么物品","机械切割器钥匙","交给摩林的钥匙"}},{q="摩林·云行者是谁？",a="摩林·云行者请你阻止伐木机器人砍伐牛头人家园附近的树木。",al={"摩林是谁","摩林·云行者","摩林这个人"}}},fp="18,186,16.385.0,30.116.0,29.148.0,31.54.0,30.76.0,26.89.0"}
P.entries["quest:98430"] = {n="Die Langläufer",s="斥候Perith Stormhoof受凯恩·血蹄派遣，在与豺狼人谋求和平时遭遇暴力，如今被困在Bleachmane Rock。救出他对凯恩和牛头人至关重要。",h="斥候Perith Stormhoof受凯恩·血蹄派遣，在与豺狼人谋求和平时遭遇暴力，如今被困在Bleachmane Rock。救出他对凯恩和牛头人至关重要。",kw={"bleachmane rock","凯恩·血蹄","豺狼人","长跑者","和平尝试","perith stormhoof","雷霆崖"},ang={["race:Tauren"]="身为牛头人，你正在帮助凯恩·血蹄信任的斥候，他的任务关系到牛头人。"},sec={{t="身陷险境的斥候",b="凯恩·血蹄派Perith Stormhoof前去接触定居于此的豺狼人。作为凯恩的长跑者之一，Perith不能透露完整任务。和平尝试遭到暴力回应，他担心若留到夜里，豺狼人会把他吃掉。请帮助他逃离Bleachmane Rock，并前往雷霆崖向凯恩报告他已平安脱险。"},{t="凯恩的谢意",b="得知Perith平安无事，凯恩如释重负。他称这名斥候是自己最信任的人，并表示这项任务意义重大。凯恩感谢你冒着生命危险救他，说你为牛头人做出的贡献远超你的想象。"}},faq={{q="Perith Stormhoof是谁？",a="Perith Stormhoof是凯恩·血蹄的长跑者之一，也就是这位酋长的斥候。",al={"perith是谁","stormhoof斥候","长跑者是谁"}},{q="Perith为何在Bleachmane Rock？",a="凯恩派Perith去接触定居于那里的豺狼人，但Perith不能透露完整任务。",al={"perith为何在那里","bleachmane rock","perith的任务"}},{q="和平尝试发生了什么？",a="豺狼人以暴力回应了长跑者的和平尝试，Perith因此陷入险境。",al={"豺狼人和平","perith为何被困","与豺狼人讲和"}},{q="凯恩要我做什么？",a="请帮助Perith逃离Bleachmane Rock，并告诉雷霆崖的凯恩他已平安无事。",al={"帮助perith","stormhoof的任务","救他出去"}}},fp="15,183,17.357.0,17.239.1,24.87.0,33.99.0,34.97.0,30.101.0"}
P.entries["quest:98435"] = {n="Thunderhorns Bericht",s="穆尔请你将雷角的报告送到雷霆崖，交给大德鲁伊哈缪尔·符文图腾。长者们需要知道你的帮助取得了什么成果。",h="穆尔请你将雷角的报告送到雷霆崖，交给大德鲁伊哈缪尔·符文图腾。长者们需要知道你的帮助取得了什么成果。",kw={"长者高地","哈缪尔·符文图腾","莫高雷","报告","泉水","牛头人","雷霆崖","雷角"},sec={{t="报告",b="你把雷角的报告交给了位于雷霆崖东部的长者高地的哈缪尔。他说，莫高雷的泉水滋养着牛头人，也滋养着他们赖以获取食物、衣物和陪伴的动物。"}},faq={{q="谁需要雷角的报告？",a="雷霆崖的大德鲁伊哈缪尔·符文图腾需要雷角的报告。",al={"谁收报告","给 哈缪尔 的报告","雷角 的报告"}},{q="哈缪尔·符文图腾在哪里？",a="哈缪尔位于雷霆崖东部的长者高地。",al={"哈缪尔 在哪里","哈缪尔 的位置","寻找 哈缪尔"}},{q="这份报告为何重要？",a="莫高雷的泉水滋养着牛头人，也滋养着他们赖以获取食物、衣物和陪伴的动物。",al={"报告为何重要","泉水有何用处","莫高雷的泉水"}},{q="哈缪尔对泉水有何评价？",a="哈缪尔说，泉水滋养着牛头人，也滋养着他们所依赖的动物。",al={"哈缪尔 说了什么","泉水与动物"}}},fp="20,151,10.240.0,33.73.0,26.53.0,27.106.0,39.79.0"}
P.entries["quest:98459"] = {n="A Lack of Virtue",s="“A Lack of Virtue”是一个送信任务，讲述了两名玩牌的水手——“半鱼”汤姆和巴特·潮汐水手之间经久不息的小摩擦。旅行者们带着一份包裹好的礼物跨越海洋来到米奈希尔港，却意外卷入了两人关于“少女的贞洁号”是如何得来的互相指控之中。",h="“A Lack of...",kw={"美德的缺失","巴特·潮汐水手","少女的贞洁号","米奈希尔港","扑克","塔纳利斯","汤姆·半鱼","汤姆的礼物","湿地"},ang={["faction:Alliance"]="路过米奈希尔港的联盟旅行者经常会遇到正在对船员咆哮的巴特·潮汐水手，这使得送信成为了在等待横跨无尽之海的交通工具时的一个小插曲。"},sec={{t="苦涩的积怨",b="“A Lack of Virtue”的核心是两位老练的海上赌徒之间尖锐的竞争：汤姆·半鱼和巴特·潮汐水手。汤姆招募过往的旅行者将一个包裹送过海面交给米奈希尔港的巴特，以此作为对这位前同伴尖酸刻薄的嘲弄。一路上，汤姆警告说巴特根本不是真正的海员，而是一个曾经靠在牌局中出老千来买下船只指挥权的演员。"},{t="摊牌",b="当在米奈希尔港的码头上收到“汤姆的礼物”时，巴特·潮汐水手一听到他这位老相识的名字就勃然大怒。巴特立即反唇相讥，发誓说出老千的其实是汤姆，而且只有在他们的牌局将“半鱼”踢出去之后，他才赢得了足够的金币买下“少女的贞洁号”。尽管脾气爆发，巴特还是很快控制住了自己，为对送信人发火表示了歉意，并欢迎旅行者来到港口。"}},faq={{q="巴特·潮汐水手是谁？",a="巴特·潮汐水手是停靠在米奈希尔港的“少女的贞洁号”的自封船长。据他的老相识汤姆·半鱼所说，巴特原本是一名演员，他是用玩牌赢来的钱买下了这艘船——尽管两人都指责对方玩牌出老千。",al={"巴特·潮汐水手是谁","巴特·潮汐水手背景故事","少女的贞洁号的船长是谁"}},{q="汤姆·半鱼是谁？",a="汤姆·半鱼是巴特·潮汐水手的一位老相识，他给旅行者一份礼物，让他们带过海面交给巴特。他怀着对这位船长的强烈积怨，声称巴特是个骗子、吝啬鬼，还是个玩牌的老千。",al={"半鱼是谁","汤姆·半鱼是谁","谁发布了缺乏美德任务"}},{q="“少女的贞洁号”是什么？",a="“少女的贞洁号”是一艘停靠在湿地米奈希尔港的船只。巴特·潮汐水手声称这是无尽之海最棒的船，尽管汤姆·半鱼贬损说这艘船航行的最远距离也就像塔纳利斯的一块石头那么远。",al={"什么是少女的贞洁号","少女的贞洁号船只","少女的贞洁号在哪里"}},{q="“汤姆的礼物”是什么？",a="“汤姆的礼物”是汤姆·半鱼寄给米奈希尔港巴特·潮汐水手的一个包裹。虽然送货人不知道里面的具体内容，但收到礼物后，巴特立即就汤姆本人打扑克出老千的问题破口大骂。",al={"什么是汤姆的礼物","汤姆的礼物里面有什么","为什么巴特对汤姆的礼物感到生气"}},{q="到底是谁在打扑克时出老千？",a="两位水手都激烈地指责对方出老千。汤姆·半鱼坚称巴特是个只靠出老千赢牌买船的演员，而巴特则声称只有在将汤姆踢出他们的牌局之后，他才名正言顺地赢得了自己的船只。",al={"谁在打扑克时出老千","巴特打扑克时出老千了吗","汤姆打扑克时出老千了吗"}},{q="如何将礼物送到米奈希尔港？",a="旅行者可以乘坐跨越无尽之海的船只到达湿地的米奈希尔港。任务发布者指出，一班直达船在米奈希尔港有停靠。",al={"如何前往米奈希尔港","前往米奈希尔港的船"}}},fp="16,170,15.236.0,18.339.1,22.212.0,21.214.0,28.187.0,19.195.0,30.215.0,47.146.0"}
P.entries["quest:98461"] = {n="Unrequited Love",s="Unrequited Love是联盟的一项送信任务，起始于黑海岸岸边的奥伯丁。霍莉请求搭乘船只前往米奈希尔港的旅人将一封私人信件交给塔雷尔·石纹，他是她曾经的考古学同学，她至今对他怀有默默的爱慕。",h="Unrequited Love是联盟的一项送信任务，起始于黑海岸岸边的奥伯丁。霍莉请求搭乘船只前往米奈希尔港的旅人将一封私人信件交给塔雷尔·石纹，他是她曾经的考古学同学，她至今对他怀有默默的爱慕。",kw={"奥伯丁","黑海岸","考古","霍莉","霍莉的便笺","米奈希尔港","麦琳","塔雷尔·石纹","单相思","湿地"},ang={["faction:Alliance"]="这次运送将黑海岸的联盟港口奥伯丁与湿地的米奈希尔港直接连接起来，连通了卡利姆多和东部王国。",["race:Dwarf"]="塔雷尔·石纹和霍莉都有考古背景，这是矮人传统和艾泽拉斯学术研究的核心职业。"},sec={{t="跨海传书",b="在黑海岸多雾的海岸边，海港小镇奥伯丁，霍莉注视着登上前往东部王国船只的旅人。她寻求路人的帮助来联系一位老同学塔雷尔·石纹，在毕业将他们分隔在不同的大陆之前，他们曾一起学习多年的考古技艺。"},{t="未诉说的情感",b="虽然霍莉深情地回忆起塔雷尔敏锐的头脑和考古技能，但一提到他的妻子麦琳，她的神情就会变得不自然。尽管相隔遥远且他已婚，霍莉还是将一封私人信件托付给了一位冒险者，请求他们前往米奈希尔港附近寻找塔雷尔，以确认他是否平安。"}},faq={{q="谁发布了单相思任务？",a="霍莉在黑海岸的沿海定居点奥伯丁发布了这个任务。她请求搭乘前往米奈希尔港船只的旅人将一封私人便笺交给一位老同学。",al={"谁发布了单相思","奥伯丁的任务发布者"}},{q="塔雷尔·石纹是谁？",a="塔雷尔·石纹是一位考古学家，也是霍莉以前的同学。学业结束后，他被派往湿地，现在和他的妻子麦琳一起在米奈希尔港附近工作。",al={"塔雷尔·石纹是谁","塔雷尔相关传说"}},{q="麦琳是谁？",a="麦琳是塔雷尔·石纹的妻子。霍莉在提到她时显得犹豫不决且眉头紧锁，这揭示了尽管塔雷尔已经结婚，她对他仍有挥之不去、未得到回应的感情。",al={"麦琳是谁","塔雷尔的妻子"}},{q="为什么任务叫单相思？",a="这个标题指的是霍莉对塔雷尔·石纹那份默默的情感。尽管他们作为亲密的同学一起学习考古，但塔雷尔娶了麦琳，留下了霍莉在远隔重洋的奥伯丁独自思念。",al={"单相思任务内容","为什么叫单相思"}},{q="塔雷尔·石纹在哪里？",a="塔雷尔·石纹可以在湿地的米奈希尔港附近找到，这里与黑海岸隔着无尽之海。从奥伯丁出发的客船可以将旅人直接送达港口码头。",al={"在哪里找到塔雷尔·石纹","塔雷尔所在的湿地"}},{q="这个任务要传送什么物品？",a="你被要求携带霍莉的便笺去交给塔雷尔·石纹，以确认他在湿地的近况并传达她的私人信息。",al={"你要送什么","霍莉的信"}}},fp="15,110,24.272.0,17.267.0,37.173.0,25.176.0,14.132.0,40.167.0,35.160.0,37.124.0"}
P.entries["quest:98463"] = {n="Talk of the Town",s="一位友好的酒保指引那些渴望热闹聚会的旅客前往位于荆棘谷的藏宝海湾。如果想要寻找更狂野的同伴，则被告知去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克。",h="一位友好的酒保指引那些渴望热闹聚会的旅客前往位于荆棘谷的藏宝海湾。如果想要寻找更狂野的同伴，则被告知去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克。",kw={"藏宝海湾","地精酒馆","尼克斯拉克斯·菲拉马克","水手之家旅店","荆棘谷","街谈巷议"},sec={{t="柜台间的消息",b="消息在酒保和顾客之间流传得很快，并且传得很远。一位友好的酒保透漏了哪里正在酝酿真正的骚乱，指引任何寻找更狂野场面的人前往藏宝海湾。"},{t="咸水帆船",b="目的地是Salty Sailor Tavern，这是一间由地精在熙熙攘攘的荆棘谷中经营的热闹场所。在那里，尼克斯拉克斯·菲拉马克为每一位走进店里的客人斟满酒杯。"}},faq={{q="这会带你到哪里？",a="这会带你前往荆棘谷，直达地精经营的港口城镇藏宝海湾。",al={"我要去哪里","目的地","藏宝海湾指引"}},{q="在藏宝海湾应该去找谁？",a="你被指引去水手之家旅店寻找尼克拉克斯·菲拉莫格，他会在那里为大家斟满酒杯。",al={"要拜访谁","尼克斯拉克斯是谁","尼克斯拉克斯·菲拉马克"}},{q="为什么要让人跑那么远去荆棘谷？",a="酒保总能从客人的闲谈中听到各种流言，据说水手之家旅店有着附近最狂野的庆祝活动，无论是否由地精管理。",al={"为什么去咸水帆船","为什么要前往藏宝海湾","为什么有此推荐"}}},fp="16,172,25.184.0,16.164.0,21.70.0,42.100.0,51.140.0"}
P.entries["quest:985"] = {n="熊怪的威胁",s="“威胁有多大？”是一个联盟任务，由奥伯丁的暗夜精灵特伦希斯提供。在已经侦察过镇子南面的敌对黑木熊怪营地后，冒险者被派去消灭受腐化的探路者和风语者，以免他们的疯狂威胁到定居点。",h="“威胁有多大？”是一个联盟任务，由奥伯丁的暗夜精灵特伦希斯提供。在已经侦察过镇子南面的敌对黑木熊怪营地后，冒险者被派去消灭受腐化的探路者和风语者，以免他们的疯狂威胁到定居点。",kw={"奥伯丁","黑木","黑海岸","魔苔","熊怪","格里姆克劳","探路者","特伦希斯","风语者"},ang={["class:Druid"]="德鲁伊对此悲剧感触尤深，因为熊怪的困境反映了森林在魔苔污染下所遭受的持续痛苦。",["faction:Alliance"]="奥伯丁是联盟在黑海岸的重要港口据点，因此清除附近的敌对营地对于确保该地区的安全至关重要。",["race:NightElf"]="对于暗夜精灵来说，清理黑木熊怪是一种痛苦的悲哀；与熊怪数百年的亲族关系因第三次战争残留的恶魔枯萎病而破碎。"},sec={{t="必要的清理",b="在对奥伯丁南部进行初步侦察后，哨兵部队判定黑木熊怪对黑海岸的难民和守卫者构成了直接威胁。特伦希斯指派有战斗能力的旅行者直接突袭他们的营地，消灭黑木探路者和风语者，以打破他们的攻势。"},{t="受腐化者的悲剧",b="暗夜精灵传统上将熊怪视为精神上的亲族和荒野的历史盟友。然而，魔苔和恶魔污染在卡利姆多北部的恶性蔓延导致黑木部落陷入疯狂。由于目前没有已知的补救措施可以恢复熊怪的神智，奥伯丁的守卫者们将暴力视为防止无辜死亡的冷酷必要手段。"},{t="格里姆克劳的到来",b="在向特伦希斯汇报清理任务后，一只名叫格里姆克劳的白熊冲进奥伯丁，奔向那名暗夜精灵。它的到来标志着蹂躏海岸线的野生动物和腐化问题出现了紧急的新进展，开启了奥伯丁防御工作的下一阶段。"}},faq={{q="特伦希斯为什么要消灭黑木熊怪？",a="奥伯丁南部的黑木部落已经堕入腐化，变得暴力且失去理智。由于他们的营地对定居点构成了迫在眉睫的威胁，且目前尚未发现针对这种腐化的治疗方法，特伦希斯下令发动先发制人的打击以确保奥伯丁的安全。",al={"为什么要消灭黑木熊怪","熊怪清理的原因","特伦希斯的熊怪任务"}},{q="黑木熊怪营地在哪里？",a="营地位于奥伯丁以南，沿着黑海岸的沿海森林，坐落在黑木部落聚集的受腐化树木之中。",al={"黑木熊怪的位置","探路者和风语者在哪里","黑海岸的熊怪营地"}},{q="格里姆克劳是谁？",a="格里姆克劳是一只与黑海岸荒野调查相关的白熊。",al={"奥伯丁的白熊","熊格里姆克劳"}},{q="是什么导致熊怪发疯？",a="熊怪受到了魔苔和第三次战争后残留的恶魔腐化的毒害。蹂躏黑海岸的黑暗能量扭曲了它们的心智和身体，驱使原本爱好和平的部族陷入无法控制的狂暴之中。",al={"为什么熊怪会发疯","黑海岸熊怪的腐化","是什么腐化了黑木部落"}},{q="为什么暗夜精灵不愿杀害熊怪？",a="熊怪和暗夜精灵分享着数千年的友谊和对自然的崇敬。对暗夜精灵来说，杀死它们就像是在屠杀自己的荒野兄弟，但腐化让他们别无选择。",al={"暗夜精灵与熊怪","为什么要哀悼熊怪"}},{q="“威胁有多大？”任务的第一阶段和第二阶段有什么区别？",a="第一个任务通过要求你定位并观察黑木营地来测试侦察能力。第二个任务则是一项直接的战斗任务，在威胁确认后，旨在削减营地中的探路者和风语者数量。",al={"“威胁有多大”的组成部分","“威胁有多大”的区别"}}},fp="17,195,16.282.0,24.317.0,18.281.1,54.201.0,44.138.0,16.81.1,39.186.0,47.189.0,79.168.0"}
P.entries["quest:98512"] = {n="Al'Aketh Assassins",s="Al'Aketh Assassins 是一个要求消灭一群危险杀手的任务。冒险者需要协助一名斥候消除威胁，并获得将要在给瓦拉纳尔的报告中提到的正式表彰。",h="Al'Aketh Assassins 是一个要求消灭一群危险杀手的任务。冒险者需要协助一名斥候消除威胁，并获得将要在给瓦拉纳尔的报告中提到的正式表彰。",kw={"奥拉凯斯","刺客","杀手","任务","报告","瓦拉纳尔"},ang={["class:Rogue"]="面对像奥拉凯斯这样的致命杀手，需要具备同样致命的专注力和冷酷的精准度。"},sec={{t="致命威胁",b="Al'Aketh Assassins 在野外构成了致命威胁，当地斥候称他们为冷酷的杀手。他们无情的效率和协同作战的能力，使得任何与他们的冲突对当地斥候和旅行者来说都极其危险。处理他们的存在需要迅速果断的行动，以免他们先发制人。"},{t="向瓦拉纳尔报告",b="在消灭了敌对的奥拉凯斯部队后，一名盟军特工对你在面对如此危险的对手时幸存下来表示深感欣慰。为了感谢你及时的干预，这名斥候承诺将在发往瓦拉纳尔的官方报告中正式记录你的英勇援助。"}},faq={{q="什么是 奥拉凯斯刺客？",a="奥拉凯斯刺客 是一个任务，要求冒险者消灭一支致命的奥拉凯斯部队。他们构成的威胁十分严重，需要立即干预并提交正式报告。",al={"什么是 奥拉凯斯刺客","什么是这个任务","奥拉凯斯刺客 任务"}},{q="谁是奥拉凯斯刺客？",a="奥拉凯斯刺客被描述为冷酷的杀手，他们以协同作战的危险突击部队形式活动。他们致命的作风使他们成为野外严重的威胁。",al={"谁是奥拉凯斯","谁是奥拉凯斯刺客","奥拉凯斯杀手"}},{q="瓦拉纳尔是谁？",a="瓦拉纳尔是位于岛屿东南边缘的定居点，也是维和人员的基地。这名斥候计划在返回瓦拉纳尔时，将你的协助记录在报告中。",al={"谁是瓦拉纳尔","什么是瓦拉纳尔","向瓦拉纳尔报告"}},{q="为什么必须处理奥拉凯斯刺客？",a="奥拉凯斯刺客对该地区的特工和旅行者构成了致命且迫在眉睫的危险。消灭他们对于保护盟军并确保生存是必要的。",al={"为什么对付奥拉凯斯","为什么要击杀奥拉凯斯刺客","奥拉凯斯威胁"}},{q="处理完这些刺客后会发生什么？",a="在与刺客的冲突结束后，这名斥候准备向瓦拉纳尔报告，并承认了你在行动中提供的关键援助。",al={"奥拉凯斯刺客 之后发生了什么","下一个任务 奥拉凯斯","向瓦拉纳尔报告任务"}},{q="谁承认了你在击败刺客时提供的帮助？",a="该任务涉及一名驻扎在野外监视敌对势力动向的盟军特工。感谢你对致命刺客的干预，这名斥候记录了你的贡献，以供指挥部参考。",al={"谁发布了 奥拉凯斯刺客","谁是这名斥候","斥候报告瓦拉纳尔"}}},fp="18,115,15.226.0,21.140.0,27.120.0,31.102.0,16.133.0,46.130.0,46.78.0,53.115.0"}
P.entries["quest:98545"] = {n="Leonid's Letter",s="Leonid's Letter 是一个送信任务，指引旅行者深入幽暗城。由于与希尔瓦娜斯·风行者过去的紧张关系，莱尼德本人不愿进入被遗忘者首都，因此雇佣了一名中立的信使，将一封信送给驻扎在贸易区的旧识地精 Glix Xizzix。",h="Leonid's Letter 是一个送信任务，指引旅行者深入幽暗城。由于与希尔瓦娜斯·风行者过去的紧张关系，莱尼德本人不愿进入被遗忘者首都，因此雇佣了一名中立的信使，将一封信送给驻扎在贸易区的旧识地精 Glix...",kw={"黑暗女王","格利克斯·希兹克斯","莱尼德","失物招领","纳克萨玛斯","密封的信","希尔瓦娜斯","贸易区","幽暗城"},ang={["faction:Horde"]="代表外来者进入被遗忘者首都，让部落冒险者可以轻松使用幽暗城贸易区的设施。",["race:Undead"]="莱尼德与黑暗女王的历史使他无法亲自踏入幽暗城，这突显了独立亡灵与希尔瓦娜斯忠诚者之间的政治紧张局势。"},sec={{t="外来者的差事",b="莱尼德需要一名信使将一封密封的信件送到幽暗城的一位熟人手中。由于与希尔瓦娜斯·风行者过去存在的摩擦和紧张关系，莱尼德选择不亲自踏入被遗忘者首都的大厅，而是委托一名路过的中立人员，在不引起警报的情况下通过城市守卫。"},{t="贸易区的旧识",b="收信人是 Glix Xizzix，一个在幽暗城贸易区做生意的机会主义地精。收到信件后，Glix 回忆起与莱尼德一起在天灾军团的要塞纳克萨玛斯阴影下生存的往事。虽然对莱尼德承诺的报酬感到惊讶和恼火，但 Glix 还是勉强从粗心的亡灵客户留下的失物招领中支付了酬金。"}},faq={{q="莱尼德是谁，为什么他不愿进入幽暗城？",a="莱尼德是一位经验丰富的士兵，与各派势力保持着微妙的关系。由于与希尔瓦娜斯·风行者之间复杂的过往，他避免直接进入幽暗城，而是依靠路过的冒险者为他送信给熟人。",al={"谁给了莱尼德的信","莱尼德·巴萨罗梅","莱尼德任务给予者"}},{q="格里克斯·希兹克斯 是谁？",a="格里克斯·希兹克斯 是一名驻扎在繁华的幽暗城贸易区的地精。他似乎在理发服务处附近经营，保留着健忘的亡灵顾客留下的失物招领。",al={"格里克斯·希兹克斯在哪里","谁是格里克斯·希兹克斯","幽暗城地精理发师"}},{q="莱尼德与黑暗女王之间有什么历史？",a="莱尼德承认他与被遗忘者的女妖之王希尔瓦娜斯·风行者之间有着“相当丰富的过往”。为了避免激怒她或她的守卫，他雇佣中立的第三方来处理他在城内的事务。",al={"莱尼德与黑暗女王的历史","莱尼德和希尔瓦娜斯"}},{q="莱尼德和 格里克斯 是怎么认识的？",a="格里克斯 记得莱尼德是在对抗天灾军团的激烈战争中久经沙场的退伍军人，并回忆起可怕的要塞纳克萨玛斯向他们倾泻毁灭的岁月。",al={"格里克斯·希兹克斯与莱尼德和纳克萨玛斯","格里克斯和莱尼德怎么认识的"}},{q="为什么 格里克斯 用失物招领中的物品作为报酬？",a="莱尼德告诉信使 格里克斯 会乐意给小费，但 格里克斯 并没有做出这种承诺。尽管不情愿，这位地精还是提供了从沙龙的失物招领中搜集到的、由健忘的被遗忘者客户遗留下的奇特小饰品。",al={"格里克斯的任务奖励","为什么是失物招领"}},{q="这封信被送到了哪里？",a="这封信被带到了被遗忘者的首都幽暗城，直接送到了商人、工匠和地精在皇家药剂师学会和城市守卫的注视下进行交易的贸易区。",al={"莱尼德的信送到哪里","贸易区送信"}}},fp="15,268,20.252.0,33.318.0,47.236.0,19.171.0,44.206.0,39.142.0,51.208.0,30.207.0"}
P.entries["quest:98574"] = {n="Hallowed Memorandum",s="“神圣备忘录”是一份书面传唤，指示寒脊山谷中初出茅庐的侏儒牧师前往安威玛尔拜见布兰斯托克·卡德尔。它标志着他们精神修行的开始，将圣光描绘成一个非常适合侏儒的智力和好奇心的哲学谜题。",h="“神圣备忘录”是一份书面传唤，指示寒脊山谷中初出茅庐的侏儒牧师前往安威玛尔拜见布兰斯托克·卡德尔。它标志着他们精神修行的开始，将圣光描绘成一个非常适合侏儒的智力和好奇心的哲学谜题。",kw={"安威玛尔","布兰斯托克·卡德尔","寒脊山谷","丹莫罗","侏儒牧师","神圣备忘录","圣光"},ang={["class:Priest"]="这份备忘录标志着寒脊山谷正式牧师教学的开始，向新晋的治疗者介绍了圣光的哲学。",["race:Gnome"]="接近圣光的侏儒在精神学习中带来了敏锐的智力和好奇心，将神圣的奥秘视为与信仰一起思考的谜题。"},sec={{t="前往安威玛尔的传唤",b="当在寒脊山谷协助盟友时，有前途的侏儒见习生会收到“神圣备忘录”，这是一份指导他们前往安威玛尔寻找布兰斯托克·卡德尔的入门信件。作为精神学习的号召，这张便条邀请有抱负的牧师开始他们在丹莫罗的正式教导。"},{t="信仰之谜",b="在出示备忘录后，布兰斯托克·卡德尔欢迎这位新手加入。他解释说，钻研圣光并非一项死板的技术工艺，而是一个需要好奇心、敏锐智力以及智力与情感和谐统一的深奥谜题。通过沉思和实践，学生们学会将这些神圣的奥秘引导为恢复性的修补和神圣的惩戒。"}},faq={{q="是谁寄送了“神圣备忘录”？",a="这份备忘录是由你在寒脊山谷附近协助时的一位当地盟友转交的，它源自居住在安威玛尔内的牧师训练师布兰斯托克·卡德尔。",al={"谁给了我备忘录","谁发送了神圣备忘录","便条从哪里来"}},{q="布兰斯托克·卡德尔是谁？",a="布兰斯托克·卡德尔是一位驻扎在寒脊山谷安威玛尔内的矮人牧师训练师。他指导初出茅庐的牧师了解圣光，并利用神圣的力量来治愈伤口或打击邪恶。",al={"布兰斯托克是谁","布兰斯托克·卡德尔 安威玛尔"}},{q="侏儒是如何看待圣光的？",a="布兰斯托克解释说，侏儒的好奇心和智力是理解圣光的天然途径。他鼓励人们将其视为一个结合了思想与情感的哲学谜题，而不是将其作为一种严格的技术工艺来对待。",al={"侏儒可以成为牧师吗","侏儒与圣光的联系","侏儒如何看待圣光"}},{q="布兰斯托克教导了关于圣光的什么内容？",a="布兰斯托克将圣光描述为不仅仅是一门精确的技术学科，而是一个谜题，它通过结合个人的思想和内在情感来提供实际的祝福和人生课程。",al={"根据布兰斯托克的说法什么是圣光","圣光之谜 布兰斯托克"}},{q="布兰斯托克提供哪些技能教导？",a="一旦牧师开始理解圣光，布兰斯托克就会提供指导，教导如何将这种力量直接引导为防御性的治疗祈祷和对邪恶者的神圣打击，以此换取微薄的捐赠。",al={"布兰斯托克教什么","牧师训练师能教什么"}},{q="在哪里可以找到布兰斯托克·卡德尔？",a="安威玛尔是位于丹莫罗寒脊山谷中心地带的中央堡垒和欢迎大厅，为矮人和来访的侏儒提供训练师和避难所。",al={"安威玛尔在哪里","布兰斯托克位置"}}},fp="19,212,21.209.0,20.325.0,33.150.0,25.180.0,38.177.0,42.154.0,45.169.0,37.202.0"}
P.entries["quest:98575"] = {n="Tainted Tablet",s="Tainted Tablet是试炼谷的一项初始任务，指引有志向的施法者前往大兽穴寻找纳托克。它展现了杜隆塔尔术士们务实而谨慎的思想，尽管过去留下了挥之不去的耻辱，但他们仍试图驾驭虚空来铸就自己的命运。",h="Tainted Tablet是试炼谷的一项初始任务，指引有志向的施法者前往大兽穴寻找纳托克。它展现了杜隆塔尔术士们务实而谨慎的思想，尽管过去留下了挥之不去的耻辱，但他们仍试图驾驭虚空来铸就自己的命运。",kw={"杜隆塔尔","纳托克","虚空","被污染的石板","大兽穴","试炼谷","术士"},ang={["class:Warlock"]="Tainted Tablet标志着杜隆塔尔的新手术士们正式被引荐给他们的训练师纳托克，并敦促他们驾驭虚空，而不是恐惧它。",["faction:Horde"]="虽然萨尔领导的新部落对恶魔腐化心存戒备，但潜伏在大兽穴等地方的施法者宣称，他们可以安全地驾驭虚空力量，从而为他们的人民确保未来。",["race:Orc"]="鉴于恶魔契约在德拉诺留下的灾难性遗产，练习邪能魔法在兽人中仍然备受争议，这迫使杜隆塔尔的术士们不得不保持秘密与大胆。"},sec={{t="黑暗的召唤",b="Tainted Tablet是传送给刚抵达试炼谷并开始旅程的见习施法者的一条铭文信息。这块石板经由不安的营地看守人之手，传达了纳托克的召唤，这位术士训练师在大兽穴的阴影角落里安了家。信件邀请读者放下普通的部落职责，去探索更深层、被禁忌的魔法洪流。"},{t="驾驭虚空",b="在回应召唤后，纳托克坦率地谈到了兽人和虚空之间动荡的历史。他认为，强者应当掌控自己的命运，而不是因为羞耻或恐惧而放弃这些不稳定的能量。在他眼中，当传统的酋长们举步维艰时，能够以狡诈手段驾驭虚空实体的施法者将会脱颖而出。然而，由于恐惧者往往会轻易攻击他们无法理解的事物，他警告说，必须时刻严加守护这种力量。"}},faq={{q="什么是污染石板？",a="污染石板是传达给试炼谷见习施法者的一份书面召唤。它指示他们去寻找他们的职业训练师纳托克，他就在大兽穴内等候。",al={"什么是被污染的石板","被污染的石板任务","石板的目的"}},{q="谁发送了污染石板？",a="这块石板由纳托克发送，他是一位驻扎在试炼谷大兽穴内的兽人术士训练师。他用它来向新来的见习施法者介绍自己，并邀请他们接受指导。",al={"谁写了石板","纳托克是谁","谁发送了石板"}},{q="在哪里可以找到纳托克？",a="纳托克居住在大兽穴内，这是一处隐藏在试炼谷中的洞穴，人们在那里远离视线地练习黑魔法和专业技能。",al={"纳托克在哪里","大兽穴在哪里","如何找到纳托克"}},{q="为什么纳托克警告要严加守护你的力量？",a="纳托克告诫说，普通人会恐惧他们无法理解的力量，并经常在恐慌中反击。由于兽人在过去深受恶魔腐化的苦难，术士们必须守护好他们的技艺，并谨慎行事。",al={"为什么术士要隐藏","为什么守护力量","为什么术士要保密"}},{q="纳托克对练习邪能魔法有什么看法？",a="纳托克认为，当传统的领导者举步维艰时，那些掌握了虚空实体的人能够开辟自己的道路，掌握权力来塑造他们人民的命运，而不是成为命运的奴隶。",al={"纳托克的目标是什么","纳托克的哲学","为什么要使用虚空力量"}},{q="谁给了你污染石板？",a="试炼谷的一位当地任务发布者传递了这块石板，他公开承认对邪能施法者感到不安，但同时也认识到传递纳托克的召唤是必要的。",al={"谁递交了石板","谁把石板交给我"}}},fp="14,197,14.271.0,21.390.0,27.144.0,28.150.0,26.129.0,50.243.0,46.197.0,33.140.0"}
P.entries["quest:98576"] = {n="Glyphic Parchment",s="Glyphic Parchment 是发给在“试炼谷”的法师新手的入门召唤函。这份书面信函由“高内克”转交，指引新手前往“大兽穴”附近的巨魔法师训练师“迈安”处，开始他们的奥术修行。",h="Glyphic Parchment 是发给在“试炼谷”的法师新手的入门召唤函。这份书面信函由“高内克”转交，指引新手前往“大兽穴”附近的巨魔法师训练师“迈安”处，开始他们的奥术修行。",kw={"奥术","杜隆塔尔","雕文羊皮纸","高内克","法师","迈安","大兽穴","试炼谷"},ang={["class:Mage"]="这封信标志着你正式被认可为一名 A Student of the Arcane，指引你前往“迈安”处开始学习并扩充你的法术书。",["faction:Horde"]="“试炼谷”的导师制确保了即使是奥术这种不稳定的技艺，也能通过纪律来培养，从而加强部落的未来。",["race:Troll"]="“迈安”代表了“暗矛巨魔”日益发展的奥术传统，她贡献出自己的宇宙见解来指导同胞巨魔和盟军新兵。"},sec={{t="学习的召唤",b="虽然新兵要在“杜隆塔尔”的当地害虫面前证明他们的身体素质，但那些拥有奥术天赋的人不能仅仅依靠蛮力。“高内克”会递交一份刻有符文的书面通知，指示法师新手去找“迈安”，由她负责部落新兵早期的魔法指导。"},{t="奥术之道",b="“迈安”驻扎在“大兽穴”入口外，磨练着年轻施法者的志向。她不主张鲁莽地释放原始魔法，而是强调耐心、时机和深思熟虑的智慧。在她的指导下，新手学会将宇宙视为可以编织的纤细丝线，而不是任其爆发的狂暴风暴。"}},faq={{q="谁寄出了 雕文羊皮纸？",a="这份羊皮纸是由位于“试炼谷”的“大兽穴”附近的法师训练师“迈安”发送的。“高内克”保管着这封信，一旦法师新手开始他们的试炼，他就会将其交给他们。",al={"谁写了 雕文羊皮纸","谁发送了这个","羊皮纸作者"}},{q="在哪里可以找到“迈安”？",a="“迈安”位于“杜隆塔尔”的“试炼谷”，和其他职业导师一起驻扎在“大兽穴”的入口外。",al={"迈安在哪里","迈安的位置","寻找迈安"}},{q="这个任务的目的是什么？",a="它旨在向法师新手介绍他们的职业训练师。与“迈安”对话将开启你对奥术艺术的正规指导，从而解锁新法术和基础训练。",al={"雕文羊皮纸有什么用","为什么要进行这个任务","任务目标"}},{q="“迈安”对魔法的哲学理念是什么？",a="“迈安”认为奥术魔法需要智慧、克制和审慎的耐心。一位有效的法师不会冲动行事，而是会仔细观察，并在精确的时刻以适当的反应进行攻击。",al={"迈安教什么","迈安的背景故事"}},{q="为什么一位巨魔会在“试炼谷”训练法师？",a="“试炼谷”欢迎年轻的兽人和“暗矛巨魔”加入部落。“暗矛巨魔”施法者，比如“迈安”，贡献出她们的智慧和对宇宙力量的掌控来教导初出茅庐的修行者。",al={"为什么有巨魔法师","巨魔与奥术","兽人地区的巨魔训练师"}},{q="谁把羊皮纸交给玩家？",a="“高内克”是位于“试炼谷”中央营地的主要试炼监督者，当你完成早期任务并返回他身边时，他会把羊皮纸交给你。",al={"谁给予了 雕文羊皮纸","高内克的任务"}}},fp="17,177,18.255.0,21.281.0,32.116.0,26.102.0,34.173.0,37.139.0,54.173.0,41.138.0"}
P.entries["quest:98581"] = {n="Archaic Rune",s="Archaic Rune是丹莫罗为新手矮人萨满提供的入门任务。这块神圣的石板上灌注了来自远古蛮锤铭文的元素之力，向年轻的入门者们展示了他们的元素传承。将这块石头送到安威玛尔的提奥·蛮锤手中，标志着他们正式开始学习大地、空气、火焰和水的之道。",h="Archaic...",kw={"安威玛尔","古老的符文","铜须","寒脊山谷","元素","萨满","提奥·蛮锤","蛮锤氏族"},ang={["class:Shaman"]="Archaic Rune代表了矮人萨满精神旅程的第一步，验证了他们的元素共鸣，并将他们引向其首位导师。",["faction:Alliance"]="蛮锤导师将萨满艺术带到丹莫罗扩大了联盟的精神修行，使元素传统与圣光之道得以并存。",["race:Dwarf"]="这枚符文标志着矮人氏族间一次重要的文化交流，蛮锤矮人与寒脊山谷的铜须同胞分享了他们古老的精神传统。"},sec={{t="古老的铭文",b="寒脊山谷的冒险新手在安威玛尔附近协助当地盟友后，会发现Archaic Rune。这块石头上刻有蛮锤氏族风格的独特文字，并且可以清晰地感受到其中充盈着远古的元素力量。这枚符文不仅是一件石刻遗物，更是一次元素试炼：只有那些对原始灵魂有着天生共鸣的人，才能解读其风化表面上镌刻的文字。对于那些能够解读这些文字的人来说，它提供了明确的指引，让他们前往附近矮人哨站寻求正式的教导。"},{t="丹莫罗的蛮锤智慧",b="在安威玛尔的大厅内，蛮锤萨满提奥·蛮锤接收了这块铭文石。世世代代以来，萨满元素之术主要由生活在风蚀山峰间的蛮锤氏族所保存。如今，这些传统已开始在铁炉堡和丹莫罗的铜须矮人中扎根。提奥·蛮锤成为了两个矮人文化之间的重要桥梁，他欢迎那些展现出与元素沟通天赋的年轻入门者，并为他们提供关于大地、空气、火焰和水之道的正式教导。"}},faq={{q="什么是古老符文？",a="古老符文是一块刻有古老蛮锤文字并灌注了元素之力的古代石板。它被分发给寒脊山谷中前途无量的新冒险者，作为对其精神潜力的初步考验。如果一名入门者拥有能够解读符文的内在感应，这就证实了他们召唤萨满之道的使命，并指引他们前往安威玛尔寻找训练师。",al={"古老符文任务","这个符文是什么","古老符文物品"}},{q="是谁雕刻了古老符文？",a="符文上的铭文是采用蛮锤氏族的传统风格雕刻的。它由居住在安威玛尔内的蛮锤萨满提奥·蛮锤发出，他利用这块刻字石来识别并联系那些拥有与元素灵魂先天连接的新晋入门者。",al={"谁制作了古老符文","符文起源","蛮锤符文制造者"}},{q="提奥·蛮锤是谁？",a="提奥·蛮锤是一名蛮锤矮人，也是驻扎在寒脊山谷安威玛尔内的萨满训练师。他来到丹莫罗是为了帮助分享其氏族祖传的萨满教义给铜须矮人，指导新的修行者学习大地、火焰、水和空气之道。",al={"提奥·蛮锤是谁","安威玛尔提奥·蛮锤","安威玛尔萨满训练师"}},{q="为什么蛮锤的教义要与铜须矮人分享？",a="虽然萨满艺术在过去很长一段时间里传统上一直由蛮锤氏族保存和守护，但这些元素修行之法最近也已转交到铜须矮人手中并开始普及。像提奥·蛮锤这样的导师挺身而出，教导铁炉堡的矮人如何与元素灵魂沟通并向其致敬。",al={"为什么矮人会成为萨满","铜须蛮锤萨满","矮人萨满背景故事"}},{q="我应该把古老符文带到哪里？",a="符文必须交给位于寒脊山谷安威玛尔主营地内的提奥·蛮锤。向他呈交符文展示了你引导元素的能力，并能开启你后续基础萨满法术的训练。",al={"哪里交还古老符文","古老符文交还","寻找提奥·蛮锤"}},{q="解读符文意味着什么？",a="古老符文中灌注了古代矮人文字的元素能量。只有对元素力量有着天生共鸣的入门者才能破译其文字。成功解读它证明了冒险者拥有成为真正萨满的自然天赋和精神准备。",al={"为什么我能读懂符文","符文含义","解读古老符文"}}},fp="12,186,22.331.0,31.441.0,25.302.0,28.216.0,23.259.0,67.243.0,33.193.0,35.233.0"}
P.entries["quest:986"] = {n="失踪的主人",s="“失踪的主人”这一任务要求联盟冒险者收集材料，以协助寻找在黑海岸荒野中失踪的暗夜精灵沃科尔。奥伯丁的特伦希斯提出要编织一件附魔伪装斗篷来保护救援者，这需要从海岸最凶猛的月夜猛虎身上获取毛皮。",h="“失踪的主人”这一任务要求联盟冒险者收集材料，以协助寻找在黑海岸荒野中失踪的暗夜精灵沃科尔。奥伯丁的特伦希斯提出要编织一件附魔伪装斗篷来保护救援者，这需要从海岸最凶猛的月夜猛虎身上获取毛皮。",kw={"失踪的主人","奥伯丁","黑海岸","优质月夜猛虎毛皮","格里姆克劳","月夜猛虎","特伦希斯","沃科尔","急弯河"},ang={["class:Druid"]="德鲁伊们定能领会特伦希斯对月夜猛虎自然潜行能力的尊重，并将其野性本质转化为保护性的伪装。",["class:Hunter"]="猎人们会理解沃科尔与格里姆克劳之间的羁绊，以及追踪和猎杀黑海岸的雌雄猛虎所需的高超技巧。",["race:NightElf"]="搜寻沃科尔的过程，体现了暗夜精灵在黑海岸那未受开垦的荒野中，守护族人和野生伙伴的职责。"},sec={{t="深入荒野的搜寻",b="在追踪黑海岸沿岸的威胁时，奥伯丁的特伦希斯对沃科尔及其伙伴格里姆克劳的安危感到担忧。由于该地区充斥着好斗的掠食者和受到腐蚀的野生动物，深入南部地区向来极其危险。特伦希斯没有贸然派遣毫无防备的侦察兵，而是制定了一个计划：制作一件灌注了野性幻象的防护斗篷。"},{t="狮群之皮",b="为了编织一件能够迷惑黑海岸野兽的斗篷，普通的兽皮是不够的。特伦希斯需要专门从成年的雄性或雌性月夜猛虎身上获取优质月夜猛虎毛皮。这些强大的大猫在奥伯丁南部的林地，靠近急弯河一带游荡，一直延伸到灰谷的森林边缘。"},{t="精细的魔法",b="成品斗篷利用月夜猛虎的皮毛和自然附魔，让穿着者在搜寻沃科尔时能不受阻碍地穿过敌对区域。然而，特伦希斯警告说，这种幻象十分脆弱：进行剧烈活动或战斗会打破附魔，使搜寻者暴露在外。"}},faq={{q="沃科尔是谁？",a="沃科尔是一位在黑海岸南部荒野失踪的暗夜精灵侦察兵或追踪者。他的伙伴格里姆克劳和奥伯丁的特伦希斯正在寻找他的下落，从而引发了这次搜寻任务。",al={"沃科尔是谁","沃科尔背景故事","失踪的主人沃科尔"}},{q="谁提供了这个任务？",a="特伦希斯，一位驻扎在黑海岸奥伯丁定居点的暗夜精灵，在冒险者协助他处理了早先的当地问题后，便提供了这个任务。",al={"任务发放者","失踪的主人任务领取","特伦希斯位置"}},{q="在哪里可以找到雄性和雌性月夜猛虎？",a="这些成年的月夜猛虎在黑海岸南部游荡，特别是在急弯河河岸附近，以及更南边接近灰谷边界的地方。",al={"优质月夜猛虎毛皮位置","哪里寻找月夜猛虎","急弯河猫科动物"}},{q="这件斗篷有什么作用？",a="特伦希斯打算制作一件附魔斗篷，将穿着者隐藏起来，使其免受黑海岸敌对野兽的攻击，从而能够在不频繁引发战斗的情况下寻找沃科尔。",al={"斗篷有什么作用","特伦希斯斗篷","斗篷附魔"}},{q="为什么特伦希斯需要特定的毛皮？",a="特伦希斯说他需要五张优质毛皮，这些毛皮必须取自雄性或雌性月夜猛虎，这样才有足够的材料来制作斗篷。",al={"为什么是雄性和雌性猛虎","为什么要优质毛皮"}},{q="这种伪装斗篷有限制吗？",a="是的。特伦希斯警告说，这种附魔很脆弱。与他人交谈是允许的，但剧烈的互动或战斗会迅速驱散幻象。",al={"幻象会失效吗","斗篷限制"}}},fp="13,180,23.289.0,18.236.0,14.245.0,14.150.0,21.113.0,49.135.0,30.157.0,39.87.0,43.148.0"}
P.entries["quest:98601"] = {n="A Difficult Path",s="“A Difficult Path”标志着被遗忘者圣骑士在丧钟镇正式开始训练。在处理了从墓穴中爬出来的无脑亡灵后，新觉醒的圣光勇士会被指引去见教堂里的Aramis Hammerhand，去面对在亡灵之躯中使用圣光之力的痛苦现实。",h="“A Difficult Path”标志着被遗忘者圣骑士在丧钟镇正式开始训练。在处理了从墓穴中爬出来的无脑亡灵后，新觉醒的圣光勇士会被指引去见教堂里的Aramis...",kw={"艰难的道路","阿拉米斯·锤手","祝圣卷轴","丧钟镇","被遗忘者圣骑士","圣光","暗影牧师萨维斯","提瑞斯法林地"},ang={["class:Paladin"]="这个任务代表了被遗忘者圣骑士的基础试炼，它将圣光之力定义为并非轻松的祝福，而是一场关于纪律和耐力的痛苦磨砺。",["race:Undead"]="对于被遗忘者来说，召唤圣光证明了虔诚与纪律可以在肉体死亡后依然存在，即使这种魔法会灼烧引导它的容器。"},sec={{t="一份发臭的卷轴",b="当一名刚刚苏醒的被遗忘者圣骑士清理完墓穴外的野性亡灵后，暗影牧师萨维斯会递交一份意想不到的物品。这份祝圣卷轴散发出的圣光能量如此强烈，以至于这位暗影牧师明显退缩了，并直截了当地让持有者走开。对于一个信奉暗影与腐朽的修行者来说，圣光本身的气息就像火焰一样灼人。"},{t="圣火的试炼",b="在丧钟镇那座饱经摧残的教堂里，坐镇着被遗忘者圣骑士训练师Aramis Hammerhand。其他种族可以自然且愉悦地运用圣光，但亡灵若想召唤圣光，则必须忍受灼烧般的剧痛。Aramis并未试图减轻这种痛苦：通过腐烂的躯体引导圣光之力是一种纯粹的折磨，但他要求他的弟子拥抱这种痛苦，而不是退缩，将其作为一种淬炼他们新得决心的熔炉。"}},faq={{q="为什么暗影牧师萨维斯不喜欢这份卷轴？",a="暗影牧师萨维斯致力于暗影魔法的研究，并保护着他的亡灵同胞。祝圣卷轴散发着纯粹的圣光能量，这从本质上对亡灵躯体有害，且会让暗影的修行者感到深深的不安。",al={"萨维斯 圣光卷轴","为什么萨维斯感到不安","暗影牧师对卷轴的反应"}},{q="被遗忘者真的能在不死亡的情况下使用圣光吗？",a="被遗忘者可以通过纯粹的意志力和信仰来运用圣光，但这会给他们带来剧烈的痛苦，尤其是在引导圣光治疗自己或他人时。这需要极强的精神耐力来维持引导。",al={"被遗忘者圣骑士背景故事","亡灵使用圣光","圣光会伤害被遗忘者吗"}},{q="谁是阿拉米斯·锤手？",a="阿拉米斯·锤手是驻扎在丧钟镇教堂的圣骑士训练师。他指导刚复活的被遗忘者圣骑士，教导他们如何在亡灵状态下忍受使用圣光的剧痛，并将其锻造成有效的武器。",al={"谁是阿拉米斯·锤手","丧钟镇圣骑士训练师","阿拉米斯的角色"}},{q="这个任务在哪里进行？",a="任务开始于丧钟镇中心空地上的暗影牧师萨维斯，并在几步之遥的村庄废弃教堂内结束，阿拉米斯·锤手就在那里。",al={"艰难的道路在哪里","任务地点","丧钟镇教堂在哪里"}},{q="我必须阅读祝圣卷轴才能完成任务吗？",a="不需要，阅读卷轴并非完成目标的必要条件；直接与教堂内的阿拉米斯·锤手交谈即可推进你的训练。",al={"阅读祝圣卷轴","是否需要阅读卷轴","跳过阅读卷轴"}},{q="为什么这条道路被称为“艰难的”？",a="这个名字反映了被遗忘者圣骑士残酷的修行之路。当圣光的其他战士从信仰中获得安慰与慰藉时，亡灵圣骑士每次施放祝福或打击敌人时，都必须忍受炽热的圣火在死尸躯体中奔涌的痛苦。",al={"为什么是艰难的道路","任务名称的含义"}}},fp="16,234,16.283.0,25.384.0,49.168.0,54.180.0,25.165.0,33.159.0,63.124.0,35.216.0"}
P.entries["quest:98731"] = {n="Blessings of the Great Cat Spirit",s="得到巨豹之灵的祝福后，你被告知要回到德迪利特身边。他感受到你身上新添的狡黠与凶猛，并说你现在可以学习召唤猎豹之灵了。",h="得到巨豹之灵的祝福后，你被告知要回到德迪利特身边。他感受到你身上新添的狡黠与凶猛，并说你现在可以学习召唤猎豹之灵了。",kw={"祝福","猎豹之灵","狡黠","德迪利特","凶猛","巨豹之灵","速度","潜行"},sec={{t="德迪利特的感知",b="德迪利特在空中做了个手势，向你致意，一股力量的光环随即笼罩了他。他在你身上感受到了猎豹的狡黠与凶猛，以及你对潜行和速度的全新领悟。现在，他可以教你凝聚这份天性，召唤猎豹之灵。"}},faq={{q="德迪利特为什么要见我？",a="得到巨豹之灵的祝福后，你被告知要回到德迪利特身边，接受他的进一步指点。",al={"为何回到德迪利特身边","德迪利特 猎豹祝福","德迪利特有何要求"}},{q="德迪利特在我身上感受到了什么？",a="他感受到了猎豹的狡黠与凶猛，并相信你已领悟了掌握猎豹天性所需的潜行与速度。",al={"我有何变化","猎豹之灵的力量","德迪利特感受到了什么"}},{q="我现在能向德迪利特学习什么？",a="德迪利特说，你可以学习凝聚自己的狡黠，召唤猎豹之灵。",al={"召唤猎豹之灵","学习猎豹天性","德迪利特接下来的指点"}}},fp="33,179,20.263.0,33.107.0,31.121.0,35.83.0"}
P.entries["quest:98738"] = {n="Blessings of the Great Windborne Cat Spirit",s="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，标志着受训者在与 Zephras 的巨豹之灵交流后的回归。在吸收了野猫的潜行、速度和凶猛之后，受训者向德迪利特展示他们新觉醒的光环，以接受进一步的精神指导。",h="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，标志着受训者在与 Zephras...",kw={"风行巨豹之灵的祝福","猫形态","德迪利特","德鲁伊","大猫灵","申多雷","潜行","泽弗拉斯"},ang={["class:Druid"]="这个任务标志着掌握猫科掠食本能的一个重要里程碑，赋予了德鲁伊与猫沟通并化身为猫所需的潜行、速度和凶猛。",["race:Skyborne"]="灵魂特别认出受训者是年轻的 shen'dorei，并在他们学习驾驭野性力量时，从 Zephras 提供风与影的指引。"},sec={{t="与风之灵的沟通",b="Blessings of the Great Windborne Cat Spirit 标志着与 Zephras 的巨豹之灵进行神圣沟通的顶峰。在寻找到这位风之守护者并赢得其青睐后，受训者回到德迪利特身边，展示他们已经内化了野猫的狡黠、掠食者的潜行和凶猛。"},{t="德迪利特的教导",b="在获得祝福后展示自己时，德迪利特会进行微妙的身体动作来解读受训者新觉醒的光环。德迪利特感应到编织在他们灵魂中的猫科动物本能，承认这位候选人终于准备好集中精神，呼唤猫的真正形态。"}},faq={{q="什么是 风行巨豹之灵的祝福？",a="风行巨豹之灵的祝福 是一项成年礼任务，受训者在寻找并获得巨豹之灵的祝福后，回到德迪利特身边完成他们的精神交流。",al={"这个任务是什么","猫的祝福任务","猫灵任务"}},{q="谁是德迪利特？",a="德迪利特是一位导师，他派遣受训者去与巨豹之灵沟通。在他们返回后，他会引导仪式手势来感知这种转变，确认受训者是否已经吸收了引导猫科动物天性所需的潜行、速度和狡黠。",al={"谁是德迪利特","德迪利特背景"}},{q="谁是巨豹之灵？",a="巨豹之灵是位于 泽弗拉斯 的古老守护灵。它在受训者返回继续接受指导之前，会将精神恩惠、风的速度和掠食者的潜行赐予值得的受训者。",al={"什么是猫灵","大风之猫灵"}},{q="泽弗拉斯 位于何处？",a="泽弗拉斯 是巨豹之灵的家园，也是有前途的受训者前往寻求建议、接受风与影的祝福并学习猫科形态基础知识的地方。",al={"泽弗拉斯在哪里","猫灵位置"}},{q="为什么灵魂称呼受训者为 申多雷？",a="巨豹之灵直接称呼受训者为年轻的 申多雷，这指出了寻求与自然之灵交流并掌握野性变形的修行者的祖先传承。",al={"谁是神多雷","年轻的神多雷"}},{q="猫灵的祝福赋予了什么？",a="这种祝福赋予了猫科形态的狡黠、速度和潜行。在获得祝福后，受训者获得了德迪利特的认可，可以集中他们内心的凶猛并呼唤猫的真正本性。",al={"祝福赋予什么","猫灵祝福效果"}}},fp="43,231,35.196.0,22.218.0,52.119.0,16.223.0,28.184.0,25.181.0,55.193.0,47.203.0"}
P.entries["quest:98739"] = {n="巨豹之灵的祝福",s="接受巨豹之灵的祝福后，德迪利特让你回来。他感受到你身上新生的狡黠与凶猛，并说你现在可以学习召唤猫灵。",h="接受巨豹之灵的祝福后，德迪利特让你回来。他感受到你身上新生的狡黠与凶猛，并说你现在可以学习召唤猫灵。",kw={"祝福","blessings of the great cat spirit","狡黠","德迪利特","凶猛","巨豹之灵","迅捷","潜行"},sec={{t="回到德迪利特身边",b="接受巨豹之灵的祝福后，德迪利特让你回去找他。你抵达时，他朝你上方挥了挥手，察觉到你眼中流露出猫的狡黠与凶猛。他说，你现在已经理解了化身为猫所需的潜行与迅捷。"}},faq={{q="我该和谁交谈？",a="回到德迪利特身边与他交谈。",al={"该和谁交谈","找谁说话"}},{q="我得到了什么祝福？",a="你得到了巨豹之灵的祝福。",al={"巨豹祝福","猫灵祝福"}},{q="德迪利特察觉到我身上有什么？",a="德迪利特察觉到你身上有猫的狡黠与凶猛，也感受到你对其潜行与迅捷的理解。",al={"德迪利特察觉到什么","猫的本性"}},{q="我现在能学什么？",a="德迪利特说，你现在可以学习集中狡黠之力，召唤猫灵。",al={"召唤猫灵","现在该做什么"}}},fp="33,183,18.253.0,18.38.0,28.55.0,31.110.0,21.87.0"}
P.entries["quest:98815"] = {n="Highland Hides",s="Highland Hides是由詹姆斯·哈洛兰委托的一份探险合同，他是一位在米奈希尔港工作的制皮师。为了从高地多雾的山地沼泽中寻求优质的材料，哈洛兰用精制的皮革制品来交换丛林迅猛龙坚韧的皮。",h="Highland Hides是由詹姆斯·哈洛兰委托的一份探险合同，他是一位在米奈希尔港工作的制皮师。为了从高地多雾的山地沼泽中寻求优质的材料，哈洛兰用精制的皮革制品来交换丛林迅猛龙坚韧的皮。",kw={"高地兽皮","高地","詹姆斯·哈洛兰","米奈希尔港","迅猛龙皮","制皮师","丛林迅猛龙","湿地"},ang={["class:Hunter"]="进入高地山地沼泽的猎人们会发现丛林迅猛龙这样的可怕野兽，它们坚韧的皮需要精准的追踪和干净利落的狩猎技巧。",["faction:Alliance"]="米奈希尔港是湿地的一个主要联盟港口，像詹姆斯·哈洛兰这样的商人们就在这里为前往周围危险沼泽的旅行者提供装备。"},sec={{t="制皮师的机会",b="詹姆斯·哈洛兰是一位在米奈希尔港口小镇工作的熟练制皮师，他一直在留意异域的制作材料。当听说有一支探险队正在高地探索被遗忘的遗迹时，哈洛兰没怎么去关注古代历史，反而更在意那些在山地沼泽中潜行的凶猛野兽。他敏锐地察觉到了这些野生动物的商业和制作价值，于是委托勇敢的冒险者深入迷雾笼罩的山峰，带回上等的毛皮。"},{t="高地的野兽",b="在高地潜伏的动物群中，丛林迅猛龙是以适应崎岖沼泽地形而闻名的掠食者。它们坚韧且纹理独特的皮深受工匠的喜爱，可用于专业的皮革加工。哈洛兰指派旅行者追踪这些生物，并带回四张完好的皮，他将用这些皮为自己工作室的作品制作精致的细节装饰和边缘饰品。"}},faq={{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是一位驻扎在米奈希尔港的当地制皮师和工匠。他从事皮革和油脂加工，寻找来自湿地和周围高地的奇异野兽的优质皮，以此来制作精美的饰边和护甲。",al={"谁发布了高地皮革任务","詹姆斯·哈洛兰是谁","米奈希尔港的制皮师"}},{q="为什么詹姆斯·哈洛兰需要这些皮？",a="哈洛兰寻求丛林迅猛龙的皮，是因为它们出色的耐用性和纹理。他认为这些是他经手过的最好的皮革之一，并用它们为皮制品的饰边增添了惊人的细节。",al={"高地皮革的用途","为什么詹姆斯需要迅猛龙皮","迅猛龙皮的用途"}},{q="在哪里可以找到丛林迅猛龙？",a="丛林迅猛龙栖息在高地的山地沼泽中，潜伏在探险队目前正在考察的古代遗迹附近的崎岖荒野中。",al={"丛林迅猛龙在哪里","丛林迅猛龙位置","迅猛龙在哪里"}},{q="哈洛兰提到的遗迹是什么？",a="高地拥有一处被遗忘的遗迹，目前正由一支探险队进行调查。虽然像哈洛兰这样的工匠关注的是野生动物，但学者和探险家们却深入研究了该地区的古代秘密。",al={"高地有什么遗迹","高地探险遗迹","谁在探索高地"}},{q="这次狩猎是为团队准备的吗？",a="哈洛兰建议带上装备精良的同伴。高地的山地沼泽栖息着凶猛的野生动物，这使得针对丛林迅猛龙这类掠食者的狩猎对于孤身一人的旅行者来说危机四伏。",al={"高地皮革是否危险","高地皮革需要组队吗","做高地皮革需要同伴吗"}},{q="詹姆斯·哈洛兰提供什么交易？",a="为了换取四张原始的丛林迅猛龙皮，哈洛兰会提供他工作室定制的优质皮制品，让冒险者可以选择一件适合他们旅程的装备。",al={"哈洛兰交易什么","高地皮革奖励背景"}}},fp="14,155,22.329.0,23.280.0,22.196.0,41.123.0,35.117.0,36.173.0,34.144.0,40.143.0"}
P.entries["quest:98823"] = {n="Earthen Echo",s="大地之环请你将一件奇异的泰坦圣物交给莫高雷西北部的Muln Earthfury。上面的雕纹或许蕴藏着有关地下遗迹与失落之地的智慧。",h="大地之环请你将一件奇异的泰坦圣物交给莫高雷西北部的Muln Earthfury。上面的雕纹或许蕴藏着有关地下遗迹与失落之地的智慧。",kw={"earthen echo","大地之环","莫高雷","muln earthfury","碎片","观天者台地","泰坦机械","泰坦圣物"},sec={{t="交给长者的圣物",b="一位不知名的观察者认为，泰坦圣物并非普通的雕刻品，并催促你将它交给Muln Earthfury。你可以在莫高雷西北部的观天者台地找到他，他与大地之环议会同在那里。长者们或许会研究它，因为它的含义可能涉及地下遗迹与失落之地。"},{t="碎片的记忆",b="在观天者台地，Muln Earthfury发现，碎片中传出一个声音，仿佛来自世界本身。其中的光芒承载着记忆与历史的片段。大地之环将守护并研究这台泰坦机械，待他们能够理解其中的讯息时，再分享它揭示的内容。"}},faq={{q="我该把泰坦圣物交给谁？",a="将泰坦圣物交给Muln Earthfury，他与大地之环议会同在莫高雷西北部的观天者台地。",al={"圣物交给谁","muln earthfury圣物","泰坦圣物送到哪里"}},{q="这件圣物为何重要？",a="它似乎并非普通的雕刻品，大地之环或许能从中找到有关地下遗迹与失落之地的智慧。",al={"这是什么圣物","泰坦圣物的含义","奇怪的雕刻品"}},{q="Muln Earthfury在哪里？",a="Muln Earthfury和大地之环的其他长者都在莫高雷西北部的观天者台地。",al={"muln的位置","观天者台地","大地之环在哪里"}},{q="大地之环会如何处理这件圣物？",a="大地之环将妥善保管并研究这件圣物，待他们能够理解其中的讯息时，再将其分享出来。",al={"碎片会怎样","大地之环的研究","交付后的圣物"}}},fp="12,165,22.285.0,18.274.1,38.121.0,26.120.0,24.96.0,45.114.0"}
P.entries["quest:98824"] = {n="Prehistoric Prism",s="Prehistoric Prism是一个探索任务，引导冒险者将一件多面的泰坦圣物从湿地运送到铁炉堡。受勘察员维尔加所托，这件圣物被捐赠给了位于探险者大厅的高级探险家麦格拉斯，以推进探险者协会对古代守护者的研究。",h="Prehistoric Prism是一个探索任务，引导冒险者将一件多面的泰坦圣物从湿地运送到铁炉堡。受勘察员维尔加所托，这件圣物被捐赠给了位于探险者大厅的高级探险家麦格拉斯，以推进探险者协会对古代守护者的研究。",kw={"探险者大厅","高级探险家麦格拉斯","铁炉堡","史前棱镜","勘察员维尔加","泰坦圣物","奥达曼","湿地"},ang={["faction:Alliance"]="捐赠发现的古代宝藏能直接丰富铁炉堡著名的探险者大厅的学术收藏。",["race:Dwarf"]="找回真正的泰坦圣物是矮人身份认同的核心，也是探险者协会揭示其制造者起源这一使命的关键。"},sec={{t="古老的发现",b="在勘测湿地时，勘察员维尔加发现了一件非凡的文物，其刻面上装饰着复杂的守护者铭文。这位矮人勘察员认识到，如此具有历史意义的发现应当交到学者手中，因此他极力敦促立即将其运送到矮人主城铁炉堡。维尔加希望这次发现能被正式编入目录，确保冒险者在圣物鉴定过程中获得应有的功绩。"},{t="博物馆的馈赠",b="在探险者大厅那充满传奇色彩的大厅内，高级探险家麦格拉斯代表探险者协会接收了这件圣物。这位首席考古学家对圣物上真实的制造者印记赞叹不已，并指出光线穿过其打磨过的刻面时呈现出的折射效果，让他回想起了自己早年在奥达曼挖掘时所见到的奇观。捐赠这件文物能将其妥善保存以供研究，从而扩充探险者协会不断增长的泰坦遗产记录。"}},faq={{q="谁发布了史前棱镜任务？",a="勘察员维尔加在湿地鉴定了圣物刻面上发现的类似泰坦的铭文后，指引你将其送往铁炉堡。",al={"谁发布了史前棱镜","史前棱镜起始地点","史前棱镜任务发布者"}},{q="你在哪里交付史前棱镜？",a="你将这件圣物交付给位于铁炉堡探险者大厅的高级探险家麦格拉斯，他非常乐意将其收入博物馆的藏品中。",al={"史前棱镜交付对象","史前棱镜交付地点","史前棱镜完成情况"}},{q="史前棱镜是什么类型的文物？",a="这是一件古老的多面文物，带有明显的守护者印记。当被光照亮时，光线在其晶体结构中舞动的方式，令人想起在奥达曼出土的圣物。",al={"什么是史前棱镜","史前棱镜是否属于泰坦","什么是该圣物"}},{q="为什么探险者大厅对这个棱镜感兴趣？",a="探险者协会积极收集和编目泰坦起源的真迹。高级探险家麦格拉斯认为，这种级别的文物对于增进世界知识和理解古代历史至关重要。",al={"为什么麦格拉斯想要它","为什么要捐赠棱镜","探险者大厅棱镜"}},{q="这个棱镜与奥达曼有何关联？",a="在检查了文物的折射效果和守护者标记后，高级探险家麦格拉斯将其闪烁的光芒与他在奥达曼进行的第一次考古挖掘中所研究的圣物进行了比较。",al={"奥达曼是否与该棱镜有关","奥达曼联系","棱镜奥达曼"}},{q="你的名字会被记录在博物馆的目录中吗？",a="勘察员维尔加和高级探险家麦格拉斯确保你找回圣物的功绩被正式认可，并记录在探险者协会的历史档案中。",al={"史前棱镜目录","你会被记录在案吗","历史功绩棱镜"}}},fp="17,157,20.368.0,20.348.0,38.139.0,43.124.0,47.148.0,53.167.0,37.168.0,54.133.0"}
P.entries["quest:98895"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash 是联盟的一项军事征召令，号召勇士们防守关键阵地，抵御凶猛的暗矛突袭者。如果前线得不到及时的支援，联盟将面临彻底失去这片争议群岛的风险。",h="Darkspear Islands Clash 是联盟的一项军事征召令，号召勇士们防守关键阵地，抵御凶猛的暗矛突袭者。如果前线得不到及时的支援，联盟将面临彻底失去这片争议群岛的风险。",kw={"联盟","战场","准将","暗矛群岛","暗矛群岛冲突","暗矛突袭者","荣誉印记"},ang={["class:Paladin"]="联盟的圣职战士们带着坚定的决心投入到激烈的冲突中，响应号召，保卫联盟的生命，击退敌对势力。",["class:Warrior"]="前线战士在抵御凶猛的巨魔突袭者时承受着巨大的压力，他们用铁的纪律和战场上的英勇扭转了战局。",["faction:Alliance"]="联盟最高指挥部依靠勇士志愿者来加强前线对抗暗矛突袭者，并保卫群岛上的战略阵地。"},sec={{t="争议前线",b="为了争夺暗矛群岛的控制权，联盟与好战的暗矛突袭者战团之间爆发了公开战争。联盟指挥官警告称，若无紧急援军，他们在群岛的立足点将会失守，因此发出了战斗征召，号召有能力的勇士前来抵挡敌人的攻势。"},{t="英勇的证明",b="联盟指挥层依靠那些愿意直接奔赴前线的实战勇士。为了确保纪律并嘉奖真正的英雄主义，指挥官要求战士们带回暗矛群岛荣誉印记，以此作为他们战斗服役的切实证明，表彰那些扭转战局的人。"}},faq={{q="什么是 暗矛群岛冲突？",a="暗矛群岛冲突 是由负责前线战事的联盟军官发布的一项军事征召令。联盟勇士的任务是与暗矛突袭者交战，并通过从战斗中收集荣誉印记来证明自己的贡献。",al={"什么是 暗矛群岛冲突","冲突任务","暗矛群岛之战"}},{q="谁是暗矛突袭者？",a="暗矛突袭者是争夺暗矛群岛控制权的巨魔战团。他们咄咄逼人的攻势威胁到了联盟在该地区的立足点，迫使最高指挥部发出紧急援军请求。",al={"谁是暗矛突袭者","暗矛突袭者敌人","我们在暗矛群岛对抗谁"}},{q="为什么联盟要在暗矛群岛作战？",a="联盟试图守住暗矛群岛的战略领土，防止该地区完全落入巨魔的控制之下。如果失去这片阵地，将危及联盟在这一争议海域的影响力和安全。",al={"为什么联盟在暗矛群岛作战","为什么要在这里作战","联盟暗矛战争"}},{q="谁来发布并完成这项任务？",a="一名驻扎在战场之外的联盟准将负责监督部队调动，并接收返程勇士提交的战场服役证明。",al={"谁发布 暗矛群岛冲突","谁收取暗矛荣誉印记","联盟准将位置"}},{q="什么是暗矛群岛荣誉印记？",a="荣誉印记是颁发给在前线表现出英勇和积极参与战斗的战士的军事代币。向联盟准将提交三枚此类印记，即是证明你战场贡献的确凿证据。",al={"什么是荣誉印记","暗矛群岛荣誉印记","如何证明前线服役"}},{q="如果联盟失败，会有什么后果？",a="如果没有迅速的增援，联盟在暗矛群岛的阵地将无法承受暗矛突袭者无情的压力而全面崩溃。守住群岛可以防止敌方部队确立对整个群岛的统治地位。",al={"如果联盟输掉暗矛群岛会发生什么","为什么需要紧急援助","失去暗矛群岛"}}},fp="23,162,17.280.0,14.233.0,32.162.0,30.180.0,54.219.0,38.157.0,42.199.0,39.243.0"}
P.entries["quest:98896"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash呼吁战士们集结同伴，击败那些争夺群岛的敌对暗矛突袭者。持续不断的战斗需要协同行动，以遏制敌人对争议岛屿链的入侵。",h="Darkspear Islands Clash呼吁战士们集结同伴，击败那些争夺群岛的敌对暗矛突袭者。持续不断的战斗需要协同行动，以遏制敌人对争议岛屿链的入侵。",kw={"冲突","暗矛群岛","暗矛突袭者","群岛冲突","集结","小规模冲突","巨魔突袭者"},ang={["faction:Horde"]="这是联盟一方为暗矛群岛进行的战斗，这些位于卡利姆多海岸外的神圣巨魔群岛一直被部落占据，以抵御所有外来者。",["race:Troll"]="对于巨魔冒险者来说，这份联盟指令所针对的暗矛突袭者正是沃金的族人，他们正在保卫自己部族的神圣岛屿。"},sec={{t="战火中的群岛",b="Darkspear Islands Clash代表了在争议不断的暗矛群岛内进行的一次主动军事推进。部署到该战区的部队被敦促坚守阵地，抵御一波又一波持续在海滩和内陆地区发动小规模冲突的暗矛突袭者。这场冲突并非孤立事件，而是确保在群岛中据点领土的持久战役的一部分。"},{t="集结前线",b="前线的指挥官们强调了组织和兵力对于战胜顽强突袭者的必要性。生存和胜利取决于将附近的盟友集结成一支有凝聚力的部队，这支部队必须有能力抵御反击、击溃筑防的突袭小队，并打破他们对争议岛屿据点的控制。"}},faq={{q="什么是暗矛群岛冲突？",a="暗矛群岛冲突是一项任务，呼吁冒险者们在暗矛群岛持续不断的冲突中集结盟友，并对敌对的暗矛突袭者发起进攻。",al={"任务简述","暗矛群岛冲突摘要","冲突任务信息"}},{q="这场战斗发生在什么地方？",a="这场小规模冲突发生在暗矛群岛各地，这是一片因激烈的领土争夺和持续的海上冲突而闻名的群岛。",al={"战斗发生地","暗矛群岛位置","冲突地点"}},{q="谁是暗矛突袭者？",a="暗矛突袭者是部落在暗矛群岛的巨魔守卫，这些群岛是沃金部族的神圣岛屿。指令要求战斗人员在他们争夺岛屿领土时击败他们。",al={"敌方是谁","对抗目标","暗矛突袭者目标"}},{q="为什么必须为这场冲突集结部队？",a="冲突需要召集和集结盟军部队，以抵御持续的反击并击破敌方突袭者的防线。",al={"为什么要集结部队","任务目标","如何完成冲突"}},{q="为什么暗矛群岛的战斗会持续不断？",a="部落和联盟在这些岛屿据点的争夺中陷入了僵局：部落将这里作为神圣的巨魔领地进行守卫，而联盟则试图在卡利姆多海岸外建立一个据点。",al={"为何开战","岛屿冲突原因","群岛战斗起因"}},{q="是谁在指挥这次交战的部队？",a="该指令由奥特兰克山脉的联盟准将发布，敦促地面士兵毫不动摇地向前推进。",al={"任务发布者","冲突任务发布人","冲突指挥官"}}},fp="23,187,22.190.0,23.294.0,36.126.0,33.121.0,30.200.0,42.93.0,53.178.0,42.141.0"}
P.entries["quest:99"] = {n="阿鲁高的愚行",s="“阿鲁高的愚行”是一项危险的调查任务，旨在探究困扰焚木村的诅咒。达拉尔·道恩维沃尔派遣部落特工从村民身上获取附魔镣铐，以解读大法师阿鲁高扭曲的杰作。解开这些束缚，就能揭示让这个定居点处于狼人阴影之下的悲剧魔法。",h="“阿鲁高的愚行”是一项危险的调查任务，旨在探究困扰焚木村的诅咒。达拉尔·道恩维沃尔派遣部落特工从村民身上获取附魔镣铐，以解读大法师阿鲁高扭曲的杰作。解开这些束缚，就能揭示让这个定居点处于狼人阴影之下的悲剧魔法。",kw={"阿鲁高","阿鲁高的愚行","达拉尔·道恩维沃尔","月怒狼人","焚木镣铐","焚木村","银松森林","瑟伯切尔"},ang={["class:Mage"]="对于奥术修行者来说，阿鲁高的镣铐是一个冷酷的提醒，告诫他们当肯瑞托的魔法与异界召唤的野兽混合时，可能会陷入何等的疯狂。",["faction:Horde"]="获得这些镣铐打破了阿鲁高对通往格雷迈恩之墙南下道路的神秘控制。",["race:Undead"]="被遗忘者以冰冷的着迷和无情的实用主义看待焚木村，渴望拆除阿鲁高的附魔以确保银松森林南部的安全。"},sec={{t="焚木村的双重生活",b="瑟伯切尔以南是焚木村，这是一个处于诡异存在状态的定居点。在白昼的阳光下，居民们像普通人类农民一样过着恐惧而封闭的生活。然而，当黄昏降临森林时，他们的人类形态就会撕裂，变成野蛮的月怒狼人，在阿鲁高的支配下在街上游荡。达拉尔·道恩维沃尔试图解开导致这种昼夜恐怖的精确奥术束缚。"},{t="粉碎镣铐",b="为了分析束缚焚木村的附魔，道恩维沃尔需要从变身的城镇居民身上直接取得附魔的“焚木镣铐”。这些枷锁并非简单的铁制品，它们震颤着阿鲁高失败结界的残余魔法。通过研究其奥术构成，这位被遗忘者法师希望理解这种野兽般变形的机制，并设法最终打倒影牙城堡的那位叛逃大法师。"}},faq={{q="为什么焚木村的人在晚上会变成狼人？",a="大法师阿鲁高在焚木村施加了扭曲的附魔。白天，他的咒语维持着人类的幻象或沉睡状态，但夜幕降临会导致城镇居民在他的控制下变身为月怒狼人。",al={"焚木村昼夜","焚木村诅咒","为什么白天是人晚上是狼"}},{q="什么是“焚木镣铐”？",a="它们是被诅咒的焚木村居民所佩戴的附魔束缚。阿鲁高将它们作为他控制该镇魔法的一部分，而达拉尔·道恩维沃尔则利用其残余能量来研究这一诅咒。",al={"焚木镣铐","阿鲁高镣铐"}},{q="达拉尔·道恩维沃尔是谁？",a="达拉尔·道恩维沃尔是一位驻扎在银松森林瑟伯切尔的被遗忘者法师。他负责领导被遗忘者对大法师阿鲁高召唤的狼人进行的魔法调查。",al={"达拉尔·道恩维沃尔背景故事","瑟伯切尔的任务发放者是谁"}},{q="完成这个任务能治愈焚木村吗？",a="不能。取回的镣铐为达拉尔·道恩维沃尔提供了理解阿鲁高魔法所需的奥术见解，但诅咒依然让焚木村处于永恒的折磨之中。",al={"焚木村可以被治愈吗","焚木村的人民会被治愈吗"}},{q="阿鲁高是如何控制村民的？",a="通过鲁莽的附魔和附魔镣铐，阿鲁高将村民束缚在他的意志之下，强迫他们变成守护他影牙城堡领地入口的野兽形态。",al={"阿鲁高与焚木村的联系","阿鲁高如何控制他们"}},{q="完成“阿鲁高的愚行”任务线后会发生什么？",a="此项任务标志着“阿鲁高的愚行”系列任务的最终章。所收集的情报使被遗忘者能够全面评估影牙城堡的威胁，并策划阿鲁高的垮台。",al={"阿鲁高的愚行之后","阿鲁高的愚行结局"}}},fp="14,199,26.323.0,23.328.1,64.161.0,31.203.0,24.160.0,48.134.1,38.161.0,61.157.1"}
P.entries["quest:990"] = {n="灰谷之旅",s="“前往灰谷”是一项联盟的旅程任务，指引经验丰富的冒险者从黑海岸向南进入灰谷的原始森林。哨兵塞拉伊前来奥伯丁寻求援助，并指派旅行者前往阿斯特兰纳镇向莱恩·狼行者报到，当地的哨兵正努力对抗蔓延的腐蚀。",h="“前往灰谷”是一项联盟的旅程任务，指引经验丰富的冒险者从黑海岸向南进入灰谷的原始森林。哨兵塞拉伊前来奥伯丁寻求援助，并指派旅行者前往阿斯特兰纳镇向莱恩·狼行者报到，当地的哨兵正努力对抗蔓延的腐蚀。",kw={"灰谷","阿斯特兰纳","黑海岸","暗夜精灵","莱恩·狼行者","哨兵塞拉伊","前往灰谷"},ang={["faction:Alliance"]="作为一名联盟勇士，响应阿斯特兰纳的呼唤可以加强与暗夜精灵的联系，并巩固该阵营在卡利姆多北部的核心立足点。",["race:NightElf"]="对于暗夜精灵来说，这段旅程是回归卡利姆多的神圣中心地带，响应姐妹们的呼唤，保护古老圣地免受非自然腐烂的侵蚀。"},sec={{t="离开海岸",b="响应了哨兵塞拉伊在奥伯丁发出的援助请求后，旅行者们将告别阴郁灰暗的海岸和阴影笼罩的遗迹。哨兵认可那些拥有自保能力的强大战士和侦察兵，并直接指引他们前往暗夜精灵林地领土的中心地带。在解决了黑海岸的地方威胁后，注意力转向了从南方入侵的更严峻的危机。"},{t="通往阿斯特兰纳的路",b="向南的道路沿着一条古老的暗夜精灵之路蜿蜒而行，穿过灰谷茂密的古老树冠。驻扎在阿斯特兰纳的哨兵指挥官莱恩·狼行者发出了紧急的增援呼吁。在恶魔的玷污、猖獗的野生动物以及对祖地的外部入侵之间，阿斯特兰纳的哨兵们兵力不足，需要外部援助来维持对这片神圣森林的控制。"}},faq={{q="是谁让你踏上这段旅程？",a="哨兵塞拉伊，一位被莱恩·狼行者派往奥伯丁寻求帮助的暗夜精灵哨兵，指引你向南前往阿斯特兰纳。",al={"任务发布者","谁开启前往灰谷任务","塞拉伊"}},{q="莱恩·狼行者是谁？",a="莱恩·狼行者是常驻阿斯特兰纳的首席哨兵指挥官，负责组织灰谷的防御，并协调各方努力以遏制侵蚀森林的腐化。",al={"莱恩","狼行者","阿斯特兰纳领袖"}},{q="为什么要派冒险者去灰谷？",a="灰谷的古老森林正屈服于蔓延的腐化和日益增加的外部威胁。当地的暗夜精灵哨兵已不堪重负，迫切需要有能力的盟友来协助阿斯特兰纳的市民和保卫者。",al={"为什么去灰谷","灰谷发生了什么","灰谷腐化"}},{q="黑海岸和灰谷之间的道路安全吗？",a="哨兵塞拉伊特别建议紧贴大路行走。偏离路径深入森林会使旅行者暴露在徘徊于荒野边缘的凶猛掠食者、萨特和敌对势力面前。",al={"道路安全","灰谷道路安全吗"}},{q="到达阿斯特兰纳后我该做什么？",a="在直接向莱恩·狼行者报到后，她建议与阿斯特兰纳各处的其他居民和保卫者交谈，因为他们中有许多人需要即时的帮助来处理当地的危机。",al={"在阿斯特兰纳做什么","到达阿斯特兰纳"}},{q="这项任务适合什么等级的冒险者？",a="这段旅程通常标志着在19级左右从黑海岸毕业，将中级冒险者带入灰谷这个更广阔且充满争夺的前线。",al={"什么等级","等级要求"}}},fp="17,158,17.265.0,21.326.0,27.126.0,24.154.0,44.191.0,49.151.0,44.178.0,46.166.0"}
P.entries["quest:99046"] = {n="The Lost Runner",s="The Lost Runner是一项搜寻哨兵艾露亚·影叶的任务，她是一位从神谕之树出发、逾期未归的信使学徒。这项任务至关重要，因为这棵神圣之树与达纳苏斯的长老们之间的联络对于暗夜精灵的领导层来说必不可少。",h="The Lost Runner是一项搜寻哨兵艾露亚·影叶的任务，她是一位从神谕之树出发、逾期未归的信使学徒。这项任务至关重要，因为这棵神圣之树与达纳苏斯的长老们之间的联络对于暗夜精灵的领导层来说必不可少。",kw={"森林议会","达纳苏斯","艾露亚·影叶","神谕林地","神谕之树","哨兵","失踪的信使"},ang={["faction:Alliance"]="维护泰达希尔境内安全畅通的道路和通讯线路，有助于保障达纳苏斯和联盟领土的稳定。",["race:NightElf"]="确保古老的神谕之树与达纳苏斯领导层之间的安全通讯，对于卡多雷的安全和精神指引至关重要。"},sec={{t="神谕者的信使",b="森林议会在泰达希尔受人尊敬的神谕林地中驻扎了一支哨兵小队。这棵树负责向暗夜精灵的长老们传达神圣的信息，并依靠忠诚的信使沿着蜿蜒的林间道路将这些信件送回达纳苏斯。确保这些信件安全送达，对于卡多雷的指引和统治至关重要。"},{t="逾期的信使",b="来自神谕之树的信息传递时间并不固定，但如果信使久久未现身，这种异常的沉默会引起警觉。最近一次任务落在了哨兵艾露亚·影叶身上，她还是一名正在接受训练的学徒。她的上级担心她在路上遭遇了不幸，因此指示旅行者搜寻通往神谕林地的西向道路，以确定她的下落。"}},faq={{q="迷失的信使是谁？",a="失踪的信使是哨兵艾露亚·影叶，她是一位正在受训的暗夜精灵哨兵，任务是将来自神谕之树的信息送往达纳苏斯。",al={"谁是迷失的信使","失踪的哨兵","谁是艾露亚"}},{q="什么是神谕之树？",a="神谕之树是位于神谕林地的一棵古树，它会定期向达纳苏斯的暗夜精灵长老传达信息，需要驻扎的哨兵安全地进行传递。",al={"什么是神谕之树","神谕林地的目的","为什么要有来自神谕之树的信息"}},{q="艾露亚·影叶要去哪里？",a="艾露亚原本应该出现在连接达纳苏斯和神谕林地的西向道路上，信使经常往返于该路段，传递来自该树的交流信息。",al={"艾露亚要去哪里","艾露亚的路线","迷失的信使位置"}},{q="是谁将哨兵驻扎在神谕之树？",a="森林议会指派了一支哨兵分遣队前往神谕之树，以确保信息能够安全、迅速地传达给达纳苏斯的长老们。",al={"谁派哨兵去神谕之树","什么是森林议会"}},{q="为什么她的失踪令人担忧？",a="虽然来自神谕之树的信息传递频率不固定，但她的缺席时间已经长得反常，考虑到她学员的身份，这引起了她上级的担忧。",al={"为什么她的延误不寻常","神谕多久发送一次信息"}},{q="这项搜寻任务的目标是什么？",a="你需要沿着通往神谕林地的西向小路前进，搜寻哨兵艾露亚·影叶，找出是什么延误了她的行程。",al={"在失踪的信使中要做什么","失踪的信使任务目标"}}},fp="15,128,24.261.0,18.306.0,23.156.0,24.180.0,36.135.0,47.152.0,29.168.0,37.126.0"}
P.entries["quest:99047"] = {n="Not Dead Yet",s="“Not Dead Yet”是Eralya发出的紧急呼救，她是一名受了致命伤的暗夜精灵，在前往神谕之树的灾难性任务后被发现。她被凶残的鹰身人袭击，恳求过路人将她巡逻队遭遇的命运转达给多兰纳尔的拜恩希。这凸显了泰达希尔林间小径上日益逼近的致命威胁。",h="“Not Dead...",kw={"拜恩希","多兰纳尔","艾拉娅","鹰身人","还没死","神谕之树","泰达希尔"},ang={["faction:Alliance"]="当外勤侦察兵被阻断并陷入重围时，探索泰达希尔的联盟冒险者受命将紧急消息带回多兰纳尔这样的定居点前哨。",["race:NightElf"]="倒下的信使Eralya和她的姐妹们是在泰达希尔服役的哨兵。目睹暗夜精灵守卫在神圣的神谕之树附近遭到鹰身人伏击，这直接揭示了这片巨枝之上日益严重的威胁。"},sec={{t="遭到伏击的巡逻队",b="“Not Dead Yet”是泰达希尔荒野中的绝望呼救，故事围绕Eralya展开，她是一名受了伤的暗夜精灵信使，被发现时正流血不止，生命垂危。她与姐妹们一同被派往神圣的神谕之树执行一项关键任务，但在途中遭到了入侵的鹰身人的暴力伏击并被屠戮。援军无望，且体力迅速衰竭，Eralya只能委托过路的旅行者将紧急消息带回安全地带。"},{t="呼唤多兰纳尔",b="Eralya大口喘着气，并不时咳血，她恳求玩家将她的报告带给附近多兰纳尔村的拜恩希。那些盘踞在泰达希尔巨枝之上的鹰身人变得越来越大胆和具有攻击性，对那些试图穿越林间小径的独行信使和哨兵构成了致命威胁。传递Eralya的求救信息能确保多兰纳尔定居点在更多生命逝去之前，获知关于神谕之树伏击事件的消息。"}},faq={{q="艾拉娅是谁？",a="艾拉娅是一名在前往神谕之树执行任务途中遭到伏击的暗夜精灵哨兵或信使。她生命垂危，咳血不止，恳求过路的冒险者在她的生命走到尽头之前，带去关于她小队命运的消息。",al={"艾拉莉娅是谁","艾拉莉娅任务","垂死的暗夜精灵"}},{q="什么是神谕之树？",a="神谕之树是位于泰达希尔神谕林地的一处古老地标。艾拉娅和她的姐妹们在前往那里的途中，带着一封紧急信件时被敌方压制。",al={"什么是神谕之树","神谕林地之树","艾拉莉娅要去哪里"}},{q="艾拉娅和她的巡逻队发生了什么事？",a="艾拉娅和她的姐妹们遭到了盘踞在泰达希尔枝叶间的鹰身人的伏击并被其压制。这些生物蜂拥而至，屠戮了巡逻队，并将艾拉娅打成重伤。",al={"谁袭击了艾拉莉娅","谁伏击了她","艾拉莉娅为什么在流血"}},{q="拜恩希是谁？",a="拜恩希是驻扎在暗夜精灵村庄多兰纳尔的一名联络人。艾拉娅急切地要求将鹰身人伏击和巡逻队困境的消息直接带给拜恩希。",al={"拜恩希是谁","拜恩希在哪里","拜恩希 多兰纳尔"}},{q="艾拉娅的消息必须送到哪里？",a="多兰纳尔是位于泰达希尔幽影谷以南道路旁的主要暗夜精灵村庄。拜恩希居住在那里，负责接收报告并协调当地的防御工作。",al={"消息送到哪里","艾拉莉娅的传信","多兰纳尔在哪里"}},{q="执行任务的其他姐妹们发生了什么事？",a="艾拉娅的暗夜精灵哨兵同伴在凶残的鹰身人突袭中失散或阵亡。由于看不到援军，艾拉娅担心她的姐妹中无人能从这场屠杀中幸免。",al={"艾拉莉娅的姐妹们发生了什么","哨兵巡逻队姐妹"}}},fp="12,199,18.288.0,18.293.0,14.183.0,24.175.0,39.130.0,15.137.0,41.225.0,50.162.0"}
P.entries["quest:99048"] = {n="A Missing Hand",s="A Missing Hand是杜隆塔尔的一项任务，内容涉及碎手氏族侦察兵Heglan Shadeeye的突然失踪。她原本的任务是负责监视提拉加德城堡。在她的常规情报报告突然中断后，一位调查员被派去寻找她的岗哨，以查明究竟是什么让她噤声。",h="A Missing Hand是杜隆塔尔的一项任务，内容涉及碎手氏族侦察兵Heglan...",kw={"失踪的帮手","杜隆塔尔","赫格兰·影眼","潜行者","侦察兵","碎手氏族","提拉加德城堡"},ang={["class:Rogue"]="碎手氏族是部落隐秘的脊梁和情报公会。调查一名失踪特工的情况，足以证明他们的实地监视任务有多么危险。",["faction:Horde"]="监视提拉加德城堡的库尔提拉斯残余势力对于杜隆塔尔的安全至关重要，而一名侦察兵无法解释的失踪，预示着奥格瑞玛家门口可能存在着尚未察觉的威胁。",["race:Orc"]="杜隆塔尔是新近稳固的兽人领土，让一名特工在附近人类居住者的眼皮底下失踪，引起了对王国安全的高度警惕。"},sec={{t="沉默的报告",b="A Missing Hand的起因是人们对碎手氏族侦察兵Heglan Shadeeye日益增长的担忧。她被派驻在杜隆塔尔，从远处监视占领提拉加德城堡的敌对人类驻军，但她持续的情报报告却毫无预兆地中断了。她的上级怀疑人类士兵是否真的成功发现并抓获了她，担心是有意想不到且更危险的威胁介入了。冒险者们被派往城堡以北寻找她的岗哨，以确定这次中断仅仅是通讯延迟，还是有更可怕的事情发生。"},{t="寒冷的小屋",b="到达提拉加德城堡以北指定的观察哨后，搜寻工作以悲剧告终。Heglan冰冷的尸体躺在一间破败小屋的碎片之中。留下的实物证据表明，袭击者并非人类，这留下了一个令人不安的疑问：究竟是什么生物或实体在如此靠近部落领土的地方击杀了一名训练有素的特工？散落在残骸附近的线索暗示了一种必须被揭开的陌生威胁。"}},faq={{q="什么是失踪的帮手任务？",a="失踪的帮手是杜隆塔尔的一项任务，冒险者需要寻找碎手氏族侦察特工赫格兰·暗眼，她原本驻扎在提拉加德城堡以北，但她的常规情报报告突然中断了。",al={"失踪的帮手是什么","失踪的帮手任务概览"}},{q="赫格兰·暗眼是谁？",a="赫格兰·暗眼是一名碎手氏族特工，任务是从附近的有利位置秘密监视提拉加德城堡。她的监视报告突然中断，促使人们对她的下落展开调查。",al={"赫格兰是谁","赫格兰·影眼在哪里","失踪的侦察兵"}},{q="赫格兰·暗眼发生了什么事？",a="这正是本任务要查明的内容。她从提拉加德城堡以北的岗哨发回的报告毫无预警地中断了，派你去执行任务的人怀疑人类士兵并没有抓获她，而是担心有更危险的事情正在发生。",al={"赫格兰·影眼发生了什么","赫格兰死了吗","赫格兰的命运"}},{q="什么是碎手氏族？",a="在现代部落中，碎手氏族是一个由隐秘特工、刺客和间谍组成的组织。他们执行秘密监视和情报行动，以保护部落领土。",al={"什么是碎手氏族","碎手氏族是什么组织"}},{q="提拉加德城堡的人类杀害了赫格兰吗？",a="她的上级对此表示怀疑。尽管赫格兰一直在监视占领提拉加德城堡的敌对库尔提拉斯人类，但委派你任务的人不相信他们能抓住她，并担心有更危险的事情在发生。",al={"是人类杀了赫格兰吗","是提拉加德的士兵杀了她吗"}},{q="为什么要监视提拉加德城堡？",a="提拉加德城堡是敌对的库尔提拉斯水兵和士兵占据的据点，威胁着杜隆塔尔的海岸。赫格兰被派驻在附近以密切关注他们的行动，并将情报传回部落。",al={"为什么赫格兰要监视提拉加德城堡","提拉加德城堡监视"}}},fp="14,194,14.354.0,12.234.1,33.185.0,23.176.0,33.184.0,27.184.0,45.185.0,37.173.0"}
P.entries["quest:99049"] = {n="Threat from Below",s="Threat from Below是一个部落任务，核心内容是调查杜隆塔尔东海岸发生的一起暴力伏击事件。在哨兵赫格兰·暗眼于她的哨岗遭遇猛烈的小规模袭击后，冒险者必须检查这片受损区域，寻找袭击者的线索。发现的实物证据揭示了一个直接威胁到剃刀岭防线的入侵隐患。",h="Threat from...",kw={"杜隆塔尔","赫格兰·暗眼","部落","娜迦","奥戈尼尔·魂痕","剃刀岭","斥候","来自地下的威胁"},ang={["faction:Horde"]="调查海岸线对于杜隆塔尔的防御至关重要，能保护年轻的部落国度免受沿海边境侧翼打击的威胁。",["race:Orc"]="兽人防卫者认为针对斥候赫格兰·暗眼的伏击是对他们定居家园不可容忍的入侵，要求立即进行调查和反击。",["race:Troll"]="暗矛巨魔非常了解娜迦的狡诈本性，他们此前曾在无尽之海面对过海巫和水生恐怖生物。"},sec={{t="杜隆塔尔海岸的伏击",b="杜隆塔尔海岸发生的一场暴力小规模战斗留下了破碎的地面，引起了部落防卫者们的即刻警觉。破碎之手斥候赫格兰·暗眼在她的哨岗执行守望任务时，遭到了未知敌人的伏击。交战地点的情况清晰地表明，赫格兰进行了激烈的反击并重创了袭击者。由于敌对势力在东海岸长驱直入，部落冒险者们奉命调查这片受损的营地，仔细搜寻地面的线索，并查明袭击斥候的究竟是何种敌人。"},{t="娜迦威胁",b="搜寻残骸后发现了破碎的旗帜和一截异样兵器的残片，这些都属于蛇形生物——娜迦。这些邪恶的水生生物似乎是从艾萨拉一路沿杜隆塔尔海岸向南潜行，企图建立一个掠夺性的据点。对于驻扎在剃刀岭的守军来说，这一发现标志着危机将至。该定居点南面受困于提拉加德城堡的人类入侵者，西面又有野猪人的威胁，无法承受来自北方的新一轮海上攻势，否则将面临彻底崩溃的风险。"}},faq={{q="什么是来自海底的威胁？",a="来自海底的威胁是杜隆塔尔的一项任务，部落冒险者需在任务中调查针对斥候赫格兰·暗眼的伏击。在沿着海岸线发现暴力战斗的痕迹后，玩家需在受扰的地面上搜寻不明袭击者留下的线索。随后，回收的文物将被直接送往剃刀岭的奥戈尼尔·魂痕处，以评估该地区面临的军事危险。",al={"来自下方的威胁任务","什么是来自下方的威胁","来自下方的威胁概览"}},{q="赫格兰·暗眼是谁？",a="赫格兰·暗眼是一名破碎之手斥候，她曾在一座位于提拉加德城堡北侧的小屋中执行监视任务，守护部落的核心领地。在执行任务期间，她在海岸的观测点遭到了伏击。营地遭受的严重破坏表明她曾与袭击者进行过激烈的战斗，这引起了剃刀岭定居点领导层的紧急质询。",al={"赫格兰·暗眼","赫格兰是谁","赫格兰·暗眼背景故事"}},{q="谁袭击了赫格兰·暗眼？",a="赫格兰·暗眼遭到了沿杜隆塔尔海岸向南移动的娜迦的伏击。从交战现场回收的实物证据，特别是那面独特的旗帜和那块断裂的刀刃，证实了这次袭击是由这些蛇形生物实施的。战斗的惨烈程度也让袭击者自身负了伤。",al={"谁伏击了赫格兰","赫格兰的袭击者","什么袭击了赫格兰·暗眼"}},{q="奥戈尼尔·魂痕是谁？",a="奥戈尼尔·魂痕是驻扎在杜隆塔尔中部剃刀岭的一位著名兽人长官。他的职责是组织该地区的防御并协调部落斥候，负责监督有关敌对入侵的情报。当赫格兰·暗眼失去联络时，奥戈尼尔依靠返回的斥候和冒险者来识别袭击者并保障定居点的安全。",al={"奥戈尼尔是谁","奥戈尼尔·魂痕","剃刀岭的奥戈尼尔"}},{q="为什么娜迦对剃刀岭构成威胁？",a="剃刀岭已经面临着南面深根蒂固的库尔提拉斯人类海军，以及西面敌对野猪人的巨大军事压力。如果娜迦在北面的东海岸建立永久的滩头阵地，部落前哨将面临被夹击的风险，导致其有限的驻军过度分散，并切断横跨杜隆塔尔的增援路线。",al={"为什么娜迦在这里很危险","娜迦对剃刀岭的威胁","剃刀岭娜迦威胁"}},{q="袭击的娜迦来自哪里？",a="回收的军事残骸表明，娜迦是从北方水域沿海岸南下的，很可能源自艾萨拉或无尽之海的架层。通过利用水道避开内陆巡逻队，这些水生入侵者在杜隆塔尔防卫者组织起防线之前，便迅速袭击了孤立的海岸观测哨。",al={"娜迦来自哪里","杜隆塔尔的娜迦起源","娜迦如何到达杜隆塔尔"}}},fp="17,217,27.374.0,18.374.1,26.247.0,23.254.0,29.191.0,23.281.0,40.284.0,39.272.0"}
P.entries["quest:99050"] = {n="The Great Tree Provides",s="“大树的馈赠”是多兰纳尔的一个任务，拜安希在任务中寻求帮助以遏制威胁埃拉莉亚的危险疾病。玩家通过采集泰达希尔湖泊中的露水鞭笞者嫩叶并收集基本补给品，来帮助配制一种急救药膏。",h="“大树的馈赠”是多兰纳尔的一个任务，拜安希在任务中寻求帮助以遏制威胁埃拉莉亚的危险疾病。玩家通过采集泰达希尔湖泊中的露水鞭笞者嫩叶并收集基本补给品，来帮助配制一种急救药膏。",kw={"疾病","拜安希","露水鞭笞者嫩叶","多兰纳尔","埃拉莉亚","治疗药膏","奥拉密斯湖","泰达希尔","巨树的馈赠","涌泉湖"},ang={["class:Druid"]="德鲁伊们很欣赏泰达希尔植物中蕴含的天然修复特性，他们倾向于依赖像鞭笞者嫩叶这样的原生植物，而不是人工合成的制剂。",["profession:Herbalism"]="采集露水鞭笞者嫩叶等原生植物材料来酿制强效治疗药膏，对于经验丰富的草药师来说是本能般的技能。",["race:NightElf"]="泰达希尔的草药疗法反映了卡多雷的信仰，即他们的世界之树养育并保护着他们，为突发的疾病提供了生命之药。"},sec={{t="与时间赛跑",b="在多兰纳尔的森林村庄里，拜安希一直照料着当地暗夜精灵的健康。当埃拉莉亚在泰达希尔野外遭遇危险疾病的消息传来时，拜安希立刻着手准备急救治疗。如果不能快速配制出药膏来遏制病情，埃拉莉亚将无法支撑到被送回村庄接受正式治疗。"},{t="慷慨的世界之树",b="即使在危机时刻，卡多雷依然信任泰达希尔的慷慨馈赠。拜安希求助于这棵充满生命的世界之树来寻找疗法，她寻找着生长在南面奥拉密斯湖和西北面涌泉湖附近的露水鞭笞者嫩叶。将这些叶片与简单的玻璃瓶中的清凉的泉水混合，就能得到遏制疾病所需的救命药物。"}},faq={{q="“大树的馈赠”是什么？",a="“大树的馈赠”是多兰纳尔的一项紧急任务，由拜安希发布。她试图配制一种修复药膏，以在无法进行后续治疗前遏制威胁埃拉莉亚的疾病。",al={"大树的馈赠是什么","大树的馈赠任务","拜安希任务"}},{q="拜安希是谁？",a="拜安希是一位居住在泰达希尔多兰纳尔村的暗夜精灵治疗者或药剂师，致力于照料病人并利用当地植物配制天然药物。",al={"谁是拜安希","拜安希多兰纳尔","任务发布者拜安希"}},{q="埃拉莉亚是谁？她发生了什么事？",a="埃拉莉亚是一位身处多兰纳尔外、目前病情正在迅速恶化的受难者。拜安希需要一种紧急药膏来使她的情况稳定下来，以便将其安全送回城里接受全面治疗。",al={"谁是埃拉莉亚","埃拉莉亚怎么了","埃拉莉亚疾病"}},{q="哪里可以找到露水鞭笞者嫩叶？",a="露水鞭笞者嫩叶生长在多兰纳尔正南方的奥拉密斯湖，以及西北方向的涌泉湖及其河流周围的鞭笞者身上。",al={"哪里找到露水鞭笞者嫩叶","露水鞭笞者嫩叶位置","泰达希尔鞭笞者嫩叶"}},{q="配制药膏需要什么材料？",a="拜安希需要六片从本土鞭笞者身上采集的露水鞭笞者嫩叶、一个空瓶以及清凉的泉水来调配这种急救药膏。",al={"拜安希需要什么材料","多兰纳尔药膏材料","大树的馈赠物品"}},{q="在哪里可以获得空瓶和清凉的泉水？",a="空瓶和清凉的泉水都可以直接从多兰纳尔定居点的杂货或贸易补给品商人处购买。",al={"哪里获取瓶子和泉水","多兰纳尔空瓶","多兰纳尔清凉的泉水"}}},fp="23,183,19.267.0,24.258.0,32.152.0,15.138.0,39.157.0,35.139.0,51.102.0,63.91.0"}
P.entries["quest:99051"] = {n="Threat from Below",s="Threat from Below是一项防御任务，旨在清除附近建立营地的侵略性娜迦侦察兵。通过打击侦察部队并收集它们的脊鳍，冒险者们的目标是将这些蛇形入侵者赶回北方，保卫该地区。",h="Threat from Below是一项防御任务，旨在清除附近建立营地的侵略性娜迦侦察兵。通过打击侦察部队并收集它们的脊鳍，冒险者们的目标是将这些蛇形入侵者赶回北方，保卫该地区。",kw={"步兵","娜迦","娜迦脊鳍","侦察兵","蛇渣","脊鳍","来自地下的威胁"},ang={["faction:Horde"]="任务发布者动员部落步兵观察是否有漏网之鱼，这使其成为部落领地针对逼近的娜迦侦察兵的一次主动防御行动。"},sec={{t="蛇形入侵",b="Threat from Below旨在应对因娜迦侦察兵入侵而日益严重的边境骚乱。这些蛇形袭击者开始在附近建立前进营地，迫使当地防卫力量在入侵者稳固立足之前发动打击。冒险者们受命清除侦察部队，并带回娜迦脊鳍作为营地已被摧毁的证据。"},{t="保卫边境",b="这并非蛇人第一次滋扰该地区，当地指挥官明确表示绝不容忍它们的存在。在对它们的侦察营地进行打击后，目标是将任何幸存的娜迦赶回北方，并派遣警惕的部落步兵守卫，以防漏网之鱼或突如其来的伏击。"}},faq={{q="什么是来自海底的威胁？",a="来自海底的威胁是一项部落任务，任务要求冒险者们消灭开始在附近建立营地的娜迦侦察兵。为了确保入侵被阻止，玩家必须杀死这些逼近的蛇人并收集娜迦脊鳍作为任务完成的证明。",al={"什么是来自下方的威胁","来自下方的威胁任务"}},{q="命令中提到的蛇是指谁？",a="“蛇”或“蛇渣”指的是娜迦，这是一种两栖蛇形类人生物，它们从海岸或水底深处浮出，侦察当地的防线。",al={"蛇是指谁","来自下方的威胁里的蛇"}},{q="为什么要消灭娜迦侦察兵？",a="这些营地表明这是一种有组织的侦察活动，而非偶然游荡的生物。当地指挥官要求迅速反击，以便在入侵者发动更大规模袭击或进一步扎根之前将它们赶走。",al={"为什么要杀娜迦侦察兵","娜迦的动机"}},{q="为什么要收集娜迦脊鳍？",a="被割下的脊鳍是侦察营地已被发现并拆除的无可辩驳的实物证据，证实了边境沿线的直接压力已经解除。",al={"为什么要收集脊鳍","娜迦的证据"}},{q="娜迦预计会撤退到哪里？",a="在交付脊鳍后，指挥官表示希望这次打击能将娜迦赶回北方，并指派步兵监视是否有漏网之鱼或可疑动向。",al={"娜迦会去哪里","娜迦撤往北方"}},{q="侦察兵被杀后由谁负责警戒？",a="部落步兵受命负责监视该区域，以确保没有漏网之鱼，并防止娜迦尝试任何进一步的入侵。",al={"谁负责监视娜迦","步兵监视娜迦"}}},fp="17,156,20.218.0,20.232.0,26.149.0,43.142.0,39.192.0,33.150.0,39.121.0,43.86.0"}
P.entries["quest:99052"] = {n="Threat from Below",s="“Threat from Below”是一项部落悬赏任务，要求冒险者们前往杜隆塔尔的北部海岸，猎杀一头危险的海洋巨人。击败这样一个巨大的海岸泰坦，不仅能保卫附近的海岸线，还能赢得杜隆塔尔勇士们的尊敬。",h="“Threat from Below”是一项部落悬赏任务，要求冒险者们前往杜隆塔尔的北部海岸，猎杀一头危险的海洋巨人。击败这样一个巨大的海岸泰坦，不仅能保卫附近的海岸线，还能赢得杜隆塔尔勇士们的尊敬。",kw={"血与雷","海岸怪物","杜隆塔尔","部落任务","北部海岸","海洋巨人","来自地下的威胁"},ang={["class:Warrior"]="在近战中面对一个庞大的海洋巨人是一场残酷的武力耐力考验，是对抗海岸上最强大的蛮兽之一的证明。",["faction:Horde"]="在杜隆塔尔海岸线上击杀海洋巨人，消除了一个潜伏在部落心脏地带门户附近的危险巨兽。",["race:Orc"]="兽人的荣誉感崇尚正面面对泰坦般的强敌，并以“血与雷”的战吼回应压倒性的力量。"},sec={{t="北部海岸线",b="在杜隆塔尔的北部海岸线，无尽之海的海水拍打着锯齿状的沙滩和岩石岸边。虽然这里通常只有普通的食腐动物和螃蟹出没，但北部海岸却潜藏着更致命的威胁：一个庞大的海洋巨人在浅滩徘徊，威胁着任何试图在部落这片干旱新家园的沿海水域旅行或获取资源的人。"},{t="波涛泰坦",b="海洋巨人是巨大的蛮兽，能够轻易摧毁长船，并用巨大的拳头碾碎战士。对于年轻的冒险者来说，击杀它们绝非易事；能终结这个波涛中的巨兽，足以在兽人中赢得极高的尊敬，并伴随着在干红色的峭壁间回荡的传统战吼——“血与雷”的庆祝。"}},faq={{q="“来自海底的威胁”是什么任务？",a="“来自海底的威胁”是一项交给部落勇士的任务，要求他们追踪并击败在杜隆塔尔北部海岸徘徊的巨型海洋巨人，并带回证明以完成任务。",al={"什么是来自下方的威胁","来自下方的威胁任务","杜隆塔尔海洋巨人任务"}},{q="在哪里可以找到海洋巨人？",a="这头海洋巨人在杜隆塔尔北部海岸的水域和岸边徘徊。",al={"海洋巨人在哪里","杜隆塔尔海洋巨人位置","来自下方的威胁位置"}},{q="海洋巨人是什么样的生物？",a="海洋巨人是巨大的、古老的海岸巨兽，它们被创造出来的目的是疏浚海洋并塑造艾泽拉斯的海岸线。很少有流浪者能在与它们的直接对抗中幸存。",al={"什么是海洋巨人","海洋巨人背景故事","谁是海洋巨人"}},{q="为什么要消灭海洋巨人？",a="如此巨大规模的生物在杜隆塔尔附近游荡，对海岸边的旅行者、渔民以及部落营地构成了严重的威胁。",al={"为什么要杀海洋巨人","海洋巨人危险吗","对杜隆塔尔的威胁"}},{q="任务发布者所说的“血与雷”是什么意思？",a="“血与雷”是传统的兽人战斗口号，旨在赞颂尚武精神、勇猛，以及在对抗危险对手并获得胜利后的荣耀。",al={"血与雷的含义","兽人问候语血与雷"}},{q="完成任务需要什么证明？",a="该任务要求从北部海岸带回这头海洋巨人被击杀的切实物理证明，以确认这一庞然大物已被消灭。",al={"来自下方的威胁任务证明","成就证明"}}},fp="17,185,22.278.0,20.257.0,36.120.0,29.70.0,37.153.0,45.123.0,54.140.0,44.118.0"}
P.entries["quest:99053"] = {n="Escaping Ban'ethil",s="“逃离班奈希尔”是泰达希尔地下兽穴中的一项营救任务。哨兵莱尼莎·暮花在向沉睡的德鲁伊传递信息时被好战的棘木熊怪俘虏，她必须被安全护送回地面，并向多兰纳尔报告平安。",h="“逃离班奈希尔”是泰达希尔地下兽穴中的一项营救任务。哨兵莱尼莎·暮花在向沉睡的德鲁伊传递信息时被好战的棘木熊怪俘虏，她必须被安全护送回地面，并向多兰纳尔报告平安。",kw={"班奈希尔兽穴","多兰纳尔","逃离班奈希尔","熊怪","棘木","卡多雷","凯拉·星歌","莱尼莎·暮花","神谕之树","泰达希尔"},ang={["class:Druid"]="班奈希尔兽穴本应是沉睡的德鲁伊与翡翠梦境沟通的圣所，它被野蛮的熊怪占领，这对塞纳里奥的保护者来说是一场紧急危机。",["faction:Alliance"]="保护达纳苏斯和泰达希尔需要协助哨兵，对抗被腐化的本土野生生物和部族日益增长的敌意。",["race:NightElf"]="哨兵莱尼莎·暮花是并肩作战的战友，她被困在根须之下，这违背了暗夜精灵与泰达希尔广阔星空和林冠之间的神圣纽带。"},sec={{t="根须下的伏击",b="哨兵莱尼莎·暮花受“神谕之树”委派，前去向在班奈希尔兽穴中休息的德鲁伊传达一条紧急信息。这项原本例行的信使任务却演变成了一场灾难，因为她发现这些地下密室已被好战的棘木熊怪完全占据。她在撤退前被截断去路并遭到伏击，被关押在阴暗的隧道中。她本以为自己难逃一死，直到一位冒险者介入，护送她回到了地面。"},{t="安全返回多兰纳尔",b="对于卡多雷哨兵来说，兽穴的地下阴暗处是一个既不自然又令人厌恶的牢笼，这里远离了艾露恩那令人慰藉的星光，也远离了泰达希尔的广阔天空。从深渊中被救出后，莱尼莎逃回了文明世界，关于她生还的消息也传到了多兰纳尔。在那里，哨兵凯拉·星歌得知好友生还的消息后如释重负，并嘉奖了那些帮助她战友保卫卡多雷人民的冒险者。"}},faq={{q="谁是哨兵莱尼莎·暮花？",a="哨兵莱尼莎·暮花是一位驻扎在泰达希尔的暗夜精灵哨兵。她受“神谕之树”委派，前去向在班奈希尔兽穴中休息的德鲁伊传达一条至关重要的信息，但她在深入地下时遭到了棘木熊怪的伏击并被俘虏。",al={"谁是莱尼莎·暮花","莱尼莎·暮花","谁被困在兽穴里"}},{q="哨兵莱尼莎为什么会进入班奈希尔兽穴？",a="她受“神谕之树”的正式委派，去向在班奈希尔兽穴中沉睡的德鲁伊传达一条信息。当她到达地下兽穴时，还没来得及传达信件，就发现那里已经被敌对的熊怪占领了。",al={"莱尼莎为什么去班奈希尔","莱尼莎的任务是什么","神谕之树 的消息"}},{q="是谁俘虏了哨兵莱尼莎？",a="她被居住在兽穴中的棘木熊怪俘虏了。这些好战且充满敌意的部族在她逃脱前将其伏击，并拖入了深处，这让她担心自己会成为他们的下一顿盘中餐。",al={"谁俘虏了莱尼莎","班奈希尔里有什么熊怪","棘木熊怪"}},{q="什么是班奈希尔兽穴？",a="班奈希尔兽穴是位于泰达希尔的一处地下圣所，位于多兰纳尔以西。传统上，这里是在地底开凿出的暗夜精灵德鲁伊进行深度沟通时的休憩之所，但现在已被腐化的棘木熊怪所占据。",al={"班奈希尔兽穴在哪里","什么是班奈希尔兽穴","泰达希尔兽穴"}},{q="谁是哨兵凯拉·星歌？",a="哨兵凯拉·星歌是一位驻扎在多兰纳尔村的暗夜精灵哨兵。她是莱尼莎·暮花的挚友，正急切地等待着莱尼莎逃脱并安全返回的消息。",al={"谁是凯拉·星歌","在哪里交还“逃离班奈希尔”","多兰纳尔哨兵"}},{q="为什么莱尼莎厌恶身处地下？",a="虽然德鲁伊会利用兽穴进行神圣的沉睡，但许多暗夜精灵哨兵和战士非常不喜欢被困在地下。卡多雷文化珍视广阔的夜空、艾露恩的星光，以及森林树冠的庇护，而不是地下的隧道。",al={"为什么暗夜精灵不喜欢兽穴","地底不属于卡多雷"}}},fp="18,232,26.363.0,23.395.0,36.196.0,52.178.0,30.183.0,29.178.0,30.166.0,42.238.0"}
P.entries["quest:99073"] = {n="Easing Suffering",s="Easing Suffering是泰达希尔的一项任务，其核心内容是为哨兵埃拉莉亚·叶影提供紧急援助，她正躺在通往神谕之树的道路上，饱受一种剧毒腐烂病的折磨。玩家必须争分夺秒地将鞭水愈膏送到她身边，以缓解她的痛苦，让她临终前的气息得到安宁。",h="Easing...",kw={"减轻痛苦","埃拉莉亚·叶影","鞭水愈膏","神谕之树","腐烂病","哨兵埃拉莉亚","泰达希尔"},ang={["faction:Alliance"]="在达纳苏斯的家园道路上援助倒下的暗夜精灵哨兵，有助于守住对抗泰达希尔枝干上日益增长的腐化的脆弱前线。",["race:NightElf"]="哨兵埃拉莉亚·叶影是你的一位同胞，在泰达希尔靠近神谕之树的荒野中，她染上了一种剧毒的腐化。为她提供慰藉，是对哨兵为族人所尽职责的尊崇。"},sec={{t="与腐烂病的赛跑",b="哨兵埃拉莉亚·叶影正躺在通往神谕之树的道路上，深受一种迅速蔓延、不断恶化的腐烂病折磨。为了阻止她痛苦地走向死亡，必须在病情完全恶化之前，尽快将新鲜调制的鞭水愈膏送到她身边。"},{t="阴影中的安宁",b="虽然救治她的人怀疑鞭水愈膏是否有能力彻底根除这种枯萎病，但使用它能迅速平复埃拉莉亚那沉重而含混的呼吸。尽管她能否存活仍是个未知数，但这种治疗确实在她最黑暗的时刻给予了她安宁。"}},faq={{q="哨兵埃拉莉亚·叶影是谁？",a="哨兵埃拉莉亚·叶影是一位暗夜精灵卫兵，人们在通往神谕之树的路上发现了她，当时她正饱受疾病的折磨。她被一种极具侵略性的溃烂腐病击倒，被发现时已失去行动能力，生命垂危。",al={"埃拉莉亚是谁","埃拉莉亚·叶影","哨兵埃拉莉亚是谁"}},{q="什么是鞭水愈膏？",a="鞭水愈膏是一种配制好的药剂，用于缓解哨兵埃拉莉亚所患的剧毒腐烂病引起的剧烈疼痛。虽然不能确定是否能彻底治愈，但它能缓解她的痛苦。",al={"什么是鞭水愈膏","鞭水愈膏","药膏能否治愈腐烂病"}},{q="哨兵埃拉莉亚能从这种疾病中幸存吗？",a="这种药膏缓解了哨兵埃拉莉亚的呼吸，带给她暂时的安宁，但她究竟能否完全康复，还是会屈服于缠身已久的腐烂病，仍不确定。",al={"埃拉莉亚能否幸存","埃拉莉亚是否痊愈","埃拉莉亚死了吗"}},{q="在哪里可以找到哨兵埃拉莉亚·叶影？",a="哨兵埃拉莉亚·叶影位于通往神谕之树的道路旁，处于泰达希尔古老的区域内。",al={"神谕之树在哪里","通往神谕之树的路","埃拉莉亚的位置"}},{q="哨兵埃拉莉亚患了什么病？",a="埃拉莉亚患有一种极具侵略性且不断恶化的腐烂病，这种病在她体内迅速蔓延。这种污染的确切来源尚不明确，但它发作迅速，且随时间推移毒性越来越强。",al={"是什么导致了埃拉莉亚的疾病","什么是腐烂病","埃拉莉亚的病痛"}},{q="为什么要急着送达药膏？",a="腐烂病在埃拉莉亚体内迅速溃烂并加剧。必须争分夺秒，因为每耽误一刻，她就离被痛苦和腐化彻底吞噬更近一步。",al={"为什么要急送药膏","为什么要争分夺秒救埃拉莉亚"}}},fp="16,154,22.200.0,20.222.1,34.154.0,24.157.0,44.135.0,46.89.0,39.144.0,43.165.0"}
P.entries["quest:99079"] = {n="Longwalker Malah",s="远行者玛拉是一位失踪的牛头人侦察兵，她代表血蹄村被派往勘查莫高雷的东部边境。作为直接听命于大酋长的精英远行者，她在出发三天后未能按时归来，这引发了寻找她的紧急行动，以确保她的生存以及山谷的安全。",h="远行者玛拉是一位失踪的牛头人侦察兵，她代表血蹄村被派往勘查莫高雷的东部边境。作为直接听命于大酋长的精英远行者，她在出发三天后未能按时归来，这引发了寻找她的紧急行动，以确保她的生存以及山谷的安全。",kw={"贝恩·血蹄","血蹄村","羽毛法杖","远行者玛拉","远行者组织","玛拉·长风","莫高雷","牛头人侦察兵"},ang={["class:Hunter"]="猎人们尊重远行者所需的野外追踪技能和耐力，他们徒步巡逻莫高雷的最边缘地带。",["faction:Horde"]="协助血蹄村的领导层寻找失踪的边境侦察兵，有助于保护莫高雷免受入侵部落领地的外部威胁。",["race:Tauren"]="远行者是受人尊敬的侦察兵，直接听命于大酋长凯恩·血蹄，因此他们的安全是所有牛头人在文化和战术上都极为关注的问题。"},sec={{t="大酋长的双眼",b="远行者是舒哈鲁人的耳目，他们因不知疲倦的步伐和野外生存技巧而闻名于平原。这些精英侦察兵直接宣誓效忠于大酋长凯恩·血蹄，他们的任务是穿越广阔的领土以收集情报并传递重要信息。虽然他们最终只效忠于大酋长，但年轻的贝恩·血蹄偶尔也会请求他们的协助，以保护血蹄村及其周边的牧场。"},{t="消失在边境",b="远行者玛拉·长风被派往监视莫高雷的东部边境，进行一次例行的三天侦察任务。当她未能按计划返回血蹄村时，村里的领导层感到十分担忧。鉴于远行者掌握着重要情报，且莫高雷边境峭壁处处潜藏危险，人们呼吁侦察兵和乐于助人的旅行者去寻找她的踪迹并确认她的安全。玛拉可以通过她所属组织的传统标志来辨认：一条仪式头带和一根羽毛法杖。"}},faq={{q="谁是远行者玛拉？",a="远行者玛拉·长风是一位受人尊敬的牛头人侦察兵，效忠于大酋长。她被派往莫高雷东部边境附近执行侦察任务，随身携带着代表她所属组织标志的传统头带和羽毛法杖。",al={"谁是玛拉","玛拉背景故事","远行者玛拉身份"}},{q="什么是远行者？",a="远行者是牛头人人民最信任的精英侦察兵和信使。他们的首要忠诚直接对大酋长负责，不过其他部落领袖（例如年轻的贝恩·血蹄）偶尔也会请求他们的帮助，以获取关键的边境情报。",al={"什么是远行者","谁是远行者","牛头人侦察兵"}},{q="为什么要寻找远行者玛拉？",a="玛拉被派去勘查莫高雷的东部边缘，原定三天内返回。当她未能归来时，血蹄村的人们开始担心她在巡逻崎岖边境时遇到了麻烦。",al={"为什么玛拉失踪了","玛拉任务原因","玛拉去了哪里"}},{q="在哪里可以找到玛拉？",a="远行者玛拉被派往莫高雷的东部边境，经过血蹄村向边界山脊进发。寻找她的旅行者必须搜索村庄以东的边境地带。",al={"玛拉在哪里","玛拉位置","寻找玛拉"}},{q="如何辨认远行者玛拉？",a="玛拉可以通过远行者的标志性服饰来辨认：一条独特的头带和一根她所属尊贵组织侦察兵所携带的高大羽毛法杖。",al={"玛拉外观","如何辨认玛拉","远行者装备"}},{q="贝恩·血蹄为什么会与远行者有往来？",a="虽然远行者只向大酋长凯恩·血蹄汇报，但他的儿子贝恩负责血蹄村的当地事务，偶尔会请求他们的追踪专长来监视边境活动并确保山谷的安全。",al={"贝恩角色","为什么贝恩参与其中","贝恩·血蹄侦察兵"}}},fp="16,203,25.371.0,27.450.0,24.193.0,25.197.0,43.189.0,25.154.0,38.106.0,53.244.0"}
P.entries["quest:99080"] = {n="Vertreibt sie",s="贝恩·血蹄要你把加拉克半人马赶出村庄的小路。击败他们，孩子们便能多一分安全。",h="贝恩·血蹄要你把加拉克半人马赶出村庄的小路。击败他们，孩子们便能多一分安全。",kw={"贝恩·血蹄","半人马","孩子","加拉克人","掠夺者赫拉克","斥候","村庄"},ang={["race:Tauren"]="作为一名牛头人，贝恩称这场流血冲突是你们族人独有的荣耀。"},sec={{t="加拉克人",b="贝恩要你杀死六名加拉克半人马和四名加拉克斥候，然后把掠夺者赫拉克的头带给他。村庄的安危岌岌可危。"},{t="村庄的宽慰",b="贝恩听见最后一名半人马倒下，奔袭也随之停歇。他称这一天是村庄的大胜，并说孩子们比以往任何时候都更需要安全感。"}},faq={{q="是谁让我赶走加拉克人？",a="贝恩·血蹄要你对付加拉克半人马和斥候，并把掠夺者赫拉克的头带给他。",al={"是谁交代的","贝恩的任务"}},{q="贝恩想让我做什么？",a="贝恩要你杀死六名加拉克半人马和四名加拉克斥候，然后把掠夺者赫拉克的头带给他。",al={"要做什么","加拉克任务"}},{q="掠夺者赫拉克是谁？",a="掠夺者赫拉克就是贝恩要你带回首级的那个加拉克人。",al={"赫拉克是谁","掠夺者的头"}},{q="这对村庄为何重要？",a="贝恩说，胜利能让村里的孩子获得他们比以往任何时候都更需要的安全感。",al={"为何帮助村庄","孩子安全"}}},fp="13,135,9.145.0,20.171.1,35.110.0,29.109.0,27.68.0,36.96.0"}
P.entries["quest:99081"] = {n="Schwieriges Unterfangen",s="战士英雄 Wildrunner需要 Langläuferin Malah保管的报告。新出现的半人马营地表明，一小股劫掠者已进入莫高雷；必须报告她的死讯。",h="战士英雄 Wildrunner需要 Langläuferin Malah保管的报告。新出现的半人马营地表明，一小股劫掠者已进入莫高雷；必须报告她的死讯。",kw={"baine","血蹄村","半人马营地","战士英雄 wildrunner","langläuferin malah","malah","莫高雷","schwieriges unterfangen"},ang={["race:Tauren"]="作为一名牛头人，你将半人马劫掠者潜入莫高雷的消息带给战士英雄 Wildrunner。"},sec={{t="Malah的报告",b="你将 Langläuferin Malah的报告带给血蹄村的战士英雄 Wildrunner。他想知道 Malah遭遇了什么，以及是谁杀了她。报告带来了令人忧心的消息，必须立刻送到 Baine那里。"}},faq={{q="谁想要 Malah的报告？",a="血蹄村的战士英雄 Wildrunner想要 Langläuferin Malah的报告。",al={"谁需要这份报告","wildrunner的报告","我该把报告交给谁"}},{q="报告涉及什么？",a="报告涉及 Langläuferin Malah遭遇了什么，以及是谁杀了她。",al={"malah遭遇了什么","malah的报告","malah为何死去"}},{q="箭矢指向的方向有什么？",a="一座新出现的半人马营地位于 Malah中箭时箭矢似乎射来的方向。",al={"新半人马营地","半人马营地","劫掠者从哪里来"}},{q="营地说明了什么？",a="营地的活动表明，一小股劫掠者已经潜入莫高雷。",al={"半人马劫掠","莫高雷的劫掠者","营地意味着什么"}},{q="谁需要听到这个消息？",a="战士英雄 Wildrunner说，必须立刻通知 Baine。",al={"通知baine","wildrunner通知baine","谁会接到通知"}}},fp="23,220,14.214.0,25.81.0,29.76.0,35.99.0,27.72.0,27.61.0"}
P.entries["quest:99082"] = {n="The High Chieftain",s="凯恩·血蹄的儿子派你前往雷霆崖，请求觐见他的父亲。你为族人挺身而战，赢得了认可。",h="凯恩·血蹄的儿子派你前往雷霆崖，请求觐见他的父亲。你为族人挺身而战，赢得了认可。",kw={"觐见","凯恩·血蹄","半人马","大酋长","牛头人","萨尔","雷霆崖"},ang={["race:Tauren"]="身为牛头人，你在保卫族人后受命前去拜见凯恩·血蹄。他曾与萨尔并肩作战，努力夺回平原。"},sec={{t="酋长的功绩",b="凯恩·血蹄曾与年轻的大酋长萨尔并肩作战，努力从半人马手中夺回这片平原。身为大酋长，他能够认可你在保卫族人时所立下的功劳。"}},faq={{q="我奉命去见谁？",a="有人请你去觐见雷霆崖的高阶督军凯恩·血蹄。",al={"高阶督军是谁","请求觐见凯恩","拜见凯恩"}},{q="我为什么要去雷霆崖？",a="你保卫族人时展现出的勇气赢得了认可，因此你受命请求觐见凯恩·血蹄。",al={"为何前往雷霆崖","凯恩想要什么","与凯恩会面"}},{q="谁协助夺回了平原？",a="凯恩·血蹄和年轻的大酋长萨尔率领众人，努力从半人马手中夺回平原。",al={"谁与半人马作战","萨尔和凯恩","夺回平原"}},{q="凯恩在哪里？",a="凯恩·血蹄在雷霆崖的中央高地。",al={"大酋长在哪里","凯恩的位置","寻找凯恩"}}},fp="18,136,20.180.0,27.98.0,32.121.0,30.102.0,16.54.0"}
P.entries["quest:991"] = {n="莱恩的净化",s="“莱恩的净化”始于莱恩·狼行者请求冒险者追踪她失踪的朋友泰罗尼恩。为了寻找平息灰谷各地猖獗的熊怪侵略的方法，泰罗尼恩动身前往法拉希姆湖寻找一颗魔法宝石。",h="“莱恩的净化”始于莱恩·狼行者请求冒险者追踪她失踪的朋友泰罗尼恩。为了寻找平息灰谷各地猖獗的熊怪侵略的方法，泰罗尼恩动身前往法拉希姆湖寻找一颗魔法宝石。",kw={"灰谷","法拉希姆","熊怪","宝石","鱼人","莱恩","泰罗尼恩","狼行者"},ang={["faction:Alliance"]="抵达阿斯特兰纳的联盟新兵很快就会了解到，灰谷的神圣林地正受到充满敌意的野生野兽、熊怪和入侵鱼人的围攻。",["race:NightElf"]="泰罗尼恩的失踪对暗夜精灵来说又是沉重的一击，他们本就为了治愈灰谷并保护神龛免受腐蚀而疲于奔命。"},sec={{t="朋友的牵挂",b="莱恩·狼行者在阿斯特兰纳与哨兵部队并肩作战，保卫灰谷免受日益严重的威胁。泰罗尼恩是她最亲密的伙伴之一，他自告奋勇去寻找能有效防御那些愈发暴躁的熊怪部落的方法。当他多日未归时，莱恩深感忧虑，但又因坚守岗位而无法脱身，只能在担忧中饱受煎熬。"},{t="权杖探寻",b="泰罗尼恩追寻着关于一根由已故邪恶法师铸造的强大权杖的传言，相信其魔法能够平息熊怪的怒火。为了修复这件神器，他需要一颗隐藏在位于西侧山脉附近法拉希姆湖一座暗夜精灵神龛中的附魔宝石。不幸的是，这片宁静的水域最近已经被凶猛的鱼人部落占领。"},{t="法拉希姆湖的悲剧",b="沿着泰罗尼恩的踪迹来到法拉希姆湖中的岛屿，展现在眼前的是一幅凄惨的景象。泰罗尼恩没能活着离开这片水域；他的尸体倒在神龛上，身上布满了鱼人武器和利爪留下的深深伤痕，他的探寻也就此画上了终点。"}},faq={{q="莱恩·狼行者是谁？",a="莱恩·狼行者是一位隶属于灰谷哨兵部队的暗夜精灵，驻扎在阿斯特兰纳。她负责监督各项防御工作，以保护森林免受入侵敌人的侵害。",al={"莱恩","莱恩是谁","任务发布者"}},{q="泰罗尼恩是谁？",a="泰罗尼恩是莱恩·狼行者的挚友，他曾寻求古代魔法的解决方案来拯救森林。他相信一根附魔权杖能够平息被腐蚀的熊怪，于是只身前往搜集所需的部件。",al={"泰罗尼恩是谁","泰罗尼恩背景","失踪的朋友"}},{q="泰罗尼恩在哪里失踪的？",a="泰罗尼恩失踪于法拉希姆湖，这片水域位于灰谷西侧山脉脚下，现已被充满敌意的鱼人占领。",al={"泰罗尼恩在哪里","泰罗尼恩位置","法拉希姆湖"}},{q="为什么泰罗尼恩要寻找一颗宝石？",a="这颗宝石是充能一根由已故邪恶法师制作的魔法权杖所需的关键组件。泰罗尼恩希望利用权杖的力量来遏制狂暴熊怪的攻击。",al={"什么宝石","为什么需要宝石","泰罗尼恩的宝石"}},{q="泰罗尼恩遭遇了什么？",a="自从他前往法拉希姆湖后，莱恩就再也没有他的消息。顺着他的足迹便能发现他的结局。",al={"泰罗尼恩怎么死的","杀害泰罗尼恩的凶手","谁杀了泰罗尼恩"}},{q="为什么熊怪要攻击灰谷？",a="灰谷的熊怪在第三次战争后屈服于恶魔的腐蚀与疯狂，导致原本爱好和平的部落转而对他们往日的盟友发动了无休止的暴力攻击。",al={"熊怪攻击","为什么熊怪如此狂暴","熊怪疯狂"}}},fx={["82e89856"]={q="莱恩·狼行者为什么要找到特罗尼斯？",a="特罗尼斯是莱恩·狼行者信赖多年的老友，他曾挺身而出，帮助哨兵对抗暴怒的熊怪。他离开去寻找一根魔棒和一颗宝石，希望借此阻止那些族人遭受的袭击，却再也没有回来。莱恩十分担心他的安危，也迫切想知道他是否找到了能帮助这片饱受蹂躏土地的东西。",al={"莱恩为什么要找特罗尼斯","莱恩·狼行者的动机","为什么寻找特罗尼斯"}}},fp="17,245,18.364.0,22.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99101"] = {n="Our Ancient Enemy",s="Malah的报告送到了贝恩·血蹄手中，他的回应十分严峻。他说，此事必将得到回应。",h="Malah的报告送到了贝恩·血蹄手中，他的回应十分严峻。他说，此事必将得到回应。",kw={"古老的敌人","贝恩·血蹄","玛拉","我们的宿敌","报告"},faq={{q="谁收到了玛拉的报告？",a="贝恩·血蹄收到了玛拉的报告。",al={"谁收到报告","贝恩报告","玛拉的报告"}},{q="贝恩对这份报告怎么说？",a="读完报告后，贝恩说，此事必将得到回应。",al={"贝恩的反应","贝恩说了什么","报告回应"}},{q="谁把报告带给了贝恩？",a="你把玛拉的报告带给了贝恩·血蹄。",al={"带来玛拉报告","谁送来报告","给贝恩的报告"}}},fp="17,102,28.40.0,37.75.0,32.44.0"}
P.entries["quest:99108"] = {n="Sparring Match",s="Sparring Match是一项由格斗训练师唐·石蹄监管的入门试炼。该试炼旨在测试所有新兵，无论其职业或背景如何。它要求冒险者击败三名竞技场新兵或其他的决斗者，以证明他们在正面交锋中的实力。",h="Sparring Match是一项由格斗训练师唐·石蹄监管的入门试炼。该试炼旨在测试所有新兵，无论其职业或背景如何。它要求冒险者击败三名竞技场新兵或其他的决斗者，以证明他们在正面交锋中的实力。",kw={"竞技场","战斗训练","决斗","新兵战士","比武","切磋比试","唐·石蹄"},ang={["class:Warrior"]="虽然唐·石蹄无法对非战士职业进行其特定学科的训练，但他的比武场强调了战士的哲学：战斗的基本功、勇气以及磨砺个人的战斗决心对任何冒险者都有益处。",["race:Tauren"]="唐·石蹄使用传统的牛头人短语，比如“磨砺犄角”来描述对一个人实力的考验，并欢迎任何愿意切磋的对手进入比武竞技场，无论他们的出身如何。"},sec={{t="切磋场地",b="由资深训练师唐·石蹄监管，Sparring Match邀请各路冒险者进入竞技场来测试自己的实力。尽管唐明确表示欢迎那些并非战士职业的人，但他坚持认为，武艺纪律和正面战斗能为这个危险世界中的任何旅行者提供通用的智慧。"},{t="磨砺犄角",b="在唐·石蹄的竞技场里，出身和武器偏好的区别都不重要。无论是使用剑、弓还是法术，挑战者都需要击败三名自愿的对手——无论是训练中的新兵战士还是进行决斗的其他冒险者——来证明自己的战斗准备情况。完成这些战斗后，你将赢得唐的尊重，并获得用于处理战斗伤口的绷带。"}},faq={{q="唐·石蹄是谁？",a="唐·石蹄是一位监管当地比武竞技场的格斗训练师。即使对于那些并非战士职业的人，唐也会提供格斗指导，并邀请有潜力的冒险者在与新兵或自愿同僚的正面战斗中测试自己的实力。",al={"唐·石蹄是谁","唐·石蹄背景故事","任务发布者"}},{q="唐·石蹄对切磋有什么要求？",a="这项试炼要求在竞技场内击败三名对手——可以是进行决斗的其他自愿冒险者，也可以是在唐·石蹄指导下驻扎在那里的新兵战士。其目的是为了展示在正面战斗中的准备情况和武艺能力。",al={"切磋比赛目标","切磋比赛怎么做","与谁战斗"}},{q="为什么战士训练师要训练其他职业？",a="唐·石蹄认为，每一位冒险者，无论其挥舞的是刀剑、长弓还是魔法，都能从正面战斗中受益。在他的竞技场里，出身和特定的职业纪律远不如测试自我和磨砺战斗决心来得重要。",al={"非战士职业可以做吗","为什么其他职业要进行比武","不是战士"}},{q="切磋在哪里进行？",a="比赛就在唐·石蹄面前的露天比武竞技场内进行，新兵们在那里进行训练，而自愿的挑战者也可以在平等的条件下互相切磋。",al={"在哪里对抗新兵","竞技场位置","比武场在哪里"}},{q="我能和玩家决斗而不是对战新兵战士吗？",a="可以。唐·石蹄接受你击败竞技场中训练的新兵战士，也接受你通过正式决斗击败其他冒险者，他只关心你是否在与自愿的对手对抗来测试自己的能力。",al={"我可以和玩家决斗吗","为了任务与玩家决斗","新兵战士还是玩家"}},{q="当你完成比赛时，唐·石蹄会说什么？",a="当你证明了自己的实力并击败三名对手后，唐会认可你的技巧，并对新一代的冒险者寄予希望，同时提供医疗补给来让你处理伤口，为前方的艰难旅途做好准备。",al={"切磋比赛奖励","唐给什么奖励"}}},fp="14,178,20.258.0,20.304.0,22.197.0,56.215.0,50.222.0,41.167.0,58.196.0,57.195.0"}
P.entries["quest:99123"] = {n="Lost in the Shadows",s="“Lost in the Shadows”是一个任务，内容是营救Pal'juh，一位鲁莽的猎人，她独自闯入了危险之中。对她的营救凸显了荒野追踪者在原始的攻击性和耐心的潜行之间所必需的微妙平衡。",h="“Lost in the Shadows”是一个任务，内容是营救Pal'juh，一位鲁莽的猎人，她独自闯入了危险之中。对她的营救凸显了荒野追踪者在原始的攻击性和耐心的潜行之间所必需的微妙平衡。",kw={"猎人","迷失在暗影中","帕尔朱","迅猛龙","老虎"},ang={["class:Hunter"]="该任务强调了一项基本的猎人纪律：耐心，像老虎一样潜行，而不是像饥饿的迅猛龙那样鲁莽冲锋。",["race:Troll"]="Pal'juh的名字和性情反映了年轻的暗矛猎人，他们在掌握克制力之前就急于在荒野中证明自己的实力。"},sec={{t="鲁莽的斥候",b="“Lost in the Shadows”涉及寻找并营救Pal'juh，她是一位才华横溢但脾气火爆的猎人，独自闯入了敌对领地。她不愿等待支援，结果陷入了困境，需要外界的帮助才能确保安全返回。"},{t="狩猎的耐心",b="在Pal'juh获救后，她的监督者们指出，虽然她作为斥候和追踪者的潜力不可否认，但她像迅猛龙一样横冲直撞，而不是像老虎那样耐心地潜行。这次幸存下来的经历严酷地提醒了人们荒野的无情本质。"}},faq={{q="帕尔朱是谁？",a="帕尔朱是一位前途无量的年轻猎人，以独自闯入危险地带而闻名。虽然很有天赋，但她因行事鲁莽而声名狼藉，经常发现自己被野兽和荒野困住或淹没。",al={"帕尔朱是谁","帕尔朱背景故事","帕尔朱"}},{q="在“迷失在阴影中”任务期间发生了什么？",a="在“迷失在阴影中”中，帕尔朱独自外出，再次陷入了麻烦。需要一位冒险者去追踪她，并在她受到严重伤害之前提供援助。",al={"迷失在暗影中发生了什么","迷失在暗影中任务背景","迷失在暗影中故事"}},{q="为什么任务给予者说帕尔朱表现得更像迅猛龙而不是老虎？",a="这个比喻指的是狩猎技巧和纪律。迅猛龙在没有谨慎和预见的情况下猛烈扑击，而老虎则等待、耐心地潜行，并以精确和深谋远虑的狡诈进行攻击。",al={"为什么是迅猛龙和老虎","像迅猛龙而不像老虎的含义","猎人 迅猛龙 老虎"}},{q="谁负责接收“迷失在暗影中”的报告？",a="任务以一位导师或同伴的结语告终，他足够了解帕尔朱并预料到了她的鲁莽，表达了对有人介入营救这位固执的追踪者感到欣慰。",al={"谁接收迷失在暗影中任务","迷失在暗影中任务给予者"}},{q="帕尔朱从这次不幸的冒险中吸取教训了吗？",a="多亏了外界的干预，帕尔朱才度过了这次磨难，尽管她的监督者们仍然在密切关注她是否会真正吸取独自外出带来的危险教训。",al={"帕尔朱吸取教训了吗","帕尔朱还好吗"}},{q="帕尔朱被认为是一位熟练的猎人吗？",a="她被认为是一位有前途的猎人，拥有充足的天赋和勇气，但她的导师警告说，在追踪危险猎物时，单纯的直觉无法取代战术上的耐心。",al={"帕尔朱是优秀的猎人吗","帕尔朱技能"}}},fp="19,119,16.176.0,20.193.0,15.144.0,52.126.0,74.166.0,48.135.0,53.135.0,39.132.0"}
P.entries["quest:99127"] = {n="A Net Disaster",s="“A Net Disaster”是艾尔文森林的一项任务，围绕着水晶湖的一次异常骚乱展开。由于垂钓一无所获，甚至连浅滩里的小鱼都不见了踪影，探险者们被派去检查过夜设置的陷阱。被毁坏的陷阱显示，附近充满敌意的入侵者正在大肆破坏当地的渔具。",h="“A Net...",kw={"渔网灾难","水晶湖","艾尔文森林","鱼类储备","捕鱼陷阱","李","鱼人","麻烦制造者"},ang={["faction:Alliance"]="水晶湖坐落在艾尔文森林的中心地带，因此当地的动荡直接威胁到了支持联盟领土核心区域的生计和补给。"},sec={{t="水晶湖的困境",b="在艾尔文森林的水晶湖，当地渔民面临着渔获量急剧下降的惊人状况。空钩并不罕见，但当连浅滩里的小鱼都消失不见时，日常垂钓就变成了一个严重的谜团。为了尽可能挽回损失，他们设置了过夜陷阱，希望能捕到一些基本的鱼获。"},{t="损坏的陷阱与邻近的麻烦",b="拉出没入水中的陷阱后发现，问题不在于运气不佳，而是赤裸裸的破坏行为。湖岸边充满敌意的邻近生物毁坏了陷阱，如果不加以制止，这将威胁到当地渔民的生计。"}},faq={{q="什么是“渔网灾难”？",a="“渔网灾难”是一项设定在艾尔文森林水晶湖的任务。当地渔民发现鱼儿不再上钩，甚至连小鱼也消失了，这促使人们对过夜陷阱展开调查。",al={"什么是渔网灾难","渔网灾难任务","水晶湖渔网灾难"}},{q="你在哪里检查捕鱼陷阱？",a="捕鱼陷阱位于水晶湖的深水区，是由李在夜间放置的，目的是在常规垂钓失败时维持鱼类的储备。",al={"陷阱在哪里","渔网灾难位置","水晶湖陷阱"}},{q="谁是李？",a="李是水晶湖的一名当地渔民，他连夜设置了陷阱，以帮助在鱼儿不再正常上钩时确保鱼类储备。",al={"谁是李","渔夫李"}},{q="水晶湖的鱼发生了什么事？",a="鱼类已经完全从水面消失了，连一条小鱼都看不见。检查发现，过夜陷阱已经被附近的麻烦制造者毁坏了。",al={"水晶湖的鱼怎么了","为什么水晶湖没有鱼","水晶湖空空如也"}},{q="最后提到的邻近麻烦制造者是谁？",a="任务发布者指的是入侵水晶湖的新的邻近麻烦制造者。在水晶湖的水域和岸边，好斗的鱼人已经建立了营地，并对当地的野生动物和渔具造成了破坏。",al={"谁是附近的麻烦制造者","渔网灾难的麻烦制造者","谁破坏了陷阱"}},{q="为什么鱼类的缺乏对渔民来说是个大问题？",a="任务发布者的生计直接依赖于水晶湖的鱼类资源。随着陷阱受损和捕获量归零，如果不停止这种破坏，他们将面临破产的威胁。",al={"为什么任务发布者很在意","水晶湖渔业"}}},fp="14,165,31.208.0,39.181.1,23.152.0,39.145.0,11.133.0,42.126.0,55.161.0,61.141.0"}
P.entries["quest:99128"] = {n="Slimy Menace",s="“Slimy Menace”讲述了艾尔文森林中水晶湖沿岸日益严重的鱼人滋扰问题。这些极具攻击性的生物威胁要耗尽湖中的鱼类资源，并危及附近的居民，需要迅速采取行动以控制它们的数量。",h="“Slimy Menace”讲述了艾尔文森林中水晶湖沿岸日益严重的鱼人滋扰问题。这些极具攻击性的生物威胁要耗尽湖中的鱼类资源，并危及附近的居民，需要迅速采取行动以控制它们的数量。",kw={"水晶湖","艾尔文森林","鱼","闪金镇","鱼人","黏滑的威胁"},ang={["faction:Alliance"]="保卫水晶湖的湖岸可以保护艾尔文当地的渔民和闪金镇附近的旅行者免受鱼人的袭击。",["race:Human"]="对于艾尔文森林的居民来说，鱼人的侵扰直接威胁着他们的水道、食物来源以及附近定居点的安全。"},sec={{t="水晶湖的麻烦",b="在水晶湖的东岸，一群极具攻击性的鱼人建立了立足点。这些野蛮的半水生生物长着锋利的牙齿，脾气暴躁，将原本平静的水域变成了危险的捕食场。当地居民的生计严重依赖于这个湖泊，但鱼人的出现现在威胁到了任何胆敢在此捕鱼或靠近水边的人。"},{t="无尽的滋扰",b="除了对旅行者造成的直接威胁外，如果任由这些鱼人繁衍，它们会吃光湖里的每一条鱼。削减它们的数量可以给当地水域带来急需的喘息之机，尽管它们那怪异、回荡的鸣叫声依然时刻提醒着人们它们的顽强。即使被驱散，鱼人也能迅速补充兵力，确保对湖岸保持警惕成为一项持续的必要工作。"}},faq={{q="“黏滑的威胁”任务是关于什么的？",a="“黏滑的威胁”是一项关于居住在水晶湖远岸的侵略性鱼人群体的本地任务。如果不加控制，这些两栖生物会吞食当地的鱼类，并威胁任何试图在附近工作或旅行的人。",al={"什么是黏滑的威胁","黏滑的威胁任务信息","黏滑的威胁概述"}},{q="这个任务的事件发生在哪里？",a="这一骚乱发生在艾尔文森林的水晶湖，一群鱼人聚集在对岸的湖边。它们的出现破坏了湖泊的自然生态，并对当地居民构成了危险。",al={"水晶湖的鱼人在哪里","水晶湖位置","事件发生地点"}},{q="为什么要清理水晶湖的鱼人？",a="鱼人正在迅速消耗湖中的鱼类资源，同时用它们残暴的脾气和锋利的牙齿恐吓周围地区。清理它们的队伍有助于保护湖泊的渔业，并暂时阻止它们的扩张。",al={"为什么要杀死水晶湖的鱼人","鱼人吃鱼","鱼人有什么问题"}},{q="清理鱼人能彻底解决问题吗？",a="清理鱼人只能提供暂时的缓解。正如任务完成时所提到的，鱼人的繁殖和重组速度惊人，确保了尽管有最初的损失，它们的数量也会迅速恢复。",al={"鱼人永远消失了吗","我们消灭了鱼人吗","水晶湖的鱼人会回来吗"}},{q="是谁请求协助处理“黏滑的威胁”？",a="该任务由一名关心水晶湖状况的艾尔文当地居民发布。他们对鱼人不安的鸣叫声和贪婪的食欲感到苦恼，因此请求冒险者削减这些生物的数量以保护渔场。",al={"谁发布了黏滑的威胁","黏滑的威胁任务发布者"}},{q="是什么让鱼人成为如此大的威胁？",a="鱼人被描述为残暴、脾气暴躁的两栖生物，长着锋利的牙齿，并发出臭名昭著的喉音。它们聚集在湖岸，极具攻击性地保卫领地，并袭击任何过于靠近它们捕食地点的生物。",al={"鱼人是什么样的","水晶湖鱼人的习性"}}},fp="12,155,23.269.0,22.271.0,37.152.0,45.170.0,47.207.0,58.143.0,40.184.0,37.228.0"}
P.entries["quest:99129"] = {n="A Man About a Murloc",s="“A Man About a Murloc”是一个委托，由一名叫杰森的渔夫发出，他深受当地鱼人的困扰，他的鱼货经常被鱼人抢走。杰森派遣冒险者去咨询雷米，一个当地的怪人，他对这些生物怀有深深的怨恨，并有着自己的盘算。",h="“A Man About a Murloc”是一个委托，由一名叫杰森的渔夫发出，他深受当地鱼人的困扰，他的鱼货经常被鱼人抢走。杰森派遣冒险者去咨询雷米，一个当地的怪人，他对这些生物怀有深深的怨恨，并有着自己的盘算。",kw={"了解鱼人的人","艾尔文森林","鱼","杰森","鱼人","雷米"},ang={["faction:Alliance"]="像湖岸和码头这样的当地定居点经常遭受鱼人的入侵，使艾尔文森林及附近联盟领地的居民和卫兵倍感压力。"},sec={{t="水域危机",b="一位叫杰森的当地渔夫对鱼人抢劫他鱼货的行为感到厌倦。由于知道雷米同样憎恨这些两栖生物，杰森指引旅行者去咨询雷米，看看他是否想出了什么有效的办法将它们从水域中驱逐出去。"},{t="雷米的报复",b="当被问及此事时，雷米发泄着他的不满，称当地卫兵拒绝理会他关于鱼人威胁的持续警告。雷米没有等待官方的援助，而是准备了自己针对这些生物的报复措施，并招募能干的旅行者来协助他的计划。"}},faq={{q="谁发布了“了解鱼人的人”这个任务？",a="当地渔夫杰森派遣冒险者执行此任务，寻求阻止鱼人抢夺他鱼货的方法。",al={"谁发布了打听鱼人的人","谁开启了打听鱼人的人","杰森鱼人任务"}},{q="雷米是谁？",a="雷米是一位以不断抱怨和警告鱼人威胁而闻名的居民，杰森向他咨询对抗鱼人的实际方案。",al={"雷米是谁","艾尔文森林的雷米","雷米在哪里"}},{q="为什么杰森要咨询雷米？",a="鱼人一直在侵扰杰森的捕鱼点并偷窃他的鱼，这促使他寻求外部帮助来保护他的生计。",al={"为什么杰森需要帮助","杰森 鱼 鱼人","杰森的鱼人问题"}},{q="雷米打算如何对付鱼人？",a="雷米声称镇上的卫兵无视他的警告，因此他制定了自己针对这些生物的报复计划，并需要冒险者协助收集材料。",al={"雷米的点子","雷米的计划是什么","雷米鱼人计划"}},{q="为什么卫兵没有处理鱼人的问题？",a="根据雷米的说法，他曾多次尝试向当地卫兵警告日益严重的鱼人威胁，但他们拒绝认真对待他的警告。",al={"艾尔文森林的卫兵与鱼人","为什么卫兵不帮助雷米","雷米的卫兵警告"}},{q="和雷米交谈后会发生什么？",a="与雷米的交谈直接引出了他反击当地鱼人的个人计划，从而引发了后续代表他进行的任务。",al={"打听鱼人的人指向哪里","打听鱼人的人之后","雷米之后的下一个任务"}}},fp="20,132,20.217.0,18.186.0,41.76.0,24.140.0,36.82.0,44.119.0,46.100.0,36.120.0"}
P.entries["quest:99130"] = {n="An Enticing Offer",s="“An Enticing Offer”是一项旨在利用用有毒的duskweed调制的诱饵来驱赶入侵鱼人的当地计划。通过直接从附近的农田收割这种有害杂草，该计划在协助当地农户的同时，也建立了针对海岸害虫的威慑。",h="“An Enticing Offer”是一项旨在利用用有毒的duskweed调制的诱饵来驱赶入侵鱼人的当地计划。通过直接从附近的农田收割这种有害杂草，该计划在协助当地农户的同时，也建立了针对海岸害虫的威慑。",kw={"诱人的提议","暮色草","杰森","鱼人诱饵","鱼人","有毒诱饵"},ang={["class:Hunter"]="追踪者和驯兽师应注意duskweed的毒性，因为如果误食，由此制成的诱饵会对家养野兽和狩猎伙伴构成严重威胁。",["profession:Herbalism"]="熟悉当地植物的采集者会认识到duskweed的双重性质，这种讨人厌的杂草在调制强效诱饵时需要小心处理其有毒花瓣。"},sec={{t="一举两得的方案",b="对付鱼人泛滥通常需要更有创意的害虫防治手段，而不是无休止的正面冲突。“An Enticing Offer”提出了一种巧妙的解决方案，可以一举解决两个当地难题：制作一种掺有duskweed的特制诱饵，以阻止鱼人侵入定居点，同时在此过程中清除邻近农田中的杂草。"},{t="Duskweed的特性",b="这种合剂的核心成分是duskweed，一种困扰附近农田的顽固野生杂草。大量duskweed的花瓣中含有对大多数野兽有害的强力毒素。通过直接从受困扰的农户那里收集这种杂草，既能清除田地里肆虐的害虫植物，其有毒的产物又能为训练鱼人种群远离此地提供必要的原材料。"},{t="水域诱饵",b="虽然所得的合剂制备起来相对简单，但duskweed无差别的毒性使得处理它具有一定的危险性。家畜和宠物必须严格远离成品混合物，任务发布者临走前还提醒确保当地的熟人，也就是那个叫Jason的人，不会把这种刺鼻的诱饵当成食物。"}},faq={{q="任务“诱人的提议”是什么？",a="“诱人的提议”是一项旨在应对当地鱼人威胁，同时协助附近农户的任务。它涉及收集材料来调制一种专门用来驱赶这些生物的特殊有毒诱饵。",al={"什么是诱人的提议","这个任务是什么"}},{q="暮色草是什么？",a="暮色草是一种侵扰当地农田的常见杂草。虽然它通常被视为一种农业害虫，但其花瓣在大量堆积时对大多数动物有毒，这使得它在被浓缩成诱饵后成为一种有效的害虫威慑物。",al={"什么是暮色草","暮色草植物","暮色草的效果"}},{q="这种鱼人诱饵是如何起作用的？",a="该计划是制作注入了有毒暮色草花瓣的诱饵。目标不是常规的消灭，而是让诱饵变得足够令人不快或有害，从而训练当地的鱼人种群避开该区域。",al={"诱饵是如何起作用的","鱼人毒饵","为什么要制作诱饵"}},{q="贾森是谁？",a="贾森是一位因为鱼人骚扰而把你派去找雷米的渔夫。一旦有毒的暮色草诱饵制作完成，雷米嘱咐要告诉贾森千万别吃它。",al={"贾森是谁","不要让贾森吃掉它","关于诱饵给贾森的警告"}},{q="这种鱼人诱饵对其他生物有危险吗？",a="是的。虽然它是针对鱼人的，但大量暮色草花瓣对大多数动物都有毒。任务发布者特别提醒，必须让家养宠物和狩猎伙伴远离这种混合物。",al={"暮色草诱饵有危险吗","宠物误食诱饵"}},{q="为什么说收集暮色草是双赢的？",a="暮色草会疯狂入侵耕地，让当地农户头疼不已。收集这种杂草来酿制诱饵既能清理农田，又能同时提供击退鱼人所需的材料。",al={"为什么要帮助农户","双赢局面"}}},fp="17,106,18.229.0,22.296.0,18.227.0,36.144.0,17.165.0,40.130.0,13.123.0,48.127.0,47.160.0"}
P.entries["quest:99131"] = {n="Baited for Success",s="“Baited for Success”的任务内容是协助当地渔夫贾森·玛瑟斯处理棘手的鱼人骚扰问题。通过与雷米合作准备一种定向毒饵，Mathers希望能清理航道，从而安全地恢复捕鱼生意。",h="“Baited for Success”的任务内容是协助当地渔夫贾森·玛瑟斯处理棘手的鱼人骚扰问题。通过与雷米合作准备一种定向毒饵，Mathers希望能清理航道，从而安全地恢复捕鱼生意。",kw={"巧用诱饵","钓鱼","贾森·玛瑟斯","鱼人","毒饵","雷米"},ang={["class:Rogue"]="使用定制毒药作为控制麻烦鱼人的害虫防治手段，体现了一种务实、低调的解决问题方式。",["faction:Alliance"]="确保水域安全并恢复渔业等当地贸易，可以在减少鱼人威胁的同时，维持定居点的物资供应。"},sec={{t="渔夫的困境",b="贾森·玛瑟斯依靠开阔水域维持渔业贸易，但一群极具攻击性的鱼人扰乱了他的工作。由于无法安全地出售渔获，他试图寻找一种解决方法来清除该地区的生物。雷米介入并制作了一种专门的毒饵，旨在减少当地的鱼人数量，以便恢复正常的捕鱼作业。"},{t="定向解决方案",b="雷米准备了这种有毒混合物，并承诺会告知正确的使用方法，确保毒药只会针对鱼人，而不会污染鱼类。收到消息后，Mathers计划在当天晚些时候去收集混合物，希望它最终能清理水域并恢复他的生计。"}},faq={{q="是谁为贾森·玛瑟斯准备了诱饵？",a="雷米为贾森·玛瑟斯准备了专用诱饵，并承诺在玛瑟斯当天晚些时候过来时，向他说明其正确的使用方法。",al={"谁发布诱饵助成功","雷米诱饵任务","谁制作了诱饵"}},{q="为什么贾森·玛瑟斯需要这种诱饵？",a="贾森·玛瑟斯是一位渔夫，由于当地鱼人的存在，他难以出售自己的渔获。这种毒饵旨在捕杀鱼人，同时又不伤害他打算捕捞和出售的鱼类。",al={"为什么贾森·玛瑟斯需要诱饵","玛瑟斯渔业生意","为什么使用毒饵"}},{q="毒饵会伤害鱼类吗？",a="玛瑟斯特别提到了他对鱼类可能会误食毒饵的担忧。该计划依赖于毒药只针对鱼人而不伤害鱼类的特性，这样玛瑟斯就能恢复他的生计。",al={"诱饵对鱼类安全吗","毒饵会杀死鱼类吗"}},{q="这项任务在哪里完成？",a="这项任务是通过直接将更新带回给贾森·玛瑟斯来完成的，让他知道雷米的准备工作正在进行中。",al={"在哪里交付诱饵助成功","诱饵助成功任务终点"}},{q="鱼人对玛瑟斯构成了什么威胁？",a="鱼人扰乱了当地的捕鱼水域，使得像玛瑟斯这样的渔夫在鱼人数量减少之前，无法正常谋生或谋生存在危险。",al={"为什么在这里消灭鱼人","玛瑟斯的鱼人问题"}},{q="玛瑟斯在收到雷米的消息后有什么打算？",a="一旦消息送达，玛瑟斯决定在当天晚些时候去找雷米领取毒饵，并接受关于如何安全部署它的指导。",al={"交付信息后会发生什么","玛瑟斯拿到了诱饵吗"}}},fp="18,149,21.212.0,19.223.1,40.121.0,38.175.0,37.154.0,29.69.0,43.144.0,49.123.0"}
P.entries["quest:99134"] = {n="Discipline",s="“纪律”是提瑞斯法林地的一项任务，由执行官塞加德发布。由于对当地死亡卫士驻军的能力感到不满，塞加德委托外来的冒险者对那些懈怠的亡灵哨兵施以体罚。",h="“纪律”是提瑞斯法林地的一项任务，由执行官塞加德发布。由于对当地死亡卫士驻军的能力感到不满，塞加德委托外来的冒险者对那些懈怠的亡灵哨兵施以体罚。",kw={"黑暗女王","死亡卫士","纪律","执行官塞加德","被遗忘者","激励棒","提瑞斯法林地","亡灵"},ang={["faction:Horde"]="被遗忘者指挥官们冷酷的手段展现了部落北部领地在生活和治理上那严苛且不留情面的现实。",["race:Undead"]="对于被遗忘者来说，军事纪律关乎种族的生存。屈服于冷漠的哨兵会危及整个提瑞斯法林地。"},sec={{t="在亡灵状态下强制执行秩序",b="死亡卫士构成了被遗忘者在洛丹伦的军事脊梁，但脱离了巫妖王的铁腕意志也带来了一些并发症：冷漠、疲劳和玩忽职守。像执行官塞加德这样的监工对于松懈的纪律几乎没有耐心，尤其是考虑到血色十字军和天灾军团的威胁正在提瑞斯法林地的边界徘徊。为了让部队保持敏锐，军官们依靠钝器和强硬的监督来维持军事战备状态。"},{t="执行官的账簿",b="执行官塞加德故意聘请独立的行动者，而不是驻军内部的士兵来执行惩罚。利用执行官的“激励棒”，外来者提醒玩忽职守的死亡卫士，在为黑暗女王服务时，生存需要绝对的警惕。那些玩忽职守的人很快就会明白，亡灵的身份并不能让他们逃脱惩罚。"}},faq={{q="谁发布了“纪律”任务？",a="“纪律”任务由执行官塞加德发布，他是一位驻扎在提瑞斯法林地的严苛的被遗忘者军官，负责监督区域防御，并要求部队绝对服从。",al={"纪律任务发布者","谁开启纪律任务","执行官塞加德任务"}},{q="执行官塞加德为什么要惩罚死亡卫士？",a="塞加德认为他指挥下的死亡卫士能力不足且缺乏应有的动力。因为自满威胁着被遗忘者在提瑞斯法林地的生存，他实施严厉的纪律，以震慑哨兵，使其保持警觉。",al={"为什么要惩罚死亡卫士","为什么要激励死亡卫士","塞加德惩罚死亡卫士的原因"}},{q="为什么塞加德使用冒险者而不是其他士兵？",a="塞加德指出，作为一个尚未成为死亡卫士一员的外来者，你还没有机会让他失望。",al={"为什么要我执行纪律","塞加德为什么使用外来者"}},{q="什么是执行官的“激励棒”？",a="执行官的“激励棒”是执行官塞加德提供的一种惩戒工具。它被用来对驻扎在提瑞斯法林地各处的懒散死亡卫士进行痛苦的训诫。",al={"执行官的激励棒","什么是执行官的激励棒"}},{q="如果你拒绝塞加德的命令会发生什么？",a="塞加德警告说，犹豫或拒绝会导致你的名字被记入他的账簿，标记你为下一个被他人惩戒的目标。",al={"塞加德的威胁","账簿威胁"}},{q="被遗忘者如何看待痛苦？",a="塞加德认为痛苦是他死后仅存的少数乐趣之一。他对于惩罚的热衷反映了他严酷的性格。",al={"亡灵是否会感到痛苦","被遗忘者痛苦背景"}}},fp="10,162,26.376.0,21.299.0,31.124.0,54.172.0,61.98.0,33.125.0,42.133.0,30.123.0"}
P.entries["quest:99141"] = {n="Patience",s="“耐心”是提瑞斯法林地执行官塞加德所分配的一项任务，要求为黑暗女王保持严明的军事纪律。由于常规战场报告逾期未交，塞加德派遣一名冒险者从附近的亡灵卫兵以及一个不同寻常的哨兵那里收集最新的报告。这项任务突显了被遗忘者领地内所执行的那种严苛、不妥协的纪律。",h="“耐心”是提瑞斯法林地执行官塞加德所分配的一项任务，要求为黑暗女王保持严明的军事纪律。由于常规战场报告逾期未交，塞加德派遣一名冒险者从附近的亡灵卫兵以及一个不同寻常的哨兵那里收集最新的报告。这项任务突显了被遗忘者领地内所...",kw={"布瑞尔","黑暗女王","亡灵卫兵","迪林格尔","戈多","克里斯托夫","耐心","静水池","提瑞斯法林地","塞加德"},ang={["faction:Horde"]="这项任务让到访的部落盟友得以一窥希尔瓦娜斯·风行者的军官们在整个提瑞斯法执行的那种冷酷、高度纪律化的指挥结构。",["race:Undead"]="对于新解放的被遗忘者来说，执行塞加德的命令强化了洛丹伦残酷的生存现实：对黑暗女王的绝对忠诚，以及对失败的零容忍。"},sec={{t="执行黑暗女王的意志",b="执行官塞加德负责指挥提瑞斯法林地的当地防务，他不容许任何疏忽。在塞加德看来，效忠希尔瓦娜斯女士必须时刻保持绝对的效率。当常规战场派遣报告没能按时送达他的哨岗时，他将其视为一次不可接受的失职，而非简单的延迟。他并没有离开岗位去亲自调查，而是派新来的被遗忘者特工去纠正那些玩忽职守的下属，确保边境依然稳固。"},{t="林地的哨兵",b="这些派遣任务涉及到驻守在布瑞尔周围关键观察点的哨兵。亡灵卫兵迪林格尔负责监视西边的墓地，那里经常有不法亡灵和天灾军团的残党在活动。在东边，亡灵卫兵克里斯托夫负责看守一处哨所，守卫着通往洛丹伦王城和东部道路的入口。而在他们之中最不寻常的要数戈多，一个在静水池附近游荡的庞大缝合怪，其单纯的思维让他去进行军事记录显得非常荒谬。"}},faq={{q="执行官塞加德是谁？",a="执行官塞加德是一名高级被遗忘者军官，负责维持提瑞斯法林地布瑞尔周边的秩序和防御。他直接向效忠于希尔瓦娜斯女士的指挥层负责，并要求他所监管的所有部队必须完美地执行任务。",al={"塞加德","谁是塞加德","执行官塞加德职责"}},{q="为什么塞加德要派冒险者去收集报告？",a="几名战场哨兵没能按时提交预定的报告。塞加德没有耐心等待，也不愿离开他的中央哨岗，于是他雇佣新获得自由的被遗忘者去乡野间找回那些逾期的派遣报告。",al={"为什么要完成耐心任务","为什么要收集报告"}},{q="戈多是谁，为什么他会有报告？",a="戈多是一个在静水池西边游荡的缝合怪。塞加德像对待其他战场哨兵一样期待从他那里得到状态报告，尽管在收到报告后，这位执行官很快意识到期待一个缝合怪写出书面情报是一个尴尬的判断失误。",al={"戈多","为什么缝合怪会有报告","谁是戈多"}},{q="亡灵卫兵迪林格尔在哪里？",a="亡灵卫兵迪林格尔驻扎在布瑞尔西侧，守卫着当地的墓地，监视徘徊的天灾活动和新复活的尸体。",al={"迪林格尔位置","找到迪林格尔","迪林格尔在哪里"}},{q="亡灵卫兵克里斯托夫驻扎在哪里？",a="亡灵卫兵克里斯托夫驻扎在布瑞尔以东道路旁的哨所，守卫入口以防入侵者，并监视路上的交通。",al={"克里斯托夫位置","找到克里斯托夫","克里斯托夫在哪里"}},{q="当戈多的报告被上交后会发生什么？",a="执行官塞加德承认期待一个缝合怪写出一份连贯的书面报告是一个愚蠢的错误。他默默接受了结果，并要求你将这次尴尬的疏忽仅限于你和他之间知道。",al={"戈多报告的结果","戈多书写"}}},fp="8,159,30.345.0,23.418.0,23.183.0,54.181.0,43.199.1,38.122.0,38.107.0,46.185.1"}
P.entries["quest:99142"] = {n="Tomb Weed",s="Tomb Weed是提瑞斯法林地的一项炼金任务，由药剂师助理霍兰德发布。霍兰德一直在改良野生的厄运草并将其重新种植在闹鬼的巴尼尔农场，这种被培育出的强力新样本意外地吸引了当地的天灾军团。",h="Tomb Weed是提瑞斯法林地的一项炼金任务，由药剂师助理霍兰德发布。霍兰德一直在改良野生的厄运草并将其重新种植在闹鬼的巴尼尔农场，这种被培育出的强力新样本意外地吸引了当地的天灾军团。",kw={"巴尼尔农场","厄运草","戈多","药剂师助理霍兰德","皇家药剂师学会","提瑞斯法林地","墓地草"},ang={["profession:Herbalism"]="Tomb Weed展示了人工炼金操纵如何能从根本上改变像厄运草这样枯萎草药的特性和行为。",["race:Undead"]="药剂师助理霍兰德的研究表明，被遗忘者药剂师们一直致力于将提瑞斯法枯萎的植物群重塑为定制的炼金工具。"},sec={{t="霍兰德的培育",b="药剂师助理霍兰德并不满足于仅仅为皇家药剂师学会采集原生草药；他有着自己的宏大抱负。通过收集厄运草并对其进行细微的炼金改造，他将这些草药重新种植在巴尼尔农场的土壤中，培育出了一种他命名为Tomb Weed的进化样本。霍兰德将这种混合植物视为他工作的核心，也是他个人命运的前兆。"},{t="意外的吸引力",b="虽然霍兰德预料到了炼金效力，但将Tomb Weed移植到巴尼尔农场产生了意想不到的副作用。在枯萎的田野中游荡的天灾军团残余对这种茁壮成长的植物表现出了不可思议的普遍吸引力。霍兰德依靠路过的旅行者来突破这些入侵的亡灵并收获成熟的作物，以便他能继续他的实验。"}},faq={{q="什么是墓穴草？",a="墓穴草是由药剂师助理霍兰德培育的一种经炼金改良的厄运草变种。他采集原生的厄运草，用化学试剂对其进行改造，并将其种植在巴尼尔农场枯萎的土壤中。",al={"什么是墓地草","墓地草背景故事","墓地草植物"}},{q="药剂师助理霍兰德是谁？",a="霍兰德是皇家药剂师学会的一员，在提瑞斯法林地工作。他雄心勃勃，经常被像憎恶戈多这样的助手弄得心烦意乱，霍兰德进行私人园艺和炼金实验，旨在提升自己的地位。",al={"霍兰德是谁","药剂师助理霍兰德","药剂师霍兰德"}},{q="墓穴草种植在哪里？",a="霍兰德将他改良的作物种植在巴尼尔农场，这是一处位于提瑞斯法林地东部的废弃庄园，现已陷入枯萎和荒废之中。",al={"去哪里找墓地草","墓地草位置","巴尼尔农场的杂草"}},{q="为什么天灾军团会被墓穴草吸引？",a="霍兰德观察到，游荡在巴尼尔农场中毫无意识的天灾军团似乎本能地被这种改良植物所吸引，尽管他不知道原因；他只是觉得这很奇怪。",al={"为什么天灾军团想要墓地草","天灾军团被墓地草吸引","天灾军团的反应"}},{q="墓穴草与普通厄运草有何不同？",a="厄运草是一种在布瑞尔墓地北部的乱葬岗附近自然生长的植物。墓穴草是在霍兰德的指导下，将厄运草进行人工炼金改造并选择性地重新种植在农场土壤中而产生的。",al={"厄运草与墓地草的区别","厄运草和墓地草的差异"}},{q="霍兰德提到的戈多是谁？",a="戈多是被遗忘者制造的一只游荡的憎恶，在提瑞斯法林地的道路上徘徊，通常被霍兰德分配一些对他迟钝的大脑来说很困难的简单任务。",al={"戈多是谁","戈多行踪","戈多提瑞斯法"}}},fp="9,152,21.321.0,21.259.0,18.143.0,33.248.0,25.136.0,43.140.0,48.175.0,34.182.0"}
P.entries["quest:99143"] = {n="Bottles and Baubles",s="Bottles and Baubles 是一个任务，其核心逻辑有些古怪：既然鱼人长得像鱼，那它们的思维一定也像鱼。冒险者被派往附近的鱼人营地，搜寻那些闪闪发光的垃圾和废弃的小玩意，一位急切的垂钓者可以将它们制成鱼饵。",h="Bottles and Baubles 是一个任务，其核心逻辑有些古怪：既然鱼人长得像鱼，那它们的思维一定也像鱼。冒险者被派往附近的鱼人营地，搜寻那些闪闪发光的垃圾和废弃的小玩意，一位急切的垂钓者可以将它们制成鱼饵。",kw={"鱼饵","瓶子与饰品","钓鱼","假饵","鱼人","鱼人营地","闪亮垃圾"},sec={{t="鱼类逻辑与海岸拾荒",b="Bottles and Baubles 从一个非常奇特的海洋生物学理论开始：既然鱼人是类鱼生物，它们的思维方式一定和深海中游动的鱼类一样。基于这种逻辑，一位古怪的垂钓者断言，任何能吸引鱼人目光的好奇之物，也一定能引诱饥饿的鱼儿上钩。冒险者们受命前往附近的鱼人营地，搜刮它们的囤积物，收集闪闪发光的废弃垃圾，以验证这一假说。"},{t="闪亮的小玩意作为鱼饵",b="沿海水道和河岸上的鱼人是臭名昭著的拾荒者，它们在小屋周围杂乱地堆积着明亮的石头、贝壳、抛光的玻璃碎片和金属残渣。翻找这些泥泞的堆积物，可以找到各种各样闪闪发光的废品，机会主义的渔夫可以将它们制成简陋的假饵和闪光片。一旦收回并上交，这些奇怪的杂物足以让冒险者获得一套入门钓鱼用品。"}},faq={{q="为什么要从鱼人那里收集垃圾？",a="任务发布者认为，既然鱼人长得像鱼，它们的思维也一定和鱼一样。基于“吸引鱼人的东西也能吸引水底的鱼”这一理论，冒险者们被派往鱼人营地搜刮饰品和闪亮的废品，将其改造成鱼饵。",al={"为什么要收集垃圾","瓶子和饰品有什么用","鱼人闪亮垃圾"}},{q="哪里可以找到闪亮的垃圾？",a="闪亮的垃圾散落在附近的鱼人营地周围。鱼人是臭名昭著的拾荒者，它们会在海岸线和水道沿岸囤积闪闪发光的碎片、废弃的饰品和玻璃，这些可以直接从它们的地盘上获取。",al={"在哪里找到垃圾","鱼人营地位置","如何获得闪亮垃圾"}},{q="谁发布了这个任务，他们想要什么？",a="该任务由一位当地的垂钓者委托，他正想储备一些假饵和鱼饵。虽然他对鱼人心理学的理论有些古怪，但他会用多余的垂钓装备奖励热心的拾荒者，以鼓励新手们学习这门手艺。",al={"谁发布了瓶子和饰品","任务发布者是谁","任务交还"}},{q="鱼人真的像鱼一样思考吗？",a="尽管任务发布者有这种推理，但鱼人是两栖的部落类人生物，而不是简单的无脑鱼类。然而，就像许多生物和捕食者一样，它们天生会被闪闪发光的物品、抛光的贝壳和明亮的小玩意所吸引，从而形成了恰好包含闪亮材料的囤积堆。",al={"鱼人像鱼一样思考吗","鱼人的智力","鱼人真的是鱼吗"}},{q="鱼人的垃圾将如何被用作鱼饵？",a="收集到的垃圾包括反光玻璃、金属碎片和抛光的零碎物件。这位垂钓者打算将这些反光碎片制成假饵和临时鱼饵，希望它们的光泽能模仿小鱼，或者引起觅食鱼类的好奇。",al={"闪亮垃圾的用途","闪亮垃圾是鱼饵吗","鱼人垃圾能当鱼饵吗"}},{q="任务发布者提供什么奖励？",a="在带回足够多合适的闪亮碎片后，任务发布者会交出他以前的个人垂钓用品。这些基础工具和补给旨在帮助有抱负的渔夫们站稳脚跟，并在水边试手。",al={"瓶子和饰品的奖励是什么","你能得到什么","钓鱼用品奖励"}}},fp="19,100,35.301.0,24.322.0,45.223.0,30.139.0,42.147.0,36.222.0,41.192.0,43.189.0"}
P.entries["quest:99144"] = {n="Seeking Refuge",s="Seeking Refuge是提瑞斯法林地的一项任务，内容是营救班达里安堡的使者Bareth Dawnstone，他被囚禁在Crusader's Outpost。他的挣扎凸显了一个非传统教派的出现，该教派尽管受到了当地狂热分子的严重偏见，却依然虔诚于圣光。将他逃脱的消息安全传回布瑞尔，为这个初生的圣所确立了至关重要的联系。",h="Seeking Refuge是提瑞斯法林地的一项任务，内容是营救班达里安堡的使者Bareth Dawnstone，他被囚禁在Crusader's...",kw={"班达里安堡","巴雷斯·晨石","布瑞尔","十字军前哨","十字军","圣光","寻求庇护","莎莉·斯迪威尔","索利丹农场","提瑞斯法林地"},ang={["class:Paladin"]="圣骑士们可以留意一下Crusader's Outpost的狂热分子与Bareth Dawnstone之间的对比：前者怀着仇恨运用圣光，而后者追求仁慈与保护。",["class:Priest"]="牧师们会发现班达里安堡的哲学非常迷人，因为尽管周围对亡灵施法者存在偏见，其成员仍在追求纯粹的冥想和圣光的指引。",["faction:Horde"]="确保班达里安堡和布瑞尔之间的信使安全，可以确保新兴的中立或盟友教派在提瑞斯法林地站稳脚跟，以对抗敌对的十字军。",["race:Undead"]="依然崇敬圣光的被遗忘者既面临来自活人狂热分子的敌意，也面临来自怀疑论同胞的敌意，这使得班达里安堡不断壮大的兄弟会成为了一个罕见的圣所。"},sec={{t="危险的旅程",b="Seeking Refuge讲述了班达里安堡隐秘修道院派遣的信使Bareth Dawnstone的惊险旅程。在前往布瑞尔与Shari Stilwell商议的途中，Bareth在Crusader's Outpost被狂热的战士拦截并俘虏。尽管他的亡灵身份招致了仇恨，但Bareth对圣光的虔诚始终如一，他唯一的渴望就是逃离折磨者，并确保他的信息送达目的地。"},{t="复仇与虔诚",b="Bareth的被囚突显了笼罩在提瑞斯法林地的痛苦意识形态分歧。Crusader's Outpost的狂热分子通过复仇的愤怒和教条式的正义来引导圣光，将Bareth的存在视为一种冒犯。相比之下，Dawnstone将圣光视为保护和内在纯洁的源泉，他感叹捕获者的残忍扭曲了他所珍视的神圣教义。"},{t="山崖上的圣所",b="逃脱后，Bareth在布瑞尔向Shari Stilwell确认了安全。斯迪威尔透露，他们的修道会仍在索利丹农场西北部的山崖上扎根。失去像Dawnstone这样有前途的修行者，对他们年轻的团体来说将是沉重的打击，该团体向任何寻求真正精神指引的旅行者敞开大门。"}},faq={{q="巴雷斯·晨石是谁？",a="巴雷斯·晨石是班达里安堡的一位圣光信徒。在前往布瑞尔传递信息的途中，他遭到了厌恶他这一类的狂热十字军的伏击并被监禁。尽管他身为亡灵，但他仍冥想圣光，并努力利用圣光进行保护。",al={"巴雷斯·晨石是谁","巴雷斯·晨石背景故事","晨石"}},{q="谁俘虏了巴雷斯·晨石，为什么？",a="驻扎在十字军前哨站的狂热分子在从班达里安堡通往布瑞尔的路上伏击了巴雷斯·晨石。他感叹道，他的捕获者内心怀着强烈的仇恨运用圣光，扭曲了他所冥想的仁慈美德，并迫害那些他们视为憎恶之物的人。",al={"谁俘虏了巴雷斯·晨石","十字军前哨捕获者","他为何被俘"}},{q="莎莉·斯迪威尔是谁？",a="莎莉·斯迪威尔是驻扎在被遗忘者城镇布瑞尔的修道会代表。她接待旅行者，并与从班达里安堡派遣的使者进行协调，欢迎任何寻求圣光指引的人。",al={"莎莉·斯迪威尔是谁","斯迪威尔 布瑞尔","莎莉 布瑞尔"}},{q="什么是班达里安堡？",a="班达里安堡是一座隐秘的修道院，位于提瑞斯法林地的索利丹农场西北部的山崖上。它是一个蓬勃发展的宗教教派的圣所和训练场，致力于对圣光的纯粹冥想和研究。",al={"什么是班达里安堡","班达里安堡在哪里","索利丹西北部的修道院"}},{q="为什么巴雷斯的捕获者会对他的种族有意见？",a="巴雷斯·晨石提到了“我仅存的血液”，并承认了针对他这一类的偏见，这表明他是一位圣光的亡灵修行者。提瑞斯法的狂热十字军鄙视所有亡灵，拒绝相信他们的意图或虔诚可能是纯洁的。",al={"为什么他们仇恨他这类人","亡灵使用圣光","巴雷斯我仅存的血液"}},{q="班达里安堡驻扎的是什么样的教派？",a="驻扎在班达里安堡的教派是一个年轻、不断发展的修道兄弟会，正在提瑞斯法的山崖上扎根。与附近充满仇恨的十字军不同，他们宣扬和平的冥想和保护，并向任何寻求圣光真正指引的人敞开大门。",al={"班达里安堡的教派是什么","班达里安堡僧侣","班达里安信仰"}}},fp="14,228,18.299.0,25.284.0,23.310.0,24.233.0,39.241.0,22.205.0,23.223.0,49.259.0,46.202.0"}
P.entries["quest:99152"] = {n="As Above, So Below",s="“As Above, So Below”是班达里安堡的破击者希尔达发布的一项任务，旨在应对影谷下方潜藏的天灾军团渗透。通过回收那些仍带有新鲜复生魔法气息的骸骨，保卫者们试图弄清楚亡灵是如何在城镇下方悄无声息地聚集起来的。",h="“As Above, So Below”是班达里安堡的破击者希尔达发布的一项任务，旨在应对影谷下方潜藏的天灾军团渗透。通过回收那些仍带有新鲜复生魔法气息的骸骨，保卫者们试图弄清楚亡灵是如何在城镇下方悄无声息地聚集起来的。",kw={"上下如一","班达里安堡","发光的骸骨","破击者希尔达","复生魔法","天灾军团","影谷","玷污者"},ang={["class:Mage"]="法师们会注意到附着在发光骸骨上的残留复生魔法，这暗示了隐藏在城镇下方的特定死灵技术。",["class:Paladin"]="圣骑士将任何未被察觉的天灾势力视为迫在眉睫的危险，因此调查影谷下方的复生魔法是一项紧迫的职责。",["class:Priest"]="受过反亡灵训练的牧师们对于在定居点下方滋生的黑暗复生艺术感到十分忧虑。"},sec={{t="隐秘的威胁",b="在班达里安堡，破击者希尔达负责监督防御者们针对周边险境进行的严格训练。尽管地表的目光都集中在西南方向动荡不安的影谷定居点——那里有一个被称为“玷污者”的敌对势力频繁制造事端——但在视线之外，更大的危险已经扎根。在城镇下方的阴暗地窖中，一股未被察觉的天灾力量正在积蓄，如果任其发展，随时可能对堡垒发动突袭。"},{t="地窖中的魔法",b="希尔达不愿让毫无经验的学员盲目闯入地下墓穴，因此派遣经验丰富的冒险者直接进入影谷下方的地窖。这不仅仅是一次清剿行动，其首要目标是收集情报：回收那些仍带有残留复生魔法的骸骨残骸。研究这些微弱发光的骨头，能让防御者们有机会破解这种黑暗死灵术是如何在眼皮底下悄然运作的。"}},faq={{q="什么是“地上地下”？",a="“地上地下”是破击者希尔达委派的一项任务，旨在调查潜伏在影谷定居点下方的天灾军团势力。在班达里安堡的学员们接受操练的同时，一位冒险者被派往城镇下方收集复生的骸骨样本。",al={"什么是 如上亦如下","如上亦如下 任务"}},{q="是谁发布了“地上地下”任务？",a="破击者希尔达是班达里安堡一位严苛的教官，负责训练新兵。她坚韧且不妥协，对指挥下的任何人都有严格的要求，她宁愿新兵躺着被抬回来，也不愿他们空手而归。",al={"谁发布了 如上亦如下","谁是破击者希尔达","任务发布者希尔达"}},{q="影谷位于哪里？",a="影谷位于班达里安堡的西南方。虽然地表的麻烦主要源于一个名为“玷污者”的团体，但其地下的地窖中却隐藏着更阴险的亡灵侵害。",al={"影谷在哪里","影谷位置"}},{q="潜伏在影谷下方的是什么威胁？",a="影谷下方的地窖已被复生的亡灵所占据。如果放任不管，这股隐藏的天灾势力随时可能引发一场针对附近班达里安堡的全面暴乱。",al={"影谷下方的地窖是什么","影谷地窖中的天灾军团","影谷下方的威胁"}},{q="希尔达为什么需要微弱发光的骸骨？",a="希尔达需要那些仍带有复生魔法残留气息的骸骨。通过研究这些发光的残骸，防御者们希望能够理解死灵法师是如何在未被发现的情况下策划这场暴乱的。",al={"为什么要收集发光的骸骨","微弱发光骸骨的用途","复生魔法骸骨"}},{q="影谷的“玷污者”是谁？",a="“玷污者”是一个活跃在影谷地表的敌对势力。尽管他们对该地区构成了现实威胁，但希尔达认为城镇下方隐藏的天灾巢穴才是更加危险的敌人。",al={"谁是玷污者","影谷的玷污者"}}},fp="18,203,17.307.0,20.376.1,27.213.0,39.229.0,28.136.0,37.139.0,42.155.0,36.137.0"}
P.entries["quest:99153"] = {n="The One That Got Away",s="The One That Got Away 是一个由 Ephram Barbaro 发布的任务，旨在追踪一名从纳克萨玛斯残骸附近的冲突中逃脱的邪教徒。这名逃犯带着一块活跃的聚焦水晶碎片逃进了影谷下方，该水晶碎片可能会强化亡灵或使其复活。",h="The One That Got Away 是一个由 Ephram Barbaro...",kw={"水晶碎片","邪教徒","埃弗拉姆·巴巴罗","聚焦水晶","纳克萨玛斯","影谷","逃掉的那条鱼"},ang={["class:Paladin"]="发誓要清除死灵威胁的圣骑士会意识到任由天灾军团聚焦水晶保持活跃的危险性，特别是那些能够复活或增强地下亡灵的碎片。",["class:Priest"]="熟悉对抗黑暗魔法的牧师们明白，如果不及时回收和净化，亵渎的圣物可能会腐蚀周围的区域。"},sec={{t="影中的逃犯",b="在纳克萨玛斯战役的残骸周围与邪教徒发生冲突后，消息很快在队伍中传开了。Ephram Barbaro 在得知一名落单的邪教徒带着一块活跃的天灾军团聚焦水晶碎片潜逃出包围圈后，开始寻找有能力的冒险者。"},{t="影谷之下的威胁",b="情报显示这名逃跑的邪教徒逃进了影谷下方的地下通道。这块碎片仍然蕴含着黑暗的死灵能量，据推测它要么正在复活亡灵，要么在增强潜伏在地下深处的敌对势力。Barbaro 指派冒险者去追踪并收回这块隐藏的水晶，以免其力量引发更大的灾难。"}},faq={{q="谁发布了任务 漏网之鱼？",a="该任务由 伊弗拉姆·巴巴罗 发布，他在听闻你之前处理纳克萨玛斯战役残骸附近邪教徒的事迹后联系了你。",al={"谁发布了 漏网之鱼","谁开启了这个任务","漏网之鱼 任务发布者"}},{q="什么是聚焦水晶碎片？",a="这是由一名逃脱的邪教徒带走的天灾军团聚焦水晶的残留碎片。伊弗拉姆·巴巴罗 指出它仍然具有力量，并且正在影谷下方复活亡灵或增强现有亡灵的力量。",al={"什么是水晶碎片","水晶有什么用","为什么水晶很危险"}},{q="水晶碎片在哪里？",a="根据 伊弗拉姆·巴巴罗 的情报，那名逃亡的邪教徒带着圣物逃到了影谷下方，并将其藏在了地下的某个地方，其力量正不断从中渗出。",al={"水晶藏在哪里","影谷水晶位置","哪里寻找水晶碎片"}},{q="谁是“漏网之鱼”（漏网之鱼）？",a="这个称号指的是一名在纳克萨玛斯战役残骸的冲突后成功溜走的邪教徒，他们带走了一块活跃的聚焦水晶碎片。",al={"谁带着水晶逃跑了","持有水晶的邪教徒","漏网之鱼 含义"}},{q="当你把水晶交给 伊弗拉姆·巴巴罗 时会发生什么？",a="在归还回收的水晶碎片后，伊弗拉姆·巴巴罗 会称赞你的速度，并表示是时候进行处理这一情况时他最喜欢的部分了。",al={"归还水晶后发生什么","交付 漏网之鱼","埃弗拉姆·巴巴罗 最喜欢的部分"}},{q="伊弗拉姆·巴巴罗 是如何认识你的？",a="伊弗拉姆 提到消息在队伍中传得很快，特别提到了之前在纳克萨玛斯战役残骸周围对付邪教徒的工作。",al={"纳克萨玛斯战役残骸邪教徒","埃弗拉姆 是怎么认识你的","漏网之鱼 前置条件"}}},fp="21,192,25.263.0,29.262.0,42.123.0,38.192.0,38.108.0,31.132.0,59.133.0,39.144.0"}
P.entries["quest:99156"] = {n="巡查后方",s="巡查后方是亡灵卫兵林奈在提瑞斯法林地发布的一项关键防御任务。巡逻队员的任务不仅仅是击退漫无目的游荡的食尸鬼，还要搜寻并消灭撕裂者。这只缝合怪一直在毒蛛峡谷附近徘徊，它本不该越过亡灵壁垒。",h="巡查后方是亡灵卫兵林奈在提瑞斯法林地发布的一项关键防御任务。巡逻队员的任务不仅仅是击退漫无目的游荡的食尸鬼，还要搜寻并消灭撕裂者。这只缝合怪一直在毒蛛峡谷附近徘徊，它本不该越过亡灵壁垒。",kw={"缝合怪","亡灵壁垒","亡灵卫兵林奈","巡查后方","撕裂者","提瑞斯法林地","毒蛛峡谷"},ang={["faction:Horde"]="确保提瑞斯法东部边境的安全，可以保证供给亡灵壁垒和幽暗城的补给线不会受到流浪恐怖生物的威胁。",["race:Undead"]="被遗忘者无法承受两线作战的代价；任何在他们防线后方游荡的天灾构装体，对其王国而言都是一种生存威胁。"},sec={{t="边境的缺口",b="亡灵壁垒是提瑞斯法林地与西瘟疫之地恐怖势力之间唯一的坚固屏障。被遗忘者军队的战略完全建立在严格的单线战争基础上。如果这些毫无理智的亡灵溜到了防线后方，供给前线的补给线可能会瞬间被切断。虽然偶尔会有流浪的幽灵或食尸鬼绕过路障，但有报告称一只缝合怪正在林地中游荡，这标志着防御工作的严重失败。"},{t="撕裂者的威胁",b="那只名为撕裂者的游荡怪物被发现正笨重地在毒蛛峡谷附近移动，位于亡灵壁垒的前沿堡垒后方。缝合怪是巨大的杀戮机器，由尸体和黑暗死灵法术缝合而成。它们不可能在毫无察觉的情况下穿过严密防守的关隘，这让亡灵卫兵林奈对于这个生物如何穿过防御圈感到非常不安。林奈要求取得撕裂者的心脏，以此作为其被彻底消灭的终极证明。"}},faq={{q="谁提供了巡查后方这个任务？",a="巡逻指令由亡灵卫兵林奈发布，她是提瑞斯法林地的一名被遗忘者亡灵卫兵，直接向执行官塞加德汇报。",al={"谁发布 巡查后方","巡查后方 任务发布者","谁发布了这个任务"}},{q="撕裂者是什么？",a="撕裂者是一只流窜的缝合怪，被发现在毒蛛峡谷附近的东部林地游荡，位于前沿防线后方。",al={"谁是撕裂者","撕裂者是什么","撕裂者背景"}},{q="为什么缝合怪出现在毒蛛峡谷附近如此令人担忧？",a="缝合怪是巨大的构装体，制造它们需要黑暗死灵法术和繁重的劳作。在不知不觉中穿过戒备森严的亡灵壁垒理应是不可能的，这意味着在被遗忘者的防线后方存在一个令人震惊的缺口，或是一条未被发现的通道。",al={"为什么撕裂者是个大麻烦","为什么缝合怪在这里很危险","亡灵壁垒缺口"}},{q="这头野兽通常在哪里出没？",a="目击报告显示，撕裂者一直在提瑞斯法林地东部的树林和空地中游荡，就在毒蛛峡谷附近。",al={"撕裂者在哪里","撕裂者位置","去哪里找缝合怪"}},{q="完成巡逻需要什么证明？",a="亡灵卫兵林奈需要撕裂者的心脏来验证这只巨大的怪物已被永久消灭。",al={"我该给林奈带什么","任务提交物品","撕裂者死亡证明"}},{q="谁负责监管亡灵壁垒的防御？",a="任务中没有提到亡灵壁垒的指挥官。亡灵卫兵林奈听命于她在布瑞尔的上级执行官塞加德，后者会接收她因成功抵御天灾军团而获得的嘉奖。",al={"谁负责亡灵壁垒","林奈的上级","执行官塞加德"}}},fp="17,195,24.374.0,21.336.1,39.116.0,16.113.0,53.190.0,33.98.0,44.109.0,40.165.0"}
P.entries["quest:99158"] = {n="Dawn in the Mountains",s="Dawn in the Mountains是一个任务，要求将一箱圣烛运送给雾松避难所的加文神父。作为银色黎明的一名温和的牧师，加文维护着这个山中避难所，旨在治愈和慰藉疲惫的旅人，而非通过武力进行战争。",h="Dawn in the Mountains是一个任务，要求将一箱圣烛运送给雾松避难所的加文神父。作为银色黎明的一名温和的牧师，加文维护着这个山中避难所，旨在治愈和慰藉疲惫的旅人，而非通过武力进行战争。",kw={"银色黎明","山间黎明","加文神父","圣烛","雾松避难所","牧师","避难所"},ang={["class:Priest"]="加文神父体现了牧师更温和、更具修复力的道路，他选择关怀旅人和包扎伤口，而不是在银色黎明的前线挥舞武器。",["faction:Alliance"]="向雾松避难所这样的银色黎明庇护所提供物资，有助于在危险且充满争议的山地地形中开展中立的人道主义工作。",["faction:Horde"]="银色黎明接受援助并提供避难所，不论其立场如何，这使得加文神父的这类前哨站成为荒野中罕见的安全港湾。"},sec={{t="群峰中的庇护所",b="尽管许多银色黎明的成员拿起武器去清除艾泽拉斯的邪恶恐怖，但有些人选择了圣光更温和的召唤。加文神父是一位居住在崎岖山野中的牧师，他远离了刀剑，全心全意地致力于治愈伤痛和照料疲惫之人。他利用一处废弃的建筑，将其改造成了雾松避难所，为面对高海拔山口危险的旅人们提供了一个安全的驻足点。"},{t="为了圣光的蜡烛",b="在山中维护一个与世隔绝的避难所需要持续的维护和务实的奉献。为了维持他的神职工作并保持灯火和祭坛常亮，加文神父依赖远方盟友的慈善。一箱圣烛的运抵确保了这座避难所能在无情的荒野中继续作为光明、温暖和希望的灯塔。"}},faq={{q="谁是加文神父？",a="加文神父是银色黎明的一名牧师，驻扎在群山之中。与许多圣职人员拿起武器对抗邪恶不同，加文主要致力于治愈伤痛、慰藉旅人，并在雾松避难所提供庇护。",al={"谁是加文神父","加文神父的背景故事","雾松避难所的牧师是谁"}},{q="什么是雾松避难所？",a="雾松避难所是由加文神父建立的供山中旅人休憩的站点。他翻新了荒野中的一栋旧建筑，创造了一个宁静的庇护所，流浪者可以在此恢复体力、休息并接受治疗。",al={"什么是雾松避难所","雾松避难所在哪里","雾松避难所的背景故事"}},{q="什么是银色黎明？",a="银色黎明是一个致力于在艾泽拉斯全境搜寻并摧毁邪恶与非自然威胁的圣职组织，同时也为那些在困苦之地的挣扎求生者提供援助与慰藉。",al={"什么是银色黎明","银色黎明的宗旨","谁是银色黎明"}},{q="为什么加文神父需要一箱圣烛？",a="这箱圣烛旨在补充加文神父在雾松避难所的物资。在圣职事奉和偏远的避难所中，这些祝圣过的蜡烛对于宗教仪式、祈祷以及为疲惫的旅人照亮避难所至关重要。",al={"为什么要蜡烛","圣烛的用途","运送一箱圣烛"}},{q="加文神父会像其他银色黎明成员一样拿起武器吗？",a="加文神父更倾向于治愈和庇护旅人，而不是拿起武器。尽管银色黎明以对抗黑暗的武装十字军闻名，但加文通过同情心、好客和精神关怀来服务该组织。",al={"加文神父会战斗吗","加文神父是战士吗"}},{q="任务群山中的黎明的目的是什么？",a="该任务要求前往山区的旅人将一箱圣烛直接运送给雾松避难所的加文神父，以支持他那简朴的山中庇护所。",al={"谁发布了这个任务","山中黎明通向哪里"}}},fp="21,151,24.340.0,21.297.0,20.196.0,26.174.0,24.164.0,54.149.0,62.183.0,55.133.0"}
P.entries["quest:99159"] = {n="Finding Warmth",s="Finding Warmth是一项朴素的差事，核心是为温暖的炉火添柴。由于主人忙于其他事务，旅人受托收集木柴，以便让寻求温暖的灵魂能得到慰藉。完成任务可以维持炉火不灭，并开启后续的差事。",h="Finding Warmth是一项朴素的差事，核心是为温暖的炉火添柴。由于主人忙于其他事务，旅人受托收集木柴，以便让寻求温暖的灵魂能得到慰藉。完成任务可以维持炉火不灭，并开启后续的差事。",kw={"寻找温暖","木柴","炉火","圣光","温暖","木材"},sec={{t="温暖的炉火",b="Finding Warmth是一项为了维持温暖炉火而进行的简单琐事。任务发布者随时保持炉火通明，以温暖任何路过的灵魂，但日益繁重的责任使他们无暇亲自收集燃料。通过代为收集木柴，旅人们确保了炉火能为任何寻求庇护与慰藉的人继续燃烧。"},{t="照看炉火",b="并非所有从周边收集的木料都能立即燃烧。运回后，太潮湿而无法点燃的木头会被放在一边晾干，而干燥的木材则会立即投入火中。主人对这及时的帮助感到满意，并迅速转向其他仍需关注的紧迫事务。"}},faq={{q="任务寻找温暖的内容是什么？",a="寻找温暖是一项当地任务，要求冒险者收集木柴以维持温暖的炉火。任务发布者通常会亲自照看火堆，但由于忙于其他紧迫的杂务，不得不寻求外界的帮助。",al={"寻找温暖任务","什么是寻找温暖","寻找温暖木柴"}},{q="为什么需要这些木柴？",a="这些木柴用于维持一个开放的炉火，为路过的旅人和当地居民提供温暖与慰藉。收集木柴原本是一项普通的琐事，但由于主人忙于其他职责而耽搁了。",al={"为什么需要木材","木柴 寻找温暖","炉火 木柴"}},{q="带来的湿木柴会怎么样？",a="收集到的一些原木在送达时可能太潮湿或太湿而无法立即燃烧。任务发布者会将潮湿的部分放在一边晾干，同时使用干燥的木材立即添火。",al={"寻找温暖 湿木头","潮湿的木柴"}},{q="是什么样的人发布这个任务的？",a="虽然主人的具体身份未作详细说明，但他们那句“愿圣光指引你的任务”表明，这是一个根植于对圣光的信仰或敬畏的人，他们提供开放的炉火来温暖每一个灵魂。",al={"谁发布寻找温暖","寻找温暖 愿圣光指引你"}},{q="完成寻找温暖后还有更多任务吗？",a="是的。在交付木柴后，主人提到手头还有其他任务，如果旅人愿意进一步帮忙，他们需要一双能干的手。",al={"寻找温暖后的更多任务","寻找温暖后续"}},{q="谁可以在这个炉火旁休息？",a="主人保持炉火燃烧，是为了给任何路过、可能需要从寒冷或疲惫的旅途中得到片刻休憩的人提供庇护、慰藉和温暖。",al={"炉火 开放 灵魂","开放的炉火 寻找温暖"}}},fp="14,136,18.178.0,16.192.0,39.118.0,27.127.0,40.73.0,37.172.0,53.90.0,30.86.0"}
P.entries["quest:99160"] = {n="Rime's Wrath",s="Rime's Wrath 是一个专注于平息小型冰元素危险爆发的任务。由于不知如何和平地安抚这些充满攻击性的霜冻之灵，消灭它们成为了保障地区安全的必要手段。",h="Rime's Wrath 是一个专注于平息小型冰元素危险爆发的任务。由于不知如何和平地安抚这些充满攻击性的霜冻之灵，消灭它们成为了保障地区安全的必要手段。",kw={"元素","冰霜","冰元素","小型冰元素","安抚","寒霜之怒"},ang={["class:Mage"]="冰霜法师研究冰霜魔法的原始塑形与召唤，这使得狂野的小型冰元素成为了一种引人入胜却又难以驾驭的元素力量展示。",["class:Shaman"]="萨满祭司致力于理解并与元素之灵沟通，但这些敌对的冰霜实体显然超出了和平安抚的范畴，只能通过武力予以平息。"},sec={{t="苦涩的显现",b="Rime's Wrath 涉及处理局部小型冰元素涌动的问题。这些由刺骨严寒构成的元素之灵已成为该地区切实存在的危险，必须迅速采取干预措施，以免它们的寒气进一步蔓延或伤害过往行人。这并非有组织的突袭，而是一种针对狂暴、敌对元素显现的遏制手段。"},{t="无法安抚",b="虽然理想的结果是安抚那些狂躁的霜冻之灵，但安抚它们所需的知识遥不可及。由于没有实际可行的和平手段，且这些元素之灵变得日益危险，剩下的唯一选择便是消灭它们，以保护周边地区。"}},faq={{q="什么是 霜寒之怒？",a="霜寒之怒 是一个要求消灭构成直接威胁的小型冰元素的任务。由于不知晓或无法使用和平手段来平息这些狂躁的元素之灵，直接动武成为了维持安全的唯一选择。",al={"什么是 霜寒之怒","霜寒之怒 任务","霜寒之怒 概述"}},{q="为什么必须消灭小型冰元素？",a="这些小型冰元素变得过于不稳定且危险，不能放任不管。虽然和平安抚是首选，但缺乏让它们平静下来的知识，因此消灭它们成为了必要的手段。",al={"为什么要消灭冰元素","为什么要与它们战斗","不能安抚这些元素吗"}},{q="是谁要求消灭这些元素的？",a="该任务由一位关心控制局势的人发起，他本希望和平地安抚这些元素之灵。由于缺乏安抚它们所需的奥术或精神知识，他只能求助于冒险者来消除威胁。",al={"谁发布了 霜寒之怒","谁想要消灭这些元素","任务发布者是谁"}},{q="这些元素可以和平解决吗？",a="任务发布者指出，安抚它们超出了他的认知范围。元素之灵有时可以被平衡或安抚，但若没有相关的专业知识，它们的攻击性使得除了战斗之外别无他法。",al={"冰元素可以被安抚吗","安抚冰元素","为什么不平息元素"}},{q="小型冰元素是什么样的生物？",a="小型冰元素是不稳定的冰霜元素显现。尽管被归类为小型元素之灵，但如果任其自由游荡，它们周围的严寒和攻击性仍会对旅行者和当地居民造成危险。",al={"什么是小型冰元素","冰元素的危险性","小型冰元素有多强"}},{q="处理这些元素的结果是什么？",a="在击败十个小型冰元素后，眼前的危险便被平息了。任务发布者感叹暴力是必要的手段，因为他也意识到放任不管风险实在太大。",al={"霜寒之怒 之后会发生什么","霜寒之怒 结局"}}},fp="12,137,22.160.0,16.166.0,21.148.0,53.152.0,47.156.0,53.131.0,48.157.0,51.176.0"}
P.entries["quest:99161"] = {n="Rime's Wrath",s="在一场山崩过后，一个异常巨大的元素生物Avala出现了，并开始引发诡异的天气突变和二次山崩。一名观察者委托冒险者去猎杀该元素生物并获取它的核心，以确保该区域的安全。击败这个生物可以恢复山坡的稳定，并保护旅行者免受致命的寒冬之灾。",h="在一场山崩过后，一个异常巨大的元素生物Avala出现了，并开始引发诡异的天气突变和二次山崩。一名观察者委托冒险者去猎杀该元素生物并获取它的核心，以确保该区域的安全。击败这个生物可以恢复山坡的稳定，并保护旅行者免受致命的寒...",kw={"阿瓦拉","阿瓦拉核心","元素生物","元素核心","寒霜之怒","山崩","天气","冬季"},ang={["class:Paladin"]="圣骑士肩负着保护旅行者和平民免受突发灾难的职责。任务给予者在任务完成后祈求圣光的祝福，以感谢冒险者避免了不必要的死亡。",["class:Shaman"]="萨满祭司认识到像Avala这样不受约束的元素生物所构成的危险，其动荡的存在扭曲了当地的天气并撼动着岩石。平息这些躁动的生物对于恢复元素之间的和谐至关重要。"},sec={{t="山崩的余波",b="这些骚乱始于一次突如其来的山崩，山崩动摇了山口，为元素生物的活动打开了通道。在浮现出的众多生物中，有一个特殊的元素生物脱颖而出，以其巨大的体型和原始的力量凌驾于同类之上。警觉的任务给予者为它起了个非正式的绰号“Avala”。这个强大的实体不仅仅是一个令人望而生畏的存在，它还直接加剧了局部的天气动荡，并使周围的悬崖变得不稳定。它的存在对任何试图通过该地区的人来说都是一种直接的威胁，因为不稳定的地面和突如其来的严寒使正常的通行变得致命。"},{t="平息Avala",b="由于认识到Avala对地形的影响所带来的日益严重的危险，有人发出了号召，要求在更多的塌方造成伤亡之前消灭这头野兽。击杀该生物需要同时面对它的元素狂暴和它所制造的恶劣环境，最终还要取回它的核心作为其死亡的明确证据。随着Avala被击败，其生命之心被收回，剧烈的天气变化随之平息，这使周围的山口恢复了一定的安全，并保护未来的旅行者免受不必要的灾难。"}},faq={{q="什么是霜寒之怒？",a="霜寒之怒是一个任务，要求冒险者消灭阿瓦拉。这是一个在突然的山崩后显现的、巨大且危险的元素生物。通过猎杀该元素生物并回收其核心，冒险者终结了威胁着山口旅行者的反常天气干扰和反复发生的山崩。",al={"霜寒之怒","什么是霜寒之怒","霜寒之怒任务"}},{q="阿瓦拉是谁，或者是什么？",a="阿瓦拉是一个在重大山崩后浮现的特别巨大的元素生物。阿瓦拉比它的元素同类体型更大，它主动在区域内引发突然的天气变化、严寒以及危险的二次地震。“阿瓦拉”这个名字是监视山口的观察者给它起的。",al={"什么是阿瓦拉","阿瓦拉是谁","阿瓦拉元素生物"}},{q="为什么要摧毁阿瓦拉？",a="阿瓦拉持续存在导致不可预知的天气紊乱和小型山崩，使周围的山坡变得不稳定。如果不加制止，这个元素生物对冬季气候和地形的超自然影响将有引发进一步塌方的风险，并导致穿越山口的旅行者发生可避免的死亡。",al={"为什么要击杀阿瓦拉","击杀阿瓦拉的原因","为什么要摧毁阿瓦拉"}},{q="完成霜寒之怒需要什么证据？",a="冒险者必须在战斗中击败该生物后取回阿瓦拉的核心。将此元素核心交给任务给予者，证实该威胁已被彻底消除，区域气候可以恢复正常。",al={"阿瓦拉的证明","掉落什么物品","阿瓦拉核心证明"}},{q="阿瓦拉最初是如何出现的？",a="阿瓦拉是在一场扰乱该地区的最初山崩后出现的。它在塌方后的余波中与其他元素生物一同出现，由于其体型和元素力量，很快确立了自己是其中最突出、最危险的生物。",al={"阿瓦拉从何而来","阿瓦拉起源","阿瓦拉如何生成"}},{q="谁提供了霜寒之怒这个任务？",a="该任务由驻扎在危险山口附近的一名当地观察者提供，他密切监视着山崩和元素生物的出现。在任务完成后，这位观察者会祈求圣光的祝福，他试图通过招募有能力的勇士来消灭阿瓦拉，以防止不必要的死亡。",al={"谁给予霜寒之怒任务","霜寒之怒任务给予者"}},{q="阿瓦拉被击败后会发生什么？",a="一旦阿瓦拉被杀且其核心被带回，由该生物的存在所引发的剧烈天气变化和局部震动便会减弱。任务给予者会赐予圣光的祝福和奖励，并指出该地区对未来的旅行者来说已经变得更加安全。",al={"阿瓦拉死后发生什么","霜寒之怒完成","霜寒之怒之后"}}},fp="12,177,25.310.0,14.327.0,21.178.0,21.216.0,36.201.0,46.132.0,27.151.0,34.265.0,37.187.0"}
P.entries["quest:99162"] = {n="Treacherous Cold",s="Treacherous Cold 是在丹莫罗险峻的高峰上，于毁灭性的冰雪崩塌后进行的一项救援工作。冒险者受命寻回阵亡铁炉堡登山者的铭文步枪，以确认他们的身份，并给予其家人慰藉。",h="Treacherous Cold 是在丹莫罗险峻的高峰上，于毁灭性的冰雪崩塌后进行的一项救援工作。冒险者受命寻回阵亡铁炉堡登山者的铭文步枪，以确认他们的身份，并给予其家人慰藉。",kw={"雪崩","丹莫罗","铁炉堡","登山者","步枪","山体滑坡","致命严寒"},ang={["class:Hunter"]="登山者在冰冻荒野中依靠他们值得信赖的步枪，将名字刻在木质枪托上，这样他们的身份和功绩便永远不会被遗忘。",["faction:Alliance"]="回收阵亡登山者的装备，能确保铁炉堡给予那些为了守护高地而牺牲挚亲的家庭一份慰藉。",["race:Dwarf"]="丹莫罗的山峰是矮人的家园，但即便是老练的登山者也可能在高地山道上丧命于突发的雪崩和充满敌意的元素手中。"},sec={{t="群峰之险",b="丹莫罗崎岖的雪崖对旅行者和士兵来说始终是一种危险。即使是经验丰富的铁炉堡登山者也可能在突如其来的雪崩和坠落的冰层中措手不及，而新兵更是在毫无预警的寒冬袭击中丧命。"},{t="严酷的搜救",b="当山体滑坡掩埋了巡逻队，搜寻险峻地形便成了一场严酷的与时间赛跑。该地区加剧的元素活动使得彻底的救援行动困难重重，迫使侦察兵招募勇敢的漫步者，在雪堆中寻找失踪的登山者，并在大雪将其永远掩盖之前取回他们的铭文步枪。"},{t="刻字的枪托",b="每一位铁炉堡登山者都会将自己的名字刻在步枪的枪托上，作为在最严酷环境下的永久身份标识。通过从雪堆中找回这些武器，搜寻者能确保阵亡者得到确认，且他们受人尊崇的事迹能被铁炉堡的家人知晓。"}},faq={{q="什么是 致命的严寒？",a="致命的严寒 是一项任务，旨在搜寻被突如其来的雪崩困住的登山者，并回收他们的制式步枪。",al={"什么是 险恶的寒冷","险恶的寒冷 任务"}},{q="为什么要收集登山者的步枪？",a="登山者会将名字直接刻在步枪的枪托上。在极寒的雪堆中，遗体可能已被掩埋或无法找回，取回他们的武器能让铁炉堡确认阵亡者身份并通知其家人。",al={"为什么收集步枪","登山者步枪","为什么要拿走他们的枪"}},{q="谁在雪中遇难了？",a="在丹莫罗巡逻的新手登山者特别容易受到突发雪崩、坠冰和高海拔地区极端天气的影响。",al={"受害者是谁","谁在丹莫罗失踪了"}},{q="为什么之前没有进行搜寻？",a="虽然任务发布者通常会在雪崩后进行救援和搜寻工作，但丹莫罗最近的元素动荡使得深入山道执行任务变得过于危险，无法独自应对。",al={"为什么任务发布者不能去寻找","为什么需要冒险者"}},{q="步枪被回收后会怎样？",a="回收的步枪会被收集并送回铁炉堡，当地官方会确保这些个人武器归还给阵亡登山者的家属。",al={"步枪会被送去哪里","回收的步枪有什么用途"}},{q="丹莫罗的高海拔山道为何如此危险？",a="丹莫罗的高海拔地区充斥着严寒、致盲的雪崩和不稳定的悬崖。再加上动荡的元素活动，即使是训练有素的矮人巡逻队也可能迅速倒在恶劣的环境下。",al={"丹莫罗有多危险","丹莫罗的危险因素"}}},fp="16,158,19.219.0,13.331.0,16.192.0,25.117.0,43.192.0,30.140.0,45.197.0,42.136.0,54.179.0"}
